package com.flipsmart;

import org.junit.Test;
import java.awt.Color;
import java.awt.image.BufferedImage;
import static org.junit.Assert.assertEquals;

public class SpriteRecolorTest
{
    @Test
    public void fullStrengthMidGrayTintedGreenKeepsLuminanceOnGreenChannelOnly()
    {
        BufferedImage src = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
        src.setRGB(0, 0, new Color(128, 128, 128, 255).getRGB());

        BufferedImage out = SpriteRecolor.tint(src, new Color(0, 255, 0), 1.0);

        assertEquals(new Color(0, 128, 0, 255).getRGB(), out.getRGB(0, 0));
    }

    @Test
    public void halfStrengthBlendsBackTowardOriginal()
    {
        BufferedImage src = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
        src.setRGB(0, 0, new Color(128, 128, 128, 255).getRGB());

        // Full tint = (0,128,0); half strength halves the delta from the original 128 → (64,128,64).
        BufferedImage out = SpriteRecolor.tint(src, new Color(0, 255, 0), 0.5);

        assertEquals(new Color(64, 128, 64, 255).getRGB(), out.getRGB(0, 0));
    }

    @Test
    public void transparentPixelStaysTransparent()
    {
        BufferedImage src = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
        src.setRGB(0, 0, 0x00000000);

        BufferedImage out = SpriteRecolor.tint(src, new Color(255, 0, 0), 1.0);

        assertEquals(0, (out.getRGB(0, 0) >>> 24));
    }

    @Test
    public void preservesAlpha()
    {
        BufferedImage src = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
        src.setRGB(0, 0, new Color(200, 200, 200, 120).getRGB());

        BufferedImage out = SpriteRecolor.tint(src, new Color(255, 255, 255), 1.0);

        assertEquals(120, (out.getRGB(0, 0) >>> 24));
    }
}

package com.flipsmart;

import com.flipsmart.domain.offer.OfferRecord;
import com.flipsmart.domain.offer.OfferSignal;
import com.flipsmart.domain.offer.OfferState;
import com.flipsmart.trading.OfferReconciler;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Test;

import java.util.Collections;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class OfferReconcilerTest
{
    private static final long NOW = 5_000L;

    private static OfferSignal live(int slot, int itemId, int sold, int total)
    {
        return new OfferSignal(slot, GrandExchangeOfferState.BUYING, itemId, "i" + itemId, total, 100, sold, (long) sold * 100);
    }

    @Test
    public void liveSlotMatchingPersisted_reattachesSameOfferId()
    {
        OfferRecord persisted = OfferRecord.newOffer(7L, 0, 1234, "i1234", true, 10, 100, NOW - 1000);
        OfferReconciler.Plan plan = OfferReconciler.reconcile(
            Collections.singletonList(persisted),
            Collections.singletonList(live(0, 1234, 3, 10)), NOW);

        assertEquals(1, plan.reattached.size());
        assertEquals(7L, plan.reattached.get(0).getOfferId());
        assertTrue(plan.minted.isEmpty());
    }

    @Test
    public void liveSlotWithNoMatch_mintsWithBaselineFromLiveQuantity()
    {
        OfferReconciler.Plan plan = OfferReconciler.reconcile(
            Collections.emptyList(),
            Collections.singletonList(live(2, 5678, 4, 10)), NOW);

        assertEquals(1, plan.minted.size());
        assertEquals("baseline seeded so a total fill isn't logged as new",
            4, plan.minted.get(0).quantitySold);
        assertTrue(plan.reattached.isEmpty());
    }

    @Test
    public void persistedRecordOnEmptySlot_isMarkedForOfflineReconcile()
    {
        OfferRecord persisted = OfferRecord.newOffer(9L, 1, 4321, "i4321", true, 10, 100, NOW - 2000);
        OfferReconciler.Plan plan = OfferReconciler.reconcile(
            Collections.singletonList(persisted),
            Collections.emptyList(), NOW);

        assertEquals(1, plan.offlineCollected.size());
        assertEquals(9L, plan.offlineCollected.get(0).getOfferId());
    }

    @Test
    public void terminalPersistedRecord_isNotOfflineCollected()
    {
        // A COLLECTED record is already-reconciled history from a prior session;
        // it must not be re-flagged as a fresh offline fill on every login.
        OfferRecord collected = OfferRecord.newOffer(12L, 4, 555, "i555", true, 10, 100, NOW - 3000)
            .withFill(10, 1000, OfferState.FILLED, NOW - 2500)
            .withState(OfferState.COLLECTED, NOW - 2000);

        OfferReconciler.Plan plan = OfferReconciler.reconcile(
            Collections.singletonList(collected),
            Collections.emptyList(), NOW);

        assertTrue("terminal history must not drive an offline-fill prompt", plan.offlineCollected.isEmpty());
    }

    @Test
    public void mixedHistory_onlyActiveNowGoneRecordIsOfflineCollected()
    {
        OfferRecord active = OfferRecord.newOffer(20L, 1, 100, "i100", true, 10, 100, NOW - 2000);
        OfferRecord collected = OfferRecord.newOffer(21L, 2, 200, "i200", false, 5, 50, NOW - 3000)
            .withFill(5, 250, OfferState.FILLED, NOW - 2800)
            .withState(OfferState.COLLECTED, NOW - 2700);
        OfferRecord cancelledEmpty = OfferRecord.newOffer(22L, 3, 300, "i300", true, 8, 80, NOW - 3000)
            .withState(OfferState.CANCELLED_EMPTY, NOW - 2600);

        OfferReconciler.Plan plan = OfferReconciler.reconcile(
            java.util.Arrays.asList(active, collected, cancelledEmpty),
            Collections.emptyList(), NOW);

        assertEquals(1, plan.offlineCollected.size());
        assertEquals(20L, plan.offlineCollected.get(0).getOfferId());
    }

    @Test
    public void ageDoesNotDisqualifyAnOfflineFill()
    {
        // #1197: reconcile used to demand that a record's last activity be at or after the
        // previous sync marker. That test can never pass for a real offline fill — last-activity
        // is when the plugin last OBSERVED a change, and an offline fill is by definition a change
        // it did not observe, so the timestamp always trails a marker written on every sync.
        // Observed live: lastActivity=19:45:19 against a marker of 19:45:20, and the prompt fired
        // zero times across nine logins.
        OfferRecord ancient = OfferRecord.newOffer(30L, 1, 400, "i400", false, 3, 100, NOW - 999_999)
            .withActivityAtMillis(NOW - 999_999);

        OfferReconciler.Plan plan = OfferReconciler.reconcile(
            Collections.singletonList(ancient), Collections.emptyList(), NOW);

        assertEquals("an unmatched non-terminal record is an offline fill regardless of age",
            1, plan.offlineCollected.size());
        assertEquals(30L, plan.offlineCollected.get(0).getOfferId());
    }

    @Test
    public void terminalRecordIsNeverOfferedAgain()
    {
        // What replaces the freshness cutoff: offering a record terminalises it, and the
        // reconciler skips terminal records outright. That is what stops a re-prompt each login.
        OfferRecord collected = OfferRecord.newOffer(33L, 1, 700, "i700", false, 3, 100, NOW - 1_000)
            .withState(OfferState.COLLECTED, NOW - 500);

        OfferReconciler.Plan plan = OfferReconciler.reconcile(
            Collections.singletonList(collected), Collections.emptyList(), NOW);

        assertTrue("already-offered record must not be offered again", plan.offlineCollected.isEmpty());
    }

    @Test
    public void liveSlotMatchesDespiteTotalQuantityAndPriceDrift_reattachesNotMints()
    {
        // #1089 D1: the buy order's total_quantity drifted (7500 -> 11584) and its
        // price nudged between persistence and the live read. The old exact-match
        // on total+price then failed to reattach, so a fresh baseline-0 record
        // re-posted the whole cumulative on top of fills already recorded — a ~40%
        // over-count seen across 1,061 prod users. Identity is the live slot's
        // (slot, item, direction), not its mutable total/price.
        OfferRecord persisted = OfferRecord.newOffer(7L, 0, 536, "Dragon bones", true, 7500, 3284, NOW - 1000)
            .withFill(3027, 3027L * 3284, OfferState.PARTIAL_FILL, NOW - 500);
        OfferSignal drifted = new OfferSignal(
            0, GrandExchangeOfferState.BUYING, 536, "Dragon bones", 11584, 3290, 4279, 4279L * 3284);

        OfferReconciler.Plan plan = OfferReconciler.reconcile(
            Collections.singletonList(persisted), Collections.singletonList(drifted), NOW);

        assertEquals("must reattach despite total/price drift", 1, plan.reattached.size());
        assertEquals(7L, plan.reattached.get(0).getOfferId());
        assertEquals("recorded baseline preserved so the next fill logs only the delta",
            3027, plan.reattached.get(0).getFilledQuantity());
        assertTrue("no fresh baseline-0 record minted", plan.minted.isEmpty());
    }

    @Test
    public void terminalRecordSameSlotAndItem_isNotReattached_mintsFresh()
    {
        // Loosening the match must not grab a COLLECTED leftover occupying the same
        // slot+item: that is a reused slot holding a genuinely new offer, so it must
        // mint fresh rather than resurrect finished history.
        OfferRecord collected = OfferRecord.newOffer(9L, 0, 536, "Dragon bones", true, 7500, 3284, NOW - 3000)
            .withFill(7500, 7500L * 3284, OfferState.FILLED, NOW - 2500)
            .withState(OfferState.COLLECTED, NOW - 2000);

        OfferReconciler.Plan plan = OfferReconciler.reconcile(
            Collections.singletonList(collected), Collections.singletonList(live(0, 536, 100, 7500)), NOW);

        assertTrue("terminal record must not reattach to a live slot", plan.reattached.isEmpty());
        assertEquals(1, plan.minted.size());
    }
}

package com.flipsmart;

import com.flipsmart.api.dto.Dtos.FavoriteItem;
import com.flipsmart.api.dto.Dtos.FavoritesResponse;
import com.flipsmart.api.dto.Dtos.PluginSyncResponse;
import com.google.gson.Gson;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class FavoritesDtoParsingTest
{
	private final Gson gson = new Gson();

	@Test
	public void parsesFavoritesResponse()
	{
		String json = "{\"items\":[{\"item_id\":4151,\"item_name\":\"Abyssal whip\",\"icon_url\":\"http://x/w.png\","
			+ "\"buy_price\":1900000,\"sell_price\":2000000,\"buy_limit\":70,\"margin\":80000,\"profit\":5600000,"
			+ "\"volume\":5000000,\"risk_score\":20,\"risk_rating\":\"Very Low\"}],\"count\":1}";
		FavoritesResponse r = gson.fromJson(json, FavoritesResponse.class);
		assertEquals(1, r.getCount());
		FavoriteItem item = r.getItems().get(0);
		assertEquals(4151, item.getItemId());
		assertEquals("Abyssal whip", item.getItemName());
		assertEquals(80000, item.getMargin());
		assertEquals(5600000, item.getProfit());
		assertEquals(5000000, item.getVolume());
		assertEquals("Very Low", item.getRiskRating());
		assertEquals(2000000, item.getSellPrice().intValue());
		assertEquals(1900000, item.getBuyPrice().intValue());
		assertEquals(70, item.getBuyLimit().intValue());
	}

	@Test
	public void parsesFavoriteItemIdsFromSync()
	{
		String json = "{\"version\":1,\"favorite_item_ids\":[4151,561],\"flip_finder\":null}";
		PluginSyncResponse sync = gson.fromJson(json, PluginSyncResponse.class);
		assertNotNull(sync.getFavoriteItemIds());
		assertEquals(2, sync.getFavoriteItemIds().size());
		assertTrue(sync.getFavoriteItemIds().contains(4151));
		assertTrue(sync.getFavoriteItemIds().contains(561));
	}
}

package com.flipsmart;

import com.flipsmart.recommend.ActionDecision;
import com.flipsmart.recommend.ActionKind;
import com.flipsmart.recommend.ActionStep;
import net.runelite.client.Notifier;
import net.runelite.client.config.Notification;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Covers the action-alert trigger: which decisions alert, how repeats and flaps are
 * suppressed, and the message text. The empty-slot buy carries a queue-sourced itemId
 * that rotates on every Flip Finder refresh, so the alert key is deliberately coarser
 * than ActionDecision equality — {@link #rotatingBuySuggestionAlertsOnce()} pins that.
 */
public class ActionAlertNotifierTest
{
	private static final int ITEM = 4151;
	private static final int OTHER_ITEM = 561;
	private static final String ITEM_NAME = "Abyssal whip";
	private static final String OTHER_NAME = "Nature rune";

	private Notifier notifier;
	private FlipSmartConfig config;
	private long now;
	private boolean focused;
	private ActionAlertNotifier alerts;

	@Before
	public void setUp()
	{
		notifier = mock(Notifier.class);
		config = mock(FlipSmartConfig.class);
		when(config.actionAlert()).thenReturn(Notification.ON);
		now = 1_000_000L;
		focused = false;
		alerts = new ActionAlertNotifier(notifier, config, this::name, () -> focused, () -> now);
	}

	private String name(int itemId)
	{
		return itemId == ITEM ? ITEM_NAME : OTHER_NAME;
	}

	private static ActionDecision decision(ActionKind kind, ActionStep step, int itemId, int slot)
	{
		return new ActionDecision(kind, step, itemId, slot, 0L);
	}

	private static ActionDecision cancel(int itemId, int slot)
	{
		return decision(ActionKind.S6, ActionStep.CANCEL, itemId, slot);
	}

	private static ActionDecision collect(int itemId, int slot)
	{
		return decision(ActionKind.S5, ActionStep.COLLECT, itemId, slot);
	}

	private static ActionDecision placeBuy(int itemId)
	{
		return decision(ActionKind.S2, ActionStep.PLACE_BUY, itemId, -1);
	}

	/** A fresh cancel recommendation alerts, naming the item. */
	@Test
	public void newCancelDecisionAlertsOnce()
	{
		alerts.onDecision(cancel(ITEM, 3));

		verify(notifier, times(1)).notify(eq(Notification.ON), anyString());
	}

	/** The configured Notification is handed to RuneLite, which owns enable-gating. */
	@Test
	public void notifyReceivesTheConfiguredNotification()
	{
		Notification configured = Notification.OFF;
		when(config.actionAlert()).thenReturn(configured);

		alerts.onDecision(cancel(ITEM, 3));

		verify(notifier).notify(eq(configured), anyString());
	}

	/** resolveAndApply re-applies an unchanged decision on every offer event. */
	@Test
	public void repeatedDecisionIsSilent()
	{
		alerts.onDecision(cancel(ITEM, 3));
		alerts.onDecision(cancel(ITEM, 3));
		alerts.onDecision(cancel(ITEM, 3));

		verify(notifier, times(1)).notify(any(Notification.class), anyString());
	}

	/** detectedAtMillis is excluded from decision identity; it must not re-alert. */
	@Test
	public void detectedAtChangeIsSilent()
	{
		alerts.onDecision(new ActionDecision(ActionKind.S6, ActionStep.CANCEL, ITEM, 3, 1L));
		alerts.onDecision(new ActionDecision(ActionKind.S6, ActionStep.CANCEL, ITEM, 3, 99_999L));

		verify(notifier, times(1)).notify(any(Notification.class), anyString());
	}

	/** Nothing to do — stay silent. */
	@Test
	public void idleIsSilent()
	{
		alerts.onDecision(ActionDecision.IDLE);

		verify(notifier, never()).notify(any(Notification.class), anyString());
	}

	/** A null decision must not throw. */
	@Test
	public void nullDecisionIsSilent()
	{
		alerts.onDecision(null);

		verify(notifier, never()).notify(any(Notification.class), anyString());
	}

	/**
	 * THE regression this class exists for: the Flip Finder queue rotates its suggested
	 * buy every refresh, so the decision's itemId changes while the actionable fact —
	 * a slot is free — does not. Alert once, not once per rotation.
	 */
	@Test
	public void rotatingBuySuggestionAlertsOnce()
	{
		alerts.onDecision(placeBuy(ITEM));
		now += 120_000L;
		alerts.onDecision(placeBuy(OTHER_ITEM));
		now += 120_000L;
		alerts.onDecision(placeBuy(ITEM));

		verify(notifier, times(1)).notify(any(Notification.class), anyString());
	}

	/** Distinct actions on the same item are distinct alerts. */
	@Test
	public void cancelThenCollectAlertsTwice()
	{
		alerts.onDecision(cancel(ITEM, 3));
		alerts.onDecision(collect(ITEM, 3));

		verify(notifier, times(2)).notify(any(Notification.class), anyString());
	}

	/** The same action on a different slot is a different alert. */
	@Test
	public void sameActionDifferentSlotAlertsTwice()
	{
		alerts.onDecision(cancel(ITEM, 3));
		alerts.onDecision(cancel(ITEM, 5));

		verify(notifier, times(2)).notify(any(Notification.class), anyString());
	}

	/** Going idle then re-detecting the same action re-alerts once the cooldown lapses. */
	@Test
	public void actionReturningAfterIdleReAlertsOnceCooldownLapses()
	{
		alerts.onDecision(cancel(ITEM, 3));
		alerts.onDecision(ActionDecision.IDLE);
		now += ActionAlertNotifier.COOLDOWN_MS;
		alerts.onDecision(cancel(ITEM, 3));

		verify(notifier, times(2)).notify(any(Notification.class), anyString());
	}

	/** Message text per step. */
	@Test
	public void messageNamesTheItemPerStep()
	{
		assertEquals("Cancel your Abyssal whip offer", ActionAlertNotifier.message(cancel(ITEM, 3), this::name));
		assertEquals("Collect your Abyssal whip", ActionAlertNotifier.message(collect(ITEM, 3), this::name));
		assertEquals("A Grand Exchange slot is free", ActionAlertNotifier.message(placeBuy(ITEM), this::name));
		assertEquals("List Abyssal whip to sell",
			ActionAlertNotifier.message(decision(ActionKind.SELL_WAITING, ActionStep.LIST, ITEM, -1), this::name));
		assertEquals("Adjust the price of your Abyssal whip offer",
			ActionAlertNotifier.message(decision(ActionKind.S4, ActionStep.REPRICE, ITEM, 3), this::name));
	}

	/**
	 * S2 exists only while the queue has a surfaceable buy, so a refresh that briefly
	 * empties it flaps PLACE_BUY -> COLLECT -> PLACE_BUY. Those are different keys, so
	 * only the cooldown stops the third from re-alerting.
	 */
	@Test
	public void flapWithinCooldownDoesNotReAlert()
	{
		alerts.onDecision(placeBuy(ITEM));
		now += 1_000L;
		alerts.onDecision(collect(OTHER_ITEM, 2));
		now += 1_000L;
		alerts.onDecision(placeBuy(ITEM));

		verify(notifier, times(2)).notify(any(Notification.class), anyString());
	}

	/** Once the window lapses, a genuinely recurring action alerts again. */
	@Test
	public void flapAfterCooldownReAlerts()
	{
		alerts.onDecision(placeBuy(ITEM));
		now += 1_000L;
		alerts.onDecision(collect(OTHER_ITEM, 2));
		now += ActionAlertNotifier.COOLDOWN_MS;
		alerts.onDecision(placeBuy(ITEM));

		verify(notifier, times(3)).notify(any(Notification.class), anyString());
	}

	/** The window holds right up to its boundary. */
	@Test
	public void stillCoolingJustBeforeExpiry()
	{
		alerts.onDecision(placeBuy(ITEM));
		now += 1_000L;
		alerts.onDecision(collect(OTHER_ITEM, 2));
		now += ActionAlertNotifier.COOLDOWN_MS - 1_001L;
		alerts.onDecision(placeBuy(ITEM));

		verify(notifier, times(2)).notify(any(Notification.class), anyString());
	}

	/** Cooldowns are per key — one key cooling must not silence another. */
	@Test
	public void cooldownsAreIndependentPerKey()
	{
		alerts.onDecision(cancel(ITEM, 3));
		alerts.onDecision(cancel(OTHER_ITEM, 4));

		verify(notifier, times(2)).notify(any(Notification.class), anyString());
	}

	/** While the client is focused RuneLite discards the notification, so we must not send one. */
	@Test
	public void focusedClientIsSilent()
	{
		focused = true;

		alerts.onDecision(cancel(ITEM, 3));

		verify(notifier, never()).notify(any(Notification.class), anyString());
	}

	/**
	 * THE bug from live QA: an action that appears while the player is watching must not be
	 * consumed. RuneLite throws the notification away when focused, so marking it delivered
	 * strands the action — the player walks away and is never told. It must still fire once
	 * they look away.
	 */
	@Test
	public void alertSuppressedWhileFocusedStillFiresOnceUnfocused()
	{
		focused = true;
		alerts.onDecision(collect(ITEM, 6));
		alerts.onDecision(collect(ITEM, 6));
		verify(notifier, never()).notify(any(Notification.class), anyString());

		focused = false;
		alerts.onDecision(collect(ITEM, 6));

		verify(notifier, times(1)).notify(any(Notification.class), anyString());
	}

	/** Once delivered while away, the same pending action does not re-fire on later ticks. */
	@Test
	public void alertDeliveredWhileUnfocusedDoesNotRepeatOnTicks()
	{
		alerts.onDecision(collect(ITEM, 6));
		alerts.onDecision(collect(ITEM, 6));
		alerts.onDecision(collect(ITEM, 6));

		verify(notifier, times(1)).notify(any(Notification.class), anyString());
	}

	/** The alert-key table: PLACE_BUY is item-agnostic, LIST is per-item, the rest are per-offer. */
	@Test
	public void alertKeyTable()
	{
		assertNull(ActionAlertNotifier.alertKey(ActionDecision.IDLE));
		assertNull(ActionAlertNotifier.alertKey(null));
		assertEquals("PLACE_BUY", ActionAlertNotifier.alertKey(placeBuy(ITEM)));
		assertEquals("PLACE_BUY", ActionAlertNotifier.alertKey(placeBuy(OTHER_ITEM)));
		assertEquals("LIST:4151",
			ActionAlertNotifier.alertKey(decision(ActionKind.SELL_WAITING, ActionStep.LIST, ITEM, -1)));
		assertEquals("CANCEL:4151:3", ActionAlertNotifier.alertKey(cancel(ITEM, 3)));
		assertEquals("COLLECT:4151:3", ActionAlertNotifier.alertKey(collect(ITEM, 3)));
	}
}

package com.flipsmart;
import com.flipsmart.domain.offer.OfferRecord;

import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class BreakevenRelistDetectionTest
{
	@Test
	public void advancesWhenRelistAtAdvisedPriceWithinTolerance()
	{
		assertTrue(OfferRecord.shouldAdvanceToBreakevenRelist(true, 1048, 1050));
		assertTrue(OfferRecord.shouldAdvanceToBreakevenRelist(true, 1050, 1050));
	}

	@Test
	public void doesNotAdvanceWhenBreakevenNotAccepted()
	{
		assertFalse(OfferRecord.shouldAdvanceToBreakevenRelist(false, 1050, 1050));
	}

	@Test
	public void doesNotAdvanceWhenRelistPriceFarFromAdvised()
	{
		assertFalse(OfferRecord.shouldAdvanceToBreakevenRelist(true, 1200, 1050));
	}

	@Test
	public void doesNotAdvanceWithoutAdvisedPrice()
	{
		assertFalse(OfferRecord.shouldAdvanceToBreakevenRelist(true, 1050, 0));
	}
}

package com.flipsmart;
import com.flipsmart.domain.flip.FlipRecommendation;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Covers {@link AutoRecommendService#buildRefreshedQueue} — the ordering decision
 * applied when Flip Finder refreshes its pool in auto mode (issue #722). The
 * focused item must be dropped when it leaves the refreshed pool and retained
 * (without churn) when it is still present.
 */
public class AutoRecommendRefreshQueueTest
{
	private static FlipRecommendation rec(int itemId, String name, double volumePerHour)
	{
		FlipRecommendation r = new FlipRecommendation();
		r.setItemId(itemId);
		r.setItemName(name);
		r.setVolumePerHour(volumePerHour);
		return r;
	}

	private static List<Integer> itemIds(List<FlipRecommendation> queue)
	{
		return queue.stream().map(FlipRecommendation::getItemId).collect(Collectors.toList());
	}

	private static final Set<Integer> NONE_ACTIVE = Collections.emptySet();
	private static final String RAW_SHARK = "Raw Shark";
	private static final String MAGIC_LOGS = "Magic Logs";
	private static final String DEMONIC_HOOD = "Demonic Hood";
	private static final String YEW_LOGS = "Yew Logs";

	// AC2 — focused item removed from the refreshed pool is dropped from the queue.
	@Test
	public void dropsFocusedItemWhenNoLongerRecommended()
	{
		FlipRecommendation stale = rec(1001, DEMONIC_HOOD, 50);
		List<FlipRecommendation> refreshedPool = Arrays.asList(
			rec(2002, RAW_SHARK, 100),
			rec(3003, MAGIC_LOGS, 200));

		List<FlipRecommendation> queue = AutoRecommendService.buildRefreshedQueue(
			refreshedPool, stale, NONE_ACTIVE);

		assertFalse("stale item must be dropped", itemIds(queue).contains(1001));
		assertEquals(Arrays.asList(2002, 3003), itemIds(queue));
	}

	// AC3 — focused item still in the refreshed pool is kept at index 0 (no churn).
	@Test
	public void retainsFocusedItemAtFrontWhenStillRecommended()
	{
		FlipRecommendation focused = rec(2002, RAW_SHARK, 100);
		List<FlipRecommendation> refreshedPool = Arrays.asList(
			rec(3003, MAGIC_LOGS, 200),
			rec(2002, RAW_SHARK, 100),
			rec(4004, YEW_LOGS, 300));

		List<FlipRecommendation> queue = AutoRecommendService.buildRefreshedQueue(
			refreshedPool, focused, NONE_ACTIVE);

		assertEquals("focused item stays at index 0", 2002, queue.get(0).getItemId());
		assertEquals("no duplication of the focused item", 3, queue.size());
		assertTrue(itemIds(queue).containsAll(Arrays.asList(2002, 3003, 4004)));
	}

	// AC5 — focused item now live on the GE is excluded from the refreshed (filtered)
	// pool and must not be re-prepended; the offer is left untouched.
	@Test
	public void doesNotPrependFocusedItemThatIsLiveOnTheGe()
	{
		FlipRecommendation onGe = rec(2002, RAW_SHARK, 100);
		List<FlipRecommendation> refreshedPool = Arrays.asList(
			rec(3003, MAGIC_LOGS, 200));
		Set<Integer> active = new HashSet<>(Collections.singletonList(2002));

		List<FlipRecommendation> queue = AutoRecommendService.buildRefreshedQueue(
			refreshedPool, onGe, active);

		assertFalse("GE-active item not re-queued", itemIds(queue).contains(2002));
		assertEquals(Arrays.asList(3003), itemIds(queue));
	}

	// AC6 — empty refreshed pool clears the queue without error.
	@Test
	public void clearsQueueWhenRefreshedPoolIsEmpty()
	{
		FlipRecommendation stale = rec(1001, DEMONIC_HOOD, 50);

		List<FlipRecommendation> queue = AutoRecommendService.buildRefreshedQueue(
			Collections.emptyList(), stale, NONE_ACTIVE);

		assertTrue("queue cleared when nothing recommended", queue.isEmpty());
	}

	// Nothing focused yet — queue mirrors the refreshed pool.
	@Test
	public void mirrorsPoolWhenNothingFocused()
	{
		List<FlipRecommendation> refreshedPool = Arrays.asList(
			rec(2002, RAW_SHARK, 100),
			rec(3003, MAGIC_LOGS, 200));

		List<FlipRecommendation> queue = AutoRecommendService.buildRefreshedQueue(
			refreshedPool, null, NONE_ACTIVE);

		assertEquals(Arrays.asList(2002, 3003), itemIds(queue));
	}
}

package com.flipsmart.recommend;

import com.flipsmart.domain.offer.OfferRecord;
import com.flipsmart.domain.offer.OfferState;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ResolverInputTest {

    @Test
    public void builderRetainsScalarsAndLists() {
        OfferRecord filledSell = OfferRecord
            .newOffer(1, 0, 100, "Item", false, 5, 200, 1000L)
            .withFill(5, 1000L, OfferState.FILLED, 2000L);

        ResolverInput in = ResolverInput.builder()
            .slotLimit(8)
            .filledSlotCount(3)
            .surfaceableBuy(true, 555)
            .nowMillis(5000L)
            .completedAwaitingCollection(List.of(filledSell))
            .staleOffers(new ArrayList<>())
            .collectedAwaitingList(List.of(
                new CollectedItem(777, CollectOrigin.PARTIAL_CANCEL, true, 4000L)))
            .build();

        assertEquals(8, in.getSlotLimit());
        assertEquals(3, in.getFilledSlotCount());
        assertTrue(in.hasSurfaceableBuy());
        assertEquals(555, in.getSurfaceableBuyItemId());
        assertEquals(5000L, in.getNowMillis());
        assertEquals(1, in.getCompletedAwaitingCollection().size());
        assertEquals(1, in.getCollectedAwaitingList().size());
        assertEquals(CollectOrigin.PARTIAL_CANCEL,
            in.getCollectedAwaitingList().get(0).getOrigin());
    }

    @Test(expected = UnsupportedOperationException.class)
    public void completedAwaitingCollectionGetterIsUnmodifiable() {
        ResolverInput in = ResolverInput.builder()
            .slotLimit(8).filledSlotCount(0).surfaceableBuy(false, -1).nowMillis(0L)
            .completedAwaitingCollection(new ArrayList<>())
            .staleOffers(new ArrayList<>())
            .collectedAwaitingList(new ArrayList<>())
            .build();
        in.getCompletedAwaitingCollection().add(
            OfferRecord.newOffer(2, 1, 1, "x", true, 1, 1, 0L));
    }

    @Test(expected = UnsupportedOperationException.class)
    public void staleOffersGetterIsUnmodifiable() {
        ResolverInput in = ResolverInput.builder()
            .slotLimit(8).filledSlotCount(0).surfaceableBuy(false, -1).nowMillis(0L)
            .completedAwaitingCollection(new ArrayList<>())
            .staleOffers(new ArrayList<>())
            .collectedAwaitingList(new ArrayList<>())
            .build();
        in.getStaleOffers().add(
            OfferRecord.newOffer(2, 1, 1, "x", true, 1, 1, 0L));
    }

    @Test(expected = UnsupportedOperationException.class)
    public void collectedAwaitingListGetterIsUnmodifiable() {
        ResolverInput in = ResolverInput.builder()
            .slotLimit(8).filledSlotCount(0).surfaceableBuy(false, -1).nowMillis(0L)
            .completedAwaitingCollection(new ArrayList<>())
            .staleOffers(new ArrayList<>())
            .collectedAwaitingList(new ArrayList<>())
            .build();
        in.getCollectedAwaitingList().add(
            new CollectedItem(1, CollectOrigin.COMPLETED_BUY, true, 0L));
    }

    @Test
    public void collectedItemHasSellPriceFlagPreserved() {
        CollectedItem c = new CollectedItem(1, CollectOrigin.COMPLETED_BUY, false, 10L);
        assertFalse(c.hasSellPrice());
        assertEquals(CollectOrigin.COMPLETED_BUY, c.getOrigin());
        assertEquals(10L, c.getDetectedAtMillis());
    }
}

package com.flipsmart.recommend;

import com.flipsmart.domain.offer.OfferRecord;
import com.flipsmart.domain.offer.OfferState;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class ActionResolverTest {

    private final ActionResolver resolver = new ActionResolver();

    // ---- builders ----
    private static OfferRecord filledBuy(int slot, int itemId, long activity) {
        return OfferRecord.newOffer(slot + 1, slot, itemId, "buy" + itemId, true, 10, 100, 0L)
            .withFill(10, 1000L, OfferState.FILLED, activity);
    }
    private static OfferRecord filledSell(int slot, int itemId, long activity) {
        return OfferRecord.newOffer(slot + 1, slot, itemId, "sell" + itemId, false, 10, 200, 0L)
            .withFill(10, 2000L, OfferState.FILLED, activity);
    }
    private static OfferRecord cancelledPartialBuy(int slot, int itemId, long activity) {
        return OfferRecord.newOffer(slot + 1, slot, itemId, "buy" + itemId, true, 10, 100, 0L)
            .withFill(4, 400L, OfferState.CANCELLED_PARTIAL, activity);
    }
    private static OfferRecord staleBuyPartial(int slot, int itemId, long activity) {
        return OfferRecord.newOffer(slot + 1, slot, itemId, "buy" + itemId, true, 10, 100, 0L)
            .withFill(3, 300L, OfferState.PARTIAL_FILL, activity);
    }
    private static OfferRecord staleBuyZeroFill(int slot, int itemId, long activity) {
        return OfferRecord.newOffer(slot + 1, slot, itemId, "buy" + itemId, true, 10, 100, activity);
    }
    private static OfferRecord staleSell(int slot, int itemId, long activity) {
        return OfferRecord.newOffer(slot + 1, slot, itemId, "sell" + itemId, false, 10, 200, 0L)
            .withFill(0, 0L, OfferState.NEW, activity);
    }
    private static ResolverInput.Builder base() {
        return ResolverInput.builder()
            .slotLimit(8).filledSlotCount(8).surfaceableBuy(false, -1).nowMillis(100_000L)
            .completedAwaitingCollection(new ArrayList<>())
            .staleOffers(new ArrayList<>())
            .collectedAwaitingList(new ArrayList<>());
    }

    // ---- each tier in isolation ----
    @Test public void s1_fromStalePartialBuy() {
        ResolverInput in = base().staleOffers(Arrays.asList(staleBuyPartial(0, 11, 5L))).build();
        ActionDecision d = resolver.resolve(in);
        assertEquals(ActionKind.S1, d.getKind());
        assertEquals(ActionStep.CANCEL, d.getStep());
        assertEquals(11, d.getItemId());
    }
    @Test public void s1_fromCancelledPartialAwaitingCollect() {
        ResolverInput in = base()
            .completedAwaitingCollection(Arrays.asList(cancelledPartialBuy(0, 12, 5L))).build();
        ActionDecision d = resolver.resolve(in);
        assertEquals(ActionKind.S1, d.getKind());
        assertEquals(ActionStep.COLLECT, d.getStep());
    }
    @Test public void sellWaiting_fromCollectedPartialAwaitingList() {
        ResolverInput in = base().filledSlotCount(7).collectedAwaitingList(Arrays.asList(
            new CollectedItem(13, CollectOrigin.PARTIAL_CANCEL, true, 5L))).build();
        ActionDecision d = resolver.resolve(in);
        assertEquals(ActionKind.SELL_WAITING, d.getKind());
        assertEquals(ActionStep.LIST, d.getStep());
    }
    @Test public void s2_fromEmptySlotWithSurfaceableBuy() {
        ResolverInput in = base().filledSlotCount(7).surfaceableBuy(true, 21).build();
        ActionDecision d = resolver.resolve(in);
        assertEquals(ActionKind.S2, d.getKind());
        assertEquals(ActionStep.PLACE_BUY, d.getStep());
        assertEquals(21, d.getItemId());
    }
    @Test public void s3_fromFilledBuy() {
        ResolverInput in = base().completedAwaitingCollection(
            Arrays.asList(filledBuy(0, 31, 5L))).build();
        assertEquals(ActionKind.S3, resolver.resolve(in).getKind());
        assertEquals(ActionStep.COLLECT, resolver.resolve(in).getStep());
    }
    @Test public void sellWaiting_fromCollectedCompletedBuyAwaitingList() {
        // A collected completed buy awaiting sale lists at SELL_WAITING priority so it
        // is offloaded before a new buy consumes the slot.
        ResolverInput in = base().filledSlotCount(7).collectedAwaitingList(Arrays.asList(
            new CollectedItem(32, CollectOrigin.COMPLETED_BUY, true, 5L))).build();
        ActionDecision d = resolver.resolve(in);
        assertEquals(ActionKind.SELL_WAITING, d.getKind());
        assertEquals(ActionStep.LIST, d.getStep());
    }
    @Test public void s4_fromStaleSell() {
        ResolverInput in = base().staleOffers(Arrays.asList(staleSell(0, 41, 5L))).build();
        assertEquals(ActionKind.S4, resolver.resolve(in).getKind());
        assertEquals(ActionStep.REPRICE, resolver.resolve(in).getStep());
    }
    @Test public void s5_fromFilledSell() {
        ResolverInput in = base().completedAwaitingCollection(
            Arrays.asList(filledSell(0, 51, 5L))).build();
        assertEquals(ActionKind.S5, resolver.resolve(in).getKind());
        assertEquals(ActionStep.COLLECT, resolver.resolve(in).getStep());
    }
    @Test public void s6_fromStaleZeroFillBuy() {
        ResolverInput in = base().staleOffers(Arrays.asList(staleBuyZeroFill(0, 61, 5L))).build();
        assertEquals(ActionKind.S6, resolver.resolve(in).getKind());
        assertEquals(ActionStep.CANCEL, resolver.resolve(in).getStep());
    }

    // ---- adjacent-tier preemption ----
    @Test public void s1_preempts_s2() {
        ResolverInput in = base().filledSlotCount(7).surfaceableBuy(true, 99)
            .staleOffers(Arrays.asList(staleBuyPartial(0, 11, 5L))).build();
        assertEquals(ActionKind.S1, resolver.resolve(in).getKind());
    }
    @Test public void s3_preempts_s2() {
        // Product decision (#914): a completed buy awaiting collection is collected (so it
        // can then be sold) before a new buy consumes the freed slot. A free slot plus a
        // surfaceable buy must not pull us off collecting the item we already own.
        ResolverInput in = base().filledSlotCount(7).surfaceableBuy(true, 99)
            .completedAwaitingCollection(Arrays.asList(filledBuy(0, 31, 5L))).build();
        ActionDecision d = resolver.resolve(in);
        assertEquals(ActionKind.S3, d.getKind());
        assertEquals(ActionStep.COLLECT, d.getStep());
        assertEquals(31, d.getItemId());
    }
    @Test public void s3_preempts_s4() {
        ResolverInput in = base()
            .completedAwaitingCollection(Arrays.asList(filledBuy(0, 31, 5L)))
            .staleOffers(Arrays.asList(staleSell(1, 41, 5L))).build();
        assertEquals(ActionKind.S3, resolver.resolve(in).getKind());
    }
    @Test public void s4_preempts_s5() {
        ResolverInput in = base()
            .staleOffers(Arrays.asList(staleSell(0, 41, 5L)))
            .completedAwaitingCollection(Arrays.asList(filledSell(1, 51, 5L))).build();
        assertEquals(ActionKind.S4, resolver.resolve(in).getKind());
    }
    @Test public void s5_preempts_s6() {
        ResolverInput in = base()
            .completedAwaitingCollection(Arrays.asList(filledSell(0, 51, 5L)))
            .staleOffers(Arrays.asList(staleBuyZeroFill(1, 61, 5L))).build();
        assertEquals(ActionKind.S5, resolver.resolve(in).getKind());
    }

    // ---- FIFO within a tier ----
    @Test public void fifoWithinTierEarliestDetectedWins() {
        ResolverInput in = base().completedAwaitingCollection(Arrays.asList(
            filledSell(0, 501, 9000L),   // later activity
            filledSell(1, 502, 1000L))).build();  // earlier activity → should win
        assertEquals(502, resolver.resolve(in).getItemId());
    }
    @Test public void tierBeatsTimestamp() {
        // a very old S5 must still lose to a fresh S3
        ResolverInput in = base().completedAwaitingCollection(Arrays.asList(
            filledSell(0, 501, 1L),      // ancient S5
            filledBuy(1, 301, 9_999L))). // fresh S3
            build();
        assertEquals(ActionKind.S3, resolver.resolve(in).getKind());
    }
    @Test public void sameTierSameTimestampSmallestSlotWins() {
        ResolverInput in = base().completedAwaitingCollection(Arrays.asList(
            filledSell(5, 505, 1000L),
            filledSell(2, 502, 1000L))).build();
        assertEquals(502, resolver.resolve(in).getItemId());
    }
    @Test public void s1CancelOutranksWaitingSell() {
        // A partially-filled stale buy (S1 CANCEL) is more urgent than listing a held item.
        ResolverInput in = base().filledSlotCount(7)
            .staleOffers(Arrays.asList(staleBuyPartial(3, 303, 1000L)))
            .collectedAwaitingList(Arrays.asList(
                new CollectedItem(909, CollectOrigin.PARTIAL_CANCEL, true, 1000L)))
            .build();
        ActionDecision d = resolver.resolve(in);
        assertEquals(303, d.getItemId());
        assertEquals(ActionStep.CANCEL, d.getStep());
    }

    // ---- S2 gating ----
    @Test public void noS2WhenAllSlotsFull() {
        ResolverInput in = base().filledSlotCount(8).surfaceableBuy(true, 21).build();
        assertEquals(ActionDecision.IDLE, resolver.resolve(in));
    }
    @Test public void noS2WhenNoSurfaceableBuy() {
        ResolverInput in = base().filledSlotCount(5).surfaceableBuy(false, -1).build();
        assertEquals(ActionDecision.IDLE, resolver.resolve(in));
    }
    @Test public void noS2WhenBlockedForPendingSell() {
        // A just-collected item is awaiting its sell price: hold the free slot instead of
        // spending it on a new buy that would strand the item we already own.
        ResolverInput in = base().filledSlotCount(7).surfaceableBuy(true, 21)
            .blockBuyForPendingSell(true, 777).build();
        assertEquals(ActionDecision.IDLE, resolver.resolve(in));
    }
    @Test public void pendingSellBlockDoesNotSuppressHigherPriority() {
        // The block only gates the S2 buy — a more urgent S1 cancel must still fire.
        ResolverInput in = base().filledSlotCount(7).surfaceableBuy(true, 21)
            .blockBuyForPendingSell(true, 777)
            .staleOffers(Arrays.asList(staleBuyPartial(0, 11, 5L))).build();
        assertEquals(ActionKind.S1, resolver.resolve(in).getKind());
    }

    // ---- list-step requires a sell price (no empty label) ----
    @Test public void collectedItemWithoutSellPriceIsNotSurfaced() {
        ResolverInput in = base().filledSlotCount(7).collectedAwaitingList(Arrays.asList(
            new CollectedItem(13, CollectOrigin.PARTIAL_CANCEL, false, 5L))).build();
        assertEquals(ActionDecision.IDLE, resolver.resolve(in));
    }

    // ---- AC1-4: sell-priority around GE slot availability (scoped to preemptive collects) ----
    @Test public void ac1_noSellPromptWhenAllSlotsFull() {
        // 8/8 slots filled → a held item awaiting list must NOT surface (no slot to act on).
        ResolverInput in = base().filledSlotCount(8).collectedAwaitingList(Arrays.asList(
            new CollectedItem(70, CollectOrigin.PARTIAL_CANCEL, true, 5L))).build();
        assertEquals(ActionDecision.IDLE, resolver.resolve(in));
    }
    @Test public void ac2_preemptiveSellBeatsNewBuyWhenSlotFree() {
        // A freed slot, a surfaceable buy, and an item collected preemptively from an open
        // trade (partial cancel) → the waiting sell wins over a new buy.
        ResolverInput in = base().filledSlotCount(7).surfaceableBuy(true, 99)
            .collectedAwaitingList(Arrays.asList(
                new CollectedItem(71, CollectOrigin.PARTIAL_CANCEL, true, 5L))).build();
        ActionDecision d = resolver.resolve(in);
        assertEquals(ActionKind.SELL_WAITING, d.getKind());
        assertEquals(ActionStep.LIST, d.getStep());
        assertEquals(71, d.getItemId());
    }
    @Test public void completedBuyHeldItemBeatsNewBuy() {
        // A normally-completed buy that has been collected for sale is listed before
        // placing a new buy: the free slot lists the item we already own rather than
        // being consumed by a new buy that leaves it nowhere to sell.
        ResolverInput in = base().filledSlotCount(7).surfaceableBuy(true, 99)
            .collectedAwaitingList(Arrays.asList(
                new CollectedItem(71, CollectOrigin.COMPLETED_BUY, true, 5L))).build();
        ActionDecision d = resolver.resolve(in);
        assertEquals(ActionKind.SELL_WAITING, d.getKind());
        assertEquals(ActionStep.LIST, d.getStep());
        assertEquals(71, d.getItemId());
    }
    @Test public void ac4_oldestPreemptiveSellTakesPriority() {
        // Two preemptively-collected items awaiting list → the one waiting longest surfaces first.
        ResolverInput in = base().filledSlotCount(7).collectedAwaitingList(Arrays.asList(
            new CollectedItem(72, CollectOrigin.PARTIAL_CANCEL, true, 9000L),   // newer
            new CollectedItem(73, CollectOrigin.PARTIAL_CANCEL, true, 1000L)))  // older → wins
            .build();
        assertEquals(73, resolver.resolve(in).getItemId());
    }

    // ---- free-tier Flip Finder cap (gates new buys only, never sells) ----
    @Test public void noS2WhenFlipFinderCapReached() {
        ResolverInput in = base().filledSlotCount(7).surfaceableBuy(true, 21)
            .flipFinderCapReached(true).build();
        assertEquals(ActionDecision.IDLE, resolver.resolve(in));
    }
    @Test public void s2WhenFlipFinderCapNotReached() {
        ResolverInput in = base().filledSlotCount(7).surfaceableBuy(true, 21)
            .flipFinderCapReached(false).build();
        ActionDecision d = resolver.resolve(in);
        assertEquals(ActionKind.S2, d.getKind());
        assertEquals(ActionStep.PLACE_BUY, d.getStep());
        assertEquals(21, d.getItemId());
    }
    @Test public void flipFinderCapDoesNotSuppressSell() {
        // Anti-deadlock: a free user at the cap must still be able to list collected sells.
        ResolverInput in = base().filledSlotCount(7).flipFinderCapReached(true)
            .collectedAwaitingList(Arrays.asList(
                new CollectedItem(13, CollectOrigin.PARTIAL_CANCEL, true, 5L))).build();
        ActionDecision d = resolver.resolve(in);
        assertEquals(ActionKind.SELL_WAITING, d.getKind());
        assertEquals(ActionStep.LIST, d.getStep());
    }
    @Test public void flipFinderCapDoesNotSuppressHigherPriority() {
        ResolverInput in = base().filledSlotCount(7).surfaceableBuy(true, 21)
            .flipFinderCapReached(true)
            .staleOffers(Arrays.asList(staleBuyPartial(0, 11, 5L))).build();
        assertEquals(ActionKind.S1, resolver.resolve(in).getKind());
    }

    // ---- idle ----
    @Test public void idleWhenNothingActionable() {
        assertEquals(ActionDecision.IDLE, resolver.resolve(base().build()));
    }

    // ---- determinism (anti-flap) ----
    @Test public void identicalInputYieldsIdenticalDecision() {
        ResolverInput in = base()
            .staleOffers(Arrays.asList(staleBuyPartial(0, 11, 5L))).build();
        assertEquals(resolver.resolve(in), resolver.resolve(in));
    }
}

package com.flipsmart.recommend;

import com.flipsmart.domain.flip.ActiveFlip;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * A flip whose cost basis has gone missing must never be priced as if the basis were
 * genuinely zero. The breakeven formula reads a lost basis as "this cost me nothing",
 * so it happily returns 1gp — a price the player can act on and lose the whole position.
 */
public class SmartSellPricerLostBasisTest
{
	private static final long MARKET_PRICE = 8_925_470L;

	private static ActiveFlip flip(int averageBuyPrice, Integer recommendedSellPrice)
	{
		ActiveFlip f = new ActiveFlip();
		f.setItemId(1234);
		f.setItemName("Blood moon tassets");
		f.setAverageBuyPrice(averageBuyPrice);
		f.setRecommendedSellPrice(recommendedSellPrice == null ? null : recommendedSellPrice.longValue());
		return f;
	}

	@Test
	public void minProfitableSellPriceIsNotComputableWithoutABasis()
	{
		assertEquals("a lost basis has no breakeven; 0 means 'not computable'",
			0, SmartSellPricer.calculateMinProfitableSellPrice(0));
	}

	@Test
	public void minProfitableSellPriceStillComputesFromARealBasis()
	{
		assertEquals(104, SmartSellPricer.calculateMinProfitableSellPrice(100));
	}

	@Test
	public void smartSellPriceFallsBackToMarketWhenBasisIsLost()
	{
		Long price = SmartSellPricer.calculateSmartSellPrice(flip(0, null), MARKET_PRICE);

		assertEquals("with no basis and no target, the market price is the only sane answer",
			Long.valueOf(MARKET_PRICE), price);
	}

	@Test
	public void smartSellPriceKeepsTheOriginalTargetWhenBasisIsLost()
	{
		Long price = SmartSellPricer.calculateSmartSellPrice(flip(0, 9_100_000), MARKET_PRICE);

		assertEquals("the original recommendation outranks the market fallback",
			Long.valueOf(9_100_000), price);
	}

	@Test
	public void smartSellPriceIsUnavailableWhenBasisAndMarketAreBothUnknown()
	{
		assertNull("nothing is known, so no price may be surfaced",
			SmartSellPricer.calculateSmartSellPrice(flip(0, null), null));
	}

	@Test
	public void smartSellPriceIsUnchangedForAHealthyFlip()
	{
		Long price = SmartSellPricer.calculateSmartSellPrice(flip(8_000_000, null), MARKET_PRICE);

		assertEquals(Long.valueOf(SmartSellPricer.calculateMinProfitableSellPrice(8_000_000)), price);
	}

	@Test
	public void smartSellPriceKeepsRecommendationThatClearsBreakeven()
	{
		Long price = SmartSellPricer.calculateSmartSellPrice(flip(8_000_000, 9_000_000), MARKET_PRICE);

		assertEquals("a recommendation at or above breakeven outranks the market price",
			Long.valueOf(9_000_000), price);
	}

	@Test
	public void smartSellPriceKeepsRecommendationWhenUnderwaterAndMarketIsUnviable()
	{
		Long price = SmartSellPricer.calculateSmartSellPrice(flip(8_000_000, 7_000_000), null);

		assertEquals("with no viable market, an underwater recommendation is still the last known target",
			Long.valueOf(7_000_000), price);
	}

	@Test
	public void smartSellPriceFallsBackToBreakevenWhenOnlyBasisIsKnown()
	{
		Long price = SmartSellPricer.calculateSmartSellPrice(flip(8_000_000, null), null);

		assertEquals("no recommendation and no market leaves breakeven as the floor",
			Long.valueOf(SmartSellPricer.calculateMinProfitableSellPrice(8_000_000)), price);
	}

	@Test
	public void smartSellPriceRejectsANonPositiveRecommendation()
	{
		Long price = SmartSellPricer.calculateSmartSellPrice(flip(8_000_000, 0), null);

		assertEquals("a non-positive recommendation is not a price; breakeven is the floor",
			Long.valueOf(SmartSellPricer.calculateMinProfitableSellPrice(8_000_000)), price);
	}
}

package com.flipsmart.recommend;

import com.flipsmart.domain.flip.FlipRecommendation;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * Characterization tests for {@link RecommendationQueue}, the buy-queue collaborator
 * extracted from {@code AutoRecommendService} in #733. These pin the current bounded
 * add/replace, cursor-advancement, and lifecycle semantics so the deferred Codacy
 * refactors (unmodifiable {@code view()}, cursor-reset on {@code clear()}, field
 * renames) are made against a guarded baseline rather than blind.
 *
 * <p>Two current behaviors are surprising and pinned deliberately: {@code view()}
 * returns the LIVE backing list (not an unmodifiable copy), and {@code clear()} /
 * {@code clearAll()} do NOT reset the cursor.
 */
public class RecommendationQueueTest
{
	private static FlipRecommendation rec(int itemId, int sellPrice)
	{
		FlipRecommendation r = new FlipRecommendation();
		r.setItemId(itemId);
		r.setItemName("item-" + itemId);
		r.setRecommendedSellPrice(sellPrice);
		return r;
	}

	private static FlipRecommendation recVol(int itemId, double volumePerHour)
	{
		FlipRecommendation r = rec(itemId, 0);
		r.setVolumePerHour(volumePerHour);
		return r;
	}

	// ---- replace / add ----

	@Test
	public void replaceClearsAddsAndResetsCursorToFront()
	{
		RecommendationQueue q = new RecommendationQueue();
		q.setCurrentIndex(3);
		FlipRecommendation a = rec(11, 100);
		q.replace(Arrays.asList(a, rec(12, 100)));

		assertEquals(2, q.size());
		assertEquals(0, q.getCurrentIndex());
		assertSame(a, q.get(0));
	}

	@Test
	public void addFilteredByActiveDropsActiveItemsButStillCachesTheirNames()
	{
		RecommendationQueue q = new RecommendationQueue();
		q.setCurrentIndex(2);
		q.addFilteredByActive(
			Arrays.asList(rec(11, 100), rec(12, 100)),
			Collections.singleton(12));

		assertEquals("active item must be filtered out of the queue", 1, q.size());
		assertEquals(11, q.get(0).getItemId());
		// Name cache survives the active filter (used for prompts even while live on the GE).
		assertEquals("item-12", q.getItemName(12, "fallback"));
		assertEquals("item-11", q.getItemName(11, "fallback"));
		assertEquals("addFilteredByActive must not reset the cursor", 2, q.getCurrentIndex());
	}

	@Test
	public void getItemNameReturnsFallbackWhenUncached()
	{
		assertEquals("fallback", new RecommendationQueue().getItemName(999, "fallback"));
	}

	// ---- snapshot vs view ----

	@Test
	public void snapshotIsADetachedCopy()
	{
		RecommendationQueue q = new RecommendationQueue();
		q.replace(Arrays.asList(rec(11, 100)));

		List<FlipRecommendation> snap = q.snapshot();
		snap.clear();

		assertEquals("mutating the snapshot must not affect the queue", 1, q.size());
	}

	@Test
	public void viewReflectsTheBackingListForReads()
	{
		// view() is an unmodifiable window over the live backing list — reads still
		// reflect later mutations to the queue.
		RecommendationQueue q = new RecommendationQueue();
		q.replace(Arrays.asList(rec(11, 100)));
		List<FlipRecommendation> view = q.view();
		assertEquals(1, view.size());

		q.clear();
		assertEquals("view() must reflect the live backing list for reads", 0, view.size());
	}

	@Test(expected = UnsupportedOperationException.class)
	public void viewRejectsMutation()
	{
		RecommendationQueue q = new RecommendationQueue();
		q.replace(Arrays.asList(rec(11, 100)));
		q.view().add(rec(12, 100));
	}

	@Test
	public void addAllAppendsWithoutResettingCursor()
	{
		// Used by the offline-sync restore path, which sets a specific cursor afterward
		// (so unlike replace(), addAll must leave the cursor alone).
		RecommendationQueue q = new RecommendationQueue();
		q.replace(Arrays.asList(rec(11, 100)));
		q.setCurrentIndex(1);

		q.addAll(Arrays.asList(rec(12, 100), rec(13, 100)));

		assertEquals(3, q.size());
		assertEquals(12, q.get(1).getItemId());
		assertEquals("addAll must not reset the cursor", 1, q.getCurrentIndex());
	}

	@Test
	public void replaceIsSafeWhenAliasedWithItsOwnView()
	{
		// view() is an unmodifiable window over the backing list; replace() must copy its
		// argument before clearing, or replace(view()) would self-empty before re-adding.
		RecommendationQueue q = new RecommendationQueue();
		q.replace(Arrays.asList(rec(11, 100), rec(12, 100)));

		q.replace(q.view());

		assertEquals("replace(view()) must not self-clear", 2, q.size());
		assertEquals(11, q.get(0).getItemId());
	}

	// ---- cursor ----

	@Test
	public void getCurrentRecommendationReturnsItemAtCursor()
	{
		RecommendationQueue q = new RecommendationQueue();
		FlipRecommendation b = rec(12, 100);
		q.replace(Arrays.asList(rec(11, 100), b));
		q.setCurrentIndex(1);
		assertSame(b, q.getCurrentRecommendation());
	}

	@Test
	public void getCurrentRecommendationNullWhenCursorOutOfBounds()
	{
		RecommendationQueue q = new RecommendationQueue();
		q.replace(Arrays.asList(rec(11, 100)));
		q.setCurrentIndex(5);
		assertNull(q.getCurrentRecommendation());
	}

	@Test
	public void cursorBoundsPredicates()
	{
		RecommendationQueue q = new RecommendationQueue();
		q.replace(Arrays.asList(rec(11, 100)));

		q.setCurrentIndex(0);
		assertTrue(q.cursorWithinBounds());
		assertFalse(q.cursorBeyondEnd());

		q.setCurrentIndex(1);
		assertFalse(q.cursorWithinBounds());
		assertTrue(q.cursorBeyondEnd());
	}

	@Test
	public void skipToNextSurfaceableSkipsActiveAndBelowMinProfit()
	{
		RecommendationQueue q = new RecommendationQueue();
		FlipRecommendation surfaceable = rec(14, 500);
		q.replace(Arrays.asList(rec(11, 500), rec(12, 500), rec(13, 50), surfaceable));
		q.setCurrentIndex(0); // currently on item 11

		// item 12 is live on the GE (skip), item 13 profit 50 < 100 (skip) → stop at 14.
		q.skipToNextSurfaceable(
			Collections.singleton(12),
			FlipRecommendation::getRecommendedSellPrice,
			100);

		assertEquals(3, q.getCurrentIndex());
		assertSame(surfaceable, q.getCurrentRecommendation());
	}

	@Test
	public void skipToNextSurfaceableSkipsCoolingDownItems()
	{
		RecommendationQueue q = new RecommendationQueue();
		FlipRecommendation surfaceable = rec(14, 500);
		q.replace(Arrays.asList(rec(11, 500), rec(12, 500), rec(13, 500), surfaceable));
		q.setCurrentIndex(0); // currently on item 11

		// items 12 and 13 were recently skipped (cooling) → cursor lands on 14 (AC2).
		q.skipToNextSurfaceable(
			Collections.emptySet(),
			FlipRecommendation::getRecommendedSellPrice,
			100,
			id -> id == 12 || id == 13);

		assertEquals(3, q.getCurrentIndex());
		assertSame(surfaceable, q.getCurrentRecommendation());
	}

	@Test
	public void skipToNextSurfaceableRunsOffEndWhenNoneQualify()
	{
		RecommendationQueue q = new RecommendationQueue();
		q.replace(Arrays.asList(rec(11, 500), rec(12, 50)));
		q.setCurrentIndex(0);

		q.skipToNextSurfaceable(
			Collections.emptySet(),
			FlipRecommendation::getRecommendedSellPrice,
			100); // item 12 profit 50 < 100 → run off the end

		assertEquals(2, q.getCurrentIndex());
		assertTrue(q.cursorBeyondEnd());
		assertNull(q.getCurrentRecommendation());
	}

	// ---- lifecycle: clear / clearAll ----

	@Test
	public void clearEmptiesQueueAndResetsCursorToFront()
	{
		RecommendationQueue q = new RecommendationQueue();
		q.replace(Arrays.asList(rec(11, 100), rec(12, 100)));
		q.setCurrentIndex(2);

		q.clear();

		assertTrue(q.isEmpty());
		assertEquals("clear() resets the cursor to the front", 0, q.getCurrentIndex());
	}

	@Test
	public void clearAllAlsoDropsCachedNamesAndResetsCursorToFront()
	{
		RecommendationQueue q = new RecommendationQueue();
		q.addFilteredByActive(Arrays.asList(rec(11, 100)), Collections.emptySet());
		q.setCurrentIndex(1);

		q.clearAll();

		assertTrue(q.isEmpty());
		assertEquals("clearAll() must drop the name cache", "fallback", q.getItemName(11, "fallback"));
		assertEquals("clearAll() resets the cursor to the front", 0, q.getCurrentIndex());
	}

	@Test
	public void putItemNameIgnoresNull()
	{
		// itemNames is a ConcurrentHashMap, which rejects null values — a null name must
		// simply not be cached (the getter then returns the caller's fallback).
		RecommendationQueue q = new RecommendationQueue();
		q.putItemName(11, null);
		assertEquals("fallback", q.getItemName(11, "fallback"));
	}

	@Test
	public void addFilteredByActiveSkipsCachingNullNames()
	{
		RecommendationQueue q = new RecommendationQueue();
		FlipRecommendation noName = new FlipRecommendation();
		noName.setItemId(11);
		noName.setItemName(null);

		q.addFilteredByActive(Arrays.asList(noName), Collections.emptySet());

		assertEquals("the recommendation is still queued", 1, q.size());
		assertEquals("a null name must not be cached", "fallback", q.getItemName(11, "fallback"));
	}

	// ---- lookups / sorting ----

	@Test
	public void findRecommendationForItemReturnsMatchOrNull()
	{
		RecommendationQueue q = new RecommendationQueue();
		FlipRecommendation b = rec(12, 100);
		q.replace(Arrays.asList(rec(11, 100), b));

		assertSame(b, q.findRecommendationForItem(12));
		assertNull(q.findRecommendationForItem(999));
	}

	@Test
	public void sortByVolumeAscendingOrdersSlowestFillingFirst()
	{
		RecommendationQueue q = new RecommendationQueue();
		q.replace(Arrays.asList(recVol(11, 10.0), recVol(12, 2.0), recVol(13, 5.0)));

		q.sortByVolumeAscending();

		assertEquals(12, q.get(0).getItemId());
		assertEquals(13, q.get(1).getItemId());
		assertEquals(11, q.get(2).getItemId());
	}

	// ---- ancillary state ----

	@Test
	public void refreshTimestampRoundTrips()
	{
		RecommendationQueue q = new RecommendationQueue();
		assertEquals(0L, q.getLastQueueRefreshMillis());
		q.setLastQueueRefreshMillis(123456L);
		assertEquals(123456L, q.getLastQueueRefreshMillis());
	}

	@Test
	public void lockedItemIdRoundTrips()
	{
		RecommendationQueue q = new RecommendationQueue();
		assertNull(q.getLockedItemId());
		q.setLockedItemId(42);
		assertEquals(Integer.valueOf(42), q.getLockedItemId());
		q.setLockedItemId(null);
		assertNull(q.getLockedItemId());
	}
}

package com.flipsmart.recommend;

import com.flipsmart.recommend.AdjustmentService.SellAdjustmentState;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Characterization tests for {@link AdjustmentService}, the adjustment-timer state
 * collaborator extracted from {@code AutoRecommendService} in #733. Pins the buy
 * deadline / sell-adjustment-state / buy-price bookkeeping before the deferred
 * Codacy change (HashMap → ConcurrentHashMap) touches it.
 */
public class AdjustmentServiceTest
{
	// ---- buy deadlines ----

	@Test
	public void buyDeadlinePutHasRemoveAndCount()
	{
		AdjustmentService svc = new AdjustmentService();
		assertFalse(svc.hasBuyDeadlines());
		assertEquals(0, svc.buyDeadlineCount());

		svc.putBuyDeadline(11, 1000L);
		assertTrue(svc.hasBuyDeadlines());
		assertTrue(svc.hasBuyDeadline(11));
		assertFalse(svc.hasBuyDeadline(12));
		assertEquals(1, svc.buyDeadlineCount());

		assertTrue("removing a present deadline returns true", svc.removeBuyDeadline(11));
		assertFalse("removing an absent deadline returns false", svc.removeBuyDeadline(11));
		assertEquals(0, svc.buyDeadlineCount());
	}

	@Test
	public void buyDeadlineIteratorYieldsAllEntries()
	{
		AdjustmentService svc = new AdjustmentService();
		svc.putBuyDeadline(11, 1000L);
		svc.putBuyDeadline(12, 2000L);

		Map<Integer, Long> seen = new HashMap<>();
		svc.buyDeadlineIterator().forEachRemaining(e -> seen.put(e.getKey(), e.getValue()));

		assertEquals(2, seen.size());
		assertEquals(Long.valueOf(1000L), seen.get(11));
		assertEquals(Long.valueOf(2000L), seen.get(12));
	}

	// ---- sell adjustment states ----

	@Test
	public void sellStateConstructorDefaultsAndPutGetRemove()
	{
		AdjustmentService svc = new AdjustmentService();
		assertFalse(svc.hasSellStates());

		SellAdjustmentState state = new SellAdjustmentState(11, "item-11", 250, 5000L);
		assertEquals(11, state.itemId);
		assertEquals("item-11", state.itemName);
		assertEquals(250, state.averageBuyPrice);
		assertEquals(5000L, state.deadline);
		assertEquals("adjustmentCount starts at zero", 0, state.adjustmentCount);

		svc.putSellState(11, state);
		assertTrue(svc.hasSellStates());
		assertTrue(svc.hasSellState(11));
		assertEquals(state, svc.getSellState(11));
		assertNull(svc.getSellState(99));

		assertTrue(svc.removeSellState(11));
		assertFalse(svc.removeSellState(11));
		assertFalse(svc.hasSellStates());
	}

	@Test
	public void sellAdjustmentStateTransitionFieldsAreMutable()
	{
		// The adjustment "transition" is bumping the count and pushing the deadline forward;
		// both are public mutable fields the coordinator advances in place.
		SellAdjustmentState state = new SellAdjustmentState(11, "item-11", 250, 5000L);

		state.adjustmentCount++;
		state.deadline = 9000L;

		assertEquals(1, state.adjustmentCount);
		assertEquals(9000L, state.deadline);
	}

	@Test
	public void sellStateIteratorYieldsAllEntries()
	{
		AdjustmentService svc = new AdjustmentService();
		svc.putSellState(11, new SellAdjustmentState(11, "item-11", 250, 5000L));
		svc.putSellState(12, new SellAdjustmentState(12, "item-12", 300, 6000L));

		Map<Integer, SellAdjustmentState> seen = new HashMap<>();
		svc.sellStateIterator().forEachRemaining(e -> seen.put(e.getKey(), e.getValue()));

		assertEquals(2, seen.size());
		assertEquals(250, seen.get(11).averageBuyPrice);
		assertEquals(300, seen.get(12).averageBuyPrice);
	}

	// ---- buy prices (cost basis) ----

	@Test
	public void buyPricePutGetDefaultRemoveAndEmpty()
	{
		AdjustmentService svc = new AdjustmentService();
		assertTrue(svc.buyPricesEmpty());

		svc.putBuyPrice(11, 250);
		assertEquals(Long.valueOf(250), svc.getBuyPrice(11));
		assertEquals(Long.valueOf(250), svc.getBuyPriceOrDefault(11, 9));
		assertEquals("absent item falls back to the default", Long.valueOf(9), svc.getBuyPriceOrDefault(99, 9));
		assertNull(svc.getBuyPrice(99));
		assertFalse(svc.buyPricesEmpty());

		svc.removeBuyPrice(11);
		assertTrue(svc.buyPricesEmpty());
	}

	@Test
	public void buyPricesSnapshotIsDetached()
	{
		AdjustmentService svc = new AdjustmentService();
		svc.putBuyPrice(11, 250);

		Map<Integer, Long> snap = svc.buyPricesSnapshot();
		snap.put(12, 999L);

		assertNull("mutating the snapshot must not leak into the service", svc.getBuyPrice(12));
		assertEquals(Long.valueOf(250), svc.getBuyPrice(11));
	}

	@Test
	public void putAllBuyPricesMergesWithoutDroppingExisting()
	{
		AdjustmentService svc = new AdjustmentService();
		svc.putBuyPrice(11, 250);

		Map<Integer, Long> more = new HashMap<>();
		more.put(12, 300L);
		more.put(13, 400L);
		svc.putAllBuyPrices(more);

		assertEquals(Long.valueOf(250), svc.getBuyPrice(11));
		assertEquals(Long.valueOf(300), svc.getBuyPrice(12));
		assertEquals(Long.valueOf(400), svc.getBuyPrice(13));
	}

	// ---- lifecycle ----

	@Test
	public void clearWipesAllThreeMaps()
	{
		AdjustmentService svc = new AdjustmentService();
		svc.putBuyDeadline(11, 1000L);
		svc.putSellState(11, new SellAdjustmentState(11, "item-11", 250, 5000L));
		svc.putBuyPrice(11, 250);

		svc.clear();

		assertFalse(svc.hasBuyDeadlines());
		assertFalse(svc.hasSellStates());
		assertTrue(svc.buyPricesEmpty());
	}
}

package com.flipsmart.recommend;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;

public class ActionDecisionTest {

    @Test
    public void idleConstantHasIdleKindAndNoItem() {
        assertEquals(ActionKind.IDLE, ActionDecision.IDLE.getKind());
        assertEquals(ActionStep.NONE, ActionDecision.IDLE.getStep());
        assertEquals(-1, ActionDecision.IDLE.getItemId());
        assertEquals(-1, ActionDecision.IDLE.getSlot());
    }

    @Test
    public void equalityIgnoresDetectedAtMillis() {
        ActionDecision a = new ActionDecision(ActionKind.S1, ActionStep.LIST, 555, 3, 1000L);
        ActionDecision b = new ActionDecision(ActionKind.S1, ActionStep.LIST, 555, 3, 9999L);
        assertEquals(a, b);
        assertEquals(a.hashCode(), b.hashCode());
    }

    @Test
    public void differentKindOrStepOrItemOrSlotAreNotEqual() {
        ActionDecision base = new ActionDecision(ActionKind.S3, ActionStep.COLLECT, 1, 0, 0L);
        assertNotEquals(base, new ActionDecision(ActionKind.S5, ActionStep.COLLECT, 1, 0, 0L));
        assertNotEquals(base, new ActionDecision(ActionKind.S3, ActionStep.LIST, 1, 0, 0L));
        assertNotEquals(base, new ActionDecision(ActionKind.S3, ActionStep.COLLECT, 2, 0, 0L));
        assertNotEquals(base, new ActionDecision(ActionKind.S3, ActionStep.COLLECT, 1, 7, 0L));
    }

    @Test
    public void priorityFollowsDeclarationOrder() {
        assertTrue(ActionKind.S1.ordinal() < ActionKind.S2.ordinal());
        assertTrue(ActionKind.S5.ordinal() < ActionKind.S6.ordinal());
        assertTrue(ActionKind.S6.ordinal() < ActionKind.IDLE.ordinal());
    }
}

package com.flipsmart.recommend;

import com.flipsmart.domain.offer.OfferRecord;
import com.flipsmart.recommend.StaleOfferQueue.AddResult;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Characterization tests for {@link StaleOfferQueue}, the stale-offer collaborator
 * extracted from {@code AutoRecommendService} in #733. Pins the dedup/prompt-once
 * add semantics, head/remove/prune bookkeeping, and the companion resell-price/net
 * maps before the deferred Codacy field-rename touches it.
 */
public class StaleOfferQueueTest
{
	private static OfferRecord sell(int itemId)
	{
		return OfferRecord.newOffer(itemId, 0, itemId, "item-" + itemId, false, 1, 100, 1000L);
	}

	@Test
	public void head_onEmptyQueue_returnsNullInsteadOfThrowing()
	{
		// The queue can be drained between an isEmpty() check and head() (the offer is
		// cancelled/filled on another path), so head() must be null-safe rather than throw
		// ArrayIndexOutOfBoundsException into the RuneLite client thread.
		assertNull("head() on an empty queue must return null, not throw",
			new StaleOfferQueue().head());
	}

	@Test
	public void head_returnsFirstQueuedOffer_whenNonEmpty()
	{
		StaleOfferQueue queue = new StaleOfferQueue();
		queue.addIfAbsent(OfferRecord.newOffer(1L, 0, 4151, "Abyssal whip", false, 1, 100, 1000L));

		OfferRecord head = queue.head();
		assertNotNull(head);
		assertEquals(4151, head.getItemId());
	}

	// ---- addIfAbsent tri-state dedup (first-prompt-once) ----

	@Test
	public void addIfAbsentReportsEmptyThenAppendThenDedup()
	{
		StaleOfferQueue q = new StaleOfferQueue();

		assertEquals("first add into an empty queue surfaces the prompt",
			AddResult.ADDED_WAS_EMPTY, q.addIfAbsent(sell(11)));
		assertEquals(1, q.size());

		assertEquals("a different item appends without surfacing",
			AddResult.ADDED, q.addIfAbsent(sell(12)));
		assertEquals(2, q.size());

		// Same item again (even a distinct offer id) is the dedup no-op — prompt only once.
		assertEquals("an item already queued must not be re-added or re-prompted",
			AddResult.ALREADY_PRESENT,
			q.addIfAbsent(OfferRecord.newOffer(99L, 0, 11, "item-11", false, 1, 100, 2000L)));
		assertEquals(2, q.size());
	}

	// ---- head / remove / prune ----

	@Test
	public void removeHeadReturnsOfferAndClearsItsResellPrice()
	{
		StaleOfferQueue q = new StaleOfferQueue();
		q.addIfAbsent(sell(11));
		q.putResellPrice(11, 150);

		OfferRecord removed = q.removeHead();

		assertEquals(11, removed.getItemId());
		assertNull("removeHead must clear the removed item's resell price", q.getResellPrice(11));
		assertTrue(q.isEmpty());
	}

	@Test
	public void removeOfferDropsItAndItsResellPriceKeepingOthers()
	{
		StaleOfferQueue q = new StaleOfferQueue();
		q.addIfAbsent(sell(11));
		q.addIfAbsent(sell(12));
		q.putResellPrice(11, 150);
		q.putResellPrice(12, 200);

		q.removeOffer(11);

		assertEquals(1, q.size());
		assertTrue(q.headIsItem(12));
		assertNull(q.getResellPrice(11));
		assertEquals(Long.valueOf(200), q.getResellPrice(12));
	}

	@Test
	public void pruneIrrelevantRemovesMatchingAndClearsTheirResellPrice()
	{
		StaleOfferQueue q = new StaleOfferQueue();
		q.addIfAbsent(sell(11));
		q.addIfAbsent(sell(12));
		q.putResellPrice(11, 150);
		q.putResellPrice(12, 200);

		q.pruneIrrelevant(o -> o.getItemId() == 11);

		assertEquals(1, q.size());
		assertTrue(q.headIsItem(12));
		assertNull("pruned item's resell price must be cleared", q.getResellPrice(11));
		assertEquals(Long.valueOf(200), q.getResellPrice(12));
	}

	// ---- resell price / net bookkeeping ----

	@Test
	public void resellPriceAndNetRoundTripAndRemove()
	{
		StaleOfferQueue q = new StaleOfferQueue();

		assertNull(q.getResellPrice(11));
		q.putResellPrice(11, 150);
		assertEquals(Long.valueOf(150), q.getResellPrice(11));

		assertNull(q.getResellNet(11));
		q.putResellNet(11, -50);
		assertEquals(Long.valueOf(-50), q.getResellNet(11));
		q.removeResellNet(11);
		assertNull(q.getResellNet(11));
	}

	@Test
	public void removeOfferAlsoClearsResellNet()
	{
		// staleResellNet is a companion map to staleResellPrices; removal must clear both
		// or the net estimate leaks for an item no longer queued.
		StaleOfferQueue q = new StaleOfferQueue();
		q.addIfAbsent(sell(11));
		q.putResellPrice(11, 150);
		q.putResellNet(11, -50);

		q.removeOffer(11);

		assertNull("removeOffer must clear the companion resell-net entry", q.getResellNet(11));
	}

	@Test
	public void removeHeadAlsoClearsResellNet()
	{
		StaleOfferQueue q = new StaleOfferQueue();
		q.addIfAbsent(sell(11));
		q.putResellNet(11, -50);

		q.removeHead();

		assertNull("removeHead must clear the companion resell-net entry", q.getResellNet(11));
	}

	@Test
	public void pruneIrrelevantAlsoClearsResellNet()
	{
		StaleOfferQueue q = new StaleOfferQueue();
		q.addIfAbsent(sell(11));
		q.putResellNet(11, -50);

		q.pruneIrrelevant(o -> o.getItemId() == 11);

		assertNull("pruneIrrelevant must clear the companion resell-net entry", q.getResellNet(11));
	}

	// ---- lookups ----

	@Test
	public void findByItemIdReturnsMatchOrNull()
	{
		StaleOfferQueue q = new StaleOfferQueue();
		q.addIfAbsent(sell(11));
		q.addIfAbsent(sell(12));

		assertEquals(12, q.findByItemId(12).getItemId());
		assertNull(q.findByItemId(999));
	}

	@Test
	public void headIsItemMatchesOnlyTheFront()
	{
		StaleOfferQueue q = new StaleOfferQueue();
		assertFalse("empty queue head matches nothing", q.headIsItem(11));

		q.addIfAbsent(sell(11));
		q.addIfAbsent(sell(12));
		assertTrue(q.headIsItem(11));
		assertFalse(q.headIsItem(12));
	}

	// ---- snapshot ----

	@Test(expected = UnsupportedOperationException.class)
	public void snapshotIsUnmodifiable()
	{
		StaleOfferQueue q = new StaleOfferQueue();
		q.addIfAbsent(sell(11));
		q.snapshot().add(sell(12));
	}

	@Test
	public void snapshotIsDetachedFromLaterMutations()
	{
		StaleOfferQueue q = new StaleOfferQueue();
		q.addIfAbsent(sell(11));

		List<OfferRecord> snap = q.snapshot();
		q.removeHead();

		assertEquals("snapshot must not reflect mutations after it was taken", 1, snap.size());
	}

	// ---- lifecycle ----

	@Test
	public void clearWipesQueueResellPriceAndNet()
	{
		StaleOfferQueue q = new StaleOfferQueue();
		q.addIfAbsent(sell(11));
		q.putResellPrice(11, 150);
		q.putResellNet(11, -50);

		q.clear();

		assertTrue(q.isEmpty());
		assertNull(q.getResellPrice(11));
		assertNull(q.getResellNet(11));
	}
}

package com.flipsmart.recommend;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Manual-mode sell pricing must resolve from local state alone.
 *
 * Prod (#1133): with Auto Mode off, the sell focus was resolved only from the backend
 * active-flips list, which is trimmed to the subscription's display slots (2 on free).
 * A free user's held position could be absent from that list entirely, so clicking the
 * item to sell it back populated no price at all. Selling what you already own must not
 * depend on a display cap, so every price source used here is local.
 */
public class ManualSellFocusTest
{
	@Test
	public void prefersThePanelDisplayedPrice()
	{
		assertEquals(Long.valueOf(120), ManualSellFocus.resolveSellPrice(120L, 110L, 100));
	}

	@Test
	public void fallsBackToTheSessionRecommendedPriceWhenThePanelHasNone()
	{
		assertEquals(Long.valueOf(110), ManualSellFocus.resolveSellPrice(null, 110L, 100));
	}

	@Test
	public void fallsBackToMinProfitableWhenOnlyTheLocalBuyBasisIsKnown()
	{
		// The free-tier regression: no backend flip, no cached price — the buy basis in
		// the offer store is enough to price the exit.
		assertEquals(
			Long.valueOf(SmartSellPricer.calculateMinProfitableSellPrice(100)),
			ManualSellFocus.resolveSellPrice(null, null, 100));
	}

	@Test
	public void treatsNonPositivePricesAsAbsent()
	{
		assertEquals(Long.valueOf(110), ManualSellFocus.resolveSellPrice(0L, 110L, 100));
		assertEquals(
			Long.valueOf(SmartSellPricer.calculateMinProfitableSellPrice(100)),
			ManualSellFocus.resolveSellPrice(-1L, 0L, 100));
	}

	@Test
	public void unresolvableWithoutAnyPriceOrBuyBasis()
	{
		assertNull(ManualSellFocus.resolveSellPrice(null, null, 0));
	}

	@Test
	public void neverPricesBelowBreakevenWhenFallingBackToBasis()
	{
		// A basis-derived price must clear the 2% GE tax, else the "fix" would hand the
		// player a guaranteed loss instead of no price at all.
		int basis = 1_000_000;
		Long resolved = ManualSellFocus.resolveSellPrice(null, null, basis);
		assertEquals(true, resolved != null && resolved * 0.98 > basis);
	}
}

package com.flipsmart.recommend;

import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Covers the 5-minute skip window used by Flip Assist (#919): a skipped item is held
 * out of auto-surfacing for {@link SkipCooldownTracker#COOLDOWN_MS}, the window expires
 * lazily, an auto-mode toggle clears every window, and distinct items are independent.
 */
public class SkipCooldownTrackerTest
{
	private static final int ITEM = 4151;
	private static final int OTHER_ITEM = 561;

	private long now;
	private SkipCooldownTracker tracker;

	@Before
	public void setUp()
	{
		now = 1_000_000L;
		tracker = new SkipCooldownTracker(() -> now);
	}

	/** AC1/AC6: a freshly skipped item is inside its window. */
	@Test
	public void skippedItemIsCoolingDown()
	{
		tracker.skip(ITEM);

		assertTrue(tracker.isCoolingDown(ITEM));
	}

	/** An item that was never skipped is not cooling down. */
	@Test
	public void unseenItemIsNotCoolingDown()
	{
		assertFalse(tracker.isCoolingDown(ITEM));
	}

	/** The window holds right up to the 5-minute boundary. */
	@Test
	public void stillCoolingJustBeforeExpiry()
	{
		tracker.skip(ITEM);

		now += SkipCooldownTracker.COOLDOWN_MS - 1;

		assertTrue(tracker.isCoolingDown(ITEM));
	}

	/** At/after the boundary the item is eligible again. */
	@Test
	public void expiresAtBoundary()
	{
		tracker.skip(ITEM);

		now += SkipCooldownTracker.COOLDOWN_MS;

		assertFalse(tracker.isCoolingDown(ITEM));
	}

	/** Acting on a skipped item clears only that item's window. */
	@Test
	public void clearReleasesOnlyTheGivenItem()
	{
		tracker.skip(ITEM);
		tracker.skip(OTHER_ITEM);

		tracker.clear(ITEM);

		assertFalse(tracker.isCoolingDown(ITEM));
		assertTrue(tracker.isCoolingDown(OTHER_ITEM));
	}

	/** AC5/AC6: toggling auto-mode clears every window. */
	@Test
	public void clearAllReleasesEveryItem()
	{
		tracker.skip(ITEM);
		tracker.skip(OTHER_ITEM);

		tracker.clearAll();

		assertFalse(tracker.isCoolingDown(ITEM));
		assertFalse(tracker.isCoolingDown(OTHER_ITEM));
	}

	/** Skipping one item does not suppress another. */
	@Test
	public void distinctItemsAreIndependent()
	{
		tracker.skip(ITEM);

		assertTrue(tracker.isCoolingDown(ITEM));
		assertFalse(tracker.isCoolingDown(OTHER_ITEM));
	}

	/** Re-skipping refreshes the window from the new skip instant. */
	@Test
	public void reSkipExtendsWindow()
	{
		tracker.skip(ITEM);

		now += SkipCooldownTracker.COOLDOWN_MS - 1_000;
		tracker.skip(ITEM);
		now += 2_000;

		// Would have expired under the first skip; the second skip keeps it cooling.
		assertTrue(tracker.isCoolingDown(ITEM));
	}

	/** pruneExpired drops elapsed windows and keeps live ones. */
	@Test
	public void pruneExpiredDropsOnlyElapsedWindows()
	{
		tracker.skip(ITEM);
		now += SkipCooldownTracker.COOLDOWN_MS - 1_000;
		tracker.skip(OTHER_ITEM);

		now += 2_000; // ITEM elapsed, OTHER_ITEM still live
		tracker.pruneExpired();

		assertFalse(tracker.isCoolingDown(ITEM));
		assertTrue(tracker.isCoolingDown(OTHER_ITEM));
	}
}

package com.flipsmart.recommend;

import com.flipsmart.domain.offer.OfferRecord;
import com.flipsmart.domain.offer.OfferState;
import org.junit.Test;

import java.util.Collections;

import static org.junit.Assert.assertEquals;

public class ActionResolverBuysSuppressedTest
{
	private final ActionResolver resolver = new ActionResolver();

	@Test
	public void suppressedBuysFallThroughToCollect()
	{
		OfferRecord completedSell = OfferRecord.newOffer(1L, 0, 561, "x", false, 10, 100, 1L)
			.withFill(10, 0L, OfferState.FILLED, 2L); // completed sell awaiting collection (S5)
		ResolverInput in = ResolverInput.builder()
			.slotLimit(8)
			.filledSlotCount(1)
			.surfaceableBuy(true, 999) // a buy is available...
			.nowMillis(100L)
			.buysSuppressed(true)      // ...but sell-only mode suppresses it
			.completedAwaitingCollection(Collections.singletonList(completedSell))
			.build();

		ActionDecision d = resolver.resolve(in);
		assertEquals(ActionStep.COLLECT, d.getStep()); // not PLACE_BUY
		assertEquals(561, d.getItemId());
	}

	@Test
	public void unsuppressedBuyIsChosenWhenSoleCandidate()
	{
		ResolverInput in = ResolverInput.builder()
			.slotLimit(8)
			.filledSlotCount(1)
			.surfaceableBuy(true, 999)
			.nowMillis(100L)
			.buysSuppressed(false)
			.build();

		assertEquals(ActionStep.PLACE_BUY, resolver.resolve(in).getStep());
	}
}

package com.flipsmart;

import com.flipsmart.api.dto.Dtos.WikiPrice;
import java.lang.reflect.Field;
import net.runelite.api.Client;
import net.runelite.client.game.ItemManager;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Which price a verdict is measured against matters more than how fresh it is. The wiki pair
 * answers buys against insta-sell and sells against insta-buy; the guide price is one blended
 * number that answers neither, so falling back to it can reverse the verdict on an offer that
 * has not changed. That reversal, arriving once a cache lifetime, is what reached players as a
 * flashing border.
 */
public class CompetitivenessPriceBasisTest
{
    private static final int WHIP = 4151;
    private static final int INSTA_BUY = 2_000_000;
    private static final int INSTA_SELL = 1_800_000;
    // Sits between the two: competitive to buy against the pair, uncompetitive against the blend.
    private static final int OFFER_PRICE = 1_850_000;
    private static final int GUIDE_PRICE = 1_900_000;

    private FlipSmartPlugin plugin;
    private FlipSmartApiClient apiClient;
    private ItemManager itemManager;

    @Before
    public void setUp() throws Exception
    {
        plugin = new FlipSmartPlugin();
        apiClient = mock(FlipSmartApiClient.class);
        itemManager = mock(ItemManager.class);
        Client client = mock(Client.class);
        when(client.isClientThread()).thenReturn(true);
        when(itemManager.getItemPrice(WHIP)).thenAnswer(GpAnswer.gp(GUIDE_PRICE));

        inject("apiClient", apiClient);
        inject("itemManager", itemManager);
        inject("client", client);
    }

    private void inject(String field, Object value) throws Exception
    {
        Field f = FlipSmartPlugin.class.getDeclaredField(field);
        f.setAccessible(true);
        f.set(plugin, value);
    }

    @Test
    public void anAgedOutPair_isPreferredOverTheGuidePrice()
    {
        when(apiClient.getLastKnownWikiPrice(WHIP)).thenReturn(new WikiPrice(INSTA_BUY, INSTA_SELL));

        assertEquals(FlipSmartPlugin.OfferCompetitiveness.COMPETITIVE,
            plugin.calculateCompetitiveness(WHIP, OFFER_PRICE, true));
        verify(itemManager, never()).getItemPrice(anyInt());
    }

    @Test
    public void theGuidePriceIsStillUsedWhenNoPairWasEverHeld()
    {
        when(apiClient.getLastKnownWikiPrice(WHIP)).thenReturn(null);

        assertEquals(FlipSmartPlugin.OfferCompetitiveness.UNCOMPETITIVE,
            plugin.calculateCompetitiveness(WHIP, OFFER_PRICE, true));
    }
}

package com.flipsmart;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Covers the sell-offer description math, in particular that the GE tax-exempt
 * item list is honoured on the offer-setup screen (issue #904 AC2). A previous
 * version used the item-less {@link com.flipsmart.util.GeTax} overloads here,
 * so exempt-list items (bonds, darts, arrows, cooked food, …) were shown with
 * tax and an under-stated profit.
 */
public class GeOfferDescriptionFormatterTest
{
	private static final int ABYSSAL_WHIP_ID = 4151;       // taxable
	private static final int OLD_SCHOOL_BOND_ID = 13190;   // tax-exempt list

	@Test
	public void taxableItemAppliesTaxToBreakevenAndProfit()
	{
		// Buy 100, sell 200, qty 1: tax = floor(200 * 0.02) = 4/item.
		String out = GeOfferDescriptionFormatter.formatSellDescription(
			ABYSSAL_WHIP_ID, 100L, 200, 1);

		assertTrue("taxable item should show non-zero tax", out.contains("Tax applied: </col>4 gp"));
		// Breakeven must sit above the buy price to cover tax.
		long breakeven = GeOfferDescriptionFormatter.calculateBreakevenPrice(ABYSSAL_WHIP_ID, 100);
		assertTrue("taxable breakeven should exceed buy price", breakeven > 100);
		// Profit = 200 - 100 - 4 = 96 (post-tax).
		assertTrue("taxable profit is post-tax", out.contains("+96 gp"));
	}

	// ---------------------------------------------------------------------
	// Buy-limit cooldown line (#1115)
	// ---------------------------------------------------------------------

	private static final long MINUTE_MS = 60_000L;
	private static final long HOUR_MS = 60 * MINUTE_MS;

	@Test
	public void buyDescriptionShowsCooldownWhenTheItemWasBoughtInsideTheWindow()
	{
		String out = GeOfferDescriptionFormatter.formatBuyDescription(
			1000, 15, 500_000L, 3 * HOUR_MS + 42 * MINUTE_MS);

		assertTrue("cooldown line should render H:mm remaining",
			out.contains("Limit resets in: </col><col=ffffff>3:42</col>"));
		// AC2 — the cooldown sits underneath the buy limit and wiki insta-buy lines.
		assertTrue("cooldown must be the last line",
			out.indexOf("Limit resets in") > out.indexOf("Wiki insta-buy"));
		assertTrue("wiki insta-buy must still follow the buy limit",
			out.indexOf("Wiki insta-buy") > out.indexOf("Buy limit"));
	}

	@Test
	public void buyDescriptionOmitsCooldownWhenNothingWasBoughtInTheWindow()
	{
		// AC5 — no purchase inside 4h means the caller passes null and no line renders.
		String out = GeOfferDescriptionFormatter.formatBuyDescription(1000, 15, 500_000L, null);

		assertTrue("no cooldown line without a recorded purchase",
			!out.contains("Limit resets in"));
		assertTrue("the other lines are unaffected", out.contains("Buy limit"));
	}

	@Test
	public void buyDescriptionOmitsCooldownOnceTheWindowHasElapsed()
	{
		// A stale/expired reset time must not render "0:00" or a negative duration.
		assertTrue("elapsed window renders nothing",
			!GeOfferDescriptionFormatter.formatBuyDescription(1000, 15, 500_000L, 0L)
				.contains("Limit resets in"));
		assertTrue("negative remaining renders nothing",
			!GeOfferDescriptionFormatter.formatBuyDescription(1000, 15, 500_000L, -5_000L)
				.contains("Limit resets in"));
	}

	@Test
	public void cooldownMinutesAreZeroPaddedAndTruncatedNotRounded()
	{
		// Matches DurationFormatUtils "H:mm": 1h05m, and 59s of a minute is dropped.
		assertEquals("<col=ffb83f>Limit resets in: </col><col=ffffff>1:05</col>",
			GeOfferDescriptionFormatter.formatLimitResetLine(HOUR_MS + 5 * MINUTE_MS + 59_000L));
		assertEquals("sub-minute remainder truncates to 0:00",
			"<col=ffb83f>Limit resets in: </col><col=ffffff>0:00</col>",
			GeOfferDescriptionFormatter.formatLimitResetLine(30_000L));
	}

	@Test
	public void exemptListItemShowsNoTaxAndPreTaxProfit()
	{
		// Old school bond is on the exempt list; at any price it is never taxed.
		String out = GeOfferDescriptionFormatter.formatSellDescription(
			OLD_SCHOOL_BOND_ID, 8_000_000L, 8_100_000, 1);

		assertEquals("exempt-list item is never taxed",
			0, GeOfferDescriptionFormatter.calculateTaxPerItem(OLD_SCHOOL_BOND_ID, 8_100_000));
		assertTrue("tax line reads zero for exempt item", out.contains("Tax applied: </col>0 gp"));
		// Breakeven for an exempt item is simply the buy price (no tax to cover).
		assertEquals(8_000_000,
			GeOfferDescriptionFormatter.calculateBreakevenPrice(OLD_SCHOOL_BOND_ID, 8_000_000));
		// Profit is the raw margin: 8,100,000 - 8,000,000 = 100,000 (pre-tax).
		assertTrue("exempt profit is pre-tax margin", out.contains("+100,000 gp"));
	}
}

