	@Test
	public void parsesBillionsShorthand()
	{
		assertEquals(OptionalInt.of(1_000_000_000), GpUtils.parseGp("1b"));
	}

	@Test
	public void stripsCommaSeparators()
	{
		assertEquals(OptionalInt.of(10_000_000), GpUtils.parseGp("10,000,000"));
