import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.timeout;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class TradeStationSlotPushServiceTest
{
	private static final int ABYSSAL_WHIP = 4151;
	private static final int DRAGON_LONGSWORD = 1305;
	private static final String RSN = "TestPlayer";

	private Client client;
	private FlipSmartApiClient apiClient;
	private PlayerSession session;
	private TradeStationSlotPushService service;

	@Before
	public void setUp()
	{
		client = mock(Client.class);
		apiClient = mock(FlipSmartApiClient.class);
		session = mock(PlayerSession.class);
		when(session.getRsnSafe()).thenReturn(Optional.of(RSN));
		when(apiClient.pushTradeStationSlotsAsync(any(), any()))
			.thenReturn(CompletableFuture.completedFuture(true));
		service = new TradeStationSlotPushService(client, apiClient, session);
	}

	/**
	 * The service is a singleton and RuneLite reuses the plugin instance across disable/enable, so a
	 * scheduler terminated by shutdown() used to stay terminated for the life of the client. Every
	 * GE offer event after a plugin toggle then threw RejectedExecutionException out of the event
	 * subscriber. Observed in-game on 2026-08-02.
	 */
	@Test
	public void scheduleAfterShutdownRebuildsTheExecutorInsteadOfThrowing()
	{
		service.shutdown();

		// Previously threw RejectedExecutionException from the terminated executor.
		service.scheduleSnapshotPush(java.util.Collections.singletonList(ABYSSAL_WHIP));

		// The debounced task must actually run on the rebuilt executor, not merely be accepted.
		verify(apiClient, timeout(5000).times(1))
			.pushTradeStationSlotsAsync(eq(RSN), eq(java.util.Collections.singletonList(ABYSSAL_WHIP)));
	}

	@Test
	public void pushNowAfterShutdownRebuildsTheExecutorInsteadOfThrowing()
	{
		service.shutdown();

		service.pushNow(java.util.Collections.singletonList(ABYSSAL_WHIP));

		verify(apiClient, timeout(2000).times(1))
			.pushTradeStationSlotsAsync(eq(RSN), eq(java.util.Collections.singletonList(ABYSSAL_WHIP)));
	}

	@Test
	public void readCurrentSlotIdsDedupesAndSkipsEmpty()
	{
		GrandExchangeOffer o1 = offer(ABYSSAL_WHIP, GrandExchangeOfferState.BUYING);
		GrandExchangeOffer o2 = offer(0, GrandExchangeOfferState.EMPTY);
		GrandExchangeOffer o3 = offer(ABYSSAL_WHIP, GrandExchangeOfferState.SELLING);
		GrandExchangeOffer o4 = offer(DRAGON_LONGSWORD, GrandExchangeOfferState.BOUGHT);
		GrandExchangeOffer[] offers = { o1, o2, o3, o4, null };
		when(client.getGrandExchangeOffers()).thenReturn(offers);

		List<Integer> ids = service.readCurrentSlotIds();
		assertEquals(2, ids.size());
		assertEquals(Integer.valueOf(ABYSSAL_WHIP), ids.get(0));
		assertEquals(Integer.valueOf(DRAGON_LONGSWORD), ids.get(1));
	}

	@Test
	public void pushNowSendsItemsToApiClient() throws Exception
	{
		service.pushNow(List.of(ABYSSAL_WHIP, DRAGON_LONGSWORD));
		// Single-threaded executor — block until queued task finishes.
		Thread.sleep(50);
		verify(apiClient, times(1)).pushTradeStationSlotsAsync(eq(RSN),
			eq(List.of(ABYSSAL_WHIP, DRAGON_LONGSWORD)));
	}

	@Test
	public void duplicateSnapshotsAreSkipped() throws Exception
	{
		service.pushNow(List.of(ABYSSAL_WHIP));
		Thread.sleep(50);
		service.pushNow(List.of(ABYSSAL_WHIP));
		Thread.sleep(50);
		// Second push has the same snapshot so the service should short-circuit.
		verify(apiClient, times(1)).pushTradeStationSlotsAsync(any(), any());
	}

	@Test
	public void noPushWhenRsnUnavailable() throws Exception
	{
		when(session.getRsnSafe()).thenReturn(Optional.empty());
		service.pushNow(List.of(ABYSSAL_WHIP));
		Thread.sleep(50);
		verify(apiClient, never()).pushTradeStationSlotsAsync(any(), any());
	}

	@Test
	public void readReturnsEmptyListWhenClientHasNoOffers()
	{
		when(client.getGrandExchangeOffers()).thenReturn(null);
		assertTrue(service.readCurrentSlotIds().isEmpty());
	}

	private static GrandExchangeOffer offer(int itemId, GrandExchangeOfferState state)
	{
		GrandExchangeOffer o = mock(GrandExchangeOffer.class);
		when(o.getItemId()).thenReturn(itemId);
		when(o.getState()).thenReturn(state);
		return o;
	}
}

package com.flipsmart;
import com.flipsmart.api.dto.Dtos.OfferAdviceRequest;

import com.google.gson.JsonObject;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class OfferActionBodyTest
{
	@Test
	public void includesRequiredFieldsAndOmitsNulls()
	{
		OfferAdviceRequest req = OfferAdviceRequest.builder()
			.itemId(12345)
			.pool("high_vol")
			.side("sell")
			.stage("initial")
			.listedAtMillis(1781035200000L)
			.listedPrice(1000)
			.listedQuantity(10)
			.filledQuantity(0)
			.currentMarketHigh(1080L)
			.currentMarketLow(1020L)
			.userAvgBuyPrice(990L)
			.build();

		JsonObject body = FlipSmartApiClient.buildOfferActionBody(req);

		assertEquals(12345, body.get("item_id").getAsInt());
		assertEquals("high_vol", body.get("pool").getAsString());
		assertEquals("sell", body.get("side").getAsString());
		assertEquals("initial", body.get("stage").getAsString());
		assertEquals("2026-06-09T20:00:00Z", body.get("listed_at").getAsString());
		assertEquals(1000, body.get("listed_price").getAsInt());
		assertEquals(10, body.get("listed_quantity").getAsInt());
		assertEquals(0, body.get("filled_quantity").getAsInt());
		assertEquals(1080, body.get("current_market_high").getAsInt());
		assertEquals(1020, body.get("current_market_low").getAsInt());
		assertEquals(990, body.get("user_avg_buy_price").getAsInt());
		assertFalse("null last_fill omitted", body.has("last_fill_at"));
	}

	private OfferAdviceRequest.OfferAdviceRequestBuilder createBaseRequestBuilder()
	{
		return OfferAdviceRequest.builder()
			.itemId(1).pool("mid_vol").side("buy").stage("initial")
			.listedAtMillis(1781035200000L).listedPrice(5).listedQuantity(1).filledQuantity(0);
	}

	@Test
	public void omitsNullMarketAndBuyPrice()
	{
		OfferAdviceRequest req = createBaseRequestBuilder().build();
		JsonObject body = FlipSmartApiClient.buildOfferActionBody(req);
		assertFalse(body.has("current_market_high"));
		assertFalse(body.has("current_market_low"));
		assertFalse(body.has("user_avg_buy_price"));
		assertTrue(body.has("item_id"));
	}

	@Test
	public void includesCourierStateFields()
	{
		OfferAdviceRequest req = OfferAdviceRequest.builder()
			.itemId(4151).pool("mid_vol").side("buy").stage("initial")
			.listedAtMillis(1781035200000L).listedPrice(100000).listedQuantity(10).filledQuantity(5)
			.originalMargin(10000L).previousPositionMargin(9000L)
			.consecutiveMarginDecreases(1).cumulativeMarginReductionPct(0.1)
			.build();
		JsonObject body = FlipSmartApiClient.buildOfferActionBody(req);
		assertEquals(10000, body.get("original_margin").getAsInt());
		assertEquals(9000, body.get("previous_position_margin").getAsInt());
		assertEquals(1, body.get("consecutive_margin_decreases").getAsInt());
		assertEquals(0.1, body.get("cumulative_margin_reduction_pct").getAsDouble(), 1e-9);
	}

	@Test
	public void omitsNullCourierMarginsButKeepsCounters()
	{
		OfferAdviceRequest req = createBaseRequestBuilder().build();
		JsonObject body = FlipSmartApiClient.buildOfferActionBody(req);
		assertFalse(body.has("original_margin"));
		assertFalse(body.has("previous_position_margin"));
		assertEquals(0, body.get("consecutive_margin_decreases").getAsInt());
		assertEquals(0.0, body.get("cumulative_margin_reduction_pct").getAsDouble(), 1e-9);
	}
}

package com.flipsmart;

import com.flipsmart.domain.flip.FlipRecommendation;
import com.flipsmart.trading.OfferStore;
import java.util.Arrays;
import java.util.HashSet;
import java.util.concurrent.atomic.AtomicReference;
import javax.swing.SwingUtilities;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.mockito.Mockito.when;

/**
 * Pins the tri-state contract of {@link AutoRecommendService#overrideFocusForSell}
 * introduced with the stale re-sell focus fix (#156). The caller's tick-retry
 * logic depends on the distinction between {@code UNAVAILABLE} (state not settled,
 * retry later) and the terminal {@code ALREADY_SELLING}/{@code FOCUSED} outcomes,
 * so each branch is covered here.
 *
 * <p>{@code ALREADY_SELLING} and the reprice/known-price {@code FOCUSED} paths are
 * already pinned in {@link AutoRecommendDispatchTest}; this class fills the
 * {@code UNAVAILABLE} branches and the clean resolve-and-fire-callback path.
 */
public class OverrideFocusForSellTest
{
	@Mock private FlipSmartConfig config;
	@Mock private FlipSmartPlugin plugin;
	@Mock private FlipSmartApiClient apiClient;
	private OfferStore offerStore;
	private AutoRecommendService service;
	private PlayerSession session;

	private static FlipRecommendation rec(int itemId)
	{
		FlipRecommendation r = new FlipRecommendation();
		r.setItemId(itemId);
		r.setItemName("item-" + itemId);
		r.setRecommendedBuyPrice(100);
		r.setRecommendedSellPrice(200);
		r.setRecommendedQuantity(10);
		return r;
	}

	@Before
	public void setUp()
	{
		MockitoAnnotations.openMocks(this);
		offerStore = new OfferStore();
		session = new PlayerSession();
		when(plugin.getSession()).thenReturn(session);
		when(plugin.getFlipSlotLimit()).thenReturn(8);
		when(plugin.getActiveFlipItemIds()).thenReturn(new HashSet<>());
		when(plugin.getApiClient()).thenReturn(apiClient);
		when(apiClient.isRsnBlocked()).thenReturn(false);
		when(config.priceOffset()).thenReturn(0);
		when(config.minimumProfit()).thenReturn(1);
		when(plugin.isClientThread()).thenReturn(true);
		service = new AutoRecommendService(config, plugin, offerStore);
		service.start(Arrays.asList(rec(21)));
	}

	@Test
	public void inactiveServiceReturnsUnavailable()
	{
		service.stop();
		assertEquals(AutoRecommendService.SellFocusResult.UNAVAILABLE,
			service.overrideFocusForSell(21, "item-21"));
	}

	@Test
	public void nullSessionReturnsUnavailable()
	{
		when(plugin.getSession()).thenReturn(null);
		assertEquals(AutoRecommendService.SellFocusResult.UNAVAILABLE,
			service.overrideFocusForSell(21, "item-21"));
	}

	@Test
	public void unresolvablePriceReturnsUnavailable()
	{
		// Item 999 is not in the queue and has no session/advisor price, so no sell price
		// can be resolved yet → caller should retry on a later tick.
		assertEquals(AutoRecommendService.SellFocusResult.UNAVAILABLE,
			service.overrideFocusForSell(999, "item-999"));
	}

	@Test
	public void knownPriceButZeroQuantityReturnsUnavailable()
	{
		// Price resolvable from session, but nothing in inventory / collected and no rec to
		// supply a fallback quantity → quantity unsettled → UNAVAILABLE.
		session.setRecommendedPrice(888, 150);
		when(plugin.getInventoryCountForItem(888)).thenReturn(0);
		assertEquals(AutoRecommendService.SellFocusResult.UNAVAILABLE,
			service.overrideFocusForSell(888, "item-888"));
	}

	@Test
	public void resolvedPriceAndQuantityReturnsFocusedAndFiresCallback() throws Exception
	{
		session.setRecommendedPrice(888, 150);
		when(plugin.getInventoryCountForItem(888)).thenReturn(5);

		AtomicReference<FocusedFlip> painted = new AtomicReference<>();
		service.setOnFocusChanged(painted::set);

		AutoRecommendService.SellFocusResult result = service.overrideFocusForSell(888, "item-888");
		SwingUtilities.invokeAndWait(() -> { });

		assertEquals(AutoRecommendService.SellFocusResult.FOCUSED, result);
		assertNotNull("resolve must fire the focus callback", painted.get());
		assertEquals(888, painted.get().getItemId());
		assertEquals("focus must carry the resolved sell price", 150, painted.get().getCurrentStepPrice());
	}
}

package com.flipsmart;

import com.flipsmart.domain.offer.OfferRecord;
import com.flipsmart.trading.OfferStore;

import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.Collections;
import java.util.Set;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * #1116 AC1/AC3: collecting part of a buy and relisting it to sell before the buy finishes puts
 * one recommended item on two GE slots at once. That pair must consume one of a free user's flip
 * slots, not two.
 *
 * <p>The collapse happens in {@link FlipSmartPlugin#getActiveFlipItemIds()}, which folds every
 * live offer into a set keyed by item id. Asserting it against {@code ActiveFlipItemIds.derive}
 * in isolation proves nothing — that method's caller has already deduplicated, so the two legs
 * have to enter as two separate offers for the assertion to carry any weight.</p>
 */
public class OverlappingBuyAndSellCountTest
{
	private static final int RUNE_SCIMITAR = 4151;
	private static final long T0 = 1_000_000L;

	// Mirrors PlayerSession.FLIP_FINDER_SOURCED_GRACE_MS. Counting past the grace window is what
	// makes the count assertion meaningful: within grace a marked item counts whether or not it
	// is actually active, so the collapse would go unmeasured.
	private static final long PAST_GRACE = T0 + 8001;

	private static void inject(FlipSmartPlugin plugin, String field, Object value) throws Exception
	{
		Field declared = FlipSmartPlugin.class.getDeclaredField(field);
		declared.setAccessible(true);
		declared.set(plugin, value);
	}

	private static OfferRecord legOn(int itemId)
	{
		OfferRecord leg = mock(OfferRecord.class);
		when(leg.getItemId()).thenReturn(itemId);
		return leg;
	}

	@Test
	public void anEarlyResaleOfARecommendedItemCountsOnceNotTwice() throws Exception
	{
		// Two live offers, one item: the buy still working, and the sell of the part collected.
		// Built before the store is stubbed — stubbing a mock inside an open when() is an error.
		OfferRecord buyLeg = legOn(RUNE_SCIMITAR);
		OfferRecord sellLeg = legOn(RUNE_SCIMITAR);

		OfferStore offerStore = mock(OfferStore.class);
		when(offerStore.liveOffers()).thenReturn(Arrays.asList(buyLeg, sellLeg));

		PlayerSession session = new PlayerSession();
		session.markFlipFinderSourced(RUNE_SCIMITAR, T0);

		FlipSmartPlugin plugin = new FlipSmartPlugin();
		inject(plugin, "offerStore", offerStore);
		inject(plugin, "session", session);
		inject(plugin, "inventoryFlipItemCounts", Collections.singletonMap(RUNE_SCIMITAR, 5));
		inject(plugin, "inventorySnapshotKnown", true);

		Set<Integer> active = plugin.getActiveFlipItemIds();

		assertEquals("two legs of one item are one active flip", 1, active.size());
		assertEquals("the free-tier counter charges the item once", 1,
			session.retainAndCountFlipFinderActive(active, PAST_GRACE));
	}

	@Test
	public void twoDifferentRecommendedItemsStillCountSeparately() throws Exception
	{
		final int ABYSSAL_WHIP = 4151 + 1;
		OfferRecord scimitarLeg = legOn(RUNE_SCIMITAR);
		OfferRecord whipLeg = legOn(ABYSSAL_WHIP);

		OfferStore offerStore = mock(OfferStore.class);
		when(offerStore.liveOffers()).thenReturn(Arrays.asList(scimitarLeg, whipLeg));

		PlayerSession session = new PlayerSession();
		session.markFlipFinderSourced(RUNE_SCIMITAR, T0);
		session.markFlipFinderSourced(ABYSSAL_WHIP, T0);

		FlipSmartPlugin plugin = new FlipSmartPlugin();
		inject(plugin, "offerStore", offerStore);
		inject(plugin, "session", session);
		inject(plugin, "inventoryFlipItemCounts", Collections.emptyMap());
		inject(plugin, "inventorySnapshotKnown", true);

		Set<Integer> active = plugin.getActiveFlipItemIds();

		assertEquals("distinct items are distinct flips", 2, active.size());
		assertEquals(2, session.retainAndCountFlipFinderActive(active, PAST_GRACE));
	}
}

package com.flipsmart;

import com.flipsmart.domain.offer.OfferRecord;
import com.flipsmart.trading.OfferStore;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.chat.ChatMessageManager;
import org.junit.Test;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Optional;
import java.util.concurrent.CompletableFuture;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyList;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Unit tests for {@link GEHistoryService}'s widget-text parsing helpers.
 * <p>
 * The package-private {@code parsePerItemPriceFromText} and
 * {@code parseLeadingTotalFromText} entry points let us exercise the
 * parsing logic against raw widget-text shapes without mocking the
 * RuneLite {@code Widget} object.
 * <p>
 * The regression case under {@link #parseEachWidgetMissingSeparatorYieldsTrailingQuantity}
 * locks in the fix for Flip-Smart/flip-smart#689: pre-fix, widget text of
 * the shape {@code "<col=ffb83f>1,149 each</col>"} produced 831,149 because
 * the parser sliced from the {@code '='} inside the color attribute and
 * the orphaned {@code "ffb83f>"} fragment leaked its hex digits into the
 * digit-greedy parse. Stripping HTML tags first removes that failure mode.
 */
public class GEHistoryServiceTest
{
	// Standard yellow GE text color in OSRS interfaces; the hex digits
	// "83" here are the ones that previously bled into the parsed price.
	private static final String GE_YELLOW = "<col=ffb83f>";

	// ----- parsePerItemPriceFromText ----------------------------------

	@Test
	public void parseWellFormedPriceTextReturnsPerItemValue()
	{
		// The shape RuneLite emits for multi-quantity rows: a coins total
		// inside a color span, a <br>, then "= N each" with the per-item
		// price after the '=' sign.
		String text = GE_YELLOW + "1,571,832 coins</col><br>= 1,341 each";
		assertEquals(1341, GEHistoryService.parsePerItemPriceFromText(text));
	}

	@Test
	public void parseEachWidgetMissingSeparatorYieldsTrailingQuantity()
	{
		// REGRESSION GUARD for Flip-Smart/flip-smart#689.
		// When the matched "each" widget contains only the trailing
		// quantity inside a color tag (no plain-text '=' separator),
		// the parser must NOT leak the "83" hex digits out of the
		// color attribute into the parsed number. Pre-fix this
		// returned 831_149; the fix returns 1_149.
		String text = GE_YELLOW + "1,149 each</col>";
		assertEquals(1149, GEHistoryService.parsePerItemPriceFromText(text));
	}

	@Test
	public void parseProductionCorruptionShapeForBonesToPeaches()
	{
		// Synthetic reproduction of the exact prod corruption — a
		// 1,341 gp/unit Bones-to-peaches sell that was filed as
		// 831,149 gp/unit. Confirms the fix produces 1,341 regardless
		// of whether the widget text wraps the per-item value alone.
		String text = GE_YELLOW + "1,341 each</col>";
		assertEquals(1341, GEHistoryService.parsePerItemPriceFromText(text));
	}

	@Test
	public void parseHandlesNestedColorSpans()
	{
		// Defensive: a row whose total and "= each" segments live in
		// two separate color spans must still resolve to the per-item
		// value after the last '=' in the cleaned text.
		String text = GE_YELLOW + "1,571,832 coins</col><br>"
			+ "<col=ff981f>= 1,341 each</col>";
		assertEquals(1341, GEHistoryService.parsePerItemPriceFromText(text));
	}

	@Test
	public void parseEmptyOrNullPriceTextReturnsMinusOne()
	{
		assertEquals(-1, GEHistoryService.parsePerItemPriceFromText(null));
		assertEquals(-1, GEHistoryService.parsePerItemPriceFromText(""));
	}

	// ----- parseLeadingTotalFromText (qty=1 fallback path) ------------

	@Test
	public void parseLeadingTotalIgnoresParenthesizedTaxBreakdown()
	{
		// Used for qty=1 history rows where the per-item price equals
		// the displayed total. The parenthesized tax detail must NOT
		// be concatenated into the parse.
		String text = GE_YELLOW + "1,540,809 coins (1,571,832 - 31,023)</col>";
		assertEquals(1_540_809, GEHistoryService.parseLeadingTotalFromText(text));
	}

	@Test
	public void parseLeadingTotalHandlesNoParenthesizedTail()
	{
		// Many qty=1 rows don't render a tax breakdown at all.
		String text = GE_YELLOW + "2,500,000 coins</col>";
		assertEquals(2_500_000, GEHistoryService.parseLeadingTotalFromText(text));
	}

	@Test
	public void parseLeadingTotalEmptyOrNullReturnsMinusOne()
	{
		assertEquals(-1, GEHistoryService.parseLeadingTotalFromText(null));
		assertEquals(-1, GEHistoryService.parseLeadingTotalFromText(""));
	}

	// ----- matchOfferId (#759 offer_id linkage) -----------------------

	private static OfferRecord offer(long offerId, int itemId, boolean buy, int total, int price)
	{
		return OfferRecord.newOffer(offerId, 0, itemId, "i" + itemId, buy, total, price, 1L);
	}

	@Test
	public void matchOfferId_uniqueMatchReturnsOfferId()
	{
		List<OfferRecord> candidates = Arrays.asList(
			offer(42, 28924, false, 30000, 384),
			offer(7, 4151, true, 5, 2_000_000));
		assertEquals(Long.valueOf(42), GEHistoryService.matchOfferId(candidates, 28924, false, 384));
	}

	@Test
	public void matchOfferId_ambiguousSameItemDirectionPriceReturnsNull()
	{
		List<OfferRecord> candidates = Arrays.asList(
			offer(42, 28924, false, 30000, 384),
			offer(43, 28924, false, 20000, 384));
		assertNull(GEHistoryService.matchOfferId(candidates, 28924, false, 384));
	}

	@Test
	public void matchOfferId_noMatchOnPriceOrDirectionReturnsNull()
	{
		List<OfferRecord> candidates = Collections.singletonList(offer(42, 28924, false, 30000, 384));
		assertNull(GEHistoryService.matchOfferId(candidates, 28924, false, 999));
		assertNull(GEHistoryService.matchOfferId(candidates, 28924, true, 384));
	}

	@Test
	public void matchOfferId_sameOfferAcrossCollectionsIsNotAmbiguous()
	{
		OfferRecord same = offer(42, 28924, false, 30000, 384);
		assertEquals(Long.valueOf(42), GEHistoryService.matchOfferId(Arrays.asList(same, same), 28924, false, 384));
	}

	/**
	 * GE History reports the NET price on a sell; the offer holds the LISTED price. Matching the
	 * two directly means a taxed sell can never resolve its offer, so every sell row falls through
	 * to the backend's item-level path where distinct orders share one key. Measured on the dev
	 * DB before this fix: 351 of 351 sell backfill rows had a null offer_id (buys, untaxed, 85%).
	 */
	@Test
	public void matchOfferId_sellMatchesOnTheNetPriceHistoryActuallyReports()
	{
		// Steel cannonball listed at 290; 2% tax floors to 5, so History shows 285.
		List<OfferRecord> candidates = Collections.singletonList(offer(42, 2, false, 11000, 290));
		assertEquals(Long.valueOf(42), GEHistoryService.matchOfferId(candidates, 2, false, 285));
	}

	/** The listed price must keep matching — tax-exempt items report it unchanged. */
	@Test
	public void matchOfferId_sellStillMatchesOnTheListedPriceWhenUntaxed()
	{
		List<OfferRecord> candidates = Collections.singletonList(offer(42, 2, false, 100, 40));
		assertEquals(Long.valueOf(42), GEHistoryService.matchOfferId(candidates, 2, false, 40));
	}

