package com.flipsmart;
import com.flipsmart.api.dto.Dtos.WikiPrice;
import com.flipsmart.domain.offer.OfferRecord;
import com.flipsmart.domain.offer.OfferState;
import com.flipsmart.api.dto.Dtos.OfferAdviceRequest;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

public class ActiveOfferSnapshotTest
{
	private static OfferRecord sellOffer(int itemId, int totalQty, int price, int filled, long now)
	{
		OfferRecord offer = OfferRecord.newOffer(1, 0, itemId, "Item", false, totalQty, price, now);
		return filled > 0 ? offer.withFill(filled, 0L, OfferState.PARTIAL_FILL, now) : offer;
	}

	private static OfferRecord buyOffer(int itemId, int totalQty, int price, long now)
	{
		return OfferRecord.newOffer(1, 0, itemId, "Item", true, totalQty, price, now);
	}

	@Test
	public void buildsSellSnapshotWithMarketAndBuyPrice()
	{
		OfferRecord offer = sellOffer(12345, 10, 1000, 2, System.currentTimeMillis());
		WikiPrice market = new WikiPrice(1080, 1020);

		OfferAdviceRequest req = ActiveOfferAdvisorService.buildSnapshot(offer, market, 990L, 600000);

		assertEquals(12345, req.getItemId());
		assertEquals("high_vol", req.getPool());
		assertEquals("sell", req.getSide());
		assertEquals("initial", req.getStage());
		assertEquals(1000, req.getListedPrice());
		assertEquals(10, req.getListedQuantity());
		assertEquals(2, req.getFilledQuantity());
		assertEquals(Long.valueOf(1080), req.getCurrentMarketHigh());
		assertEquals(Long.valueOf(1020), req.getCurrentMarketLow());
		assertEquals(Long.valueOf(990), req.getUserAvgBuyPrice());
	}

	@Test
	public void classifiesHighVolFromDailyVolume()
	{
		OfferRecord offer = buyOffer(1, 1, 5, System.currentTimeMillis());
		OfferAdviceRequest req = ActiveOfferAdvisorService.buildSnapshot(offer, null, null, 600000);
		assertEquals("high_vol", req.getPool());
		assertEquals("buy", req.getSide());
		assertNull(req.getCurrentMarketHigh());
		assertNull(req.getUserAvgBuyPrice());
	}

	@Test
	public void buyOfferCarriesUserAvgBuyPriceForDecayExit()
	{
		// AC2 (#918): a partially-filled buy needs its avg buy price so the backend
		// can compute the decaying position margin.
		OfferRecord offer = buyOffer(1, 1, 5, System.currentTimeMillis());
		OfferAdviceRequest req = ActiveOfferAdvisorService.buildSnapshot(offer, null, 990L, 100000);
		assertEquals("mid_vol", req.getPool());
		assertEquals(Long.valueOf(990), req.getUserAvgBuyPrice());
	}

	@Test
	public void buildsSnapshotWithCourierState()
	{
		OfferRecord offer = buyOffer(4151, 10, 100000, System.currentTimeMillis());
		ActiveOfferAdvisorService.CourierState courier =
			new ActiveOfferAdvisorService.CourierState(9000L, 1, 0.1);

		OfferAdviceRequest req = ActiveOfferAdvisorService.buildSnapshot(
			offer, new WikiPrice(95000, 94000), 90000L, 100000, 10000L, courier);

		assertEquals(Long.valueOf(10000), req.getOriginalMargin());
		assertEquals(Long.valueOf(9000), req.getPreviousPositionMargin());
		assertEquals(1, req.getConsecutiveMarginDecreases());
		assertEquals(0.1, req.getCumulativeMarginReductionPct(), 1e-9);
		assertEquals(Long.valueOf(90000), req.getUserAvgBuyPrice());
	}

	@Test
	public void fourArgSnapshotDefaultsCourierStateToEmpty()
	{
		OfferRecord offer = buyOffer(1, 1, 5, System.currentTimeMillis());
		OfferAdviceRequest req = ActiveOfferAdvisorService.buildSnapshot(offer, null, null, 100000);
		assertNull(req.getOriginalMargin());
		assertNull(req.getPreviousPositionMargin());
		assertEquals(0, req.getConsecutiveMarginDecreases());
		assertEquals(0.0, req.getCumulativeMarginReductionPct(), 1e-9);
	}

	@Test
	public void aggressiveGateRelaysMarginOnlyWhenOn()
	{
		assertNull("margin must not be relayed when the aggressive advisor is off",
			ActiveOfferAdvisorService.relayedMargin(false, 5000L));
		assertEquals(Long.valueOf(5000), ActiveOfferAdvisorService.relayedMargin(true, 5000L));
	}

	@Test
	public void aggressiveGateRelaysCourierOnlyWhenOn()
	{
		ActiveOfferAdvisorService.CourierState courier =
			new ActiveOfferAdvisorService.CourierState(9000L, 2, 0.2);
		assertSame("courier must be EMPTY when the aggressive advisor is off",
			ActiveOfferAdvisorService.CourierState.EMPTY,
			ActiveOfferAdvisorService.relayedCourier(false, courier));
		assertSame(courier, ActiveOfferAdvisorService.relayedCourier(true, courier));
	}
}

package com.flipsmart;

import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.Keybind;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;

import java.awt.Canvas;
import java.awt.event.KeyEvent;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.when;

public class FlipAssistInputListenerTest
{
	@Mock private Client client;
	@Mock private ClientThread clientThread;
	@Mock private FlipSmartConfig config;
	@Mock private FlipAssistOverlay overlay;
	@Mock private FocusedFlip focusedFlip;

	private FlipAssistInputListener listener;
	private final Canvas source = new Canvas();

	@Before
	public void setUp()
	{
		MockitoAnnotations.openMocks(this);
		listener = new FlipAssistInputListener(client, clientThread, config, overlay);
		when(config.enableFlipAssistant()).thenReturn(true);
		when(config.flipAssistHotkey()).thenReturn(new Keybind(KeyEvent.VK_E, 0));
		when(overlay.getFocusedFlip()).thenReturn(focusedFlip);
		when(focusedFlip.getItemName()).thenReturn("Rune arrows");
	}

	private KeyEvent hotkeyPress()
	{
		// A synthetic KeyEvent never gets an extendedKeyCode (only the native peer
		// sets it), but Keybind.matches keys off getExtendedKeyCode() — so override it.
		return new KeyEvent(source, KeyEvent.KEY_PRESSED, System.currentTimeMillis(), 0, KeyEvent.VK_E, 'e')
		{
			@Override
			public int getExtendedKeyCode()
			{
				return KeyEvent.VK_E;
			}
		};
	}

	// Regression for #1348/#616: the hotkey character must reach the GE item-search box
	// so item names are typed intact. The player has typed a prefix of the focused item
	// ("Run" of "Rune arrows"); the next hotkey letter "E" must NOT be swallowed.
	@Test
	public void hotkeyNotConsumedOnItemSearchScreen()
	{
		listener.updateInputType(FlipAssistInputListener.INPUT_TYPE_GE_ITEM_SEARCH);
		KeyEvent e = hotkeyPress();
		listener.keyPressed(e);
		assertFalse("hotkey char must pass through to the GE search box", e.isConsumed());
	}

	// The hotkey is still intercepted on the numeric price/quantity entry screen,
	// which is the only screen it should act on.
	@Test
	public void hotkeyConsumedOnNumericInputScreen()
	{
		listener.updateInputType(7); // INPUT_TYPE_NUMERIC
		KeyEvent e = hotkeyPress();
		listener.keyPressed(e);
		assertTrue("hotkey must be consumed on the price/quantity screen", e.isConsumed());
	}

	// The max-cash update opens the price prompt in the 64-bit input mode (30);
	// the hotkey must be consumed there too, not just the legacy int mode (7).
	@Test
	public void hotkeyConsumedOnLongNumericInputScreen()
	{
		listener.updateInputType(30); // INPUT_TYPE_NUMERIC_LONG
		KeyEvent e = hotkeyPress();
		listener.keyPressed(e);
		assertTrue("hotkey must be consumed on the 64-bit price screen", e.isConsumed());
	}
}

package com.flipsmart;

import com.flipsmart.api.dto.Dtos.ActiveFlipsResponse;
import com.flipsmart.domain.flip.ActiveFlip;
import java.util.Collections;
import java.util.Optional;
import java.util.concurrent.CompletableFuture;
import net.runelite.client.game.ItemManager;
import org.junit.Before;
import org.junit.Test;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Pins the deferred sell-focus tick-retry in {@link GrandExchangeTracker}, the
 * settle-race fix from #156. When {@code overrideFocusForSell} reports the local
 * collect/inventory/session state has not settled ({@code UNAVAILABLE}), the
 * tracker retries once per game tick for a bounded budget before falling back to
 * the backend active-flip lookup — the fallback restored in {@code 3c6e53d}.
 */
public class SellFocusRetryTest
{
	private static final int ITEM = 4151;
	private static final String RSN = "TestPlayer";
	private static final int RETRY_BUDGET_TICKS = 6;

	private PlayerSession session;
	private FlipSmartApiClient apiClient;
	private ActiveFlipTracker activeFlipTracker;
	private ItemManager itemManager;
	private TradeActivityLog tradeActivityLog;
	private AutoRecommendService autoRecommendService;
	private GrandExchangeTracker tracker;

	@Before
	public void setUp()
	{
		session = new PlayerSession();
		session.setRsn(RSN);
		apiClient = mock(FlipSmartApiClient.class);
		activeFlipTracker = mock(ActiveFlipTracker.class);
		itemManager = mock(ItemManager.class);
		tradeActivityLog = mock(TradeActivityLog.class);
		autoRecommendService = mock(AutoRecommendService.class);

		when(activeFlipTracker.getInventoryCountForItem(anyInt())).thenReturn(0);
		when(apiClient.getActiveFlipsAsync(anyString()))
			.thenReturn(CompletableFuture.<ActiveFlipsResponse>completedFuture(null));
		when(autoRecommendService.isActive()).thenReturn(true);

		tracker = new GrandExchangeTracker(
			session, apiClient, activeFlipTracker, itemManager, tradeActivityLog);
		tracker.setAutoRecommendService(autoRecommendService);
		tracker.setRsnSupplier(() -> Optional.of(RSN));
	}

	@Test
	public void settlesToFocusedWithinBudgetWithoutApiFallback()
	{
		// First attempt unsettled, the retry tick resolves it.
		when(autoRecommendService.overrideFocusForSell(anyInt(), anyString()))
			.thenReturn(AutoRecommendService.SellFocusResult.UNAVAILABLE,
				AutoRecommendService.SellFocusResult.FOCUSED);

		tracker.autoFocusOnActiveFlip(ITEM);   // UNAVAILABLE → schedules a retry
		tracker.retryPendingSellFocusTick();   // FOCUSED → settles, clears pending

		verify(apiClient, never()).getActiveFlipsAsync(anyString());

		// Pending is cleared: a further tick must be a no-op (no extra resolve attempt).
		tracker.retryPendingSellFocusTick();
		verify(autoRecommendService, times(2)).overrideFocusForSell(anyInt(), anyString());
	}

	@Test
	public void fallsBackToApiLookupAfterBudgetExhausted()
	{
		when(autoRecommendService.overrideFocusForSell(anyInt(), anyString()))
			.thenReturn(AutoRecommendService.SellFocusResult.UNAVAILABLE);

		tracker.autoFocusOnActiveFlip(ITEM);   // UNAVAILABLE → budget = 6 ticks

		// Exhaust all but the final tick — still no fallback.
		for (int i = 0; i < RETRY_BUDGET_TICKS - 1; i++)
		{
			tracker.retryPendingSellFocusTick();
		}
		verify(apiClient, never()).getActiveFlipsAsync(anyString());

		// The budget-exhausting tick falls back to the backend active-flip lookup once.
		tracker.retryPendingSellFocusTick();
		verify(apiClient, times(1)).getActiveFlipsAsync(anyString());

		// Pending cleared after fallback — no second API call on subsequent ticks.
		tracker.retryPendingSellFocusTick();
		verify(apiClient, times(1)).getActiveFlipsAsync(anyString());
	}

	@Test
	public void clearsPendingRetryWhenAutoRecommendTurnedOff()
	{
		when(autoRecommendService.overrideFocusForSell(anyInt(), anyString()))
			.thenReturn(AutoRecommendService.SellFocusResult.UNAVAILABLE);

		tracker.autoFocusOnActiveFlip(ITEM);   // schedules a retry while active

		when(autoRecommendService.isActive()).thenReturn(false);
		tracker.retryPendingSellFocusTick();   // auto-recommend off → drop the pending retry

		verify(apiClient, never()).getActiveFlipsAsync(anyString());
		// Only the initial autoFocus attempt ran; the off-tick must not re-resolve.
		verify(autoRecommendService, times(1)).overrideFocusForSell(anyInt(), anyString());

		// Pending was actually cleared: re-enabling and ticking again is a no-op.
		when(autoRecommendService.isActive()).thenReturn(true);
		tracker.retryPendingSellFocusTick();
		verify(autoRecommendService, times(1)).overrideFocusForSell(anyInt(), anyString());
	}

	@Test
	public void manualMode_retriesBackendLookupAcrossTicks_thenStops()
	{
		// #1089 D5: with auto-recommend off, opening a sell screen must still retry
		// the backend active-flip lookup across ticks. Before, manual mode issued a
		// single one-shot lookup that silently failed when the backend snapshot
		// lagged the just-opened screen, so the sell target never filled.
		when(autoRecommendService.isActive()).thenReturn(false);

		tracker.autoFocusOnActiveFlip(ITEM);   // manual path: 1 lookup + arms retry
		verify(apiClient, times(1)).getActiveFlipsAsync(anyString());

		for (int i = 0; i < RETRY_BUDGET_TICKS; i++)
		{
			tracker.retryPendingSellFocusTick();
		}
		// 1 (entry) + 6 (ticks) lookups, then the budget clears the pending retry.
		verify(apiClient, times(1 + RETRY_BUDGET_TICKS)).getActiveFlipsAsync(anyString());

		// Budget exhausted → further ticks are no-ops.
		tracker.retryPendingSellFocusTick();
		verify(apiClient, times(1 + RETRY_BUDGET_TICKS)).getActiveFlipsAsync(anyString());

		// Manual mode never touches the auto-recommend local resolver.
		verify(autoRecommendService, never()).overrideFocusForSell(anyInt(), anyString());
	}

	@Test
	public void staleResponseForPreviousItem_doesNotClobberNewlyArmedItem()
	{
		// Manual mode re-issues the backend lookup every tick, so an old item's
		// in-flight request can resolve after the player has already opened a
		// sell screen for a different item. That stale response must not clear
		// the newly-armed session's pending retry.
		when(autoRecommendService.isActive()).thenReturn(false);
		int otherItem = 995;

		CompletableFuture<ActiveFlipsResponse> firstLookup = new CompletableFuture<>();
		when(apiClient.getActiveFlipsAsync(anyString())).thenReturn(firstLookup);
		tracker.autoFocusOnActiveFlip(ITEM);   // arms + fires lookup for ITEM

		CompletableFuture<ActiveFlipsResponse> secondLookup = new CompletableFuture<>();
		when(apiClient.getActiveFlipsAsync(anyString())).thenReturn(secondLookup);
		tracker.autoFocusOnActiveFlip(otherItem);   // re-arms + fires lookup for otherItem

		// The stale ITEM lookup resolves after otherItem is already pending.
		ActiveFlip staleFlip = new ActiveFlip();
		staleFlip.setItemId(ITEM);
		staleFlip.setAverageBuyPrice(100);
		staleFlip.setTotalQuantity(10);
		ActiveFlipsResponse staleResponse = new ActiveFlipsResponse();
		staleResponse.setActiveFlips(Collections.singletonList(staleFlip));
		firstLookup.complete(staleResponse);

		// otherItem's session must still be pending: a retry tick re-issues its lookup.
		tracker.retryPendingSellFocusTick();
		verify(apiClient, times(3)).getActiveFlipsAsync(anyString());
	}
}

package com.flipsmart;

import com.flipsmart.domain.offer.OfferRecord;
import com.flipsmart.domain.offer.OfferSignal;
import com.flipsmart.domain.offer.OfferState;
import com.flipsmart.trading.OfferEvent;
import com.flipsmart.trading.OfferStore;
import com.flipsmart.domain.offer.OfferTransition;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class OfferStoreTest
{
    private static final long NOW = 1_000L;

    private static OfferSignal sig(int slot, GrandExchangeOfferState s, int itemId, int sold, int total)
    {
        return new OfferSignal(slot, s, itemId, "i" + itemId, total, 100, sold, (long) sold * 100);
    }

    @Test
    public void newOffer_isStoredAndIndexedBySlotAndItem()
    {
        OfferStore store = new OfferStore();
        store.apply(sig(0, GrandExchangeOfferState.BUYING, 1234, 0, 10), NOW);

        OfferRecord bySlot = store.bySlot(0);
        assertEquals(1234, bySlot.getItemId());
        assertEquals(OfferState.NEW, bySlot.getState());
        assertEquals(1, store.forItem(1234).size());
    }

    @Test
    public void slotReuseWithDifferentItem_doesNotCollide()
    {
        OfferStore store = new OfferStore();
        store.apply(sig(0, GrandExchangeOfferState.BUYING, 1234, 0, 10), NOW);
        store.apply(sig(0, GrandExchangeOfferState.BOUGHT, 1234, 10, 10), NOW);
        store.apply(sig(0, GrandExchangeOfferState.EMPTY, 1234, 10, 10), NOW); // collected, slot freed
        store.apply(sig(0, GrandExchangeOfferState.SELLING, 5678, 0, 5), NOW); // reuse slot 0

        assertEquals(5678, store.bySlot(0).getItemId());
        assertEquals("two distinct offer lifecycles existed in slot 0",
            2, store.allRecords().size());
        assertNotEquals(store.forItem(1234).get(0).getOfferId(),
            store.forItem(5678).get(0).getOfferId());
    }

    @Test
    public void differentItemOnOccupiedSlot_mintsFreshRecordAndLeavesStaleUntouched()
    {
        // A FILLED buy is collected off-plugin (mobile, or a "Collect all" whose EMPTY we
        // never observe), so its record stays non-terminal with its slot intact. The slot is
        // then reused by a DIFFERENT item. The incoming signal must never be applied to the
        // stale record — doing so stamps the new offer's fills onto the old item (#1248).
        OfferStore store = new OfferStore();
        store.apply(sig(0, GrandExchangeOfferState.BUYING, 1234, 0, 10), NOW);
        store.apply(sig(0, GrandExchangeOfferState.BOUGHT, 1234, 10, 10), NOW); // FILLED, uncollected
        long staleOfferId = store.bySlot(0).getOfferId();

        store.apply(sig(0, GrandExchangeOfferState.BUYING, 5678, 0, 5), NOW); // slot reused, no EMPTY

        assertEquals("slot now holds the new item's record", 5678, store.bySlot(0).getItemId());
        assertNotEquals("the new offer must not inherit the stale record's id",
            staleOfferId, store.bySlot(0).getOfferId());

        OfferRecord stale = store.forItem(1234).get(0);
        assertEquals("the stale record's fills are left intact", 10, stale.getFilledQuantity());
    }

    @Test
    public void staleSlotReuse_emitsFillEventForNewItemNotStaleOne()
    {
        // The event carries what reaches the backend as a transaction. A fill on a reused slot
        // must be attributed to the new item — never to the stale record whose collect we missed.
        OfferStore store = new OfferStore();
        List<OfferEvent> fills = new ArrayList<>();
        store.addListener(e -> {
            if (e.kind == OfferTransition.Kind.FILLED_DELTA
                || e.kind == OfferTransition.Kind.COMPLETED
                || e.kind == OfferTransition.Kind.PLACED)
            {
                fills.add(e);
            }
        });

        store.apply(sig(0, GrandExchangeOfferState.BUYING, 1234, 0, 10), NOW);
        store.apply(sig(0, GrandExchangeOfferState.BOUGHT, 1234, 10, 10), NOW); // FILLED, uncollected
        fills.clear();

        store.apply(sig(0, GrandExchangeOfferState.SELLING, 5678, 0, 5), NOW); // slot reused, new item
        store.apply(sig(0, GrandExchangeOfferState.SOLD, 5678, 5, 5), NOW);     // it fills

        assertFalse("the new item's fill was emitted", fills.isEmpty());
        for (OfferEvent e : fills)
        {
            assertEquals("no fill may be attributed to the stale item 1234",
                5678, e.record.getItemId());
        }
    }

    @Test
    public void oppositeDirectionOnOccupiedSlot_mintsFreshRecord()
    {
        // Same slot, same item, but the collected buy is relisted as a SELL and we missed the
        // EMPTY between them. Direction distinguishes the two offers; the sell must be its own
        // record, not a mutation of the buy that would corrupt the buy's cost basis.
        OfferStore store = new OfferStore();
        store.apply(sig(0, GrandExchangeOfferState.BUYING, 1234, 0, 10), NOW);
        store.apply(sig(0, GrandExchangeOfferState.BOUGHT, 1234, 10, 10), NOW); // FILLED buy, uncollected

        store.apply(sig(0, GrandExchangeOfferState.SELLING, 1234, 0, 10), NOW); // relisted as sell

        assertFalse("slot now holds a sell offer", store.bySlot(0).isBuy());
        assertEquals("buy and sell are two distinct records", 2, store.forItem(1234).size());
        OfferRecord buy = store.forItem(1234).stream()
            .filter(OfferRecord::isBuy).findFirst().orElseThrow(AssertionError::new);
        assertEquals("the collected buy keeps its fills", 10, buy.getFilledQuantity());
    }

    @Test
    public void mismatchedCancelOnOccupiedSlot_evictsStaleRecordWithoutMintingPhantom()
    {
        // A missed EMPTY leaves a stale record in the slot. The next signal observed for that
        // slot is a CANCEL for a different item, never a live directional state. The stale
        // record must still be evicted rather than have the mismatched cancel's data stamped
        // onto it, and no phantom record should be minted purely from observing a cancellation.
        OfferStore store = new OfferStore();
        store.apply(sig(0, GrandExchangeOfferState.BUYING, 1234, 0, 10), NOW);
        store.apply(sig(0, GrandExchangeOfferState.BOUGHT, 1234, 10, 10), NOW); // FILLED, uncollected

        store.apply(sig(0, GrandExchangeOfferState.CANCELLED_SELL, 5678, 3, 5), NOW); // mismatched cancel

        assertNull("no phantom offer minted from a bare cancellation", store.bySlot(0));
        OfferRecord stale = store.forItem(1234).get(0);
        assertEquals("the stale record's state is untouched by the mismatched cancel",
            OfferState.FILLED, stale.getState());
        assertEquals("the stale record's fills are left intact", 10, stale.getFilledQuantity());
        assertTrue("item 5678 must not gain a record from a bare cancel signal",
            store.forItem(5678).isEmpty());
    }

    @Test
    public void sameItemInTwoSlots_keepsTwoDistinctOffers()
    {
        OfferStore store = new OfferStore();
        store.apply(sig(0, GrandExchangeOfferState.BUYING, 1234, 0, 10), NOW);
        store.apply(sig(3, GrandExchangeOfferState.SELLING, 1234, 0, 10), NOW);

        assertEquals(2, store.forItem(1234).size());
    }

    @Test
    public void collected_clearsSlotIndexButRecordRemains()
    {
        OfferStore store = new OfferStore();
        store.apply(sig(0, GrandExchangeOfferState.BUYING, 1234, 0, 10), NOW);
        store.apply(sig(0, GrandExchangeOfferState.BOUGHT, 1234, 10, 10), NOW);
        store.apply(sig(0, GrandExchangeOfferState.EMPTY, 1234, 10, 10), NOW);

        assertNull("slot freed", store.bySlot(0));
        assertEquals(OfferState.COLLECTED, store.forItem(1234).get(0).getState());
    }

    @Test
    public void snapshotIsolation_heldListDoesNotMutate()
    {
        OfferStore store = new OfferStore();
        store.apply(sig(0, GrandExchangeOfferState.BUYING, 1234, 0, 10), NOW);
        List<OfferRecord> held = store.allRecords();
        int before = held.size();

        store.apply(sig(1, GrandExchangeOfferState.BUYING, 9999, 0, 10), NOW);

        assertEquals("previously-returned snapshot is immutable", before, held.size());
        assertTrue(store.allRecords().size() > before);
    }

    @Test
    public void hasActiveSellOfferForItem_trueForLiveSell_falseAfterCollect()
    {
        OfferStore store = new OfferStore();
        store.apply(sig(0, GrandExchangeOfferState.SELLING, 1234, 0, 10), NOW);
        assertTrue(store.hasActiveSellOfferForItem(1234));

        store.apply(sig(0, GrandExchangeOfferState.SOLD, 1234, 10, 10), NOW);
        assertTrue("FILLED sell still occupies the slot", store.hasActiveSellOfferForItem(1234));

        store.apply(sig(0, GrandExchangeOfferState.EMPTY, 1234, 10, 10), NOW); // collected
        assertFalse("collected sell is terminal", store.hasActiveSellOfferForItem(1234));
    }

    @Test
    public void hasActiveSellOfferForItem_ignoresBuyOffers()
    {
        OfferStore store = new OfferStore();
        store.apply(sig(0, GrandExchangeOfferState.BUYING, 1234, 0, 10), NOW);
        assertFalse(store.hasActiveSellOfferForItem(1234));
    }

    @Test
    public void hasActiveSellOfferForItem_terminalRecordDoesNotMaskLiveSell()
    {
        OfferStore store = new OfferStore();
        // slot 0: complete the buy lifecycle so a terminal COLLECTED record exists for item 1234
        store.apply(sig(0, GrandExchangeOfferState.BUYING, 1234, 0, 5), NOW);
        store.apply(sig(0, GrandExchangeOfferState.BOUGHT, 1234, 5, 5), NOW);
        store.apply(sig(0, GrandExchangeOfferState.EMPTY, 1234, 5, 5), NOW); // COLLECTED (terminal)
        // slot 1: open a live sell for the same item
        store.apply(sig(1, GrandExchangeOfferState.SELLING, 1234, 0, 5), NOW); // NEW sell
        assertTrue("live sell must be visible even when a terminal record for the same item exists",
            store.hasActiveSellOfferForItem(1234));
    }

    @Test
    public void hasLiveBuyOfferForItem_coversInFlightAndUncollected()
    {
        OfferStore store = new OfferStore();
        store.apply(sig(0, GrandExchangeOfferState.BUYING, 1234, 0, 10), NOW);
        assertTrue("in-flight buy", store.hasLiveBuyOfferForItem(1234));

        store.apply(sig(0, GrandExchangeOfferState.BOUGHT, 1234, 10, 10), NOW);
        assertTrue("filled but uncollected buy", store.hasLiveBuyOfferForItem(1234));

        store.apply(sig(0, GrandExchangeOfferState.EMPTY, 1234, 10, 10), NOW); // collected
        assertFalse("collected buy is terminal", store.hasLiveBuyOfferForItem(1234));
    }

    @Test
    public void hasLiveBuyOfferForItem_ignoresSellOffers()
    {
        OfferStore store = new OfferStore();
        store.apply(sig(0, GrandExchangeOfferState.SELLING, 1234, 0, 10), NOW);
        assertFalse(store.hasLiveBuyOfferForItem(1234));
    }

    @Test
    public void completedAwaitingCollection_listsFilledOnly()
    {
        OfferStore store = new OfferStore();
        store.apply(sig(0, GrandExchangeOfferState.BUYING, 1234, 0, 10), NOW); // NEW
        store.apply(sig(1, GrandExchangeOfferState.BOUGHT, 5678, 10, 10), NOW); // FILLED
        assertEquals(1, store.completedAwaitingCollection().size());
        assertEquals(5678, store.completedAwaitingCollection().get(0).getItemId());

        store.apply(sig(1, GrandExchangeOfferState.EMPTY, 5678, 10, 10), NOW); // collected
        assertTrue("collected offer drops out of awaiting-collection",
            store.completedAwaitingCollection().isEmpty());
    }

    @Test
    public void completedAwaitingCollection_includesCancelledPartial()
    {
        OfferStore store = new OfferStore();
        store.apply(sig(0, GrandExchangeOfferState.BUYING, 1234, 3, 10), NOW); // PARTIAL_FILL
        store.apply(sig(0, GrandExchangeOfferState.CANCELLED_BUY, 1234, 3, 10), NOW); // CANCELLED_PARTIAL
        assertEquals("cancelled-partial has collectable fills and must trigger collect prompt",
            1, store.completedAwaitingCollection().size());
        assertEquals(1234, store.completedAwaitingCollection().get(0).getItemId());
    }

    @Test
    public void completedAwaitingCollection_excludesInFlightOffers()
    {
        OfferStore store = new OfferStore();
        store.apply(sig(0, GrandExchangeOfferState.BUYING, 1234, 0, 10), NOW); // NEW
        store.apply(sig(1, GrandExchangeOfferState.BUYING, 5678, 3, 10), NOW); // PARTIAL_FILL
        assertTrue("in-flight offers have nothing to collect yet",
            store.completedAwaitingCollection().isEmpty());
    }

    @Test
    public void liveOffers_excludesTerminalRecords()
    {
        OfferStore store = new OfferStore();
        store.apply(sig(0, GrandExchangeOfferState.BUYING, 1234, 0, 10), NOW); // NEW (live)
        store.apply(sig(1, GrandExchangeOfferState.SELLING, 5678, 0, 5), NOW); // NEW sell (live)

        assertEquals("both offers are live", 2, store.liveOffers().size());

        // Complete and collect the buy → terminal COLLECTED
        store.apply(sig(0, GrandExchangeOfferState.BOUGHT, 1234, 10, 10), NOW); // FILLED (still live)
        assertEquals("filled-but-uncollected buy is still live", 2, store.liveOffers().size());

        store.apply(sig(0, GrandExchangeOfferState.EMPTY, 1234, 10, 10), NOW); // COLLECTED (terminal)
        List<OfferRecord> live = store.liveOffers();
        assertEquals("collected offer drops out of live view", 1, live.size());
        assertEquals(5678, live.get(0).getItemId());
    }

    @Test
    public void liveOffers_isEmptyWhenNoOffers()
    {
        OfferStore store = new OfferStore();
        assertTrue(store.liveOffers().isEmpty());
    }

    @Test
    public void offerIds_areMonotonicAndUnique()
    {
        OfferStore store = new OfferStore();
        store.apply(sig(0, GrandExchangeOfferState.BUYING, 1, 0, 1), NOW);
        store.apply(sig(1, GrandExchangeOfferState.BUYING, 2, 0, 1), NOW);

        long a = store.bySlot(0).getOfferId();
        long b = store.bySlot(1).getOfferId();
        assertTrue(b > a);
    }

    @Test
    public void exportImport_roundTripsRecordsAndRebuildsSlotIndex()
    {
        OfferStore source = new OfferStore();
        source.apply(sig(0, GrandExchangeOfferState.BUYING, 1234, 0, 10), NOW);
        source.apply(sig(1, GrandExchangeOfferState.BOUGHT, 5678, 10, 10), NOW); // FILLED (live)
        source.apply(sig(2, GrandExchangeOfferState.BUYING, 4321, 0, 10), NOW);
        source.apply(sig(2, GrandExchangeOfferState.CANCELLED_BUY, 4321, 0, 10), NOW); // CANCELLED_EMPTY (terminal, slot freed)

        List<OfferRecord> exported = source.export();

        OfferStore target = new OfferStore();
        target.importRecords(exported);

        assertEquals(source.allRecords().size(), target.allRecords().size());
        assertEquals(1234, target.bySlot(0).getItemId());
        assertEquals(5678, target.bySlot(1).getItemId());
        assertNull("terminal record's slot is not re-indexed", target.bySlot(2));
        assertEquals("terminal record is still retained", 1, target.forItem(4321).size());
    }

    @Test
    public void lossyImport_doesNotRecycleAnIdTheBackendAlreadyHoldsFillsUnder()
    {
        // The login reconcile drops terminal records past the retention window and
        // runs on every world hop, so an import is routinely a SUBSET of what the
        // store held. Seeding the counter from the survivors let it regress and
        // remint an id the backend still has fills recorded against.
        OfferStore store = new OfferStore();
        store.apply(sig(0, GrandExchangeOfferState.BUYING, 1234, 0, 10), NOW);
        store.apply(sig(1, GrandExchangeOfferState.BUYING, 5678, 0, 10), NOW);
        long prunedId = store.bySlot(1).getOfferId();

        List<OfferRecord> survivors = new ArrayList<>();
        for (OfferRecord r : store.export())
        {
            if (r.getOfferId() != prunedId)
            {
                survivors.add(r);
            }
        }
        store.importRecords(survivors);

        store.apply(sig(2, GrandExchangeOfferState.BUYING, 9999, 0, 10), NOW);
        assertTrue("id counter must not regress past a pruned record",
            store.bySlot(2).getOfferId() > prunedId);
    }

    @Test
    public void importRecords_reseedsNextOfferIdAboveMax()
    {
        OfferStore source = new OfferStore();
        source.apply(sig(0, GrandExchangeOfferState.BUYING, 1234, 0, 10), NOW);
        source.apply(sig(1, GrandExchangeOfferState.BUYING, 5678, 0, 10), NOW);
        long maxId = source.bySlot(1).getOfferId();

        OfferStore target = new OfferStore();
        target.importRecords(source.export());

        // A fresh offer placed after import must get a non-colliding id above the max.
        target.apply(sig(3, GrandExchangeOfferState.BUYING, 9999, 0, 10), NOW);
        long newId = target.bySlot(3).getOfferId();
        assertTrue("new id (" + newId + ") must exceed imported max (" + maxId + ")", newId > maxId);

        for (OfferRecord r : target.allRecords())
        {
            if (r.getItemId() != 9999)
            {
                assertNotEquals("imported ids are preserved, not reused", newId, r.getOfferId());
            }
        }
    }

    @Test
    public void correctCreatedAt_replacesTimestampPreservingSlotIndex()
    {
        OfferStore store = new OfferStore();
        store.apply(sig(2, GrandExchangeOfferState.BUYING, 1234, 0, 10), NOW);
        long offerId = store.bySlot(2).getOfferId();

        store.correctCreatedAt(offerId, 42L);

        OfferRecord corrected = store.bySlot(2);
        assertEquals("createdAt is replaced", 42L, corrected.getCreatedAtMillis());
        assertEquals("same offerId after correction", offerId, corrected.getOfferId());
        assertEquals("slot index preserved", Integer.valueOf(2), corrected.getSlot());
    }

    @Test
    public void correctCreatedAt_unknownOfferId_isNoOp()
    {
        OfferStore store = new OfferStore();
        store.apply(sig(2, GrandExchangeOfferState.BUYING, 1234, 0, 10), NOW);
        long before = store.bySlot(2).getCreatedAtMillis();

        store.correctCreatedAt(999_999L, 42L);

        assertEquals("no record changed for unknown id", before, store.bySlot(2).getCreatedAtMillis());
    }

    @Test
    public void correctActivityAt_restoresEffectiveLastActivity()
    {
        OfferStore store = new OfferStore();
        store.apply(sig(2, GrandExchangeOfferState.BUYING, 1234, 0, 10), NOW);
        long offerId = store.bySlot(2).getOfferId();
        assertEquals("freshly seen offer anchors activity to now", NOW,
            store.bySlot(2).getEffectiveLastActivityAtMillis());

        store.correctActivityAt(offerId, 42L);

        assertEquals("activity restored to the older value", 42L,
            store.bySlot(2).getEffectiveLastActivityAtMillis());
        assertEquals("slot index preserved", Integer.valueOf(2), store.bySlot(2).getSlot());
    }

    @Test
    public void correctActivityAt_unknownOfferId_isNoOp()
    {
        OfferStore store = new OfferStore();
        store.apply(sig(2, GrandExchangeOfferState.BUYING, 1234, 0, 10), NOW);
        long before = store.bySlot(2).getEffectiveLastActivityAtMillis();

        store.correctActivityAt(999_999L, 42L);

        assertEquals("no record changed for unknown id", before,
            store.bySlot(2).getEffectiveLastActivityAtMillis());
    }

}

package com.flipsmart;

import javax.swing.JSpinner;
import javax.swing.SpinnerNumberModel;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * The gear pop-out filter spinners must capture a value the user TYPED even when
 * they dismiss the pop-out without pressing Enter (they click outside, or hit the
 * Update button). {@link FlipFinderPanel#commitSpinner} force-commits the editor
 * text to the model, reverting to the last valid value if the text is unparseable.
 */
public class GearPopoutFilterCommitTest
{
	private static JSpinner spinner(int value)
	{
		return new JSpinner(new SpinnerNumberModel(value, 0, Integer.MAX_VALUE, 100));
	}

	private static void type(JSpinner s, String text)
	{
		((JSpinner.DefaultEditor) s.getEditor()).getTextField().setText(text);
	}

	@Test
	public void commitsTypedValueWithoutEnter()
	{
		JSpinner s = spinner(1000);
		type(s, "5000");

		assertEquals(5000, FlipFinderPanel.commitSpinner(s));
		assertEquals(5000, s.getValue());
	}

	@Test
	public void revertsInvalidTypedTextToLastValue()
	{
		JSpinner s = spinner(1000);
		type(s, "not a number");

		assertEquals(1000, FlipFinderPanel.commitSpinner(s));
		assertEquals(1000, s.getValue());
	}

	@Test
	public void revertsEmptyTypedTextToLastValue()
	{
		JSpinner s = spinner(2000);
		type(s, "");

		assertEquals(2000, FlipFinderPanel.commitSpinner(s));
		assertEquals(2000, s.getValue());
	}
}

