			.thenReturn(new GrandExchangeOffer[] { empty, empty, empty, empty, empty, empty, empty, empty });
		service.preloadPersistedOffers();

		org.junit.Assert.assertNotNull("live offer must survive a non-null-but-empty snapshot preload",
			store.bySlot(0));
		assertEquals(1234, store.bySlot(0).getItemId());
	}

	/**
	 * A collected buy is the cost basis for the sell that follows it, so breakeven and profit go
	 * unresolvable if a reconcile drops it. LOGGED_IN fires on every world hop, so this ran
	 * mid-session with no logout, and the following persist wrote the loss through to disk.
	 */
	@Test
	public void preload_withReadableGeSnapshot_preservesCollectedBuyHistory()
	{
		when(session.getRsn()).thenReturn("Zezima");

		// Wall-clock relative: the service reconciles against System.currentTimeMillis().
		long now = System.currentTimeMillis();

		// Earlier this session: bought 10 of item 4444 and collected them (terminal history).
		store.apply(sig(0, GrandExchangeOfferState.BUYING, 4444, 0, 10), now - 300_000L);
		store.apply(sig(0, GrandExchangeOfferState.BOUGHT, 4444, 10, 10), now - 200_000L);
		store.apply(sig(0, GrandExchangeOfferState.EMPTY, 4444, 10, 10), now - 100_000L);
		// A live sell for a different item occupies slot 1.
		store.apply(sig(1, GrandExchangeOfferState.SELLING, 5555, 0, 10), now - 50_000L);
		service.persistOfferState();

		assertFalse("sanity: collected buy present before preload", store.forItem(4444).isEmpty());

		// World hop where the GE snapshot IS readable: slot 1 still holds the live sell.
		ItemComposition comp5555 = itemComp("i5555");
		when(itemManager.getItemComposition(5555)).thenReturn(comp5555);
		GrandExchangeOffer liveSell = geOffer(5555, GrandExchangeOfferState.SELLING, 10, 100);
		when(client.getGrandExchangeOffers()).thenReturn(new GrandExchangeOffer[]{null, liveSell});

		service.preloadPersistedOffers();

		boolean survivedInStore = !store.forItem(4444).isEmpty();

		// The next persist writes the store back over the saved blob, so if the record was
		// dropped in memory it is also gone from disk — a relog cannot bring it back.
		store.apply(sig(2, GrandExchangeOfferState.BUYING, 6666, 0, 5), 5000L);
		service.persistOfferState();
		boolean survivedInPersistence = configStore.get("persistedOffers_Zezima") != null
			&& configStore.get("persistedOffers_Zezima").contains("4444");

		assertTrue("collected buy history must survive a readable-snapshot preload", survivedInStore);
		assertTrue("collected buy history must survive the following persist", survivedInPersistence);
	}

	@Test
	public void terminalHistoryRetention_dropsRecordsOlderThanTheWindow()
	{
		long now = 10_000_000_000L;
		// A collect only terminalizes a filled offer, so each record runs BUYING -> BOUGHT -> EMPTY.
		store.apply(sig(0, GrandExchangeOfferState.BUYING, 111, 0, 10), now);
		store.apply(sig(0, GrandExchangeOfferState.BOUGHT, 111, 10, 10), now);
		store.apply(sig(0, GrandExchangeOfferState.EMPTY, 111, 10, 10),
			now - OfflineSyncService.TERMINAL_HISTORY_RETENTION_MS - 1);
		store.apply(sig(1, GrandExchangeOfferState.BUYING, 222, 0, 10), now);
		store.apply(sig(1, GrandExchangeOfferState.BOUGHT, 222, 10, 10), now);
		store.apply(sig(1, GrandExchangeOfferState.EMPTY, 222, 10, 10), now - 1000L);

		List<OfferRecord> retained =
			service.retainRecentTerminalHistory(store.export(), now);

		assertEquals("only the in-window terminal record is retained", 1, retained.size());
		assertEquals(222, retained.get(0).getItemId());
	}

	/**
	 * Age is the wrong sole criterion. A buy collected two days ago is still the cost basis for
	 * stock the player is holding right now, and dropping it puts breakeven back to "?" — the same
	 * defect the retention was added to fix, just on a slower clock.
	 */
	@Test
	public void terminalHistoryRetention_keepsRecordsBackingAnOpenPosition()
	{
		when(session.getRsn()).thenReturn("Zezima");
		long now = System.currentTimeMillis();
		long longAgo = now - OfflineSyncService.TERMINAL_HISTORY_RETENTION_MS - 60_000L;

		// Bought and collected well outside the window, but never sold: the position is still open.
		store.apply(sig(0, GrandExchangeOfferState.BUYING, 333, 0, 10), longAgo);
		store.apply(sig(0, GrandExchangeOfferState.BOUGHT, 333, 10, 10), longAgo);
		store.apply(sig(0, GrandExchangeOfferState.EMPTY, 333, 10, 10), longAgo);
		ledger.recordFill("Zezima", 333, true, 10);

		// Equally old, but fully liquidated — nothing depends on it any more.
		store.apply(sig(1, GrandExchangeOfferState.BUYING, 444, 0, 10), longAgo);
		store.apply(sig(1, GrandExchangeOfferState.BOUGHT, 444, 10, 10), longAgo);
		store.apply(sig(1, GrandExchangeOfferState.EMPTY, 444, 10, 10), longAgo);
		ledger.recordFill("Zezima", 444, true, 10);
		ledger.recordFill("Zezima", 444, false, 10);

		List<OfferRecord> retained = service.retainRecentTerminalHistory(store.export(), now);

		java.util.Set<Integer> items = new java.util.HashSet<>();
		for (OfferRecord r : retained)
		{
			items.add(r.getItemId());
		}
		assertTrue("a held position keeps its basis however old", items.contains(333));
		assertFalse("a liquidated position ages out as before", items.contains(444));
	}

	/**
	 * The exemption is only as good as the ledger backing it. On a cold start the ledger lives in
	 * config, not memory, so it has to be restored before retention asks it what is still held —
	 * otherwise every held position reads as zero and its basis ages out exactly as before.
	 */
	@Test
	public void terminalHistoryRetention_consultsAPersistedLedgerOnAColdStart()
	{
		when(session.getRsn()).thenReturn("Zezima");
		long longAgo = System.currentTimeMillis()
			- OfflineSyncService.TERMINAL_HISTORY_RETENTION_MS - 60_000L;

		// An old, collected buy for an item the player still holds.
		store.apply(sig(0, GrandExchangeOfferState.BUYING, 333, 0, 10), longAgo);
		store.apply(sig(0, GrandExchangeOfferState.BOUGHT, 333, 10, 10), longAgo);
		store.apply(sig(0, GrandExchangeOfferState.EMPTY, 333, 10, 10), longAgo);
		service.persistOfferState();

		// A cold start: the ledger is empty in memory and its state sits in config.
		configStore.put("roundTripLedger_Zezima", "{\"333\":{\"heldQuantity\":10,\"cycleId\":1}}");
		store.importRecords(Collections.emptyList());
		when(client.getGrandExchangeOffers()).thenReturn(null);

		service.preloadPersistedOffers();

		assertFalse("the held position's basis must survive a cold start",
			store.forItem(333).isEmpty());
	}

	@Test
	public void terminalHistoryRetention_capsRecordCountKeepingNewest()
	{
		long now = 10_000_000_000L;
		for (int i = 0; i < OfflineSyncService.MAX_RETAINED_TERMINAL_RECORDS + 25; i++)
		{
			int itemId = 1000 + i;
			store.apply(sig(0, GrandExchangeOfferState.BUYING, itemId, 0, 1), now);
			store.apply(sig(0, GrandExchangeOfferState.BOUGHT, itemId, 1, 1), now);
			// Newer index == more recent activity.
			store.apply(sig(0, GrandExchangeOfferState.EMPTY, itemId, 1, 1), now - 100_000L + i);
		}

		List<OfferRecord> retained =
			service.retainRecentTerminalHistory(store.export(), now);

		assertEquals("retained set is capped", OfflineSyncService.MAX_RETAINED_TERMINAL_RECORDS,
			retained.size());
		assertEquals("newest record is kept", 1000 + OfflineSyncService.MAX_RETAINED_TERMINAL_RECORDS + 24,
			retained.get(0).getItemId());
	}

	@Test
	public void relog_restoresOfferAge_forStillLiveOffer()
	{
		when(session.getRsn()).thenReturn("Zezima");
		when(session.isOfflineSyncCompleted()).thenReturn(false);

		// Offer placed long ago — activity anchored at 1000.
		store.apply(sig(0, GrandExchangeOfferState.BUYING, 111, 0, 5), 1000L);
		service.persistOfferState();

		// Fresh login re-anchors the still-live offer to "now" (9000).
		store.importRecords(Collections.emptyList());
		store.apply(sig(0, GrandExchangeOfferState.BUYING, 111, 0, 5), 9000L);
		assertEquals("re-anchored to login time before restore", 9000L,
			store.bySlot(0).getEffectiveLastActivityAtMillis());

		ItemComposition comp = itemComp("i111");
		when(itemManager.getItemComposition(111)).thenReturn(comp);
		GrandExchangeOffer live = geOffer(111, GrandExchangeOfferState.BUYING, 5, 100);
		when(client.getGrandExchangeOffers()).thenReturn(new GrandExchangeOffer[]{live});

		service.syncOfflineFills();

		assertEquals("offer age restored across relog", 1000L,
			store.bySlot(0).getEffectiveLastActivityAtMillis());
	}

	/**
	 * A sell that completes while offline must decrement the round-trip ledger's held quantity the
	 * same way a live sell fill would, so a full liquidation closes the cycle. Without this the held
	 * count never returns to zero, the cycle never closes, and its cost basis blends buys the player
	 * has already sold — the overstated GE breakeven a user reported.
	 */
	@Test
	public void offlineCollectedSellClosesTheRoundTripCycle()
	{
		// A buy of 10 counted live: held = 10, cycle 1 open.
		ledger.recordFill("Zezima", 555, true, 10);
		assertEquals(10, ledger.heldQuantity("Zezima", 555));
		int cycleBefore = ledger.peekRoundTripId("Zezima", 555);

		// A sell of all 10 that completed while offline.
		stageCompletedOfflineSell(555);
		when(client.getGrandExchangeOffers()).thenReturn(new GrandExchangeOffer[0]);

		service.syncOfflineFills();

		assertEquals("offline sell must decrement held to zero", 0, ledger.heldQuantity("Zezima", 555));
		assertEquals("a full liquidation must close the cycle", cycleBefore + 1,
			(int) ledger.peekRoundTripId("Zezima", 555));
	}

	/**
	 * The decrement is applied exactly once. Terminalising the offered record is the guard — a second
	 * login over the now-terminal sell must not re-decrement held or run the cycle away.
	 */
	@Test
	public void offlineCollectedSellDecrementsHeldExactlyOnce()
	{
		ledger.recordFill("Zezima", 555, true, 10);
		stageCompletedOfflineSell(555);
		when(client.getGrandExchangeOffers()).thenReturn(new GrandExchangeOffer[0]);

		service.syncOfflineFills();
		int cycleAfterFirst = ledger.peekRoundTripId("Zezima", 555);

		service.syncOfflineFills();

		assertEquals("held stays zero across a second sync", 0, ledger.heldQuantity("Zezima", 555));
		assertEquals("the cycle must not advance a second time", cycleAfterFirst,
			(int) ledger.peekRoundTripId("Zezima", 555));
	}

	/**
	 * Mirrors the live QA path exactly: the held position and the offline sell both arrive as
	 * PERSISTED blobs (ledger restored from config, sell restored from the persisted offers), rather
	 * than being built in-memory. Proves the decrement fires against an imported ledger entry.
	 */
	@Test
	public void offlineCollectedSell_fromPersistedBlobs_closesCycle()
	{
		when(session.getRsn()).thenReturn("Zezima");
		when(session.isOfflineSyncCompleted()).thenReturn(false);

		// Held 3 of item 555, cycle 1 — as if restored from a previous session's ledger.
		configStore.put("roundTripLedger_Zezima",
			"{\"555\":{\"heldQuantity\":3,\"cycleId\":1,\"boughtQuantity\":3,\"boughtSpent\":2991,\"absorbedBySlotDir\":{}}}");

		// A FILLED (non-terminal) sell of all 3 that completed offline, persisted into the offers blob.
		OfferRecord sell = OfferRecord.newOffer(999300888L, 0, 555, "i555", false, 3, 1000, 1000L)
			.withFill(3, 2000L, OfferState.FILLED, 2000L);
		configStore.put("persistedOffers_Zezima", new Gson().toJson(java.util.Collections.singletonList(sell)));

		// Import the ledger from config (preload), exactly as login does.
		when(client.getGrandExchangeOffers()).thenReturn(null);
		service.preloadPersistedOffers();
		assertEquals("sanity: ledger imported held=3", 3, ledger.heldQuantity("Zezima", 555));

		// Now the offline sync classifies the sell and (with the fix) decrements.
		when(client.getGrandExchangeOffers()).thenReturn(new GrandExchangeOffer[0]);
		service.syncOfflineFills();

		assertEquals("offline sell must decrement the imported held to zero", 0,
			ledger.heldQuantity("Zezima", 555));
		assertEquals("full liquidation must close the imported cycle", 2,
			(int) ledger.peekRoundTripId("Zezima", 555));
	}

	private static GrandExchangeOffer geOffer(int itemId, GrandExchangeOfferState state, int total, int price)
	{
		GrandExchangeOffer o = mock(GrandExchangeOffer.class);
		when(o.getItemId()).thenReturn(itemId);
		when(o.getState()).thenReturn(state);
		when(o.getTotalQuantity()).thenReturn(total);
		when(o.getPrice()).thenAnswer(GpAnswer.gp(price));
		when(o.getQuantitySold()).thenReturn(0);
		when(o.getSpent()).thenAnswer(GpAnswer.gp(0));
		return o;
	}

	private static ItemComposition itemComp(String name)
	{
		ItemComposition c = mock(ItemComposition.class);
		when(c.getName()).thenReturn(name);
		return c;
	}

	private static com.flipsmart.domain.offer.OfferSignal sig(int slot, GrandExchangeOfferState s, int itemId, int sold, int total)
	{
		return new com.flipsmart.domain.offer.OfferSignal(slot, s, itemId, "i" + itemId, total, 100, sold, (long) sold * 100);
	}
}

package com.flipsmart.trading;

import static org.junit.Assert.assertEquals;
import com.flipsmart.domain.offer.OfferRecord;
import com.flipsmart.domain.offer.OfferState;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

public class RealizedFlipProfitTest
{
	private static final int ITEM_ID = 12934; // Zulrah's scales (not tax-exempt)

	private static OfferRecord sell(int qty, int price, long spent, long activityMs)
	{
		// newOffer(offerId, slot, itemId, itemName, buy=false, totalQuantity, price, now)
		return OfferRecord.newOffer(1L, 0, ITEM_ID, "Zulrah's scales", false, qty, price, activityMs)
			.withFill(qty, spent, OfferState.FILLED, activityMs);
	}

	private static OfferRecord buy(int qty, int price, long spent, long activityMs)
	{
		return OfferRecord.newOffer(2L, 1, ITEM_ID, "Zulrah's scales", true, qty, price, activityMs)
			.withFill(qty, spent, OfferState.FILLED, activityMs);
	}

	@Test
	public void noSellsYieldsZero()
	{
		RealizedFlipProfit.Result r = RealizedFlipProfit.compute(Collections.emptyList(), ITEM_ID, 173, 0L);
		assertEquals(0, r.soldQuantity);
		assertEquals(0L, r.grossProceeds);
		assertEquals(0L, r.netProfit);
	}

	@Test
	public void buyRecordsAreIgnored()
	{
		List<OfferRecord> recs = Collections.singletonList(buy(100, 173, 17_300L, 1000L));
		RealizedFlipProfit.Result r = RealizedFlipProfit.compute(recs, ITEM_ID, 173, 0L);
		assertEquals(0, r.soldQuantity);
		assertEquals(0L, r.netProfit);
	}

	@Test
	public void realizedNetIsProceedsMinusBuyCostMinusTax()
	{
		// sell 1000 @ 179 => proceeds 179,000; tax = taxFor(179)*1000; buyCost = 1000*173
		OfferRecord s = sell(1000, 179, 179_000L, 5000L);
		RealizedFlipProfit.Result r = RealizedFlipProfit.compute(Collections.singletonList(s), ITEM_ID, 173, 0L);
		long expectedTax = (long) com.flipsmart.util.GeTax.taxFor(ITEM_ID, 179) * 1000;
		assertEquals(1000, r.soldQuantity);
		assertEquals(179_000L, r.grossProceeds);
		assertEquals(expectedTax, r.taxTotal);
		assertEquals(179_000L - (1000L * 173) - expectedTax, r.netProfit);
	}

	@Test
	public void sellsBeforeCutoffAreExcluded()
	{
		OfferRecord older = sell(500, 179, 89_500L, 1000L);
		OfferRecord newer = sell(500, 179, 89_500L, 9000L);
		RealizedFlipProfit.Result r = RealizedFlipProfit.compute(Arrays.asList(older, newer), ITEM_ID, 173, 5000L);
		assertEquals(500, r.soldQuantity); // only the newer sell counts
		assertEquals(89_500L, r.grossProceeds);
	}
}

package com.flipsmart.trading;

import org.junit.Test;

import java.util.HashMap;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;

public class FillWatermarksTest
{
	@Test
	public void identity_isValueEqual_andSeparatesGenerations()
	{
		OfferIdentity a = OfferIdentity.of(0, 4444, true, 1);
		OfferIdentity b = OfferIdentity.of(0, 4444, true, 1);
		OfferIdentity nextGen = OfferIdentity.of(0, 4444, true, 2);

		assertEquals(a, b);
		assertEquals(a.hashCode(), b.hashCode());
		assertNotEquals("a reused slot holds a different offer", a, nextGen);
	}

	@Test
	public void identity_ignoresDirectionCollisions()
	{
		assertNotEquals("a buy and a sell of one item are different offers",
			OfferIdentity.of(0, 4444, true, 1), OfferIdentity.of(0, 4444, false, 1));
	}

	@Test
	public void observe_returnsOnlyTheIncrement()
	{
		FillWatermarks watermarks = new FillWatermarks();
		OfferIdentity id = OfferIdentity.of(0, 7777, true, 1);

		assertEquals(4, watermarks.observe(id, 4, 400L).quantity);
		assertEquals(3, watermarks.observe(id, 7, 700L).quantity);
		assertEquals(300L, watermarks.observe(id, 10, 1000L).spent);
	}

	@Test
	public void observe_isIdempotentOnReplay()
	{
		FillWatermarks watermarks = new FillWatermarks();
		OfferIdentity id = OfferIdentity.of(0, 7777, true, 1);
		watermarks.observe(id, 7, 700L);

		// A login burst re-feeds the same cumulative; it carries no new information.
		assertEquals(0, watermarks.observe(id, 7, 700L).quantity);
		assertEquals(0L, watermarks.observe(id, 7, 700L).spent);
	}

	@Test
	public void observe_neverRegressesOnALowerCumulative()
	{
		FillWatermarks watermarks = new FillWatermarks();
		OfferIdentity id = OfferIdentity.of(0, 7777, true, 1);
		watermarks.observe(id, 7, 700L);

		assertEquals("a stale lower snapshot reports no fill", 0, watermarks.observe(id, 4, 400L).quantity);
		assertEquals("and does not lower the mark", 0, watermarks.observe(id, 7, 700L).quantity);
	}

	@Test
	public void advanceGeneration_startsAFreshBaselineForAReusedSlot()
	{
		FillWatermarks watermarks = new FillWatermarks();
		OfferIdentity first = OfferIdentity.of(0, 7777, true, watermarks.generationFor(0));
		watermarks.observe(first, 10, 1000L);

		watermarks.advanceGeneration(0);
		OfferIdentity second = OfferIdentity.of(0, 7777, true, watermarks.generationFor(0));

		assertNotEquals(first, second);
		assertEquals("a new order in a reused slot counts from zero",
			5, watermarks.observe(second, 5, 500L).quantity);
	}

	@Test
	public void mergeFrom_neverLowersAWatermark()
	{
		FillWatermarks watermarks = new FillWatermarks();
		OfferIdentity id = OfferIdentity.of(0, 7777, true, 1);
		watermarks.observe(id, 4, 400L);

		// A persisted snapshot written before that fill. Restoring it must not rewind progress,
		// or the next observation re-reports fills already sent.
		Map<String, long[]> stale = new HashMap<>();
		stale.put(id.toString(), new long[]{0L, 0L});
		watermarks.mergeFrom(stale);

		assertEquals("a stale restore cannot rewind the mark", 0, watermarks.observe(id, 4, 400L).quantity);
	}

	@Test
	public void generation_survivesARestart_soAReusedSlotDoesNotInheritAFinishedMark()
	{
		FillWatermarks before = new FillWatermarks();
		OfferIdentity finished = OfferIdentity.of(0, 7777, true, before.generationFor(0));
		before.observe(finished, 10, 1000L);
		before.advanceGeneration(0);

		// A restart: only what export() carries survives.
		FillWatermarks after = new FillWatermarks();
		after.mergeFrom(before.export());

		OfferIdentity next = OfferIdentity.of(0, 7777, true, after.generationFor(0));
		assertNotEquals("a new order must not reuse a finished order's identity", finished, next);
		assertEquals("its fills must still be reported", 5, after.observe(next, 5, 500L).quantity);
	}

	@Test
	public void generation_neverRewindsOnAStaleRestore()
	{
		FillWatermarks watermarks = new FillWatermarks();
		watermarks.advanceGeneration(0);
		watermarks.advanceGeneration(0);
		int current = watermarks.generationFor(0);

		// A snapshot written two turnovers ago must not roll the slot backwards.
		watermarks.mergeFrom(new FillWatermarks().export());

		assertEquals("generation only ever moves forward", current, watermarks.generationFor(0));
	}

	@Test
	public void mergeFrom_adoptsMarksTheSessionHasNotSeen()
	{
		FillWatermarks watermarks = new FillWatermarks();
		OfferIdentity id = OfferIdentity.of(0, 7777, true, 1);

		Map<String, long[]> restored = new HashMap<>();
		restored.put(id.toString(), new long[]{6L, 600L});
		watermarks.mergeFrom(restored);

		assertEquals("progress from a previous session is adopted", 1, watermarks.observe(id, 7, 700L).quantity);
	}
}

package com.flipsmart.trading;

import com.flipsmart.util.BuyPriceLookup;
import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import org.junit.Assume;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.Parameterized;

import java.io.IOException;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.DirectoryStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Session-corpus regression harness.
 *
 * <p>Replays each fixture's {@code timeline} — slot observations interleaved with hops and
 * relogs — through the real offer store and offline-sync service, then asserts the fixture's
 * {@code expect} block. Complements the fill-level golden corpus, which cannot express the
 * session lifecycle.</p>
 *
 * <p>Adding a case is one file: drop the JSON into {@code src/test/resources/session_corpus/};
 * it is auto-discovered.</p>
 */
@RunWith(Parameterized.class)
public class SessionCorpusTest
{
	private static final Path FIXTURES_DIR = Paths.get("src", "test", "resources", "session_corpus");
	private static final Gson GSON = new Gson();

	private final String name;
	private final JsonObject fixture;

	public SessionCorpusTest(String name, JsonObject fixture)
	{
		this.name = name;
		this.fixture = fixture;
	}

	@Parameterized.Parameters(name = "{0}")
	public static List<Object[]> fixtures() throws IOException
	{
		List<Object[]> cases = new ArrayList<>();
		try (DirectoryStream<Path> stream = Files.newDirectoryStream(FIXTURES_DIR, "*.json"))
		{
			for (Path path : stream)
			{
				try (Reader reader = Files.newBufferedReader(path, StandardCharsets.UTF_8))
				{
					JsonObject obj = GSON.fromJson(reader, JsonObject.class);
					String name = obj.has("name")
						? obj.get("name").getAsString() : path.getFileName().toString();
					cases.add(new Object[]{name, obj});
				}
			}
		}
		cases.sort((a, b) -> ((String) a[0]).compareTo((String) b[0]));
		return cases;
	}

	@Test
	public void corpusIsNonTrivial()
	{
		// Guards against a silently-empty resource dir masking a green run.
		assertTrue("[" + name + "] fixture must carry a timeline", fixture.has("timeline"));
	}

	@Test
	public void timelineMatchesExpectations()
	{
		Assume.assumeFalse("known failure pending absolute-merge",
			fixture.has("known_failure") && fixture.get("known_failure").getAsBoolean());

		SessionCorpusHarness.Result result = SessionCorpusHarness.run(fixture);
		JsonObject expect = fixture.getAsJsonObject("expect");

		assertBuyBasis(expect, result);
		assertLiveSlots(expect, result);
		assertReportedFills(expect, result);
	}

	private void assertBuyBasis(JsonObject expect, SessionCorpusHarness.Result result)
	{
		if (!expect.has("buy_basis"))
		{
			return;
		}
		for (Map.Entry<String, JsonElement> e : expect.getAsJsonObject("buy_basis").entrySet())
		{
			int itemId = Integer.parseInt(e.getKey());
			// Null cycle basis: the harness drives the store directly, so no fills reach a ledger.
			// This assertion is deliberately about what the offer records alone can resolve.
			Long basis = BuyPriceLookup.findAverageBuyPriceWithFallback(
				null, null, result.store.forItem(itemId), itemId);
			assertEquals("[" + name + "] buy basis for item " + itemId,
				Long.valueOf(e.getValue().getAsLong()), basis);
		}
	}

	private void assertLiveSlots(JsonObject expect, SessionCorpusHarness.Result result)
	{
		if (!expect.has("live_slot_items"))
		{
			return;
		}
		for (Map.Entry<String, JsonElement> e : expect.getAsJsonObject("live_slot_items").entrySet())
		{
			int slot = Integer.parseInt(e.getKey());
			assertNotNull("[" + name + "] slot " + slot + " must hold a live record",
				result.store.bySlot(slot));
			assertEquals("[" + name + "] item in slot " + slot,
				e.getValue().getAsInt(), result.store.bySlot(slot).getItemId());
		}
	}

	private void assertReportedFills(JsonObject expect, SessionCorpusHarness.Result result)
	{
		if (!expect.has("reported_fills"))
		{
			return;
		}
		List<String> actual = new ArrayList<>();
		for (OfferEvent event : result.reportedFills)
		{
			actual.add(event.record.getItemId() + ":" + event.record.isBuy()
				+ ":" + event.newlyFilledQuantity);
		}
		List<String> wanted = new ArrayList<>();
		for (JsonElement element : expect.getAsJsonArray("reported_fills"))
		{
			JsonObject f = element.getAsJsonObject();
			wanted.add(f.get("item_id").getAsInt() + ":" + f.get("is_buy").getAsBoolean()
				+ ":" + f.get("quantity").getAsInt());
		}
		assertEquals("[" + name + "] reported fills", wanted, actual);
	}
}

package com.flipsmart.trading;

import com.flipsmart.FlipSmartApiClient;
import com.flipsmart.PlayerSession;
import com.flipsmart.api.dto.Dtos.TransactionRequest;
import com.flipsmart.domain.offer.OfferRecord;
import com.flipsmart.domain.offer.OfferState;
import com.flipsmart.domain.offer.OfferTransition;

import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

import java.util.List;
import java.util.Optional;
import java.util.concurrent.CompletableFuture;

import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Send-layer behaviour of the round-trip guard: a duplicate/phantom closing fill that the
 * peek-based dedup cannot catch must not be forwarded to the backend (#1054).
 */
public class TransactionLoggerTest
{
    private static final String RSN = "Zezima";
    private static final int ITEM = 4151;

    private FlipSmartApiClient apiClient;
    private TransactionLogger logger;

    @Before
    public void setUp()
    {
        apiClient = mock(FlipSmartApiClient.class);
        when(apiClient.recordTransactionAsync(any(TransactionRequest.class)))
            .thenReturn(CompletableFuture.completedFuture(null));
        PlayerSession session = mock(PlayerSession.class);
        when(session.getRecommendedPrice(anyInt())).thenReturn(null);
        RoundTripLedger ledger = new RoundTripLedger();
        logger = new TransactionLogger(apiClient, session, () -> Optional.of(RSN), ledger);
    }

    /** A fully-filled offer whose only fill delivery carries the whole quantity. */
    private OfferRecord completed(long offerId, int slot, boolean buy, int qty, int price, long createdAt)
    {
        return OfferRecord.newOffer(offerId, slot, ITEM, "Abyssal whip", buy, qty, price, createdAt)
            .withFill(qty, (long) qty * price, OfferState.FILLED, createdAt + 1);
    }

    private void deliverFill(OfferRecord r, int newlyFilled, long newlySpent)
    {
        logger.onOfferEvent(new OfferEvent(OfferTransition.Kind.COMPLETED, r, newlyFilled, newlySpent, 1));
    }

    private List<TransactionRequest> sentRequests(int expectedCount)
    {
        ArgumentCaptor<TransactionRequest> cap = ArgumentCaptor.forClass(TransactionRequest.class);
        verify(apiClient, times(expectedCount)).recordTransactionAsync(cap.capture());
        return cap.getAllValues();
    }

    @Test
    public void duplicateClosingFill_underChurnedOfferId_isNotForwarded()
    {
        // Clean lot on slot 0: buy 10 then sell 10 closes the cycle.
        deliverFill(completed(1L, 0, true, 10, 100, 1_000L), 10, 1_000L);
        deliverFill(completed(2L, 0, false, 10, 110, 2_000L), 10, 1_100L);

        // The exact closing sell is re-delivered under a CHURNED offer_id (a Collect re-detect):
        // same slot + cumulative, new offer_id + timestamp. The peek-based dedup can't catch it —
        // the real close already advanced the cycle, so this fill peeks a different round-trip id
        // and its normalized key differs. Only the ledger guard recognises it.
        deliverFill(completed(3L, 0, false, 10, 110, 3_000L), 10, 1_100L);

        // Two sends (buy + sell), not three — the phantom was dropped.
        List<TransactionRequest> sent = sentRequests(2);
        assertEquals("buy and sell of the one lot both forwarded", 2, sent.size());
        assertEquals("buy and sell share the round trip id",
            sent.get(0).roundTripId, sent.get(1).roundTripId);
    }

    @Test
    public void timeframeSupplier_tagsRecordedTransactions()
    {
        logger.setTimeframeSupplier(() -> "12h");
        deliverFill(completed(1L, 0, true, 10, 100, 1_000L), 10, 1_000L);
        assertEquals("configured timeframe is tagged on the transaction",
            "12h", sentRequests(1).get(0).timeframe);
    }

    @Test
    public void noTimeframeSupplier_leavesTransactionUntagged()
    {
        deliverFill(completed(1L, 0, true, 10, 100, 1_000L), 10, 1_000L);
        assertEquals("untagged by default", null, sentRequests(1).get(0).timeframe);
    }

    @Test
    public void genuineRepeatRoundTrip_forwardsEveryFill()
    {
        // buy -> sell (closes) -> genuine new buy (opens next cycle) -> sell (closes) on the same slot.
        deliverFill(completed(1L, 0, true, 10, 100, 1_000L), 10, 1_000L);
        deliverFill(completed(2L, 0, false, 10, 110, 2_000L), 10, 1_100L);
        deliverFill(completed(3L, 0, true, 10, 100, 3_000L), 10, 1_000L);
        deliverFill(completed(4L, 0, false, 10, 110, 4_000L), 10, 1_100L);

        // All four forwarded — the guard only suppresses an immediate byte-identical re-delivery,
        // never a genuine repeat separated by a real intervening fill.
        List<TransactionRequest> sent = sentRequests(4);
        assertEquals(4, sent.size());
        assertEquals("first lot's buy and sell share a cycle",
            sent.get(0).roundTripId, sent.get(1).roundTripId);
        assertEquals("second lot's buy and sell share a cycle",
            sent.get(2).roundTripId, sent.get(3).roundTripId);
        assertEquals("the two round trips get distinct ids",
            (int) sent.get(0).roundTripId + 1, (int) sent.get(2).roundTripId);
    }

    @Test
    public void concurrentSameItemTwoSlots_forwardsBothClosingFills()
    {
        // Two open buys of the same item in different slots — one round trip across slots.
        deliverFill(completed(1L, 0, true, 10, 100, 1_000L), 10, 1_000L);
        deliverFill(completed(2L, 1, true, 5, 100, 1_500L), 5, 500L);
        // Liquidate both; the guard must not treat the slot-1 close as a duplicate of the slot-0 one.
        deliverFill(completed(3L, 0, false, 10, 110, 2_000L), 10, 1_100L);
        deliverFill(completed(4L, 1, false, 5, 110, 2_500L), 5, 550L);

        List<TransactionRequest> sent = sentRequests(4);
        assertEquals("all four fills across two slots forwarded", 4, sent.size());
    }

    @Test
    public void recordOfflineSellFill_postsFillWithDeterministicKey()
    {
        OfferRecord sell = completed(87L, 0, false, 10, 110, 2_000L);
        logger.recordOfflineSellFill(sell);

        TransactionRequest t = sentRequests(1).get(0);
        assertEquals("must be a sell", false, t.isBuy);
        assertEquals("full offline-collected quantity", 10, t.quantity);
        assertEquals("price from spent / filled", 110, t.pricePerItem);
        assertEquals("canonical FILL idempotency key",
            TransactionLogger.idempotencyKey(RSN, sell, TransactionLogger.Type.FILL), t.idempotencyKey);
    }

    @Test
    public void recordOfflineSellFill_ignoresBuyAndZeroFill()
    {
        logger.recordOfflineSellFill(completed(1L, 0, true, 10, 100, 1_000L));
        logger.recordOfflineSellFill(
            OfferRecord.newOffer(2L, 0, ITEM, "Abyssal whip", false, 10, 110, 2_000L));
        verify(apiClient, never()).recordTransactionAsync(any(TransactionRequest.class));
    }

    @Test
    public void sellFill_firesSessionRefreshCallback_butBuyDoesNot()
    {
        int[] fired = {0};
        logger.setOnSellRecorded(() -> fired[0]++);

        deliverFill(completed(1L, 0, true, 10, 100, 1_000L), 10, 1_000L);
        assertEquals("a buy fill does not refresh session P&L", 0, fired[0]);

        deliverFill(completed(2L, 0, false, 10, 110, 2_000L), 10, 1_100L);
        assertEquals("a sell fill refreshes session P&L once the push resolves", 1, fired[0]);
    }
}

package com.flipsmart.trading;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;

import java.io.IOException;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.nio.file.DirectoryStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;

import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.Parameterized;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Mirrored golden-corpus regression harness.
 *
 * Replays the shared production offer-event fixtures — the same JSON files the
 * backend golden-corpus suite asserts against — through the plugin's
 * {@link RoundTripLedger} and asserts its zero-crossing round-trip
 * segmentation. Distinct ids for back-to-back same-item round trips are the
 * plugin-side guard against the fill over-count class.
 *
 * Each fixture's {@code plugin.round_trip_ids} list is the expected id
 * {@link RoundTripLedger#recordFill} returns for each event, in order. A
 * fixture whose invariant is backend-only (e.g. Collect-fill idempotency)
 * carries {@code plugin.skip} and is not replayed here.
 *
 * Adding a case is one file: drop the shared JSON into
 * {@code src/test/resources/golden_corpus/}; it is auto-discovered.
 */
@RunWith(Parameterized.class)
public class GoldenCorpusTest
{
    private static final Path FIXTURES_DIR = Paths.get("src", "test", "resources", "golden_corpus");
    private static final Gson GSON = new Gson();

    private final String name;
    private final JsonObject fixture;

    public GoldenCorpusTest(String name, JsonObject fixture)
    {
        this.name = name;
        this.fixture = fixture;
    }

    @Parameterized.Parameters(name = "{0}")
    public static List<Object[]> fixtures() throws IOException
    {
        List<Object[]> cases = new ArrayList<>();
        try (DirectoryStream<Path> stream = Files.newDirectoryStream(FIXTURES_DIR, "*.json"))
        {
            for (Path path : stream)
            {
                try (Reader reader = Files.newBufferedReader(path, StandardCharsets.UTF_8))
                {
                    JsonObject obj = GSON.fromJson(reader, JsonObject.class);
                    String name = obj.has("name") ? obj.get("name").getAsString() : path.getFileName().toString();
                    cases.add(new Object[]{name, obj});
                }
            }
        }
        cases.sort((a, b) -> ((String) a[0]).compareTo((String) b[0]));
        return cases;
    }

    @Test
    public void corpusIsNonTrivial()
    {
        // Guards against a silently-empty resource dir masking a green run.
        assertTrue("golden corpus fixtures should be present", fixture.has("events"));
    }

    @Test
    public void roundTripSegmentationMatchesFixture()
    {
        JsonObject plugin = fixture.has("plugin") ? fixture.getAsJsonObject("plugin") : new JsonObject();
        if (plugin.has("skip"))
        {
            return;
        }

        JsonArray expectedIds = plugin.getAsJsonArray("round_trip_ids");
        assertTrue(
            "[" + name + "] fixture must supply plugin.round_trip_ids or plugin.skip",
            expectedIds != null);

        RoundTripLedger ledger = new RoundTripLedger();
        JsonArray events = fixture.getAsJsonArray("events");
        assertEquals(
            "[" + name + "] round_trip_ids length must match event count",
            events.size(), expectedIds.size());

        for (int i = 0; i < events.size(); i++)
        {
            JsonObject event = events.get(i).getAsJsonObject();
            String rsn = event.has("rsn") ? event.get("rsn").getAsString() : "TestPlayer";
            int itemId = event.get("item_id").getAsInt();
            boolean isBuy = event.get("is_buy").getAsBoolean();
            int quantity = event.get("quantity").getAsInt();

            Integer actualId = ledger.recordFill(rsn, itemId, isBuy, quantity);
            JsonElement expected = expectedIds.get(i);
            assertEquals(
                "[" + name + "] event[" + i + "] round-trip id",
                Integer.valueOf(expected.getAsInt()), actualId);
        }
    }
}

package com.flipsmart.trading;

import com.flipsmart.GpAnswer;
import com.flipsmart.ActiveFlipTracker;
import com.flipsmart.GEHistoryService;
import com.flipsmart.OfflineSyncService;
import com.flipsmart.PlayerSession;
import com.flipsmart.domain.offer.OfferSignal;
import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.ItemComposition;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Replays a session-corpus timeline through the real {@link OfferStore} and
 * {@link OfflineSyncService}. Unlike the fill-level golden corpus, a timeline can express the
 * session lifecycle — world hops, relogs and offline gaps — which is where retention and
 * fill-accounting defects actually surface.
 */
final class SessionCorpusHarness
{
	private static final String CONFIG_GROUP = "flipsmart";
	private static final int GE_SLOT_COUNT = 8;

	static final class Result
	{
		final OfferStore store;
		final List<OfferEvent> reportedFills;

		Result(OfferStore store, List<OfferEvent> reportedFills)
		{
			this.store = store;
			this.reportedFills = reportedFills;
		}
	}

	private SessionCorpusHarness()
	{
		// Test helper - prevent instantiation
	}

	static Result run(JsonObject fixture)
	{
		// The services age records against the wall clock, so timeline offsets anchor to it.
		long base = System.currentTimeMillis();
		String rsn = fixture.has("rsn") ? fixture.get("rsn").getAsString() : "TestPlayer";

		OfferStore store = new OfferStore();
		List<OfferEvent> fills = new ArrayList<>();
		store.addListener(e ->
		{
			if (e.newlyFilledQuantity > 0)
			{
				fills.add(e);
			}
		});

		PlayerSession session = mock(PlayerSession.class);
		when(session.getRsn()).thenReturn(rsn);
		when(session.getCollectedItemIds()).thenReturn(Collections.emptySet());

		Map<String, String> configStore = new HashMap<>();
		ConfigManager configManager = mock(ConfigManager.class);
		doAnswer(inv ->
		{
			configStore.put(inv.getArgument(1), inv.getArgument(2));
			return null;
		}).when(configManager).setConfiguration(eq(CONFIG_GROUP), anyString(), any());
		doAnswer(inv ->
		{
			configStore.remove(inv.<String>getArgument(1));
			return null;
		}).when(configManager).unsetConfiguration(eq(CONFIG_GROUP), anyString());
		when(configManager.getConfiguration(eq(CONFIG_GROUP), anyString()))
			.thenAnswer(inv -> configStore.get(inv.<String>getArgument(1)));

		Client client = mock(Client.class);
		ClientThread clientThread = mock(ClientThread.class);
		doAnswer(inv ->
		{
			inv.<Runnable>getArgument(0).run();
			return null;
		}).when(clientThread).invokeLater(any(Runnable.class));

		// Stubbed up front: building a mock inside a when(...) argument throws
		// UnfinishedStubbingException.
		ItemComposition anyComposition = mock(ItemComposition.class);
		when(anyComposition.getName()).thenReturn("item");
		ItemManager itemManager = mock(ItemManager.class);
		when(itemManager.getItemComposition(anyInt())).thenReturn(anyComposition);

		// Everything in the environment survives a restart because it stands in for the client
		// and its config file. The Session below is process state, rebuilt from the config blob
		// alone when the timeline restarts.
		Environment env = new Environment(session, configManager, client, clientThread,
			itemManager, fills);
		Session live = new Session();
		live.rebuild(env);

		for (JsonElement element : fixture.getAsJsonArray("timeline"))
		{
			applyEvent(element.getAsJsonObject(), base, live, env);
		}
		return new Result(live.store, fills);
	}

	/**
	 * The client/config/item stand-ins a real restart would rebuild the process against. Grouped
	 * so the harness can pass "what a restart reads" as a single unit.
	 */
	private static final class Environment
	{
		final PlayerSession session;
		final ConfigManager configManager;
		final Client client;
		final ClientThread clientThread;
		final ItemManager itemManager;
		final List<OfferEvent> fills;

		Environment(PlayerSession session, ConfigManager configManager, Client client,
			ClientThread clientThread, ItemManager itemManager, List<OfferEvent> fills)
		{
			this.session = session;
			this.configManager = configManager;
			this.client = client;
			this.clientThread = clientThread;
			this.itemManager = itemManager;
			this.fills = fills;
		}
	}

	/**
	 * The process-local half of the plugin: the offer store and the service that reconciles into
	 * it. A restart replaces both, which is what distinguishes it from a relog — a relog keeps the
	 * running instance and only loses the GE slots, so anything held outside the store (the fill
	 * watermarks, for one) survives it.
	 */
	private static final class Session
	{
		private OfferStore store;
		private OfflineSyncService service;

		void rebuild(Environment env)
		{
			store = new OfferStore();
			store.addListener(e ->
			{
				if (e.newlyFilledQuantity > 0)
				{
					env.fills.add(e);
				}
			});
			service = new OfflineSyncService(
				env.session,
				env.configManager,
				new Gson(),
				env.client,
				env.clientThread,
				mock(ActiveFlipTracker.class),
				mock(GEHistoryService.class),
				store,
				env.itemManager,
				new RoundTripLedger(),
				mock(TransactionLogger.class));
		}
	}

	private static void applyEvent(JsonObject event, long base, Session live, Environment env)
	{
		long at = base + event.get("at_seconds").getAsLong() * 1000L;
		String type = event.get("type").getAsString();

		if ("observe".equals(type))
		{
			live.store.apply(toSignal(event), at);
			return;
		}

		// A hop and a relog both persist then preload; only a relog loses the in-memory store.
		// "persist": false models the window where the RSN cannot be resolved and the newer
		// store state never reaches disk, so the preload reattaches an older persisted record.
		if (!event.has("persist") || event.get("persist").getAsBoolean())
		{
			live.service.persistOfferState();
		}
		if ("relog".equals(type))
		{
			live.store.importRecords(Collections.emptyList());
		}
		if ("restart".equals(type))
		{
			// Nothing but the config blob crosses a process boundary.
			live.rebuild(env);
		}
		// Built before the stubbing call: creating mocks inside a when(...) argument throws
		// UnfinishedStubbingException.
		GrandExchangeOffer[] snapshot = toSnapshot(event);
		when(env.client.getGrandExchangeOffers()).thenReturn(snapshot);
		live.service.preloadPersistedOffers();
	}

	private static OfferSignal toSignal(JsonObject e)
	{
		int itemId = e.get("item_id").getAsInt();
		return new OfferSignal(
			e.get("slot").getAsInt(),
			GrandExchangeOfferState.valueOf(e.get("state").getAsString()),
			itemId,
			"i" + itemId,
			e.get("total").getAsInt(),
			e.get("price").getAsInt(),
			e.get("sold").getAsInt(),
			e.get("spent").getAsLong());
	}

	/**
	 * The GE snapshot as the client would report it: {@code null} when it is not readable yet,
	 * otherwise a full-length array whose unused slots read EMPTY.
	 */
	private static GrandExchangeOffer[] toSnapshot(JsonObject event)
	{
		if (event.has("ge_readable") && !event.get("ge_readable").getAsBoolean())
		{
			return null;
		}

		GrandExchangeOffer empty = mock(GrandExchangeOffer.class);
		when(empty.getState()).thenReturn(GrandExchangeOfferState.EMPTY);
		GrandExchangeOffer[] slots = new GrandExchangeOffer[GE_SLOT_COUNT];
		Arrays.fill(slots, empty);

		JsonArray live = event.has("live_slots")
			? event.getAsJsonArray("live_slots") : new JsonArray();
		for (JsonElement element : live)
		{
			JsonObject s = element.getAsJsonObject();
			GrandExchangeOffer offer = mock(GrandExchangeOffer.class);
			when(offer.getState())
				.thenReturn(GrandExchangeOfferState.valueOf(s.get("state").getAsString()));
			when(offer.getItemId()).thenReturn(s.get("item_id").getAsInt());
			when(offer.getTotalQuantity()).thenReturn(s.get("total").getAsInt());
			when(offer.getPrice()).thenAnswer(GpAnswer.gp(s.get("price").getAsLong()));
			when(offer.getQuantitySold()).thenReturn(s.get("sold").getAsInt());
			when(offer.getSpent()).thenAnswer(GpAnswer.gp(s.get("spent").getAsLong()));
			slots[s.get("slot").getAsInt()] = offer;
		}
		return slots;
	}
}

package com.flipsmart.trading;

import com.flipsmart.domain.offer.OfferRecord;
import com.flipsmart.domain.offer.OfferState;

import org.junit.Before;
import org.junit.Test;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class RoundTripLedgerTest
{
    private static final String RSN = "Zezima";
    private static final int ITEM = 4151;

    private RoundTripLedger ledger;

    @Before
    public void setUp()
    {
        ledger = new RoundTripLedger();
    }

    @Test
    public void basis_isWeightedAcrossTheOpenCycle()
    {
        ledger.recordBuyBasis(RSN, ITEM, 10, 100);
        ledger.recordBuyBasis(RSN, ITEM, 10, 140);

        assertEquals(Long.valueOf(120), ledger.currentBasis(RSN, ITEM));
    }

    @Test
    public void basis_survivesAnExportImportRoundTrip()
    {
        // Persistence is the only thing that carries a position across a restart, and a position
        // whose basis does not come with it silently falls back to averaging across closed flips.
        ledger.recordFill(RSN, ITEM, true, 10);
        ledger.recordBuyBasis(RSN, ITEM, 10, 1736);

        RoundTripLedger restored = new RoundTripLedger();
        restored.importState(RSN, ledger.export(RSN));

        assertEquals("held quantity survives", 10, restored.heldQuantity(RSN, ITEM));
        assertEquals("so must the basis it depends on",
            Long.valueOf(1736), restored.currentBasis(RSN, ITEM));
    }

    @Test
    public void basis_isAbsentBeforeAnyBuy()
    {
        assertNull("an untouched item has no basis", ledger.currentBasis(RSN, ITEM));
    }

    @Test
    public void basis_resetsWhenTheCycleCloses()
    {
        ledger.recordBuyBasis(RSN, ITEM, 10, 100);
        ledger.recordFill(RSN, ITEM, true, 10);
        ledger.recordFill(RSN, ITEM, false, 10);   // fully liquidated: cycle closes

        assertNull("a closed cycle carries no basis", ledger.currentBasis(RSN, ITEM));

        ledger.recordBuyBasis(RSN, ITEM, 5, 200);
        assertEquals("the next cycle starts clean",
            Long.valueOf(200), ledger.currentBasis(RSN, ITEM));
    }

    @Test
    public void basis_survivesAPartialLiquidation()
    {
        ledger.recordBuyBasis(RSN, ITEM, 10, 100);
        ledger.recordFill(RSN, ITEM, true, 10);
        ledger.recordFill(RSN, ITEM, false, 3);    // holdings still 7, cycle stays open

        assertEquals("a partial sell does not disturb the buy-side basis",
            Long.valueOf(100), ledger.currentBasis(RSN, ITEM));
    }

    @Test
    public void basis_ignoresAZeroPrice()
    {
        // A placement row carries no price; folding it in would drag the average toward zero.
        ledger.recordBuyBasis(RSN, ITEM, 10, 0);

        assertNull("a priceless fill contributes no basis", ledger.currentBasis(RSN, ITEM));
    }

    @Test
    public void cleanTwoCycleSequence_producesTwoDistinctIds()
    {
        int buyLow = ledger.recordFill(RSN, ITEM, true, 10);
        int sellLow = ledger.recordFill(RSN, ITEM, false, 10);
        int buyHigh = ledger.recordFill(RSN, ITEM, true, 10);
        int sellHigh = ledger.recordFill(RSN, ITEM, false, 10);

        assertEquals("buy and sell of the same lot share the cycle", buyLow, sellLow);
        assertEquals("buy and sell of the second lot share the cycle", buyHigh, sellHigh);
        assertNotEquals("liquidating the first lot starts a new cycle for the second",
            sellLow, buyHigh);
    }

    @Test
    public void partialFillsWithinACycle_shareTheSameId()
    {
        int fill1 = ledger.recordFill(RSN, ITEM, true, 3);
        int fill2 = ledger.recordFill(RSN, ITEM, true, 2);
        int sellPartial = ledger.recordFill(RSN, ITEM, false, 4);
        int sellRest = ledger.recordFill(RSN, ITEM, false, 1);

        assertEquals(fill1, fill2);
        assertEquals(fill1, sellPartial);
        assertEquals(fill1, sellRest);
    }

    @Test
    public void overSell_isTreatedAsLiquidationAndStartsNewCycle()
    {
        int buy = ledger.recordFill(RSN, ITEM, true, 5);
        // Sells more than the ledger has recorded as held (e.g. externally-sourced stock) —
        // still closes the cycle rather than leaving heldQuantity permanently negative.
        int oversell = ledger.recordFill(RSN, ITEM, false, 8);
        assertEquals(buy, oversell);

        int nextBuy = ledger.recordFill(RSN, ITEM, true, 1);
        assertNotEquals("the cycle after an over-sell is a fresh one", oversell, nextBuy);
    }

    @Test
    public void oversellPastZeroDoesNotRepeatedlyReclose()
    {
        // A fully-liquidated position (held at zero) that keeps receiving sell fills — overselling
        // externally-sourced stock, or a ledger drifted low — must not re-close the cycle on every
        // fill and run the round-trip id away.
        ledger.recordFill(RSN, ITEM, 0, true, 5, 5, true);
        int sell = ledger.recordFill(RSN, ITEM, 0, false, 5, 5, true);   // held 5 -> 0: one genuine close
        int afterFirstClose = ledger.peekRoundTripId(RSN, ITEM);
        assertNotEquals("the genuine liquidation closes the cycle once", sell, afterFirstClose);

        // Extra sell fills arriving while held is already zero must NOT advance the cycle again.
        ledger.recordFill(RSN, ITEM, 1, false, 100, 100, false);
        ledger.recordFill(RSN, ITEM, 1, false, 100, 200, false);
        assertEquals("overselling past zero does not repeatedly re-close the cycle",
            afterFirstClose, (int) ledger.peekRoundTripId(RSN, ITEM));
    }

    @Test
    public void duplicateSellFill_cannotPrematurelyAdvanceCycle()
    {
        // One clean lot on slot 0: buy 10, sell 10 — held returns to zero, cycle closes.
        int buy = ledger.recordFill(RSN, ITEM, 0, true, 10, 10, true);
        int sell = ledger.recordFill(RSN, ITEM, 0, false, 10, 10, true);
        assertEquals("buy and sell of one lot share the round trip", buy, sell);

        int afterLiquidation = ledger.peekRoundTripId(RSN, ITEM);
        assertNotEquals("a clean liquidation opens the next cycle", sell, afterLiquidation);

        // A phantom re-delivery of the exact closing sell (same slot + direction + cumulative) reaches
        // the ledger before client-side suppression catches it. It must NOT drive held negative and
        // advance the cycle a second time.
        int phantom = ledger.recordFill(RSN, ITEM, 0, false, 10, 10, true);
        assertEquals("the duplicate is ignored and returns the still-open cycle id",
            afterLiquidation, phantom);
        assertEquals("the duplicate did not advance the cycle",
            afterLiquidation, (int) ledger.peekRoundTripId(RSN, ITEM));

        // The next genuine buy opens the un-poisoned cycle the phantom tried to skip past.
        int nextBuy = ledger.recordFill(RSN, ITEM, 0, true, 10, 10, true);
        assertEquals("the round trip after a phantom is the one the phantom tried to skip",
            afterLiquidation, nextBuy);
    }

    @Test
    public void concurrentSameItemInTwoSlots_shareCycleAndAreNotFalselyDeduped()
    {
        int buyA = ledger.recordFill(RSN, ITEM, 0, true, 10, 10, true);
        int buyB = ledger.recordFill(RSN, ITEM, 1, true, 5, 5, true);
        assertEquals("two open buys of the same item are one round trip", buyA, buyB);

        int sellA = ledger.recordFill(RSN, ITEM, 0, false, 10, 10, true);
        assertEquals("selling one slot while the other is still open stays in the cycle",
            buyA, sellA);

        int sellB = ledger.recordFill(RSN, ITEM, 1, false, 5, 5, true);
        assertEquals("only the final zero-cross closes it — still the same round trip",
            buyA, sellB);

        int next = ledger.peekRoundTripId(RSN, ITEM);
        assertNotEquals("the fully liquidated position opens the next cycle", sellB, next);
    }

    @Test
    public void identicalFillInASubsequentCycle_isNotFalselySuppressed()
    {
        ledger.recordFill(RSN, ITEM, 0, true, 10, 10, true);
        int firstSell = ledger.recordFill(RSN, ITEM, 0, false, 10, 10, true);

        // A genuine new position reusing the same slot and quantity builds held again: completing the
        // first lot reset slot 0's baselines, so the new cycle's fills are absorbed from zero —
        // suppression only ever catches a re-delivery of an already-absorbed cumulative within an
        // open offer.
        int secondBuy = ledger.recordFill(RSN, ITEM, 0, true, 10, 10, true);
        assertNotEquals("the new cycle is distinct from the closed one", firstSell, secondBuy);

        int secondSell = ledger.recordFill(RSN, ITEM, 0, false, 10, 10, true);
        assertEquals("the genuine repeat sell is applied within its own cycle",
            secondBuy, secondSell);

        int third = ledger.peekRoundTripId(RSN, ITEM);
        assertNotEquals("the genuine repeat still closes its cycle normally", secondSell, third);
    }

    @Test
    public void closingOneSlotDoesNotWipeAStillFillingSiblingSlot()
    {
        // Same item in two slots: slot 0 buys 100 (offer complete), slot 1 buys 100 but is STILL
        // FILLING (offer not complete), so slot 1's baseline must be retained.
        ledger.recordFill(RSN, ITEM, 0, true, 100, 100, true);
        ledger.recordFill(RSN, ITEM, 1, true, 100, 100, false);

        // A 200-unit sell on slot 0 liquidates the position: held hits zero and the cycle closes while
        // slot 1's buy is still open. Resetting every slot on close (rather than only completed offers'
        // slots) would wipe slot 1's baseline, so its next fill would re-count its whole cumulative.
        ledger.recordFill(RSN, ITEM, 0, false, 200, 200, true);

        // slot 1's buy fills 50 more (cumulative 100 -> 150): only 50 new units should enter held.
        ledger.recordFill(RSN, ITEM, 1, true, 50, 150, true);

        // If the sibling baseline survived, held is exactly 50, so selling 50 closes the next cycle.
        // If it was wiped, held would be 150 and this sell would leave 100 open — no close.
        int sellRt = ledger.recordFill(RSN, ITEM, 1, false, 50, 50, true);
        int after = ledger.peekRoundTripId(RSN, ITEM);
        assertNotEquals("a still-filling sibling slot keeps its baseline through another slot's close",
            sellRt, after);
    }

    @Test
    public void relogDoesNotDoubleCountAnOpenBuy()
    {
        // Session 1: a still-open buy fills to cumulative 1324 on slot 4 — held becomes 1324. Not
        // complete, so its baseline is retained for the re-feed to match against.
        ledger.recordFill(RSN, ITEM, 4, true, 1324, 1324, false);

        // Persist + restart (relog / rebuild): held, cycle, and per-slot absorbed cumulative restore.
        Map<Integer, RoundTripLedger.Entry> exported = ledger.export(RSN);
        RoundTripLedger restarted = new RoundTripLedger();
        restarted.importState(RSN, exported);

        // Login reconciliation re-feeds the still-open offer's full current cumulative, because the
        // rebuilt OfferStore has no baseline yet and the GE signal looks like a fresh 1324 fill. A
        // relog mints a fresh offer_id for the slot, so the guard must match on (slot, cumulative)
        // alone — never offer_id — or this is added on top of the restored held (the double-count).
        restarted.recordFill(RSN, ITEM, 4, true, 1324, 1324, false);

        // Proof the true held is still 1324, not 2648: selling exactly 1324 (completing) closes the cycle.
        int cycleBefore = restarted.peekRoundTripId(RSN, ITEM);
        restarted.recordFill(RSN, ITEM, 4, false, 1324, 1324, true);
        int cycleAfter = restarted.peekRoundTripId(RSN, ITEM);
        assertNotEquals("selling the true held must close the round trip — no relog double-count",
            cycleBefore, cycleAfter);
    }

    @Test
    public void differentItems_areTrackedIndependently()
    {
        int itemABuy = ledger.recordFill(RSN, ITEM, true, 5);
        int itemBBuy = ledger.recordFill(RSN, 1305, true, 5);
        assertEquals("a fresh item starts at the same initial cycle id as any other fresh item",
            itemABuy, itemBBuy);

        ledger.recordFill(RSN, ITEM, false, 5);
        int itemBStillOpen = ledger.recordFill(RSN, 1305, true, 1);
        assertEquals("liquidating item A must not roll item B's still-open cycle forward",
            itemBBuy, itemBStillOpen);
    }

    @Test
    public void nullOrEmptyRsn_returnsNullAndDoesNotThrow()
    {
        assertNull(ledger.recordFill(null, ITEM, true, 5));
        assertNull(ledger.recordFill("", ITEM, true, 5));
        assertNull(ledger.peekRoundTripId(null, ITEM));
    }

    @Test
    public void peekRoundTripId_doesNotMutateHeldQuantityOrCycle()
    {
        int buy = ledger.recordFill(RSN, ITEM, true, 5);
        Integer peeked = ledger.peekRoundTripId(RSN, ITEM);
        assertEquals(Integer.valueOf(buy), peeked);

        // Peeking repeatedly must never itself close the cycle.
        ledger.peekRoundTripId(RSN, ITEM);
        ledger.peekRoundTripId(RSN, ITEM);
        int sell = ledger.recordFill(RSN, ITEM, false, 5);
        assertEquals("cycle unaffected by peeks", buy, sell);
    }

    @Test
    public void relogMidCycle_importedStatePreservesTheOpenId()
    {
        int buy = ledger.recordFill(RSN, ITEM, true, 7);

        // Simulate a plugin restart: persist the entry, build a fresh ledger, restore it.
        Map<Integer, RoundTripLedger.Entry> exported = ledger.export(RSN);
        assertFalse(exported.isEmpty());

        RoundTripLedger restarted = new RoundTripLedger();
        restarted.importState(RSN, exported);

        int sellAfterRelog = restarted.recordFill(RSN, ITEM, false, 7);
        assertEquals("the id from before the relog is preserved on the imported ledger",
            buy, sellAfterRelog);

        int nextCycleBuy = restarted.recordFill(RSN, ITEM, true, 1);
        assertNotEquals("a new cycle still starts correctly after the restored one closes",
            sellAfterRelog, nextCycleBuy);
    }

    @Test
    public void importState_withNullOrEmptyRsnOrEntries_isNoOp()
    {
        ledger.importState(null, Collections.singletonMap(ITEM, new RoundTripLedger.Entry(5, 1)));
        ledger.importState(RSN, null);
        ledger.importState(RSN, Collections.emptyMap());
        assertTrue("no state materialized for RSN from any no-op import call", ledger.isEmpty(RSN));
