    @Test
    public void relogMidCycle_preservesRoundTripIdFromPersistedLedgerState()
    {
        int itemId = 4151;

        // First "session": a buy fill opens a cycle on the shared ledger.
        TransactionLogger firstSession = newLogger(RSN);
        OfferRecord buy = OfferRecord.newOffer(1, 0, itemId, "Abyssal whip", true, 5, 1_000, 1L)
            .withFill(5, 5_000L, OfferState.FILLED, 2L);
        firstSession.onOfferEvent(new OfferEvent(OfferTransition.Kind.COMPLETED, buy, 5, 5_000L, 1));
        Integer openCycleId = captureAll().get(0).roundTripId;

        // Simulate a plugin restart: persist + restore the ledger, exactly as
        // OfflineSyncService's persistLedgerState/preloadLedgerState round-trip it.
        java.util.Map<Integer, RoundTripLedger.Entry> persisted = roundTripLedger.export(RSN);
        RoundTripLedger restoredLedger = new RoundTripLedger();
        restoredLedger.importState(RSN, persisted);

        reset(apiClient);
        when(apiClient.recordTransactionAsync(any(TransactionRequest.class)))
            .thenReturn(CompletableFuture.completedFuture(null));
        TransactionLogger secondSession = new TransactionLogger(apiClient, session,
            () -> Optional.of(RSN), restoredLedger);

        OfferRecord sell = OfferRecord.newOffer(2, 1, itemId, "Abyssal whip", false, 5, 1_200, 10L)
            .withFill(5, 6_000L, OfferState.FILLED, 11L);
        secondSession.onOfferEvent(new OfferEvent(OfferTransition.Kind.COMPLETED, sell, 5, 6_000L, 1));

        TransactionRequest sellReq = capture();
        assertEquals("the id opened before the relog is preserved after restoring the ledger",
            openCycleId, sellReq.roundTripId);
    }

    /**
     * The slot generation observed with a fill has to reach the backend, which uses it to
     * tell one order apart from the next order to occupy the same slot (#1211). Sending
     * nothing leaves the backend on its colliding round-trip + slot scope.
     */
    @Test
    public void fillForwardsTheSlotGenerationItWasObservedWith()
    {
        TransactionLogger logger = newLogger(RSN);
        OfferRecord r = OfferRecord.newOffer(5, 3, 4151, "Abyssal whip", true, 5, 2_000_000, 1700000000000L)
            .withFill(2, 4_000_000L, OfferState.PARTIAL_FILL, 1700000000500L);
        logger.onOfferEvent(new OfferEvent(OfferTransition.Kind.FILLED_DELTA, r, 2, 4_000_000L, 7));
        assertEquals(Integer.valueOf(7), capture().slotGeneration);
    }

    @Test
    public void placementForwardsTheSlotGeneration()
    {
        TransactionLogger logger = newLogger(RSN);
        OfferRecord r = OfferRecord.newOffer(7, 2, 1515, "Yew logs", false, 100, 300, 1700000000000L);
        logger.onOfferEvent(new OfferEvent(OfferTransition.Kind.PLACED, r, 0, 0, 4));
        assertEquals(Integer.valueOf(4), capture().slotGeneration);
    }

    /**
     * End-to-end through the real store: two consecutive orders in one slot must reach the
     * backend under different generations, otherwise the second order's early fills are
     * suppressed by the first order's watermark -- the #1211 failure.
     */
    @Test
    public void consecutiveOrdersInOneSlotSendDistinctGenerations()
    {
        final int waterOrbId = 571;
        final int natureRuneId = 561;

        OfferStore store = new OfferStore();
        store.addListener(newLogger(RSN)::onOfferEvent);

        store.apply(OfferEventMapper.toSignal(0, GrandExchangeOfferState.BUYING, waterOrbId,
            "Water orb", 10, 1736, 0, 0L), 1700000000000L);
        store.apply(OfferEventMapper.toSignal(0, GrandExchangeOfferState.BOUGHT, waterOrbId,
            "Water orb", 10, 1736, 10, 17360L), 1700000001000L);
        store.apply(OfferEventMapper.toSignal(0, GrandExchangeOfferState.EMPTY, waterOrbId,
            "Water orb", 0, 0, 0, 0L), 1700000002000L);
        store.apply(OfferEventMapper.toSignal(0, GrandExchangeOfferState.BUYING, natureRuneId,
            "Nature rune", 10, 200, 0, 0L), 1700000003000L);
        store.apply(OfferEventMapper.toSignal(0, GrandExchangeOfferState.BOUGHT, natureRuneId,
            "Nature rune", 10, 200, 10, 2000L), 1700000004000L);

        Integer firstOrder = null;
        Integer secondOrder = null;
        for (TransactionRequest req : captureAll())
        {
            if (req.itemId == waterOrbId)
            {
                firstOrder = req.slotGeneration;
            }
            else if (req.itemId == natureRuneId)
            {
                secondOrder = req.slotGeneration;
            }
        }
        assertNotNull("first order reported a generation", firstOrder);
        assertNotNull("second order reported a generation", secondOrder);
        assertNotEquals("a reused slot must not reuse its predecessor's identity", firstOrder, secondOrder);
    }
}

package com.flipsmart;

import com.flipsmart.domain.offer.OfferRecord;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The standalone AC5 sell-price recalc must defer to the /flips/adjustment ladder once
 * the ladder has begun stepping a sitting 12h sell down — otherwise the recalc re-anchors
 * the offer back up to the fresh overnight estimate and the two fight (the overlay shows
 * the laddered price while the GE screen shows the recalc'd one).
 */
public class TwelveHourSellRecalcTest
{
	private static final long HOUR = 3_600_000L;

	private static OfferRecord sell(long placedAtMillis)
	{
		return OfferRecord.newOffer(1L, 0, 4151, "Fremennik kilt", false, 3, 100, placedAtMillis);
	}

	@Test
	public void freshSell_ladderDoesNotOwnYet()
	{
		long now = 100 * HOUR;
		assertFalse("a sell listed under 6h ago is still in the rung-0 window",
			FlipSmartPlugin.ladderOwnsSell(sell(now - 5 * HOUR), now));
	}

	@Test
	public void sellOpenPastSixHours_ladderOwns()
	{
		long now = 100 * HOUR;
		assertTrue("past the 6h rung-1 boundary the ladder is stepping the price down",
			FlipSmartPlugin.ladderOwnsSell(sell(now - 7 * HOUR), now));
	}

	@Test
	public void noLiveSell_ladderDoesNotOwn()
	{
		assertFalse("a brand-new listing has no live sell yet — recalc may refresh it",
			FlipSmartPlugin.ladderOwnsSell(null, 100 * HOUR));
	}
}

package com.flipsmart;

import com.flipsmart.trading.OfferStore;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.mock;

/**
 * Verifies the offer-screen lock state machine on {@link AutoRecommendService}.
 * Covers the public state contract only; the {@code invokeFocusCallback} gate
 * is exercised via manual QA because it requires a fully-wired queue.
 */
public class AutoRecommendServiceLockTest
{
	private AutoRecommendService service;

	@Before
	public void setUp()
	{
		FlipSmartConfig config = mock(FlipSmartConfig.class);
		FlipSmartPlugin plugin = mock(FlipSmartPlugin.class);
		service = new AutoRecommendService(config, plugin, new OfferStore());
	}

	@Test
	public void lockStartsCleared()
	{
		assertNull(service.getLockedItemId());
	}

	@Test
	public void acquireOfferLockStoresItemId()
	{
		service.acquireOfferLock(1234);
		assertEquals(Integer.valueOf(1234), service.getLockedItemId());
	}

	@Test
	public void acquireOfferLockIgnoresNonPositiveItemId()
	{
		service.acquireOfferLock(0);
		assertNull(service.getLockedItemId());

		service.acquireOfferLock(-1);
		assertNull(service.getLockedItemId());
	}

	@Test
	public void acquireOfferLockReplacesExistingLock()
	{
		service.acquireOfferLock(1111);
		service.acquireOfferLock(2222);
		assertEquals(Integer.valueOf(2222), service.getLockedItemId());
	}

	@Test
	public void acquireOfferLockIsIdempotentForSameItem()
	{
		service.acquireOfferLock(4444);
		service.acquireOfferLock(4444);
		assertEquals(Integer.valueOf(4444), service.getLockedItemId());
	}

	@Test
	public void releaseOfferLockClearsState()
	{
		service.acquireOfferLock(5555);
		service.releaseOfferLock();
		assertNull(service.getLockedItemId());
	}

	@Test
	public void releaseOfferLockIsSafeWhenAlreadyCleared()
	{
		service.releaseOfferLock();
		assertNull(service.getLockedItemId());
	}

	// #1349: when the offer-setup panel is open but no item is selected yet
	// (TRADINGPOST_SEARCH == 0), the lock must target the currently-focused
	// recommendation so a refresh can't swap it before the player searches.
	@Test
	public void lockTargetFallsBackToFocusedRecommendationBeforeSearch()
	{
		assertEquals(4321, AutoRecommendService.resolveOfferLockTarget(0, 4321));
	}

	@Test
	public void lockTargetPrefersSelectedItemOverFocused()
	{
		assertEquals(31111, AutoRecommendService.resolveOfferLockTarget(31111, 4321));
	}

	@Test
	public void lockTargetIsZeroWhenNothingSelectedOrFocused()
	{
		assertEquals(0, AutoRecommendService.resolveOfferLockTarget(0, null));
	}

	// The acquire path used on offer-setup open: an empty panel with a focused
	// recommendation must lock that recommendation (the AC2 window this fix closes).
	@Test
	public void acquireForOpenSetupLocksFocusedRecommendationWhenNoItemSelected()
	{
		service.acquireOfferLockForOpenSetup(0, 4321);
		assertEquals(Integer.valueOf(4321), service.getLockedItemId());
	}
}

package com.flipsmart;

import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.SpriteManager;
import org.junit.Test;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyBoolean;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.ArgumentMatchers.anyLong;
import static org.mockito.Mockito.doNothing;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * The border is recomputed every game tick. Any tick that cannot decide a colour used to
 * revert the slot to vanilla, so a single undecidable tick in a run of decidable ones read
 * as a flash. These pin the stability rule and the limit on it.
 */
public class SlotBorderStabilityTest
{
    private final FlipSmartPlugin plugin = mock(FlipSmartPlugin.class);
    private final FlipSmartConfig config = mock(FlipSmartConfig.class);

    private GeSlotWidgetDecorator decorator()
    {
        GeSlotWidgetDecorator real = new GeSlotWidgetDecorator(
            mock(Client.class), config, plugin, mock(SpriteManager.class));
        GeSlotWidgetDecorator decorator = spy(real);
        doNothing().when(decorator).applyBorder(anyInt(), any(), any());
        doNothing().when(decorator).revertBorder(anyInt(), any());
        return decorator;
    }

    private static GrandExchangeOffer buyOffer(int itemId, int price)
    {
        GrandExchangeOffer offer = mock(GrandExchangeOffer.class);
        when(offer.getState()).thenReturn(GrandExchangeOfferState.BUYING);
        when(offer.getItemId()).thenReturn(itemId);
        when(offer.getPrice()).thenAnswer(GpAnswer.gp(price));
        return offer;
    }

    private void verdict(FlipSmartPlugin.OfferCompetitiveness first,
        FlipSmartPlugin.OfferCompetitiveness... rest)
    {
        when(plugin.calculateCompetitiveness(anyInt(), anyLong(), anyBoolean()))
            .thenReturn(first, rest);
    }

    @Test
    public void undecidableTick_holdsTheLastDecidedTint_insteadOfRevertingToVanilla()
    {
        verdict(FlipSmartPlugin.OfferCompetitiveness.COMPETITIVE,
            FlipSmartPlugin.OfferCompetitiveness.UNKNOWN);

        GeSlotWidgetDecorator decorator = decorator();
        Widget slotWidget = mock(Widget.class);
        GrandExchangeOffer offer = buyOffer(4444, 100);

        decorator.reconcileBorder(slotWidget, 0, offer, true);
        decorator.reconcileBorder(slotWidget, 0, offer, true);

        verify(decorator, times(2)).applyBorder(0, slotWidget, SlotBorderTint.GREEN);
        verify(decorator, never()).revertBorder(anyInt(), any());
    }

    @Test
    public void aRepricedOfferInTheSameSlot_doesNotInheritTheHeldTint()
    {
        verdict(FlipSmartPlugin.OfferCompetitiveness.COMPETITIVE,
            FlipSmartPlugin.OfferCompetitiveness.UNKNOWN);

        GeSlotWidgetDecorator decorator = decorator();
        Widget slotWidget = mock(Widget.class);

        decorator.reconcileBorder(slotWidget, 0, buyOffer(4444, 100), true);
        // Same slot, same item, cancelled and relisted at a price we cannot yet judge.
        decorator.reconcileBorder(slotWidget, 0, buyOffer(4444, 250), true);

        verify(decorator, times(1)).applyBorder(anyInt(), any(), any());
        verify(decorator).revertBorder(0, slotWidget);
    }

    @Test
    public void aHeldTintInOneSlot_doesNotLeakIntoAnother()
    {
        verdict(FlipSmartPlugin.OfferCompetitiveness.COMPETITIVE,
            FlipSmartPlugin.OfferCompetitiveness.UNKNOWN);

        GeSlotWidgetDecorator decorator = decorator();
        Widget slotWidget = mock(Widget.class);
        GrandExchangeOffer offer = buyOffer(4444, 100);

        decorator.reconcileBorder(slotWidget, 0, offer, true);
        decorator.reconcileBorder(slotWidget, 3, offer, true);

        verify(decorator).applyBorder(0, slotWidget, SlotBorderTint.GREEN);
        verify(decorator).revertBorder(3, slotWidget);
    }
}

package com.flipsmart;

