import static org.junit.Assert.assertTrue;

/**
 * Parity guard for the GE tax-exempt item list (epic tracking-accuracy work).
 *
 * The OSRS GE tax-exempt set is duplicated across two repos: the backend's
 * {@code app.constants.GE_TAX_EXEMPT_ITEM_IDS} is the CANONICAL source of
 * truth, and {@link GeTax#EXEMPT_ITEM_IDS} mirrors it so the GE-slot hover
 * overlay can compute true post-tax profit without a network round-trip.
 *
 * This test pins the exact expected exempt-id set as a literal. The same
 * literal set is pinned in the backend repo's
 * {@code tests/test_ge_tax_exempt_parity.py}. Because both repos assert their
 * own list equals this identical pinned contract, the two lists cannot drift
 * apart while both test suites are green.
 *
 * When Jagex changes GE exemptions, update all four places in lockstep:
 * backend constants, the backend parity test, {@link GeTax}, and this test.
 */
public class GeTaxExemptParityTest
{
	/**
	 * Canonical cross-repo contract. Keep byte-identical to the backend's
	 * EXPECTED_GE_TAX_EXEMPT_ITEM_IDS in test_ge_tax_exempt_parity.py.
	 */
	private static final Set<Integer> EXPECTED_EXEMPT_ITEM_IDS =
		Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
			233,    // Pestle and mortar
			315,    // Shrimps
			329,    // Salmon
			347,    // Herring
			351,    // Pike
			355,    // Mackerel
			361,    // Tuna
			365,    // Bass
			379,    // Lobster
			558,    // Mind rune
			806,    // Bronze dart
			807,    // Iron dart
			808,    // Steel dart
			882,    // Bronze arrow
			884,    // Iron arrow
			886,    // Steel arrow
			952,    // Spade
			1733,   // Needle
			1735,   // Shears
			1755,   // Chisel
			1785,   // Glassblowing pipe
			1891,   // Cake
			2140,   // Cooked chicken
			2142,   // Cooked meat
			2309,   // Bread
			2327,   // Meat pie
			2347,   // Hammer
			2552,   // Ring of dueling(8)
			3008,   // Energy potion(4)
			3853,   // Games necklace(8)
			5325,   // Gardening trowel
			5329,   // Secateurs
			5331,   // Watering can
			5341,   // Rake
			5343,   // Seed dibber
			8007,   // Varrock teleport (tablet)
			8008,   // Lumbridge teleport (tablet)
			8009,   // Falador teleport (tablet)
			8010,   // Camelot teleport (tablet)
			8011,   // Ardougne teleport (tablet)
			8013,   // Teleport to house (tablet)
			8794,   // Saw
			13190,  // Old school bond
			28790,  // Kourend castle teleport (tablet)
			28824   // Civitas illa fortis teleport
		)));

	@Test
	public void pluginExemptListMatchesPinnedContract()
	{
		Set<Integer> missing = new TreeSet<>(EXPECTED_EXEMPT_ITEM_IDS);
		missing.removeAll(GeTax.EXEMPT_ITEM_IDS);

		Set<Integer> unexpected = new TreeSet<>(GeTax.EXEMPT_ITEM_IDS);
		unexpected.removeAll(EXPECTED_EXEMPT_ITEM_IDS);

		assertEquals(
			"GE tax-exempt list drifted from the pinned cross-repo contract. "
				+ "Missing from plugin: " + missing + "; unexpected in plugin: "
				+ unexpected + ". Update GeTax.java, this test, and BOTH backend "
				+ "files in lockstep.",
			EXPECTED_EXEMPT_ITEM_IDS, GeTax.EXEMPT_ITEM_IDS);
	}

	@Test
	public void mindRuneExemptNatureRuneNot()
	{
		final int mindRuneId = 558;
		final int natureRuneId = 561;

		assertTrue("Mind rune (558) must be tax-exempt",
			GeTax.EXEMPT_ITEM_IDS.contains(mindRuneId));
		assertFalse("Nature rune (561) is NOT tax-exempt",
			GeTax.EXEMPT_ITEM_IDS.contains(natureRuneId));
		assertTrue(EXPECTED_EXEMPT_ITEM_IDS.contains(mindRuneId));
		assertFalse(EXPECTED_EXEMPT_ITEM_IDS.contains(natureRuneId));
	}
}

package com.flipsmart;
import com.flipsmart.domain.flip.FlipRecommendation;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * Covers {@link AutoRecommendService#firstAvailableBuyIndex} — the scan that lets a
 * freed GE slot (collect / unfilled-cancel) surface a buy even when {@code currentIndex}
 * has advanced past every still-valid item. Monotonic {@code currentIndex} was the
 * root cause of issue #725: once it reached the end, a freed slot found nothing to
 * focus until the next full queue refresh.
 */
public class AutoRecommendFreeSlotBuyTest
{
	// recommendedBuyPrice/SellPrice/quantity chosen so adjusted profit is clearly
	// positive (profitable) or negative (below threshold) under priceOffset 0.
	private static FlipRecommendation profitable(int itemId)
	{
		FlipRecommendation r = new FlipRecommendation();
		r.setItemId(itemId);
		r.setItemName("item-" + itemId);
		r.setRecommendedBuyPrice(100);
		r.setRecommendedSellPrice(200);
		r.setRecommendedQuantity(10);
		return r;
	}

	private static FlipRecommendation unprofitable(int itemId)
	{
		FlipRecommendation r = new FlipRecommendation();
		r.setItemId(itemId);
		r.setItemName("item-" + itemId);
		r.setRecommendedBuyPrice(200);
		r.setRecommendedSellPrice(100);
		r.setRecommendedQuantity(10);
		return r;
	}

	private static final Set<Integer> NONE_ACTIVE = Collections.emptySet();
	private static final int NO_EXCLUDE = -1;

	// The freed slot must find an available item even when it sits at index 0 and
	// the (monotonic) currentIndex has run off the end — the scan ignores currentIndex.
	@Test
	public void findsLowestAvailableIndex()
	{
		List<FlipRecommendation> queue = Arrays.asList(
			profitable(1001), profitable(2002), profitable(3003));

		int idx = AutoRecommendService.firstAvailableBuyIndex(queue, NONE_ACTIVE, NO_EXCLUDE, 0, 1);

		assertEquals(0, idx);
	}

	// Items already live on the GE are skipped — only a genuinely free item surfaces.
	@Test
	public void skipsItemsAlreadyOnTheGe()
	{
		List<FlipRecommendation> queue = Arrays.asList(
			profitable(1001), profitable(2002), profitable(3003));
		Set<Integer> active = new HashSet<>(Arrays.asList(1001, 2002));

		int idx = AutoRecommendService.firstAvailableBuyIndex(queue, active, NO_EXCLUDE, 0, 1);

		assertEquals("first non-GE item", 2, idx);
	}

	// The just-cancelled item is skipped so a cancel surfaces a different flip
	// instead of immediately re-recommending the one the player just dropped (#725).
	@Test
	public void skipsExcludedJustCancelledItem()
	{
		List<FlipRecommendation> queue = Arrays.asList(
			profitable(1001), profitable(2002), profitable(3003));

		int idx = AutoRecommendService.firstAvailableBuyIndex(queue, NONE_ACTIVE, 1001, 0, 1);

		assertEquals("skips the excluded item, picks the next", 1, idx);
	}

	// Items below the minimum-profit threshold are skipped.
	@Test
	public void skipsBelowMinProfit()
	{
		List<FlipRecommendation> queue = Arrays.asList(
			unprofitable(1001), profitable(2002));

		int idx = AutoRecommendService.firstAvailableBuyIndex(queue, NONE_ACTIVE, NO_EXCLUDE, 0, 1);

		assertEquals(1, idx);
	}

	// Nothing available -> -1, so the caller prompts collection instead of crashing (AC6 spirit).
	@Test
	public void returnsMinusOneWhenNothingAvailable()
	{
		List<FlipRecommendation> queue = Arrays.asList(
			profitable(1001), profitable(2002));
		Set<Integer> active = new HashSet<>(Arrays.asList(1001, 2002));

		int idx = AutoRecommendService.firstAvailableBuyIndex(queue, active, NO_EXCLUDE, 0, 1);

		assertEquals(-1, idx);
	}

	@Test
	public void returnsMinusOneForEmptyQueue()
	{
		int idx = AutoRecommendService.firstAvailableBuyIndex(
			Collections.emptyList(), NONE_ACTIVE, NO_EXCLUDE, 0, 1);

		assertEquals(-1, idx);
	}

	// AC1/AC2/AC4: an item inside its skip cooldown is passed over even though it is
	// otherwise surfaceable, so a skipped buy does not immediately re-appear (including
	// after a backend refresh that still lists it).
	@Test
	public void skipsCoolingDownItem()
	{
		List<FlipRecommendation> queue = Arrays.asList(
			profitable(1001), profitable(2002), profitable(3003));
		Set<Integer> cooling = new HashSet<>(Collections.singletonList(1001));

		int idx = AutoRecommendService.firstAvailableBuyIndex(
			queue, NONE_ACTIVE, NO_EXCLUDE, 0, 1, cooling::contains);

		assertEquals("skips the cooling item, picks the next", 1, idx);
	}

	// When every remaining item is cooling down the scan reports nothing surfaceable,
	// which is what makes the exhausted queue pull a fresh recommendation list (AC3).
	@Test
	public void returnsMinusOneWhenAllCoolingDown()
	{
		List<FlipRecommendation> queue = Arrays.asList(profitable(1001), profitable(2002));
		Set<Integer> cooling = new HashSet<>(Arrays.asList(1001, 2002));

		int idx = AutoRecommendService.firstAvailableBuyIndex(
			queue, NONE_ACTIVE, NO_EXCLUDE, 0, 1, cooling::contains);

		assertEquals(-1, idx);
	}
}

package com.flipsmart;

import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Supplier;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * Covers {@link FlipSmartApiClient#dedupeInFlight} — the in-flight dedup that stops
 * the per-render-frame GE offer loop from opening one daily-volume connection per
 * frame for the same uncached item (issue #727).
 */
public class DailyVolumeDedupTest
{
	// AC1 — repeated calls while a fetch is in flight share a single underlying fetch.
	@Test
	public void sharesSingleFetchWhileInFlight()
	{
		Map<Integer, CompletableFuture<Integer>> inFlight = new ConcurrentHashMap<>();
		AtomicInteger fetches = new AtomicInteger();
		Supplier<CompletableFuture<Integer>> fetcher = () ->
		{
			fetches.incrementAndGet();
			return new CompletableFuture<>(); // never completes during this test
		};

		CompletableFuture<Integer> first = FlipSmartApiClient.dedupeInFlight(inFlight, 1747, fetcher);
		for (int i = 0; i < 10; i++)
		{
			CompletableFuture<Integer> again = FlipSmartApiClient.dedupeInFlight(inFlight, 1747, fetcher);
			assertSame("repeat callers get the same in-flight future", first, again);
		}

		assertEquals("only one underlying fetch is issued", 1, fetches.get());
	}

	// AC2 — once the in-flight fetch completes, the entry clears and a later call refetches.
	@Test
	public void clearsInFlightOnCompletionAndAllowsRefetch()
	{
		Map<Integer, CompletableFuture<Integer>> inFlight = new ConcurrentHashMap<>();
		AtomicInteger fetches = new AtomicInteger();
		CompletableFuture<Integer> backing = new CompletableFuture<>();
		Supplier<CompletableFuture<Integer>> fetcher = () ->
		{
			fetches.incrementAndGet();
			return backing.thenApply(v -> v); // a fresh dependent future per call
		};

		FlipSmartApiClient.dedupeInFlight(inFlight, 1747, fetcher);
		assertTrue("entry registered while in flight", inFlight.containsKey(1747));

		backing.complete(42);

		assertFalse("entry cleared after completion", inFlight.containsKey(1747));

		FlipSmartApiClient.dedupeInFlight(inFlight, 1747, fetcher);
		assertEquals("a post-completion call refetches", 2, fetches.get());
	}

	// AC3 — different item ids fetch independently.
	@Test
	public void differentItemsFetchIndependently()
	{
		Map<Integer, CompletableFuture<Integer>> inFlight = new ConcurrentHashMap<>();
		AtomicInteger fetches = new AtomicInteger();
		Supplier<CompletableFuture<Integer>> fetcher = () ->
		{
			fetches.incrementAndGet();
			return new CompletableFuture<>();
		};

		CompletableFuture<Integer> a = FlipSmartApiClient.dedupeInFlight(inFlight, 1747, fetcher);
		CompletableFuture<Integer> b = FlipSmartApiClient.dedupeInFlight(inFlight, 27641, fetcher);

		assertEquals("each distinct item issues its own fetch", 2, fetches.get());
		org.junit.Assert.assertNotSame("distinct items get distinct futures", a, b);
		assertTrue(inFlight.containsKey(1747));
		assertTrue(inFlight.containsKey(27641));
	}
}

package com.flipsmart;
import com.flipsmart.domain.offer.OfferAction;
import com.flipsmart.api.dto.Dtos.OfferAdviceBatchResponse;
