import java.util.Arrays;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class OfferActionsBatchTest
{
	private static final String OFFERS_KEY = "offers";

	@Test
	public void bodyWrapsEachOfferUnderOffersArray()
	{
		OfferAdviceRequest a = OfferAdviceRequest.builder()
			.itemId(1).pool("high_vol").side("buy").stage("initial")
			.listedAtMillis(1781035200000L).listedPrice(5).listedQuantity(1).filledQuantity(0).build();
		OfferAdviceRequest b = OfferAdviceRequest.builder()
			.itemId(2).pool("mid_vol").side("sell").stage("initial")
			.listedAtMillis(1781035200000L).listedPrice(50).listedQuantity(3).filledQuantity(1)
			.userAvgBuyPrice(40L).build();

		JsonObject body = FlipSmartApiClient.buildOfferActionsBody(Arrays.asList(a, b));

		assertTrue(body.has(OFFERS_KEY));
		assertEquals(2, body.getAsJsonArray(OFFERS_KEY).size());
		assertEquals(1, body.getAsJsonArray(OFFERS_KEY).get(0).getAsJsonObject().get("item_id").getAsInt());
		assertEquals(2, body.getAsJsonArray(OFFERS_KEY).get(1).getAsJsonObject().get("item_id").getAsInt());
	}

	@Test
	public void deserializesBatchResponseWithItemIdAndAdvice()
	{
		String json = "{\"results\":["
			+ "{\"item_id\":111,\"action\":\"move_price_down\",\"reason\":\"r\",\"new_price\":1050,\"net_profit_estimate\":900},"
			+ "{\"item_id\":222,\"action\":\"wait\",\"reason\":\"w\"}]}";

		OfferAdviceBatchResponse resp = new Gson().fromJson(json, OfferAdviceBatchResponse.class);

		assertEquals(2, resp.getResults().size());
		OfferAdviceResult first = resp.getResults().get(0);
		assertEquals(111, first.getItemId());
		assertEquals(OfferAction.MOVE_PRICE_DOWN, first.getActionEnum());
		assertEquals(Long.valueOf(1050), first.getNewPrice());

		OfferAdviceResult second = resp.getResults().get(1);
		assertEquals(222, second.getItemId());
		assertEquals(OfferAction.WAIT, second.getActionEnum());
		assertNull(second.getNewPrice());
	}
}

package com.flipsmart;

import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;

import java.time.Duration;
import java.time.Instant;

import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Buy-limit cooldown window bookkeeping (#1115).
 *
 * <p>AC6 is the subtle requirement under test: the 4h window opens on the FIRST
 * unit bought on an offer, not when the limit finishes filling. The stock GE
 * plugin uses the same rule, and we deliberately mirror it — but we keep our own
 * record because that plugin can be switched off, in which case its copy never
 * gets written at all.</p>
 */
public class BuyLimitWindowTest
{
	private static final int CANNONBALL_ID = 2;
	private static final String OUR_GROUP = "flipsmart";
	private static final String STOCK_GROUP = "grandexchange";
	private static final String KEY = "buylimit." + CANNONBALL_ID;

	private ConfigManager configManager;
	private GeOfferDescriptionService service;

	@Before
	public void setUp()
	{
		configManager = mock(ConfigManager.class);
		service = new GeOfferDescriptionService(
			mock(Client.class),
			mock(ClientThread.class),
			mock(FlipSmartApiClient.class),
			mock(FlipSmartPlugin.class),
			mock(ItemManager.class),
			mock(FlipAssistOverlay.class),
			configManager,
			mock(FlipSmartConfig.class));
	}

	private static GrandExchangeOffer offer(GrandExchangeOfferState state, int quantitySold)
	{
		GrandExchangeOffer o = mock(GrandExchangeOffer.class);
		when(o.getState()).thenReturn(state);
		when(o.getQuantitySold()).thenReturn(quantitySold);
		when(o.getItemId()).thenReturn(CANNONBALL_ID);
		return o;
	}

	private void stubStored(String group, Instant value)
	{
		when(configManager.getRSProfileConfiguration(eq(group), eq(KEY), any()))
			.thenReturn(value);
	}

	// -----------------------------------------------------------------
	// AC6 — when the window opens
	// -----------------------------------------------------------------

	@Test
	public void aSinglePartialFillOpensTheWindow()
	{
		// One cannonball of an 11,000 offer has bought — the limit is nowhere near
		// filled, but the 4h clock is already running.
		service.recordBuyLimitWindow(offer(GrandExchangeOfferState.BUYING, 1));

		verify(configManager).setRSProfileConfiguration(eq(OUR_GROUP), eq(KEY), any(Instant.class));
	}

	@Test
	public void anUnfilledBuyOfferDoesNotOpenTheWindow()
	{
		// Offer placed, nothing bought yet: no purchase means no cooldown (AC5).
		service.recordBuyLimitWindow(offer(GrandExchangeOfferState.BUYING, 0));

		verify(configManager, never()).setRSProfileConfiguration(any(), any(), any());
	}

	@Test
	public void aSellOfferNeverOpensABuyLimitWindow()
	{
		service.recordBuyLimitWindow(offer(GrandExchangeOfferState.SELLING, 500));
		service.recordBuyLimitWindow(offer(GrandExchangeOfferState.SOLD, 500));

		verify(configManager, never()).setRSProfileConfiguration(any(), any(), any());
	}

	@Test
	public void aLaterFillOnTheSameOfferDoesNotPushTheResetBack()
	{
		// The window is already running. Subsequent fills must leave it alone,
		// otherwise a slowly-filling offer would show a permanently-refreshing 4h.
		stubStored(OUR_GROUP, Instant.now().plus(Duration.ofHours(3)));

		service.recordBuyLimitWindow(offer(GrandExchangeOfferState.BUYING, 250));

		verify(configManager, never()).setRSProfileConfiguration(any(), any(), any());
	}

	@Test
	public void aWindowTheStockPluginAlreadyOpenedIsNotRestarted()
	{
		// Cold start: we were installed mid-window, so only the stock plugin has a
		// record. Minting our own here would report a fresh 4h against a window
		// with one hour left — the GE does not extend on later purchases.
		stubStored(OUR_GROUP, null);
		stubStored(STOCK_GROUP, Instant.now().plus(Duration.ofHours(1)));

		service.recordBuyLimitWindow(offer(GrandExchangeOfferState.BUYING, 5));

		verify(configManager, never()).setRSProfileConfiguration(any(), any(), any());
	}

	@Test
	public void anExpiredWindowIsReopenedByTheNextPurchase()
	{
		stubStored(OUR_GROUP, Instant.now().minus(Duration.ofMinutes(1)));

		service.recordBuyLimitWindow(offer(GrandExchangeOfferState.BOUGHT, 11_000));

		verify(configManager).setRSProfileConfiguration(eq(OUR_GROUP), eq(KEY), any(Instant.class));
	}

	// -----------------------------------------------------------------
	// Reading it back
	// -----------------------------------------------------------------

	@Test
	public void ourRecordIsUsedWhenTheStockGePluginIsDisabled()
	{
		// runelite.grandexchangeplugin=false — nothing is ever written to the
		// stock group, so only our own record can drive the timer.
		stubStored(STOCK_GROUP, null);
		stubStored(OUR_GROUP, Instant.now().plus(Duration.ofHours(2)));

		Long remaining = service.lookupLimitResetMillis(CANNONBALL_ID);

		assertNotNull("our own record must drive the timer on its own", remaining);
		assertTrue("roughly two hours remain", remaining > Duration.ofMinutes(119).toMillis());
	}

	@Test
	public void theStockRecordStillCountsForItemsBoughtBeforeThisFeatureShipped()
	{
		stubStored(OUR_GROUP, null);
		stubStored(STOCK_GROUP, Instant.now().plus(Duration.ofHours(1)));

		assertNotNull("stock record is honoured as a fallback",
			service.lookupLimitResetMillis(CANNONBALL_ID));
	}

	@Test
	public void theLaterOfTheTwoRecordsWins()
	{
		// Whichever source saw the earlier first-fill has the more accurate reset;
		// taking the later one avoids under-reporting the remaining cooldown.
		stubStored(OUR_GROUP, Instant.now().plus(Duration.ofHours(3)));
		stubStored(STOCK_GROUP, Instant.now().plus(Duration.ofMinutes(30)));

		Long remaining = service.lookupLimitResetMillis(CANNONBALL_ID);

		assertTrue("the longer window is reported", remaining > Duration.ofMinutes(150).toMillis());
	}

	@Test
	public void nothingIsReportedWithNoRecordAtAll()
	{
		stubStored(OUR_GROUP, null);
		stubStored(STOCK_GROUP, null);

		assertNull("AC5 — no purchase in the window means no timer",
			service.lookupLimitResetMillis(CANNONBALL_ID));
	}

	@Test
	public void anElapsedRecordReportsNothingRatherThanZero()
	{
		stubStored(OUR_GROUP, Instant.now().minus(Duration.ofMinutes(5)));
		stubStored(STOCK_GROUP, null);

		assertNull("an elapsed window must not render 0:00",
			service.lookupLimitResetMillis(CANNONBALL_ID));
	}

	@Test
	public void theRecordedResetIsFourHoursFromTheFirstFill()
	{
		// Asserting the value actually written, not that a 4h constant equals 4h.
		Instant before = Instant.now();
		service.recordBuyLimitWindow(offer(GrandExchangeOfferState.BUYING, 1));

		ArgumentCaptor<Object> written = ArgumentCaptor.forClass(Object.class);
		verify(configManager).setRSProfileConfiguration(eq(OUR_GROUP), eq(KEY), written.capture());

		Instant reset = (Instant) written.getValue();
		long minutesOut = Duration.between(before, reset).toMinutes();
		assertTrue("reset should land ~4h out, got " + minutesOut + "m",
			minutesOut >= 239 && minutesOut <= 240);
	}
}

package com.flipsmart;

import com.flipsmart.FlipAssistOverlay.FlipAssistStep;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

/**
 * Covers {@link FlipAssistOverlay#offerSetupStep} — the step shown on the GE offer-setup
 * screen given the current vs target quantity/price. Quantity must match EXACTLY: the ±1
 * price tolerance previously accepted the default qty 1 when the target was 2, skipping the
 * "Set Quantity" step and jumping straight to Confirm (the user would buy 1 instead of 2).
 */
public class FlipAssistOfferSetupStepTest
{
	// Regression: default qty 1 with target 2 must still prompt SET_QUANTITY, not Confirm.
	@Test
	public void defaultQtyOneWithTargetTwoPromptsSetQuantity()
	{
		assertEquals(FlipAssistStep.SET_QUANTITY,
			FlipAssistOverlay.offerSetupStep(1, 2, 7348074, 7348074, true));
	}

	// Exact qty + exact price → Confirm (buy).
	@Test
	public void exactQtyAndPriceConfirmsBuy()
	{
		assertEquals(FlipAssistStep.CONFIRM_OFFER,
			FlipAssistOverlay.offerSetupStep(2, 2, 7348074, 7348074, true));
	}

	// Exact qty + exact price → Confirm (sell).
	@Test
	public void exactQtyAndPriceConfirmsSell()
	{
		assertEquals(FlipAssistStep.CONFIRM_SELL,
			FlipAssistOverlay.offerSetupStep(2, 2, 21505278, 21505278, false));
	}

	// Price keeps ±1 tolerance (1gp rounding) once qty is exact.
	@Test
	public void priceWithinOneGpStillConfirms()
	{
		assertEquals(FlipAssistStep.CONFIRM_OFFER,
			FlipAssistOverlay.offerSetupStep(2, 2, 7348073, 7348074, true));
	}

	// Correct qty but wrong price → SET_PRICE (buy).
	@Test
	public void correctQtyWrongPricePromptsSetPrice()
	{
		assertEquals(FlipAssistStep.SET_PRICE,
			FlipAssistOverlay.offerSetupStep(2, 2, 7000000, 7348074, true));
	}

	// Target qty 1 with default 1 → no quantity entry needed, advance to price/confirm.
	@Test
	public void targetQtyOneDoesNotForceQuantityStep()
	{
		assertEquals(FlipAssistStep.CONFIRM_OFFER,
			FlipAssistOverlay.offerSetupStep(1, 1, 7348074, 7348074, true));
	}
}

package com.flipsmart;

import com.flipsmart.api.dto.Dtos.FavoriteItem;
import com.flipsmart.api.dto.Dtos.FlipAdjustmentResponse;
import com.flipsmart.api.dto.Dtos.FlipFinderResponse;
import com.flipsmart.api.dto.Dtos.OfferAdviceResponse;
import com.flipsmart.api.dto.Dtos.PriceTargetResponse;
import com.flipsmart.api.dto.Dtos.ReadjustmentResponse;
import com.flipsmart.api.dto.Dtos.SellPriceCheckResponse;
import com.flipsmart.api.dto.Dtos.TransactionRequest;
import com.flipsmart.domain.flip.ActiveFlip;
import com.flipsmart.domain.flip.FlipAnalysis;
import com.flipsmart.domain.flip.FlipRecommendation;
import com.flipsmart.domain.offer.OfferRecord;
import com.flipsmart.domain.offer.OfferState;
import com.flipsmart.recommend.SmartSellPricer;
import com.flipsmart.trading.ActiveFlipCardMetrics;
import com.flipsmart.trading.RealizedFlipProfit;
import com.flipsmart.util.BuyPriceLookup;
import com.flipsmart.util.GeTax;
import com.flipsmart.util.GpUtils;
import com.flipsmart.v9.V9FlipState;
import com.google.gson.JsonObject;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Jagex's max-cash update lets a single GE price exceed Integer.MAX_VALUE. Every GP value the
 * plugin parses, stores, computes or displays must survive a 3b per-item price and ~2.1T totals.
 */
public class MaxCashGpTest
{
	private static final long PRICE_3B = 3_000_000_000L;
	private static final long SELL_3_1B = 3_100_000_000L;
	private static final long TOTAL_2_1T = 2_100_000_000_000L;
	private static final int QTY_700 = 700;
	private static final int ITEM = 4151;
	private static final int TAX_CAP = 5_000_000;

	private final Gson gson = new Gson();

	// ---- DTO parse: an int field would throw JsonSyntaxException and drop the whole response ----

	@Test
	public void flipRecommendationParsesPricesAndTotalsAboveInt32()
	{
		String json = "{\"item_id\":4151,\"instant_buy_price\":3100000000,\"instant_sell_price\":3000000000,"
			+ "\"recommended_buy_price\":3000000000,\"recommended_sell_price\":3100000000,"
			+ "\"recommended_quantity\":700,\"margin\":100000000,\"ge_tax\":5000000,"
			+ "\"breakeven_sell_price\":3005000000,\"potential_profit\":66500000000,"
			+ "\"total_cost\":2100000000000}";
		FlipRecommendation rec = gson.fromJson(json, FlipRecommendation.class);

		assertEquals(SELL_3_1B, rec.getInstantBuyPrice());
		assertEquals(PRICE_3B, rec.getInstantSellPrice());
		assertEquals(PRICE_3B, rec.getRecommendedBuyPrice());
		assertEquals(SELL_3_1B, rec.getRecommendedSellPrice());
		assertEquals(100_000_000L, rec.getMargin());
		assertEquals(3_005_000_000L, rec.getBreakevenSellPrice());
		assertEquals(66_500_000_000L, rec.getPotentialProfit());
		assertEquals(TOTAL_2_1T, rec.getTotalCost());
	}

	@Test
	public void otherResponseDtosParseMoneyAboveInt32()
	{
		ActiveFlip flip = gson.fromJson(
			"{\"average_buy_price\":3000000000,\"recommended_sell_price\":3100000000,\"total_invested\":2100000000000}",
			ActiveFlip.class);
		assertEquals(PRICE_3B, flip.getAverageBuyPrice());
		assertEquals(Long.valueOf(SELL_3_1B), flip.getRecommendedSellPrice());
		assertEquals(TOTAL_2_1T, flip.getTotalInvested());

		FlipAnalysis analysis = gson.fromJson(
			"{\"current_prices\":{\"high\":3100000000,\"low\":3000000000,\"gross_margin\":100000000,"
				+ "\"ge_tax\":5000000,\"net_margin\":95000000},\"historical_data\":{\"avg_price\":3050000000}}",
			FlipAnalysis.class);
		assertEquals(Long.valueOf(SELL_3_1B), analysis.getCurrentPrices().getHigh());
		assertEquals(Long.valueOf(PRICE_3B), analysis.getCurrentPrices().getLow());
		assertEquals(Long.valueOf(3_050_000_000L), analysis.getHistoricalData().getAvgPrice());

		FavoriteItem fav = gson.fromJson(
			"{\"buy_price\":3000000000,\"sell_price\":3100000000,\"margin\":95000000,\"profit\":66500000000}",
			FavoriteItem.class);
		assertEquals(Long.valueOf(PRICE_3B), fav.getBuyPrice());
		assertEquals(66_500_000_000L, fav.getProfit());

		OfferAdviceResponse advice = gson.fromJson(
			"{\"action\":\"move_down\",\"new_price\":3000000000,\"net_profit_estimate\":2100000000000,"
				+ "\"position_margin\":95000000}",
			OfferAdviceResponse.class);
		assertEquals(Long.valueOf(PRICE_3B), advice.getNewPrice());
		assertEquals(Long.valueOf(TOTAL_2_1T), advice.getNetProfitEstimate());

		FlipAdjustmentResponse adj = gson.fromJson(
			"{\"recommended_price\":3000000000,\"current_margin\":95000000,\"breakeven_price\":3005000000}",
			FlipAdjustmentResponse.class);
		assertEquals(Long.valueOf(PRICE_3B), adj.getRecommendedPrice());
		assertEquals(3_005_000_000L, adj.getBreakevenPrice());

		SellPriceCheckResponse check = gson.fromJson(
			"{\"recommended_sell_price\":3100000000}", SellPriceCheckResponse.class);
		assertEquals(SELL_3_1B, check.getRecommendedSellPrice());

		FlipFinderResponse finder = gson.fromJson("{\"cash_stack\":2100000000000}", FlipFinderResponse.class);
		assertEquals(Long.valueOf(TOTAL_2_1T), finder.getCashStack());
	}

	@Test
	public void transactionRequestSerializesPriceAboveInt32Untruncated()
	{
		TransactionRequest req = TransactionRequest.builder(ITEM, "Whip", true, QTY_700, PRICE_3B)
			.recommendedSellPrice(SELL_3_1B)
			.build();
		String json = gson.toJson(req);
		assertTrue(json, json.contains("3000000000"));
		assertTrue(json, json.contains("3100000000"));
	}

	@Test
	public void v9PriceTargetDtosAndStateCarryPricesAboveInt32()
	{
		PriceTargetResponse target = gson.fromJson(
			"{\"recommended_buy_price\":3000000000,\"recommended_sell_price\":3100000000,"
				+ "\"listing_sell_price\":3050000000,\"scenario\":\"B\",\"scenario_b_mid\":3040000000}",
			PriceTargetResponse.class);
		assertEquals(PRICE_3B, target.getRecommendedBuyPrice());
		assertEquals(Long.valueOf(3_050_000_000L), target.getListingSellPrice());
		assertEquals(Long.valueOf(3_040_000_000L), target.getScenarioBMid());

		ReadjustmentResponse readjust = gson.fromJson(
			"{\"action\":\"relist\",\"listing_price\":3020000000}", ReadjustmentResponse.class);
		assertEquals(Long.valueOf(3_020_000_000L), readjust.getListingPrice());

		V9FlipState legacy = gson.fromJson(
			"{\"itemId\":4151,\"buyPrice\":1000,\"originalTarget\":1100,\"scenarioBMid\":1050}", V9FlipState.class);
		assertEquals(1000L, legacy.getBuyPrice());
		assertEquals(Long.valueOf(1050L), legacy.getScenarioBMid());

		JsonObject body = FlipSmartApiClient.buildReadjustmentBody(
			"B", 1, PRICE_3B, QTY_700, QTY_700, TOTAL_2_1T, SELL_3_1B, SELL_3_1B, 3_040_000_000L, 7L);
		assertEquals(PRICE_3B, body.get("buy_price").getAsLong());
		assertEquals(SELL_3_1B, body.get("original_target").getAsLong());
		assertEquals(TOTAL_2_1T, body.get("realized_profit").getAsLong());
	}

	// ---- persisted local state written by the int-typed build must still load ----

	@Test
	public void legacyIntPersistedStateDeserializesIntoWidenedFields()
	{
		String legacyOffers = "[{\"offerId\":7,\"slot\":2,\"itemId\":4151,\"itemName\":\"Whip\",\"buy\":true,"
			+ "\"totalQuantity\":10,\"price\":2000000000,\"filledQuantity\":10,\"spent\":20000000000,"
			+ "\"state\":\"FILLED\",\"createdAtMillis\":1,\"completedAtMillis\":2,\"lastActivityAtMillis\":2}]";
		List<OfferRecord> records = gson.fromJson(legacyOffers, new TypeToken<List<OfferRecord>>() { }.getType());
		assertEquals(2_000_000_000L, records.get(0).getPrice());
		assertEquals(20_000_000_000L, records.get(0).getSpent());

		String legacyAuto = "{\"active\":true,\"currentIndex\":0,\"savedAtMillis\":5,"
			+ "\"queue\":[{\"item_id\":4151,\"recommended_buy_price\":1500000,\"recommended_sell_price\":1600000}],"
			+ "\"buyPrices\":{\"4151\":1500000}}";
		AutoRecommendService.PersistedState state = gson.fromJson(legacyAuto, AutoRecommendService.PersistedState.class);
		assertEquals(1_500_000L, state.queue.get(0).getRecommendedBuyPrice());
		assertEquals(Long.valueOf(1_500_000L), state.buyPrices.get(4151));
	}

	@Test
	public void persistedStateRoundTripsPricesAboveInt32()
	{
		AutoRecommendService.PersistedState state = new AutoRecommendService.PersistedState();
		state.buyPrices = Collections.singletonMap(ITEM, PRICE_3B);
		AutoRecommendService.PersistedState back = gson.fromJson(gson.toJson(state), AutoRecommendService.PersistedState.class);
		Map<Integer, Long> prices = back.buyPrices;
		assertEquals(Long.valueOf(PRICE_3B), prices.get(ITEM));

		OfferRecord rec = OfferRecord.newOffer(1L, 0, ITEM, "Whip", false, QTY_700, PRICE_3B, 1L);
		OfferRecord roundTripped = gson.fromJson(gson.toJson(rec), OfferRecord.class);
		assertEquals(PRICE_3B, roundTripped.getPrice());
	}

	// ---- tax / breakeven / min profitable ----

	@Test
	public void taxIsCappedAndBreakevenIsExactAboveInt32()
	{
		assertEquals(TAX_CAP, GeTax.taxFor(ITEM, PRICE_3B));
		assertEquals(TAX_CAP, GeTax.taxFor(TOTAL_2_1T));
		assertEquals(3_005_000_000L, GeTax.breakevenSellPrice(ITEM, PRICE_3B));
		assertEquals(TOTAL_2_1T + TAX_CAP, GeTax.breakevenSellPrice(TOTAL_2_1T));
	}

	@Test(timeout = 1_000)
	public void breakevenAboveTheTaxCapDoesNotWalkMillionsOfSteps()
	{
		for (long buy = 250_000_000L; buy < 2_100_000_000_000L; buy *= 3)
		{
			long s = GeTax.breakevenSellPrice(buy);
			assertTrue(s - GeTax.taxFor(s) >= buy);
			assertTrue((s - 1) - GeTax.taxFor(s - 1) < buy);
		}
	}

	@Test
	public void minProfitableSellPriceDoesNotWrapNegative()
	{
		long min = SmartSellPricer.calculateMinProfitableSellPrice(PRICE_3B);
		// Tax caps at 5m, so the 2% closed form (~3.061b) would overshoot the real breakeven.
		assertEquals(GeTax.breakevenSellPrice(PRICE_3B) + 1, min);
		assertEquals(3_005_000_001L, min);
		assertEquals(104L, SmartSellPricer.calculateMinProfitableSellPrice(100));
		assertEquals((long) Math.ceil(8_000_000 / 0.98) + 1, SmartSellPricer.calculateMinProfitableSellPrice(8_000_000));
		assertTrue(min > PRICE_3B);

		ActiveFlip flip = new ActiveFlip();
		flip.setAverageBuyPrice(PRICE_3B);
		assertEquals(Long.valueOf(min), SmartSellPricer.calculateSmartSellPrice(flip, SELL_3_1B + 100_000_000L));
	}

	// ---- profit calc sites ----

	@Test
	public void adjustedProfitDoesNotOverflowAboveInt32()
	{
		FlipRecommendation rec = new FlipRecommendation();
		rec.setItemId(ITEM);
		rec.setRecommendedBuyPrice(PRICE_3B);
		rec.setRecommendedSellPrice(SELL_3_1B);
		rec.setRecommendedQuantity(QTY_700);
		assertEquals((SELL_3_1B - PRICE_3B - TAX_CAP) * QTY_700, FocusedFlip.calculateAdjustedProfit(rec, 0));
	}

	@Test
	public void slotTooltipProfitLineShowsAboveInt32Total()
	{
		List<String> lines = new ArrayList<>();
		GrandExchangeSlotOverlay.addProfitLossLine(lines, SELL_3_1B, PRICE_3B, QTY_700, ITEM);
		// (3.1b - 3b - 5m) x 700 = 66.5b; the old int math wrapped this to a loss.
		assertEquals("Profit: 66.5B gp (3.2%)", lines.get(lines.size() - 1));
	}

	@Test
	public void cardMetricsAndRealizedProfitHandleAboveInt32()
	{
		ActiveFlipCardMetrics.Result m = ActiveFlipCardMetrics.compute(PRICE_3B, SELL_3_1B, ITEM, PRICE_3B, 0, QTY_700);
		assertEquals(100_000_000L, m.margin);
		assertEquals(SELL_3_1B - PRICE_3B - TAX_CAP, m.positionNetPerUnit);

		OfferRecord sold = OfferRecord.newOffer(1L, 0, ITEM, "Whip", false, QTY_700, SELL_3_1B, 1L)
			.withFill(QTY_700, SELL_3_1B * QTY_700, OfferState.FILLED, 2L);
		RealizedFlipProfit.Result r = RealizedFlipProfit.compute(Collections.singletonList(sold), ITEM, PRICE_3B, 0L);
		assertEquals((SELL_3_1B - PRICE_3B - TAX_CAP) * QTY_700, r.netProfit);
	}

	@Test
	public void sellDescriptionShowsBreakevenAndProfitAboveInt32()
	{
		String out = GeOfferDescriptionFormatter.formatSellDescription(ITEM, PRICE_3B, SELL_3_1B, QTY_700);
		assertTrue(out, out.contains("3,005,000,000 gp"));
		assertTrue(out, out.contains("+66,500,000,000 gp"));
	}

	@Test
	public void averageBuyPriceFromOffersKeepsAboveInt32()
	{
		OfferRecord buy = OfferRecord.newOffer(1L, 0, ITEM, "Whip", true, QTY_700, PRICE_3B, 1L)
			.withFill(QTY_700, PRICE_3B * QTY_700, OfferState.FILLED, 2L);
		assertEquals(Long.valueOf(PRICE_3B), BuyPriceLookup.findAverageBuyPriceWithFallback(
			null, null, Collections.singletonList(buy), ITEM));
	}

	// ---- text parsing ----

	@Test
	public void parseDigitsReadsAboveInt32()
	{
		assertEquals(PRICE_3B, GpUtils.parseDigits("3,000,000,000 coins"));
		assertEquals(TOTAL_2_1T, GpUtils.parseDigits("2,100,000,000,000"));
	}

	@Test
	public void geHistoryRowsAboveInt32AreKeptNotDropped()
	{
		assertEquals(PRICE_3B, GEHistoryService.parsePerItemPriceFromText("<col=ffb83f>= 3,000,000,000 each</col>"));
		assertEquals(TOTAL_2_1T, GEHistoryService.parseLeadingTotalFromText("2,100,000,000,000 coins"));

		OfferRecord offer = OfferRecord.newOffer(9L, 0, ITEM, "Whip", true, QTY_700, PRICE_3B, 1L);
		assertEquals(Long.valueOf(9L), GEHistoryService.matchOfferId(Arrays.asList(offer), ITEM, true, PRICE_3B));
	}

	@Test
	public void geHistoryEntryCarriesAboveInt32Price()
	{
		GEHistoryEntry e = new GEHistoryEntry(ITEM, false, QTY_700, PRICE_3B);
		assertNotNull(e.toString());
		assertEquals(PRICE_3B, e.getPricePerItem());
	}
}

package com.flipsmart.exit;

import com.flipsmart.FocusedFlip;
import com.flipsmart.api.dto.Dtos.WikiPrice;
import com.flipsmart.domain.offer.OfferRecord;
import com.flipsmart.trading.OfferStore;
import org.junit.Before;
import org.junit.Test;

import java.util.Locale;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class ExitTradesSurfaceTest
{
	private OfferStore store;
	private ExitTradesController controller;
	private final AtomicReference<FocusedFlip> lastFocus = new AtomicReference<>();
	private final AtomicReference<String> lastStatus = new AtomicReference<>();
	private final AtomicBoolean completed = new AtomicBoolean(false);
	private int inventory; // held qty returned for any item

	@Before
	public void setUp()
	{
		store = new OfferStore();
		controller = new ExitTradesController(store);
		inventory = 0;
		controller.setBuyBasisSupplier(itemId -> 1000);
		controller.setWikiPriceSupplier(itemId -> new WikiPrice(1100, 950));
		controller.setInventoryQtySupplier(itemId -> inventory);
		controller.setOnFocusTarget(lastFocus::set);
		controller.setOnStatusMessage((m, id) -> lastStatus.set(m));
		controller.setOnComplete(() -> completed.set(true));
	}

	private void seed(int slot, int itemId, boolean buy, int qty)
	{
		java.util.List<OfferRecord> existing = new java.util.ArrayList<>(store.export());
		existing.add(OfferRecord.newOffer(4000L + slot, slot, itemId, "Item", buy, qty, 100, 1L));
		store.importRecords(existing);
	}

	private void clearStore()
	{
		store.importRecords(new java.util.ArrayList<>());
	}

	private OfferRecord rec(int slot, int itemId, boolean buy, int filled, com.flipsmart.domain.offer.OfferState state)
	{
		return OfferRecord.newOffer(9000L + slot, slot, itemId, "Item", buy, 1000, 100, 1L)
			.withFill(filled, 0L, state, 2L);
	}

	@Test
	public void cancelledSellWithFreedSlotPromptsCollectNotSkip()
	{
		seed(0, 561, false, 1000);
		controller.start(ExitTradesMode.INSTANT);
		// Cancel the live sell: unsold stock lands in the GE collection box, not inventory (#1274).
		controller.onOfferChanged(rec(0, 561, false, 0, com.flipsmart.domain.offer.OfferState.CANCELLED_EMPTY));
		clearStore();  // slot freed while the stock waits in the collection box
		inventory = 0; // nothing in inventory yet — it must be collected first

		controller.surfaceCurrent();

		// Must prompt a collect and hold the target, not read inventory==0 and drop it.
		assertEquals(ExitPhase.AWAITING_COLLECT, controller.getTargets().get(0).getPhase());
		assertFalse(completed.get());
		assertTrue(lastStatus.get().toLowerCase(Locale.ROOT).contains("collect"));
	}

	@Test
	public void cancelledSellAfterCollectPromptsRelist()
	{
		seed(0, 561, false, 1000);
		controller.start(ExitTradesMode.INSTANT);
		controller.onOfferChanged(rec(0, 561, false, 0, com.flipsmart.domain.offer.OfferState.CANCELLED_EMPTY));
		// Player collects: the unsold stock is now in inventory.
		controller.onOfferChanged(rec(0, 561, false, 0, com.flipsmart.domain.offer.OfferState.COLLECTED));
		assertEquals(ExitPhase.CANCELLED_HOLDING, controller.getTargets().get(0).getPhase());
		clearStore();
		inventory = 1000;

		controller.surfaceCurrent();

		FocusedFlip f = lastFocus.get();
		assertNotNull(f);
		assertTrue(f.isSelling());
		assertEquals(561, f.getItemId());
		assertEquals(1000, f.getCurrentStepQuantity());
	}

	@Test
	public void sellTargetSurfacesInstantSellFocus()
	{
		seed(0, 561, false, 1000);
		controller.start(ExitTradesMode.INSTANT);
		controller.surfaceCurrent();
		FocusedFlip f = lastFocus.get();
		assertNotNull(f);
		assertTrue(f.isSelling());
		assertEquals(950, f.getCurrentStepPrice());
		assertEquals(1000, f.getCurrentStepQuantity());
	}

	@Test
	public void buyTargetPromptsCancelFirst()
	{
		seed(2, 4151, true, 10);
		controller.start(ExitTradesMode.INSTANT);
		controller.surfaceCurrent();
		assertTrue(lastStatus.get().toLowerCase(Locale.ROOT).contains("cancel"));
	}

	@Test
	public void staleTargetIsSkippedWhenNoOfferAndNoStock()
	{
		seed(0, 561, false, 1000);
		controller.start(ExitTradesMode.INSTANT);
		// The sell for 561 sold/was collected on its own before we reach it: no live offer, none held.
		clearStore();
		inventory = 0;
		controller.surfaceCurrent();
		assertEquals(ExitPhase.DONE, controller.getTargets().get(0).getPhase());
		assertTrue(completed.get()); // nothing else pending -> run complete
	}

	@Test
	public void onSellScreenScopesPromptToThatItem()
	{
		seed(0, 561, false, 1000);
		seed(1, 999, false, 500);
		controller.start(ExitTradesMode.INSTANT);
		controller.surfaceCurrent(); // pointer surfaces slot 0 (item 561)

		// Player opens slot 1's sell screen (item 999) out of order.
		assertTrue(controller.onSellScreenOpened(999));
		FocusedFlip f = lastFocus.get();
		assertNotNull(f);
		assertEquals(999, f.getItemId());
		assertEquals(950, f.getCurrentStepPrice());
		assertEquals(500, f.getCurrentStepQuantity());
	}

	@Test
	public void onSellScreenIgnoresNonTargetItem()
	{
		seed(0, 561, false, 1000);
		controller.start(ExitTradesMode.INSTANT);
		assertFalse(controller.onSellScreenOpened(12345));
	}

	@Test
	public void collectedBuySurfacesHeldStockSell()
	{
		seed(0, 4151, true, 10);
		controller.start(ExitTradesMode.INSTANT);
		// Buy filled and was collected: slot empty, but 5 sit in inventory to sell.
		clearStore();
		inventory = 5;
		controller.surfaceCurrent();
		assertEquals(ExitPhase.CANCELLED_HOLDING, controller.getTargets().get(0).getPhase());
		FocusedFlip f = lastFocus.get();
		assertNotNull(f);
		assertTrue(f.isSelling());
		assertEquals(4151, f.getItemId());
		assertEquals(950, f.getCurrentStepPrice());
		assertEquals(5, f.getCurrentStepQuantity());
	}
}

package com.flipsmart.exit;

import com.flipsmart.FocusedFlip;
import com.flipsmart.api.dto.Dtos.WikiPrice;
import com.flipsmart.domain.offer.OfferRecord;
import com.flipsmart.trading.OfferStore;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * #1114: Exit Trades must prompt a sell even when the stock to exit is already collected into
 * inventory with no live GE slot. Before the fix, start() seeded the queue from GE slots only, so a
 * fully-collected position built an empty queue (active=false) and silently no-opped — the reported
 * "no prompt on first attempt" bug.
 */
public class ExitTradesInventorySeedTest
{
	private OfferStore store;
	private ExitTradesController controller;
	private final AtomicReference<FocusedFlip> lastFocus = new AtomicReference<>();
	private int inventory; // held qty returned for any item

	@Before
	public void setUp()
	{
		store = new OfferStore();
		controller = new ExitTradesController(store);
		inventory = 0;
		controller.setBuyBasisSupplier(itemId -> 1000);
		controller.setWikiPriceSupplier(itemId -> new WikiPrice(1100, 950));
		controller.setInventoryQtySupplier(itemId -> inventory);
		controller.setItemNameSupplier(itemId -> "Item");
		controller.setOnFocusTarget(lastFocus::set);
		controller.setOnStatusMessage((m, id) -> { });
	}

	private void seedSlot(int slot, int itemId, boolean buy, int qty)
	{
		java.util.List<OfferRecord> existing = new java.util.ArrayList<>(store.export());
		existing.add(OfferRecord.newOffer(4000L + slot, slot, itemId, "Item", buy, qty, 100, 1L));
		store.importRecords(existing);
	}

	@Test
	public void seedsExitFromInventoryWhenNoLiveSlots()
	{
		// No live GE offers, but the player holds 7 of item 561 collected from a prior flip.
		controller.setHeldSellItemIdsSupplier(() -> List.of(561));
		inventory = 7;

		controller.start(ExitTradesMode.INSTANT);

		assertTrue("queue seeded from inventory, not empty", controller.isActive());
		controller.surfaceCurrent();

		FocusedFlip f = lastFocus.get();
		assertNotNull("prompt fires on the first attempt (AC1)", f);
		assertTrue(f.isSelling());
		assertEquals(561, f.getItemId());
		assertEquals(950, f.getCurrentStepPrice());
		assertEquals(7, f.getCurrentStepQuantity());
		assertEquals(ExitPhase.CANCELLED_HOLDING, controller.getTargets().get(0).getPhase());
	}

	@Test
	public void doesNotDoubleSeedHeldItemAlreadyInSlot()
	{
		seedSlot(0, 561, false, 1000); // a live sell for 561 already owns slot 0
		controller.setHeldSellItemIdsSupplier(() -> List.of(561));
		inventory = 7;

		controller.start(ExitTradesMode.INSTANT);

		assertEquals("held item already represented by a slot is not double-added",
			1, controller.getTargets().size());
	}

	@Test
	public void doesNotSeedHeldItemWithNoInventory()
	{
		// Collected set still lists 561, but nothing is actually held (already sold/moved).
		controller.setHeldSellItemIdsSupplier(() -> List.of(561));
		inventory = 0;

		controller.start(ExitTradesMode.INSTANT);

		assertFalse("no phantom target for a zero-quantity held item", controller.isActive());
	}

	@Test
	public void regularModeDoesNotSeedInventory()
	{
		// REGULAR is latched sell-only with no queue; inventory seeding must not build one.
		controller.setHeldSellItemIdsSupplier(() -> List.of(561));
		inventory = 7;

		controller.start(ExitTradesMode.REGULAR);

		assertTrue(controller.isActive()); // active for buy-suppression
		assertTrue("REGULAR builds no queue", controller.getTargets().isEmpty());
	}
}

