    @Test
    public void fullySoldSellAdvancesToNextAction() throws Exception {
        // Guard: a fully-sold sell (nothing returned to inventory, not in collected) must still
        // advance to the next action rather than trying to re-list.
        when(plugin.getFilledGESlotCount()).thenReturn(7);
        AtomicReference<FocusedFlip> painted = new AtomicReference<>();
        service.setOnFocusChanged(painted::set);

        service.onOfferCollected(99, false, "item-99", 5); // 99 not in collected
        SwingUtilities.invokeAndWait(() -> {});

        // Advanced via resolver to the surfaceable buy (item 21), not a re-list of 99.
        assertTrue(painted.get() != null);
        assertEquals(21, painted.get().getItemId());
        assertTrue(painted.get().isBuying());
    }

    @Test
    public void modifyActiveSellPaintsKnownPriceInsteadOfBlanking() throws Exception {
        // The ~9s re-sell delay: opening Modify on an active sell with no pending reprice bailed
        // ALREADY_SELLING and painted nothing. With the setup screen open (lock held for the item)
        // and a known recommended price in session, it must paint immediately from local state.
        OfferRecord activeSell = OfferRecord
            .newOffer(2, 0, 42, "item-42", false, 5, 300, 0L)
            .withFill(0, 0L, OfferState.PARTIAL_FILL, 1L);
        offerStore.importRecords(Arrays.asList(activeSell));
        session.setRecommendedPrice(42, 305);
        service.acquireOfferLock(42); // modify/setup screen open for this item

        AtomicReference<FocusedFlip> painted = new AtomicReference<>();
        service.setOnFocusChanged(painted::set);

        AutoRecommendService.SellFocusResult result = service.overrideFocusForSell(42, "item-42");
        SwingUtilities.invokeAndWait(() -> {});

        assertEquals(AutoRecommendService.SellFocusResult.FOCUSED, result);
        assertTrue("modify-active-sell must paint the known price", painted.get() != null);
        assertEquals(305, painted.get().getCurrentStepPrice());
    }

    @Test
    public void activeSellWithoutPendingRepriceStillBailsAlreadySelling() {
        // Guard: the ALREADY_SELLING short-circuit still holds when no reprice is pending.
        OfferRecord activeSell = OfferRecord
            .newOffer(2, 0, 42, "item-42", false, 5, 300, 0L)
            .withFill(0, 0L, OfferState.PARTIAL_FILL, 1L);
        offerStore.importRecords(Arrays.asList(activeSell));

        assertEquals(AutoRecommendService.SellFocusResult.ALREADY_SELLING,
            service.overrideFocusForSell(42, "item-42"));
    }

    @Test
    public void collectingNormalCompletedBuyStillTagsCompletedBuy() {
        // Guard: a plain completed buy (no prior partial-cancel) keeps COMPLETED_BUY (S3).
        when(plugin.getInventoryCountForItem(40)).thenReturn(5);
        session.setRecommendedPrice(40, 150);

        service.onOfferCollected(40, true, "item-40", 5);

        assertEquals(CollectOrigin.COMPLETED_BUY, session.getCollectOrigin(40));
    }

    @Test
    public void collectPromptShowsResolverChosenItemNotSlotZero() {
        // Slot 0 holds a completed SELL (itemId=100, S5). Slot 5 holds a completed BUY (itemId=200, S3).
        // S3 < S5 in priority, so the resolver picks itemId=200.
        // Without the fix, promptCollection() renders completedAwaitingCollection().get(0)
        // which may be the sell offer (slot/insertion order), showing "Collect profit from GE"
        // instead of "Collect item-200 from GE".
        when(plugin.getFilledGESlotCount()).thenReturn(8);
        when(plugin.hasCollectableGEOffers()).thenReturn(true);

        OfferRecord completedSell = OfferRecord
            .newOffer(1, 0, 100, "item-100", false, 5, 300, 0L)
            .withFill(5, 1500L, OfferState.FILLED, 1L);
        OfferRecord completedBuy = OfferRecord
            .newOffer(2, 5, 200, "item-200", true, 10, 100, 0L)
            .withFill(10, 1000L, OfferState.FILLED, 2L);
        offerStore.importRecords(Arrays.asList(completedSell, completedBuy));

        ActionDecision d = service.resolveAndApply(-1);

        assertEquals(ActionKind.S3, d.getKind());
        assertEquals(ActionStep.COLLECT, d.getStep());
        assertEquals(200, d.getItemId());

        // lastOverlayMessage is set synchronously before the EDT callback fires — safe to read inline.
        String overlay = service.getLastOverlayMessage();
        assertTrue("overlay must mention item-200, not profit; got: " + overlay,
            overlay != null && overlay.contains("item-200"));
    }

    @Test
    public void collectPromptLightsResolverChosenItemSlot() {
        // The slot highlight must follow the collect prompt: when the resolver picks the
        // completed BUY (item-200), the highlight callback must fire for 200 — not linger
        // on the completed SELL (item-100) or any prior focus.
        when(plugin.getFilledGESlotCount()).thenReturn(8);
        when(plugin.hasCollectableGEOffers()).thenReturn(true);

        OfferRecord completedSell = OfferRecord
            .newOffer(1, 0, 100, "item-100", false, 5, 300, 0L)
            .withFill(5, 1500L, OfferState.FILLED, 1L);
        OfferRecord completedBuy = OfferRecord
            .newOffer(2, 5, 200, "item-200", true, 10, 100, 0L)
            .withFill(10, 1000L, OfferState.FILLED, 2L);
        offerStore.importRecords(Arrays.asList(completedSell, completedBuy));

        AtomicInteger highlightedItem = new AtomicInteger(-1);
        service.setOnHighlightItemSlot(highlightedItem::set);

        service.resolveAndApply(-1);

        assertEquals("highlight must follow the collect prompt's item", 200, highlightedItem.get());
    }

    // AC1/AC2 (#919): a skipped buy is snoozed for its cooldown, so the next resolve
    // surfaces a different item instead of re-recommending the one just skipped.
    @Test
    public void skippedBuyIsSnoozedAndNextItemSurfaces() {
        when(plugin.getFilledGESlotCount()).thenReturn(7); // one free slot
        service.start(Arrays.asList(rec(21), rec(22)));

        ActionDecision first = service.resolveAndApply(-1);
        assertEquals(ActionStep.PLACE_BUY, first.getStep());
        assertEquals(21, first.getItemId());

        service.skip(); // skip 21 -> 5-minute cooldown

        ActionDecision afterSkip = service.resolveAndApply(-1);
        assertEquals(ActionStep.PLACE_BUY, afterSkip.getStep());
        assertEquals("skipped 21 is snoozed; 22 surfaces instead", 22, afterSkip.getItemId());
    }

    // AC5 (#919): toggling auto-mode off and back on clears the skip cooldown, so a
    // previously-skipped item becomes eligible again.
    @Test
    public void togglingAutoModeClearsSkipCooldown() {
        when(plugin.getFilledGESlotCount()).thenReturn(7);
        service.start(Arrays.asList(rec(21), rec(22)));
        service.resolveAndApply(-1);
        service.skip(); // 21 cooling

        service.stop();                                    // toggle OFF
        service.start(Arrays.asList(rec(21), rec(22)));    // toggle ON

        ActionDecision d = service.resolveAndApply(-1);
        assertEquals(ActionStep.PLACE_BUY, d.getStep());
        assertEquals("cooldown cleared on toggle; 21 surfaces again", 21, d.getItemId());
    }
}

package com.flipsmart;
import com.flipsmart.domain.flip.FlipRecommendation;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The minimum-volume floor of the shared recommendation predicate
 * ({@link FocusedFlip#passesRecommendationFilters}) — used by both Flip Finder's
 * list and the Flip Assist queue. Each recommendation here clears the profit floor
 * (minProfit 0), so daily volume is the only discriminator.
 */
public class VolumeFilterTest
{
	private static final int NO_OFFSET = 0;
	private static final int NO_MIN_PROFIT = 0;

	/** A comfortably-profitable recommendation with the given daily volume. */
	private static FlipRecommendation withDailyVolume(int dailyVolume)
	{
		FlipRecommendation r = new FlipRecommendation();
		r.setItemId(1);
		r.setRecommendedBuyPrice(100);
		r.setRecommendedSellPrice(2000);
		r.setRecommendedQuantity(1);
		r.setDailyVolume(dailyVolume);
		return r;
	}

	private static boolean passesVolume(int dailyVolume, int minVolume)
	{
		return FocusedFlip.passesRecommendationFilters(
			withDailyVolume(dailyVolume), NO_OFFSET, NO_MIN_PROFIT, minVolume);
	}

	@Test
	public void volumeAtOrAboveThresholdPasses()
	{
		assertTrue(passesVolume(1000, 500));
		assertTrue(passesVolume(500, 500));
	}

	@Test
	public void volumeBelowThresholdFails()
	{
		assertFalse(passesVolume(499, 500));
	}

	@Test
	public void zeroThresholdPassesEverything()
	{
		assertTrue(passesVolume(0, 0));
		assertTrue(passesVolume(1, 0));
	}
}

package com.flipsmart;

import com.flipsmart.api.dto.Dtos.BankSnapshotResponse;
import com.flipsmart.api.dto.Dtos.BankSnapshotResult;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.game.ItemManager;
import org.junit.Before;
import org.junit.Test;

import java.util.concurrent.CompletableFuture;

import static org.junit.Assert.assertFalse;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyList;
import static org.mockito.ArgumentMatchers.anyLong;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class BankSnapshotServiceTest
{
	private static final String RSN = "Zezima";

	private PlayerSession session;
	private FlipSmartApiClient apiClient;
	private ChatMessageManager chatMessageManager;
	private BankSnapshotService service;

	@Before
	public void setUp()
	{
		session = new PlayerSession();
		apiClient = mock(FlipSmartApiClient.class);
		Client client = mock(Client.class);
		ClientThread clientThread = mock(ClientThread.class);
		ItemManager itemManager = mock(ItemManager.class);
		chatMessageManager = mock(ChatMessageManager.class);

		doAnswer(inv -> {
			Runnable r = inv.getArgument(0);
			r.run();
			return null;
		}).when(clientThread).invokeLater(any(Runnable.class));

		when(apiClient.isAuthenticated()).thenReturn(true);

		// Bank containing a coins stack only — avoids tradeable/price lookups.
		ItemContainer bank = mock(ItemContainer.class);
		when(bank.getItems()).thenReturn(new Item[]{new Item(995, 25_000)});
		when(client.getItemContainer(InventoryID.BANK)).thenReturn(bank);

		service = new BankSnapshotService(session, apiClient, client, clientThread, itemManager, chatMessageManager);
	}

	private void stubCreate(CompletableFuture<BankSnapshotResult> future)
	{
		when(apiClient.createBankSnapshotAsync(anyString(), anyList(), anyList(), anyList(), anyLong()))
			.thenReturn(future);
	}

	private BankSnapshotResult successResult()
	{
		BankSnapshotResponse response = mock(BankSnapshotResponse.class);
		when(response.getTotalWealth()).thenReturn(1_000_000L);
		when(response.getItemCount()).thenReturn(1);
		return BankSnapshotResult.success(response);
	}

	private void fakeElapsed(long elapsedMs)
	{
		session.setLastBankSnapshotAttempt(System.currentTimeMillis() - elapsedMs);
	}

	@Test
	public void successUploadsInSingleCallAndPostsChat()
	{
		stubCreate(CompletableFuture.completedFuture(successResult()));

		service.onBankContainerChanged(RSN);

		verify(apiClient, times(1)).createBankSnapshotAsync(anyString(), anyList(), anyList(), anyList(), anyLong());
		verify(chatMessageManager, times(1)).queue(any());
		assertFalse(session.isBankSnapshotInProgress());
	}

	@Test
	public void cooldownBlocksImmediateRetryAfterSuccess()
	{
		stubCreate(CompletableFuture.completedFuture(successResult()));

		service.onBankContainerChanged(RSN);
		service.onBankContainerChanged(RSN);

		verify(apiClient, times(1)).createBankSnapshotAsync(anyString(), anyList(), anyList(), anyList(), anyLong());
	}

	@Test
	public void failureKeepsCooldownNoImmediateRetry()
	{
		stubCreate(CompletableFuture.completedFuture(BankSnapshotResult.failure()));

		service.onBankContainerChanged(RSN);
		service.onBankContainerChanged(RSN);

		verify(apiClient, times(1)).createBankSnapshotAsync(anyString(), anyList(), anyList(), anyList(), anyLong());
		assertFalse(session.isBankSnapshotInProgress());
	}

	@Test
	public void failureRetriesAfterStandardCooldownElapses()
	{
		stubCreate(CompletableFuture.completedFuture(BankSnapshotResult.failure()));

		service.onBankContainerChanged(RSN);
		fakeElapsed(90_000);
		service.onBankContainerChanged(RSN);

		verify(apiClient, times(2)).createBankSnapshotAsync(anyString(), anyList(), anyList(), anyList(), anyLong());
	}

	@Test
	public void transportExceptionKeepsCooldownNoImmediateRetry()
	{
		CompletableFuture<BankSnapshotResult> failed = new CompletableFuture<>();
		failed.completeExceptionally(new RuntimeException("boom"));
		stubCreate(failed);

		service.onBankContainerChanged(RSN);
		service.onBankContainerChanged(RSN);

		verify(apiClient, times(1)).createBankSnapshotAsync(anyString(), anyList(), anyList(), anyList(), anyLong());
		assertFalse(session.isBankSnapshotInProgress());
	}

	@Test
	public void rateLimitedIsSilentAndBacksOffLongerThanStandardCooldown()
	{
		stubCreate(CompletableFuture.completedFuture(BankSnapshotResult.rateLimitedResult()));

		service.onBankContainerChanged(RSN);
		verify(chatMessageManager, never()).queue(any());
		assertFalse(session.isBankSnapshotInProgress());

		// Standard cooldown has elapsed, but the server said no — stay backed off.
		fakeElapsed(90_000);
		service.onBankContainerChanged(RSN);

		verify(apiClient, times(1)).createBankSnapshotAsync(anyString(), anyList(), anyList(), anyList(), anyLong());
	}

	@Test
	public void successBacksOffLongerThanStandardCooldown()
	{
		stubCreate(CompletableFuture.completedFuture(successResult()));

		service.onBankContainerChanged(RSN);
		fakeElapsed(90_000);
		service.onBankContainerChanged(RSN);

		verify(apiClient, times(1)).createBankSnapshotAsync(anyString(), anyList(), anyList(), anyList(), anyLong());
	}

	@Test
	public void skipsWhenNotAuthenticated()
	{
		when(apiClient.isAuthenticated()).thenReturn(false);
		stubCreate(CompletableFuture.completedFuture(successResult()));

		service.onBankContainerChanged(RSN);

		verify(apiClient, never()).createBankSnapshotAsync(anyString(), anyList(), anyList(), anyList(), anyLong());
	}
}

package com.flipsmart;

import com.flipsmart.domain.offer.OfferRecord;
import com.flipsmart.domain.offer.OfferSignal;
import com.flipsmart.domain.offer.OfferState;
import com.flipsmart.domain.offer.OfferTransition;
import com.flipsmart.trading.OfferStateMachine;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class OfferStateMachineTest
{
    private static final long NOW = 1_000_000L;
    private static final long ID = 42L;

    private static OfferSignal buy(GrandExchangeOfferState s, int sold, int total)
    {
        return new OfferSignal(0, s, 1234, "Item", total, 100, sold, (long) sold * 100);
    }

    @Test
    public void placement_fromNull_isNewOffer()
    {
        OfferTransition t = OfferStateMachine.decide(null, buy(GrandExchangeOfferState.BUYING, 0, 10), ID, NOW);

        assertEquals(OfferTransition.Kind.PLACED, t.kind);
        assertEquals(OfferState.NEW, t.record.getState());
        assertEquals(ID, t.record.getOfferId());
        assertEquals(0, t.record.getFilledQuantity());
    }

    @Test
    public void partialFill_advancesToPartialAndReportsDelta()
    {
        OfferRecord placed = OfferRecord.newOffer(ID, 0, 1234, "Item", true, 10, 100, NOW);

        OfferTransition t = OfferStateMachine.decide(placed, buy(GrandExchangeOfferState.BUYING, 3, 10), ID, NOW);

        assertEquals(OfferTransition.Kind.FILLED_DELTA, t.kind);
        assertEquals(OfferState.PARTIAL_FILL, t.record.getState());
        assertEquals(3, t.record.getFilledQuantity());
        assertEquals(3, t.newlyFilledQuantity);
    }

    @Test
    public void secondPartial_reportsOnlyTheDelta()
    {
        OfferRecord partial = OfferStateMachine
            .decide(OfferRecord.newOffer(ID, 0, 1234, "Item", true, 10, 100, NOW),
                buy(GrandExchangeOfferState.BUYING, 3, 10), ID, NOW).record;

        OfferTransition t = OfferStateMachine.decide(partial, buy(GrandExchangeOfferState.BUYING, 7, 10), ID, NOW);

        assertEquals(4, t.newlyFilledQuantity);
        assertEquals(7, t.record.getFilledQuantity());
        assertEquals(OfferState.PARTIAL_FILL, t.record.getState());
    }

    @Test
    public void complete_whenBought_setsFilledAndCompletedKind()
    {
        OfferRecord partial = OfferRecord.newOffer(ID, 0, 1234, "Item", true, 10, 100, NOW);

        OfferTransition t = OfferStateMachine.decide(partial, buy(GrandExchangeOfferState.BOUGHT, 10, 10), ID, NOW);

        assertEquals(OfferTransition.Kind.COMPLETED, t.kind);
        assertEquals(OfferState.FILLED, t.record.getState());
        assertEquals(10, t.newlyFilledQuantity);
    }

    @Test
    public void collect_fromFilled_isCollectedAndClearsSlot()
    {
        OfferRecord filled = OfferStateMachine
            .decide(OfferRecord.newOffer(ID, 0, 1234, "Item", true, 10, 100, NOW),
                buy(GrandExchangeOfferState.BOUGHT, 10, 10), ID, NOW).record;

        OfferTransition t = OfferStateMachine.decide(filled, buy(GrandExchangeOfferState.EMPTY, 10, 10), ID, NOW);

        assertEquals(OfferTransition.Kind.COLLECTED, t.kind);
        assertEquals(OfferState.COLLECTED, t.record.getState());
        assertNull("collected offer no longer holds a slot", t.record.getSlot());
    }

    @Test
    public void cancelWithNoFills_isCancelledEmpty()
    {
        OfferRecord placed = OfferRecord.newOffer(ID, 0, 1234, "Item", true, 10, 100, NOW);

        OfferTransition t = OfferStateMachine.decide(placed, buy(GrandExchangeOfferState.CANCELLED_BUY, 0, 10), ID, NOW);

        assertEquals(OfferTransition.Kind.CANCELLED, t.kind);
        assertEquals(OfferState.CANCELLED_EMPTY, t.record.getState());
    }

    @Test
    public void cancelWithPartialFills_isCancelledPartial_thenCollect()
    {
        OfferRecord partial = OfferStateMachine
            .decide(OfferRecord.newOffer(ID, 0, 1234, "Item", true, 10, 100, NOW),
                buy(GrandExchangeOfferState.BUYING, 4, 10), ID, NOW).record;

        OfferTransition cancelled = OfferStateMachine.decide(partial, buy(GrandExchangeOfferState.CANCELLED_BUY, 4, 10), ID, NOW);
        assertEquals(OfferState.CANCELLED_PARTIAL, cancelled.record.getState());

        OfferTransition collected = OfferStateMachine.decide(cancelled.record, buy(GrandExchangeOfferState.EMPTY, 4, 10), ID, NOW);
        assertEquals(OfferState.COLLECTED, collected.record.getState());
        assertEquals(OfferTransition.Kind.COLLECTED, collected.kind);
    }

    @Test
    public void illegalTransition_isRejected_recordUnchanged()
    {
        OfferRecord collected = OfferStateMachine
            .decide(OfferStateMachine.decide(
                    OfferRecord.newOffer(ID, 0, 1234, "Item", true, 10, 100, NOW),
                    buy(GrandExchangeOfferState.BOUGHT, 10, 10), ID, NOW).record,
                buy(GrandExchangeOfferState.EMPTY, 10, 10), ID, NOW).record;

        OfferTransition t = OfferStateMachine.decide(collected, buy(GrandExchangeOfferState.BUYING, 3, 10), ID, NOW);

        assertEquals(OfferTransition.Kind.REJECTED, t.kind);
        assertEquals(OfferState.COLLECTED, t.record.getState());
    }

    @Test
    public void duplicateCancellation_onTerminal_isRejectedNoThrow()
    {
        OfferRecord cancelled = OfferStateMachine
            .decide(OfferRecord.newOffer(ID, 0, 1234, "Item", true, 10, 100, NOW),
                buy(GrandExchangeOfferState.CANCELLED_BUY, 0, 10), ID, NOW).record;

        OfferTransition t = OfferStateMachine.decide(cancelled, buy(GrandExchangeOfferState.CANCELLED_BUY, 0, 10), ID, NOW);

        assertEquals(OfferTransition.Kind.REJECTED, t.kind);
    }

    @Test
    public void instantFillOnPlacement_fromNull_isCompleted()
    {
        // OSRS can fill an offer the instant it is placed (large margin) — the very first
        // event we see is BOUGHT with no prior record. It must mint + complete in one step.
        OfferTransition t = OfferStateMachine.decide(null, buy(GrandExchangeOfferState.BOUGHT, 10, 10), ID, NOW);

        assertEquals(OfferTransition.Kind.COMPLETED, t.kind);
        assertEquals(OfferState.FILLED, t.record.getState());
        assertEquals(ID, t.record.getOfferId());
        assertEquals(10, t.record.getFilledQuantity());
        assertEquals(10, t.newlyFilledQuantity);
    }

    @Test
    public void reseed_fromNull_onCancelledSlot_mintsNothing()
    {
        // A render-tick reseed can observe a cancelled-but-uncollected slot (OSRS reports
        // CANCELLED_BUY/CANCELLED_SELL until the GP/items are collected). With no tracked record,
        // that must NOT fabricate a live phantom offer — the offer is already finished, and a
        // fabricated NEW record could never be terminalized.
        OfferTransition tBuy = OfferStateMachine.decide(null, buy(GrandExchangeOfferState.CANCELLED_BUY, 0, 10), ID, NOW);
        assertEquals(OfferTransition.Kind.NONE, tBuy.kind);
        assertNull(tBuy.record);

        OfferTransition tSell = OfferStateMachine.decide(null, buy(GrandExchangeOfferState.CANCELLED_SELL, 0, 10), ID, NOW);
        assertEquals(OfferTransition.Kind.NONE, tSell.kind);
        assertNull(tSell.record);
    }

    @Test
    public void emptyOnNewOffer_withNoFills_isRejected()
    {
        // A slot cleared before any fill (place-then-instant-cancel-collect in one tick)
        // is a bad/no-op signal, not a collection — must be rejected, state untouched.
        OfferRecord placed = OfferRecord.newOffer(ID, 0, 1234, "Item", true, 10, 100, NOW);

        OfferTransition t = OfferStateMachine.decide(placed, buy(GrandExchangeOfferState.EMPTY, 0, 10), ID, NOW);

        assertEquals(OfferTransition.Kind.REJECTED, t.kind);
        assertEquals(OfferState.NEW, t.record.getState());
    }

    private static OfferSignal signal(int slot, int itemId, int totalQty, int price,
                                      int qtySold, long spent, GrandExchangeOfferState geState)
    {
        return new OfferSignal(slot, geState, itemId, "Abyssal whip", totalQty, price, qtySold, spent);
    }

    @Test
    public void partialFillReportsNewlySpent()
    {
        OfferRecord placed = OfferRecord.newOffer(1, 3, 4151, "Abyssal whip", true, 5, 2_000_000, 1000L);
        OfferSignal s = signal(3, 4151, 5, 2_000_000, 2, 4_000_000, GrandExchangeOfferState.BUYING);
        OfferTransition t = OfferStateMachine.decide(placed, s, 1, 2000L);
        assertEquals(OfferTransition.Kind.FILLED_DELTA, t.kind);
        assertEquals(2, t.newlyFilledQuantity);
        assertEquals(4_000_000L, t.newlySpent);
    }

    @Test
    public void cancelWithResidualFillReportsDelta()
    {
        OfferRecord partial = OfferRecord.newOffer(1, 3, 4151, "Abyssal whip", true, 5, 2_000_000, 1000L)
            .withFill(2, 4_000_000L, OfferState.PARTIAL_FILL, 1500L);
        OfferSignal cancel = signal(3, 4151, 5, 2_000_000, 3, 6_000_000, GrandExchangeOfferState.CANCELLED_BUY);
        OfferTransition t = OfferStateMachine.decide(partial, cancel, 1, 2000L);
        assertEquals(OfferTransition.Kind.CANCELLED, t.kind);
        assertEquals(1, t.newlyFilledQuantity);
        assertEquals(2_000_000L, t.newlySpent);
        assertEquals(OfferState.CANCELLED_PARTIAL, t.record.getState());
        assertEquals(3, t.record.getFilledQuantity());
    }
}

package com.flipsmart;

import com.flipsmart.api.dto.Dtos.ActiveFlipsResponse;
import com.flipsmart.domain.flip.AwaitingSaleLots;
import com.flipsmart.recommend.SmartSellPricer;
import com.flipsmart.trading.OfferStore;

import java.util.concurrent.CompletableFuture;
import java.util.concurrent.atomic.AtomicReference;

import net.runelite.client.game.ItemManager;

import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Manual-mode (Auto Mode off) sell focus must resolve from local state.
 *
 * <p>Prod (#1133): the manual path resolved the sell price only from
 * {@code GET /transactions/active-flips}, which the backend trims to the subscription's
 * display slots — 2 on free tier, unlimited on premium. A free user's held position could
 * be absent from that response, so {@code handleActiveFlipResponse} found no match, never
 * reached {@code setFocusForSell}, and no price was populated at all. Auto Mode was
 * unaffected because it resolves locally, which is why the bug looked free-and-manual only.
 *
 * <p>A display cap must never stop someone selling what they already own.</p>
 */
public class ManualSellFocusLocalResolutionTest
{
	private static final int ITEM_ID = 4151; // Abyssal whip
	private static final String ITEM_NAME = "Abyssal whip";
	private static final int AVG_BUY_PRICE = 1_000_000;
	private static final int HELD_QUANTITY = 3;

	private FlipSmartApiClient apiClient;
	private ActiveFlipTracker activeFlipTracker;
	private GrandExchangeTracker tracker;
	private AtomicReference<FocusedFlip> focus;

	@Before
	public void setUp()
	{
		PlayerSession session = new PlayerSession();
		session.setRsn("TestPlayer");

		apiClient = mock(FlipSmartApiClient.class);
		activeFlipTracker = mock(ActiveFlipTracker.class);
		ItemManager itemManager = mock(ItemManager.class);

		// The backend list is EMPTY throughout: this is the free-tier trim, where the
		// held position never appears in the response the old path depended on.
		when(apiClient.getActiveFlipsAsync(any()))
			.thenReturn(CompletableFuture.completedFuture(new ActiveFlipsResponse()));
		when(activeFlipTracker.getInventoryCountForItem(anyInt())).thenReturn(HELD_QUANTITY);

		tracker = new GrandExchangeTracker(
			session, apiClient, activeFlipTracker, itemManager, mock(TradeActivityLog.class));
		tracker.setOfferStore(new OfferStore());

		focus = new AtomicReference<>();
		tracker.setOnFocusChanged(focus::set);

		// Auto-recommend left unset => manual mode, the path under test.
	}

	/** onFocusChanged is dispatched to the EDT; drain it before asserting. */
	private FocusedFlip awaitFocus() throws Exception
	{
		javax.swing.SwingUtilities.invokeAndWait(() ->
		{
		});
		return focus.get();
	}

	@Test
	public void pricesTheExitFromTheOfferStoreBasisWhenTheBackendListOmitsTheHolding() throws Exception
	{
		tracker.setBuyBasisProvider(
			itemId -> new AwaitingSaleLots.BuyBasis(ITEM_NAME, AVG_BUY_PRICE, null));

		tracker.autoFocusOnActiveFlip(ITEM_ID);

		FocusedFlip focused = awaitFocus();
		assertNotNull("free-tier holding must still be priced for sale", focused);
		assertEquals(ITEM_ID, focused.getItemId());
		assertEquals(HELD_QUANTITY, focused.getSellQuantity());
		assertEquals(SmartSellPricer.calculateMinProfitableSellPrice(AVG_BUY_PRICE),
			focused.getSellPrice());
	}

	@Test
	public void anEmptyBackendListNeitherBlocksNorUndoesTheLocalFocus() throws Exception
	{
		// The lookup still fires — it carries the under-counted-quantity reconciliation —
		// but a response that omits the holding must no longer decide whether a price shows.
		tracker.setBuyBasisProvider(
			itemId -> new AwaitingSaleLots.BuyBasis(ITEM_NAME, AVG_BUY_PRICE, null));

		tracker.autoFocusOnActiveFlip(ITEM_ID);

		verify(apiClient).getActiveFlipsAsync(any());
		assertNotNull("empty backend response must not clear a locally-priced focus", awaitFocus());
	}

	@Test
	public void prefersThePanelPriceOverTheDerivedBreakevenPrice() throws Exception
	{
		tracker.setBuyBasisProvider(
			itemId -> new AwaitingSaleLots.BuyBasis(ITEM_NAME, AVG_BUY_PRICE, null));
		tracker.setDisplayedSellPriceProvider(itemId -> 1_234_567L);

		tracker.autoFocusOnActiveFlip(ITEM_ID);

		assertEquals(1_234_567, awaitFocus().getSellPrice());
	}

	@Test
	public void stillFallsBackToTheBackendLookupWhenNothingLocalCanPriceTheExit() throws Exception
	{
		// No buy basis, no cached price: local resolution genuinely cannot price this,
		// so the original backend path must remain in place.
		tracker.setBuyBasisProvider(itemId -> null);

		tracker.autoFocusOnActiveFlip(ITEM_ID);

		verify(apiClient).getActiveFlipsAsync(any());
		// Nothing priced it, and the stubbed backend list is empty, so no focus is invented.
		assertNull(awaitFocus());
	}

	@Test
	public void doesNotFocusAnItemThePlayerDoesNotHold() throws Exception
	{
		when(activeFlipTracker.getInventoryCountForItem(anyInt())).thenReturn(0);
		tracker.setBuyBasisProvider(
			itemId -> new AwaitingSaleLots.BuyBasis(ITEM_NAME, AVG_BUY_PRICE, null));

		tracker.autoFocusOnActiveFlip(ITEM_ID);

		// Falls through to the backend rather than inventing a quantity out of nothing.
		verify(apiClient).getActiveFlipsAsync(any());
		assertNull(awaitFocus());
	}

	@Test
	public void derivedPriceClearsGeTaxSoTheExitIsNotAGuaranteedLoss() throws Exception
	{
		tracker.setBuyBasisProvider(
			itemId -> new AwaitingSaleLots.BuyBasis(ITEM_NAME, AVG_BUY_PRICE, null));

		tracker.autoFocusOnActiveFlip(ITEM_ID);

		assertTrue("a locally-derived price must still beat breakeven after 2% tax",
			awaitFocus().getSellPrice() * 0.98 > AVG_BUY_PRICE);
	}
}

package com.flipsmart;

import com.flipsmart.api.dto.Dtos.FavoriteItem;
import com.flipsmart.ui.panel.FavoritesSort;
import com.flipsmart.ui.panel.Paginator;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class FavoritesSortAndPaginationTest
{
	private FavoriteItem item(String name, int profit, int volume)
	{
		FavoriteItem i = new FavoriteItem();
		i.setItemName(name);
		i.setProfit(profit);
		i.setVolume(volume);
		return i;
	}

	@Test
	public void profitSortsHighToLow()
	{
		List<FavoriteItem> list = new ArrayList<>();
		list.add(item("A", 100, 1));
		list.add(item("B", 300, 1));
		list.add(item("C", 200, 1));
		list.sort(FavoritesSort.PROFIT.comparator());
		assertEquals("B", list.get(0).getItemName());
		assertEquals("C", list.get(1).getItemName());
		assertEquals("A", list.get(2).getItemName());
	}

	@Test
	public void volumeSortsHighToLow()
	{
		List<FavoriteItem> list = new ArrayList<>();
		list.add(item("A", 1, 50));
		list.add(item("B", 1, 90));
		list.sort(FavoritesSort.VOLUME.comparator());
		assertEquals("B", list.get(0).getItemName());
	}

	@Test
	public void alphabeticalSortsAtoZCaseInsensitive()
	{
		List<FavoriteItem> list = new ArrayList<>();
		list.add(item("banana", 1, 1));
		list.add(item("Apple", 1, 1));
		list.sort(FavoritesSort.ALPHABETICAL.comparator());
		assertEquals("Apple", list.get(0).getItemName());
		assertEquals("banana", list.get(1).getItemName());
	}

	@Test
	public void paginationSlicesAndCountsPages()
	{
		List<Integer> items = new ArrayList<>();
		for (int i = 0; i < 23; i++)
		{
			items.add(i);
		}
		assertEquals(3, Paginator.pageCount(23, 10));
		assertEquals(10, Paginator.page(items, 0, 10).size());
		assertEquals(3, Paginator.page(items, 2, 10).size()); // last partial page
		assertEquals(0, Paginator.page(items, 5, 10).size()); // out-of-range page
		assertEquals(1, Paginator.pageCount(0, 10)); // empty still one page
	}
}

package com.flipsmart;

import com.flipsmart.domain.flip.ActiveFlip;
import java.util.List;
import java.util.Optional;
import java.util.concurrent.CompletableFuture;
import org.junit.Before;
import org.junit.Test;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class ActiveFlipsSnapshotPushServiceTest
{
	private static final String RSN = "zezima";

	private FlipSmartApiClient apiClient;
	private PlayerSession session;
	private ActiveFlipsSnapshotPushService service;

	private static ActiveFlip flip(int itemId, int filledSoFar)
	{
		ActiveFlip f = new ActiveFlip();
		f.setItemId(itemId);
		f.setPhase("sell");
		f.setOrderQuantity(100);
		f.setTotalQuantity(filledSoFar);
		return f;
	}

	@Before
	public void setUp()
	{
		apiClient = mock(FlipSmartApiClient.class);
		session = mock(PlayerSession.class);
		when(session.getRsnSafe()).thenReturn(Optional.of(RSN));
		when(apiClient.pushActiveFlipsSnapshotAsync(any(), any()))
			.thenReturn(CompletableFuture.completedFuture(true));
		service = new ActiveFlipsSnapshotPushService(apiClient, session);
	}

	@Test
	public void pushesTheProjection() throws Exception
	{
		service.scheduleSnapshotPush(() -> List.of(flip(4151, 0)));
		verify(apiClient, timeout(3000).times(1)).pushActiveFlipsSnapshotAsync(eq(RSN), any());
	}

	@Test
	public void identicalProjectionIsNotPushedTwice() throws Exception
	{
		service.scheduleSnapshotPush(() -> List.of(flip(4151, 0)));
		verify(apiClient, timeout(3000).times(1)).pushActiveFlipsSnapshotAsync(any(), any());
		service.scheduleSnapshotPush(() -> List.of(flip(4151, 0)));
		// after() blocks the full window so this actually waits out the second
		// debounced push instead of just sampling a moment right after scheduling.
		verify(apiClient, after(2500).times(1)).pushActiveFlipsSnapshotAsync(any(), any());
	}

	@Test
	public void fillProgressAloneDoesNotTriggerAPush() throws Exception
	{
		// Same set of flips, more filled. Fill ticks fire constantly; if they
		// each pushed, an actively-filling order would spam the API.
		service.scheduleSnapshotPush(() -> List.of(flip(4151, 0)));
		verify(apiClient, timeout(3000).times(1)).pushActiveFlipsSnapshotAsync(any(), any());
		service.scheduleSnapshotPush(() -> List.of(flip(4151, 70)));
		verify(apiClient, after(2500).times(1)).pushActiveFlipsSnapshotAsync(any(), any());
	}

	@Test
	public void aNewItemTriggersAPush() throws Exception
	{
		service.scheduleSnapshotPush(() -> List.of(flip(4151, 0)));
		verify(apiClient, timeout(3000).times(1)).pushActiveFlipsSnapshotAsync(any(), any());
		service.scheduleSnapshotPush(() -> List.of(flip(4151, 0), flip(561, 0)));
		verify(apiClient, timeout(3000).times(2)).pushActiveFlipsSnapshotAsync(any(), any());
	}

	@Test
	public void emptyProjectionIsPushed() throws Exception
	{
		// "No active flips" must reach the server — it is what clears the dashboard.
		service.scheduleSnapshotPush(() -> List.of(flip(4151, 0)));
		verify(apiClient, timeout(3000).times(1)).pushActiveFlipsSnapshotAsync(any(), any());
		service.scheduleSnapshotPush(List::of);
		verify(apiClient, timeout(3000).times(2)).pushActiveFlipsSnapshotAsync(any(), any());
	}

	@Test
	public void failedPushDoesNotAdvanceTheDedupBaseline() throws Exception
	{
		// v1 bug: baseline recorded what was ATTEMPTED. A dropped push then
		// suppressed the retry, and AC2 (cancel disappears) silently failed.
		when(apiClient.pushActiveFlipsSnapshotAsync(any(), any()))
			.thenReturn(CompletableFuture.completedFuture(false));
		service.scheduleSnapshotPush(() -> List.of(flip(4151, 0)));
		verify(apiClient, timeout(3000).times(1)).pushActiveFlipsSnapshotAsync(any(), any());

		when(apiClient.pushActiveFlipsSnapshotAsync(any(), any()))
			.thenReturn(CompletableFuture.completedFuture(true));
		service.scheduleSnapshotPush(() -> List.of(flip(4151, 0)));
		verify(apiClient, timeout(3000).times(2)).pushActiveFlipsSnapshotAsync(any(), any());
	}

	@Test
	public void noRsnMeansNoPush() throws Exception
	{
		when(session.getRsnSafe()).thenReturn(Optional.empty());
		service.scheduleSnapshotPush(() -> List.of(flip(4151, 0)));
		verify(apiClient, after(2500).never()).pushActiveFlipsSnapshotAsync(any(), any());
	}

	@Test
	public void supplierIsEvaluatedAtSendTimeNotScheduleTime() throws Exception
	{
		// Regression: captured_at is stamped when the endpoint is called, which is
		// when the supplier runs here. If the caller captured the list up-front
		// instead of deferring to the supplier, this test would observe the stale
		// value instead of the one set right before firing.
		java.util.concurrent.atomic.AtomicReference<List<ActiveFlip>> latest =
			new java.util.concurrent.atomic.AtomicReference<>(List.of(flip(4151, 0)));

		service.scheduleSnapshotPush(latest::get);
		latest.set(List.of(flip(4151, 0), flip(561, 0)));

		verify(apiClient, timeout(3000).times(1))
			.pushActiveFlipsSnapshotAsync(eq(RSN), eq(latest.get()));
	}

	@Test
	public void nullFromSupplierSkipsThePush() throws Exception
	{
		// A null result signals "emptiness wasn't observed" (e.g. login burst) —
		// the service must not attempt a push at all, not even an empty one.
		service.scheduleSnapshotPush(() -> null);
		verify(apiClient, after(2500).never()).pushActiveFlipsSnapshotAsync(any(), any());
	}

	/**
	 * Mirrors the TradeStationSlotPushService regression: the service is a singleton and RuneLite
	 * reuses the plugin instance across disable/enable, so a scheduler terminated by shutdown()
	 * stayed terminated for the life of the client. Every snapshot push after a plugin toggle was
	 * then rejected and swallowed, so the website's Active Flips mirror silently stopped updating.
	 * Observed in-game on 2026-08-05, after the sibling service had already been fixed.
	 */
	@Test
	public void scheduleAfterShutdownRebuildsTheExecutorInsteadOfBeingRejected()
	{
		service.shutdown();

		service.scheduleSnapshotPush(() -> List.of(flip(4151, 0)));

		// Must actually run on a rebuilt executor, not merely fail quietly in the catch block.
		verify(apiClient, timeout(5000).times(1)).pushActiveFlipsSnapshotAsync(eq(RSN), any());
	}
}

