package com.flipsmart;

import org.junit.Test;
import java.awt.Color;
import java.awt.image.BufferedImage;
import static org.junit.Assert.assertEquals;

public class SpriteOutlineTest
{
    private static final Color GREEN = new Color(0, 255, 0);
    private static final int OPAQUE = GREEN.getRGB();

    @Test
    public void topEdgePieceDrawsLineAtSlotBorderNotSpriteEdge()
    {
        // Mirrors the vanilla top edge piece: 83x32 overhanging 13px above the slot (relY=-13).
        BufferedImage out = SpriteOutline.build(83, 32, SpriteOutline.TOP, GREEN, 2, 16, -13, 115, 110);

        // The slot's top border sits at piece-local y = -relY = 13, not at the sprite's own top (y=0).
        assertEquals(OPAQUE, out.getRGB(40, 13));
        assertEquals("sprite top (above the slot) stays transparent", 0, out.getRGB(40, 0));
        assertEquals("below the border line stays transparent", 0, out.getRGB(40, 20));
    }

    @Test
    public void rightEdgePieceDrawsLineAtSlotRightBorder()
    {
        // Vanilla right edge piece: 32x78 at relX=95; slot right border = slotWidth - relX - t = 18.
        BufferedImage out = SpriteOutline.build(32, 78, SpriteOutline.RIGHT, GREEN, 2, 95, 16, 115, 110);

        assertEquals(OPAQUE, out.getRGB(18, 40));
        assertEquals("sprite right edge (past the slot) stays transparent", 0, out.getRGB(31, 40));
        assertEquals("sprite left stays transparent", 0, out.getRGB(0, 40));
    }

    @Test
    public void alignedCornerDrawsTwoEdgesAtItsOwnCorner()
    {
        // Top-left corner is aligned to the slot (relX=relY=0), so the formula resolves to its own edges.
        BufferedImage out = SpriteOutline.build(32, 32, SpriteOutline.TOP | SpriteOutline.LEFT, GREEN, 2, 0, 0, 115, 110);

        assertEquals("top line", OPAQUE, out.getRGB(15, 0));
        assertEquals("left line", OPAQUE, out.getRGB(0, 15));
        assertEquals("interior transparent", 0, out.getRGB(16, 16));
    }
}

package com.flipsmart;

import net.runelite.api.Client;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import org.junit.Before;
import org.junit.Test;

import java.util.concurrent.CompletableFuture;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * The "Show Item Info" setting (#1222), which lets a player keep the native GE
 * offer screen instead of our breakeven/tax/profit description.
 *
 * <p>Turning it off is implemented as "stop writing" rather than "undo what we
 * wrote": Jagex's own script repaints the description on the next panel build,
 * so the native text returns without us restoring it by hand.</p>
 */
public class GeItemInfoToggleTest
{
	private static final int CANNONBALL_ID = 2;
	private static final String NATIVE_TEXT = "Cannonball<br>A heavy metal ball.";

	private Client client;
	private FlipSmartConfig config;
	private Object[] objectStack;
	private GeOfferDescriptionService service;

	@Before
	public void setUp()
	{
		client = mock(Client.class);
		config = mock(FlipSmartConfig.class);

		FlipSmartApiClient apiClient = mock(FlipSmartApiClient.class);
		when(apiClient.getDailyVolumeAsync(anyInt())).thenReturn(CompletableFuture.completedFuture(null));

		objectStack = new Object[]{NATIVE_TEXT};
		when(client.getObjectStack()).thenReturn(objectStack);
		when(client.getObjectStackSize()).thenReturn(1);
		when(client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH)).thenReturn(CANNONBALL_ID);

		service = new GeOfferDescriptionService(
			client,
			mock(ClientThread.class),
			apiClient,
			mock(FlipSmartPlugin.class),
			mock(ItemManager.class),
			mock(FlipAssistOverlay.class),
			mock(ConfigManager.class),
			config);
	}

	private static ScriptCallbackEvent buyExamine()
	{
		ScriptCallbackEvent event = mock(ScriptCallbackEvent.class);
		when(event.getEventName()).thenReturn(GeOfferDescriptionService.EVENT_BUY_EXAMINE);
		return event;
	}

	// -----------------------------------------------------------------
	// AC2 — on (default) behaves exactly as before
	// -----------------------------------------------------------------

	@Test
	public void ourDescriptionReplacesTheNativeTextWhenTheSettingIsOn()
	{
		when(config.showGeItemInfo()).thenReturn(true);

		assertEquals("the buy-examine callback is ours to handle", true,
			service.onScriptCallbackEvent(buyExamine()));
		assertNotEquals("the native examine text is replaced", NATIVE_TEXT, objectStack[0]);
	}

	@Test
	public void theNativeFeeAndGraphicAreHiddenWhenTheSettingIsOn()
	{
		when(config.showGeItemInfo()).thenReturn(true);
		Widget fee = mock(Widget.class);
		when(client.getWidget(InterfaceID.GeOffers.SETUP_FEE)).thenReturn(fee);

		service.onSetupBuildScriptPostFired();

		verify(fee).setHidden(true);
	}

	// -----------------------------------------------------------------
	// AC3 — off leaves the GE screen untouched
	// -----------------------------------------------------------------

	@Test
	public void theNativeExamineTextSurvivesWhenTheSettingIsOff()
	{
		when(config.showGeItemInfo()).thenReturn(false);

		assertEquals("the callback is declined so the game keeps its own text", false,
			service.onScriptCallbackEvent(buyExamine()));
		assertEquals("the native examine text is left in place", NATIVE_TEXT, objectStack[0]);
	}

	@Test
	public void theNativeFeeAndGraphicStayVisibleWhenTheSettingIsOff()
	{
		when(config.showGeItemInfo()).thenReturn(false);
		Widget fee = mock(Widget.class);
		when(client.getWidget(InterfaceID.GeOffers.SETUP_FEE)).thenReturn(fee);

		service.onSetupBuildScriptPostFired();

		verify(fee, never()).setHidden(true);
	}

	@Test
	public void theOfferStatusPanelIsNotTouchedWhenTheSettingIsOff()
	{
		when(config.showGeItemInfo()).thenReturn(false);

		service.onBeforeRender(mock(BeforeRender.class));

		// Reading no widget at all is the strongest available proof that the
		// per-frame description write never starts.
		verify(client, never()).getWidget(anyInt());
	}
}

package com.flipsmart.plugin;

import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class RsnSyncGateTest
{
	private static final String RSN_A = "PlayerOne";
	private static final String RSN_B = "PlayerTwo";

	@Test
	public void pushesAnRsnItHasNeverSeen()
	{
		assertTrue(new RsnSyncGate().shouldPush(RSN_A));
	}

	@Test
	public void suppressesRepeatPushOfConfirmedRsn()
	{
		RsnSyncGate gate = new RsnSyncGate();
		gate.markPushed(RSN_A);
		assertFalse("world hops re-trigger sync; a confirmed RSN must not re-push", gate.shouldPush(RSN_A));
	}

	@Test
	public void pushesAgainWhenRsnChanges()
	{
		RsnSyncGate gate = new RsnSyncGate();
		gate.markPushed(RSN_A);
		assertTrue(gate.shouldPush(RSN_B));
	}

	@Test
	public void unconfirmedPushStaysEligibleForRetry()
	{
		RsnSyncGate gate = new RsnSyncGate();
		assertTrue(gate.shouldPush(RSN_A));
		assertTrue("no markPushed happened, so the next transition must retry", gate.shouldPush(RSN_A));
	}

	@Test
	public void resetForcesRepush()
	{
		RsnSyncGate gate = new RsnSyncGate();
		gate.markPushed(RSN_A);
		gate.reset();
		assertTrue(gate.shouldPush(RSN_A));
	}

	@Test
	public void neverPushesNullOrEmpty()
	{
		RsnSyncGate gate = new RsnSyncGate();
		assertFalse(gate.shouldPush(null));
		assertFalse(gate.shouldPush(""));
	}

	@Test
	public void accountSwitchBackAndForthPushesEachSwitch()
	{
		RsnSyncGate gate = new RsnSyncGate();
		gate.markPushed(RSN_A);
		gate.markPushed(RSN_B);
		assertTrue(gate.shouldPush(RSN_A));
	}
}

package com.flipsmart.plugin;

import com.flipsmart.BankSnapshotService;
import com.flipsmart.FlipSmartConfig;
import com.flipsmart.FlipSmartPlugin;
import com.flipsmart.FlipSmartApiClient;
import com.flipsmart.GEHistoryService;
import com.flipsmart.GeOfferDescriptionService;
import com.flipsmart.GrandExchangeTracker;
import com.flipsmart.OfflineSyncService;
import com.flipsmart.PlayerSession;
import com.flipsmart.WebhookSyncService;
import com.flipsmart.trading.OfferStore;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.chat.ChatMessageManager;

import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * The GE History read latch has to be cleared on every transition that clears
 * {@code offlineSyncCompleted}, not only on a full logout.
 *
 * <p>{@code HOPPING} and {@code CONNECTION_LOST} reset the session's sync flag so the
 * offline sync runs again on the following {@code LOGGED_IN}, but
 * {@code GEHistoryService.reset()} used to be reachable only from {@code LOGIN_SCREEN}.
 * The latch therefore survived, and {@code registerOfflineFill} short-circuits on it — so
 * once a player had opened the History tab at any point in a session, every subsequent
 * world hop and reconnect dropped its offline fills with no prompt and no scrape.</p>
 */
public class EventRouterHopResetTest
{
	private GEHistoryService geHistoryService;
	private EventRouter router;

	/** A visible History list holding one "Bought:" row (4151 x5 @ 2,000). */
	private Widget visibleHistoryList()
	{
		Widget header = mock(Widget.class);
		when(header.getText()).thenReturn("Bought:");
		Widget item = mock(Widget.class);
		when(item.getItemId()).thenReturn(4151);
		when(item.getItemQuantity()).thenReturn(5);
		Widget price = mock(Widget.class);
		when(price.getText()).thenReturn("<col=ffb83f>10,000 coins</col><br>= 2,000 each");

		Widget list = mock(Widget.class);
		when(list.isHidden()).thenReturn(false);
		when(list.getDynamicChildren()).thenReturn(new Widget[]{header, item, price});
		return list;
	}

	@Before
	public void setUp()
	{
		Client client = mock(Client.class);
		// Built before the outer stubbing call: Mockito rejects a nested when() that lands
		// inside an in-progress one.
		Widget historyList = visibleHistoryList();
		when(client.getWidget(InterfaceID.GE_HISTORY, 3)).thenReturn(historyList);

		geHistoryService = new GEHistoryService(client, mock(FlipSmartApiClient.class),
			mock(PlayerSession.class), mock(ChatMessageManager.class), new OfferStore());

		router = new EventRouter(
			mock(FlipSmartPlugin.class),
			client,
			mock(FlipSmartConfig.class),
			mock(PlayerSession.class),
			mock(WebhookSyncService.class),
			mock(OfflineSyncService.class),
			mock(BankSnapshotService.class),
			geHistoryService,
			mock(GeOfferDescriptionService.class),
			mock(GrandExchangeTracker.class),
			new OfferStore());
	}

	private static GameStateChanged state(GameState gameState)
	{
		GameStateChanged event = new GameStateChanged();
		event.setGameState(gameState);
		return event;
	}

	/** Read the History tab so the latch is set, exactly as a real session would. */
	private void latchHistoryRead()
	{
		geHistoryService.onHistoryWidgetLoaded();
		geHistoryService.onGameTick();
		geHistoryService.onGameTick();
		geHistoryService.registerOfflineFill(4151);
		assertFalse("precondition: a completed read latches the flag",
			geHistoryService.hasUnverifiedOfflineFills());
	}

	@Test
	public void worldHopClearsHistoryLatchSoLaterOfflineFillsRegister()
	{
		latchHistoryRead();

		router.onGameStateChanged(state(GameState.HOPPING));
		geHistoryService.registerOfflineFill(4151);

		assertTrue(geHistoryService.hasUnverifiedOfflineFills());
	}

	@Test
	public void connectionLostClearsHistoryLatchSoLaterOfflineFillsRegister()
	{
		latchHistoryRead();

		router.onGameStateChanged(state(GameState.CONNECTION_LOST));
		geHistoryService.registerOfflineFill(4151);

		assertTrue(geHistoryService.hasUnverifiedOfflineFills());
	}
}

