package com.flipsmart.plugin;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.BiConsumer;

import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

public class PanelRefreshCoalescerTest
{
	/** Records scheduled one-shots so tests control time and firing explicitly. */
	private static final class FakeScheduler implements BiConsumer<Integer, Runnable>
	{
		final List<Integer> delays = new ArrayList<>();
		final AtomicReference<Runnable> pending = new AtomicReference<>();

		@Override
		public void accept(Integer delayMs, Runnable action)
		{
			delays.add(delayMs);
			pending.set(action);
		}

		void fire()
		{
			pending.getAndSet(null).run();
		}
	}

	private FakeScheduler scheduler;
	private long now;
	private int fullRefreshes;
	private int activeFlipsRefreshes;
	private PanelRefreshCoalescer coalescer;

	@Before
	public void setUp()
	{
		scheduler = new FakeScheduler();
		now = 0;
		fullRefreshes = 0;
		activeFlipsRefreshes = 0;
		coalescer = new PanelRefreshCoalescer(scheduler, () -> now,
			() -> fullRefreshes++, () -> activeFlipsRefreshes++);
	}

	@Test
	public void requestNeverRefreshesSynchronously()
	{
		coalescer.request(true);
		coalescer.request(false);

		assertEquals(0, fullRefreshes);
		assertEquals(0, activeFlipsRefreshes);
	}

	@Test
	public void singleFullRequestFiresOneFullRefreshAfterQuietWindow()
	{
		coalescer.request(true);
		assertEquals(1, scheduler.delays.size());
		assertEquals(PanelRefreshCoalescer.QUIET_WINDOW_MS, (int) scheduler.delays.get(0));

		now = PanelRefreshCoalescer.QUIET_WINDOW_MS;
		scheduler.fire();

		assertEquals(1, fullRefreshes);
		assertEquals(0, activeFlipsRefreshes);
		assertNull(scheduler.pending.get());
	}

	@Test
	public void burstCoalescesIntoOneRefresh()
	{
		coalescer.request(true);
		now = 1_000;
		coalescer.request(false);
		now = 2_000;
		coalescer.request(true);

		assertEquals(1, scheduler.delays.size());

		now = 5_000;
		scheduler.fire();
		assertEquals(0, fullRefreshes);
		assertNotNull(scheduler.pending.get());
		assertEquals(2_000, (int) scheduler.delays.get(1));

		now = 7_000;
		scheduler.fire();
		assertEquals(1, fullRefreshes);
		assertEquals(0, activeFlipsRefreshes);
	}

	@Test
	public void activeFlipsOnlyRequestFiresActiveFlipsRefresh()
	{
		coalescer.request(false);

		now = PanelRefreshCoalescer.QUIET_WINDOW_MS;
		scheduler.fire();

		assertEquals(0, fullRefreshes);
		assertEquals(1, activeFlipsRefreshes);
	}

	@Test
	public void fullRequestUpgradesPendingWindow()
	{
		coalescer.request(false);
		now = 1_000;
		coalescer.request(true);

		now = 6_000;
		scheduler.fire();

		assertEquals(1, fullRefreshes);
		assertEquals(0, activeFlipsRefreshes);
	}

	@Test
	public void continuousStreamFiresByMaxWait()
	{
		coalescer.request(false);
		now = 4_000;
		coalescer.request(false);

		now = 5_000;
		scheduler.fire();
		assertEquals(0, activeFlipsRefreshes);

		now = 8_000;
		coalescer.request(false);

		now = 9_000;
		scheduler.fire();
		assertEquals(0, activeFlipsRefreshes);
		assertEquals(1_000, (int) scheduler.delays.get(2));

		now = PanelRefreshCoalescer.MAX_WAIT_MS;
		scheduler.fire();
		assertEquals(1, activeFlipsRefreshes);
	}

	@Test
	public void windowReopensAfterFiring()
	{
		coalescer.request(true);
		now = 5_000;
		scheduler.fire();
		assertEquals(1, fullRefreshes);

		now = 20_000;
		coalescer.request(true);
		assertEquals(2, scheduler.delays.size());

		now = 25_000;
		scheduler.fire();
		assertEquals(2, fullRefreshes);
	}

	@Test
	public void requestSoonFiresAfterShortWindow()
	{
		coalescer.requestSoon(true);
		assertEquals(1, scheduler.delays.size());
		assertEquals(PanelRefreshCoalescer.FAST_QUIET_WINDOW_MS, (int) scheduler.delays.get(0));

		now = PanelRefreshCoalescer.FAST_QUIET_WINDOW_MS;
		scheduler.fire();

		assertEquals(1, fullRefreshes);
		assertEquals(0, activeFlipsRefreshes);
	}

	@Test
	public void fastRequestShortensAnOpenSlowWindow()
	{
		coalescer.request(true);
		now = 1_000;
		coalescer.requestSoon(true);

		// The slow window's one-shot fires; the fast join shrank the quiet window, so
		// sinceLast (4000) already exceeds it and the refresh fires instead of rescheduling.
		now = 5_000;
		scheduler.fire();

		assertEquals(1, fullRefreshes);
	}

	@Test
	public void quietWindowResetsToDefaultAfterFastCycle()
	{
		coalescer.requestSoon(true);
		now = PanelRefreshCoalescer.FAST_QUIET_WINDOW_MS;
		scheduler.fire();
		assertEquals(1, fullRefreshes);

		// A later ordinary request must use the full window again, not the fast one.
		now = 20_000;
		coalescer.request(true);
		assertEquals(PanelRefreshCoalescer.QUIET_WINDOW_MS, (int) scheduler.delays.get(1));
	}

	@Test
	public void fullFlagResetsBetweenWindows()
	{
		coalescer.request(true);
		now = 5_000;
		scheduler.fire();
		assertEquals(1, fullRefreshes);

		now = 20_000;
		coalescer.request(false);
		now = 25_000;
		scheduler.fire();

		assertEquals(1, fullRefreshes);
		assertEquals(1, activeFlipsRefreshes);
	}
}

package com.flipsmart.plugin;

import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.fail;

/**
 * Regression coverage for issue #917: a manual refresh must reset BOTH the visual
 * countdown and the underlying refresh scheduler together. The countdown deadline
 * ({@code nextFlipFinderRefreshAtMillis}) is the single source of truth the panel's
 * label reads, so asserting it here proves the label and the actual trigger stay in
 * step — the next auto-refresh always sits a full interval after the manual refresh.
 */
public class PluginSchedulerTest
{
	private static final int FIVE_MINUTES = 5;
	private static final long FIVE_MINUTES_MS = FIVE_MINUTES * 60 * 1000L;

	private long now;
	private PluginScheduler scheduler;

	@Before
	public void setUp()
	{
		now = 0;
		scheduler = new PluginScheduler(() -> now);
	}

	@After
	public void tearDown()
	{
		scheduler.stopFlipFinderRefreshTimer();
		scheduler.stopActiveFlipsSnapshotTimer();
	}

	/** AC5(b): starting the timer aligns the next refresh to a full interval from now. */
	@Test
	public void startAlignsNextRefreshToFullInterval()
	{
		scheduler.startFlipFinderRefreshTimer(FIVE_MINUTES, () -> true, () -> { });

		assertEquals(FIVE_MINUTES_MS, scheduler.getNextFlipFinderRefreshAtMillis());
	}

	/**
	 * AC4 / AC5(c): a manual refresh part-way through the cycle restarts the timer, so
	 * the next auto-refresh fires a full interval from the manual click — never early on
	 * the stale original deadline (which was the bug).
	 */
	@Test
	public void manualRefreshRealignsNextRefreshToFullIntervalFromNow()
	{
		scheduler.startFlipFinderRefreshTimer(FIVE_MINUTES, () -> true, () -> { });
		assertEquals(FIVE_MINUTES_MS, scheduler.getNextFlipFinderRefreshAtMillis());

		// Player manually refreshes 200s into the 300s cycle.
		now = 200_000;
		scheduler.startFlipFinderRefreshTimer(FIVE_MINUTES, () -> true, () -> { });

		// Next auto-refresh is a FULL interval from the manual refresh, not the stale 300_000.
		assertEquals(now + FIVE_MINUTES_MS, scheduler.getNextFlipFinderRefreshAtMillis());
	}

	/** Stopping the timer clears the deadline so the label falls back to its default. */
	@Test
	public void stopClearsNextRefreshDeadline()
	{
		scheduler.startFlipFinderRefreshTimer(FIVE_MINUTES, () -> true, () -> { });
		scheduler.stopFlipFinderRefreshTimer();

		assertEquals(0, scheduler.getNextFlipFinderRefreshAtMillis());
	}

	/** The configured interval is clamped to at least one minute before scheduling. */
	@Test
	public void intervalIsClampedToConfiguredMinimum()
	{
		scheduler.startFlipFinderRefreshTimer(0, () -> true, () -> { });

		assertEquals(60_000L, scheduler.getNextFlipFinderRefreshAtMillis());
	}

	/** The Active Flips heartbeat is a fixed 5 minutes, independent of the flip-finder setting. */
	@Test
	public void activeFlipsSnapshotIntervalIsFiveMinutes()
	{
		assertEquals(5 * 60 * 1000L, PluginScheduler.ACTIVE_FLIPS_SNAPSHOT_INTERVAL_MS);
	}

	/** Starting the heartbeat twice must cancel the prior timer rather than leaking it. */
	@Test
	public void activeFlipsSnapshotTimerStartAndStopIsIdempotent()
	{
		try
		{
			scheduler.startActiveFlipsSnapshotTimer(() -> true, () -> { });
			scheduler.startActiveFlipsSnapshotTimer(() -> true, () -> { });
			scheduler.stopActiveFlipsSnapshotTimer();
			scheduler.stopActiveFlipsSnapshotTimer();
		}
		catch (RuntimeException e)
		{
			fail("double start/stop must not throw: " + e.getMessage());
		}
	}

	/** Stopping a timer that was never started must be a no-op, not a NullPointerException. */
	@Test
	public void stoppingActiveFlipsSnapshotTimerBeforeStartIsSafe()
	{
		try
		{
			scheduler.stopActiveFlipsSnapshotTimer();
		}
		catch (RuntimeException e)
		{
			fail("stopping before start must not throw: " + e.getMessage());
		}
	}
}

