import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class ApiHttpTransportBackoffTest
{
	private final long[] now = {0L};
	private OkHttpClient httpClient;
	private Call call;
	private ApiBackoffGate gate;
	private ApiHttpTransport transport;

	@Before
	public void setUp()
	{
		httpClient = mock(OkHttpClient.class);
		call = mock(Call.class);
		when(httpClient.newCall(any(Request.class))).thenReturn(call);
		gate = new ApiBackoffGate(new Random(1), () -> now[0]);
		transport = new ApiHttpTransport(httpClient, new Gson(), mock(FlipSmartConfig.class), gate);
	}

	private static Request request()
	{
		return new Request.Builder().url("https://api.flipsm.art/test").build();
	}

	private static Response response(Request req, int code)
	{
		return new Response.Builder()
			.request(req)
			.protocol(Protocol.HTTP_1_1)
			.code(code)
			.message("test")
			.body(ResponseBody.create(ApiHttpTransport.JSON, "{}"))
			.build();
	}

	private Callback enqueuedCallback()
	{
		ArgumentCaptor<Callback> captor = ArgumentCaptor.forClass(Callback.class);
		verify(call).enqueue(captor.capture());
		return captor.getValue();
	}

	@Test
	public void shortCircuitsDuringCooldownWithoutSendingRequest() throws Exception
	{
		gate.recordFailure();
		AtomicReference<String> error = new AtomicReference<>();

		CompletableFuture<String> future =
			transport.executeAsync(request(), body -> body, error::set, false);

		assertNull(future.get());
		assertEquals("API backing off after repeated failures", error.get());
		verify(httpClient, never()).newCall(any(Request.class));
	}

	@Test
	public void serverErrorOpensTheGate() throws Exception
	{
		Request req = request();
		CompletableFuture<String> future =
			transport.executeAsync(req, body -> body, null, false);
		enqueuedCallback().onResponse(call, response(req, 500));
		assertNull(future.get());

		transport.executeAsync(request(), body -> body, null, false);
		verify(httpClient, times(1)).newCall(any(Request.class));
	}

	@Test
	public void ioFailureOpensTheGate() throws Exception
	{
		CompletableFuture<String> future =
			transport.executeAsync(request(), body -> body, null, false);
		enqueuedCallback().onFailure(call, new IOException("timeout"));
		assertNull(future.get());

		transport.executeAsync(request(), body -> body, null, false);
		verify(httpClient, times(1)).newCall(any(Request.class));
	}

	@Test
	public void tooManyRequestsOpensTheGate() throws Exception
	{
		Request req = request();
		CompletableFuture<String> future =
			transport.executeAsync(req, body -> body, null, false);
		enqueuedCallback().onResponse(call, response(req, 429));
		assertNull(future.get());

		transport.executeAsync(request(), body -> body, null, false);
		verify(httpClient, times(1)).newCall(any(Request.class));
	}

	@Test
	public void clientErrorDoesNotOpenTheGate() throws Exception
	{
		Request req = request();
		CompletableFuture<String> future =
			transport.executeAsync(req, body -> body, null, false);
		enqueuedCallback().onResponse(call, response(req, 404));
		assertNull(future.get());

		transport.executeAsync(request(), body -> body, null, false);
		verify(httpClient, times(2)).newCall(any(Request.class));
	}

	@Test
	public void successClosesTheGate() throws Exception
	{
		Request req = request();
		transport.executeAsync(req, body -> body, null, false);
		enqueuedCallback().onFailure(call, new IOException("down"));

		now[0] += ApiBackoffGate.MAX_COOLDOWN_MS;
		Call recoveryCall = mock(Call.class);
		when(httpClient.newCall(any(Request.class))).thenReturn(recoveryCall);
		CompletableFuture<String> future =
			transport.executeAsync(req, body -> body, null, false);
		ArgumentCaptor<Callback> captor = ArgumentCaptor.forClass(Callback.class);
		verify(recoveryCall).enqueue(captor.capture());
		captor.getValue().onResponse(recoveryCall, response(req, 200));
		assertEquals("{}", future.get());

		transport.executeAsync(request(), body -> body, null, false);
		verify(httpClient, times(3)).newCall(any(Request.class));
	}
}

package com.flipsmart.api;

import com.flipsmart.FlipSmartConfig;
import com.google.gson.Gson;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.atomic.AtomicInteger;
import okhttp3.Call;
import okhttp3.OkHttpClient;
import okhttp3.Protocol;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.junit.Before;
import org.junit.Test;
import org.mockito.ArgumentCaptor;
import okhttp3.Callback;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class ApiHttpTransportAuthFailureTest
{
	private OkHttpClient httpClient;
	private Call call;
	private ApiHttpTransport transport;

	@Before
	public void setUp()
	{
		httpClient = mock(OkHttpClient.class);
		call = mock(Call.class);
		when(httpClient.newCall(any(Request.class))).thenReturn(call);
		// Mocked config returns null email/password, so password login always fails validation.
		transport = new ApiHttpTransport(httpClient, new Gson(), mock(FlipSmartConfig.class));
	}

	private static Request.Builder authRequest()
	{
		return new Request.Builder().url("https://api.flipsm.art/protected");
	}

	private static Response response(int code)
	{
		Request req = new Request.Builder().url("https://api.flipsm.art/auth/refresh").build();
		return new Response.Builder()
			.request(req)
			.protocol(Protocol.HTTP_1_1)
			.code(code)
			.message("test")
			.body(ResponseBody.create(ApiHttpTransport.JSON, "{}"))
			.build();
	}

	@Test
	public void terminalAuthFailurePromptsReloginExactlyOnce() throws Exception
	{
		AtomicInteger prompts = new AtomicInteger();
		transport.setOnAuthFailure(prompts::incrementAndGet);

		// No refresh token and no credentials -> auth is terminally unrecoverable.
		assertNull(transport.executeAuthenticatedAsync(authRequest(), body -> body).get());
		assertNull(transport.executeAuthenticatedAsync(authRequest(), body -> body).get());

		// A burst of failures raises the prompt once, not once per request.
		assertEquals(1, prompts.get());
	}

	@Test
	public void logoutRearmsPromptForNextFailureEpisode() throws Exception
	{
		AtomicInteger prompts = new AtomicInteger();
		transport.setOnAuthFailure(prompts::incrementAndGet);

		assertNull(transport.executeAuthenticatedAsync(authRequest(), body -> body).get());
		assertEquals(1, prompts.get());

		transport.clearAuth();

		// A fresh failure episode after logout must prompt again, not stay
		// suppressed by the flag from the previous episode.
		assertNull(transport.executeAuthenticatedAsync(authRequest(), body -> body).get());
		assertEquals(2, prompts.get());
	}

	@Test
	public void transientRefreshFailureDoesNotPrompt() throws Exception
	{
		AtomicInteger prompts = new AtomicInteger();
		transport.setOnAuthFailure(prompts::incrementAndGet);
		transport.setRefreshToken("rt");

		CompletableFuture<String> future =
			transport.executeAuthenticatedAsync(authRequest(), body -> body);

		// The refresh exchange gets a 5xx: transient, refresh token is retained, so the
		// next attempt can still recover on its own -> no re-login prompt.
		ArgumentCaptor<Callback> captor = ArgumentCaptor.forClass(Callback.class);
		verify(call).enqueue(captor.capture());
		captor.getValue().onResponse(call, response(500));

		assertNull(future.get());
		assertEquals(0, prompts.get());
	}
}

package com.flipsmart.api;

import com.flipsmart.FlipSmartConfig;
import com.flipsmart.api.dto.Dtos.EntitlementsResponse;
import com.google.gson.Gson;
import okhttp3.OkHttpClient;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.mock;

/**
 * Pins the entitlement-application contract (#1087): an entitlements snapshot
 * only updates RSN-blocked status. Premium is sourced exclusively from the
 * flip-finder payload; applying entitlements must never change the premium
 * flag, because the snapshot nests premium under {@code rsn_entitlement} and
 * re-sourcing it here previously downgraded premium players to the free tier.
 */
public class ApiHttpTransportEntitlementsTest
{
	private final Gson gson = new Gson();
	private ApiHttpTransport transport;

	@Before
	public void setUp()
	{
		transport = new ApiHttpTransport(
			mock(OkHttpClient.class), gson, mock(FlipSmartConfig.class));
	}

	private EntitlementsResponse parse(String json)
	{
		return EntitlementsResponse.fromJson(gson, json);
	}

	@Test
	public void applyingEntitlementsDoesNotDowngradePremium()
	{
		transport.setPremium(true);  // as set by the flip-finder payload / login token
		// Real snapshot shape: premium nested under rsn_entitlement, no top-level flag.
		transport.applyEntitlements(parse(
			"{\"has_any_premium\":true,\"rsn_entitlement\":{\"is_premium\":true,\"status\":\"active\"}}"));
		assertTrue("entitlements must not clobber premium", transport.isPremium());
	}

	@Test
	public void applyingEntitlementsDoesNotPromoteFreeToPremium()
	{
		transport.setPremium(false);
		transport.applyEntitlements(parse("{\"is_premium\":true}"));
		assertFalse("entitlements is not a premium source", transport.isPremium());
	}

	@Test
	public void applyingEntitlementsUpdatesRsnBlocked()
	{
		transport.applyEntitlements(parse("{\"rsn_entitlement\":{\"status\":\"blocked\"}}"));
		assertTrue(transport.isRsnBlocked());
	}

	@Test
	public void applyingNonBlockedEntitlementsClearsRsnBlocked()
	{
		transport.applyEntitlements(parse("{\"rsn_entitlement\":{\"status\":\"blocked\"}}"));
		transport.applyEntitlements(parse("{\"rsn_entitlement\":{\"status\":\"active\"}}"));
		assertFalse(transport.isRsnBlocked());
	}

	@Test
	public void v9GateDefaultsFalse()
	{
		assertFalse(transport.isV9Enabled());
	}

	@Test
	public void applyingEntitlementsEnablesV9WhenFlagTrue()
	{
		transport.applyEntitlements(parse("{\"v9_enabled\":true}"));
		assertTrue(transport.isV9Enabled());
	}

	@Test
	public void applyingEntitlementsWithoutFlagKeepsV9Disabled()
	{
		transport.applyEntitlements(parse("{\"is_premium\":true}"));
		assertFalse(transport.isV9Enabled());
	}

	@Test
	public void applyingEntitlementsWithoutFlagDisablesV9()
	{
		transport.applyEntitlements(parse("{\"v9_enabled\":true}"));
		transport.applyEntitlements(parse("{}"));
		assertFalse(transport.isV9Enabled());
	}

	@Test
	public void clearAuthDisablesV9()
	{
		transport.applyEntitlements(parse("{\"v9_enabled\":true}"));
		transport.clearAuth();
		assertFalse(transport.isV9Enabled());
	}
}

package com.flipsmart;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Every repaint of the recommendation list must pass the free-tier slot gate.
 *
 * <p>Prod (#1133 follow-up): a free user at their 2-item cap saw the upgrade message replaced
 * by a full list of recommendation cards, because Auto's queue-advance callback repainted via
 * {@code populateRecommendations} directly. This is the second time a repaint call site skipped
 * the gate — the cogwheel "Update" path had the same hole earlier — so the invariant is pinned
 * here rather than left to review.
 *
 * <p>The gate lives in {@code repopulateRecommendationsGated} and {@code reevaluateSlotLimitDisplay};
 * {@code handleRecommendationsResponse} applies it inline around the fetch. Any NEW call site is a
 * bypass until it routes through one of those. If you are here because this test failed, call
 * {@code repopulateRecommendationsGated()} instead of {@code populateRecommendations(...)}.</p>
 */
public class RecommendationRepaintGateTest
{
	private static final Path PANEL_SOURCE =
		Paths.get("src/main/java/com/flipsmart/FlipFinderPanel.java");

	/** Methods allowed to call populateRecommendations, because each applies the gate itself. */
	private static final List<String> GATED_CALLERS = Arrays.asList(
		"handleRecommendationsResponse",
		"repopulateRecommendationsGated",
		"reevaluateSlotLimitDisplay");

	// A method declaration at class-body indentation (exactly one tab), e.g. "\tprivate void foo(".
	// Anchored on an access modifier so control flow ("\t\telse if (") can't pose as a declaration.
	private static final Pattern METHOD_DECL = Pattern.compile(
		"^\\t(?:public|private|protected)\\s+(?:static\\s+|final\\s+|synchronized\\s+)*"
			+ "[\\w<>,\\[\\].?]+\\s+(\\w+)\\s*\\(");

	@Test
	public void everyRecommendationRepaintRoutesThroughTheSlotGate() throws IOException
	{
		assertTrue("FlipFinderPanel source not found — is the test running from the project root?",
			Files.exists(PANEL_SOURCE));

		List<String> lines = Files.readAllLines(PANEL_SOURCE, StandardCharsets.UTF_8);
		List<String> ungated = new ArrayList<>();

		for (int i = 0; i < lines.size(); i++)
		{
			String line = lines.get(i);
			if (!line.contains("populateRecommendations(") || line.contains("private void populateRecommendations("))
			{
				continue;
			}
			String enclosing = enclosingMethod(lines, i);
			if (!GATED_CALLERS.contains(enclosing))
			{
				ungated.add((i + 1) + ": in " + enclosing + " -> " + line.trim());
			}
		}

		assertEquals("ungated populateRecommendations call site(s) — route through "
			+ "repopulateRecommendationsGated() so a capped free user keeps the upgrade message: "
			+ ungated, 0, ungated.size());
	}

	/** Name of the method containing {@code lineIndex}, or "<unknown>" when none is found. */
	private static String enclosingMethod(List<String> lines, int lineIndex)
	{
		for (int i = lineIndex; i >= 0; i--)
		{
			Matcher m = METHOD_DECL.matcher(lines.get(i));
			if (m.find())
			{
				return m.group(1);
			}
		}
		return "<unknown>";
	}
}

package com.flipsmart;
import com.flipsmart.domain.flip.FlipRecommendation;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Issue #935 — Flip Assist must only surface items that Flip Finder would display.
 * Both features consume the same backend recommendation list; the plugin's
 * minimum-profit and minimum-volume config filters must therefore apply
 * identically to the Flip Finder display and to the Flip Assist queue. Prior to
 * this fix the min-volume filter was never applied to the queue (start() or
 * refresh) and the min-profit filter was missing from start(), so sub-threshold
 * items leaked into Flip Assist only.
 */
public class FlipAssistFlipFinderConsistencyTest
{
	private static final int OFFSET = 0;
	private static final int MIN_PROFIT = 500;
	private static final int MIN_VOLUME = 1000;
	private static final Set<Integer> NONE_ACTIVE = Collections.emptySet();

	private static FlipRecommendation rec(int itemId, int buy, int sell, int qty, int dailyVolume)
	{
		FlipRecommendation r = new FlipRecommendation();
		r.setItemId(itemId);
		r.setItemName("Item " + itemId);
		r.setRecommendedBuyPrice(buy);
		r.setRecommendedSellPrice(sell);
		r.setRecommendedQuantity(qty);
		r.setDailyVolume(dailyVolume);
		r.setVolumePerHour(dailyVolume / 24.0);
		return r;
	}

	private static List<Integer> ids(List<FlipRecommendation> recs)
	{
		return recs.stream().map(FlipRecommendation::getItemId).collect(Collectors.toList());
	}

	// The core #935 leak: a high-margin item that fails only the volume floor must
	// be filtered out of the Flip Assist queue, exactly as Flip Finder hides it.
	@Test
	public void excludesItemBelowMinimumVolume()
	{
		FlipRecommendation lowVolume = rec(1001, 100, 2000, 10, 100);
		FlipRecommendation ok = rec(2002, 100, 2000, 10, 5000);

		List<FlipRecommendation> filtered = AutoRecommendService.filterSurfaceable(
			Arrays.asList(lowVolume, ok), NONE_ACTIVE, OFFSET, MIN_PROFIT, MIN_VOLUME);

		assertFalse("below-min-volume item must not surface in Flip Assist", ids(filtered).contains(1001));
		assertTrue(ids(filtered).contains(2002));
	}

	// Below-min-profit items must be excluded on the start() path too — previously
	// only refreshQueue() applied the profit floor.
	@Test
	public void excludesItemBelowMinimumProfit()
	{
		FlipRecommendation lowProfit = rec(1001, 100, 101, 1, 5000);
		FlipRecommendation ok = rec(2002, 100, 2000, 10, 5000);

		List<FlipRecommendation> filtered = AutoRecommendService.filterSurfaceable(
			Arrays.asList(lowProfit, ok), NONE_ACTIVE, OFFSET, MIN_PROFIT, MIN_VOLUME);

		assertFalse("below-min-profit item must not surface", ids(filtered).contains(1001));
		assertTrue(ids(filtered).contains(2002));
	}

	// Items already active on the GE stay excluded from the queue (unchanged).
	@Test
	public void excludesActiveItems()
	{
		FlipRecommendation active = rec(1001, 100, 2000, 10, 5000);
		FlipRecommendation ok = rec(2002, 100, 2000, 10, 5000);

		List<FlipRecommendation> filtered = AutoRecommendService.filterSurfaceable(
			Arrays.asList(active, ok), Collections.singleton(1001), OFFSET, MIN_PROFIT, MIN_VOLUME);

		assertFalse(ids(filtered).contains(1001));
		assertTrue(ids(filtered).contains(2002));
	}

	// The shared predicate must match Flip Finder's shouldDisplay semantics exactly:
	// both the profit floor AND the volume floor are required.
	@Test
	public void sharedPredicateRequiresBothProfitAndVolume()
	{
		assertTrue(FocusedFlip.passesRecommendationFilters(
			rec(1, 100, 2000, 10, 5000), OFFSET, MIN_PROFIT, MIN_VOLUME));
		assertFalse("volume floor enforced", FocusedFlip.passesRecommendationFilters(
			rec(1, 100, 2000, 10, 100), OFFSET, MIN_PROFIT, MIN_VOLUME));
		assertFalse("profit floor enforced", FocusedFlip.passesRecommendationFilters(
			rec(1, 100, 101, 1, 5000), OFFSET, MIN_PROFIT, MIN_VOLUME));
	}
}

package com.flipsmart;
import com.flipsmart.domain.offer.OfferAction;
import com.flipsmart.domain.offer.OfferDisposition;

import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class OfferDispositionTest
{
	@Test
	public void priceActionsSurface()
	{
		assertEquals(OfferDisposition.SURFACE_PRICE, OfferDisposition.route(OfferAction.MOVE_PRICE_DOWN));
		assertEquals(OfferDisposition.SURFACE_PRICE, OfferDisposition.route(OfferAction.MOVE_PRICE_UP));
		assertEquals(OfferDisposition.SURFACE_PRICE, OfferDisposition.route(OfferAction.EXIT_AT_BREAKEVEN));
		assertEquals(OfferDisposition.SURFACE_PRICE, OfferDisposition.route(OfferAction.EXIT_AT_LOSS));
	}

	@Test
	public void moveUpParsesFromWire()
	{
		assertEquals(OfferAction.MOVE_PRICE_UP, OfferAction.fromWire("move_price_up"));
	}

	@Test
	public void cancelActionsHandOff()
	{
		assertEquals(OfferDisposition.HANDOFF, OfferDisposition.route(OfferAction.CANCEL_AND_RELIST_OTHER));
		assertEquals(OfferDisposition.HANDOFF, OfferDisposition.route(OfferAction.CANCEL_AND_SELL_PARTIAL));
	}

	@Test
	public void waitAndUnknownAreNone()
	{
		assertEquals(OfferDisposition.NONE, OfferDisposition.route(OfferAction.WAIT));
		assertEquals(OfferDisposition.NONE, OfferDisposition.route(null));
	}
}

package com.flipsmart.domain.offer;

import com.google.gson.Gson;
import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class OfferRecordStageTest
{
	@Test
	public void defaultsToInitial()
	{
		OfferRecord offer = OfferRecord.newOffer(1L, 0, 1, "Item", true, 10, 1000, 0L);
		assertEquals("initial", offer.getOfferStage());
	}

	@Test
	public void stageRoundTripsThroughGson()
	{
		OfferRecord offer = OfferRecord.newOffer(1L, 0, 1, "Item", false, 10, 1000, 0L)
			.withOfferStage("breakeven_relist");
		Gson gson = new Gson();
		OfferRecord restored = gson.fromJson(gson.toJson(offer), OfferRecord.class);
		assertEquals("breakeven_relist", restored.getOfferStage());
	}

	@Test
	public void nullOfferStageCoalescesToInitial()
	{
		Gson gson = new Gson();
		String json = "{\"offerId\":1,\"slot\":0,\"itemId\":1,\"itemName\":\"Item\",\"buy\":true,\"totalQuantity\":10,\"price\":1000}";
		OfferRecord restored = gson.fromJson(json, OfferRecord.class);
		assertEquals(OfferRecord.STAGE_INITIAL, restored.getOfferStage());
	}
}

package com.flipsmart.domain.flip;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Which items count as an in-flight flip.
 *
 * Prod (#1133 follow-up): the collected set is persisted per-RSN and restored at login, and its
 * don't-destroy-on-empty guard means an entry can never be cleared from disk once written. An
 * item sold in a later session therefore stayed in the restored collected set forever, kept
 * counting toward the free-tier cap, and pinned the user at "capReached=true" through refreshes
 * AND relogs — locking them out of recommendations entirely.
 *
 * Inventory is the proof a collected lot is still open. A collected item the player no longer
 * holds, with no live offer, is a finished flip.
 */
public class ActiveFlipItemIdsTest
{
	private static final int HELD = 11128;      // Berserker necklace, still in inventory
	private static final int SOLD = 6914;       // stale collected entry, already sold
	private static final int ON_OFFER = 31722;  // Rubium splinters, live GE sell

	private static Map<Integer, Integer> inventory(int... itemIds)
	{
		Map<Integer, Integer> counts = new HashMap<>();
		for (int id : itemIds)
		{
			counts.put(id, 1);
		}
		return counts;
	}

	private static Set<Integer> ids(Integer... itemIds)
	{
		return new HashSet<>(Arrays.asList(itemIds));
	}

	@Test
	public void dropsCollectedItemsThePlayerNoLongerHolds()
	{
		Set<Integer> active = ActiveFlipItemIds.derive(
			ids(ON_OFFER), ids(HELD, SOLD), inventory(HELD), true);

		assertEquals(ids(ON_OFFER, HELD), active);
	}

	@Test
	public void keepsCollectedItemsStillInInventory()
	{
		Set<Integer> active = ActiveFlipItemIds.derive(
			Collections.emptySet(), ids(HELD), inventory(HELD), true);

		assertTrue(active.contains(HELD));
	}

	@Test
	public void alwaysKeepsItemsWithALiveOfferEvenWhenNotInInventory()
	{
		// A listed sell is out of the inventory by definition — it must still count.
		Set<Integer> active = ActiveFlipItemIds.derive(
			ids(ON_OFFER), Collections.emptySet(), inventory(), true);

		assertEquals(ids(ON_OFFER), active);
	}

	@Test
	public void trustsTheCollectedSetWhenNoInventorySnapshotIsReadable()
	{
		// Logged out: the snapshot is empty because it is unknown, not because the player
		// holds nothing. Dropping the set here would release the cap while logged out.
		Set<Integer> active = ActiveFlipItemIds.derive(
			Collections.emptySet(), ids(HELD, SOLD), inventory(), false);

		assertEquals(ids(HELD, SOLD), active);
	}

	@Test
	public void theStuckCapScenarioReleasesOnceTheSoldItemIsGone()
	{
		// Exactly the reported state: one live sell, plus a sold item lingering in the
		// restored collected set. Only the live sell should count, so a 2-item cap frees up.
		Set<Integer> active = ActiveFlipItemIds.derive(
			ids(ON_OFFER), ids(HELD), inventory(), true);

		assertEquals(ids(ON_OFFER), active);
		assertEquals(1, active.size());
	}

	@Test
	public void toleratesNullInputs()
	{
		assertEquals(Collections.emptySet(), ActiveFlipItemIds.derive(null, null, null, true));
	}
}

