package com.flipsmart.session;

import static org.junit.Assert.assertEquals;

import com.flipsmart.domain.flip.ActiveFlip;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

public class OpenPositionsTest
{
	private static ActiveFlip projected(int itemId, Integer recSell, int avgBuy, int qty)
	{
		ActiveFlip a = new ActiveFlip();
		a.setItemId(itemId);
		a.setRecommendedSellPrice(recSell == null ? null : recSell.longValue());
		a.setAverageBuyPrice(avgBuy);
		a.setTotalQuantity(qty);
		return a;
	}

	@Test
	public void partiallyFilledSell_leavesOnlyTheUnsoldRemainder()
	{
		// The projection reports the sell offer's original quantity (1000). 400 have sold and
		// are already counted in realised profit, so only 600 may be valued as unrealised —
		// otherwise those 400 are counted twice in projected profit.
		List<OpenPosition> open = OpenPositions.derive(
			Collections.singletonList(projected(4151, 200, 100, 1000)), itemId -> 400);

		assertEquals(1, open.size());
		assertEquals(600, open.get(0).unsoldQuantity);
	}

	@Test
	public void awaitingSaleLot_withNoLiveSell_keepsItsFullQuantity()
	{
		List<OpenPosition> open = OpenPositions.derive(
			Collections.singletonList(projected(4151, 200, 100, 25)), itemId -> 0);

		assertEquals(25, open.get(0).unsoldQuantity);
	}

	@Test
	public void fullyFilledSell_leavesNothingUnsold()
	{
		List<OpenPosition> open = OpenPositions.derive(
			Collections.singletonList(projected(4151, 200, 100, 500)), itemId -> 500);

		assertEquals(0, open.get(0).unsoldQuantity);
	}

	@Test
	public void filledExceedingProjectedQuantity_clampsAtZero()
	{
		// Consolidation or a re-list can report more filled than the projection's snapshot
		// quantity; a negative remainder would credit phantom profit.
		List<OpenPosition> open = OpenPositions.derive(
			Collections.singletonList(projected(4151, 200, 100, 100)), itemId -> 250);

		assertEquals(0, open.get(0).unsoldQuantity);
	}

	@Test
	public void carriesPricingBasisThrough()
	{
		OpenPosition p = OpenPositions.derive(
			Collections.singletonList(projected(4151, 200, 100, 10)), itemId -> 0).get(0);

		assertEquals(4151, p.itemId);
		assertEquals(Long.valueOf(200), p.recommendedSellPrice);
		assertEquals(100, p.averageBuyPrice);
	}

	@Test
	public void filledQuantityIsLookedUpPerItem()
	{
		List<OpenPosition> open = OpenPositions.derive(
			Arrays.asList(projected(4151, 200, 100, 1000), projected(561, 200, 100, 1000)),
			itemId -> itemId == 4151 ? 900 : 0);

		assertEquals(100, open.get(0).unsoldQuantity);
		assertEquals(1000, open.get(1).unsoldQuantity);
	}

	@Test
	public void multipleLiveSellOffersOfTheSameItem_shareOneFilledPoolInsteadOfDoubleSubtracting()
	{
		// Two GE slots both selling item 4151: slot A sold 100/500, slot B sold 200/500 — the
		// item-level lookup reports the combined fill (300). Applying that whole total to each
		// flip independently would compute 500-300=200 twice (400 total) instead of the true
		// 700 remaining across both slots.
		List<OpenPosition> open = OpenPositions.derive(
			Arrays.asList(projected(4151, 200, 100, 500), projected(4151, 200, 100, 500)),
			itemId -> 300);

		int totalUnsold = open.get(0).unsoldQuantity + open.get(1).unsoldQuantity;
		assertEquals(700, totalUnsold);
	}

	@Test
	public void doesNotMutateTheProjectedFlips()
	{
		// The same ActiveFlip instances render the Active Flips cards and feed the backend
		// snapshot push — deriving positions must not rewrite their quantities.
		ActiveFlip flip = projected(4151, 200, 100, 1000);

		OpenPositions.derive(Collections.singletonList(flip), itemId -> 400);

		assertEquals(1000, flip.getTotalQuantity());
	}
}

package com.flipsmart.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.concurrent.atomic.AtomicReference;
import org.junit.Test;

public class SessionStatsViewTest
{
	@Test
	public void defaultsToExpanded()
	{
		SessionStatsView view = new SessionStatsView();
		assertFalse(view.isCollapsed());
		assertTrue(bodyPanel(view).isVisible());
	}

	@Test
	public void restoringCollapsedStateDoesNotNotifyListener()
	{
		SessionStatsView view = new SessionStatsView();
		AtomicReference<Boolean> notified = new AtomicReference<>(null);
		view.setToggleListener(notified::set);

		view.setCollapsed(true);

		assertTrue(view.isCollapsed());
		assertNull("programmatic restore must not fire the persist callback", notified.get());
	}

	@Test
	public void toggleFlipsStateAndReportsIt()
	{
		SessionStatsView view = new SessionStatsView();
		AtomicReference<Boolean> notified = new AtomicReference<>(null);
		view.setToggleListener(notified::set);

		clickHeader(view);
		assertTrue(view.isCollapsed());
		assertEquals(Boolean.TRUE, notified.get());

		clickHeader(view);
		assertFalse(view.isCollapsed());
		assertEquals(Boolean.FALSE, notified.get());
	}

	/** The body panel is the root container's second child, after the header. */
	private static java.awt.Component bodyPanel(SessionStatsView view)
	{
		java.awt.Container root = (java.awt.Container) view.getComponent();
		return root.getComponent(1);
	}

	/** Drive the header's mouse listener the way a user click would. */
	private static void clickHeader(SessionStatsView view)
	{
		java.awt.Container root = (java.awt.Container) view.getComponent();
		java.awt.Component header = root.getComponent(0);
		java.awt.event.MouseListener[] listeners =
			((javax.swing.JComponent) header).getMouseListeners();
		java.awt.event.MouseEvent press = new java.awt.event.MouseEvent(
			header, java.awt.event.MouseEvent.MOUSE_PRESSED, 0L, 0, 1, 1, 1, false);
		for (java.awt.event.MouseListener listener : listeners)
		{
			listener.mousePressed(press);
		}
	}
}

package com.flipsmart;

import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Pins the item-scoping contract of
 * {@link GeOfferDescriptionService#resolveOfferContext()} (issues #972, #992).
 *
 * <p>Sources are ranked by how authoritative each is about the item actually on
 * screen, not by how much context each carries:
 *
 * <ol>
 *   <li>Flip Assist focus tracks the plugin's <em>next recommended action</em>, which
 *       is routinely a different item than the panel the player has open. It may only
 *       drive the description when it agrees with the on-screen item (#972).</li>
 *   <li>The "Set up offer" window is pre-confirm and belongs to no committed slot.
 *       While it is open it outranks the active slot, which may hold an unrelated
 *       in-flight offer the player merely hovered or clicked earlier (#992).</li>
 *   <li>The committed offer on the active slot owns the in-flight status panel.</li>
 * </ol>
 */
public class GeOfferContextResolutionTest
{
	private static final int ELY_ITEM_ID = 12817;   // focused elsewhere, insta-buy ~515m
	private static final int KIT_ITEM_ID = 25454;   // item actually on the open offer panel

	private static final int SHARK = 385;           // item on the setup screen
	private static final int RAW_KARAMBWAN = 3142;  // unrelated in-flight offer on another slot

	private static final int GE_OFFERS_GROUP = 465;
	private static final int INDEX_0_CHILD = 7;
	private static final int NEWOFFER_PRICE_VARP = 5753;

	private static final String MSG_SETUP_ITEM = "item must be the one on the setup screen";
	private static final String MSG_SETUP_PRICE = "price must be the setup screen's";

	private final Client client = mock(Client.class);

	private GeOfferDescriptionService newService()
	{
		return newServiceWithFocus(null);
	}

	private GeOfferDescriptionService newServiceWithFocus(FocusedFlip focus)
	{
		FlipAssistOverlay overlay = mock(FlipAssistOverlay.class);
		when(overlay.getFocusedFlip()).thenReturn(focus);
		return new GeOfferDescriptionService(
			client,
			mock(ClientThread.class),
			mock(FlipSmartApiClient.class),
			mock(FlipSmartPlugin.class),
			mock(ItemManager.class),
			overlay,
			mock(ConfigManager.class),
			mock(FlipSmartConfig.class));
	}

	/** Puts an in-flight offer for {@code itemId} on {@code slot} and selects that slot. */
	private void openOfferPanel(int slot, int itemId, int price)
	{
		putOffer(slot, itemId, price, 1);
		when(client.getVarbitValue(VarbitID.GE_SELECTEDSLOT)).thenReturn(slot);
	}

	@SuppressWarnings("PMD.SingularField")
	private final GrandExchangeOffer[] offers = new GrandExchangeOffer[8];

	/** Puts an in-flight sell offer on {@code slot} without selecting it. */
	private void putOffer(int slot, int itemId, int price, int qty)
	{
		GrandExchangeOffer offer = mock(GrandExchangeOffer.class);
		when(offer.getState()).thenReturn(GrandExchangeOfferState.SELLING);
		when(offer.getItemId()).thenReturn(itemId);
		when(offer.getPrice()).thenAnswer(GpAnswer.gp(price));
		when(offer.getTotalQuantity()).thenReturn(qty);

		offers[slot] = offer;
		when(client.getGrandExchangeOffers()).thenReturn(offers);
	}

	/** Opens the "Set up offer" window showing {@code itemId} at price x qty. */
	private void openSetupWindow(int itemId, long price, int qty, boolean isSell)
	{
		Widget setupDesc = mock(Widget.class);
		when(setupDesc.isHidden()).thenReturn(false);
		when(client.getWidget(InterfaceID.GeOffers.SETUP_DESC)).thenReturn(setupDesc);

		when(client.getVarbitValue(VarbitID.GE_NEWOFFER_TYPE)).thenReturn(isSell ? 1 : 2);
		when(client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH)).thenReturn(itemId);
		when(client.getVarpLongValue(NEWOFFER_PRICE_VARP)).thenReturn(price);
		when(client.getVarbitValue(VarbitID.GE_NEWOFFER_QUANTITY)).thenReturn(qty);
	}

	/** Player clicks the slot tile for {@code slot} (group 465, child 7+N). */
	private void clickSlot(GeOfferDescriptionService service, int slot)
	{
		MenuOptionClicked event = mock(MenuOptionClicked.class);
		when(event.getParam1()).thenReturn((GE_OFFERS_GROUP << 16) | (INDEX_0_CHILD + slot));
		service.onMenuOptionClicked(event);
	}

	// -- #972: focus must not bleed onto an unrelated panel ---------------------

	@Test
	public void focusOnAnotherItemDoesNotBleedOntoOpenOfferPanel()
	{
		// Focus is on the Ely (next recommended action) ...
		GeOfferDescriptionService service =
			newServiceWithFocus(FocusedFlip.forSell(ELY_ITEM_ID, "Elysian spirit shield", 515_000_000, 1));
		// ... but the open GE panel is the Dragon Pickaxe Upgrade Kit.
		openOfferPanel(0, KIT_ITEM_ID, 650_000);

		long[] ctx = service.resolveOfferContext();

		assertNotNull("open offer panel must resolve a context", ctx);
		assertEquals("resolved item must be the on-screen offer item, not the focus",
			KIT_ITEM_ID, ctx[0]);
	}

	@Test
	public void focusIsUsedWhenItMatchesTheOpenOfferPanel()
	{
		// Focus and the open panel are the same item — focus is authoritative and
		// contributes its recommended price (distinct from the raw offer price).
		GeOfferDescriptionService service =
			newServiceWithFocus(FocusedFlip.forSell(KIT_ITEM_ID, "Dragon pickaxe upgrade kit", 700_000, 1));
		openOfferPanel(0, KIT_ITEM_ID, 650_000);

		long[] ctx = service.resolveOfferContext();

		assertNotNull(ctx);
		assertEquals(KIT_ITEM_ID, ctx[0]);
		assertEquals("focus price should drive when focus matches the panel", 700_000, ctx[2]);
	}

	@Test
	public void focusIsUsedWhenNoPanelItemCanBeDetermined()
	{
		// No offers loaded and no setup window open → nothing on screen to compare
		// against, so the focus remains the best available context.
		GeOfferDescriptionService service =
			newServiceWithFocus(FocusedFlip.forSell(ELY_ITEM_ID, "Elysian spirit shield", 515_000_000, 1));
		when(client.getGrandExchangeOffers()).thenReturn(null);
		when(client.getVarbitValue(VarbitID.GE_SELECTEDSLOT)).thenReturn(-1);

		long[] ctx = service.resolveOfferContext();

		assertNotNull(ctx);
		assertEquals(ELY_ITEM_ID, ctx[0]);
	}

	// -- #992: the open setup window outranks an unrelated active slot ----------

	/**
	 * Reported case: an in-flight Raw Karambwan sell sits on a slot the player
	 * clicked earlier; the player then sets up a Shark sell. The panel must show
	 * Shark's numbers, not the Karambwan offer's.
	 */
	@Test
	public void setupWindowOutranksStaleClickedSlot_withFocusOnTheStaleItem()
	{
		GeOfferDescriptionService service =
			newServiceWithFocus(FocusedFlip.forSell(RAW_KARAMBWAN, "Raw karambwan", 274, 4500));

		putOffer(0, RAW_KARAMBWAN, 274, 4500);
		clickSlot(service, 0);
		openSetupWindow(SHARK, 960, 10_000, true);

		long[] ctx = service.resolveOfferContext();

		assertNotNull(ctx);
		assertEquals(MSG_SETUP_ITEM, SHARK, ctx[0]);
		assertEquals(MSG_SETUP_PRICE, 960, ctx[2]);
		assertEquals("qty must be the setup screen's", 10_000, ctx[3]);
	}

	/** A typed price above the old int limit survives, read from the 64-bit varp. */
	@Test
	public void setupWindowPriceAboveIntMaxSurvives()
	{
		GeOfferDescriptionService service = newService();

		long bigPrice = 5_000_000_000L; // > Integer.MAX_VALUE (max-cash territory)
		openSetupWindow(SHARK, bigPrice, 1, true);

		long[] ctx = service.resolveOfferContext();

		assertNotNull(ctx);
		assertEquals(MSG_SETUP_PRICE, bigPrice, ctx[2]);
	}

	/** Same divergence with no focus at all — isolates the slot path. */
	@Test
	public void setupWindowOutranksStaleClickedSlot_withoutFocus()
	{
		GeOfferDescriptionService service = newService();

		putOffer(0, RAW_KARAMBWAN, 274, 4500);
		clickSlot(service, 0);
		openSetupWindow(SHARK, 960, 10_000, true);

		long[] ctx = service.resolveOfferContext();

		assertNotNull(ctx);
		assertEquals(MSG_SETUP_ITEM, SHARK, ctx[0]);
		assertEquals(MSG_SETUP_PRICE, 960, ctx[2]);
		assertEquals("qty must be the setup screen's", 10_000, ctx[3]);
	}

	/**
	 * Buy side: a stale <em>sell</em> slot must not capture a <em>buy</em> setup
	 * screen. Direction comes from GE_NEWOFFER_TYPE on the setup path but from the
	 * slot's own state on the slot path, so losing this sends the panel through the
	 * sell builder and prints a breakeven where the wiki insta-buy belongs.
	 */
	@Test
	public void setupWindowOwnsDirectionAndItemOnTheBuyScreen()
	{
		GeOfferDescriptionService service = newService();

		putOffer(0, RAW_KARAMBWAN, 274, 4500); // an in-flight SELL
		clickSlot(service, 0);
		openSetupWindow(SHARK, 960, 500, false); // ... while BUYING sharks

		long[] ctx = service.resolveOfferContext();

		assertNotNull(ctx);
		assertEquals(MSG_SETUP_ITEM, SHARK, ctx[0]);
		assertEquals("direction must be the setup screen's, not the stale slot's", 1, ctx[1]);
		assertEquals(MSG_SETUP_PRICE, 960, ctx[2]);
	}

	/**
	 * No click ever recorded, so resolveActiveSlot() falls back to GE_SELECTEDSLOT,
	 * which tracks the *hovered* slot. Hovering an unrelated in-flight offer must
	 * not poison the setup window either — this is why clearing the clicked-slot
	 * latch alone cannot fix the bug.
	 */
	@Test
	public void setupWindowOutranksMerelyHoveredSlot()
	{
		GeOfferDescriptionService service = newService();

		putOffer(0, RAW_KARAMBWAN, 274, 4500);
		when(client.getVarbitValue(VarbitID.GE_SELECTEDSLOT)).thenReturn(0);
		openSetupWindow(SHARK, 960, 10_000, true);

		long[] ctx = service.resolveOfferContext();

		assertNotNull(ctx);
		assertEquals(MSG_SETUP_ITEM, SHARK, ctx[0]);
	}

	/** With no setup window open, the clicked slot still owns the in-flight panel. */
	@Test
	public void clickedSlotStillOwnsInFlightPanelWhenNoSetupWindow()
	{
		GeOfferDescriptionService service = newService();

		putOffer(0, RAW_KARAMBWAN, 274, 4500);
		clickSlot(service, 0);
		when(client.getWidget(InterfaceID.GeOffers.SETUP_DESC)).thenReturn(null);

		long[] ctx = service.resolveOfferContext();

		assertNotNull(ctx);
		assertEquals(RAW_KARAMBWAN, ctx[0]);
	}

	/**
	 * The mirror of the bug: the in-flight status panel is owned by its committed
	 * slot, so a setup window left visible underneath it must not speak for it.
	 * onBeforeRender writes one resolved context to both panels, so without this
	 * the fix would trade one cross-item bleed for another.
	 */
	@Test
	public void inFlightDetailsPanelOutranksACoveredSetupWindow()
	{
		GeOfferDescriptionService service = newService();

		putOffer(0, RAW_KARAMBWAN, 274, 4500);
		clickSlot(service, 0);
		openSetupWindow(SHARK, 960, 10_000, true);

		Widget details = mock(Widget.class);
		when(details.isHidden()).thenReturn(false);
		when(client.getWidget(InterfaceID.GeOffers.DETAILS)).thenReturn(details);

		long[] ctx = service.resolveOfferContext();

		assertNotNull(ctx);
		assertEquals("the details panel's own slot must win", RAW_KARAMBWAN, ctx[0]);
	}

	/**
	 * The clicked-slot latch must not survive a GE visit: slots are reused between
	 * visits, so a carried-over index can name a different item. After a reopen the
	 * resolver falls back to the live selected slot until the player clicks again.
	 */
	@Test
	public void reopeningGeClearsTheClickedSlotLatch()
	{
		GeOfferDescriptionService service = newService();

		putOffer(0, RAW_KARAMBWAN, 274, 4500);
		putOffer(3, SHARK, 960, 10_000);
		when(client.getWidget(InterfaceID.GeOffers.SETUP_DESC)).thenReturn(null);

		clickSlot(service, 0);
		assertEquals("clicked slot owns the panel while the GE stays open",
			RAW_KARAMBWAN, service.resolveOfferContext()[0]);

		service.onGeOffersWidgetLoaded();
		when(client.getVarbitValue(VarbitID.GE_SELECTEDSLOT)).thenReturn(3);

		assertEquals("a reopened GE must not carry the previous visit's slot",
			SHARK, service.resolveOfferContext()[0]);
	}
}

package com.flipsmart;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Covers {@link FlipAssistOverlay#selectNoFocusMessage} — which hint/status box (if any)
 * the overlay draws when no flip is focused. Issue #726: the "Collect profit" prompt
 * (and friends) must NOT overlay the GE buy/sell offer-setup screen, but must re-surface
 * once setup closes, and the history-backfill prompt stays the one high-priority exception.
 */
public class FlipAssistNoFocusMessageTest
{
	private static final String HIST = "history";
	private static final String LOGIN = "login";
	private static final String HINT = "hint";
	private static final String MONITOR = "Monitoring your flips";
	private static final String COLLECT = "Collect profit from GE";

	private static String select(boolean showHistory, boolean offerInterfaceOpen,
		String autoStatus, String fallback, boolean authenticated)
	{
		return select(showHistory, offerInterfaceOpen, autoStatus, fallback, authenticated, false);
	}

	private static String select(boolean showHistory, boolean offerInterfaceOpen,
		String autoStatus, String fallback, boolean authenticated, boolean hasTradeActivity)
	{
		return FlipAssistOverlay.selectNoFocusMessage(
			showHistory, offerInterfaceOpen, autoStatus, fallback, authenticated, hasTradeActivity,
			HIST, LOGIN, MONITOR, HINT);
	}

	// Collect-profit (autoStatus) is suppressed while in any offer interface.
	@Test
	public void suppressesAutoStatusDuringOfferInterface()
	{
		assertNull(select(false, true, COLLECT, null, true));
	}

	// Suppression also hides the auto-recommend fallback message during an offer interface.
	@Test
	public void suppressesFallbackDuringOfferInterface()
	{
		assertNull(select(false, true, null, "Monitoring active offers", true));
	}

	// When NOT in an offer interface, the collect-profit prompt shows normally.
	@Test
	public void showsAutoStatusWhenNotInOfferInterface()
	{
		assertEquals(COLLECT, select(false, false, COLLECT, null, true));
	}

	// The offer interface now takes priority over EVERYTHING — even the one-shot
	// history-backfill prompt is suppressed while a buy/sell screen is up.
	@Test
	public void suppressesHistoryDuringOfferInterface()
	{
		assertNull(select(true, true, COLLECT, null, true));
	}

	// History takes precedence over auto-status when both are present.
	@Test
	public void historyTakesPrecedenceOverAutoStatus()
	{
		assertEquals(HIST, select(true, false, COLLECT, null, true));
	}

	// Falls back to the auto-recommend fallback message when no autoStatus.
	@Test
	public void usesFallbackWhenNoAutoStatus()
	{
		assertEquals("fallback msg", select(false, false, null, "fallback msg", true));
	}

	// Login prompt when unauthenticated and nothing else to show.
	@Test
	public void showsLoginWhenUnauthenticatedAndNoMessages()
	{
		assertEquals(LOGIN, select(false, false, null, null, false));
	}

	// Generic hint when authenticated and nothing else to show.
	@Test
	public void showsHintWhenAuthenticatedAndNothingElse()
	{
		assertEquals(HINT, select(false, false, null, null, true));
	}

	// AC11: with no GE activity, the default state is the generic hint, regardless of Auto.
	@Test
	public void defaultsToHintWhenNoTradeActivity()
	{
		assertEquals(HINT, select(false, false, null, null, true, false));
	}

	// AC12/AC13: GE activity opens the monitoring log even when Auto is off (no auto messages).
	@Test
	public void showsMonitoringOnTradeActivityWithoutAuto()
	{
		assertEquals(MONITOR, select(false, false, null, null, true, true));
	}

	// Auto-recommend messages still take precedence over the activity-driven monitoring message.
	@Test
	public void autoFallbackTakesPrecedenceOverMonitoring()
	{
		assertEquals("Monitoring active offers",
			select(false, false, null, "Monitoring active offers", true, true));
	}

	// Trade activity must not surface the monitoring log while unauthenticated.
	@Test
	public void unauthenticatedTradeActivityStillShowsLogin()
	{
		assertEquals(LOGIN, select(false, false, null, null, false, true));
	}

	// --- iconForNoFocusMessage: the icon must track the DISPLAYED message ---

	private static final String COLLECT_ITEM = "Collect Obsidian platebody";
	private static final int OBSIDIAN_ID = 21301;

	// The item-carrying auto-status prompt shows its icon.
	@Test
	public void iconShownForAutoStatusItemPrompt()
	{
		assertEquals(OBSIDIAN_ID,
			FlipAssistOverlay.iconForNoFocusMessage(COLLECT_ITEM, COLLECT_ITEM, OBSIDIAN_ID));
	}

	// Bug: a higher-priority text-only prompt (e.g. "Open GE History") must NOT
	// inherit the leftover item icon from a prior "Collect X" auto-status message.
	@Test
	public void noIconWhenHistoryPromptOutranksAutoStatus()
	{
		assertEquals(0,
			FlipAssistOverlay.iconForNoFocusMessage(HIST, COLLECT_ITEM, OBSIDIAN_ID));
	}

	// A text-only auto-status message (itemId 0, e.g. "Waiting for flips") shows no icon.
	@Test
	public void noIconForTextOnlyAutoStatus()
	{
		assertEquals(0,
			FlipAssistOverlay.iconForNoFocusMessage(HINT, HINT, 0));
	}

	// Null displayed message → no icon.
	@Test
	public void noIconForNullMessage()
	{
		assertEquals(0,
			FlipAssistOverlay.iconForNoFocusMessage(null, COLLECT_ITEM, OBSIDIAN_ID));
	}

	// No auto-status message at all → no icon regardless of leftover id.
	@Test
	public void noIconWhenNoAutoStatusMessage()
	{
		assertEquals(0,
			FlipAssistOverlay.iconForNoFocusMessage(MONITOR, null, OBSIDIAN_ID));
	}
}

