package com.flipsmart;

import com.google.inject.Inject;
import com.google.inject.Singleton;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;

/**
 * Pushes the player's current open Grand Exchange slot item IDs to the
 * FlipSmart backend so the "Import from RuneLite" button on the web Trade
 * Station page (issue #683 AC7) can read them back.
 *
 * Triggered every time the plugin observes a {@code GrandExchangeOfferChanged}
 * event. Debounced because individual slot fills produce a burst of events
 * (one per state transition) — we only need to push the final state of the
 * snapshot, not every intermediate one. Failed pushes are dropped silently;
 * this is best-effort cache warmth, not a critical signal.
 *
 * <p>Runs unconditionally — does not consult the {@code ff_trade_station}
 * feature flag that gates the web page. The plugin has no user-visible
 * Trade Station UI, so players see nothing whether the flag is on or off,
 * and pre-warming the cache means the web Import button works immediately
 * the moment the flag flips on for them (no "open RuneLite and wait for a
 * trade to register" experience on first use).
 */
@Slf4j
@Singleton
public class TradeStationSlotPushService
{
	private static final long DEBOUNCE_MS = 1_500L;

	private final Client client;
	private final FlipSmartApiClient apiClient;
	private final PlayerSession session;
	/**
	 * Rebuilt on demand rather than created once. The service is a singleton and RuneLite reuses
	 * the plugin instance across disable/enable, so a scheduler terminated by {@link #shutdown()}
	 * would otherwise stay terminated for the life of the client and every later GE event would
	 * throw RejectedExecutionException.
	 */
	private ScheduledExecutorService scheduler; // NOPMD DoNotUseThreads - desktop plugin, not J2EE

	private final AtomicReference<ScheduledFuture<?>> pending = new AtomicReference<>();
	private final AtomicReference<List<Integer>> lastPushed = new AtomicReference<>();

	@Inject
	public TradeStationSlotPushService(
		Client client,
		FlipSmartApiClient apiClient,
		PlayerSession session)
	{
		this.client = client;
		this.apiClient = apiClient;
		this.session = session;
	}

	/**
	 * Schedule a debounced push. Safe to call from any thread, including the
	 * client thread, because the actual GE-slot read is re-scheduled onto its
	 * own executor and we don't touch the client API there — only the slot
	 * snapshot the event handler captured.
	 *
	 * @param itemIds the snapshot of currently open slot item IDs at the time
	 *                of the event; pass {@code null} to read from the client
	 *                on the executor thread (only safe if called from the
	 *                client thread originally).
	 */
	public void scheduleSnapshotPush(List<Integer> itemIds)
	{
		List<Integer> snapshot = itemIds != null ? itemIds : readCurrentSlotIds();
		ScheduledFuture<?> existing = pending.get();
		if (existing != null)
		{
			existing.cancel(false);
		}
		ScheduledFuture<?> next = scheduler().schedule(
			() -> doPush(snapshot),
			DEBOUNCE_MS,
			TimeUnit.MILLISECONDS);
		pending.set(next);
	}

	/**
	 * Force an immediate push (no debounce). Intended for plugin shutdown so
	 * the cache reflects the last-known state.
	 */
	public void pushNow(List<Integer> itemIds)
	{
		List<Integer> snapshot = itemIds != null ? itemIds : readCurrentSlotIds();
		ScheduledFuture<?> existing = pending.getAndSet(null);
		if (existing != null)
		{
			existing.cancel(false);
		}
		scheduler().execute(() -> doPush(snapshot)); // NOPMD DoNotUseThreads
	}

	/** The live scheduler, created on first use and replaced if a shutdown terminated it. */
	private ScheduledExecutorService scheduler() // NOPMD DoNotUseThreads
	{
		synchronized (this)
		{
			if (scheduler == null || scheduler.isShutdown())
			{
				scheduler = Executors.newSingleThreadScheduledExecutor(r -> // NOPMD DoNotUseThreads
				{
					Thread t = new Thread(r, "flipsmart-trade-station-push"); // NOPMD DoNotUseThreads
					t.setDaemon(true);
					return t;
				});
			}
			return scheduler;
		}
	}

	public void shutdown()
	{
		ScheduledFuture<?> existing = pending.getAndSet(null);
		if (existing != null)
		{
			existing.cancel(false);
		}
		synchronized (this)
		{
			if (scheduler != null)
			{
				scheduler.shutdownNow(); // NOPMD DoNotUseThreads
			}
		}
	}

	/**
	 * Read the current GE slot item IDs. MUST be called from the client thread.
	 * Returns a deduped list preserving the slot order the player sees.
	 */
	public List<Integer> readCurrentSlotIds()
	{
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers == null)
		{
			return new ArrayList<>();
		}
		Set<Integer> seen = new LinkedHashSet<>();
		for (GrandExchangeOffer offer : offers)
		{
			if (offer == null || offer.getState() == GrandExchangeOfferState.EMPTY)
			{
				continue;
			}
			int id = offer.getItemId();
			if (id > 0)
			{
				seen.add(id);
			}
		}
		return new ArrayList<>(seen);
	}

	private void doPush(List<Integer> itemIds)
	{
		String rsn = session.getRsnSafe().orElse(null);
		if (rsn == null)
		{
			log.debug("Skipping trade-station slot push: no RSN");
			return;
		}
		List<Integer> previous = lastPushed.get();
		if (previous != null && previous.equals(itemIds))
		{
			if (log.isDebugEnabled())
			{
				log.debug("Skipping trade-station slot push: snapshot unchanged ({} items)",
					itemIds.size());
			}
			return;
		}
		try
		{
			apiClient.pushTradeStationSlotsAsync(rsn, itemIds)
				.exceptionally(e ->
				{
					if (log.isDebugEnabled())
					{
						log.debug("Trade-station slot push failed: {}", e.getMessage());
					}
					return false;
				});
			lastPushed.set(itemIds);
		}
		catch (RuntimeException e)
		{
			if (log.isDebugEnabled())
			{
				log.debug("Trade-station slot push threw: {}", e.getMessage());
			}
		}
	}
}

package com.flipsmart;

import com.google.gson.JsonObject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.Objects;

/**
 * Service for syncing webhook configuration between plugin and backend.
 * When webhook URL or preferences change in the plugin config, they are
 * synced to the backend. On login, backend config is pulled to the plugin.
 * All API calls are skipped when there is no authenticated session.
 */
@Slf4j
@Singleton
public class WebhookSyncService
{
	private static final String CONFIG_GROUP = "flipsmart";
	private static final String JSON_WEBHOOK_URL = "webhook_url";
	private static final String JSON_NOTIFY_SALE = "notify_sale_completed";
	private static final String JSON_NOTIFY_SUGGESTION = "notify_flip_suggestion";

	private final FlipSmartConfig config;
	private final FlipSmartApiClient apiClient;
	private final ConfigManager configManager;

	private String lastSyncedWebhookUrl = null;
	private boolean lastSyncedNotifySale = false;
	private boolean lastSyncedNotifySuggestion = false;
	private String lastPulledBackendUrl = null;
	private boolean pulledThisSession;

	@Inject
	public WebhookSyncService(
		FlipSmartConfig config,
		FlipSmartApiClient apiClient,
		ConfigManager configManager
	)
	{
		this.config = config;
		this.apiClient = apiClient;
		this.configManager = configManager;
	}

	private static String extractUrl(JsonObject webhookConfig)
	{
		return webhookConfig.has(JSON_WEBHOOK_URL)
			? webhookConfig.get(JSON_WEBHOOK_URL).getAsString() : "";
	}

	private static boolean extractNotifySale(JsonObject webhookConfig)
	{
		return webhookConfig.has(JSON_NOTIFY_SALE)
			&& webhookConfig.get(JSON_NOTIFY_SALE).getAsBoolean();
	}

	private static boolean extractNotifySuggestion(JsonObject webhookConfig)
	{
		return webhookConfig.has(JSON_NOTIFY_SUGGESTION)
			&& webhookConfig.get(JSON_NOTIFY_SUGGESTION).getAsBoolean();
	}

	/**
	 * Apply backend webhook config to the plugin's local config and update cached state.
	 */
	private void applyBackendConfig(String backendUrl, boolean notifySale, boolean notifySuggestion)
	{
		// Sync notification preferences to plugin config (not the URL -- always fetch from API)
		configManager.setConfiguration(CONFIG_GROUP, "notifySaleCompleted", String.valueOf(notifySale));
		configManager.setConfiguration(CONFIG_GROUP, "notifyFlipSuggestion", String.valueOf(notifySuggestion));

		lastPulledBackendUrl = backendUrl;
		lastSyncedWebhookUrl = backendUrl;
		lastSyncedNotifySale = notifySale;
		lastSyncedNotifySuggestion = notifySuggestion;
	}

	/**
	 * Pull webhook config from backend and update plugin config if needed, to keep the web
	 * dashboard and the plugin in parity. Fires on every LOGGED_IN transition, so a world hop
	 * or reconnect re-runs it — not once per session.
	 */
	public void pullFromBackend()
	{
		if (!apiClient.isAuthenticated())
		{
			log.debug("Skipping webhook pull: no authenticated session");
			return;
		}

		// The answer cannot change without the player leaving the world, and most accounts have
		// no webhook at all, so re-asking on every hop was the bulk of this endpoint's traffic.
		if (pulledThisSession)
		{
			return;
		}
		pulledThisSession = true;

		apiClient.fetchWebhookConfigAsync(
			webhookConfig -> applyBackendConfig(
				extractUrl(webhookConfig),
				extractNotifySale(webhookConfig),
				extractNotifySuggestion(webhookConfig)
			),
			() -> log.debug("No webhook configured on backend"),
			error -> {
				pulledThisSession = false;
				log.warn("Failed to pull webhook config from backend: {}", error);
			}
		);
	}

	/**
	 * Allow the next login to pull again. Called from the logout transition only, which a world
	 * hop does not pass through, so a hop reuses the pulled answer and a genuine relog refreshes it.
	 */
	public void onLogout()
	{
		pulledThisSession = false;
	}

	/**
	 * Check if webhook config has changed and sync if needed.
	 */
	public void syncIfChanged()
	{
		if (!apiClient.isAuthenticated())
		{
			log.debug("Skipping webhook sync: no authenticated session");
			return;
		}

		String webhookUrl = config.discordWebhookUrl();
		boolean notifySale = config.notifySaleCompleted();
		boolean notifySuggestion = config.notifyFlipSuggestion();

		boolean hasChanged = !Objects.equals(webhookUrl, lastSyncedWebhookUrl)
			|| notifySale != lastSyncedNotifySale
			|| notifySuggestion != lastSyncedNotifySuggestion;

		// Skip if the URL matches what we just pulled from backend (no real change)
		if (hasChanged && Objects.equals(webhookUrl, lastPulledBackendUrl)
			&& notifySale == lastSyncedNotifySale
			&& notifySuggestion == lastSyncedNotifySuggestion)
		{
			lastSyncedWebhookUrl = webhookUrl;
			return;
		}

		if (!hasChanged)
		{
			return;
		}

		// If webhook URL is empty, delete webhook from backend
		if (webhookUrl == null || webhookUrl.trim().isEmpty())
		{
			log.debug("Webhook URL cleared in plugin config (lastSynced={})", lastSyncedWebhookUrl);
			if (lastSyncedWebhookUrl != null && !lastSyncedWebhookUrl.trim().isEmpty())
			{
				deleteWebhook();
			}
			return;
		}

		syncToBackend(webhookUrl, notifySale, notifySuggestion);
	}

	private void syncToBackend(String webhookUrl, boolean notifySale, boolean notifySuggestion)
	{
		log.debug("Syncing webhook config to backend");

		apiClient.updateWebhookAsync(
			webhookUrl,
			notifySale,
			notifySuggestion,
			() -> {
				log.debug("Webhook config synced to backend successfully");
				lastSyncedWebhookUrl = webhookUrl;
				lastSyncedNotifySale = notifySale;
				lastSyncedNotifySuggestion = notifySuggestion;
			},
			error -> log.warn("Failed to sync webhook config to backend: {}", error)
		);
	}

	private void deleteWebhook()
	{
		log.debug("Deleting webhook from backend");

		apiClient.deleteWebhookAsync(
			() -> {
				log.debug("Webhook deleted from backend successfully");
				lastSyncedWebhookUrl = null;
				lastSyncedNotifySale = false;
				lastSyncedNotifySuggestion = false;
			},
			error -> log.warn("Failed to delete webhook from backend: {}", error)
		);
	}
}

