/**
 * Flip Assist overlay - a unique step-by-step workflow guide.
 * 
 * Unlike other flipping tools that use widget highlights, this shows a
 * floating panel with:
 * - Horizontal progress indicator showing the complete flip journey
 * - Current step prominently displayed with animated effects
 * - All relevant info (item, price, qty, profit) in one place
 * - Clear hotkey prompts at each step
 * 
 * Design philosophy: Guide the player through the ENTIRE flip journey
 * from initial purchase to final sale, not just one transaction.
 */
@Slf4j
public class FlipAssistOverlay extends Overlay
{
	private static final ThreadLocal<DecimalFormat> PRICE_FORMAT =
		ThreadLocal.withInitial(() -> new DecimalFormat("#,###"));

	// Color theme
	private static final Color COLOR_BG_DARK = new Color(25, 22, 18, 200);
	private static final Color COLOR_BORDER = new Color(10, 10, 10);
	private static final Color COLOR_ACCENT = new Color(255, 185, 50);
	private static final Color COLOR_ACCENT_GLOW = new Color(255, 185, 50, 60);
	private static final Color COLOR_TEXT = new Color(245, 240, 230);
	private static final Color COLOR_TEXT_DIM = new Color(160, 150, 140);
	private static final Color COLOR_GREEN_HINT = new Color(100, 220, 130);
	// Buy/sell trade convention — light blue / light orange, matching the website Item Graph (lightened for the dark overlay)
	private static final Color COLOR_TRADE_BUY = new Color(0x60, 0xA5, 0xFA);
	private static final Color COLOR_TRADE_SELL = new Color(0xFF, 0xA6, 0x57);
	private static final Color COLOR_PROFIT = new Color(80, 255, 120);
	private static final Color COLOR_LOSS = new Color(255, 100, 100);
	private static final Color COLOR_STEP_COMPLETE = new Color(80, 200, 100);
	private static final Color COLOR_STEP_CURRENT = COLOR_ACCENT;
	private static final Color COLOR_STEP_PENDING = new Color(80, 75, 70);
	private static final Color COLOR_ACTION_BOX = new Color(45, 42, 38);

	// Layout constants
	private static final int PANEL_WIDTH = 220;
	private static final int PANEL_HEIGHT = 170;
	private static final int HINT_PANEL_WIDTH = 200;
	private static final int HINT_PANEL_HEIGHT = 50;
	private static final int PADDING = 6;
	private static final int SECTION_PADDING = 10;
	private static final int ICON_SIZE = 28;
	private static final int STEP_INDICATOR_SIZE = 10;

	// Hint message
	private static final String HINT_TITLE = "FlipSmart";
	private static final String HINT_MESSAGE = "Click on a flip suggestion to start";
	private static final String LOGIN_MESSAGE = "Log in to use FlipSmart";
	private static final String HISTORY_PROMPT_MESSAGE = "Open GE History tab to backfill recent trades";
	private static final String MONITORING_MESSAGE = "Monitoring your flips";

	// GE Interface IDs
	private static final int GE_INTERFACE_GROUP = 465;
	private static final int GE_OFFER_PANEL_CHILD = 26;
	private static final int GE_QTY_CHILD_START = 31;
	private static final int GE_QTY_CHILD_END = 36;
	private static final int GE_PRICE_CHILD_START = 38;
	private static final int GE_PRICE_CHILD_END = 44;
	// VarClientInt.INPUT_TYPE value (raw ID to avoid deprecated API)
	private static final int VARCLIENT_INPUT_TYPE = 5;
	private static final int INPUT_TYPE_NUMERIC = 7;
	private static final int INPUT_TYPE_NUMERIC_LONG = 30;
	private static final int INPUT_TYPE_GE_SEARCH = 14;
	private static final String COINS_TEXT = "coins";
	private static final int[] CHATBOX_WIDGET_GROUPS = {162, 163, 164, 217, 219, 229, 548, 161};

	private final FlipSmartPlugin flipSmartPlugin;
	private final Client client;
	private final ClientThread clientThread;
	private final FlipSmartConfig config;
	private final ItemManager itemManager;
	private final TradeActivityLog tradeActivityLog;
	private final GEHistoryService geHistoryService;

	@Getter
	private FocusedFlip focusedFlip;

	// Auto-recommend overlay message (shown in hint box when no flip is focused)
	private volatile String autoStatusMessage;
	private volatile int autoStatusItemId;

	// Animation state
	private long animationStartTime = System.currentTimeMillis();
	private static final long PULSE_DURATION = 1500; // ms for one pulse cycle

	/**
	 * The current step in the flip assist workflow
	 */
	public enum FlipAssistStep
	{
		SELECT_ITEM("Select Item", "Click BUY on an empty slot"),
		SEARCH_ITEM("Search Item", "Press Enter or click the item"),
		SET_QUANTITY("Set Quantity", "Press [%s] to set qty: %s"),
		SET_PRICE("Set Price", "Press [%s] to set price: %s"),
		CONFIRM_OFFER("Confirm", "Click the confirm button"),
		WAITING_BUY("Buying...", "Offer placed, waiting to fill"),
		COLLECT_ITEMS("Collect", "Items bought! Collect from slot"),
		SELL_ITEMS("Sell Items", "Click SELL on collected items"),
		SET_SELL_PRICE("Set Sell Price", "Press [%s] to set: %s"),
		CONFIRM_SELL("Confirm Sale", "Click confirm to list"),
		WAITING_SELL("Selling...", "Listed! Waiting to sell"),
		COMPLETE("Complete!", "Flip finished - collect GP");

		private final String title;
		private final String description;

		FlipAssistStep(String title, String description)
		{
			this.title = title;
			this.description = description;
		}

		public String getTitle()
		{
			return title;
		}

		public String getDescription()
		{
			return description;
		}
	}

	@Getter
	private FlipAssistStep currentStep = FlipAssistStep.SELECT_ITEM;
	private FlipAssistStep previousStep = FlipAssistStep.SELECT_ITEM;
	@Setter
	private Consumer<FlipAssistStep> onStepChanged;

	@Inject
	private FlipAssistOverlay(FlipSmartPlugin flipSmartPlugin, Client client, ClientThread clientThread, FlipSmartConfig config, ItemManager itemManager, TradeActivityLog tradeActivityLog, GEHistoryService geHistoryService)
	{
		this.flipSmartPlugin = flipSmartPlugin;
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.itemManager = itemManager;
		this.tradeActivityLog = tradeActivityLog;
		this.geHistoryService = geHistoryService;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGH);
		setMovable(true);
	}

	public void updateStep()
	{
		FlipAssistStep newStep;
		final FocusedFlip flip = focusedFlip;
		if (flip == null)
		{
			newStep = FlipAssistStep.SELECT_ITEM;
		}
		else if (!isGrandExchangeOpen())
		{
			newStep = flip.isBuying() ? FlipAssistStep.WAITING_BUY : FlipAssistStep.WAITING_SELL;
		}
		else
		{
			newStep = determineGEOpenStep();
		}

		currentStep = newStep;
		if (currentStep != previousStep)
		{
			previousStep = currentStep;
			if (onStepChanged != null)
			{
				onStepChanged.accept(currentStep);
			}
		}
	}

	private FlipAssistStep determineNumericInputStep()
	{
		final FocusedFlip flip = focusedFlip;
		if (flip != null && isLikelyPriceInput())
		{
			return flip.isBuying() ? FlipAssistStep.SET_PRICE : FlipAssistStep.SET_SELL_PRICE;
		}
		return FlipAssistStep.SET_QUANTITY;
	}

	private FlipAssistStep determineGEOpenStep()
	{
		int inputType = getInputType();
		if (inputType == INPUT_TYPE_GE_SEARCH)
		{
			return FlipAssistStep.SEARCH_ITEM;
		}
		if (isNumericInput(inputType))
		{
			return determineNumericInputStep();
		}
		if (isOfferSetupOpen())
		{
			return determineOfferSetupStep();
		}
		final FocusedFlip flip = focusedFlip;
		if (flip == null)
		{
			return FlipAssistStep.SELECT_ITEM;
		}
		return flip.isBuying() ? FlipAssistStep.SELECT_ITEM : FlipAssistStep.SELL_ITEMS;
	}

	private FlipAssistStep determineOfferSetupStep()
	{
		final FocusedFlip flip = focusedFlip;
		if (flip == null)
		{
			return FlipAssistStep.SELECT_ITEM;
		}
		return offerSetupStep(getCurrentQuantityFromGE(), flip.getCurrentStepQuantity(),
			getCurrentPriceFromGE(), flip.getCurrentStepPrice(), flip.isBuying());
	}

	/**
	 * Pure step decision for the offer-setup screen. Quantity must match EXACTLY — it is an
	 * integer count with no rounding, so the ±1 price tolerance would wrongly accept the
	 * default qty 1 when the target is 2. Price keeps the ±1 tolerance. Package-private for tests.
	 */
	static FlipAssistStep offerSetupStep(long currentQty, int targetQty, long currentPrice, long targetPrice,
		boolean buying)
	{
		boolean qtyCorrect = targetQty > 0 && currentQty == targetQty;
		boolean priceCorrect = isValueWithinTolerance(currentPrice, targetPrice);

		if (qtyCorrect && priceCorrect)
		{
			return buying ? FlipAssistStep.CONFIRM_OFFER : FlipAssistStep.CONFIRM_SELL;
		}
		if (!qtyCorrect)
		{
			return FlipAssistStep.SET_QUANTITY;
		}
		return buying ? FlipAssistStep.SET_PRICE : FlipAssistStep.SET_SELL_PRICE;
	}

	/**
	 * Check if a GE value matches the target within ±1 tolerance.
	 * Tolerance is needed because GE can have slight rounding differences
	 * when displaying prices/quantities (e.g., 1gp variance in price).
	 */
	private static boolean isValueWithinTolerance(long current, long target)
	{
		return current > 0 && target > 0 && Math.abs(current - target) <= 1;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.enableFlipAssistant())
		{
			return null;
		}

		// If no flip is focused, show hint box only when GE is open (or showAssistantAlways)
		if (focusedFlip == null)
		{
			if (!isGrandExchangeOpen() && !config.showAssistantAlways())
			{
				return null;
			}
			// While the player is in any buy/sell offer interface (item search,
			// numeric qty/price input, or the offer-setup screen) the offer takes
			// priority — every status/hint prompt, including the History-backfill
			// prompt, is suppressed so nothing overlays the buy/sell screens. The
			// prompts re-surface at the main GE view. Off the offer interface, the
			// History prompt still takes priority over the auto-recommend status.
			String fallbackMessage = flipSmartPlugin.isAutoRecommendActive()
				? flipSmartPlugin.getAutoRecommendOverlayMessage()
				: null;
			String message = selectNoFocusMessage(
				isGrandExchangeOpen() && geHistoryService.hasUnverifiedOfflineFills(),
				isInOfferInterface(),
				autoStatusMessage,
				fallbackMessage,
				flipSmartPlugin.getApiClient().isAuthenticated(),
				!tradeActivityLog.isEmpty(),
				HISTORY_PROMPT_MESSAGE,
				LOGIN_MESSAGE,
				MONITORING_MESSAGE,
				HINT_MESSAGE);
			if (message == null)
			{
				return null;
			}
			// The icon must track the message actually shown: only the item-carrying
			// auto-status prompt ("Collect X") gets an icon. History/monitoring/login/
			// hint prompts outrank it in selectNoFocusMessage but carry no item, so a
			// leftover autoStatusItemId must not paint an icon onto them.
			int hintIconItemId = iconForNoFocusMessage(message, autoStatusMessage, autoStatusItemId);
			return renderHintBox(graphics, message, hintIconItemId);
		}

		// Only show when GE is open or when we have an active flip
		if (!isGrandExchangeOpen() && !config.showAssistantAlways())
		{
			return null;
		}

		// Update step based on current game state
		updateStep();

		// Enable anti-aliasing
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

		// Calculate animation phase for pulse effect
		long elapsed = System.currentTimeMillis() - animationStartTime;
		double pulsePhase = (elapsed % PULSE_DURATION) / (double) PULSE_DURATION;
		float pulseAlpha = (float) (0.5 + 0.5 * Math.sin(pulsePhase * 2 * Math.PI));

		int panelHeight = PANEL_HEIGHT;

		// Draw outer glow (animated)
		Color glowColor = new Color(
			COLOR_ACCENT_GLOW.getRed(),
			COLOR_ACCENT_GLOW.getGreen(),
			COLOR_ACCENT_GLOW.getBlue(),
			(int)(COLOR_ACCENT_GLOW.getAlpha() * pulseAlpha)
		);
		graphics.setColor(glowColor);
		graphics.fillRoundRect(-4, -4, PANEL_WIDTH + 8, panelHeight + 8, 16, 16);

		// Draw background
		graphics.setColor(COLOR_BG_DARK);
		graphics.fillRoundRect(0, 0, PANEL_WIDTH, panelHeight, 12, 12);

		// Draw thin black border
		graphics.setColor(COLOR_BORDER);
		graphics.setStroke(new BasicStroke(1));
		graphics.drawRoundRect(0, 0, PANEL_WIDTH, panelHeight, 12, 12);

		int y = PADDING;

		// Draw header section
		y = renderHeader(graphics, y);

		// Draw step progress indicator
		y = renderStepProgress(graphics, y, pulseAlpha);

		// Draw current action panel
		y = renderCurrentAction(graphics, y, pulseAlpha);

		// Draw flip summary
		renderFlipSummary(graphics, y);

		return new Dimension(PANEL_WIDTH, panelHeight);
	}

	/**
	 * Render a small hint box with a title and message.
	 * When an item icon is present, shows a two-line layout:
	 *   "FlipSmart" title
	 *   "Collect items from GE" subtitle
	 *   [icon] item name
	 */
	private Dimension renderHintBox(Graphics2D graphics, String message, int itemId)
	{
		boolean hasIcon = itemId > 0;
		int hintIconSize = 20;

		// Enable anti-aliasing
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

		// Pre-compute wrapped lines for text-only messages to determine panel height
		graphics.setFont(FontManager.getRunescapeSmallFont());
		FontMetrics smallMetrics = graphics.getFontMetrics();
		int textPadding = 10;
		int maxTextWidth = HINT_PANEL_WIDTH - textPadding * 2;
		List<String> wrappedLines = null;

		// Activity log: shown in idle assist states (waiting/monitoring) (AC4)
		List<TradeActivityLog.Entry> activityEntries =
			isIdleAssistMessage(message) ? tradeActivityLog.snapshot() : java.util.Collections.emptyList();
		int activityLogHeight = computeActivityLogHeight(activityEntries, smallMetrics);

		int panelHeight;
		if (hasIcon)
		{
			int iconSpace = 20 + 6; // hintIconSize + gap
			List<String> iconLines = wrapText(message, smallMetrics, maxTextWidth - iconSpace);
			int lineHeight = smallMetrics.getHeight();
			int textHeight = lineHeight * iconLines.size();
			// Title (20px) + gap (12px) + max(icon height, text height) + bottom padding (8px)
			panelHeight = 20 + 12 + Math.max(20, textHeight) + 8;
			panelHeight = Math.max(panelHeight, HINT_PANEL_HEIGHT);
		}
		else
		{
			wrappedLines = wrapText(message, smallMetrics, maxTextWidth);
			int lineHeight = smallMetrics.getHeight();
			// Title (20px) + gap (8px) + wrapped lines + bottom padding (8px)
			panelHeight = 20 + 8 + lineHeight * wrappedLines.size() + 8;
			panelHeight = Math.max(panelHeight, HINT_PANEL_HEIGHT);
		}
		panelHeight += activityLogHeight;

		// Calculate pulse animation
		long elapsed = System.currentTimeMillis() - animationStartTime;
		double pulsePhase = (elapsed % PULSE_DURATION) / (double) PULSE_DURATION;
		float pulseAlpha = (float) (0.5 + 0.5 * Math.sin(pulsePhase * 2 * Math.PI));

		// Draw subtle outer glow (animated)
		Color glowColor = new Color(
			COLOR_ACCENT_GLOW.getRed(),
			COLOR_ACCENT_GLOW.getGreen(),
			COLOR_ACCENT_GLOW.getBlue(),
			(int)(COLOR_ACCENT_GLOW.getAlpha() * pulseAlpha * 0.5)
		);
		graphics.setColor(glowColor);
		graphics.fillRoundRect(-3, -3, HINT_PANEL_WIDTH + 6, panelHeight + 6, 10, 10);

		// Draw background
		graphics.setColor(COLOR_BG_DARK);
		graphics.fillRoundRect(0, 0, HINT_PANEL_WIDTH, panelHeight, 8, 8);

		// Draw accent border (animated)
		Color borderColor = new Color(
			COLOR_ACCENT.getRed(),
			COLOR_ACCENT.getGreen(),
			COLOR_ACCENT.getBlue(),
			(int)(150 + 100 * pulseAlpha)
		);
		graphics.setColor(borderColor);
		graphics.setStroke(new BasicStroke(1.5f));
		graphics.drawRoundRect(0, 0, HINT_PANEL_WIDTH, panelHeight, 8, 8);

		// Draw title
		graphics.setFont(FontManager.getRunescapeBoldFont());
		graphics.setColor(COLOR_ACCENT);
		FontMetrics boldMetrics = graphics.getFontMetrics();
		int titleWidth = boldMetrics.stringWidth(HINT_TITLE);
		graphics.drawString(HINT_TITLE, (HINT_PANEL_WIDTH - titleWidth) / 2, 20);

		if (hasIcon)
		{
			// Layout: [icon] + message text (centered together)
			graphics.setFont(FontManager.getRunescapeSmallFont());
			graphics.setColor(COLOR_TEXT);

			AsyncBufferedImage itemImage = itemManager.getImage(itemId);

			// Wrap message to fit alongside icon
			int iconSpace = hintIconSize + 6;
			List<String> iconLines = wrapText(message, smallMetrics, maxTextWidth - iconSpace);

			int lineHeight = smallMetrics.getHeight();
			int textBlockHeight = lineHeight * iconLines.size();
			int iconY = 32 + (textBlockHeight - hintIconSize) / 2;
			int textStartX = textPadding + iconSpace;

			if (itemImage != null)
			{
				graphics.drawImage(itemImage, textPadding, iconY, hintIconSize, hintIconSize, null);
			}

			int y = 32 + lineHeight;
			for (String line : iconLines)
			{
				drawHintLine(graphics, line, textStartX, y, smallMetrics);
				y += lineHeight;
			}
		}
		else
		{
			// Wrapped text layout
			graphics.setFont(FontManager.getRunescapeSmallFont());
			int lineHeight = smallMetrics.getHeight();
			int y = 28 + lineHeight;
			for (String line : wrappedLines)
			{
				int lineWidth = smallMetrics.stringWidth(line);
				drawHintLine(graphics, line, (HINT_PANEL_WIDTH - lineWidth) / 2, y, smallMetrics);
				y += lineHeight;
			}
		}

		if (!activityEntries.isEmpty())
		{
			int activityTop = panelHeight - activityLogHeight;
			renderActivityLog(graphics, activityEntries, activityTop, smallMetrics);
		}

		return new Dimension(HINT_PANEL_WIDTH, panelHeight);
	}

	private boolean isIdleAssistMessage(String message)
	{
		if (message == null)
		{
			return false;
		}
		return message.startsWith("Waiting for flips")
			|| message.startsWith("Monitoring active offers")
			|| message.startsWith(MONITORING_MESSAGE);
	}

	private int computeActivityLogHeight(List<TradeActivityLog.Entry> entries, FontMetrics fm)
	{
		if (entries.isEmpty())
		{
			return 0;
		}
		// gap above divider (4) + divider line (1) + gap below (4) + entries + bottom padding (4)
		return 4 + 1 + 4 + fm.getHeight() * entries.size() + 4;
	}

	private void renderActivityLog(Graphics2D graphics, List<TradeActivityLog.Entry> entries, int top, FontMetrics fm)
	{
		int dividerY = top + 4;
		graphics.setColor(COLOR_STEP_PENDING);
		graphics.setStroke(new BasicStroke(1f));
		graphics.drawLine(10, dividerY, HINT_PANEL_WIDTH - 10, dividerY);

		graphics.setFont(FontManager.getRunescapeSmallFont());
		int lineHeight = fm.getHeight();
		int textY = dividerY + 4 + fm.getAscent();
		int leftX = 10;
		int rightEdge = HINT_PANEL_WIDTH - 10;
		for (TradeActivityLog.Entry entry : entries)
		{
			String ago = TimeUtils.formatRelativeAgo(entry.getTimestampMs());
			int agoWidth = fm.stringWidth(ago);
			int agoX = rightEdge - agoWidth;

			String prefix = entry.isBuy() ? "Buy" : "Sell";
			String head = String.format("%s %dx ", prefix, entry.getQuantity());
			int nameMaxWidth = agoX - leftX - fm.stringWidth(head) - 4;
			String name = truncateString(entry.getItemName(), Math.max(0, nameMaxWidth), fm);

			graphics.setColor(entry.isBuy() ? COLOR_TRADE_BUY : COLOR_TRADE_SELL);
			graphics.drawString(head + name, leftX, textY);

			graphics.setColor(COLOR_TEXT_DIM);
			graphics.drawString(ago, agoX, textY);

			textY += lineHeight;
		}
	}

	private void drawHintLine(Graphics2D graphics, String line, int x, int y, FontMetrics fm)
	{
		int parenIdx = line.lastIndexOf(" (");
		boolean isNetParen = parenIdx > 0 && line.endsWith(")")
			&& (line.startsWith("(-", parenIdx + 1) || line.startsWith("(+", parenIdx + 1));
		if (!isNetParen)
		{
			graphics.setColor(getHintLineColor(line));
			graphics.drawString(line, x, y);
			return;
		}
		String base = line.substring(0, parenIdx);
		String paren = line.substring(parenIdx);
		graphics.setColor(getHintLineColor(base));
		graphics.drawString(base, x, y);
		graphics.setColor(paren.trim().startsWith("(-") ? COLOR_LOSS : COLOR_PROFIT);
		graphics.drawString(paren, x + fm.stringWidth(base), y);
	}

	private Color getHintLineColor(String line)
	{
		String trimmed = line.trim();
		if (trimmed.startsWith("Loss"))
		{
			return COLOR_LOSS;
		}
		if (trimmed.startsWith("Profit") || trimmed.startsWith("Breakeven"))
		{
			return COLOR_PROFIT;
		}
		if (trimmed.startsWith("Open GE History"))
		{
			return COLOR_GREEN_HINT;
		}
		if (trimmed.endsWith("gp"))
		{
			return COLOR_GREEN_HINT;
		}
		if (!trimmed.contains(":") && !trimmed.isEmpty()
			&& !trimmed.startsWith("Consider") && !trimmed.startsWith("Re-sell")
			&& !trimmed.startsWith("Adjust") && !trimmed.startsWith("Margin")
			&& !trimmed.startsWith("Click") && !trimmed.startsWith("Monitoring")
			&& !trimmed.startsWith("Waiting") && !trimmed.startsWith("Checking")
			&& !trimmed.startsWith("Auto"))
		{
			return COLOR_GREEN_HINT;
		}
		return COLOR_TEXT;
	}

	private List<String> wrapText(String text, FontMetrics fm, int maxWidth)
	{
		List<String> lines = new java.util.ArrayList<>();
		for (String segment : text.split("\n"))
		{
			if (fm.stringWidth(segment) <= maxWidth)
			{
				lines.add(segment);
			}
			else
			{
				wrapSegment(segment, fm, maxWidth, lines);
			}
		}
		return lines;
	}

	private void wrapSegment(String segment, FontMetrics fm, int maxWidth, List<String> lines)
	{
		StringBuilder currentLine = new StringBuilder();
		for (String word : segment.split(" "))
		{
			String candidate = currentLine.length() == 0 ? word : currentLine + " " + word;
			if (fm.stringWidth(candidate) <= maxWidth)
			{
				currentLine = new StringBuilder(candidate);
			}
			else
			{
				if (currentLine.length() > 0)
				{
					lines.add(currentLine.toString());
				}
				currentLine = new StringBuilder(word);
			}
		}
		if (currentLine.length() > 0)
		{
			lines.add(currentLine.toString());
		}
	}

	private int renderHeader(Graphics2D graphics, int y)
	{
		final FocusedFlip flip = focusedFlip;
		if (flip == null)
		{
			return y;
		}
		y += 4;

		AsyncBufferedImage itemImage = itemManager.getImage(flip.getItemId());
		if (itemImage != null)
		{
			graphics.drawImage(itemImage, SECTION_PADDING, y, ICON_SIZE, ICON_SIZE, null);
		}

		graphics.setFont(FontManager.getRunescapeBoldFont());
		graphics.setColor(COLOR_TEXT);
		String itemName = truncateString(flip.getItemName(), PANEL_WIDTH - ICON_SIZE - SECTION_PADDING * 3, graphics.getFontMetrics());
		graphics.drawString(itemName, SECTION_PADDING + ICON_SIZE + 6, y + 10);

		graphics.setFont(FontManager.getRunescapeSmallFont());
		graphics.setColor(flip.isBuying() ? COLOR_TRADE_BUY : COLOR_TRADE_SELL);
		String stepLabel;
		if (flip.isBuying())
		{
			stepLabel = "BUYING";
		}
		else
		{
			// Show "MODIFY" if there's already an active sell order for this item
			com.flipsmart.trading.OfferStore store = flipSmartPlugin.getOfferStore();
			boolean hasActiveSell = store != null && store.hasActiveSellOfferForItem(flip.getItemId());
			stepLabel = hasActiveSell ? "MODIFY" : "SELLING";
		}
		graphics.drawString(stepLabel, SECTION_PADDING + ICON_SIZE + 6, y + 24);

		return y + ICON_SIZE + 4;
	}

	private int renderStepProgress(Graphics2D graphics, int y, float pulseAlpha)
	{
		y += 4;
		FlipAssistStep[] stepsToShow = getStepsForCurrentPhase();
		int currentStepIndex = getStepIndex(currentStep, stepsToShow);
		int stepX = 20;
		int stepWidth = (PANEL_WIDTH - 40) / (stepsToShow.length - 1);

		for (int i = 0; i < stepsToShow.length; i++)
		{
			if (i > 0)
			{
				drawStepConnector(graphics, stepX, y, stepWidth, i <= currentStepIndex);
			}
			drawStepCircle(graphics, stepX, y, i, currentStepIndex, pulseAlpha);
			drawStepLabel(graphics, stepX, y, stepsToShow[i], i == currentStepIndex);
			stepX += stepWidth;
		}
		return y + 34;
	}

	private FlipAssistStep[] getStepsForCurrentPhase()
	{
		final FocusedFlip flip = focusedFlip;
		if (flip == null)
		{
			return new FlipAssistStep[0];
		}
		if (flip.isBuying())
		{
			return new FlipAssistStep[]{
				FlipAssistStep.SELECT_ITEM, FlipAssistStep.SET_QUANTITY,
				FlipAssistStep.SET_PRICE, FlipAssistStep.CONFIRM_OFFER
			};
		}
		return new FlipAssistStep[]{
			FlipAssistStep.SELL_ITEMS, FlipAssistStep.SET_QUANTITY,
			FlipAssistStep.SET_SELL_PRICE, FlipAssistStep.CONFIRM_SELL
		};
	}

	private void drawStepConnector(Graphics2D graphics, int stepX, int y, int stepWidth, boolean completed)
	{
		graphics.setColor(completed ? COLOR_STEP_COMPLETE : COLOR_STEP_PENDING);
		graphics.setStroke(new BasicStroke(2));
		int lineGap = 6;
		int yCenter = y + STEP_INDICATOR_SIZE / 2;
		graphics.drawLine(stepX - stepWidth + STEP_INDICATOR_SIZE / 2 + lineGap, yCenter,
			stepX - STEP_INDICATOR_SIZE / 2 - lineGap, yCenter);
	}

	private void drawStepCircle(Graphics2D graphics, int stepX, int y, int index, int currentIndex, float pulseAlpha)
	{
		Color stepColor = getStepColor(index, currentIndex, pulseAlpha);
		graphics.setColor(stepColor);
		graphics.fillOval(stepX - STEP_INDICATOR_SIZE / 2, y, STEP_INDICATOR_SIZE, STEP_INDICATOR_SIZE);

		graphics.setColor(COLOR_BG_DARK);
		if (index < currentIndex)
		{
			graphics.setFont(new Font("Arial", Font.BOLD, 7));
			graphics.drawString("✓", stepX - 2, y + 8);
		}
		else if (index == currentIndex)
		{
			graphics.setFont(new Font("Arial", Font.BOLD, 8));
			graphics.drawString(String.valueOf(index + 1), stepX - 2, y + 8);
		}
	}

	private Color getStepColor(int index, int currentIndex, float pulseAlpha)
	{
		if (index < currentIndex)
		{
			return COLOR_STEP_COMPLETE;
		}
		if (index == currentIndex)
		{
			return new Color(COLOR_STEP_CURRENT.getRed(), COLOR_STEP_CURRENT.getGreen(),
				COLOR_STEP_CURRENT.getBlue(), (int)(180 + 75 * pulseAlpha));
		}
		return COLOR_STEP_PENDING;
	}

	private void drawStepLabel(Graphics2D graphics, int stepX, int y, FlipAssistStep step, boolean isCurrent)
	{
		graphics.setFont(FontManager.getRunescapeSmallFont());
		graphics.setColor(isCurrent ? COLOR_TEXT : COLOR_TEXT_DIM);
		String label = getShortStepLabel(step);
		int labelWidth = graphics.getFontMetrics().stringWidth(label);
		graphics.drawString(label, stepX - labelWidth / 2, y + STEP_INDICATOR_SIZE + 12);
	}

	private int renderCurrentAction(Graphics2D graphics, int y, float pulseAlpha)
	{
		int boxHeight = 42;
		int boxMargin = 10;
		int boxWidth = PANEL_WIDTH - boxMargin * 2;

		graphics.setColor(COLOR_ACTION_BOX);
		graphics.fillRoundRect(boxMargin, y, boxWidth, boxHeight, 6, 6);

		Color borderColor = new Color(COLOR_ACCENT.getRed(), COLOR_ACCENT.getGreen(),
			COLOR_ACCENT.getBlue(), (int)(150 + 100 * pulseAlpha));
		graphics.setColor(borderColor);
		graphics.setStroke(new BasicStroke(1.5f));
		graphics.drawRoundRect(boxMargin, y, boxWidth, boxHeight, 6, 6);

		drawCenteredText(graphics, currentStep.getTitle(), y + 18, FontManager.getRunescapeBoldFont(), COLOR_ACCENT);
		drawCenteredText(graphics, formatStepDescription(), y + 34, FontManager.getRunescapeSmallFont(), COLOR_TEXT);

		return y + boxHeight + 4;
	}

	private void drawCenteredText(Graphics2D graphics, String text, int y, Font font, Color color)
	{
		graphics.setFont(font);
		graphics.setColor(color);
		int width = graphics.getFontMetrics().stringWidth(text);
		graphics.drawString(text, (PANEL_WIDTH - width) / 2, y);
	}

	private void renderFlipSummary(Graphics2D graphics, int y)
	{
		final FocusedFlip flip = focusedFlip;
		if (flip == null)
		{
			return;
		}
		graphics.setFont(FontManager.getRunescapeSmallFont());
		int lineHeight = 12;

		String priceLabel = flip.isBuying() ? "Buy at:" : "Sell at:";
		drawLabelValue(graphics, priceLabel, PRICE_FORMAT.get().format(flip.getCurrentStepPrice()) + " gp",
			y + lineHeight, flip.isBuying() ? COLOR_TRADE_BUY : COLOR_TRADE_SELL);

		drawLabelValue(graphics, "Qty:", PRICE_FORMAT.get().format(flip.getCurrentStepQuantity()),
			y + lineHeight * 2, COLOR_TEXT);

		if (flip.isBuying() && flip.getSellPrice() > 0)
		{
			long totalProfit = calculateTotalProfit();
			drawLabelValue(graphics, "Profit:", PRICE_FORMAT.get().format(totalProfit) + " gp",
				y + lineHeight * 3, totalProfit > 0 ? COLOR_PROFIT : new Color(255, 100, 100));
		}
	}

	private void drawLabelValue(Graphics2D graphics, String label, String value, int y, Color valueColor)
	{
		graphics.setColor(COLOR_TEXT_DIM);
		graphics.drawString(label, SECTION_PADDING, y);
		graphics.setColor(valueColor);
		graphics.drawString(value, SECTION_PADDING + 42, y);
	}

	private long calculateTotalProfit()
	{
		final FocusedFlip flip = focusedFlip;
		if (flip == null)
		{
			return 0;
		}
		long margin = flip.getSellPrice() - flip.getBuyPrice();
		int geTax = GeTax.taxFor(flip.getItemId(), flip.getSellPrice());
		return (margin - geTax) * flip.getBuyQuantity();
	}

	private String formatStepDescription()
	{
		String hotkeyName = config.flipAssistHotkey().toString();
		final FocusedFlip flip = focusedFlip;
		if (flip == null)
		{
			return currentStep.getDescription();
		}

		switch (currentStep)
		{
			case SET_QUANTITY:
				int targetQty = flip.getCurrentStepQuantity();
				// Just show the target quantity with hotkey
				return String.format(currentStep.getDescription(), hotkeyName,
					PRICE_FORMAT.get().format(targetQty));
			case SET_PRICE:
			case SET_SELL_PRICE:
				long targetPrice = flip.getCurrentStepPrice();
				// Just show the target price with hotkey
				return String.format(currentStep.getDescription(), hotkeyName,
					PRICE_FORMAT.get().format(targetPrice));
			default:
				return currentStep.getDescription();
		}
	}

	private String getShortStepLabel(FlipAssistStep step)
	{
		switch (step)
		{
			case SELECT_ITEM:
			case SELL_ITEMS:
				return "Select";
			case SET_QUANTITY:
				return "Qty";
			case SET_PRICE:
			case SET_SELL_PRICE:
				return "Price";
			case CONFIRM_OFFER:
			case CONFIRM_SELL:
				return "Confirm";
			case COMPLETE:
				return "Done";
			default:
				return step.getTitle().substring(0, Math.min(5, step.getTitle().length()));
		}
	}

	private int getStepIndex(FlipAssistStep step, FlipAssistStep[] steps)
	{
		for (int i = 0; i < steps.length; i++)
		{
			if (steps[i] == step || isEquivalentStep(steps[i], step))
			{
				return i;
			}
		}
		return 0;
	}

	private boolean isEquivalentStep(FlipAssistStep a, FlipAssistStep b)
	{
		if ((a == FlipAssistStep.SELECT_ITEM || a == FlipAssistStep.SELL_ITEMS) && b == FlipAssistStep.SEARCH_ITEM)
		{
			return true;
		}
		return a == FlipAssistStep.SET_QUANTITY && b == FlipAssistStep.SET_QUANTITY;
	}

	private boolean isGrandExchangeOpen()
	{
		// Check the main GE interface (465) - this is the primary indicator
		Widget geWidget = client.getWidget(GE_INTERFACE_GROUP, 0);
		if (geWidget != null && !geWidget.isHidden())
		{
			return true;
		}

		// Also check if we're in the GE offer setup dialog specifically
		// Widget 162 is the chatbox which is used for many dialogs, so we need
		// to verify it's actually a GE-related dialog by checking for GE-specific content
		Widget offerPanel = client.getWidget(GE_INTERFACE_GROUP, GE_OFFER_PANEL_CHILD);
		return offerPanel != null && !offerPanel.isHidden();
	}

	private boolean isOfferSetupOpen()
	{
		Widget[] children = getOfferPanelChildren();
		if (children.length < 30)
		{
			return false;
		}

		boolean hasQuantityLabel = false;
		boolean hasPriceCoins = false;

		for (Widget child : children)
		{
			String text = getVisibleWidgetText(child);
			if (text != null)
			{
				hasQuantityLabel = hasQuantityLabel || text.contains("Quantity:");
				hasPriceCoins = hasPriceCoins || (text.contains(COINS_TEXT) && text.matches(".*\\d+.*"));
			}
		}
		return hasQuantityLabel && hasPriceCoins;
	}

	/**
	 * True while the player is in any GE buy/sell offer interface: the item-search
	 * screen, the numeric quantity/price input, or the offer-setup screen. While one
	 * is open the offer takes priority and transient status prompts are hidden.
	 */
	private boolean isInOfferInterface()
	{
		if (!isGrandExchangeOpen())
		{
			return false;
		}
		int inputType = getInputType();
		return inputType == INPUT_TYPE_GE_SEARCH
			|| isNumericInput(inputType)
			|| isOfferSetupOpen();
	}

	/**
	 * Pick the hint/status message to draw when no flip is focused, or null to draw
	 * nothing. While any buy/sell offer interface is open the offer takes priority and
	 * ALL prompts — including the one-shot history-backfill prompt — are suppressed so
	 * nothing overlays the buy/sell screens; the prompts re-surface at the main GE view
	 * (none of them are cleared). Off the offer interface the history prompt takes
	 * priority over the auto-recommend status, then login, then the generic hint.
	 */
	static String selectNoFocusMessage(
		boolean showHistoryPrompt,
		boolean offerInterfaceOpen,
		String autoStatusMessage,
		String autoRecommendFallback,
		boolean authenticated,
		boolean hasTradeActivity,
		String historyMessage,
		String loginMessage,
		String monitoringMessage,
		String hintMessage)
	{
		if (offerInterfaceOpen)
		{
			return null;
		}
		if (showHistoryPrompt)
		{
			return historyMessage;
		}
		if (autoStatusMessage != null)
		{
			return autoStatusMessage;
		}
		if (autoRecommendFallback != null)
		{
			return autoRecommendFallback;
		}
		// GE activity opens the monitoring log regardless of Auto mode (AC12/AC13).
		if (authenticated && hasTradeActivity)
		{
			return monitoringMessage;
		}
		if (!authenticated)
		{
			return loginMessage;
		}
		return hintMessage;
	}

	/**
	 * The item icon to draw beside a no-focus hint message. Only the auto-status
	 * prompt carries an item ("Collect X"); every other message source (history,
	 * monitoring, login, hint, fallback) is text-only. Returning the item id only
	 * when the displayed message is exactly the auto-status message keeps the icon
	 * from bleeding onto a higher-priority text-only prompt.
	 */
	static int iconForNoFocusMessage(String displayedMessage, String autoStatusMessage, int autoStatusItemId)
	{
		if (autoStatusItemId > 0 && displayedMessage != null && displayedMessage.equals(autoStatusMessage))
		{
			return autoStatusItemId;
		}
		return 0;
	}

	private Widget[] getOfferPanelChildren()
	{
		Widget offerPanel = client.getWidget(GE_INTERFACE_GROUP, GE_OFFER_PANEL_CHILD);
		if (offerPanel == null || offerPanel.isHidden())
		{
			return new Widget[0];
		}
		Widget[] children = offerPanel.getDynamicChildren();
		return children != null ? children : new Widget[0];
	}

	private String getVisibleWidgetText(Widget widget)
	{
		if (widget == null || widget.isHidden())
		{
			return null;
		}
		return widget.getText();
	}

	private int getInputType()
	{
		return client.getVarcIntValue(VARCLIENT_INPUT_TYPE);
	}

	private static boolean isNumericInput(int inputType)
	{
		return inputType == INPUT_TYPE_NUMERIC || inputType == INPUT_TYPE_NUMERIC_LONG;
	}

	private boolean isLikelyPriceInput()
	{
		for (int groupId : CHATBOX_WIDGET_GROUPS)
		{
			Boolean result = checkChatboxGroupForInputType(groupId);
			if (result != null)
			{
				return result;
			}
		}
		return getCurrentQuantityFromGE() > 1;
	}

	@SuppressWarnings("java:S2447") // null represents "no determination made" in tri-state logic
	private Boolean checkChatboxGroupForInputType(int groupId)
	{
		for (int childId = 0; childId <= 50; childId++)
		{
			Boolean result = checkWidgetForInputType(client.getWidget(groupId, childId));
			if (result != null)
			{
				return result;
			}
		}
		return null;
	}

	@SuppressWarnings("java:S2447") // null represents "no determination made" in tri-state logic
	private Boolean checkWidgetForInputType(Widget widget)
	{
		String text = getVisibleWidgetText(widget);
		if (text == null || text.isEmpty())
		{
			return null;
		}
		String lowerText = text.toLowerCase();
		if (lowerText.contains("price") && !lowerText.contains("price:"))
		{
			return Boolean.TRUE;
		}
		if (lowerText.contains("how many"))
		{
			return Boolean.FALSE;
		}
		return null;
	}

	private long getCurrentQuantityFromGE()
	{
		Widget[] children = getOfferPanelChildren();
		return findNumericValueInRange(children, GE_QTY_CHILD_START, GE_QTY_CHILD_END, false);
	}

	private long findNumericValueInRange(Widget[] children, int start, int end, boolean requireCoins)
	{
		for (int i = start; i <= end && i < children.length; i++)
		{
			long value = extractValueFromWidget(children[i], requireCoins);
			if (value >= 1)
			{
				return value;
			}
		}
		return 0;
	}

	private long extractValueFromWidget(Widget widget, boolean requireCoins)
	{
		String text = getVisibleWidgetText(widget);
		if (text == null || text.isEmpty())
		{
			return 0;
		}
		String lowerText = text.toLowerCase();
		if (requireCoins && !lowerText.contains(COINS_TEXT))
		{
			return 0;
		}
		if (!requireCoins && (lowerText.contains(COINS_TEXT) || lowerText.contains("quantity") || lowerText.contains("price")))
		{
			return 0;
		}
		return GpUtils.parseDigits(text);
	}

	private long getCurrentPriceFromGE()
	{
		Widget[] children = getOfferPanelChildren();
		long value = findNumericValueInRange(children, GE_PRICE_CHILD_START, GE_PRICE_CHILD_END, true);
		return value > 0 ? value : getCurrentPriceFromGEFallback();
	}

	private long getCurrentPriceFromGEFallback()
	{
		int[] priceWidgetIds = {25, 27};
		for (int childId : priceWidgetIds)
		{
			long value = findPriceInWidget(client.getWidget(GE_INTERFACE_GROUP, childId));
			if (value > 0)
			{
				return value;
			}
		}
		return 0;
	}

	private long findPriceInWidget(Widget widget)
	{
		if (widget == null || widget.isHidden())
		{
			return 0;
		}

		long value = extractCoinsValue(widget.getText());
		if (value > 0)
		{
			return value;
		}

		Widget[] children = widget.getDynamicChildren();
		if (children == null)
		{
			return 0;
		}
		for (Widget child : children)
		{
			value = extractCoinsValue(getVisibleWidgetText(child));
			if (value > 0)
			{
				return value;
			}
		}
		return 0;
	}

	private long extractCoinsValue(String text)
	{
		if (text != null && text.toLowerCase().contains(COINS_TEXT))
		{
			return GpUtils.parseDigits(text);
		}
		return 0;
	}


	private String truncateString(String str, int maxWidth, FontMetrics fm)
	{
		if (fm.stringWidth(str) <= maxWidth)
		{
			return str;
		}

		String ellipsis = "...";
		int len = str.length();
		while (len > 0 && fm.stringWidth(str.substring(0, len)) + fm.stringWidth(ellipsis) > maxWidth)
		{
			len--;
		}
		return str.substring(0, len) + ellipsis;
	}

	public void setFocusedFlip(FocusedFlip focusedFlip)
	{
		this.focusedFlip = focusedFlip;
		if (focusedFlip != null)
		{
			this.autoStatusMessage = null;
			setGELastSearchedItem(focusedFlip.getItemId());
		}
	}

	public void setAutoStatusMessage(String message, int itemId)
	{
		this.autoStatusMessage = message;
		this.autoStatusItemId = itemId;
	}

	// Clear the auto-status prompt only if it belongs to this item (e.g. its flip completed),
	// leaving a prompt for any other active item untouched.
	public void clearAutoStatusForItem(int itemId)
	{
		if (autoStatusItemId == itemId)
		{
			this.autoStatusMessage = null;
			this.autoStatusItemId = 0;
		}
	}

	private void setGELastSearchedItem(int itemId)
	{
		clientThread.invokeLater(() -> {
			try
			{
				int[] varps = client.getVarps();
				varps[VarPlayerID.GE_LAST_SEARCHED] = itemId;
				client.queueChangedVarp(VarPlayerID.GE_LAST_SEARCHED);
			}
			catch (Exception e)
			{
				log.warn("Failed to set GE last searched item: {}", e.getMessage());
			}
		});
	}

	public void clearFocus()
	{
		this.focusedFlip = null;
		this.autoStatusMessage = null;
		this.autoStatusItemId = 0;
		this.currentStep = FlipAssistStep.SELECT_ITEM;
	}
}

package com.flipsmart;

import com.flipsmart.api.dto.Dtos.WikiPrice;
import com.flipsmart.domain.offer.OfferSignal;
import com.flipsmart.util.BuyPriceLookup;
import com.flipsmart.util.GeTax;
import com.flipsmart.util.GpUtils;
import java.text.NumberFormat;
import java.util.List;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;

import java.awt.*;

/**
 * Overlay that draws timer and competitiveness indicators directly on the
 * native Grand Exchange interface slots.
 */
@Slf4j
public class GrandExchangeSlotOverlay extends Overlay
{
	// GE Interface constants
	private static final int GE_INTERFACE_GROUP = 465;

	// The main offer container shows all GE slots - child IDs for slot containers
	// These are the container widgets for each GE slot (0-7)
	// Widget 465.7 through 465.14 are the slot containers in the main view
	private static final int GE_SLOT_CONTAINER_START = 7;

	// GE offer setup panel and button widget IDs
	private static final int GE_OFFER_CONTAINER = 26;       // The offer setup container widget
	private static final int GE_OFFER_QUANTITY_BUTTON_CHILD = 51;  // Child ID for "Set quantity" button
	private static final int GE_OFFER_PRICE_BUTTON_CHILD = 54;     // Child ID for "Set price" button
	private static final int GE_OFFER_CONFIRM_BUTTON_CHILD = 58;   // Child ID for "Confirm" button

	// Main GE panel: buy/sell button child IDs within each slot widget (465.7-14)
	// Discovered via RuneLite Widget Inspector
	private static final int GE_SLOT_BUY_BUTTON_CHILD = 0;   // Buy button within empty slot
	private static final int GE_SLOT_SELL_BUTTON_CHILD = 1;  // Sell button within empty slot

	// Maximum number of GE slots available to a player
	private static final int GE_MAX_SLOTS = 8;

	// Colors - designed to blend with GE's brown/tan color scheme
	private static final Color COLOR_COMPETITIVE = new Color(76, 187, 23);        // OSRS green
	private static final Color COLOR_UNCOMPETITIVE = new Color(215, 75, 75);      // Soft red
	private static final Color COLOR_FLIP_ASSIST_GLOW = new Color(255, 185, 50);  // Orange glow for flip assist

	// Colorblind-safe alternative colors (blue/orange instead of green/red)
	private static final Color COLOR_COMPETITIVE_CB = new Color(0, 102, 204);           // Blue
	private static final Color COLOR_UNCOMPETITIVE_CB = new Color(255, 140, 0);         // Orange

	// Adjustment highlight color — amber pulse to draw attention without conflicting with red/green
	private static final NumberFormat NUMBER_FORMAT = NumberFormat.getIntegerInstance();

	// Slots with pending adjustment recommendations (slot -> recommended price)
	private final java.util.Map<Integer, Long> adjustmentHighlights = new java.util.concurrent.ConcurrentHashMap<>();

	// Slots whose orange box must persist across focus changes because the player skipped
	// their maintenance action and it is still within its cooldown. Transient clears
	// (clearAllAdjustmentHighlights) deliberately leave these alone; they are dropped only
	// when the cooldown expires or the offer is acted on / leaves the GE.
	private final java.util.Set<Integer> stickyAdjustmentSlots = java.util.concurrent.ConcurrentHashMap.newKeySet();

	private final Client client;
	private final FlipSmartConfig config;
	private final FlipSmartPlugin plugin;

	@Inject
	private GrandExchangeSlotOverlay(Client client, FlipSmartConfig config, FlipSmartPlugin plugin)
	{
		this.client = client;
		this.config = config;
		this.plugin = plugin;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(OverlayPriority.LOW);
	}

	/**
	 * Set an adjustment highlight on a GE slot to draw attention to a stale offer.
	 *
	 * @param slot GE slot index
	 * @param recommendedPrice The recommended adjustment price
	 */
	public void setAdjustmentHighlight(int slot, long recommendedPrice)
	{
		adjustmentHighlights.put(slot, recommendedPrice);
	}

	/**
	 * Clear the adjustment highlight for a GE slot.
	 */
	public void clearAdjustmentHighlight(int slot)
	{
		adjustmentHighlights.remove(slot);
	}

	/**
	 * Clear all transient adjustment highlights (e.g., on a focus change). Sticky
	 * highlights kept for a skipped-but-cooling action are intentionally preserved.
	 */
	public void clearAllAdjustmentHighlights()
	{
		adjustmentHighlights.clear();
	}

	/**
	 * Keep a slot's orange box lit across focus changes while its skipped action cools
	 * down.
	 */
	public void setStickyAdjustmentHighlight(int slot)
	{
		stickyAdjustmentSlots.add(slot);
	}

	/**
	 * Drop the sticky highlight for a slot (cooldown expired, or the offer was acted on).
	 */
	public void clearStickyAdjustmentHighlight(int slot)
	{
		stickyAdjustmentSlots.remove(slot);
	}

	/**
	 * Full reset of every highlight, transient and sticky (e.g., on logout or when
	 * auto-mode stops).
	 */
	public void resetAllHighlights()
	{
		adjustmentHighlights.clear();
		stickyAdjustmentSlots.clear();
	}

	/**
	 * Get the competitive color (green or blue for colorblind mode)
	 */
	private Color getCompetitiveColor()
	{
		return config.colorblindMode() ? COLOR_COMPETITIVE_CB : COLOR_COMPETITIVE;
	}

	/**
	 * Get the uncompetitive color (red or orange for colorblind mode)
	 */
	private Color getUncompetitiveColor()
	{
		return config.colorblindMode() ? COLOR_UNCOMPETITIVE_CB : COLOR_UNCOMPETITIVE;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!isGEInterfaceOpen())
		{
			return null;
		}

		// Ensure wiki prices are loaded for competitiveness indicators
		plugin.refreshWikiPrices();

		setupGraphics(graphics);
		renderFlipAssistHighlights(graphics);

		if (!hasAnySlotFeaturesEnabled())
		{
			return null;
		}

		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers == null)
		{
			return null;
		}

		TooltipData tooltip = renderAllSlots(graphics, offers);
		if (tooltip != null)
		{
			drawPriceTooltip(graphics, tooltip.x, tooltip.y, tooltip.offer, tooltip.wikiPrice, tooltip.offerPrice, tooltip.buyPrice);
		}

		return null;
	}

	/**
	 * Check if the GE interface is currently open
	 */
	private boolean isGEInterfaceOpen()
	{
		Widget geMainWidget = client.getWidget(GE_INTERFACE_GROUP, 0);
		return geMainWidget != null && !geMainWidget.isHidden();
	}

	/**
	 * Setup graphics rendering hints
	 */
	private void setupGraphics(Graphics2D graphics)
	{
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
	}

	/**
	 * Render flip assist button highlights if enabled
	 */
	private void renderFlipAssistHighlights(Graphics2D graphics)
	{
		if (config.highlightGEWidgets() && plugin.isFlipAssistActive())
		{
			drawFlipAssistButtonHighlights(graphics);
		}
	}

	/**
	 * Check if any GE slot features are enabled
	 */
	private boolean hasAnySlotFeaturesEnabled()
	{
		return config.showOfferTimers() || config.showCompetitivenessIndicators() || config.highlightSlotBorders();
	}

	/**
	 * Data class for tooltip information
	 */
	private static class TooltipData
	{
		GrandExchangeOffer offer;
		WikiPrice wikiPrice;
		long offerPrice;
		int x;
		int y;
		Long buyPrice; // null if no buy price on record or not a sell offer
	}

	/**
	 * Render all GE slots and return tooltip data if mouse is hovering
	 */
	private TooltipData renderAllSlots(Graphics2D graphics, GrandExchangeOffer[] offers)
	{
		TooltipData tooltip = null;

		for (int slot = 0; slot < Math.min(offers.length, GE_MAX_SLOTS); slot++)
		{
			TooltipData slotTooltip = renderSlot(graphics, slot, offers[slot]);
			if (slotTooltip != null)
			{
				tooltip = slotTooltip;
			}
		}

		return tooltip;
	}

	/**
	 * Render a single GE slot's overlays
	 */
	private TooltipData renderSlot(Graphics2D graphics, int slot, GrandExchangeOffer offer)
	{
		if (offer.getState() == GrandExchangeOfferState.EMPTY)
		{
			return null;
		}

		Widget slotWidget = getSlotWidget(slot);
		if (slotWidget == null || slotWidget.isHidden())
		{
			return null;
		}

		Rectangle bounds = slotWidget.getBounds();
		if (bounds == null || bounds.width == 0)
		{
			return null;
		}

		renderAmberGlow(graphics, bounds, slot);

		return checkForTooltip(bounds, offer);
	}

	/**
	 * Render the amber Flip Assist glow for the slot, if any. The competitiveness border and the
	 * timer are native widget manipulations (GeSlotWidgetDecorator), not drawn here, so they always
	 * sit under the game's hover text.
	 */
	private void renderAmberGlow(Graphics2D graphics, Rectangle bounds, int slot)
	{
		// A current-action highlight (bright amber pulse) always wins over a skipped-item
		// reminder on the same slot; a sticky-only slot renders dimmed so it reads as
		// secondary and never competes with the slot the Flip Assist panel is prompting.
		if (adjustmentHighlights.containsKey(slot))
		{
			drawOrangeGlow(graphics, bounds);
		}
		else if (stickyAdjustmentSlots.contains(slot))
		{
			drawDimReminderGlow(graphics, bounds);
		}
	}

	/**
	 * Check if mouse is hovering over slot and return tooltip data
	 */
	private TooltipData checkForTooltip(Rectangle bounds, GrandExchangeOffer offer)
	{
		net.runelite.api.Point mousePos = client.getMouseCanvasPosition();
		if (mousePos == null || !bounds.contains(mousePos.getX(), mousePos.getY()))
		{
			return null;
		}

		TooltipData tooltip = new TooltipData();
		tooltip.offer = offer;
		tooltip.wikiPrice = plugin.getWikiPrice(offer.getItemId());
		tooltip.offerPrice = offer.getPrice();
		tooltip.x = mousePos.getX() + 15;
		tooltip.y = mousePos.getY() - 30;

		if (!isOfferBuyType(offer) && config.showProfitLoss())
		{
			tooltip.buyPrice = getBuyPriceForItem(offer.getItemId());
		}

		if (tooltip.wikiPrice == null)
		{
			plugin.refreshWikiPrices();
		}

		return tooltip;
	}

	private Long getBuyPriceForItem(int itemId)
	{
		return BuyPriceLookup.findAverageBuyPriceWithFallback(
			plugin.getCurrentActiveFlips(), plugin.getCycleBasisForItem(itemId),
			plugin.getOfferRecordsForItem(itemId), itemId, plugin.getHeldQuantityForItem(itemId));
	}

	/**
	 * Get the widget for a specific GE slot (0-7)
	 */
	private Widget getSlotWidget(int slot)
	{
		// The GE interface has slot containers at different child IDs
		// Main GE view: slots are children 7-14 of group 465
		Widget slotWidget = client.getWidget(GE_INTERFACE_GROUP, GE_SLOT_CONTAINER_START + slot);

		if (slotWidget != null && !slotWidget.isHidden())
		{
			return slotWidget;
		}

		return null;
	}

	/**
	 * Draw a custom tooltip with background showing real-time insta prices
	 */
	private void drawPriceTooltip(Graphics2D graphics, int x, int y, GrandExchangeOffer offer,
								  WikiPrice wikiPrice, long offerPrice, Long buyPrice)
	{
		boolean isBuy = isOfferBuyType(offer);

		Font originalFont = graphics.getFont();
		graphics.setFont(new Font("Arial", Font.PLAIN, 11));
		FontMetrics fm = graphics.getFontMetrics();

		List<String> lines = buildTooltipLines(wikiPrice, offerPrice, buyPrice, isBuy, offer.getTotalQuantity(), offer.getItemId());
		Color yourPriceColor = determineYourPriceColor(wikiPrice, offerPrice, isBuy);

		drawTooltipBackground(graphics, x, y, lines, fm);
		drawTooltipText(graphics, x, y, lines, yourPriceColor, fm);

		graphics.setFont(originalFont);
	}

	/**
	 * Check if offer is a buy type (BUYING, BOUGHT, or CANCELLED_BUY)
	 */
	private boolean isOfferBuyType(GrandExchangeOffer offer)
	{
		return OfferSignal.isBuyState(offer.getState());
	}

	/**
	 * Build tooltip text lines based on wiki price data
	 */
	private List<String> buildTooltipLines(WikiPrice wikiPrice, long offerPrice,
													  Long buyPrice, boolean isBuy, int totalQuantity, int itemId)
	{
		List<String> lines = new java.util.ArrayList<>();

		addPriceLines(lines, wikiPrice);
		lines.add("Your Price: " + NUMBER_FORMAT.format(offerPrice) + " gp");

		if (!isBuy && buyPrice != null && buyPrice > 0 && totalQuantity > 0)
		{
			addProfitLossLine(lines, offerPrice, buyPrice, totalQuantity, itemId);
		}

		return lines;
	}

	private void addPriceLines(List<String> lines, WikiPrice wikiPrice)
	{
		if (wikiPrice == null || (wikiPrice.instaBuy <= 0 && wikiPrice.instaSell <= 0))
		{
			lines.add("Price data loading...");
			return;
		}
		if (wikiPrice.instaBuy > 0)
		{
			lines.add("Insta Buy: " + NUMBER_FORMAT.format(wikiPrice.instaBuy) + " gp");
		}
		if (wikiPrice.instaSell > 0)
		{
			lines.add("Insta Sell: " + NUMBER_FORMAT.format(wikiPrice.instaSell) + " gp");
		}
	}

	static void addProfitLossLine(List<String> lines, long sellPrice, long buyPrice, int totalQuantity, int itemId)
	{
		// Honor the GE tax-exempt list and the <=50gp threshold (issue #685 Bugs 3 & 4).
		// ROI uses netPnlPerItem so it automatically becomes pre-tax for exempt items
		// and post-tax for taxable ones, matching AC2 of Bug 4.
		int geTaxPerItem = GeTax.taxFor(itemId, sellPrice);
		long netPnlPerItem = sellPrice - buyPrice - geTaxPerItem;
		long totalPnl = netPnlPerItem * totalQuantity;
		double roiPercent = (netPnlPerItem / (double) buyPrice) * 100.0;

		lines.add("---");

		String formattedPnl = formatPnlValue(totalPnl);
		String label = totalPnl >= 0 ? "Profit: " : "Loss: ";
		lines.add(label + formattedPnl + " gp (" + String.format("%.1f%%", roiPercent) + ")");
	}

	private static String formatPnlValue(long totalPnl)
	{
		if (Math.abs(totalPnl) >= 100_000)
		{
			return GpUtils.formatGPSigned(totalPnl);
		}
		String sign = totalPnl >= 0 ? "+" : "";
		return sign + NUMBER_FORMAT.format(totalPnl);
	}

	/**
	 * Determine color for user's price based on competitiveness
	 */
	private Color determineYourPriceColor(WikiPrice wikiPrice, long offerPrice, boolean isBuy)
	{
		if (wikiPrice == null || (wikiPrice.instaBuy <= 0 && wikiPrice.instaSell <= 0))
		{
			return Color.WHITE;
		}

		boolean isCompetitive = isBuy
			? offerPrice >= wikiPrice.instaSell
			: offerPrice <= wikiPrice.instaBuy;

		return isCompetitive ? getCompetitiveColor() : getUncompetitiveColor();
	}

	/**
	 * Draw tooltip background and border
	 */
	private static final int DIVIDER_HEIGHT = 6;

	private void drawTooltipBackground(Graphics2D graphics, int x, int y, List<String> lines, FontMetrics fm)
	{
		int lineHeight = fm.getHeight();
		int padding = 5;
		int maxWidth = lines.stream()
			.filter(l -> !l.equals("---"))
			.mapToInt(fm::stringWidth).max().orElse(0);
		int tooltipWidth = maxWidth + padding * 2;

		int textLines = (int) lines.stream().filter(l -> !l.equals("---")).count();
		int dividers = (int) lines.stream().filter(l -> l.equals("---")).count();
		int tooltipHeight = lineHeight * textLines + DIVIDER_HEIGHT * dividers + padding * 2;

		graphics.setColor(new Color(30, 30, 30, 220));
		graphics.fillRoundRect(x, y, tooltipWidth, tooltipHeight, 4, 4);

		graphics.setColor(new Color(80, 80, 80));
		graphics.drawRoundRect(x, y, tooltipWidth, tooltipHeight, 4, 4);
	}

	/**
	 * Draw tooltip text lines
	 */
	private void drawTooltipText(Graphics2D graphics, int x, int y, List<String> lines,
								 Color yourPriceColor, FontMetrics fm)
	{
		int padding = 5;
		int textY = y + padding + fm.getAscent();
		int maxWidth = lines.stream()
			.filter(l -> !l.equals("---"))
			.mapToInt(fm::stringWidth).max().orElse(0);

		for (String line : lines)
		{
			if (line.equals("---"))
			{
				int dividerY = textY - fm.getAscent() + DIVIDER_HEIGHT / 2;
				graphics.setColor(new Color(80, 80, 80));
				graphics.drawLine(x + padding, dividerY, x + padding + maxWidth, dividerY);
				textY += DIVIDER_HEIGHT;
			}
			else
			{
				drawTooltipLine(graphics, line, x + padding, textY, yourPriceColor, fm);
				textY += fm.getHeight();
			}
		}
	}

	/**
	 * Draw a single tooltip line with appropriate coloring
	 */
	private void drawTooltipLine(Graphics2D graphics, String line, int x, int y, Color yourPriceColor, FontMetrics fm)
	{
		if (line.startsWith("Your Price:"))
		{
			String prefix = "Your Price: ";
			graphics.setColor(Color.WHITE);
			graphics.drawString(prefix, x, y);

			graphics.setColor(yourPriceColor);
			graphics.drawString(line.substring(prefix.length()), x + fm.stringWidth(prefix), y);
		}
		else if (line.startsWith("Profit:"))
		{
			String prefix = "Profit: ";
			graphics.setColor(Color.WHITE);
			graphics.drawString(prefix, x, y);
			graphics.setColor(getCompetitiveColor());
			graphics.drawString(line.substring(prefix.length()), x + fm.stringWidth(prefix), y);
		}
		else if (line.startsWith("Loss:"))
		{
			String prefix = "Loss: ";
			graphics.setColor(Color.WHITE);
			graphics.drawString(prefix, x, y);
			graphics.setColor(getUncompetitiveColor());
			graphics.drawString(line.substring(prefix.length()), x + fm.stringWidth(prefix), y);
		}
		else
		{
			graphics.setColor(Color.WHITE);
			graphics.drawString(line, x, y);
		}
	}

	/**
	 * Draw orange glow highlights on GE buttons based on the current flip assist step.
	 * Handles both the main GE panel (8-slot overview) and the offer setup panel.
	 */
	private void drawFlipAssistButtonHighlights(Graphics2D graphics)
	{
		FlipAssistOverlay.FlipAssistStep step = plugin.getFlipAssistStep();
		if (step == null)
		{
			return;
		}

		// Handle steps on the main GE panel (SELECT_ITEM / SELL_ITEMS)
		if (step == FlipAssistOverlay.FlipAssistStep.SELECT_ITEM ||
			step == FlipAssistOverlay.FlipAssistStep.SELL_ITEMS)
		{
			// During an Exit Trades re-list of an offer that still owns its slot, the item's own
			// slot is already highlighted — don't also glow the sell button on empty slots.
			if (step == FlipAssistOverlay.FlipAssistStep.SELL_ITEMS
				&& plugin.getExitTradesController() != null
				&& plugin.getExitTradesController().isModifyingActiveOffer())
			{
				return;
			}
			drawMainPanelButtonHighlights(graphics, step);
			return;
		}

		// Handle steps on the offer setup panel (SET_QUANTITY, SET_PRICE, CONFIRM)
		drawOfferSetupButtonHighlights(graphics, step);
	}

	/**
	 * Highlight buy/sell buttons on empty GE slots in the main 8-slot panel.
	 */
	private void drawMainPanelButtonHighlights(Graphics2D graphics, FlipAssistOverlay.FlipAssistStep step)
	{
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers == null)
		{
			return;
		}

		int buttonChild = (step == FlipAssistOverlay.FlipAssistStep.SELECT_ITEM)
			? GE_SLOT_BUY_BUTTON_CHILD
			: GE_SLOT_SELL_BUTTON_CHILD;

		for (int slot = 0; slot < Math.min(offers.length, GE_MAX_SLOTS); slot++)
		{
			Widget slotWidget = client.getWidget(GE_INTERFACE_GROUP, GE_SLOT_CONTAINER_START + slot);
			if (offers[slot].getState() != GrandExchangeOfferState.EMPTY
				|| slotWidget == null || slotWidget.isHidden())
			{
				continue;
			}

			Widget buttonWidget = slotWidget.getChild(buttonChild);
			if (buttonWidget != null && !buttonWidget.isHidden())
			{
				Rectangle bounds = buttonWidget.getBounds();
				if (bounds != null && bounds.width > 0)
				{
					drawOrangeGlow(graphics, bounds);
				}
			}
		}
	}

	/**
	 * Highlight buttons on the offer setup panel (quantity, price, confirm).
	 * Uses GE offer setup widget child IDs for quantity, price, and confirm buttons.
	 */
	private void drawOfferSetupButtonHighlights(Graphics2D graphics, FlipAssistOverlay.FlipAssistStep step)
	{
		Widget offerContainer = client.getWidget(GE_INTERFACE_GROUP, GE_OFFER_CONTAINER);
		if (offerContainer == null || offerContainer.isHidden())
		{
			return;
		}

		int childId = -1;

		switch (step)
		{
			case SET_QUANTITY:
				childId = GE_OFFER_QUANTITY_BUTTON_CHILD;
				break;
			case SET_PRICE:
			case SET_SELL_PRICE:
				childId = GE_OFFER_PRICE_BUTTON_CHILD;
				break;
			case CONFIRM_OFFER:
			case CONFIRM_SELL:
				childId = GE_OFFER_CONFIRM_BUTTON_CHILD;
				break;
			default:
				return;
		}

		Widget targetWidget = offerContainer.getChild(childId);

		if (targetWidget != null && !targetWidget.isHidden())
		{
			Rectangle bounds = targetWidget.getBounds();
			if (bounds != null && bounds.width > 0)
			{
				// For quantity/price buttons, shrink the highlight to fit just the button area
				// These widgets include extra space above/below the actual button
				if (step == FlipAssistOverlay.FlipAssistStep.SET_QUANTITY ||
					step == FlipAssistOverlay.FlipAssistStep.SET_PRICE ||
					step == FlipAssistOverlay.FlipAssistStep.SET_SELL_PRICE)
				{
					int shrinkAmount = bounds.height / 3;
					bounds = new Rectangle(
						bounds.x,
						bounds.y + shrinkAmount / 2,
						bounds.width,
						bounds.height - shrinkAmount
					);
				}
				drawOrangeGlow(graphics, bounds);
			}
		}
	}

	/**
	 * Draw an animated orange glow around a widget bounds
	 */
	private void drawOrangeGlow(Graphics2D graphics, Rectangle bounds)
	{
		// Calculate pulse animation
		long elapsed = System.currentTimeMillis() % 1500;
		float pulseAlpha = (float) (0.5 + 0.5 * Math.sin(elapsed / 1500.0 * 2 * Math.PI));

		// Draw outer glow layers
		for (int i = 3; i >= 1; i--)
		{
			int alpha = (int) ((40 + 30 * pulseAlpha) / i);
			Color glowColor = new Color(
				COLOR_FLIP_ASSIST_GLOW.getRed(),
				COLOR_FLIP_ASSIST_GLOW.getGreen(),
				COLOR_FLIP_ASSIST_GLOW.getBlue(),
				alpha
			);
			graphics.setColor(glowColor);
			graphics.setStroke(new BasicStroke(i * 2.0f));
			graphics.drawRoundRect(
				bounds.x - i * 2,
				bounds.y - i * 2,
				bounds.width + i * 4,
				bounds.height + i * 4,
				4, 4
			);
		}

		// Draw inner border
		int borderAlpha = (int) (180 + 75 * pulseAlpha);
		Color borderColor = new Color(
			COLOR_FLIP_ASSIST_GLOW.getRed(),
			COLOR_FLIP_ASSIST_GLOW.getGreen(),
			COLOR_FLIP_ASSIST_GLOW.getBlue(),
			borderAlpha
		);
		graphics.setColor(borderColor);
		graphics.setStroke(new BasicStroke(2));
		graphics.drawRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, 4, 4);
	}

	/**
	 * Dimmed, non-pulsing amber border for a skipped-item reminder. Kept visually
	 * subordinate to the bright current-action glow so it reminds without competing
	 * with the slot the Flip Assist panel is actively prompting.
	 */
	private void drawDimReminderGlow(Graphics2D graphics, Rectangle bounds)
	{
		Stroke originalStroke = graphics.getStroke();
		Color reminderColor = new Color(
			COLOR_FLIP_ASSIST_GLOW.getRed(),
			COLOR_FLIP_ASSIST_GLOW.getGreen(),
			COLOR_FLIP_ASSIST_GLOW.getBlue(),
			90
		);
		graphics.setColor(reminderColor);
		graphics.setStroke(new BasicStroke(2));
		graphics.drawRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, 4, 4);
		graphics.setStroke(originalStroke);
	}
}

package com.flipsmart;

import com.flipsmart.recommend.ActionDecision;
import com.flipsmart.recommend.ActionStep;
import net.runelite.client.Notifier;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.BooleanSupplier;
import java.util.function.IntFunction;
import java.util.function.LongSupplier;

/**
 * Fires a RuneLite notification when a Grand Exchange offer needs the player's action,
 * so a player who is not watching the client does not miss it.
 *
 * Alert identity is deliberately coarser than {@link ActionDecision} equality. An
 * empty-slot buy carries the Flip Finder queue's current suggestion, which rotates on
 * every refresh — but what the player must do, "a slot is free", does not change when
 * the suggested item does, so PLACE_BUY is keyed item-agnostically.
 *
 * Enable/sound/desktop gating belongs to RuneLite: {@link Notifier#notify} no-ops when
 * the notification is disabled, and honours the player's global notification settings
 * unless they opt into overriding them.
 */
public class ActionAlertNotifier
{
	/** Minimum gap before the same alert key may fire again. */
	static final long COOLDOWN_MS = 60_000L;

	/** Housekeeping cap; expired entries are pruned lazily well before this. */
	private static final int MAX_ENTRIES = 64;

	private final Notifier notifier;
	private final FlipSmartConfig config;
	private final IntFunction<String> itemNames;
	private final BooleanSupplier clientFocused;
	private final LongSupplier clock;

	/** alert key -> wall-clock instant at which it may fire again. */
	private final Map<String, Long> cooldownUntilMillis = new ConcurrentHashMap<>();

	private volatile String lastAlertKey;

	public ActionAlertNotifier(Notifier notifier, FlipSmartConfig config, IntFunction<String> itemNames,
		BooleanSupplier clientFocused)
	{
		this(notifier, config, itemNames, clientFocused, System::currentTimeMillis);
	}

	/** Test seam: inject a deterministic clock. */
	ActionAlertNotifier(Notifier notifier, FlipSmartConfig config, IntFunction<String> itemNames,
		BooleanSupplier clientFocused, LongSupplier clock)
	{
		this.notifier = notifier;
		this.config = config;
		this.itemNames = itemNames;
		this.clientFocused = clientFocused;
		this.clock = clock;
	}

	/**
	 * Offer a decision for alerting. Safe to call on every resolve and every tick —
	 * repeats of an unchanged action are silent.
	 */
	@SuppressWarnings("PMD.NullAssignment")
	public void onDecision(ActionDecision decision)
	{
		String key = alertKey(decision);
		if (key == null)
		{
			lastAlertKey = null;
			return;
		}
		if (key.equals(lastAlertKey))
		{
			return;
		}
		// While the client is focused RuneLite discards the notification, so treating it
		// as delivered would strand the action: the player walks away and is never told.
		// Leave it unconsumed instead — the next tick re-offers it once they look away.
		if (clientFocused.getAsBoolean())
		{
			return;
		}
		lastAlertKey = key;
		if (isCoolingDown(key))
		{
			return;
		}
		mark(key);
		notifier.notify(config.actionAlert(), message(decision, itemNames));
	}

	/** The player-facing identity of an action, or null when there is nothing to do. */
	static String alertKey(ActionDecision decision)
	{
		if (decision == null || decision.getStep() == ActionStep.NONE)
		{
			return null;
		}
		switch (decision.getStep())
		{
			case PLACE_BUY:
				return "PLACE_BUY";
			case LIST:
				return "LIST:" + decision.getItemId();
			default:
				return decision.getStep() + ":" + decision.getItemId() + ":" + decision.getSlot();
		}
	}

	static String message(ActionDecision decision, IntFunction<String> itemNames)
	{
		switch (decision.getStep())
		{
			case PLACE_BUY:
				return "A Grand Exchange slot is free";
			case LIST:
				return "List " + itemNames.apply(decision.getItemId()) + " to sell";
			case CANCEL:
				return "Cancel your " + itemNames.apply(decision.getItemId()) + " offer";
			case REPRICE:
				return "Adjust the price of your " + itemNames.apply(decision.getItemId()) + " offer";
			case COLLECT:
				return "Collect your " + itemNames.apply(decision.getItemId());
			default:
				return "A Grand Exchange offer needs attention";
		}
	}

	private boolean isCoolingDown(String key)
	{
		Long until = cooldownUntilMillis.get(key);
		if (until == null)
		{
			return false;
		}
		if (clock.getAsLong() >= until)
		{
			cooldownUntilMillis.remove(key);
			return false;
		}
		return true;
	}

	private void mark(String key)
	{
		long now = clock.getAsLong();
		cooldownUntilMillis.put(key, now + COOLDOWN_MS);
		if (cooldownUntilMillis.size() > MAX_ENTRIES)
		{
			cooldownUntilMillis.entrySet().removeIf(entry -> now >= entry.getValue());
		}
	}
}

package com.flipsmart;

public final class OfferPoolClassifier
{
	static final int HIGH_VOL_THRESHOLD = 500_000;
	static final String HIGH_VOL = "high_vol";
	static final String MID_VOL = "mid_vol";

	private OfferPoolClassifier()
	{
	}

	public static String classify(Integer dailyVolume)
	{
		if (dailyVolume != null && dailyVolume >= HIGH_VOL_THRESHOLD)
		{
			return HIGH_VOL;
		}
		return MID_VOL;
	}
}

package com.flipsmart;

import com.flipsmart.api.dto.Dtos.HistoryBackfillEntry;
import com.flipsmart.domain.offer.OfferRecord;
import com.flipsmart.trading.OfferStore;
import com.flipsmart.util.GeTax;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;

/**
 * Reads the in-game GE History tab to recover actual fill prices for trades
 * completed while offline, then posts them to the API as is_history_backfill.
 * <p>
 * The read is triggered on multiple lifecycle points so it does not depend on
 * the user acting on a one-shot chat nag: on the History WidgetLoaded, which fires
 * on every open of the tab; when an unverified offline fill is registered while
 * the tab is already open; and by a throttled re-scan that retries until a read
 * recovers rows. All triggers only ever <em>read</em> the widget already on screen
 * — the plugin never opens or drives the interface for the player.
 */
@Slf4j
@Singleton
public class GEHistoryService
{
	// Row layout in the GE History list (child 3 of group 383): each entry
	// is anchored by a "Bought:" / "Sold:" header widget; the next item
	// sprite (carries itemId + itemQuantity natively) and the next text
	// containing "each" (the per-item price) within the following ~6
	// children belong to that header. We walk children rather than
	// fixed-stride to handle variable-width rows.
	private static final int GE_HISTORY_LIST_CHILD = 3;

	// Minimum gap between retries by the re-scan, in game ticks (~0.6s each), while it is
	// still waiting for a read that recovers rows. Explicit WidgetLoaded/offline-fill reads
	// are not throttled — only the re-scan honours this.
	private static final long PROACTIVE_RESCAN_INTERVAL_TICKS = 17;

	private final Client client;
	private final FlipSmartApiClient apiClient;
	private final PlayerSession session;
	private final ChatMessageManager chatMessageManager;
	private final OfferStore offerStore;

	private final Set<Integer> pendingOfflineFillItemIds = ConcurrentHashMap.newKeySet();
	private final Map<Integer, OfferRecord> recentlyPersistedOffers = new ConcurrentHashMap<>();
	private final AtomicInteger pendingHistoryReadTicks = new AtomicInteger(0);
	private volatile boolean historyReadThisSession = false;
	private volatile boolean chatPromptSent = false;
	@Setter
	private volatile Runnable onBackfillComplete;

	// Monotonic game-tick counter and the tick of the most recent read, used to
	// throttle the proactive re-scan. Only touched on the client thread.
	private volatile long tickCount;
	private volatile long lastReadTick = -PROACTIVE_RESCAN_INTERVAL_TICKS;

	@Inject
	public GEHistoryService(
		Client client,
		FlipSmartApiClient apiClient,
		PlayerSession session,
		ChatMessageManager chatMessageManager,
		OfferStore offerStore)
	{
		this.client = client;
		this.apiClient = apiClient;
		this.session = session;
		this.chatMessageManager = chatMessageManager;
		this.offerStore = offerStore;
	}

	public void onHistoryWidgetLoaded()
	{
		// WidgetLoaded fires when the interface is *created*, but list rows are
		// populated by clientscripts that run afterward. Defer two ticks so the
		// scripts have time to write the row widgets before we scan them.
		pendingHistoryReadTicks.set(2);
	}

	/** Called from FlipSmartPlugin.onGameTick. */
	public void onGameTick()
	{
		tickCount++;
		int prev = pendingHistoryReadTicks.get();
		if (prev > 0)
		{
			if (pendingHistoryReadTicks.decrementAndGet() == 0)
			{
				readHistoryNow();
			}
			return;
		}
		maybeProactiveRescan();
	}

	/**
	 * Retry trigger for a read that recovered nothing. WidgetLoaded fires when the interface is
	 * created, ahead of the clientscripts that populate the rows, so the deferred read can find an
	 * empty list; re-read on a throttled cadence until one parses.
	 * <p>
	 * It does NOT exist to catch fills landing while the tab is open: an offer only enters the
	 * History tab once collected, and collecting requires the main GE interface, which replaces
	 * the History tab. The tab's contents cannot change while it is visible, so once a read has
	 * succeeded there is nothing further to find until it is re-opened — which fires WidgetLoaded
	 * again. Gated on offline sync so we never latch {@code historyReadThisSession} before the
	 * reconciler has had a chance to register offline fills.
	 */
	private void maybeProactiveRescan()
	{
		if (!session.isOfflineSyncCompleted() || historyReadThisSession)
		{
			return;
		}
		if (tickCount - lastReadTick < PROACTIVE_RESCAN_INTERVAL_TICKS)
		{
			return;
		}
		if (isHistoryWidgetVisible())
		{
			readHistoryNow();
		}
	}

	private boolean isHistoryWidgetVisible()
	{
		Widget listWidget = client.getWidget(InterfaceID.GE_HISTORY, GE_HISTORY_LIST_CHILD);
		return listWidget != null && !listWidget.isHidden();
	}

	private void readHistoryNow()
	{
		// Throttle the next re-scan regardless of outcome, so an unreadable tab
		// cannot spin the proactive path every tick.
		lastReadTick = tickCount;

		Widget listWidget = client.getWidget(InterfaceID.GE_HISTORY, GE_HISTORY_LIST_CHILD);
		if (listWidget == null)
		{
			return;
		}

		List<GEHistoryEntry> entries = parseHistoryEntries(listWidget);
		if (entries.isEmpty())
		{
			return;
		}

		// Latch only once rows were actually recovered. Latching on entry — before the
		// widget and row checks below — meant a WidgetLoaded whose clientscripts had not
		// populated the list yet (or a tab closed within the two-tick defer) still counted
		// as "History has been read", after which registerOfflineFill silently discards
		// every subsequent offline fill for the rest of the session.
		historyReadThisSession = true;

		log.debug("Read {} GE history entries", entries.size());
		backfillOfflineFills(entries);
	}

	public void registerOfflineFill(int itemId)
	{
		if (!historyReadThisSession && pendingOfflineFillItemIds.add(itemId))
		{
			log.debug("Registered offline fill for itemId={} (pending count {})",
				itemId, pendingOfflineFillItemIds.size());
			if (isHistoryWidgetVisible())
			{
				// Tab is already open — scrape it directly instead of nagging.
				pendingHistoryReadTicks.set(2);
			}
			else
			{
				maybeSendChatPrompt();
			}
		}
	}

	private void maybeSendChatPrompt()
	{
		if (chatPromptSent)
		{
			return;
		}
		chatPromptSent = true;
		String msg = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT)
			.append("[FlipSmart] ")
			.append(ChatColorType.NORMAL)
			.append("Offline trades detected. Open the Grand Exchange and click the ")
			.append(ChatColorType.HIGHLIGHT)
			.append("History")
			.append(ChatColorType.NORMAL)
			.append(" tab to recover their actual fill prices.")
			.build();
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(msg)
			.build());
	}

	/**
	 * Snapshot of offers persisted at the previous session's logout — used for
	 * item-name resolution and offerId matching in the backfill payload. This
	 * does NOT prompt: merely having tracked offers last session is not missing
	 * data. The prompt is driven solely by genuinely-unverified offline fills
	 * registered via {@link #registerOfflineFill} (offers the reconciler found
	 * gone from their slot on login).
	 */
	public void setRecentlyPersistedOffers(List<OfferRecord> offers)
	{
		recentlyPersistedOffers.clear();
		if (offers != null)
		{
			for (OfferRecord o : offers)
			{
				recentlyPersistedOffers.put(o.getItemId(), o);
			}
		}
	}

	public boolean hasUnverifiedOfflineFills()
	{
		// Only prompt/flag when we haven't read History yet this session AND the
		// reconciler registered a genuinely-unverified offline fill. Persisted
		// offer state alone is not missing data — the live OfferStore pipeline
		// already records in-slot offline completions.
		return !historyReadThisSession && !pendingOfflineFillItemIds.isEmpty();
	}

	public void reset()
	{
		pendingOfflineFillItemIds.clear();
		recentlyPersistedOffers.clear();
		historyReadThisSession = false;
		pendingHistoryReadTicks.set(0);
		chatPromptSent = false;
		tickCount = 0;
		lastReadTick = -PROACTIVE_RESCAN_INTERVAL_TICKS;
	}

	private List<GEHistoryEntry> parseHistoryEntries(Widget listWidget)
	{
		Widget[] children = firstNonEmpty(listWidget.getDynamicChildren(), listWidget.getChildren(), listWidget.getNestedChildren());
		if (children == null)
		{
			return new ArrayList<>();
		}

		// Walk the children looking for "Bought:" / "Sold:" header markers.
		// Each header anchors a row; the item sprite (carries itemId+qty) and
		// the price text follow within the next ~6 widgets. This is robust to
		// variable per-row stride that breaks fixed-offset indexing.
		List<GEHistoryEntry> entries = new ArrayList<>();
		for (int i = 0; i < children.length; i++)
		{
			Boolean isBuy = headerToIsBuy(children[i]);
			if (isBuy != null)
			{
				tryParseRowAt(children, i, isBuy, entries);
			}
		}
		return entries;
	}

	/** Returns TRUE for "Bought:", FALSE for "Sold:", null otherwise. */
	private static Boolean headerToIsBuy(Widget w)
	{
		if (w == null) return null;
		String text = w.getText();
		if ("Bought:".equals(text)) return Boolean.TRUE;
		if ("Sold:".equals(text)) return Boolean.FALSE;
		return null;
	}

	private void tryParseRowAt(Widget[] children, int headerIdx, boolean isBuy, List<GEHistoryEntry> entries)
	{
		RowScan scan = scanRowFrom(children, headerIdx);
		if (scan.itemWidget == null)
		{
			log.debug("[GEHistory] dropped row at headerIdx={} isBuy={} — no itemWidget", headerIdx, isBuy);
			return;
		}
		int itemId = scan.itemWidget.getItemId();
		// RuneLite's Widget.getItemQuantity() returns 0 for single-item sprites
		// because the GE clientscript does not write a quantity badge when qty
		// would visually be "1". Default to 1 when we have a valid itemId but
		// no reported quantity — that is the only context this triggers.
		int rawQty = scan.itemWidget.getItemQuantity();
		int qty = (rawQty > 0) ? rawQty : (itemId > 0 ? 1 : 0);
		long price;
		String pricePath;
		if (scan.priceWidget != null)
		{
			price = parsePerItemPrice(scan.priceWidget);
			pricePath = "each";
		}
		else if (scan.coinsWidget != null && qty > 0)
		{
			// Single-quantity GE History rows omit the "= N each" line because
			// there's nothing to break out — the displayed total IS the per-item
			// price. Fall back to the "X,XXX coins" widget and divide by qty.
			// See Flip-Smart/flip-smart#650.
			long total = parseLeadingTotal(scan.coinsWidget);
			price = (total > 0) ? total / qty : -1;
			pricePath = "coins-fallback(total=" + total + ")";
		}
		else
		{
			log.debug("[GEHistory] dropped row at headerIdx={} isBuy={} itemId={} rawQty={} — "
					+ "no priceWidget AND (no coinsWidget OR qty<=0)",
				headerIdx, isBuy, itemId, rawQty);
			return;
		}
		if (qty > 0 && price > 0)
		{
			entries.add(new GEHistoryEntry(itemId, isBuy, qty, price));
			log.debug("[GEHistory] parsed row isBuy={} itemId={} qty={} price={} via {}",
				isBuy, itemId, qty, price, pricePath);
		}
		else
		{
			log.debug("[GEHistory] dropped row at headerIdx={} isBuy={} itemId={} qty={} price={} via {}",
				headerIdx, isBuy, itemId, qty, price, pricePath);
		}
	}

	/**
	 * Scan the children starting just after a header, capturing the first
	 * item-bearing widget and the first "X each" price text. Stops at the
	 * next header so we never bleed into the following row.
	 */
	private static RowScan scanRowFrom(Widget[] children, int headerIdx)
	{
		RowScan scan = new RowScan();
		int end = Math.min(children.length, headerIdx + 8);
		for (int j = headerIdx + 1; j < end; j++)
		{
			Widget w = children[j];
			if (w != null && !absorbWidget(w, scan))
			{
				break;
			}
		}
		return scan;
	}

	/** Returns false if the next-header marker is hit (caller should stop). */
	private static boolean absorbWidget(Widget w, RowScan scan)
	{
		String text = w.getText();
		if ("Bought:".equals(text) || "Sold:".equals(text))
		{
			return false;
		}
		if (scan.itemWidget == null && w.getItemId() > 0)
		{
			scan.itemWidget = w;
		}
		if (text != null)
		{
			if (scan.priceWidget == null && text.contains("each"))
			{
				scan.priceWidget = w;
			}
			else if (scan.coinsWidget == null && text.contains("coins"))
			{
				// Single-qty rows have a "X,XXX coins" widget but no "each" line.
				// Captured for the qty=1 fallback in tryParseRowAt.
				scan.coinsWidget = w;
			}
		}
		return true;
	}

	private static final class RowScan
	{
		Widget itemWidget;
		Widget priceWidget;
		Widget coinsWidget;
	}

	/** Price text is "<col=...>X coins</col><br>= Y each" — the per-item price is after the '='. */
	private static long parsePerItemPrice(Widget widget)
	{
		return (widget == null) ? -1 : parsePerItemPriceFromText(widget.getText());
	}

	/** String-level entry point for {@link #parsePerItemPrice}, package-private
	 *  so unit tests can exercise the parsing logic without mocking
	 *  {@link Widget}.
	 *  <p>
	 *  Strips HTML tags <em>before</em> seeking the '=' separator. If the seek
	 *  runs on the raw text first, the '=' inside {@code <col=ffb83f>} can win
	 *  the {@code lastIndexOf('=')} race (when no plain-text '=' exists in the
	 *  row), the substring starts mid-tag at {@code "=ffb83f>…"}, and
	 *  {@link #stripHtmlTags} can no longer strip the fragment because its
	 *  regex requires a leading '<'. The orphaned hex digits then leak into
	 *  {@link #parseDigits} and concatenate with the trailing quantity —
	 *  the {@code 83 × 10^n + qty} corruption pattern observed in production
	 *  (Flip-Smart/flip-smart#689). Tag-stripping first removes that whole
	 *  failure mode regardless of which widget shape RuneLite returns. */
	static long parsePerItemPriceFromText(String text)
	{
		if (text == null || text.isEmpty()) return -1;
		String cleaned = stripHtmlTags(text);
		int eqIdx = cleaned.lastIndexOf('=');
		String slice = (eqIdx >= 0) ? cleaned.substring(eqIdx) : cleaned;
		return parseDigits(slice);
	}

	/** Leading total from a "X,XXX coins[(gross - tax)]" widget, ignoring any
	 *  parenthesized tax breakdown so parseDigits doesn't concatenate them. */
	private static long parseLeadingTotal(Widget widget)
	{
		return (widget == null) ? -1 : parseLeadingTotalFromText(widget.getText());
	}

	/** String-level entry point for {@link #parseLeadingTotal}, package-private
	 *  for the same testing reason as {@link #parsePerItemPriceFromText}.
	 *  Same tag-strip-first discipline: today the raw widget text always wraps
	 *  the parenthesized tax breakdown inside the same {@code <col>} as the
	 *  total, so the {@code indexOf('(')} seek would produce the correct head
	 *  either way — but ordering matters as soon as RuneLite changes the row
	 *  shape, so we strip first defensively. */
	static long parseLeadingTotalFromText(String text)
	{
		if (text == null || text.isEmpty()) return -1;
		String cleaned = stripHtmlTags(text);
		int parenIdx = cleaned.indexOf('(');
		String head = (parenIdx >= 0) ? cleaned.substring(0, parenIdx) : cleaned;
		return parseDigits(head);
	}

	/** Strip HTML-like tags (e.g. {@code <col=ffb83f>}, {@code <br>}, {@code </col>})
	 *  before parsing digits, so hex characters inside color codes don't pollute
	 *  the result. parseDigits is digit-greedy and would otherwise concatenate
	 *  digits found inside attribute values like "ff<b>83</b>f" into the price. */
	private static String stripHtmlTags(String text)
	{
		return (text == null) ? "" : text.replaceAll("<[^>]*>", "");
	}

	/**
	 * Conservatively resolve a History row to a tracked OfferStore offerId so the
	 * backend can reconcile it per-offer. Matches on (itemId, isBuy, price) and
	 * returns the offerId ONLY when exactly one distinct offer matches — a wrong
	 * offerId is worse than none, so any ambiguity (or no match) returns null and
	 * the backend falls back to the item-level path.
	 */
	static Long matchOfferId(List<OfferRecord> candidates, int itemId, boolean isBuy, long pricePerItem)
	{
		Long found = null;
		for (OfferRecord o : candidates)
		{
			if (o.getItemId() == itemId && o.isBuy() == isBuy && priceMatches(o, pricePerItem))
			{
				if (found != null && found.longValue() != o.getOfferId())
				{
					return null;
				}
				found = o.getOfferId();
			}
		}
		return found;
	}

	/**
	 * History reports a sell at its net price while the offer holds the listed one, so comparing
	 * them directly never matches a taxed sell. Both forms are accepted; a row that fits two
	 * different offers still resolves to null via the ambiguity check above.
	 */
	private static boolean priceMatches(OfferRecord o, long historyPrice)
	{
		if (o.getPrice() == historyPrice)
		{
			return true;
		}
		return !o.isBuy() && o.getPrice() - GeTax.taxFor(o.getItemId(), o.getPrice()) == historyPrice;
	}

	private void backfillOfflineFills(List<GEHistoryEntry> entries)
	{
		if (!session.isOfflineSyncCompleted() || entries.isEmpty())
		{
			return;
		}
		Optional<String> rsnOpt = session.getRsnSafe();
		if (rsnOpt.isEmpty())
		{
			return;
		}
		String rsn = rsnOpt.get();

		// Resolve item names from live + persisted-offer state when available.
		// The backend tolerates null but resolves from prior transactions on
		// its side too; this just gives nicer logs.
		Map<Integer, String> nameByItem = new HashMap<>();
		for (OfferRecord o : offerStore.allRecords()) nameByItem.put(o.getItemId(), o.getItemName());
		for (OfferRecord o : recentlyPersistedOffers.values()) nameByItem.putIfAbsent(o.getItemId(), o.getItemName());

		// Candidate offers for offer_id linkage: live + recently-persisted.
		List<OfferRecord> candidates = new ArrayList<>(offerStore.allRecords());
		candidates.addAll(recentlyPersistedOffers.values());

		List<HistoryBackfillEntry> batch = new ArrayList<>(entries.size());
		for (GEHistoryEntry e : entries)
		{
			Long offerId = matchOfferId(candidates, e.getItemId(), e.isBuy(), e.getPricePerItem());
			batch.add(new HistoryBackfillEntry(
				e.getItemId(), nameByItem.get(e.getItemId()),
				e.isBuy(), e.getQuantity(), e.getPricePerItem(), offerId
			));
		}

		log.debug("Posting {} GE history rows for batch reconciliation", batch.size());
		apiClient.recordHistoryBackfillBatchAsync(rsn, batch)
			.whenComplete((v, ex) ->
			{
				if (ex != null)
				{
					log.warn("History backfill batch failed: {}", ex.getMessage());
					return;
				}
				Runnable cb = onBackfillComplete;
				if (cb != null)
				{
					try { cb.run(); }
					catch (Exception e) { log.debug("onBackfillComplete callback threw: {}", e.getMessage()); }
				}
			});
	}

	private static long parseDigits(String text)
	{
		if (text == null) return -1;
		String cleaned = text.replaceAll("\\D", "");
		if (cleaned.isEmpty()) return -1;
		try
		{
			return Long.parseLong(cleaned);
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}

	@SafeVarargs
	private static Widget[] firstNonEmpty(Widget[]... candidates)
	{
		for (Widget[] c : candidates)
		{
			if (c != null && c.length > 0) return c;
		}
		return null;
	}
}

package com.flipsmart.recommend;

import com.flipsmart.domain.flip.ActiveFlip;
import com.flipsmart.util.GeTax;
import lombok.extern.slf4j.Slf4j;

/**
 * Smart-sell pricing decisions for active flips. Stateless and free of any UI
 * dependency: every method takes the data it needs as primitives or domain
 * objects and returns a price (or a strategy decision) the panel renders.
 */
@Slf4j
public final class SmartSellPricer
{
	private static final int HIGH_VOLUME_THRESHOLD = 500_000;
	private static final int HIGH_VOLUME_TIME_MINUTES = 10;

	private static final int REGULAR_TIME_MINUTES = 20;

	private static final int HIGH_VALUE_THRESHOLD = 250_000_000;
	private static final int HIGH_VALUE_TIME_MINUTES = 30;

	private SmartSellPricer()
	{
		// Utility class - prevent instantiation
	}

	/**
	 * Calculate the sell price threshold time for an active flip.
	 * Returns the number of minutes after which we should switch from
	 * profit-first to loss-minimizing strategy.
	 *
	 * Rules:
	 * - High volume items (&gt;500k daily): 10 minutes
	 * - High value items (&gt;250M buy price): 30 minutes
	 * - Regular items: 20 minutes
	 */
	public static int getSellPriceThresholdMinutes(ActiveFlip flip, Integer dailyVolume)
	{
		if (flip.getAverageBuyPrice() >= HIGH_VALUE_THRESHOLD)
		{
			return HIGH_VALUE_TIME_MINUTES;
		}

		if (dailyVolume != null && dailyVolume >= HIGH_VOLUME_THRESHOLD)
		{
			return HIGH_VOLUME_TIME_MINUTES;
		}

		return REGULAR_TIME_MINUTES;
	}

	/**
	 * Calculate the minimum profitable sell price for an active flip.
	 * This is the price that would result in zero profit after tax.
	 * Formula: minSellPrice = min(buyPrice / (1 - taxRate), buyPrice + tax cap)
	 * Adding 1gp ensures a small profit.
	 *
	 * @return {@code 0} when {@code buyPrice} is non-positive. A missing cost basis is not a
	 *         free position: it has no computable breakeven, and reading it as one yields 1gp.
	 */
	public static long calculateMinProfitableSellPrice(long buyPrice)
	{
		if (buyPrice <= 0)
		{
			return 0;
		}
		return Math.min((long) Math.ceil(buyPrice / 0.98), buyPrice + GeTax.GE_TAX_CAP) + 1;
	}

	/**
	 * Resolve the sell price to show, or {@code null} when no source knows one.
	 *
	 * <p>Returning null is deliberate: callers must drop the prompt rather than surface a
	 * fabricated number. Every price this returns traces to the player's own basis, the
	 * original recommendation, or live market data.</p>
	 */
	public static Long calculateSmartSellPrice(ActiveFlip flip, Long currentMarketPrice)
	{
		long buyPrice = flip.getAverageBuyPrice();
		if (buyPrice <= 0)
		{
			return priceWithoutBasis(flip, currentMarketPrice);
		}
		return priceFromBasis(flip, currentMarketPrice, calculateMinProfitableSellPrice(buyPrice));
	}

	private static Long priceWithoutBasis(ActiveFlip flip, Long currentMarketPrice)
	{
		Long target = flip.getRecommendedSellPrice();
		if (isPositive(target))
		{
			return target;
		}
		log.warn("No cost basis for item {} ({}); falling back to market",
			flip.getItemId(), flip.getItemName());
		return isPositive(currentMarketPrice) ? currentMarketPrice : null;
	}

	private static Long priceFromBasis(ActiveFlip flip, Long currentMarketPrice, long minProfitablePrice)
	{
		Long recommended = flip.getRecommendedSellPrice();
		if (atLeast(recommended, minProfitablePrice))
		{
			return recommended;
		}
		if (atLeast(currentMarketPrice, minProfitablePrice))
		{
			return minProfitablePrice;
		}
		return isPositive(recommended) ? recommended : minProfitablePrice;
	}

	private static boolean isPositive(Long value)
	{
		return value != null && value > 0;
	}

	private static boolean atLeast(Long value, long threshold)
	{
		return value != null && value >= threshold;
	}
}

package com.flipsmart.recommend;

import com.flipsmart.domain.offer.OfferRecord;

import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Predicate;

/**
 * Owns the stale-offer queue and its companion price/net maps plus the
 * already-prompted set. Guides the user through stale offers one at a time.
 *
 * Not thread-safe; guarded by AutoRecommendService's monitor. Every method is
 * only ever called while AutoRecommendService holds its {@code this} monitor.
 * The concurrent collection types are retained from the original fields for
 * behavioural parity, not because this class provides synchronization.
 */
public final class StaleOfferQueue
{
	private final List<OfferRecord> offers = new CopyOnWriteArrayList<>();
	private final Map<Integer, Long> staleResellPrices = new ConcurrentHashMap<>();
	// Advisor-only: net profit/loss estimate to show alongside a re-sell prompt. Kept in
	// sync with staleResellPrices at both put-sites, so it's never read with a stale price.
	private final Map<Integer, Long> staleResellNet = new ConcurrentHashMap<>();
	// Items that have already been flagged as stale/uncompetitive — prevents repeated prompts.
	// Cleared when the offer is cancelled, filled, or a new offer is placed for the item.
	private final Set<Integer> promptedStaleItems = ConcurrentHashMap.newKeySet();

	public boolean isEmpty()
	{
		return offers.isEmpty();
	}

	public int size()
	{
		return offers.size();
	}

	public OfferRecord head()
	{
		return offers.isEmpty() ? null : offers.get(0);
	}

	public List<OfferRecord> snapshot() {
		return java.util.Collections.unmodifiableList(new java.util.ArrayList<>(offers));
	}

	public boolean headIsItem(int itemId)
	{
		return !offers.isEmpty() && offers.get(0).getItemId() == itemId;
	}

	public OfferRecord findByItemId(int itemId)
	{
		for (OfferRecord o : offers)
		{
			if (o.getItemId() == itemId)
			{
				return o;
			}
		}
		return null;
	}

	public Long getResellPrice(int itemId)
	{
		return staleResellPrices.get(itemId);
	}

	public void putResellPrice(int itemId, long price)
	{
		staleResellPrices.put(itemId, price);
	}

	public Long getResellNet(int itemId)
	{
		return staleResellNet.get(itemId);
	}

	public void putResellNet(int itemId, long net)
	{
		staleResellNet.put(itemId, net);
	}

	public void removeResellNet(int itemId)
	{
		staleResellNet.remove(itemId);
	}

	public void removePrompted(int itemId)
	{
		promptedStaleItems.remove(itemId);
	}

	/**
	 * Forget an item entirely: drop it from the queue and its resell price.
	 * Used by buy/cancel/collect handlers when the offer leaves the GE.
	 * Does not touch the prompted set (callers manage that separately, matching
	 * the original ordering of side effects).
	 */
	public void removeOffer(int itemId)
	{
		offers.removeIf(o -> o.getItemId() == itemId);
		staleResellPrices.remove(itemId);
		staleResellNet.remove(itemId);
	}

	/** Remove the head offer and clear its resell price; returns the removed offer. */
	public OfferRecord removeHead()
	{
		OfferRecord skipped = offers.remove(0);
		staleResellPrices.remove(skipped.getItemId());
		staleResellNet.remove(skipped.getItemId());
		return skipped;
	}

	/** Outcome of {@link #addIfAbsent(OfferRecord)}. */
	public enum AddResult
	{
		/** An entry for this item already existed — nothing changed. */
		ALREADY_PRESENT,
		/** The offer was appended to a previously non-empty offers. */
		ADDED,
		/** The offer was added and the queue was empty before — surface it now. */
		ADDED_WAS_EMPTY
	}

	/**
	 * Add an offer to the queue if no entry for its item already exists, marking
	 * it prompted. The return value lets the caller distinguish the dedup no-op
	 * from a genuine add and decide whether to surface the first prompt.
	 */
	public AddResult addIfAbsent(OfferRecord offer)
	{
		for (OfferRecord existing : offers)
		{
			if (existing.getItemId() == offer.getItemId())
			{
				return AddResult.ALREADY_PRESENT;
			}
		}
		boolean wasEmpty = offers.isEmpty();
		offers.add(offer);
		promptedStaleItems.add(offer.getItemId());
		return wasEmpty ? AddResult.ADDED_WAS_EMPTY : AddResult.ADDED;
	}

	/**
	 * Drop every queued offer for which {@code shouldRemove} returns true,
	 * clearing the matching resell price for each removed entry. The predicate
	 * is supplied by the coordinator because relevance depends on live session
	 * and competitiveness state outside this class.
	 */
	public void pruneIrrelevant(Predicate<OfferRecord> shouldRemove)
	{
		offers.removeIf(o ->
		{
			if (shouldRemove.test(o))
			{
				staleResellPrices.remove(o.getItemId());
				staleResellNet.remove(o.getItemId());
				return true;
			}
			return false;
		});
	}

	/** Clear all stale-queue state. Used by stop(). */
	public void clear()
	{
		promptedStaleItems.clear();
		offers.clear();
		staleResellPrices.clear();
		staleResellNet.clear();
	}
}

package com.flipsmart.recommend;

public enum ActionStep {
    PLACE_BUY, COLLECT, LIST, CANCEL, REPRICE, NONE
}

package com.flipsmart.recommend;

import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Owns the buy/sell adjustment-timer state: per-item buy deadlines, sell
 * adjustment states, and the buy-price cost-basis map.
 *
 * Not thread-safe; guarded by AutoRecommendService's monitor. Every method is
 * only ever called while AutoRecommendService holds its {@code this} monitor,
 * so this class introduces no locks of its own. The API delegation and response
 * handling stay in the coordinator (they touch session, config, and callbacks);
 * this class holds the state and the bounded timer bookkeeping.
 */
public final class AdjustmentService
{
	/**
	 * Tracks state for a pending sell-side adjustment timer.
	 */
	public static final class SellAdjustmentState
	{
		public final int itemId;
		public final String itemName;
		public final long averageBuyPrice;
		public long deadline;
		public int adjustmentCount;

		public SellAdjustmentState(int itemId, String itemName, long averageBuyPrice, long deadline)
		{
			this.itemId = itemId;
			this.itemName = itemName;
			this.averageBuyPrice = averageBuyPrice;
			this.deadline = deadline;
			this.adjustmentCount = 0;
		}
	}

	// Buy adjustment timer deadlines: itemId → System.currentTimeMillis() when timer expires
	private final Map<Integer, Long> adjustmentDeadlines = new ConcurrentHashMap<>();

	// Sell adjustment tracking
	private final Map<Integer, SellAdjustmentState> sellAdjustmentStates = new ConcurrentHashMap<>();

	// Buy prices stored when buy orders are placed — used as cost basis for sell adjustments
	private final Map<Integer, Long> buyPrices = new ConcurrentHashMap<>();

	// =====================
	// Buy deadlines
	// =====================

	public boolean hasBuyDeadlines()
	{
		return !adjustmentDeadlines.isEmpty();
	}

	public int buyDeadlineCount()
	{
		return adjustmentDeadlines.size();
	}

	public boolean hasBuyDeadline(int itemId)
	{
		return adjustmentDeadlines.containsKey(itemId);
	}

	public void putBuyDeadline(int itemId, long deadline)
	{
		adjustmentDeadlines.put(itemId, deadline);
	}

	/** Remove a buy deadline; returns true if one was present. */
	public boolean removeBuyDeadline(int itemId)
	{
		return adjustmentDeadlines.remove(itemId) != null;
	}

	public Iterator<Map.Entry<Integer, Long>> buyDeadlineIterator()
	{
		return adjustmentDeadlines.entrySet().iterator();
	}

	// =====================
	// Sell adjustment states
	// =====================

	public boolean hasSellStates()
	{
		return !sellAdjustmentStates.isEmpty();
	}

	public boolean hasSellState(int itemId)
	{
		return sellAdjustmentStates.containsKey(itemId);
	}

	public SellAdjustmentState getSellState(int itemId)
	{
		return sellAdjustmentStates.get(itemId);
	}

	public void putSellState(int itemId, SellAdjustmentState state)
	{
		sellAdjustmentStates.put(itemId, state);
	}

	/** Remove a sell state; returns true if one was present. */
	public boolean removeSellState(int itemId)
	{
		return sellAdjustmentStates.remove(itemId) != null;
	}

	public Iterator<Map.Entry<Integer, SellAdjustmentState>> sellStateIterator()
	{
		return sellAdjustmentStates.entrySet().iterator();
	}

	// =====================
	// Buy prices (cost basis)
	// =====================

	public void putBuyPrice(int itemId, long price)
	{
		buyPrices.put(itemId, price);
	}

	public Long getBuyPrice(int itemId)
	{
		return buyPrices.get(itemId);
	}

	public Long getBuyPriceOrDefault(int itemId, long fallback)
