import java.util.Objects;

public final class ActionDecision {

    public static final ActionDecision IDLE =
        new ActionDecision(ActionKind.IDLE, ActionStep.NONE, -1, -1, 0L);

    private final ActionKind kind;
    private final ActionStep step;
    private final int itemId;
    private final int slot;
    private final long detectedAtMillis;

    public ActionDecision(ActionKind kind, ActionStep step, int itemId, int slot, long detectedAtMillis) {
        this.kind = kind;
        this.step = step;
        this.itemId = itemId;
        this.slot = slot;
        this.detectedAtMillis = detectedAtMillis;
    }

    public ActionKind getKind() { return kind; }
    public ActionStep getStep() { return step; }
    public int getItemId() { return itemId; }
    public int getSlot() { return slot; }
    public long getDetectedAtMillis() { return detectedAtMillis; }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof ActionDecision)) return false;
        ActionDecision that = (ActionDecision) o;
        return itemId == that.itemId && slot == that.slot
            && kind == that.kind && step == that.step;
    }

    @Override
    public int hashCode() {
        return Objects.hash(kind, step, itemId, slot);
    }

    @Override
    public String toString() {
        return "ActionDecision{" + kind + "/" + step + " item=" + itemId
            + " slot=" + slot + " detectedAt=" + detectedAtMillis + '}';
    }
}

package com.flipsmart.recommend;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.LongSupplier;

/**
 * Tracks a short per-item "leave me alone" window after a Flip Assist skip.
 *
 * When the player skips a recommendation or an action in auto-mode, that item is
 * held out of auto-surfacing for {@link #COOLDOWN_MS} so it does not immediately
 * re-appear on the next GE event, game tick, or Flip Finder refresh. Suppression is
 * intentionally limited to auto-surfacing — the passive orange highlight and a manual
 * GE offer-screen pull-up are unaffected.
 *
 * The window survives Flip Finder refreshes (the map is never touched by a refresh)
 * and is cleared only by natural expiry or an auto-mode toggle off-and-on via
 * {@link #clearAll()}. The clock is injectable so the cooldown can be unit-tested
 * without wall-clock sleeps.
 */
public class SkipCooldownTracker
{
	/** How long a skipped item stays out of auto-surfacing (5 minutes). */
	public static final long COOLDOWN_MS = 5 * 60 * 1000L;

	/** Housekeeping cap; expired entries are pruned lazily well before this. */
	private static final int MAX_ENTRIES = 500;

	/** itemId -> wall-clock instant at which the cooldown expires. */
	private final Map<Integer, Long> cooldownUntilMillis = new ConcurrentHashMap<>();

	private final LongSupplier clock;

	public SkipCooldownTracker()
	{
		this(System::currentTimeMillis);
	}

	/** Test seam: inject a deterministic clock. */
	SkipCooldownTracker(LongSupplier clock)
	{
		this.clock = clock;
	}

	/** Start (or restart) the cooldown window for an item. */
	public void skip(int itemId)
	{
		long now = clock.getAsLong();
		cooldownUntilMillis.put(itemId, now + COOLDOWN_MS);
		if (cooldownUntilMillis.size() > MAX_ENTRIES)
		{
			pruneExpired();
		}
	}

	/** True while the item is inside its skip window. Expires lazily on read. */
	public boolean isCoolingDown(int itemId)
	{
		Long until = cooldownUntilMillis.get(itemId);
		if (until == null)
		{
			return false;
		}
		if (clock.getAsLong() >= until)
		{
			cooldownUntilMillis.remove(itemId);
			return false;
		}
		return true;
	}

	/** Drop the cooldown for a single item — used when the player acts on it. */
	public void clear(int itemId)
	{
		cooldownUntilMillis.remove(itemId);
	}

	/** Drop every cooldown — used when auto-mode is toggled off and back on. */
	public void clearAll()
	{
		cooldownUntilMillis.clear();
	}

	/** Remove entries whose window has elapsed. */
	public void pruneExpired()
	{
		long now = clock.getAsLong();
		cooldownUntilMillis.entrySet().removeIf(entry -> now >= entry.getValue());
	}
}

package com.flipsmart.recommend;

import com.flipsmart.domain.offer.OfferRecord;
import com.flipsmart.domain.offer.OfferState;
import java.util.ArrayList;
import java.util.List;

public final class ActionResolver {

    public ActionDecision resolve(ResolverInput in) {
        List<ActionDecision> candidates = new ArrayList<>();

        for (OfferRecord r : in.getCompletedAwaitingCollection()) {
            long ts = r.getEffectiveLastActivityAtMillis();
            int slot = slotOf(r);
            if (!r.isBuy()) {
                candidates.add(new ActionDecision(ActionKind.S5, ActionStep.COLLECT, r.getItemId(), slot, ts));
            } else if (r.getState() == OfferState.CANCELLED_PARTIAL) {
                candidates.add(new ActionDecision(ActionKind.S1, ActionStep.COLLECT, r.getItemId(), slot, ts));
            } else {
                candidates.add(new ActionDecision(ActionKind.S3, ActionStep.COLLECT, r.getItemId(), slot, ts));
            }
        }

        boolean slotFree = in.getFilledSlotCount() < in.getSlotLimit();
        for (CollectedItem c : in.getCollectedAwaitingList()) {
            if (!c.hasSellPrice()) {
                continue;
            }
            if (!slotFree) {
                break;
            }
            // A collected item that is meant to be sold takes priority over placing a
            // new buy: the free slot should list what we already own rather than be
            // consumed by a new buy that leaves the held item with nowhere to sell.
            // Applies to both preemptive (partial-cancel) and normally-completed collects.
            candidates.add(new ActionDecision(ActionKind.SELL_WAITING, ActionStep.LIST,
                c.getItemId(), -1, c.getDetectedAtMillis()));
        }

        for (OfferRecord r : in.getStaleOffers()) {
            long ts = r.getEffectiveLastActivityAtMillis();
            int slot = slotOf(r);
            if (!r.isBuy()) {
                candidates.add(new ActionDecision(ActionKind.S4, ActionStep.REPRICE, r.getItemId(), slot, ts));
            } else if (r.getFilledQuantity() > 0) {
                candidates.add(new ActionDecision(ActionKind.S1, ActionStep.CANCEL, r.getItemId(), slot, ts));
            } else {
                candidates.add(new ActionDecision(ActionKind.S6, ActionStep.CANCEL, r.getItemId(), slot, ts));
            }
        }

        // Suppress a new buy while a just-collected item is awaiting its sell price: the free
        // slot must be held for the pending sell, not spent on a fresh purchase that would
        // strand the item we already own. Bounded by a grace window upstream so a permanently
        // unresolved price can't wedge trading.
        if (in.getFilledSlotCount() < in.getSlotLimit() && in.hasSurfaceableBuy()
            && !in.isBlockBuyForPendingSell() && !in.isBuysSuppressed()
            && !in.isFlipFinderCapReached()) {
            candidates.add(new ActionDecision(ActionKind.S2, ActionStep.PLACE_BUY,
                in.getSurfaceableBuyItemId(), -1, in.getNowMillis()));
        }

        ActionDecision best = null;
        for (ActionDecision c : candidates) {
            if (best == null || beats(c, best)) {
                best = c;
            }
        }
        return best == null ? ActionDecision.IDLE : best;
    }

    private static int slotOf(OfferRecord r) {
        Integer slot = r.getSlot();
        return slot == null ? -1 : slot;
    }

    private static boolean beats(ActionDecision a, ActionDecision b) {
        int byTier = Integer.compare(a.getKind().ordinal(), b.getKind().ordinal());
        if (byTier != 0) {
            return byTier < 0;
        }
        int byTime = Long.compare(a.getDetectedAtMillis(), b.getDetectedAtMillis());
        if (byTime != 0) {
            return byTime < 0;
        }
        return Integer.compare(slotKey(a), slotKey(b)) < 0;
    }

    private static int slotKey(ActionDecision d) {
        return d.getSlot() < 0 ? Integer.MAX_VALUE : d.getSlot();
    }
}

