public final class ResolverInput {

    private final int slotLimit;
    private final int filledSlotCount;
    private final boolean hasSurfaceableBuy;
    private final int surfaceableBuyItemId;
    private final long nowMillis;
    private final boolean blockBuyForPendingSell;
    private final int pendingSellItemId;
    private final boolean buysSuppressed;
    private final boolean flipFinderCapReached;
    private final List<OfferRecord> completedAwaitingCollection;
    private final List<OfferRecord> staleOffers;
    private final List<CollectedItem> collectedAwaitingList;

    private ResolverInput(Builder b) {
        this.slotLimit = b.slotLimit;
        this.filledSlotCount = b.filledSlotCount;
        this.hasSurfaceableBuy = b.hasSurfaceableBuy;
        this.surfaceableBuyItemId = b.surfaceableBuyItemId;
        this.nowMillis = b.nowMillis;
        this.blockBuyForPendingSell = b.blockBuy;
        this.pendingSellItemId = b.pendingSellItemId;
        this.buysSuppressed = b.buysSuppressed;
        this.flipFinderCapReached = b.flipFinderCapReached;
        this.completedAwaitingCollection =
            Collections.unmodifiableList(new ArrayList<>(b.completedAwaitingCollection));
        this.staleOffers =
            Collections.unmodifiableList(new ArrayList<>(b.staleOffers));
        this.collectedAwaitingList =
            Collections.unmodifiableList(new ArrayList<>(b.collectedAwaitingList));
    }

    public int getSlotLimit() { return slotLimit; }
    public int getFilledSlotCount() { return filledSlotCount; }
    public boolean hasSurfaceableBuy() { return hasSurfaceableBuy; }
    public int getSurfaceableBuyItemId() { return surfaceableBuyItemId; }
    public long getNowMillis() { return nowMillis; }
    /**
     * True when a just-collected item is awaiting a sell price that has not resolved yet
     * (e.g. a transient wiki-price timeout) and is still within its grace window. While set,
     * the resolver suppresses a new S2 buy so the free slot is held for the pending sell
     * rather than spent on a fresh purchase.
     */
    public boolean isBlockBuyForPendingSell() { return blockBuyForPendingSell; }
    public int getPendingSellItemId() { return pendingSellItemId; }
    /**
     * True while Exit Trades sell-only mode is active. Suppresses new S2 buys entirely so the
     * resolver falls through to the next collect/sell action instead of stalling on a buy.
     */
    public boolean isBuysSuppressed() { return buysSuppressed; }
    /**
     * True when a free-tier user has reached their Flip Finder item cap. Suppresses new S2
     * buys only — collecting, repricing, and listing collected sells stay available, so an
     * at-cap free user can always finish (sell) their in-flight flips. Manual listings never
     * set this (they are excluded from the count upstream).
     */
    public boolean isFlipFinderCapReached() { return flipFinderCapReached; }
    public List<OfferRecord> getCompletedAwaitingCollection() { return completedAwaitingCollection; }
    public List<OfferRecord> getStaleOffers() { return staleOffers; }
    public List<CollectedItem> getCollectedAwaitingList() { return collectedAwaitingList; }

    public static Builder builder() { return new Builder(); }

    public static final class Builder {
        private int slotLimit;
        private int filledSlotCount;
        private boolean hasSurfaceableBuy;
        private int surfaceableBuyItemId = -1;
        private long nowMillis;
        private boolean blockBuy;
        private int pendingSellItemId = -1;
        private boolean buysSuppressed;
        private boolean flipFinderCapReached;
        private List<OfferRecord> completedAwaitingCollection = new ArrayList<>();
        private List<OfferRecord> staleOffers = new ArrayList<>();
        private List<CollectedItem> collectedAwaitingList = new ArrayList<>();

        public Builder slotLimit(int v) { this.slotLimit = v; return this; }
        public Builder filledSlotCount(int v) { this.filledSlotCount = v; return this; }
        public Builder surfaceableBuy(boolean has, int itemId) {
            this.hasSurfaceableBuy = has; this.surfaceableBuyItemId = itemId; return this;
        }
        public Builder nowMillis(long v) { this.nowMillis = v; return this; }
        public Builder blockBuyForPendingSell(boolean block, int itemId) {
            this.blockBuy = block; this.pendingSellItemId = itemId; return this;
        }
        public Builder buysSuppressed(boolean v) { this.buysSuppressed = v; return this; }
        public Builder flipFinderCapReached(boolean v) { this.flipFinderCapReached = v; return this; }
        public Builder completedAwaitingCollection(List<OfferRecord> v) {
            this.completedAwaitingCollection = v; return this;
        }
        public Builder staleOffers(List<OfferRecord> v) { this.staleOffers = v; return this; }
        public Builder collectedAwaitingList(List<CollectedItem> v) {
            this.collectedAwaitingList = v; return this;
        }
        public ResolverInput build() { return new ResolverInput(this); }
    }
}

package com.flipsmart.recommend;

/**
 * Sell pricing for a manual (Auto Mode off) exit, resolved entirely from local state.
 *
 * <p>The backend active-flips list is trimmed to the subscription's display slots, so a
 * held position can be missing from it while the item sits in the player's inventory.
 * A display cap must never stop someone selling what they already own, so the price is
 * sourced locally: the panel's shown price, then the session's stored recommendation,
 * then the offer store's buy basis.</p>
 */
public final class ManualSellFocus
{
	private ManualSellFocus()
	{
	}

	/**
	 * Best locally-known sell price, or null when nothing can price the exit.
	 *
	 * @param panelPrice              price the Active Flips card is showing, if any
	 * @param sessionRecommendedPrice recommendation cached for this item, if any
	 * @param averageBuyPrice         cost basis from the offer store; 0 when unknown
	 */
	public static Long resolveSellPrice(Long panelPrice, Long sessionRecommendedPrice,
										   long averageBuyPrice)
	{
		if (panelPrice != null && panelPrice > 0)
		{
			return panelPrice;
		}
		if (sessionRecommendedPrice != null && sessionRecommendedPrice > 0)
		{
			return sessionRecommendedPrice;
		}
		if (averageBuyPrice > 0)
		{
			return SmartSellPricer.calculateMinProfitableSellPrice(averageBuyPrice);
		}
		return null;
	}
}

package com.flipsmart.recommend;

import com.flipsmart.domain.flip.FlipRecommendation;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.ToLongFunction;
import lombok.Getter;
import lombok.Setter;

/**
 * Owns the auto-recommend buy queue: the ordered recommendation list, the
 * monotonic cursor, cached item names, the offer-screen lock, and the
 * last-refresh timestamp.
 *
 * Not thread-safe; guarded by AutoRecommendService's monitor. Every method is
 * only ever called while AutoRecommendService holds its {@code this} monitor,
 * so this class deliberately introduces no locks of its own.
 */
public final class RecommendationQueue
{
	private final List<FlipRecommendation> recommendations = new ArrayList<>();
	// Cached item names from recommendations - survives queue refreshes
	private final Map<Integer, String> itemNames = new ConcurrentHashMap<>();
	@Getter @Setter
	private int currentIndex;

	// Offer-screen lock. While set, the coordinator drops focus changes
	// for any item other than this one. null = unlocked.
	@Getter @Setter
	private volatile Integer lockedItemId;

	// Timestamp of last queue refresh for staleness checks
	@Getter @Setter
	private volatile long lastQueueRefreshMillis;

	public int size()
	{
		return recommendations.size();
	}

	public boolean isEmpty()
	{
		return recommendations.isEmpty();
	}

	public FlipRecommendation get(int index)
	{
		return recommendations.get(index);
	}

	public List<FlipRecommendation> snapshot()
	{
		return new ArrayList<>(recommendations);
	}

	/** Unmodifiable view of the underlying list for scan helpers; reflects live reads. */
	public List<FlipRecommendation> view()
	{
		return Collections.unmodifiableList(recommendations);
	}

	public void clear()
	{
		recommendations.clear();
		currentIndex = 0;
	}

	public void clearAll()
	{
		recommendations.clear();
		itemNames.clear();
		currentIndex = 0;
	}

	public void putItemName(int itemId, String itemName)
	{
		// itemNames is a ConcurrentHashMap; a null name is simply not cached.
		if (itemName != null)
		{
			itemNames.put(itemId, itemName);
		}
	}

	public String getItemName(int itemId, String fallback)
	{
		return itemNames.getOrDefault(itemId, fallback);
	}

	/**
	 * Replace the queue contents with the given recommendations and reset the
	 * cursor to the front.
	 */
	public void replace(List<FlipRecommendation> newRecommendations)
	{
		// Copy first: the argument may alias the live backing list (e.g. view()), and
		// clear() would empty it before it could be re-added.
		List<FlipRecommendation> copy = new ArrayList<>(newRecommendations);
		recommendations.clear();
		recommendations.addAll(copy);
		currentIndex = 0;
	}

	/**
	 * Add every recommendation whose item id is not in {@code activeItemIds},
	 * caching all item names. Used by start() — does not reset the cursor.
	 */
	public void addFilteredByActive(List<FlipRecommendation> incoming, Set<Integer> activeItemIds)
	{
		for (FlipRecommendation rec : incoming)
		{
			if (!activeItemIds.contains(rec.getItemId()))
			{
				recommendations.add(rec);
			}
			if (rec.getItemName() != null)
			{
				itemNames.put(rec.getItemId(), rec.getItemName());
			}
		}
	}

	/**
	 * Append recommendations without touching the cursor. Used by the offline-sync
	 * restore path, which clears, re-populates, then sets a specific cursor — unlike
	 * {@link #replace(List)}, which resets the cursor to the front.
	 */
	public void addAll(List<FlipRecommendation> toAdd)
	{
		recommendations.addAll(toAdd);
	}

	/** Sort the queue by volume per hour ascending (slowest-filling items first). */
	public void sortByVolumeAscending()
	{
		recommendations.sort(Comparator.comparingDouble(FlipRecommendation::getVolumePerHour));
	}

	public FlipRecommendation getCurrentRecommendation()
	{
		if (currentIndex >= 0 && currentIndex < recommendations.size())
		{
			return recommendations.get(currentIndex);
		}
		return null;
	}

	/** Find a recommendation matching the given item ID from the queue. */
	public FlipRecommendation findRecommendationForItem(int itemId)
	{
		for (FlipRecommendation rec : recommendations)
		{
			if (rec.getItemId() == itemId)
			{
				return rec;
			}
		}
		return null;
	}

	public boolean cursorBeyondEnd()
	{
		return currentIndex >= recommendations.size();
	}

	public boolean cursorWithinBounds()
	{
		return currentIndex < recommendations.size();
	}

	// =====================
	// Offer-screen lock
	// =====================


	// =====================
	// Refresh timestamp
	// =====================



	// =====================
	// Cursor advancement
	// =====================

	/**
	 * Advance {@code currentIndex} past any item that is currently on the GE or
	 * below the minimum adjusted profit, stopping at the first surfaceable buy
	 * or running off the end. Mirrors the skip-loop in advanceToNext().
	 *
	 * @param activeItemIds items currently live on the GE
	 * @param profitFn      adjusted-profit calculator for a recommendation
	 * @param minProfit     minimum acceptable adjusted profit
	 */
	public void skipToNextSurfaceable(
		Set<Integer> activeItemIds,
		ToLongFunction<FlipRecommendation> profitFn,
		int minProfit)
	{
		skipToNextSurfaceable(activeItemIds, profitFn, minProfit, id -> false);
	}

	/**
	 * As above, but also skips items inside their post-skip cooldown so the cursor never
	 * lands on a recently-skipped item (AC2).
	 */
	public void skipToNextSurfaceable(
		Set<Integer> activeItemIds,
		ToLongFunction<FlipRecommendation> profitFn,
		int minProfit,
		java.util.function.IntPredicate isCoolingDown)
	{
		currentIndex++;
		while (currentIndex < recommendations.size())
		{
			FlipRecommendation next = recommendations.get(currentIndex);
			if (!activeItemIds.contains(next.getItemId())
				&& !isCoolingDown.test(next.getItemId())
				&& profitFn.applyAsLong(next) >= minProfit)
			{
				break;
			}
			currentIndex++;
		}
	}
}

package com.flipsmart.recommend;

public enum ActionKind {
    // Priority is by ordinal (lowest wins). SELL_WAITING and S3 both sit above S2 so
    // the collect->sell pipeline for an item we already own is finished before capital
    // is deployed into a new buy: SELL_WAITING lists an already-collected item, and S3
    // collects a completed buy (which then becomes a SELL_WAITING) — both ahead of the
    // S2 new buy.
    S1, SELL_WAITING, S3, S2, S4, S5, S6, IDLE
}

package com.flipsmart;

/**
 * Shared constants for adjustment timer scheduling.
 *
 * The backend API (/flips/adjustment) is the source of truth for adjustment
 * timing. The plugin uses a short initial delay for the first check, then
 * relies on the API's {@code next_check_minutes} response field to schedule
 * subsequent checks. This allows timing to be tuned server-side without
 * requiring plugin updates.
 */
final class AdjustmentTimerUtils
{
	/** Initial delay before the first adjustment check (5 minutes). */
	static final long INITIAL_CHECK_DELAY_MS = 5 * 60 * 1000L;

	/** Fallback delay if the API doesn't return next_check_minutes (10 minutes). */
	static final long FALLBACK_CHECK_DELAY_MS = 10 * 60 * 1000L;

	private AdjustmentTimerUtils()
	{
	}

	/**
	 * Convert the API's next_check_minutes to milliseconds,
	 * falling back to {@link #FALLBACK_CHECK_DELAY_MS} if null or zero.
	 */
	static long nextCheckDelayMs(Integer nextCheckMinutes)
	{
		if (nextCheckMinutes != null && nextCheckMinutes > 0)
		{
			return nextCheckMinutes * 60 * 1000L;
		}
		return FALLBACK_CHECK_DELAY_MS;
	}
}

