package com.flipsmart;
import com.flipsmart.api.dto.Dtos.BankItemId;
import com.flipsmart.api.dto.Dtos.BankItem;
import com.flipsmart.api.dto.Dtos.BankSnapshotResponse;
import com.flipsmart.domain.offer.OfferSignal;
import com.flipsmart.util.ItemUtils;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.ChatMessageType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.game.ItemManager;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.List;

/**
 * Handles bank snapshot capture and submission to the API.
 * Manages cooldowns, rate limit checks, and wealth calculation.
 */
@Slf4j
@Singleton
public class BankSnapshotService
{
	private static final int COINS_ITEM_ID = 995;
	private static final long BANK_SNAPSHOT_COOLDOWN_MS = 60_000;
	private static final long BANK_SNAPSHOT_BACKOFF_MS = 30 * 60_000;

	/**
	 * Cooldown applied to the next attempt. Extended to the long backoff when
	 * the server accepted a snapshot or answered rate-limited — its window is
	 * 24h, so re-posting the full bank every minute would be wasted traffic.
	 */
	private volatile long currentCooldownMs = BANK_SNAPSHOT_COOLDOWN_MS;

	private final PlayerSession session;
	private final FlipSmartApiClient apiClient;
	private final Client client;
	private final ClientThread clientThread;
	private final ItemManager itemManager;
	private final ChatMessageManager chatMessageManager;

	@Inject
	public BankSnapshotService(
		PlayerSession session,
		FlipSmartApiClient apiClient,
		Client client,
		ClientThread clientThread,
		ItemManager itemManager,
		ChatMessageManager chatMessageManager)
	{
		this.session = session;
		this.apiClient = apiClient;
		this.client = client;
		this.clientThread = clientThread;
		this.itemManager = itemManager;
		this.chatMessageManager = chatMessageManager;
	}

	/**
	 * Handle bank container changes - attempt to capture snapshot when bank is opened.
	 * @param rsn The player's RSN (must not be null)
	 */
	public void onBankContainerChanged(String rsn)
	{
		if (session.isBankSnapshotInProgress())
		{
			return;
		}

		long now = System.currentTimeMillis();
		if (now - session.getLastBankSnapshotAttempt() < currentCooldownMs)
		{
			return;
		}

		if (rsn == null)
		{
			return;
		}

		if (!apiClient.isAuthenticated())
		{
			return;
		}

		session.setLastBankSnapshotAttempt(now);
		session.setBankSnapshotInProgress(true);
		currentCooldownMs = BANK_SNAPSHOT_COOLDOWN_MS;

		clientThread.invokeLater(() -> captureBankSnapshot(rsn));
	}

	/**
	 * Capture the current bank contents and send to API.
	 * Must be called on client thread.
	 */
	private void captureBankSnapshot(String rsn)
	{
		try
		{
			List<BankItem> items = collectTradeableBankItems();

			if (items == null || items.isEmpty())
			{
				session.setBankSnapshotInProgress(false);
				return;
			}

			List<BankItemId> inventoryItems = collectInventoryItems();
			List<BankItemId> gearItems = collectGearItems();
			long geOffersValue = calculateGEOffersValue();

			log.debug("Capturing bank snapshot: {} bank items, {} inv items, {} gear items, ge={} for RSN {}",
				items.size(), inventoryItems.size(), gearItems.size(), geOffersValue, rsn);

			apiClient.createBankSnapshotAsync(rsn, items, inventoryItems, gearItems, geOffersValue).thenAccept(result ->
			{
				if (result != null && result.isSuccess())
				{
					BankSnapshotResponse response = result.getResponse();
					String wealthStr = String.format("%,d", response.getTotalWealth());
					log.debug("Bank snapshot captured: {} items, {} GP total wealth",
						response.getItemCount(), wealthStr);
					postBankSnapshotMessage(
						String.format("Bank snapshot saved: %s GP total wealth", wealthStr),
						false);
					currentCooldownMs = BANK_SNAPSHOT_BACKOFF_MS;
				}
				else if (result != null && result.isRateLimited())
				{
					log.debug("Bank snapshot rate limited by server - backing off");
					currentCooldownMs = BANK_SNAPSHOT_BACKOFF_MS;
				}
				else
				{
					log.debug("Failed to create bank snapshot");
					postBankSnapshotMessage("Failed to save bank snapshot", true);
				}
				session.setBankSnapshotInProgress(false);
			}).exceptionally(e ->
			{
				log.debug("Error creating bank snapshot: {}", e.getMessage());
				postBankSnapshotMessage("Connection error - will retry", true);
				session.setBankSnapshotInProgress(false);
				return null;
			});
		}
		catch (Exception e)
		{
			log.error("Error capturing bank snapshot: {}", e.getMessage());
			postBankSnapshotMessage("Error capturing bank data", true);
			session.setBankSnapshotInProgress(false);
		}
	}

	/**
	 * Post a bank snapshot message to game chat.
	 */
	private void postBankSnapshotMessage(String message, boolean isError)
	{
		ChatMessageBuilder builder = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT)
			.append("[FlipSmart] ")
			.append(isError ? ChatColorType.HIGHLIGHT : ChatColorType.NORMAL)
			.append(message);

		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(builder.build())
			.build());
	}

	/**
	 * Collect all tradeable items from the bank with their GE prices.
	 */
	private List<BankItem> collectTradeableBankItems()
	{
		ItemContainer bank = client.getItemContainer(InventoryID.BANK);
		if (bank == null)
		{
			log.debug("Bank container is null - bank may have been closed");
			return null;
		}

		Item[] bankItems = bank.getItems();
		if (bankItems == null || bankItems.length == 0)
		{
			log.debug("Bank is empty");
			return null;
		}

		List<BankItem> items = new ArrayList<>();

		for (Item item : bankItems)
		{
			BankItem bankItem = toTradeableBankItem(item);
			if (bankItem != null)
			{
				items.add(bankItem);
			}
		}

		if (items.isEmpty())
		{
			log.debug("No tradeable items with prices found in bank");
		}

		return items;
	}

	/**
	 * Convert a bank item to a BankItem if it's tradeable and has a price, or if it's coins.
	 */
	private BankItem toTradeableBankItem(Item item)
	{
		int itemId = item.getId();
		int quantity = item.getQuantity();

		if (itemId <= 0 || quantity <= 0)
		{
			return null;
		}

		if (itemId == COINS_ITEM_ID)
		{
			return new BankItem(itemId, quantity, 1);
		}

		if (!ItemUtils.isTradeable(itemManager, itemId))
		{
			return null;
		}

		long gePrice = itemManager.getItemPrice(itemId);
		if (gePrice <= 0)
		{
			return null;
		}

		return new BankItem(itemId, quantity, gePrice);
	}

	/**
	 * Collect tradeable items from the player's inventory.
	 * The backend prices these server-side, so no GE price is computed here.
	 * Coins (item_id 995) are included; backend prices coins as 1 GP each.
	 */
	private List<BankItemId> collectInventoryItems()
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
		if (inventory == null)
		{
			return new ArrayList<>();
		}
		return collectItemIds(inventory.getItems());
	}

	/**
	 * Collect tradeable equipped gear items from the EQUIPMENT container.
	 * The backend prices these server-side.
	 */
	private List<BankItemId> collectGearItems()
	{
		ItemContainer equipment = client.getItemContainer(InventoryID.EQUIPMENT);
		if (equipment == null)
		{
			return new ArrayList<>();
		}
		return collectItemIds(equipment.getItems());
	}

	/**
	 * Filter an item array to tradeable items (or coins) and return as a list
	 * of BankItemId records (item_id + quantity, no client-side price).
	 */
	private List<BankItemId> collectItemIds(Item[] items)
	{
		List<BankItemId> out = new ArrayList<>();
		if (items == null)
		{
			return out;
		}
		for (Item item : items)
		{
			int itemId = item.getId();
			int quantity = item.getQuantity();
			if (itemId <= 0 || quantity <= 0)
			{
				continue;
			}
			if (itemId == COINS_ITEM_ID || ItemUtils.isTradeable(itemManager, itemId))
			{
				out.add(new BankItemId(itemId, quantity));
			}
		}
		return out;
	}

	/**
	 * Calculate the total value locked in GE offers.
	 */
	private long calculateGEOffersValue()
	{
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers == null)
		{
			return 0;
		}

		long totalValue = 0;

		for (GrandExchangeOffer offer : offers)
		{
			totalValue += getGEOfferValue(offer);
		}

		return totalValue;
	}

	/**
	 * Get the GP value locked in a single GE offer (budget + items).
	 * Returns 0 for null or empty offers.
	 */
	private long getGEOfferValue(GrandExchangeOffer offer)
	{
		if (offer == null || offer.getState() == GrandExchangeOfferState.EMPTY)
		{
			return 0;
		}

		long price = offer.getPrice();
		int totalQty = offer.getTotalQuantity();
		int filledQty = offer.getQuantitySold();
		int remainingQty = totalQty - filledQty;

		long itemPrice = itemManager.getItemPrice(offer.getItemId());
		if (itemPrice <= 0)
		{
			itemPrice = price;
		}

		if (OfferSignal.isBuyState(offer.getState()))
		{
			return (long) remainingQty * price + (long) filledQty * itemPrice;
		}
		else
		{
			return (long) remainingQty * itemPrice + (long) filledQty * price;
		}
	}
}

package com.flipsmart;
import com.flipsmart.api.dto.Dtos.WikiPrice;
import com.flipsmart.domain.offer.OfferRecord;
import com.flipsmart.api.dto.Dtos.OfferAdviceResponse;
import com.flipsmart.domain.offer.OfferDisposition;
import com.flipsmart.api.dto.Dtos.OfferAdviceRequest;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Consumer;
import java.util.function.IntConsumer;
import lombok.Getter;

public class ActiveOfferAdvisorService
{
	/**
	 * Cross-poll advisor state (#918). The backend advisor is stateless, so the
	 * plugin relays the counters it returned on the previous poll: last position
	 * margin (for consecutive-decrease detection) and the joint reduction budget.
	 */
	@Getter
	public static final class CourierState
	{
		private final Long previousPositionMargin;
		private final int consecutiveMarginDecreases;
		private final double cumulativeMarginReductionPct;

		public CourierState(Long previousPositionMargin, int consecutiveMarginDecreases, double cumulativeMarginReductionPct)
		{
			this.previousPositionMargin = previousPositionMargin;
			this.consecutiveMarginDecreases = consecutiveMarginDecreases;
			this.cumulativeMarginReductionPct = cumulativeMarginReductionPct;
		}

		static final CourierState EMPTY = new CourierState(null, 0, 0.0);
	}

	private final Map<Integer, OfferAdviceResponse> dispositions = new ConcurrentHashMap<>();
	private final Map<Integer, CourierState> courierByItem = new ConcurrentHashMap<>();

	private volatile Consumer<OfferAdviceResponse> onSurfacePrice;
	private volatile Consumer<OfferAdviceResponse> onHandoff;
	private volatile IntConsumer onClearSurface;

	public void setCallbacks(Consumer<OfferAdviceResponse> onSurfacePrice, Consumer<OfferAdviceResponse> onHandoff, IntConsumer onClearSurface)
	{
		this.onSurfacePrice = onSurfacePrice;
		this.onHandoff = onHandoff;
		this.onClearSurface = onClearSurface;
	}

	public OfferAdviceResponse getDisposition(int itemId)
	{
		return dispositions.get(itemId);
	}

	/** The courier state to relay for this item's next snapshot (EMPTY if none). */
	public CourierState getCourierState(int itemId)
	{
		return courierByItem.getOrDefault(itemId, CourierState.EMPTY);
	}

	/**
	 * Drop dispositions for items that are no longer open active offers (sold, bought,
	 * collected, cancelled) so their prompt/highlight clears immediately instead of
	 * lingering until the next poll skips them.
	 */
	void reconcile(java.util.Set<Integer> activeItemIds)
	{
		for (Integer itemId : dispositions.keySet())
		{
			if (!activeItemIds.contains(itemId))
			{
				applyResponse(itemId, null);
			}
		}
		// Courier state can outlive a disposition (a WAITing offer clears its
		// disposition but keeps accumulating decay/budget), so prune it too.
		courierByItem.keySet().removeIf(id -> !activeItemIds.contains(id));
	}

	void applyResponse(int itemId, OfferAdviceResponse resp)
	{
		if (resp == null)
		{
			courierByItem.remove(itemId);
		}
		else
		{
			courierByItem.put(itemId, new CourierState(
				resp.getPositionMargin(), resp.getConsecutiveMarginDecreases(), resp.getCumulativeMarginReductionPct()));
		}
		OfferDisposition disposition = OfferDisposition.route(resp == null ? null : resp.getActionEnum());
		switch (disposition)
		{
			case SURFACE_PRICE:
				resp.setItemIdHint(itemId);
				dispositions.put(itemId, resp);
				if (onSurfacePrice != null)
				{
					onSurfacePrice.accept(resp);
				}
				break;
			case HANDOFF:
				dispositions.remove(itemId);
				if (onClearSurface != null)
				{
					onClearSurface.accept(itemId);
				}
				if (onHandoff != null)
				{
					resp.setItemIdHint(itemId);
					onHandoff.accept(resp);
				}
				break;
			case NONE:
			default:
				dispositions.remove(itemId);
				if (onClearSurface != null)
				{
					onClearSurface.accept(itemId);
				}
				break;
		}
	}

	static OfferAdviceRequest buildSnapshot(
		OfferRecord offer,
		WikiPrice market,
		Long userAvgBuyPrice,
		Integer dailyVolume)
	{
		return buildSnapshot(offer, market, userAvgBuyPrice, dailyVolume, null, CourierState.EMPTY);
	}

	/**
	 * Aggressive Advisor gate: the competitive re-prompts and margin-decay exit only evaluate when
	 * the backend receives the original margin and courier counters. When the experimental toggle is
	 * off we relay null / EMPTY so the backend runs only the base wait / move-down / exit advice.
	 * Static + package-private so the gate stays unit-testable.
	 */
	static Long relayedMargin(boolean aggressive, Long originalMargin)
	{
		return aggressive ? originalMargin : null;
	}

	static CourierState relayedCourier(boolean aggressive, CourierState courier)
	{
		return aggressive ? courier : CourierState.EMPTY;
	}

	static OfferAdviceRequest buildSnapshot(
		OfferRecord offer,
		WikiPrice market,
		Long userAvgBuyPrice,
		Integer dailyVolume,
		Long originalMargin,
		CourierState courier)
	{
		boolean isSell = !offer.isBuy();
		long lastFill = offer.getLastActivityAtMillis();
		CourierState c = courier == null ? CourierState.EMPTY : courier;
		return OfferAdviceRequest.builder()
			.itemId(offer.getItemId())
			.pool(OfferPoolClassifier.classify(dailyVolume))
			.side(isSell ? "sell" : "buy")
			.stage(offer.getOfferStage())
			.listedAtMillis(offer.getCreatedAtMillis())
			.listedPrice(offer.getPrice())
			.listedQuantity(offer.getTotalQuantity())
			.filledQuantity(offer.getFilledQuantity())
			.lastFillAtMillis(lastFill > 0 ? lastFill : null)
			.currentMarketHigh(market == null ? null : market.instaBuy)
			.currentMarketLow(market == null ? null : market.instaSell)
			// Now carried for buys too — the margin-decay exit (AC2) needs the
			// avg buy price on a partially-filled buy.
			.userAvgBuyPrice(userAvgBuyPrice)
			.originalMargin(originalMargin)
			.previousPositionMargin(c.getPreviousPositionMargin())
			.consecutiveMarginDecreases(c.getConsecutiveMarginDecreases())
			.cumulativeMarginReductionPct(c.getCumulativeMarginReductionPct())
			.build();
	}
}

package com.flipsmart;

import com.flipsmart.util.GpUtils;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.Keybind;
import net.runelite.client.input.KeyListener;

import javax.inject.Inject;
import java.awt.event.KeyEvent;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;

/**
 * Key listener for the Flip Assist feature.
 * Handles the hotkey press to auto-fill price and quantity in the GE.
 */
@Slf4j
public class FlipAssistInputListener implements KeyListener
{
	private final Client client;
	private final ClientThread clientThread;
	private final FlipSmartConfig config;
	private final FlipAssistOverlay flipAssistOverlay;

	// GE Interface group IDs
	private static final int GE_INTERFACE_GROUP = 465;
	private static final int GE_OFFER_GROUP = 162;

	// GE Interface child IDs
	private static final int GE_QUANTITY_CHILD = 24;

	// VarClient IDs (raw values to avoid deprecated API)
	static final int VARCLIENT_INPUT_TYPE = 5;
	static final int VARCLIENT_INPUT_TEXT = 359;

	// Input type values
	private static final int INPUT_TYPE_NUMERIC = 7;
	private static final int INPUT_TYPE_NUMERIC_LONG = 30;
	static final int INPUT_TYPE_GE_ITEM_SEARCH = 14;

	private static boolean isNumericInput(int inputType)
	{
		return inputType == INPUT_TYPE_NUMERIC || inputType == INPUT_TYPE_NUMERIC_LONG;
	}

	// Chat message prefix - cyan color for visibility
	private static final String CHAT_MESSAGE_PREFIX = "<col=00e5ff>[FlipSmart]</col> ";

	// Widget groups to scan for price/quantity dialog title
	private static final int[] CHATBOX_WIDGET_GROUPS = {162, 163, 164, 217, 219, 229, 548, 161};

	// Parent widgets to check for static/dynamic children with price/quantity text
	private static final int[][] CHATBOX_PARENT_WIDGETS = {
		{162, 0}, {162, 1}, {162, 5}, {162, 24},
		{217, 0}, {217, 4}, {217, 5}, {217, 6}
	};

	@Inject
	public FlipAssistInputListener(Client client, ClientThread clientThread, FlipSmartConfig config, FlipAssistOverlay flipAssistOverlay)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.flipAssistOverlay = flipAssistOverlay;
	}

	// Track the keyPressed event we're handling to consume its corresponding keyTyped
	private final AtomicReference<KeyEvent> handledKeyPressedEvent = new AtomicReference<>(null);

	// Cached input type from VarClientInt, updated via event from FlipSmartPlugin.
	// Used on EDT to decide whether to consume the hotkey before clientThread runs.
	private final AtomicInteger currentInputType = new AtomicInteger(0);

	/**
	 * Update the cached input type. Called from FlipSmartPlugin on VarClientIntChanged.
	 */
	public void updateInputType(int inputType)
	{
		currentInputType.set(inputType);
	}

	@Override
	public void keyTyped(KeyEvent e)
	{
		// Only consume if this keyTyped corresponds to a keyPressed we handled
		// Check by comparing the key character
		KeyEvent handled = handledKeyPressedEvent.get();
		if (handled != null && 
			Character.toLowerCase(e.getKeyChar()) == Character.toLowerCase(handled.getKeyChar()))
		{
			handledKeyPressedEvent.set(null);
			e.consume();
		}
	}

	@Override
	public void keyPressed(KeyEvent e)
	{
		// Don't process hotkeys if Flip Assist is disabled
		if (!config.enableFlipAssistant())
		{
			return;
		}

		// Check if the hotkey matches
		Keybind hotkey = config.flipAssistHotkey();
		if (!hotkey.matches(e))
		{
			return;
		}

		// Don't trigger if no focused flip (this doesn't need client thread)
		FocusedFlip focusedFlip = flipAssistOverlay.getFocusedFlip();
		if (focusedFlip == null)
		{
			return;
		}

		int cachedInputType = currentInputType.get();

		// Numeric (price/quantity) input is hotkey-driven: the plugin fills the
		// value. Consume eagerly on the EDT — clientThread.invoke() is async, so
		// consuming inside the callback would be too late to stop the keystroke.
		if (isNumericInput(cachedInputType))
		{
			handledKeyPressedEvent.set(e);
			e.consume();
			clientThread.invoke(() -> handleHotkeyOnClientThread(focusedFlip));
		}

		// On the GE item-search screen the hotkey must NOT be consumed: the player is
		// typing an item name and its letters (e.g. the "E" in "Rune arrows") have to
		// reach the search box. Item selection happens via the injected "FlipSmart
		// item" row, not the hotkey.
	}

	/**
	 * Handle the hotkey action on the client thread.
	 * Validates GE state and fills the numeric price/quantity input.
	 * MUST be called on client thread.
	 */
	private void handleHotkeyOnClientThread(FocusedFlip focusedFlip)
	{
		if (!isGrandExchangeOpen())
		{
			return;
		}

		// Defense-in-depth against the auto-advance race window before the offer-screen lock acquires.
		int openOfferItemId = client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH);
		if (openOfferItemId > 0 && focusedFlip.getItemId() != openOfferItemId)
		{
			if (log.isDebugEnabled())
			{
				log.debug("FlipAssist hotkey: skipped (focused item {} != open offer item {})",
					focusedFlip.getItemId(), openOfferItemId);
			}
			return;
		}

		// Only numeric (price/quantity) input is hotkey-driven. Item selection is
		// handled by the injected "FlipSmart item" shortcut row the player clicks.
		if (isNumericInput(client.getVarcIntValue(VARCLIENT_INPUT_TYPE)))
		{
			handleFlipAssistAction(focusedFlip);
			flipAssistOverlay.updateStep();
		}
	}

	@Override
	public void keyReleased(KeyEvent e)
	{
		// Not used
	}

	/**
	 * Check if the Grand Exchange interface is open.
	 * MUST be called on client thread.
	 */
	private boolean isGrandExchangeOpen()
	{
		Widget geWidget = client.getWidget(GE_INTERFACE_GROUP, 0);
		Widget offerWidget = client.getWidget(GE_OFFER_GROUP, 0);

		return (geWidget != null && !geWidget.isHidden()) ||
			   (offerWidget != null && !offerWidget.isHidden());
	}

	/**
	 * Handle the Flip Assist action - auto-fill price/quantity in GE.
	 * Called only when in a numeric input dialog.
	 * MUST be called on client thread.
	 */
	private void handleFlipAssistAction(FocusedFlip focusedFlip)
	{
		// Determine if it's price or quantity based on context
		if (isLikelyPriceInput())
		{
			setInputValue(focusedFlip.getCurrentStepPrice());
			sendChatMessage(focusedFlip.getItemName() + " price set to " + String.format("%,d", focusedFlip.getCurrentStepPrice()) + " gp");
		}
		else
		{
			setInputValue(focusedFlip.getCurrentStepQuantity());
			sendChatMessage(focusedFlip.getItemName() + " quantity set to " + String.format("%,d", focusedFlip.getCurrentStepQuantity()));
		}
	}

	/**
	 * Set the current input field value and refresh the display.
	 * MUST be called on client thread.
	 */
	private void setInputValue(long value)
	{
		String valueStr = String.valueOf(value);
		client.setVarcStrValue(VARCLIENT_INPUT_TEXT, valueStr);

		// Redraw the chatbox input line directly instead of invoking the rebuild
		// script: write the value plus the cursor glyph into the full-input widget
		// (MES_TEXT2 == CHATBOX_FULL_INPUT) so it is visible. The GE confirms off the
		// VarClientStr above, not this text.
		Widget input = client.getWidget(InterfaceID.Chatbox.MES_TEXT2);
		if (input != null)
		{
			input.setText(valueStr + "*");
		}
	}

	/**
	 * Determine if we're in a price input dialog vs quantity input.
	 * Checks the chatbox dialog title text for keywords.
	 * MUST be called on client thread.
	 */
	private boolean isLikelyPriceInput()
	{
		// Scan ALL visible widgets in chatbox-related groups for the dialog title
		// The OSRS chatbox input dialog title can appear in various locations
		for (int groupId : CHATBOX_WIDGET_GROUPS)
		{
			// Check children 0-100 for each group
			for (int childId = 0; childId <= 100; childId++)
			{
				Optional<Boolean> result = checkWidgetForPriceKeyword(groupId, childId);
				if (result.isPresent())
				{
					return result.get();
				}
			}
		}

		// Also try checking static and dynamic children of key parent widgets
		for (int[] parent : CHATBOX_PARENT_WIDGETS)
		{
			Widget parentWidget = client.getWidget(parent[0], parent[1]);
			if (parentWidget != null)
			{
				// Check static children
				Optional<Boolean> staticResult = checkChildrenForPriceKeyword(parentWidget.getStaticChildren());
				if (staticResult.isPresent())
				{
					return staticResult.get();
				}

				// Check dynamic children
				Optional<Boolean> dynamicResult = checkChildrenForPriceKeyword(parentWidget.getDynamicChildren());
				if (dynamicResult.isPresent())
				{
					return dynamicResult.get();
				}

				// Check nested children
				Optional<Boolean> nestedResult = checkChildrenForPriceKeyword(parentWidget.getNestedChildren());
				if (nestedResult.isPresent())
				{
					return nestedResult.get();
				}
			}
		}

		// Fallback: Check the GE interface state to determine what we're setting
		// If quantity field has a non-default value, we're probably setting price
		return determineFromGEState();
	}

	/**
	 * Check an array of widget children for price/quantity keywords.
	 */
	private Optional<Boolean> checkChildrenForPriceKeyword(Widget[] children)
	{
		if (children == null)
		{
			return Optional.empty();
		}
		for (Widget child : children)
		{
			if (child != null && !child.isHidden())
			{
				Optional<Boolean> result = checkTextForPriceKeyword(child.getText());
				if (result.isPresent())
				{
					return result;
				}
			}
		}
		return Optional.empty();
	}

	/**
	 * Try to determine price vs quantity input based on GE interface state.
	 * If quantity is already set to a non-default value, we're likely setting price.
	 * @return true if likely price input, false if likely quantity input
	 */
	private boolean determineFromGEState()
	{
		// GE offer setup widget children for quantity and price displays
		Widget quantityWidget = client.getWidget(GE_INTERFACE_GROUP, GE_QUANTITY_CHILD);

		String quantityText = (quantityWidget != null && !quantityWidget.isHidden()) ? quantityWidget.getText() : null;

		// Parse quantity from text (e.g., "6,000" -> 6000)
		long currentQuantity = GpUtils.parseDigits(quantityText);

		// If quantity has been set (> 1, since default is often 1) and we're in an input,
		// user is probably now setting price
		return currentQuantity > 1;
	}

	/**
	 * Parse a number from formatted text like "6,000" or "6000 coins".
	 */

	/**
	 * Check a specific widget for price/quantity keywords.
	 * Returns Optional containing true if price, false if quantity, empty if no match.
	 */
	private Optional<Boolean> checkWidgetForPriceKeyword(int groupId, int childId)
	{
		Widget widget = client.getWidget(groupId, childId);
		if (widget != null && !widget.isHidden())
		{
			return checkTextForPriceKeyword(widget.getText());
		}
		return Optional.empty();
	}

	/**
	 * Check text for price/quantity keywords.
	 * Returns Optional containing true if price, false if quantity, empty if no match.
	 */
	private Optional<Boolean> checkTextForPriceKeyword(String text)
	{
		if (text != null && !text.isEmpty())
		{
			String lowerText = text.toLowerCase();
			// "Set a price for each item" = price input
			if (lowerText.contains("price") && !lowerText.contains("price:"))
			{
				return Optional.of(Boolean.TRUE);
			}
			// "How many do you wish to" = quantity input
			if (lowerText.contains("how many"))
			{
				return Optional.of(Boolean.FALSE);
			}
		}
		return Optional.empty();
	}

	/**
	 * Send a message to the chatbox (game message style).
	 * MUST be called on client thread.
	 */
	private void sendChatMessage(String message)
	{
		client.addChatMessage(
			net.runelite.api.ChatMessageType.GAMEMESSAGE,
			"",
			CHAT_MESSAGE_PREFIX + message,
			null
		);
	}
}

package com.flipsmart.trading;

import com.flipsmart.domain.offer.OfferSignal;

import net.runelite.api.GrandExchangeOfferState;

/** Reduces a raw GE offer-changed event to the {@link OfferSignal} the trading core consumes. */
public final class OfferEventMapper
{
    private OfferEventMapper() {}

    public static OfferSignal toSignal(
        int slot,
        GrandExchangeOfferState state,
        int itemId,
        String itemName,
        int totalQuantity,
        long price,
        int quantitySold,
        long spent)
    {
        return new OfferSignal(slot, state, itemId, itemName, totalQuantity, price, quantitySold, spent);
    }
}

package com.flipsmart.trading;

import com.flipsmart.domain.offer.OfferRecord;
import com.flipsmart.domain.offer.OfferTransition;

public final class OfferEvent
{
    public final OfferTransition.Kind kind;
    public final OfferRecord record;
    public final int newlyFilledQuantity;
    public final long newlySpent;
    /** Generation of the slot when this delta was measured. Carried on the event
     *  rather than looked up by listeners because a terminal offer advances its
     *  slot's generation before they run, which would stamp an order's last fill
     *  with its successor's identity. */
    public final int slotGeneration;

    public OfferEvent(OfferTransition.Kind kind, OfferRecord record, int newlyFilledQuantity, long newlySpent,
        int slotGeneration)
    {
        this.kind = kind;
        this.record = record;
        this.newlyFilledQuantity = newlyFilledQuantity;
        this.newlySpent = newlySpent;
        this.slotGeneration = slotGeneration;
    }
}

package com.flipsmart.trading;

import com.flipsmart.FlipSmartApiClient;
import com.flipsmart.PlayerSession;
import com.flipsmart.api.dto.Dtos.TransactionRequest;
import com.flipsmart.domain.offer.OfferRecord;
import com.flipsmart.domain.offer.OfferState;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.function.Supplier;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Single recording point for GE transactions, driven by OfferEvents from OfferStore.
 * Generates a deterministic per-event idempotency key and delegates to the API client.
 * The backend partial-unique index is the durable backstop; this class adds a
 * bounded client-side guard to suppress immediate duplicate sends within one session.
 */
@Singleton
public final class TransactionLogger
{
    public enum Type { PLACE, FILL }

    private static final int SEEN_KEYS_CAPACITY = 512;

    private final FlipSmartApiClient apiClient;
    private final PlayerSession session;
    private final Supplier<Optional<String>> rsnSupplier;
    private final RoundTripLedger roundTripLedger;

    // Fired after a sell fill's push resolves (the backend pairs the flip within that
    // request), so session P&L can refresh off the just-recorded completed flip rather
    // than waiting for the next timer poll.
    private volatile Runnable onSellRecorded;

    // Tags recorded transactions with the player's active flip timeframe; defaults to untagged.
    private volatile Supplier<String> timeframeSupplier = () -> null;

    private final Set<String> seenKeys = Collections.synchronizedSet(
        Collections.newSetFromMap(
            new LinkedHashMap<String, Boolean>()
            {
                @Override
                protected boolean removeEldestEntry(Map.Entry<String, Boolean> eldest)
                {
                    return size() > SEEN_KEYS_CAPACITY;
                }
            }));

    @Inject
    public TransactionLogger(FlipSmartApiClient apiClient, PlayerSession session, RoundTripLedger roundTripLedger)
    {
        this(apiClient, session, session::getRsnSafe, roundTripLedger);
    }

    public TransactionLogger(FlipSmartApiClient apiClient, PlayerSession session,
                             Supplier<Optional<String>> rsnSupplier, RoundTripLedger roundTripLedger)
    {
        this.apiClient = apiClient;
        this.session = session;
        this.rsnSupplier = rsnSupplier;
        this.roundTripLedger = roundTripLedger;
    }

    public void setOnSellRecorded(Runnable callback)
    {
        this.onSellRecorded = callback;
    }

    public void setTimeframeSupplier(Supplier<String> supplier)
    {
        this.timeframeSupplier = supplier;
    }

    public void onOfferEvent(OfferEvent e)
    {
        switch (e.kind)
        {
            case PLACED:
                // An offer first seen already filling (immediate / offline fill) records the
                // fill only — never a separate qty-0 placement row. The placement row is for
                // genuine 0-filled placements; emitting both here would double-log the order
                // versus the single fill the old recording path produced.
                if (e.newlyFilledQuantity > 0)
                {
                    recordFill(e.record, e.newlyFilledQuantity, e.newlySpent, e.slotGeneration);
                }
                else
                {
                    recordPlacement(e.record, e.slotGeneration);
                }
                break;
            case FILLED_DELTA:
            case COMPLETED:
            case CANCELLED:
                if (e.newlyFilledQuantity > 0)
                {
                    recordFill(e.record, e.newlyFilledQuantity, e.newlySpent, e.slotGeneration);
                }
                break;
            default:
                // COLLECTED, NONE, REJECTED — nothing to record
                break;
        }
    }

    private void recordPlacement(OfferRecord r, int slotGeneration)
    {
        String rsn = rsnSupplier.get().orElse(null);
        String key = idempotencyKey(rsn, r, Type.PLACE);
        // Zero-fill placement: peek the current cycle rather than recordFill, since no
        // quantity actually moved and peeking must never trip a zero-crossing.
        Integer roundTripId = roundTripLedger.peekRoundTripId(rsn, r.getItemId());
        if (alreadySent(key, normalizedDedupKey(rsn, roundTripId, r, Type.PLACE)))
        {
            return;
        }
        apiClient.recordTransactionAsync(baseBuilder(r, 0, r.getPrice(), rsn, key).roundTripId(roundTripId).slotGeneration(slotGeneration).build());
    }

    private void recordFill(OfferRecord r, int newlyFilled, long newlySpent, int slotGeneration)
    {
        String rsn = rsnSupplier.get().orElse(null);
        String key = idempotencyKey(rsn, r, Type.FILL);
        // Peek (non-mutating) the round trip this fill belongs to for the dedup key
        // BEFORE the guard, so a suppressed duplicate never advances the ledger.
        Integer roundTripId = roundTripLedger.peekRoundTripId(rsn, r.getItemId());
        if (alreadySent(key, normalizedDedupKey(rsn, roundTripId, r, Type.FILL)))
        {
            return;
        }
        // Rounded rather than truncated: this now also feeds recordBuyBasis below, and truncation
        // biased every weighted-average basis down by up to 1gp/item.
        long pricePerItem = newlyFilled > 0 ? Math.round((double) newlySpent / newlyFilled) : 0;
        // The offer is done filling (so its slot's cumulative baseline may reset) once it is no longer
        // NEW or PARTIAL_FILL — i.e. FILLED, collected, or cancelled. A still-filling offer keeps its
        // baseline so a sibling slot of the same item is never double-counted on a mid-fill close.
        OfferState state = r.getState();
        boolean offerComplete = state != OfferState.NEW
            && state != OfferState.PARTIAL_FILL;
        RoundTripLedger.FillResult fill = roundTripLedger.recordFillGuarded(
            rsn, r.getItemId(), r.getSlot(), r.isBuy(), newlyFilled, r.getFilledQuantity(), offerComplete);
        if (fill.duplicateSuppressed)
        {
            // A duplicate/phantom closing fill (Collect re-detection under a churned offer_id) that
            // the peek-based dedup above can't catch: the genuine close already advanced the cycle,
            // so this fill's peeked id — and thus its dedup key — differs from the original's. The
            // ledger recognised it as a byte-identical re-delivery and mutated nothing; forwarding
            // it would stamp the backend with the next cycle's id, so drop it here.
            // Basis is deliberately not folded either — a re-delivery buys nothing.
            return;
        }
        if (r.isBuy())
        {
            // Folded quantity, not the caller's: the ledger rebaselines a slot-keyed fill against
            // what that slot already absorbed, and the basis has to describe the same items.
            roundTripLedger.recordBuyBasis(rsn, r.getItemId(), fill.foldedQuantity, pricePerItem);
        }
        java.util.concurrent.CompletableFuture<Void> sent = apiClient.recordTransactionAsync(
            baseBuilder(r, newlyFilled, pricePerItem, rsn, key).roundTripId(fill.roundTripId).slotGeneration(slotGeneration).build());
        if (!r.isBuy() && onSellRecorded != null)
        {
            sent.thenRun(onSellRecorded);
        }
    }

    /**
     * True if either the exact per-record key or the churn-resistant normalized key
     * has already been sent this session; records both so a later re-report — under
     * the same record OR a Collect-re-detected new offerId — is suppressed. Purely
     * additive: anything not matched is sent exactly as before.
     */
    private boolean alreadySent(String key, String normalizedKey)
    {
        synchronized (seenKeys)
        {
            boolean seen = seenKeys.contains(key) || seenKeys.contains(normalizedKey);
            seenKeys.add(key);
            seenKeys.add(normalizedKey);
            return seen;
        }
    }

    /**
     * Identity of a logical fill/placement that survives Collect-driven offer_id and
     * timestamp churn: {@code rsn:itemId:isBuy:slot:roundTrip:TYPE:cumulative}. The GE
     * slot is included because {@code filledQuantity} is per-offer, so two CONCURRENT
     * same-item offers (different slots) can reach the same cumulative — without the
     * slot they would collide and the second fill would be dropped. A real re-report
     * keeps its slot even when its offer_id churns, so suppression still works. Used
     * only for client-side send suppression; the sent idempotency key is unchanged.
     */
    static String normalizedDedupKey(String rsn, Integer roundTripId,
                                     OfferRecord r, Type type)
    {
        long cumulative = type == Type.PLACE ? 0 : r.getFilledQuantity();
        return rsn + ":" + r.getItemId() + ":" + r.isBuy() + ":" + r.getSlot()
            + ":" + roundTripId + ":" + type + ":" + cumulative;
    }

    private TransactionRequest.Builder baseBuilder(OfferRecord r,
                                                    int qty, long price, String rsn, String key)
    {
        Long recPrice = r.isBuy() ? session.getRecommendedPrice(r.getItemId()) : null;
        return TransactionRequest
            .builder(r.getItemId(), r.getItemName(), r.isBuy(), qty, price)
            .geSlot(r.getSlot())
            .recommendedSellPrice(recPrice)
            .rsn(rsn)
            .totalQuantity(r.getTotalQuantity())
            .idempotencyKey(key)
            .offerId(r.getOfferId())
            .timeframe(timeframeSupplier.get());
    }

    /**
     * Deterministic idempotency key for a single logical record+type combination.
     * Format: {@code rsn:offerId:createdAtMillis:TYPE:cumulative}
     * where cumulative=0 for PLACE, filledQuantity for FILL.
     */
    public static String idempotencyKey(String rsn, OfferRecord r, Type type)
    {
        long cumulative = type == Type.PLACE ? 0 : r.getFilledQuantity();
        return rsn + ":" + r.getOfferId() + ":" + r.getCreatedAtMillis() + ":" + type + ":" + cumulative;
    }

    /**
     * Emit the live FILL an offline-completed sell never sent — its GE slot was gone at
     * login, so it bypassed {@link #onOfferEvent}. Fired once per record by offline sync
     * (the ledger fill is recorded there); the deterministic key lets the backend floor a
     * later History backfill for the same offer, so the two never double-count.
     */
    public void recordOfflineSellFill(OfferRecord r)
    {
        if (r.isBuy() || r.getFilledQuantity() <= 0)
        {
            return;
        }
        String rsn = rsnSupplier.get().orElse(null);
        int qty = r.getFilledQuantity();
        long pricePerItem = Math.round((double) r.getSpent() / qty);
        Integer roundTripId = roundTripLedger.peekRoundTripId(rsn, r.getItemId());
        apiClient.recordTransactionAsync(
            baseBuilder(r, qty, pricePerItem, rsn, idempotencyKey(rsn, r, Type.FILL))
                .roundTripId(roundTripId).build());
    }
}

package com.flipsmart.trading;

import lombok.Getter;

/**
 * Identity of one Grand Exchange order.
 *
 * <p>Deliberately excludes price, total quantity and fill count. Those drift while an order is
 * live — a partial buy re-reads a different total, a relist changes price — and keying on them
 * made a still-live order fail to match itself. Generation separates successive orders that
 * reuse the same slot, so a new order never inherits the previous one's progress.</p>
 */
@Getter
public final class OfferIdentity
{
	private final int slot;
	private final int itemId;
	private final boolean buy;
	private final int generation;

	private OfferIdentity(int slot, int itemId, boolean buy, int generation)
	{
		this.slot = slot;
		this.itemId = itemId;
		this.buy = buy;
		this.generation = generation;
	}

	public static OfferIdentity of(int slot, int itemId, boolean buy, int generation)
	{
		return new OfferIdentity(slot, itemId, buy, generation);
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof OfferIdentity))
		{
			return false;
		}
		OfferIdentity other = (OfferIdentity) o;
		return slot == other.slot
			&& itemId == other.itemId
			&& buy == other.buy
			&& generation == other.generation;
	}

	@Override
	public int hashCode()
	{
		int result = slot;
		result = 31 * result + itemId;
		result = 31 * result + (buy ? 1 : 0);
		result = 31 * result + generation;
		return result;
	}

	/** Stable string form, used as the persisted watermark key. */
	@Override
	public String toString()
	{
		return slot + ":" + itemId + ":" + (buy ? "b" : "s") + ":" + generation;
	}
}

package com.flipsmart.trading;

import com.flipsmart.domain.offer.OfferRecord;
import com.flipsmart.util.GeTax;
import java.util.List;

/**
 * Realized profit on the units of an active flip that have actually sold, computed
 * from locally-tracked GE sell fills. Pure: a function of the supplied records.
 */
public final class RealizedFlipProfit
{
	public static final class Result
	{
		public final int soldQuantity;
		public final long grossProceeds;
		public final long taxTotal;
		public final long netProfit;

		Result(int soldQuantity, long grossProceeds, long taxTotal, long netProfit)
		{
			this.soldQuantity = soldQuantity;
			this.grossProceeds = grossProceeds;
			this.taxTotal = taxTotal;
			this.netProfit = netProfit;
		}
	}

	private RealizedFlipProfit()
	{
	}

	/**
	 * @param itemRecords     all offer records for the item (e.g. OfferStore.forItem)
	 * @param itemId          item id, for the GE tax-exempt list
	 * @param averageBuyPrice player's average buy price for the flip
	 * @param sinceMillis     include only sells last active at/after this epoch-ms
	 *                        (the current flip's first-buy time); 0 includes all
	 */
	public static Result compute(List<OfferRecord> itemRecords, int itemId, long averageBuyPrice, long sinceMillis)
	{
		int soldQuantity = 0;
		long grossProceeds = 0L;
		long taxTotal = 0L;

		if (itemRecords != null)
		{
			for (OfferRecord r : itemRecords)
			{
				if (r == null || r.isBuy() || r.getFilledQuantity() <= 0)
				{
					continue;
				}
				if (r.getEffectiveLastActivityAtMillis() < sinceMillis)
				{
					continue;
				}
				soldQuantity += r.getFilledQuantity();
				grossProceeds += r.getSpent();
				taxTotal += (long) GeTax.taxFor(itemId, r.getPrice()) * r.getFilledQuantity();
			}
		}

		long buyCost = (long) soldQuantity * averageBuyPrice;
		long netProfit = grossProceeds - buyCost - taxTotal;
		return new Result(soldQuantity, grossProceeds, taxTotal, netProfit);
	}
}

package com.flipsmart.trading;

import com.flipsmart.domain.offer.OfferRecord;
import java.util.HashMap;
import java.util.Map;

/**
 * Highest cumulative fill ever observed for each order.
 *
 * <p>The Grand Exchange reports cumulative totals per slot, never increments, so what is new
 * has to be derived by subtraction. Deriving it from whatever record happens to be in memory
 * makes the result depend on that record surviving — and it does not always survive a hop, a
 * reconcile, or a skipped persist. Holding the high-water mark here instead means a lost or
 * rewound record cannot re-report fills that were already counted, and the first observation
 * after a gap reports exactly the amount that filled during it.</p>
 *
 * <p>Marks only ever rise. Every path that brings marks in from elsewhere merges by maximum,
 * so restoring an older snapshot can add knowledge but never remove it.</p>
 */
public final class FillWatermarks
{
	/** What one observation newly revealed. Zero on a replay or a stale snapshot. */
	public static final class Delta
	{
		public final int quantity;
		public final long spent;

		Delta(int quantity, long spent)
		{
			this.quantity = quantity;
			this.spent = spent;
		}
	}

	private static final int FILLED = 0;
	private static final int SPENT = 1;
	private static final int FIRST_GENERATION = 1;

	/**
	 * Prefix marking a persisted slot generation rather than a fill mark. Without carrying
	 * generation across a restart, a slot restarts at the first generation while marks from the
	 * previous session survive, so a new order matching a slot's earliest use would adopt that
	 * finished order's mark and have its fills suppressed.
	 */
	private static final String GENERATION_KEY_PREFIX = "gen:";

	private final Map<String, long[]> marks = new HashMap<>();
	private final Map<Integer, Integer> slotGeneration = new HashMap<>();

	/** Record a cumulative observation and return only what it added. */
	public synchronized Delta observe(OfferIdentity id, int cumulativeFilled, long cumulativeSpent)
	{
		String key = id.toString();
		long[] mark = marks.get(key);
		long priorFilled = mark == null ? 0L : mark[FILLED];
		long priorSpent = mark == null ? 0L : mark[SPENT];

		long raisedFilled = Math.max(priorFilled, cumulativeFilled);
		long raisedSpent = Math.max(priorSpent, cumulativeSpent);
		marks.put(key, new long[]{raisedFilled, raisedSpent});

		return new Delta((int) (raisedFilled - priorFilled), raisedSpent - priorSpent);
	}

	/** The generation currently in force for {@code slot}. */
	public synchronized int generationFor(int slot)
	{
		Integer generation = slotGeneration.get(slot);
		return generation == null ? FIRST_GENERATION : generation;
	}

	/**
	 * Called when a slot demonstrably turns over, so the order that follows starts from a zero
	 * baseline rather than inheriting the finished order's progress.
	 */
	public synchronized void advanceGeneration(int slot)
	{
		slotGeneration.put(slot, generationFor(slot) + 1);
	}

	public synchronized Map<String, long[]> export()
	{
		Map<String, long[]> out = new HashMap<>(marks);
		// Generation rides along in the same map so there is only ever one thing to keep fresh.
		// An identity key carries four colon-separated fields, so this prefix cannot collide.
		for (Map.Entry<Integer, Integer> entry : slotGeneration.entrySet())
		{
			out.put(GENERATION_KEY_PREFIX + entry.getKey(), new long[]{entry.getValue(), 0L});
		}
		return out;
	}

	/**
	 * Raise marks to the progress already recorded on {@code records}.
	 *
	 * <p>Clients upgrading from a build without marks have none persisted, so the first
	 * observation of an in-flight order would measure against zero and re-report the whole
	 * cumulative. The records themselves already carry the correct totals, so seeding from them
	 * starts the marks in the right place. Terminal records are skipped: they are finished, and
	 * no further observation of them can arrive.</p>
	 */
	public synchronized void seedFrom(java.util.Collection<OfferRecord> records)
	{
		if (records == null)
		{
			return;
		}
		for (OfferRecord r : records)
		{
			if (r == null || r.getSlot() == null || r.getState().isTerminal())
			{
				continue;
			}
			observe(OfferIdentity.of(r.getSlot(), r.getItemId(), r.isBuy(), generationFor(r.getSlot())),
				r.getFilledQuantity(), r.getSpent());
		}
	}

	/**
	 * Fold restored marks in, keeping the higher of each pair. Never replaces: a snapshot
	 * written before the current session's fills would otherwise rewind them, and the next
	 * observation would re-report fills already sent.
	 */
	public synchronized void mergeFrom(Map<String, long[]> restored)
	{
		if (restored == null)
		{
			return;
		}
		for (Map.Entry<String, long[]> entry : restored.entrySet())
		{
			long[] incoming = entry.getValue();
			if (incoming == null || incoming.length < 2)
			{
				continue;
			}
			if (entry.getKey().startsWith(GENERATION_KEY_PREFIX))
			{
				restoreGeneration(entry.getKey(), incoming[FILLED]);
				continue;
			}
			long[] current = marks.get(entry.getKey());
			if (current == null)
			{
				marks.put(entry.getKey(), new long[]{incoming[FILLED], incoming[SPENT]});
				continue;
			}
			marks.put(entry.getKey(), new long[]{
				Math.max(current[FILLED], incoming[FILLED]),
				Math.max(current[SPENT], incoming[SPENT])
			});
		}
	}

	/** Adopt a persisted slot generation, keeping the later one so a slot never rewinds. */
	private void restoreGeneration(String key, long persisted)
	{
		try
		{
			int slot = Integer.parseInt(key.substring(GENERATION_KEY_PREFIX.length()));
			slotGeneration.put(slot, Math.max(generationFor(slot), (int) persisted));
		}
		catch (NumberFormatException e)
		{
			// A malformed key is not worth failing a restore over; the slot keeps its default.
		}
	}
}

package com.flipsmart.trading;

import com.flipsmart.util.GeTax;

/**
 * Market-based metrics for an active-flip card row (margin, ROI, profit potential,
 * total tax, break-even position). Pure: a function of the supplied prices and
 * quantities, independent of Swing state.
 */
public final class ActiveFlipCardMetrics
{
	public static final class Result
	{
		public final long margin;
		public final double roi;
		public final long totalTax;
		public final long positionNetPerUnit;

		Result(long margin, double roi, long totalTax, long positionNetPerUnit)
		{
			this.margin = margin;
			this.roi = roi;
			this.totalTax = totalTax;
			this.positionNetPerUnit = positionNetPerUnit;
		}
	}

	private ActiveFlipCardMetrics()
	{
	}

	/**
	 * @param low             current market low (instant-buy target)
	 * @param high            current market high (instant-sell target)
	 * @param itemId          item id, for the GE tax-exempt list
	 * @param averageBuyPrice player's average buy price for the flip
	 * @param realizedSoldQuantity units already sold and realized this flip
	 * @param remainingQuantity    units still held (flip.getTotalQuantity())
	 */
	public static Result compute(long low, long high, int itemId, long averageBuyPrice,
		int realizedSoldQuantity, int remainingQuantity)
	{
		long margin = high - low;
		double roi = low > 0 ? (margin * 100.0) / low : 0.0;
		long fullQuantity = (long) realizedSoldQuantity + remainingQuantity;
		int perItemTax = GeTax.taxFor(itemId, high);
		long totalTax = (long) perItemTax * fullQuantity;
		long positionNetPerUnit = high - averageBuyPrice - perItemTax;

		return new Result(margin, roi, totalTax, positionNetPerUnit);
	}
}

package com.flipsmart.trading;

import com.flipsmart.domain.offer.OfferRecord;
import com.flipsmart.domain.offer.OfferSignal;

import java.util.ArrayList;
import java.util.List;

/** Pure reconciliation of persisted offers against the live GE slots on login/reload. */
public final class OfferReconciler
{
    private OfferReconciler() {}

    public static final class Plan
    {
        public final List<OfferRecord> reattached = new ArrayList<>();
        public final List<OfferSignal> minted = new ArrayList<>();
        public final List<OfferRecord> offlineCollected = new ArrayList<>();
    }

    /**
     * A non-terminal record no live slot claims is an offer that completed while we were not
     * watching. There is deliberately no timestamp gate on that: a record's last-activity is when
     * the plugin last <em>observed</em> a change, and an offline fill is by definition a change it
     * did not observe, so the timestamp can only ever say "older than the last sync". Whether a
     * record has already been offered for backfill is answered by terminalising it once offered,
     * not by comparing clocks.
     */
    public static Plan reconcile(List<OfferRecord> persisted, List<OfferSignal> liveSlots, long now)
    {
        Plan plan = new Plan();
        List<OfferRecord> remaining = new ArrayList<>(persisted);

        for (OfferSignal live : liveSlots)
        {
            OfferRecord match = null;
            for (OfferRecord p : remaining)
            {
                if (matches(p, live))
                {
                    match = p;
                    break;
                }
            }
            if (match != null)
            {
                remaining.remove(match);
                plan.reattached.add(match.withSlot(live.slot));
            }
            else
            {
                plan.minted.add(live);
            }
        }
        // Terminal (collected/cancelled-empty) records are already-reconciled history, not
        // offline fills — including them re-flagged the whole backlog every login (false nag).
        for (OfferRecord r : remaining)
        {
            if (r.getState().isTerminal())
            {
                continue;
            }
            plan.offlineCollected.add(r);
        }
        return plan;
    }

    private static boolean matches(OfferRecord p, OfferSignal live)
    {
        // Identity is the live slot's (slot, item, direction) — NOT its mutable
        // totalQuantity/price. The order's total and price legitimately drift
        // (partial buys re-read a different total, a relist changes price), and
        // requiring them to be equal made a still-live record fail to reattach:
        // a fresh baseline-0 record then re-posted the whole cumulative on top of
        // fills already recorded, a ~40% buy over-count. Terminal
        // records are finished history — a live slot showing their item is a
        // reused slot holding a new offer, so they never reattach.
        return !p.getState().isTerminal()
            && p.getSlot() != null
            && p.getSlot() == live.slot
            && p.getItemId() == live.itemId
            && p.isBuy() == live.isBuy();
    }
}

package com.flipsmart.trading;

import com.flipsmart.domain.offer.OfferRecord;
import com.flipsmart.domain.offer.OfferSignal;
import com.flipsmart.domain.offer.OfferState;
import com.flipsmart.domain.offer.OfferTransition;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GrandExchangeOfferState;

/** Pure offer lifecycle transitions. The only place offer state is decided. */
@Slf4j
public final class OfferStateMachine
{
    private OfferStateMachine() {}

    /**
     * Pure transition function. {@code current} is null when the slot has no known offer (new placement).
     * Returns the resulting {@link com.flipsmart.domain.offer.OfferTransition}; never mutates its arguments.
     */
    public static OfferTransition decide(OfferRecord current, OfferSignal signal, long offerIdForNew, long now)
    {
        final GrandExchangeOfferState ge = signal.geState;

        if (current == null)
        {
            // With no tracked offer for this slot, only a genuinely-live GE state may mint a record.
            // EMPTY or a cancelled slot (CANCELLED_BUY/CANCELLED_SELL, still reported until the GP or
            // items are collected) is a finished offer — minting a live record from it (e.g. a
            // render-tick reseed observing a cancelled-but-uncollected slot) would fabricate a
            // phantom that can never be terminalized and lingers in the live set.
            if (ge == GrandExchangeOfferState.EMPTY
                || ge == GrandExchangeOfferState.CANCELLED_BUY
                || ge == GrandExchangeOfferState.CANCELLED_SELL)
            {
                return OfferTransition.of(OfferTransition.Kind.NONE, null, 0);
            }
            OfferRecord placed = OfferRecord.newOffer(offerIdForNew, signal.slot, signal.itemId,
                signal.itemName, signal.isBuy(), signal.totalQuantity, signal.price, now);
            if (signal.quantitySold > 0 || ge == GrandExchangeOfferState.BOUGHT || ge == GrandExchangeOfferState.SOLD)
            {
                return applyFillOrComplete(placed, signal, now, OfferTransition.Kind.PLACED);
            }
            return OfferTransition.of(OfferTransition.Kind.PLACED, placed, 0);
        }

        if (current.getState().isTerminal())
        {
            return OfferTransition.rejected(current);
        }

        switch (ge)
        {
            case BUYING:
            case SELLING:
            case BOUGHT:
            case SOLD:
                return applyFillOrComplete(current, signal, now, null);

            case CANCELLED_BUY:
            case CANCELLED_SELL:
            {
                int residual = Math.max(signal.quantitySold - current.getFilledQuantity(), 0);
                long residualSpent = Math.max(signal.spent - current.getSpent(), 0);
                OfferState target = signal.quantitySold > 0
                    ? OfferState.CANCELLED_PARTIAL : OfferState.CANCELLED_EMPTY;
                OfferRecord updated = residual > 0
                    ? current.withFill(signal.quantitySold, signal.spent, target, now)
                    : current.withState(target, now);
                return OfferTransition.of(OfferTransition.Kind.CANCELLED, updated, residual, residualSpent);
            }

            case EMPTY:
                if (current.getState() == OfferState.FILLED
                    || current.getState() == OfferState.PARTIAL_FILL
                    || current.getState() == OfferState.CANCELLED_PARTIAL)
                {
                    return OfferTransition.of(OfferTransition.Kind.COLLECTED,
                        current.withState(OfferState.COLLECTED, now), 0);
                }
                return OfferTransition.rejected(current);

            default:
                log.warn("Unhandled GE state {} for offer {}", ge, current.getOfferId());
                return OfferTransition.rejected(current);
        }
    }

    private static OfferTransition applyFillOrComplete(OfferRecord base, OfferSignal signal, long now,
                                                       OfferTransition.Kind newOverride)
    {
        int delta = signal.quantitySold - base.getFilledQuantity();
        boolean complete = signal.geState == GrandExchangeOfferState.BOUGHT
            || signal.geState == GrandExchangeOfferState.SOLD
            || signal.quantitySold >= signal.totalQuantity;
        OfferState target = complete ? OfferState.FILLED
            : (signal.quantitySold > 0 ? OfferState.PARTIAL_FILL : OfferState.NEW);

        if (delta <= 0 && target == base.getState())
        {
            return OfferTransition.of(OfferTransition.Kind.NONE, base, 0);
        }
        long newlySpent = Math.max(signal.spent - base.getSpent(), 0);
        OfferRecord updated = base.withFill(signal.quantitySold, signal.spent, target, now);
        OfferTransition.Kind kind = complete ? OfferTransition.Kind.COMPLETED
            : (newOverride != null ? newOverride : OfferTransition.Kind.FILLED_DELTA);
        return OfferTransition.of(kind, updated, Math.max(delta, 0), newlySpent);
    }
}

package com.flipsmart.trading;

import com.flipsmart.domain.offer.OfferRecord;
import com.flipsmart.domain.offer.OfferSignal;
import com.flipsmart.domain.offer.OfferState;
import com.flipsmart.domain.offer.OfferTransition;

import net.runelite.api.GrandExchangeOfferState;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Consumer;

import javax.inject.Singleton;


/**
 * Single source of truth for offer state. Keyed by a monotonic offerId; indexed by slot
 * (event resolution) and item (consumer queries). The sole writer of offer state.
 * Thread-safe: every compound mutation runs under this monitor; reads return snapshots.
 * Listeners are notified after the monitor is released so a slow listener cannot stall readers.
 */
@Singleton
public final class OfferStore
{
    private final Map<Long, OfferRecord> byOfferId = new HashMap<>();
    private final Map<Integer, Long> slotToOfferId = new HashMap<>();   // 0..7 -> offerId (live only)
    private long nextOfferId = 1;
    private final List<Consumer<OfferEvent>> listeners = new ArrayList<>();
    private final FillWatermarks fillWatermarks = new FillWatermarks();

    /** The high-water fill marks backing every reported delta. Persisted alongside the records. */
    public FillWatermarks watermarks()
    {
        return fillWatermarks;
    }

    /** The id the next minted offer will take. Persisted so pruning cannot recycle ids. */
    public synchronized long nextOfferId()
    {
        return nextOfferId;
    }

    /**
     * Raise the counter to at least {@code candidate}, e.g. from a persisted high-water mark.
     * Never lowers it, so restoring a stale value cannot reintroduce a collision.
     */
    public synchronized void raiseNextOfferId(long candidate)
    {
        nextOfferId = Math.max(nextOfferId, candidate);
    }

    /** Register a listener to receive an {@link OfferEvent} after each successful state change. */
    public synchronized void addListener(Consumer<OfferEvent> listener)
    {
        listeners.add(listener);
    }

    /**
     * Apply {@code signal} to the current offer for its slot, delegating to
     * {@link OfferStateMachine#decide decide()} for the transition. Notifies listeners after
     * the monitor is released. Returns the transition (including REJECTED/NONE) for the caller.
     */
    public OfferTransition apply(OfferSignal signal, long now)
    {
        OfferTransition t;
        OfferEvent event;
        List<Consumer<OfferEvent>> snapshot;
        synchronized (this)
        {
            Long currentId = slotToOfferId.get(signal.slot);
            OfferRecord current = currentId == null ? null : byOfferId.get(currentId);

            // A directional signal only belongs to the slot's record if it is the SAME order:
            // same item and same direction. A different item or side means the slot turned over
            // without us observing the collect (an offline/mobile collect, or a missed EMPTY),
            // so the record still sitting in the slot is stale. Feeding the signal into it would
            // stamp the new offer's fills — and its price — onto the old item. Evict the stale
            // occupant here so the transition below mints a fresh record for the new order.
            // EMPTY is the only state exempt: it carries no item/direction of its own and
            // legitimately targets the existing record to terminalise it via collect.
            boolean staleOccupant = current != null
                && carriesOfferIdentity(signal.geState)
                && (current.getItemId() != signal.itemId || current.isBuy() != signal.isBuy());

            if (staleOccupant)
            {
                byOfferId.put(current.getOfferId(), current.withSlot(null));
                slotToOfferId.remove(signal.slot);
            }

            OfferRecord effectiveCurrent = staleOccupant ? null : current;

            long idForNew = effectiveCurrent == null ? nextOfferId : effectiveCurrent.getOfferId();
            t = OfferStateMachine.decide(effectiveCurrent, signal, idForNew, now);

            if (t.kind == OfferTransition.Kind.REJECTED || t.kind == OfferTransition.Kind.NONE || t.record == null)
            {
                return t;
            }

            if (effectiveCurrent == null)
            {
                nextOfferId = Math.max(nextOfferId, t.record.getOfferId() + 1);
            }

            byOfferId.put(t.record.getOfferId(), t.record);
            if (t.record.getSlot() == null)
            {
                slotToOfferId.remove(signal.slot);
            }
            else
            {
                slotToOfferId.put(signal.slot, t.record.getOfferId());
            }

            // What the signal newly revealed, measured against the highest cumulative ever seen
            // for this order rather than against the record. The record can be rewound by a
            // reconcile against a stale snapshot; the mark cannot. Direction comes from the
            // record because a collect arrives as EMPTY, which reads as neither buy nor sell.
            int generation = fillWatermarks.generationFor(signal.slot);
            OfferIdentity identity = OfferIdentity.of(
                signal.slot, t.record.getItemId(), t.record.isBuy(), generation);
            FillWatermarks.Delta delta = fillWatermarks.observe(identity, signal.quantitySold, signal.spent);

            if (t.record.getState().isTerminal())
            {
                fillWatermarks.advanceGeneration(signal.slot);
            }

            event = new OfferEvent(t.kind, t.record, delta.quantity, delta.spent, generation);
            snapshot = new ArrayList<>(listeners);
        }

        for (Consumer<OfferEvent> l : snapshot)
        {
            l.accept(event);
        }
        return t;
    }

    /**
     * A GE state that reports an item and a side, as opposed to EMPTY, which reports neither.
     * Includes cancellations: a cancelled slot still names the item and direction it cancelled,
     * so a mismatch against the tracked order means it belongs to a different offer entirely.
     */
    private static boolean carriesOfferIdentity(GrandExchangeOfferState state)
    {
        return state == GrandExchangeOfferState.BUYING
            || state == GrandExchangeOfferState.SELLING
            || state == GrandExchangeOfferState.BOUGHT
            || state == GrandExchangeOfferState.SOLD
            || state == GrandExchangeOfferState.CANCELLED_BUY
            || state == GrandExchangeOfferState.CANCELLED_SELL;
    }

    /** Live offer currently occupying {@code slot} (0–7), or {@code null} if the slot is empty. */
    public synchronized OfferRecord bySlot(int slot)
    {
        Long id = slotToOfferId.get(slot);
        return id == null ? null : byOfferId.get(id);
    }

    /** All records (live and terminal) for {@code itemId}, as an unmodifiable snapshot. */
    public synchronized List<OfferRecord> forItem(int itemId)
    {
        List<OfferRecord> out = new ArrayList<>();
        for (OfferRecord r : byOfferId.values())
        {
            if (r.getItemId() == itemId)
            {
                out.add(r);
            }
        }
        return Collections.unmodifiableList(out);
    }

    /** All records known to the store (live and terminal), as an unmodifiable snapshot. */
    public synchronized List<OfferRecord> allRecords()
    {
        return Collections.unmodifiableList(new ArrayList<>(byOfferId.values()));
    }

    /** Snapshot of every record for persistence. */
    public synchronized List<OfferRecord> export()
    {
        return new ArrayList<>(byOfferId.values());
    }

    /**
     * Replace all state with {@code records} (e.g. restored from persistence),
     * rebuilding the slot index for live records and raising the id counter
     * above the largest imported offerId so subsequent offers cannot collide.
     * The counter only ever moves forward: an import is routinely lossy — the
     * login reconcile drops terminal records past the retention window, and it
     * runs on every world hop, not just login — so assigning from the surviving
     * maximum would let the counter regress and hand a fresh offer an ID the backend
     * still holds fills under.
     */
    public synchronized void importRecords(List<OfferRecord> records)
    {
        byOfferId.clear();
        slotToOfferId.clear();
        long maxId = 0;
        for (OfferRecord r : records)
        {
            byOfferId.put(r.getOfferId(), r);
            if (r.getSlot() != null && !r.getState().isTerminal())
            {
                slotToOfferId.put(r.getSlot(), r.getOfferId());
            }
            maxId = Math.max(maxId, r.getOfferId());
        }
        nextOfferId = Math.max(nextOfferId, maxId + 1);
        // A record entering the store carries progress that has already been reported. Raising the
        // marks to match keeps the next observation measuring the increment rather than re-reporting
        // the whole cumulative.
        fillWatermarks.seedFrom(records);
    }

    /**
     * Records that still occupy a GE slot (state is non-terminal). Terminal
     * records (collected / cancelled-empty) are retained by the store but
     * excluded here, matching the live-only view the session offer map exposed.
     */
    public synchronized List<OfferRecord> liveOffers()
    {
        List<OfferRecord> out = new ArrayList<>();
        for (OfferRecord r : byOfferId.values())
        {
            if (!r.getState().isTerminal())
            {
                out.add(r);
            }
        }
        return Collections.unmodifiableList(out);
    }

    /**
     * A sell offer for {@code itemId} is currently live (occupies a GE slot).
     * Terminal records (collected / cancelled-empty) are ignored so a finished
     * lifecycle never reports as an active slot.
     */
    public synchronized boolean hasActiveSellOfferForItem(int itemId)
    {
        for (OfferRecord r : byOfferId.values())
        {
            if (r.getItemId() == itemId && !r.isBuy() && !r.getState().isTerminal())
            {
                return true;
            }
        }
        return false;
    }

    /**
     * A buy offer for {@code itemId} is live — either still filling or filled but
     * not yet collected. Mirrors the union of the session's in-flight and
     * uncollected buy predicates: any non-terminal buy record qualifies, since a
     * collected buy is terminal and a freshly-collected slot is freed.
     */
    public synchronized boolean hasLiveBuyOfferForItem(int itemId)
    {
        for (OfferRecord r : byOfferId.values())
        {
            if (r.getItemId() == itemId && r.isBuy() && !r.getState().isTerminal())
            {
                return true;
            }
        }
        return false;
    }

    /**
     * Quantity already sold across live (non-terminal) sell offers for {@code itemId}.
     * Lets a consumer value only the unsold remainder of a partially-filled sell; terminal
     * records are excluded because their fills have left the open position entirely.
     */
    public int liveSellFilledQuantity(int itemId)
    {
        synchronized (this)
        {
            int sum = 0;
            for (OfferRecord r : byOfferId.values())
            {
                if (r.getItemId() == itemId && !r.isBuy() && !r.getState().isTerminal())
                {
                    sum += r.getFilledQuantity();
                }
            }
            return sum;
        }
    }

    /**
     * Replace the createdAt timestamp of the record with {@code offerId}, preserving
     * its slot index. No-op when the offerId is unknown. Used to backfill a missing
     * placement time from an authoritative external source (e.g. backend active flips).
     */
    public synchronized void correctCreatedAt(long offerId, long millis)
    {
        OfferRecord current = byOfferId.get(offerId);
        if (current == null)
        {
            return;
        }
        byOfferId.put(offerId, current.withCreatedAtMillis(millis));
    }

    /**
     * Replace the last-activity timestamp of the record with {@code offerId}. No-op when
     * the offerId is unknown. Used on relog to restore an offer's true age after the live
     * record was re-anchored to login time.
     */
    public synchronized void correctActivityAt(long offerId, long millis)
    {
        OfferRecord current = byOfferId.get(offerId);
        if (current == null)
        {
            return;
        }
        byOfferId.put(offerId, current.withActivityAtMillis(millis));
    }

    /**
     * Records with collectable fills awaiting a GE collect action: fully filled
     * (FILLED) or partially-cancelled (CANCELLED_PARTIAL). Matches the prior
     * getCompletedOffers behaviour so the "collect profit" prompt fires for both.
     */
    public synchronized List<OfferRecord> completedAwaitingCollection()
    {
        List<OfferRecord> out = new ArrayList<>();
        for (OfferRecord r : byOfferId.values())
        {
            if (r.getState() == OfferState.FILLED || r.getState() == OfferState.CANCELLED_PARTIAL)
            {
                out.add(r);
            }
        }
        return Collections.unmodifiableList(out);
    }
}

package com.flipsmart.trading;

import com.flipsmart.domain.offer.OfferRecord;

import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import javax.inject.Singleton;

/**
 * Zero-crossing round-trip id ledger, keyed by (rsn, itemId).
 *
 * Tracks the running held quantity the plugin has observed (buys minus sells) and
 * assigns a monotonic id to every fill between two zero-crossings, so the backend can
 * match a sell to buys strictly within one round trip instead of across unrelated
 * same-item positions. A full or over liquidation (held quantity returns to zero or
 * below) closes the current cycle; whatever follows starts a new one.
 *
 * The cycle id is deliberately item-scoped (not slot-scoped) so a round trip that spans
 * several GE slots still matches. Slot is used only as a guard: a duplicate/phantom fill
 * that repeats the exact fill which just closed a cycle is ignored so it cannot prematurely
 * advance the cycle and poison the round-trip id of every later real fill.
 */
@Singleton
public final class RoundTripLedger
{
    private static final int INITIAL_CYCLE_ID = 1;

    /** Per-(rsn, itemId) state: quantity currently held, the active cycle id, and the cumulative
     *  already absorbed for the current offer on each GE slot. */
    public static final class Entry
    {
        public int heldQuantity;
        public int cycleId;

        /**
         * Buy-side quantity and outlay accumulated for the CURRENT cycle, zeroed when it closes.
         * Scoping them to the cycle is what keeps a cost basis from averaging across positions the
         * player has already fully liquidated.
         */
        public int boughtQuantity;
        public long boughtSpent;

        /**
         * Cumulative filled quantity already folded into {@code heldQuantity} for the offer currently
         * on each (slot, direction), keyed by {@code slot * 2 + (isBuy ? 1 : 0)}. PERSISTED: on relog
         * the login reconciliation re-feeds an open offer's full current cumulative, and matching it
         * against the persisted absorbed cumulative lets the ledger recognise it as already-absorbed
         * and apply a zero delta instead of double-counting. Deliberately offer-id-AGNOSTIC — a relog
         * mints a fresh offer_id for the same slot, so keying on offer_id would miss the re-feed.
         * Direction is part of the key because a buy and a sell reuse the same slot with independent
         * cumulatives. A slot's entry is reset when that slot's own offer completes (not on cycle
         * close), so a still-filling sibling slot keeps its baseline. Lazily created so old persisted
         * blobs deserialize.
         */
        public Map<Integer, Integer> absorbedBySlotDir;

        /**
         * Fingerprint (slot:isBuy:cumulative) of the fill that most recently closed a cycle, or null
         * when the current position is open. Session-local ({@code transient}): it catches a
         * re-delivery of the closing fill even after that slot's {@link #absorbedBySlotDir} baseline
         * was reset on offer completion — a Collect re-detect. Direction keeps a genuine new lot, which
         * opens the next cycle in the opposite direction, from being falsely suppressed.
         */
        public transient String lastClosingFingerprint;

        public Entry()
        {
        }

        public Entry(int heldQuantity, int cycleId)
        {
            this.heldQuantity = heldQuantity;
            this.cycleId = cycleId;
        }
    }

    /** Outcome of a guarded fill: the round-trip id, and whether the fill was a suppressed
     *  duplicate the caller should not forward. */
    public static final class FillResult
    {
        public final Integer roundTripId;
        public final boolean duplicateSuppressed;

        /**
         * Quantity actually folded into held, which is not always what the caller passed — a
         * slot-keyed fill rebaselines against what that slot has already absorbed. Cost basis
         * must follow this number, or the money would describe a different number of items.
         */
        public final int foldedQuantity;

        public FillResult(Integer roundTripId, boolean duplicateSuppressed, int foldedQuantity)
        {
            this.roundTripId = roundTripId;
            this.duplicateSuppressed = duplicateSuppressed;
            this.foldedQuantity = foldedQuantity;
        }
    }

    private final Object lock = new Object();
    private final Map<String, Map<Integer, Entry>> byRsn = new HashMap<>();

    /**
     * Slot-unaware overload retained for round-trip accounting that has no GE slot to key on
     * (and for tests exercising pure zero-crossing semantics). Applies no duplicate-fill guard.
     */
    public Integer recordFill(String rsn, int itemId, boolean isBuy, int deltaQuantity)
    {
        return recordFill(rsn, itemId, null, isBuy, deltaQuantity, 0, false);
    }

    /**
     * Apply a fill for (rsn, itemId) and return the round-trip id it belongs to. Returns {@code null}
     * when {@code rsn} can't be resolved — the caller sends no id in that case rather than guess.
     *
     * The cycle id stays item-scoped so the backend can still match a sell to buys of the same item
     * across whichever GE slots the round trip happened to use. For a slot-keyed fill the quantity
     * folded into held is derived from {@code cumulativeQuantity} against what's already absorbed for
     * that {@code (slot, direction)}, so a re-fed or duplicate cumulative is idempotent (see
     * {@link #recordFillGuarded}). Passing a null {@code slot} keeps the legacy delta-based path.
     */
    public Integer recordFill(String rsn, int itemId, Integer slot, boolean isBuy,
                              int deltaQuantity, int cumulativeQuantity, boolean offerComplete)
    {
        return recordFillGuarded(rsn, itemId, slot, isBuy, deltaQuantity, cumulativeQuantity, offerComplete).roundTripId;
    }

    /**
     * As {@link #recordFill(String, int, Integer, boolean, int, int, boolean)} but also reports whether the
     * fill was recognised as an already-absorbed re-delivery and suppressed.
     *
     * <p>For a slot-keyed fill the delta folded into {@code heldQuantity} is derived from the offer's
     * {@code cumulativeQuantity} against the cumulative already absorbed for that {@code (slot,
     * direction)} — NOT from the caller's {@code deltaQuantity}. This makes held idempotent to a
     * re-fed cumulative: on relog the login reconciliation re-feeds an open offer's full current
     * cumulative (the rebuilt OfferStore has no baseline, so the GE signal looks like one big fresh
     * fill), and without this the ledger would add it on top of the already-restored held, permanently
     * biasing held so it never returns to zero, freezing the round-trip cycle and consolidating
     * unrelated same-item positions. A cumulative equal to what's already absorbed is a re-feed and is
     * suppressed; a lower cumulative is a fresh offer reusing the slot and rebaselines to it.
     *
     * <p>Passing a null {@code slot} keeps the legacy delta-based path (no cumulative tracking) for
     * round-trip accounting that has no GE slot to key on and for tests exercising pure zero-crossing.
     */
    public FillResult recordFillGuarded(String rsn, int itemId, Integer slot, boolean isBuy,
                                        int deltaQuantity, int cumulativeQuantity, boolean offerComplete)
    {
        synchronized (lock)
        {
            if (rsn == null || rsn.isEmpty())
            {
                return new FillResult(null, false, 0);
            }
            Entry e = entryFor(rsn, itemId);

            // Guard for a re-delivery of the fill that just CLOSED the cycle after the absorbed map was
            // cleared on close — a Collect re-detect. Direction keeps a genuine opposite-side new lot
            // from being suppressed.
            String fingerprint = slot == null ? null : slot + ":" + isBuy + ":" + cumulativeQuantity;
            if (fingerprint != null && fingerprint.equals(e.lastClosingFingerprint))
            {
                return new FillResult(e.cycleId, true, 0);
            }

            int effectiveDelta;
            if (slot == null)
            {
                effectiveDelta = deltaQuantity;
            }
            else
            {
                if (e.absorbedBySlotDir == null)
                {
                    e.absorbedBySlotDir = new HashMap<>();
                }
                int key = slot * 2 + (isBuy ? 1 : 0);
                int absorbed = e.absorbedBySlotDir.getOrDefault(key, 0);
                if (cumulativeQuantity == absorbed)
                {
                    // Exactly the cumulative already folded in for this (slot, direction): a relog
                    // re-feed or a duplicate re-delivery. Fold nothing; tell the caller not to forward.
                    return new FillResult(e.cycleId, true, 0);
                }
                // A lower cumulative means a fresh offer reused the slot (fills restart at 0), so its
                // whole cumulative is new; a higher one is genuine incremental progress on this offer.
                effectiveDelta = cumulativeQuantity > absorbed ? cumulativeQuantity - absorbed : cumulativeQuantity;
                e.absorbedBySlotDir.put(key, cumulativeQuantity);
            }

            int heldBefore = e.heldQuantity;
            e.heldQuantity += isBuy ? effectiveDelta : -effectiveDelta;
            int roundTripId = e.cycleId;
            // Advance the cycle only on a genuine positive->zero crossing. If held was already zero — a
            // fully-liquidated position still receiving sell fills (overselling externally-sourced stock,
            // or a ledger drifted low) — don't re-close on every fill and run the cycle away.
            boolean closed = heldBefore > 0 && e.heldQuantity <= 0;
            if (e.heldQuantity <= 0)
            {
                e.heldQuantity = 0;
            }
            if (closed)
            {
                e.cycleId++;
                // The position is gone, so its cost basis goes with it — otherwise the next cycle
                // would inherit the average of stock that has already been sold.
                e.boughtQuantity = 0;
                e.boughtSpent = 0L;
                e.lastClosingFingerprint = fingerprint;
            }
            else
            {
                e.lastClosingFingerprint = null;
            }
            // Reset THIS slot's baselines once its own offer is done filling (COMPLETED / CANCELLED),
            // so the next offer reusing the slot rebaselines from zero even at a coincidentally-equal
            // cumulative. Sibling slots are deliberately left intact: a same-item offer still filling in
            // another slot must keep its baseline, or its next fill would re-count its whole cumulative
            // instead of just the increment when held momentarily crosses zero. Resetting on offer
            // completion rather than on cycle close is what distinguishes a finished slot from a
            // still-open sibling — the ledger has no per-slot open/closed view otherwise.
            if (offerComplete && slot != null && e.absorbedBySlotDir != null)
            {
                e.absorbedBySlotDir.remove(slot * 2);
                e.absorbedBySlotDir.remove(slot * 2 + 1);
            }
            return new FillResult(roundTripId, false, effectiveDelta);
        }
    }

    /**
     * Fold a buy's quantity and outlay into the current cycle's cost basis.
     *
     * <p>Takes a per-item price rather than a total so the money always corresponds to the
     * quantity actually folded in: {@link #recordFillGuarded} may rebaseline a fill's quantity
     * against what a slot has already absorbed, and a separately-supplied total would then
     * describe a different number of items than the one recorded.</p>
     *
     * <p>A non-positive price contributes nothing — a placement row carries no price, and folding
     * it in would drag the average toward zero.</p>
     */
    public void recordBuyBasis(String rsn, int itemId, int quantity, long pricePerItem)
    {
        if (rsn == null || rsn.isEmpty() || quantity <= 0 || pricePerItem <= 0)
        {
            return;
        }
        synchronized (lock)
        {
            Entry e = entryFor(rsn, itemId);
            e.boughtQuantity += quantity;
            e.boughtSpent += quantity * pricePerItem;
        }
    }

    /**
     * Quantity the player is currently observed to hold for (rsn, itemId). Zero when the position
     * is closed or unknown. Lets callers ask whether anything still depends on an item's history.
     */
    public int heldQuantity(String rsn, int itemId)
    {
        if (rsn == null || rsn.isEmpty())
        {
            return 0;
        }
        synchronized (lock)
        {
            return entryFor(rsn, itemId).heldQuantity;
        }
    }

    /**
     * Quantity-weighted average buy price for the OPEN cycle, or {@code null} when it has taken
     * no priced buys. Because a closed cycle's basis is cleared, this can never average across a
     * position the player has already liquidated.
     */
    public Long currentBasis(String rsn, int itemId)
    {
        if (rsn == null || rsn.isEmpty())
        {
            return null;
        }
        synchronized (lock)
        {
            Entry e = entryFor(rsn, itemId);
            if (e.boughtQuantity <= 0)
            {
                return null;
            }
            return Math.round(e.boughtSpent / (double) e.boughtQuantity);
        }
    }

    /**
     * The current round-trip id for (rsn, itemId) without mutating held quantity. Used to
     * stamp zero-fill placement rows so they carry the same id their eventual fills will.
     */
    public Integer peekRoundTripId(String rsn, int itemId)
    {
        synchronized (lock)
        {
            if (rsn == null || rsn.isEmpty())
            {
                return null;
            }
            return entryFor(rsn, itemId).cycleId;
        }
    }

    private Entry entryFor(String rsn, int itemId)
    {
        return byRsn.computeIfAbsent(rsn, k -> new HashMap<>())
            .computeIfAbsent(itemId, k -> new Entry(0, INITIAL_CYCLE_ID));
    }

    /**
     * Snapshot of every itemId -> Entry tracked for {@code rsn}, for persistence. Entries are
     * deep-copied so a later mutation via {@link #recordFill} can't race with serialization of
     * this snapshot on another thread.
     */
    public Map<Integer, Entry> export(String rsn)
    {
        synchronized (lock)
        {
            Map<Integer, Entry> existing = byRsn.get(rsn);
            if (existing == null)
            {
                return Collections.emptyMap();
            }
            Map<Integer, Entry> copy = new HashMap<>();
            for (Map.Entry<Integer, Entry> entry : existing.entrySet())
            {
                Entry source = entry.getValue();
                Entry clone = new Entry(source.heldQuantity, source.cycleId);
                // The open cycle's basis travels with the position it describes; a restored
                // position without it falls back to averaging across already-closed flips.
                clone.boughtQuantity = source.boughtQuantity;
                clone.boughtSpent = source.boughtSpent;
                if (source.absorbedBySlotDir != null)
                {
                    clone.absorbedBySlotDir = new HashMap<>(source.absorbedBySlotDir);
                }
                copy.put(entry.getKey(), clone);
            }
            return copy;
        }
    }

    /** True when no state has ever been recorded for {@code rsn} (cold start / first run). */
    public boolean isEmpty(String rsn)
    {
        synchronized (lock)
        {
            return rsn == null || !byRsn.containsKey(rsn);
        }
    }

    /** Replace all state for {@code rsn} with {@code entries} (e.g. restored from persistence). */
    public void importState(String rsn, Map<Integer, Entry> entries)
    {
        synchronized (lock)
        {
            if (rsn == null || rsn.isEmpty() || entries == null || entries.isEmpty())
            {
                return;
            }
            byRsn.put(rsn, new HashMap<>(entries));
        }
    }

    /**
     * Conservative cold-start seed, applied only when {@code rsn} has no ledger state at
     * all — a genuine first run, e.g. this feature shipping to an account that already has
     * an open GE position. Seeds held quantity per item from currently-live unmatched buy
     * fills so the next sell of that pre-existing position doesn't collide with a fresh
     * cycle that has never seen it.
     */
    public void seedColdStart(String rsn, List<OfferRecord> liveUnmatchedBuys)
    {
        synchronized (lock)
        {
            if (rsn == null || rsn.isEmpty() || !isEmpty(rsn) || liveUnmatchedBuys == null || liveUnmatchedBuys.isEmpty())
            {
                return;
            }
            Map<Integer, Entry> seeded = seedMapFrom(liveUnmatchedBuys);
            if (!seeded.isEmpty())
            {
                byRsn.put(rsn, seeded);
            }
        }
    }

    private static Map<Integer, Entry> seedMapFrom(List<OfferRecord> liveUnmatchedBuys)
    {
        Map<Integer, Entry> seeded = new HashMap<>();
        for (OfferRecord r : liveUnmatchedBuys)
        {
            if (!r.isBuy() || r.getFilledQuantity() <= 0)
            {
                continue;
            }
            Entry e = seeded.computeIfAbsent(r.getItemId(), k -> new Entry(0, INITIAL_CYCLE_ID));
            e.heldQuantity += r.getFilledQuantity();
            // Seed the cost basis too, not just the quantity. A seeded position with no basis
            // leaves currentBasis null, which sends breakeven to the never-evicted offer-records
            // fallback that averages across already-sold lots.
            e.boughtQuantity += r.getFilledQuantity();
            e.boughtSpent += r.getSpent();
        }
        return seeded;
    }
}

