/**
 * Tracks the lifecycle of active flips: mark sold, auto-close,
 * stale flip cleanup, and inventory quantity validation.
 */
@Slf4j
@Singleton
public class ActiveFlipTracker
{
	private static final int INVENTORY_CONTAINER_ID = 93;

	private final PlayerSession session;
	private final FlipSmartApiClient apiClient;
	private final Client client;
	private final ClientThread clientThread;
	private final ItemManager itemManager;
	private final OfferStore offerStore;

	@Setter
	private Runnable onPanelRefreshNeeded;
	@Setter
	private Runnable onActiveFlipsRefreshNeeded;

	@Inject
	public ActiveFlipTracker(
		PlayerSession session,
		FlipSmartApiClient apiClient,
		Client client,
		ClientThread clientThread,
		ItemManager itemManager,
		OfferStore offerStore)
	{
		this.session = session;
		this.apiClient = apiClient;
		this.client = client;
		this.clientThread = clientThread;
		this.itemManager = itemManager;
		this.offerStore = offerStore;
	}


	/**
	 * Mark an item as sold - removes it from the collected tracking.
	 * Called when a sell transaction is recorded.
	 * Also checks if inventory is empty AND no active GE sell slot for this item,
	 * then auto-closes the active flip.
	 */
	public void markItemSold(int itemId)
	{
		if (session.removeCollectedItem(itemId))
		{
			log.debug("Removed item {} from collected tracking (sold)", itemId);
		}

		if (offerStore.hasActiveSellOfferForItem(itemId))
		{
			log.debug("Item {} still has active sell slot, keeping flip open", itemId);
			return;
		}

		tryAutoCloseFlip(itemId);
	}

	/**
	 * Dismiss an active flip on the backend.
	 * Used by other services when they determine a flip is complete.
	 */
	public void dismissFlip(int itemId)
	{
		apiClient.dismissActiveFlipAsync(itemId, getRsnSafe().orElse(null)).thenAccept(success ->
		{
			if (Boolean.TRUE.equals(success))
			{
				log.debug("Dismissed active flip for item {}", itemId);
				if (onPanelRefreshNeeded != null)
				{
					SwingUtilities.invokeLater(onPanelRefreshNeeded);
				}
			}
		});
	}

	/**
	 * Attempt to auto-close a flip if inventory is empty.
	 */
	private void tryAutoCloseFlip(int itemId)
	{
		int inventoryCount = getInventoryCountForItem(itemId);
		if (inventoryCount > 0)
		{
			return;
		}
		// The store can be transiently empty; read the client GE state directly so we never
		// delete a flip whose offer is still live in a slot.
		if (hasLiveGeOfferForItem(itemId))
		{
			return;
		}

		log.debug("Inventory empty and no active sell slot for item {}, auto-closing active flip", itemId);
		apiClient.dismissActiveFlipAsync(itemId, getRsnSafe().orElse(null)).thenAccept(success ->
		{
			if (Boolean.TRUE.equals(success))
			{
				log.debug("Successfully auto-closed active flip for item {} (no items remaining)", itemId);
				if (onPanelRefreshNeeded != null)
				{
					SwingUtilities.invokeLater(onPanelRefreshNeeded);
				}
			}
		});
	}

	private boolean hasLiveGeOfferForItem(int itemId)
	{
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers == null)
		{
			return false;
		}
		for (GrandExchangeOffer offer : offers)
		{
			if (offer != null && offer.getState() != GrandExchangeOfferState.EMPTY
				&& offer.getItemId() == itemId)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Get the count of a specific item in the player's inventory.
	 * Uses canonicalize to match noted/placeholder variants of the same item.
	 */
	public int getInventoryCountForItem(int itemId)
	{
		ItemContainer inventory = client.getItemContainer(INVENTORY_CONTAINER_ID);
		if (inventory == null)
		{
			return 0;
		}

		int canonicalId = itemManager.canonicalize(itemId);
		int count = 0;
		Item[] items = inventory.getItems();
		for (Item item : items)
		{
			if (item.getId() > 0 && itemManager.canonicalize(item.getId()) == canonicalId)
			{
				count += item.getQuantity();
			}
		}

		return count;
	}

	/**
	 * Clean up stale active flips on the backend.
	 * Sends the list of item IDs that are "truly active" (in GE slots or inventory)
	 * to the API, which will mark all other active flips as closed.
	 */
	public void cleanupStaleActiveFlips()
	{
		clientThread.invokeLater(this::executeStaleFlipCleanup);
	}

	private void executeStaleFlipCleanup()
	{
		Set<Integer> activeItemIds = collectAllActiveItemIds();

		log.debug("Cleaning up stale flips - {} item IDs are truly active", activeItemIds.size());

		apiClient.cleanupStaleFlipsAsync(activeItemIds, getRsnSafe().orElse(null))
			.thenAccept(this::handleCleanupResult);
	}

	private Set<Integer> collectAllActiveItemIds()
	{
		Set<Integer> itemIds = new java.util.HashSet<>();
		for (OfferRecord offer : offerStore.liveOffers())
		{
			itemIds.add(offer.getItemId());
		}
		itemIds.addAll(session.getCollectedItemIds());

		// Also read directly from the game client's GE state as the definitive
		// source of truth. This protects against the race condition where the
		// offer store may not be fully populated from login burst events.
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers != null)
		{
			int addedFromClient = 0;
			for (GrandExchangeOffer offer : offers)
			{
				if (offer != null && offer.getState() != GrandExchangeOfferState.EMPTY
					&& itemIds.add(offer.getItemId()))
				{
					addedFromClient++;
					log.debug("Cleanup safety: item {} found in GE client state but not in tracked offers",
						offer.getItemId());
				}
			}
			if (addedFromClient > 0)
			{
				log.warn("Cleanup safety caught {} items from client GE state that were missing from session tracking",
					addedFromClient);
			}
		}

		return itemIds;
	}

	private void handleCleanupResult(Boolean success)
	{
		if (Boolean.TRUE.equals(success))
		{
			log.debug("Stale flip cleanup completed successfully");
			if (onActiveFlipsRefreshNeeded != null)
			{
				SwingUtilities.invokeLater(onActiveFlipsRefreshNeeded);
			}
		}
	}

	/**
	 * Validate inventory quantities against active flips and sync down if needed.
	 * Must be called on client thread.
	 */
	public void validateInventoryQuantities()
	{
		String rsn = getRsnSafe().orElse(null);
		if (rsn == null)
		{
			return;
		}

		Map<Integer, Integer> totalItemCounts = getTotalItemCounts();

		apiClient.getActiveFlipsAsync(rsn).thenAccept(response -> {
			if (response == null || response.getActiveFlips() == null)
			{
				return;
			}

			for (ActiveFlip flip : response.getActiveFlips())
			{
				validateAndSyncFlipQuantity(flip, totalItemCounts, rsn);
			}
		}).exceptionally(e -> {
			log.debug("Failed to validate inventory quantities: {}", e.getMessage());
			return null;
		});
	}

	private void validateAndSyncFlipQuantity(ActiveFlip flip, Map<Integer, Integer> totalItemCounts, String rsn)
	{
		int itemId = flip.getItemId();
		int activeFlipQty = flip.getTotalQuantity();
		int actualQty = totalItemCounts.getOrDefault(itemId, 0);

		if (isItemInActiveBuySlot(itemId))
		{
			log.debug("Skipping validation for {} - still in buy slot", flip.getItemName());
			return;
		}

		// Items in collectedItemIds are known to exist (e.g. in GE collect state after
		// a partial buy cancel) but haven't been counted by getTotalItemCounts which
		// only looks at inventory + sell slots. Don't dismiss or sync these.
		if (session.getCollectedItemIds().contains(itemId))
		{
			log.debug("Skipping validation for {} - item is in collected state", flip.getItemName());
			return;
		}

		if (actualQty == activeFlipQty)
		{
			return;
		}

		if (actualQty == 0)
		{
			// Backend now soft-deletes via 30-day grace (#602); the plugin no longer
			// dismisses here. GE state may not yet be loaded 17s post-login, and a
			// hard dismiss races offline-collect items that have not yet repopulated.
			log.debug("No items found for {} during validation - leaving for backend grace period",
				flip.getItemName());
			return;
		}

		int difference = Math.abs(activeFlipQty - actualQty);
		boolean significantDifference = difference >= 10 || (activeFlipQty > 0 && difference > activeFlipQty * 0.1);

		if (!significantDifference)
		{
			log.debug("Skipping validation for {} - difference of {} is not significant", flip.getItemName(), difference);
			return;
		}

		String direction = actualQty > activeFlipQty ? "up" : "down";
		log.debug("Inventory quantity mismatch for {} - active flip shows {} but have {} (inv + sell slots). Syncing {}.",
			flip.getItemName(), activeFlipQty, actualQty, direction);

		int orderQty = flip.getOrderQuantity() > 0 ? flip.getOrderQuantity() : Math.max(activeFlipQty, actualQty);
		apiClient.syncActiveFlipAsync(
			itemId,
			flip.getItemName(),
			actualQty,
			orderQty,
			flip.getAverageBuyPrice(),
			rsn
		);
	}

	private boolean isItemInActiveBuySlot(int itemId)
	{
		return offerStore.hasLiveBuyOfferForItem(itemId);
	}

	private Map<Integer, Integer> getTotalItemCounts()
	{
		Map<Integer, Integer> counts = new HashMap<>();

		ItemContainer inventory = client.getItemContainer(INVENTORY_CONTAINER_ID);
		if (inventory != null)
		{
			for (Item item : inventory.getItems())
			{
				if (item.getId() > 0)
				{
					int canonicalId = itemManager.canonicalize(item.getId());
					counts.merge(canonicalId, item.getQuantity(), Integer::sum);
				}
			}
		}

		for (OfferRecord offer : offerStore.liveOffers())
		{
			if (!offer.isBuy() && offer.getItemId() > 0)
			{
				int remainingInSlot = offer.getTotalQuantity() - offer.getFilledQuantity();
				if (remainingInSlot > 0)
				{
					counts.merge(offer.getItemId(), remainingInSlot, Integer::sum);
				}
			}
		}

		return counts;
	}

	private Optional<String> getRsnSafe()
	{
		return session.getRsnSafe();
	}
}

package com.flipsmart;

import com.flipsmart.api.dto.Dtos.FlipAdjustmentRequest;
import com.flipsmart.api.dto.Dtos.FlipAdjustmentResponse;
import com.flipsmart.api.dto.Dtos.FlipFinderResponse;
import com.flipsmart.domain.flip.FlipRecommendation;
import com.flipsmart.domain.offer.OfferRecord;
import com.flipsmart.domain.offer.OfferState;
import com.flipsmart.trading.OfferStore;
import com.flipsmart.util.GpUtils;
import java.util.Iterator;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.BiConsumer;
import java.util.function.IntConsumer;
import java.util.function.IntPredicate;
import java.util.function.ObjIntConsumer;
import java.util.function.Supplier;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;

/**
 * Tracks adjustment timers for manual (non-auto-recommend) flip offers.
 * When a manual buy or sell offer becomes stale, calls the backend /flips/adjustment
 * endpoint and prompts the user with a recommended price change.
 *
 * <p>This complements AutoRecommendService's built-in adjustment timers by providing
 * the same staleness detection for manual flips. Unlike auto mode (which uses local
 * recommendation data), manual mode calls the backend API for adjustment recommendations.</p>
 */
@Slf4j
public class ManualAdjustmentTracker
{
	/**
	 * Per-offer state for tracking adjustment timers and counts.
	 */
	private static class OfferAdjustmentState
	{
		final int itemId;
		final String itemName;
		final boolean isBuy;
		final int geSlot;
		long deadlineMs;
		int adjustmentCount;
		long averageBuyPrice;

		OfferAdjustmentState(int itemId, String itemName, boolean isBuy, int geSlot,
			long deadlineMs, long averageBuyPrice)
		{
			this.itemId = itemId;
			this.itemName = itemName;
			this.isBuy = isBuy;
			this.geSlot = geSlot;
			this.deadlineMs = deadlineMs;
			this.adjustmentCount = 0;
			this.averageBuyPrice = averageBuyPrice;
		}
	}

	private final FlipSmartApiClient apiClient;
	private final FlipSmartConfig config;
	private final OfferStore offerStore;

	private static final String MARGIN_GONE_MSG = "Margin gone on %s — consider cancelling";

	private final Map<Integer, OfferAdjustmentState> trackedOffers = new ConcurrentHashMap<>();

	// Callback to show adjustment prompts in FlipAssistOverlay
	@Setter
	private volatile ObjIntConsumer<String> onAdjustmentPrompt;

	// Callback to set a FocusedFlip for buy adjustments
	@Setter
	private volatile BiConsumer<FocusedFlip, String> onFocusFlip;

	// Callback to highlight a GE slot for adjustment
	@Setter
	private volatile BiConsumer<Integer, Long> onHighlightSlot;

	// Callback to clear a GE slot highlight
	@Setter
	private volatile IntConsumer onClearHighlight;

	// Callback to highlight an inventory item for sell adjustments
	@Setter
	private volatile IntConsumer onHighlightInventoryItem;

	// Callback to clear an inventory item highlight
	@Setter
	private volatile IntConsumer onClearInventoryItem;

	// Callback to persist adjusted sell price to session
	@Setter
	private volatile BiConsumer<Integer, Long> onSellPriceAdjusted;

	// Suppliers for ditch logic — needed to fetch replacement recommendations
	@Setter
	private volatile Supplier<Integer> cashStackSupplier;
	@Setter
	private volatile Supplier<String> rsnSupplier;
	@Setter
	private volatile Supplier<Integer> filledSlotsSupplier;
	@Setter
	private volatile Supplier<Boolean> membersWorldSupplier;
	@Setter
	private volatile IntPredicate v9OwnsSell;

	public ManualAdjustmentTracker(FlipSmartApiClient apiClient, FlipSmartConfig config, OfferStore offerStore)
	{
		this.apiClient = apiClient;
		this.config = config;
		this.offerStore = offerStore;
	}








	/**
	 * Schedule an adjustment timer for a manual buy offer.
	 *
	 * @param itemId Item ID
	 * @param itemName Item display name
	 * @param geSlot GE slot index
	 * @param offerPrice Price of the buy offer
	 */
	public void scheduleBuyAdjustment(int itemId, String itemName, int geSlot, long offerPrice)
	{
		long delay = AdjustmentTimerUtils.INITIAL_CHECK_DELAY_MS;
		long deadline = System.currentTimeMillis() + delay;
		OfferAdjustmentState state = new OfferAdjustmentState(
			itemId, itemName, true, geSlot, deadline, offerPrice);
		trackedOffers.put(geSlot, state);
		log.debug("Manual adjustment timer scheduled for {} (slot {}) in {}m",
			itemName, geSlot, delay / 60000);
	}

	/**
	 * Schedule an adjustment timer for a manual sell offer.
	 *
	 * @param itemId Item ID
	 * @param itemName Item display name
	 * @param geSlot GE slot index
	 * @param offerPrice Price of the sell offer
	 * @param averageBuyPrice Average buy price (cost basis)
	 */
	public void scheduleSellAdjustment(int itemId, String itemName, int geSlot,
		long offerPrice, long averageBuyPrice)
	{
		long delay = AdjustmentTimerUtils.INITIAL_CHECK_DELAY_MS;
		long deadline = System.currentTimeMillis() + delay;
		OfferAdjustmentState state = new OfferAdjustmentState(
			itemId, itemName, false, geSlot, deadline, averageBuyPrice);
		trackedOffers.put(geSlot, state);
		log.debug("Manual sell adjustment timer scheduled for {} (slot {}) in {}m",
			itemName, geSlot, delay / 60000);
	}

	/**
	 * Reset the adjustment timer for a GE slot (e.g., after a partial fill).
	 */
	public void resetTimer(int geSlot)
	{
		OfferAdjustmentState state = trackedOffers.get(geSlot);
		if (state == null)
		{
			return;
		}
		state.deadlineMs = System.currentTimeMillis() + AdjustmentTimerUtils.INITIAL_CHECK_DELAY_MS;
		log.debug("Manual adjustment timer reset for slot {} ({}m)", geSlot,
			AdjustmentTimerUtils.INITIAL_CHECK_DELAY_MS / 60000);
	}

	/**
	 * Clear the adjustment timer for a GE slot (e.g., on completion or cancellation).
	 */
	public void clearTimer(int geSlot)
	{
		OfferAdjustmentState removed = trackedOffers.remove(geSlot);
		if (removed != null)
		{
			log.debug("Manual adjustment timer cleared for {} (slot {})", removed.itemName, geSlot);
			IntConsumer cb = onClearHighlight;
			if (cb != null)
			{
				cb.accept(geSlot);
			}
			if (!removed.isBuy)
			{
				notifyClearInventoryHighlight(removed.itemId);
			}
		}
	}

	/**
	 * Clear all tracked timers (e.g., on logout).
	 */
	public void clearAll()
	{
		for (Map.Entry<Integer, OfferAdjustmentState> entry : trackedOffers.entrySet())
		{
			IntConsumer cb = onClearHighlight;
			if (cb != null)
			{
				cb.accept(entry.getKey());
			}
			if (!entry.getValue().isBuy)
			{
				notifyClearInventoryHighlight(entry.getValue().itemId);
			}
		}
		trackedOffers.clear();
	}

	/**
	 * Check all adjustment timers and fire API calls for expired ones.
	 * Called periodically from the plugin's refresh timer. Offer state is read
	 * from the authoritative {@link OfferStore} keyed by GE slot.
	 */
	public void checkTimers()
	{
		if (trackedOffers.isEmpty())
		{
			return;
		}

		long now = System.currentTimeMillis();
		Iterator<Map.Entry<Integer, OfferAdjustmentState>> iter = trackedOffers.entrySet().iterator();

		while (iter.hasNext())
		{
			Map.Entry<Integer, OfferAdjustmentState> entry = iter.next();
			OfferRecord offer = offerStore.bySlot(entry.getKey());
			OfferAdjustmentState state = entry.getValue();

			if (shouldRemoveTimer(offer))
			{
				iter.remove();
			}
			else if (now >= state.deadlineMs)
			{
				processExpiredTimer(state, offer);
			}
		}
	}

	private boolean shouldRemoveTimer(OfferRecord offer)
	{
		// Only remove if offer is gone (slot freed / collected) or fully filled.
		// Partial fills don't remove the timer — the API decides whether to hold or adjust.
		return offer == null || offer.getState() == OfferState.FILLED;
	}

	private void processExpiredTimer(OfferAdjustmentState state, OfferRecord offer)
	{
		// V9 owns this item's sell once it is tracking the flip; keep the legacy path off it.
		if (!state.isBuy && v9OwnsSell != null && v9OwnsSell.test(state.itemId))
		{
			return;
		}
		long minutesSinceOffer = (System.currentTimeMillis() - offer.getEffectiveLastActivityAtMillis()) / 60000;
		String timeframe = config.flipTimeframe().getApiValue();
		String style = config.flipStyle().getApiValue();
		String rsn = rsnSupplier != null ? rsnSupplier.get() : null;

		apiClient.getFlipAdjustmentAsync(FlipAdjustmentRequest.builder()
			.itemId(state.itemId)
			.isBuyOffer(state.isBuy)
			.offerPrice(offer.getPrice())
			.averageBuyPrice(state.averageBuyPrice)
			.minutesSinceOffer((int) minutesSinceOffer)
			.adjustmentCount(state.adjustmentCount)
			.quantityFilled(offer.getFilledQuantity())
			.totalQuantity(offer.getTotalQuantity())
			.timeframe(timeframe)
			.rsn(rsn)
			.style(style)
			.build()
		).thenAccept(response ->
		{
			if (response == null)
			{
				return;
			}

			if (response.isActionRequired())
			{
				handleAdjustmentRecommendation(state, offer, response);
				state.adjustmentCount++;
			}

			// Reschedule using API-provided next_check_minutes (source of truth)
			state.deadlineMs = System.currentTimeMillis()
				+ AdjustmentTimerUtils.nextCheckDelayMs(response.getNextCheckMinutes());

		}).exceptionally(e ->
		{
			log.debug("Failed to get adjustment recommendation for {}: {}",
				state.itemName, e.getMessage());
			// Reschedule with fallback delay on error
			state.deadlineMs = System.currentTimeMillis() + AdjustmentTimerUtils.FALLBACK_CHECK_DELAY_MS;
			return null;
		});

		// Don't remove from iterator — we reschedule in the callback
	}

	private void handleAdjustmentRecommendation(OfferAdjustmentState state,
		OfferRecord offer, FlipAdjustmentResponse response)
	{
		if (response.isReadjustBuy() && response.getRecommendedPrice() != null)
		{
			handleBuyAdjustment(state, offer, response);
		}
		else if (response.isReadjustSell() && response.getRecommendedPrice() != null)
		{
			handleSellAdjustment(state, offer, response);
		}
		else if (response.isCancelAndSell())
		{
			handleCancelAndSell(state, response);
		}
	}

	private void handleCancelAndSell(OfferAdjustmentState state, FlipAdjustmentResponse response)
	{
		if (response.getMessage() != null && !response.getMessage().isEmpty())
		{
			notifyPrompt(response.getMessage(), state.itemId);
		}
		if (response.getRecommendedPrice() != null)
		{
			// Overnight exit that already bought items: surface the sell price to list at.
			notifyHighlight(state.geSlot, response.getRecommendedPrice());
			notifyInventoryHighlight(state.itemId);
			BiConsumer<Integer, Long> cb = onSellPriceAdjusted;
			if (cb != null)
			{
				cb.accept(state.itemId, response.getRecommendedPrice());
			}
		}
		else
		{
			log.debug("Manual adjustment: Margin gone on {} — fetching replacement", state.itemName);
			fetchReplacementRecommendation(state);
		}
	}

	private void handleBuyAdjustment(OfferAdjustmentState state, OfferRecord offer,
		FlipAdjustmentResponse response)
	{
		String msg = String.format("Adjust %s buy price %s → %s gp",
			state.itemName,
			GpUtils.formatGPWithSuffix(offer.getPrice()),
			GpUtils.formatGPWithSuffix(response.getRecommendedPrice()));

		log.debug("Manual adjustment: {}", msg);

		BiConsumer<FocusedFlip, String> focusCallback = onFocusFlip;
		if (focusCallback != null)
		{
			long sellPrice = response.getBreakevenPrice() + 1;
			if (response.getCurrentMargin() != null && response.getCurrentMargin() > 0)
			{
				sellPrice = response.getRecommendedPrice() + response.getCurrentMargin();
			}
			FocusedFlip focus = FocusedFlip.forBuy(
				state.itemId, state.itemName,
				response.getRecommendedPrice(),
				offer.getTotalQuantity(),
				sellPrice,
				config.priceOffset());
			focusCallback.accept(focus, msg);
		}

		notifyHighlight(state.geSlot, response.getRecommendedPrice());
	}

	private void handleSellAdjustment(OfferAdjustmentState state, OfferRecord offer,
		FlipAdjustmentResponse response)
	{
		String msg = String.format("Adjust %s sell price %s → %s gp",
			state.itemName,
			GpUtils.formatGPWithSuffix(offer.getPrice()),
			GpUtils.formatGPWithSuffix(response.getRecommendedPrice()));

		log.debug("Manual adjustment: {}", msg);
		notifyPrompt(msg, state.itemId);
		notifyHighlight(state.geSlot, response.getRecommendedPrice());
		notifyInventoryHighlight(state.itemId);

		BiConsumer<Integer, Long> cb = onSellPriceAdjusted;
		if (cb != null)
		{
			cb.accept(state.itemId, response.getRecommendedPrice());
		}
	}

	private void notifyPrompt(String msg, int itemId)
	{
		ObjIntConsumer<String> cb = onAdjustmentPrompt;
		if (cb != null)
		{
			cb.accept(msg, itemId);
		}
	}

	private void notifyHighlight(int geSlot, long price)
	{
		BiConsumer<Integer, Long> cb = onHighlightSlot;
		if (cb != null)
		{
			cb.accept(geSlot, price);
		}
	}

	private void notifyInventoryHighlight(int itemId)
	{
		IntConsumer cb = onHighlightInventoryItem;
		if (cb != null)
		{
			cb.accept(itemId);
		}
	}

	private void notifyClearInventoryHighlight(int itemId)
	{
		IntConsumer cb = onClearInventoryItem;
		if (cb != null)
		{
			cb.accept(itemId);
		}
	}

	/**
	 * Fetch a replacement flip recommendation when the current flip's margin has evaporated.
	 * Shows a prompt like "Margin gone on [item] — switch to [new item] instead?"
	 */
	private void fetchReplacementRecommendation(OfferAdjustmentState state)
	{
		Integer cashStack = cashStackSupplier != null ? cashStackSupplier.get() : null;
		String rsn = rsnSupplier != null ? rsnSupplier.get() : null;
		Integer filledSlots = filledSlotsSupplier != null ? filledSlotsSupplier.get() : null;
		boolean isMembersWorld = membersWorldSupplier == null || membersWorldSupplier.get();
		String timeframe = config.flipTimeframe().getApiValue();
		String flipStyle = config.flipStyle().getApiValue();

		apiClient.getFlipRecommendationsAsync(cashStack, flipStyle, 1, null, timeframe, rsn, filledSlots, isMembersWorld, false)
			.thenAccept(response -> handleReplacementResponse(response, state))
			.exceptionally(e ->
			{
				log.debug("Failed to fetch replacement recommendation: {}", e.getMessage());
				notifyMarginGone(state);
				return null;
			});
	}

	private void handleReplacementResponse(FlipFinderResponse response,
		OfferAdjustmentState state)
	{
		if (response == null || response.getRecommendations() == null
			|| response.getRecommendations().isEmpty())
		{
			notifyMarginGone(state);
			return;
		}

		FlipRecommendation replacement = response.getRecommendations().get(0);
		if (replacement.getItemId() == state.itemId)
		{
			notifyMarginGone(state);
			return;
		}

		String msg = String.format("Margin gone on %s — switch to %s instead? (%s profit)",
			state.itemName,
			replacement.getItemName(),
			GpUtils.formatGPWithSuffix(replacement.getPotentialProfit()));

		log.debug("Ditch recommendation: {}", msg);

		BiConsumer<FocusedFlip, String> focusCallback = onFocusFlip;
		if (focusCallback != null)
		{
			FocusedFlip focus = FocusedFlip.forBuy(
				replacement.getItemId(),
				replacement.getItemName(),
				replacement.getRecommendedBuyPrice(),
				replacement.getRecommendedQuantity(),
				replacement.getRecommendedSellPrice(),
				config.priceOffset());
			focusCallback.accept(focus, msg);
		}

		notifyHighlight(state.geSlot, 0);
	}

	private void notifyMarginGone(OfferAdjustmentState state)
	{
		notifyPrompt(String.format(MARGIN_GONE_MSG, state.itemName), state.itemId);
	}

}

package com.flipsmart;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;

/**
 * Builds a thin edge-outline sprite for one GE slot border piece.
 *
 * <p>The frame pieces overhang the visible slot by a few px (their outer edge sticks out past the
 * slot bounds), so the slot's actual border does not sit at the sprite's own edge. Each line is
 * therefore positioned at the slot border expressed in the piece's local coordinates —
 * {@code -relX}/{@code -relY} for the top/left, {@code slot - rel - thickness} for the bottom/right —
 * and the {@link Graphics2D} clip drops any part that falls outside the piece. Corners (which are
 * aligned to the slot) resolve to their own edges under the same formula.
 */
public final class SpriteOutline
{
    public static final int TOP = 1;
    public static final int BOTTOM = 2;
    public static final int LEFT = 4;
    public static final int RIGHT = 8;

    private SpriteOutline()
    {
    }

    public static BufferedImage build(int width, int height, int edges, Color color, int thickness,
                                      int relX, int relY, int slotWidth, int slotHeight)
    {
        BufferedImage out = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
        int t = Math.max(1, thickness);
        Graphics2D g = out.createGraphics();
        g.setColor(color);
        if ((edges & TOP) != 0)
        {
            g.fillRect(0, -relY, width, t);
        }
        if ((edges & BOTTOM) != 0)
        {
            g.fillRect(0, slotHeight - relY - t, width, t);
        }
        if ((edges & LEFT) != 0)
        {
            g.fillRect(-relX, 0, t, height);
        }
        if ((edges & RIGHT) != 0)
        {
            g.fillRect(slotWidth - relX - t, 0, t, height);
        }
        g.dispose();
        return out;
    }
}

package com.flipsmart.exit;

public enum ExitTradesMode
{
	BREAKEVEN,
	INSTANT,
	REGULAR // sell-only: suppress buys but leave the normal sell flow and its prices untouched
}

package com.flipsmart.exit;

import lombok.Getter;
import lombok.Setter;

/** One occupied GE slot the Exit Trades flow must unwind. Phase mutates as the player acts. */
@Getter
public final class ExitSlotTarget
{
	private final int slot;
	private final int itemId;
	private final String itemName;
	private final boolean buy;
	private final long buyBasis;
	@Setter
	private ExitPhase phase;
	@Setter
	private int heldQuantity; // stock bought from a cancelled/filled buy, remembered across the collect lag

	private ExitSlotTarget(int slot, int itemId, String itemName, boolean buy, long buyBasis, ExitPhase phase)
	{
		this.slot = slot;
		this.itemId = itemId;
		this.itemName = itemName;
		this.buy = buy;
		this.buyBasis = buyBasis;
		this.phase = phase;
	}

	public static ExitSlotTarget sell(int slot, int itemId, String itemName, long buyBasis)
	{
		return new ExitSlotTarget(slot, itemId, itemName, false, buyBasis, ExitPhase.PENDING);
	}

	public static ExitSlotTarget forBuy(int slot, int itemId, String itemName, long buyBasis)
	{
		return new ExitSlotTarget(slot, itemId, itemName, true, buyBasis, ExitPhase.PENDING_CANCEL);
	}

}

