		}
	}

	/**
	 * Set focus from external source (e.g., auto-focus when setting up a sell offer).
	 * This sets the logical focus without highlighting a specific panel.
	 */
	public void setExternalFocus(FocusedFlip focus)
	{
		if (focus == null)
		{
			clearFocus();
			return;
		}

		// Clear any existing panel highlight
		if (currentFocusedPanel != null)
		{
			resetPanelStyle(currentFocusedPanel);
			currentFocusedPanel = null;
		}

		// Set the focus state
		currentFocus = focus;
		currentFocusedItemId = focus.getItemId();

		// Note: We don't have a panel to highlight since this was set externally
		// The Flip Assist overlay will show the focused item info

		log.debug("External focus set: {} - {} at {} gp", 
			focus.isBuying() ? "BUY" : "SELL",
			focus.getItemName(),
			focus.getCurrentStepPrice());
	}

	/**
	 * Create a panel for an active flip with current market data
	 */
	/** The hairline rule separating a card's live-market block from its position block. */
	private static void addCardDivider(JPanel detailsPanel)
	{
		detailsPanel.add(Box.createRigidArea(new Dimension(0, 3)));
		JSeparator rowDivider = new JSeparator();
		rowDivider.setForeground(new Color(70, 70, 70));
		rowDivider.setMaximumSize(new Dimension(Integer.MAX_VALUE, 1));
		detailsPanel.add(rowDivider);
		detailsPanel.add(Box.createRigidArea(new Dimension(0, 3)));
	}

	private JPanel createActiveFlipPanel(ActiveFlip flip)
	{
		JPanel panel = CardWidgets.createBaseItemPanel(ColorScheme.DARKER_GRAY_COLOR, 210, true);

		// Details section using BoxLayout for vertical rows
		JPanel detailsPanel = CardWidgets.createDetailsPanel(ColorScheme.DARKER_GRAY_COLOR);

		// --- Top "live" block: instant market info (HTML rows carry their own colours) ---
		CardRows rows = new CardRows(CardRow.values());
		JLabel buyLimitLabel = rows.get(CardRow.BUY_LIMIT);

		rows.addTo(detailsPanel, CardRow.ACTION, CardRow.BUY_SELL, CardRow.LIVE_MARGIN, CardRow.TAX);
		// Divider separates the "live" block from the position-reference block
		addCardDivider(detailsPanel);
		rows.addTo(detailsPanel, CardRow.CURRENT_PROFIT, CardRow.MAX_POTENTIAL, CardRow.QTY,
			CardRow.LIQUIDITY, CardRow.RISK);
		rows.set(CardRow.ACTION, PanelFormat.actionSellingHtml());

		// Array indirection: the refresh closure needs the header panels before createItemHeaderPanels produces them.
		HeaderPanels[] headerHolder = new HeaderPanels[1];
		Runnable refreshCard = () ->
		{
			apiClient.invalidateCache(flip.getItemId());
			populateActiveFlipCard(flip,
				new ActiveFlipCardPanels(panel, headerHolder[0].topPanel, headerHolder[0].namePanel, detailsPanel),
				rows);
		};
		JLabel refreshIcon = createRefreshIconLabel(refreshCard);
		HeaderPanels header = createItemHeaderPanels(flip.getItemId(), flip.getItemName(),
			ColorScheme.DARKER_GRAY_COLOR, refreshIcon, buyLimitLabel);
		headerHolder[0] = header;
		activeFlipCardRefreshers.add(refreshCard);
		allowForWrappedName(panel, header.extraNameHeight);
		JPanel topPanel = header.topPanel;
		JPanel namePanel = header.namePanel;

		panel.add(topPanel, BorderLayout.NORTH);
		panel.add(detailsPanel, BorderLayout.CENTER);

		populateActiveFlipCard(flip,
			new ActiveFlipCardPanels(panel, topPanel, namePanel, detailsPanel), rows);

		// Store default background color as client property (will be overwritten if price indicator is applied)
		panel.putClientProperty("baseBackgroundColor", ColorScheme.DARKER_GRAY_COLOR);

		// Add hover effect, click to focus, and context menu
		panel.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				// Left click: set as Flip Assist focus for selling
				if (e.getButton() == MouseEvent.BUTTON1 && !e.isPopupTrigger())
				{
					setFocus(flip, panel);
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				if (currentFocus == null || currentFocus.getItemId() != flip.getItemId() 
					|| !currentFocus.isSelling())
				{
					// Get the base color (may be price indicator color) and brighten it for hover
					Color baseColor = PanelFormat.getBaseBackgroundColor(panel, ColorScheme.DARKER_GRAY_COLOR);
					Color hoverColor = PanelFormat.brightenColor(baseColor, 15);
					CardWidgets.setPanelBackgrounds(hoverColor, panel, topPanel, namePanel, detailsPanel);
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				if (currentFocus == null || currentFocus.getItemId() != flip.getItemId() 
					|| !currentFocus.isSelling())
				{
					// Restore the base color (may be price indicator color)
					Color baseColor = PanelFormat.getBaseBackgroundColor(panel, ColorScheme.DARKER_GRAY_COLOR);
					CardWidgets.setPanelBackgrounds(baseColor, panel, topPanel, namePanel, detailsPanel);
				}
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				showContextMenu(e, flip);
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				showContextMenu(e, flip);
			}

			private void showContextMenu(MouseEvent e, ActiveFlip flip)
			{
				if (e.isPopupTrigger())
				{
					showItemContextMenu(flip.getItemId(), flip.getItemName(), header.starLabel,
						e.getComponent(), e.getX(), e.getY(), true, () -> dismissActiveFlip(flip));
				}
			}
		});

		return panel;
	}

	/**
	 * Panels touched when (re)populating an active-flip card.
	 */
	private static class ActiveFlipCardPanels
	{
		final JPanel panel;
		final JPanel topPanel;
		final JPanel namePanel;
		final JPanel detailsPanel;

		ActiveFlipCardPanels(JPanel panel, JPanel topPanel, JPanel namePanel, JPanel detailsPanel)
		{
			this.panel = panel;
			this.topPanel = topPanel;
			this.namePanel = namePanel;
			this.detailsPanel = detailsPanel;
		}
	}

	/**
	 * Detail-row labels populated on an active-flip card.
	 */
	/**
	 * The rows a position card can show. Each carries its own placeholder and styling, so a
	 * card is described by WHICH rows it has rather than by code that builds each one.
	 */
	private enum CardRow
	{
		ACTION("Action: ...", Color.WHITE, false),
		BUY_SELL("Live Price: ...", Color.WHITE, false),
		LIVE_MARGIN("Live Margin: ...", Color.WHITE, false),
		TAX("Tax: ...", COLOR_TEXT_GRAY, true),
		CURRENT_PROFIT("Current Profit: ...", Color.WHITE, false),
		MAX_POTENTIAL("Max Potential Profit: ...", Color.WHITE, true),
		QTY("Qty: ...", COLOR_TEXT_GRAY, true),
		LIQUIDITY("Liquidity: ...", Color.CYAN, false),
		RISK("Risk: ...", COLOR_YELLOW, false),
		BUY_LIMIT("Buy limit: ...", COLOR_TEXT_GRAY, true);

		private final String placeholder;
		private final Color colour;
		private final boolean small;

		CardRow(String placeholder, Color colour, boolean small)
		{
			this.placeholder = placeholder;
			this.colour = colour;
			this.small = small;
		}

		private JLabel create()
		{
			JLabel label = CardWidgets.createStyledLabel(placeholder, colour);
			if (small)
			{
				label.setFont(FONT_PLAIN_11);
			}
			return label;
		}
	}

	/**
	 * A card's rows, keyed rather than bound to named locals. Keying is what makes one
	 * builder serve several card types: population addresses a row by name instead of the
	 * caller having to hold nine separate references.
	 */
	private static final class CardRows
	{
		private final EnumMap<CardRow, JLabel> labels = new EnumMap<>(CardRow.class);

		private CardRows(CardRow... rows)
		{
			for (CardRow row : rows)
			{
				labels.put(row, row.create());
			}
		}

		private JLabel get(CardRow row)
		{
			return labels.get(row);
		}

		/** Silently ignores rows this card does not carry, so specs can differ safely. */
		private void set(CardRow row, String text)
		{
			JLabel label = labels.get(row);
			if (label != null)
			{
				label.setText(text);
			}
		}

		private void addTo(JPanel panel, CardRow... rows)
		{
			JLabel[] present = java.util.Arrays.stream(rows)
				.map(labels::get)
				.filter(java.util.Objects::nonNull)
				.toArray(JLabel[]::new);
			CardWidgets.addLabelsWithSpacing(panel, present);
		}
	}


	/**
	 * Fetch fresh market analysis for an active-flip card and (re)populate its rows.
	 * Reused by the initial card build and the manual refresh button.
	 */
	private void populateActiveFlipCard(ActiveFlip flip, ActiveFlipCardPanels panels, CardRows rows)
	{
		apiClient.getItemAnalysisAsync(flip.getItemId()).thenAccept(analysis ->
			SwingUtilities.invokeLater(() ->
			{
				Long high = null;
				Long low = null;
				Integer buyLimit = null;
				FlipAnalysis.Liquidity liquidity = null;
				FlipAnalysis.Risk risk = null;

				if (analysis != null)
				{
					buyLimit = analysis.getBuyLimit();
					liquidity = analysis.getLiquidity();
					risk = analysis.getRisk();
					if (analysis.getCurrentPrices() != null)
					{
						high = analysis.getCurrentPrices().getHigh();
						low = analysis.getCurrentPrices().getLow();
					}
				}

				// Realized fills (sold-so-far) drive both Qty and Current Profit; compute once.
				RealizedFlipProfit.Result realized = RealizedFlipProfit.compute(
					plugin.getOfferStore().forItem(flip.getItemId()), flip.getItemId(), flip.getAverageBuyPrice(),
					flip.getFirstBuyTime() != null ? TimeUtils.parseIsoToMillis(flip.getFirstBuyTime()) : 0L);
				long fullQty = (long) realized.soldQuantity + flip.getTotalQuantity();
				rows.set(CardRow.QTY, PanelFormat.qtyHtml(realized.soldQuantity, fullQty));

				// The flip's own sell price (session-recommended, else computed) drives both the
				// side effects and the Max Potential Profit figure.
				Long flipSellPrice = resolveSmartSellPrice(flip, high, plugin.getSession());
				applySmartSellSideEffects(flip, panels, flipSellPrice);

				rows.set(CardRow.BUY_LIMIT, 
					"Buy limit: " + (buyLimit != null ? PanelFormat.formatGP(buyLimit) : "?"));

				if (hasValidMarketPrices(high, low))
				{
					populateActiveFlipMarketRows(flip, panels, rows, low, high, flipSellPrice, realized, fullQty);
				}
				else
				{
					rows.set(CardRow.BUY_SELL, "Live Price: N/A");
					rows.set(CardRow.LIVE_MARGIN, "Live Margin: N/A");
					rows.set(CardRow.CURRENT_PROFIT, "Current Profit: N/A");
					rows.set(CardRow.MAX_POTENTIAL, "Max Potential Profit: N/A");
					rows.set(CardRow.TAX, "Tax: N/A");
					panels.panel.setToolTipText(null);
				}

				updateLiquidityLabel(rows.get(CardRow.LIQUIDITY), liquidity);
				updateRiskLabel(rows.get(CardRow.RISK), risk);
			}));
	}

	private static boolean hasValidMarketPrices(Long high, Long low)
	{
		return high != null && high > 0 && low != null && low > 0;
	}

	/**
	 * The flip's sell price drives the session write, Flip Assist focus update and
	 * price-indicator background, even though the price itself is not displayed.
	 */
	private void applySmartSellSideEffects(ActiveFlip flip, ActiveFlipCardPanels panels, Long smartSellPrice)
	{
		if (smartSellPrice == null)
		{
			return;
		}

		displayedSellPrices.put(flip.getItemId(), smartSellPrice);
		applyPriceIndicatorIfNeeded(flip, panels, smartSellPrice);
		updateFocusIfSelected(flip, smartSellPrice);
	}

	/**
	 * Prefer the session's already-recommended price; otherwise compute one and persist
	 * it to the session so later cards/refreshes stay pinned to the same price.
	 */
	private static Long resolveSmartSellPrice(ActiveFlip flip, Long high, PlayerSession session)
	{
		Long sessionPrice = session != null ? session.getRecommendedPrice(flip.getItemId()) : null;
		if (isValidPrice(sessionPrice))
		{
			return sessionPrice;
		}

		Long computedPrice = SmartSellPricer.calculateSmartSellPrice(flip, high);
		// With no basis the price is a live-market reading, not a target. Persisting it would
		// pin this instant's market for the session and outrank the real breakeven once it returns.
		if (isValidPrice(computedPrice) && session != null && flip.getAverageBuyPrice() > 0)
		{
			session.setRecommendedPrice(flip.getItemId(), computedPrice);
		}
		return isValidPrice(computedPrice) ? computedPrice : null;
	}

	private static boolean isValidPrice(Long price)
	{
		return price != null && price > 0;
	}

	private void applyPriceIndicatorIfNeeded(ActiveFlip flip, ActiveFlipCardPanels panels, long smartSellPrice)
	{
		Long recommendedPrice = flip.getRecommendedSellPrice();
		boolean focusedOnThisFlip = currentFocus != null && currentFocus.getItemId() == flip.getItemId();
		if (recommendedPrice == null || recommendedPrice <= 0 || smartSellPrice == recommendedPrice || focusedOnThisFlip)
		{
			return;
		}

		Color priceIndicatorBg = smartSellPrice > recommendedPrice
			? COLOR_PRICE_HIGHER_BG
			: COLOR_PRICE_LOWER_BG;
		CardWidgets.applyPriceIndicatorBackground(panels.panel, panels.topPanel, panels.namePanel, panels.detailsPanel, priceIndicatorBg);
	}

	private void updateFocusIfSelected(ActiveFlip flip, long smartSellPrice)
	{
		if (currentFocus == null || currentFocus.getItemId() != flip.getItemId() || !currentFocus.isSelling())
		{
			return;
		}

		FocusedFlip updatedFocus = FocusedFlip.forSell(
			flip.getItemId(), flip.getItemName(), smartSellPrice,
			sellQuantityFor(flip), config.priceOffset());
		// Re-pushing an unchanged focus clears the overlay's active prompt and re-writes
		// the GE search varp, so a periodic refresh must not do it.
		if (updatedFocus.equals(currentFocus))
		{
			return;
		}
		currentFocus = updatedFocus;
		if (onFocusChanged != null)
		{
			onFocusChanged.accept(updatedFocus);
		}
	}

	/**
	 * Render the market-based detail rows (live price, live margin, tax) plus the
	 * position rows (current profit, max potential profit) once prices are available.
	 */
	private void populateActiveFlipMarketRows(ActiveFlip flip, ActiveFlipCardPanels panels,
		CardRows rows, long low, long high, Long flipSellPrice,
		RealizedFlipProfit.Result realized, long fullQty)
	{
		ActiveFlipCardMetrics.Result metrics = ActiveFlipCardMetrics.compute(
			low, high, flip.getItemId(), flip.getAverageBuyPrice(), realized.soldQuantity, flip.getTotalQuantity());

		if (metrics.positionNetPerUnit < 0)
		{
			panels.panel.setToolTipText("Selling at the current price would be a loss - below your buy price plus tax.");
		}
		else
		{
			panels.panel.setToolTipText(null);
		}

		// Max Potential Profit uses the flip's OWN buy/sell prices (not the wiki spread):
		// (sell - buy - tax) x full flip quantity.
		long maxPotentialProfit = 0L;
		if (flipSellPrice != null && flipSellPrice > 0)
		{
			int sellTax = GeTax.taxFor(flip.getItemId(), flipSellPrice);
			maxPotentialProfit = (flipSellPrice - flip.getAverageBuyPrice() - sellTax) * fullQty;
		}

		// Colours are baked into the HTML by PanelFormat, so no setForeground needed here.
		rows.set(CardRow.BUY_SELL, PanelFormat.livePriceHtml(low, high));
		rows.set(CardRow.LIVE_MARGIN, PanelFormat.liveMarginHtml(metrics.margin, metrics.roi));
		rows.set(CardRow.TAX, PanelFormat.taxHtml(metrics.totalTax));
		rows.set(CardRow.CURRENT_PROFIT, PanelFormat.currentProfitHtml(realized.netProfit));
		rows.set(CardRow.MAX_POTENTIAL, PanelFormat.maxPotentialProfitHtml(maxPotentialProfit));
	}

	/**
	 * Create a panel for a pending order (not yet filled)
	 * Uses same detailed layout as active flips with Liquidity/Risk data
	 */
	private JPanel createPendingOrderPanel(PendingOrder pending)
	{
		Color bgColor = new Color(55, 55, 65); // Slightly different color for pending
		JPanel panel = CardWidgets.createBaseItemPanel(bgColor, 210, false);

		JPanel detailsPanel = CardWidgets.createDetailsPanel(bgColor);

		// --- Top "live" block ---
		// No Current Profit row — nothing has sold yet on a pending buy.
		CardRows rows = new CardRows(CardRow.ACTION, CardRow.BUY_SELL, CardRow.LIVE_MARGIN, CardRow.TAX,
			CardRow.MAX_POTENTIAL, CardRow.QTY, CardRow.LIQUIDITY, CardRow.RISK, CardRow.BUY_LIMIT);
		JLabel buyLimitLabel = rows.get(CardRow.BUY_LIMIT);

		rows.addTo(detailsPanel, CardRow.ACTION, CardRow.BUY_SELL, CardRow.LIVE_MARGIN, CardRow.TAX);
		addCardDivider(detailsPanel);
		rows.addTo(detailsPanel, CardRow.MAX_POTENTIAL, CardRow.QTY, CardRow.LIQUIDITY, CardRow.RISK);
		rows.set(CardRow.ACTION, PanelFormat.actionBuyingHtml());

		// Header with refresh + corner buy-limit, matching the active-flip cards
		Runnable refreshCard = () ->
		{
			apiClient.invalidateCache(pending.itemId);
			populatePendingCardRows(pending, rows);
		};
		activeFlipCardRefreshers.add(refreshCard);
		JLabel refreshIcon = createRefreshIconLabel(refreshCard);
		HeaderPanels header = createItemHeaderPanels(pending.itemId, pending.itemName, bgColor, refreshIcon, buyLimitLabel);
		allowForWrappedName(panel, header.extraNameHeight);
		JPanel topPanel = header.topPanel;
		JPanel namePanel = header.namePanel;

		panel.add(topPanel, BorderLayout.NORTH);
		panel.add(detailsPanel, BorderLayout.CENTER);

		populatePendingCardRows(pending, rows);

		// Add click listener for focus selection
		panel.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				// Only allow focus if there are filled items to sell
				if (pending.quantityFilled > 0 && e.getButton() == MouseEvent.BUTTON1)
				{
					setFocus(pending, panel);
				}
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				if (currentFocus == null || currentFocus.getItemId() != pending.itemId)
				{
					CardWidgets.setPanelBackgrounds(new Color(65, 65, 75), panel, topPanel, namePanel, detailsPanel);
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				if (currentFocus == null || currentFocus.getItemId() != pending.itemId)
				{
					CardWidgets.setPanelBackgrounds(bgColor, panel, topPanel, namePanel, detailsPanel);
				}
			}
		});

		// Set cursor to indicate clickable if filled
		if (pending.quantityFilled > 0)
		{
			panel.setCursor(new Cursor(Cursor.HAND_CURSOR));
		}

		return panel;
	}

	/**
	 * Fetch market analysis and (re)populate a pending buy card's rows. Reused by the
	 * initial build and the refresh button. Mirrors the active-flip card layout minus
	 * Current Profit (nothing is sold on a pending buy).
	 */
	private void populatePendingCardRows(PendingOrder pending, CardRows rows)
	{
		rows.set(CardRow.QTY, PanelFormat.qtyHtml(pending.quantityFilled, pending.quantity));

		apiClient.getItemAnalysisAsync(pending.itemId).thenAccept(analysis ->
			SwingUtilities.invokeLater(() ->
			{
				Long high = null;
				Long low = null;
				Integer buyLimit = null;
				FlipAnalysis.Liquidity liquidity = null;
				FlipAnalysis.Risk risk = null;

				if (analysis != null)
				{
					buyLimit = analysis.getBuyLimit();
					liquidity = analysis.getLiquidity();
					risk = analysis.getRisk();
					if (analysis.getCurrentPrices() != null)
					{
						high = analysis.getCurrentPrices().getHigh();
						low = analysis.getCurrentPrices().getLow();
					}
				}

				rows.set(CardRow.BUY_LIMIT, "Buy limit: " + (buyLimit != null ? PanelFormat.formatGP(buyLimit) : "?"));

				if (high != null && high > 0 && low != null && low > 0)
				{
					long margin = high - low;
					double roi = (margin * 100.0) / low;
					long totalTax = (long) GeTax.taxFor(pending.itemId, high) * pending.quantity;
					rows.set(CardRow.BUY_SELL, PanelFormat.livePriceHtml(low, high));
					rows.set(CardRow.LIVE_MARGIN, PanelFormat.liveMarginHtml(margin, roi));
					rows.set(CardRow.TAX, PanelFormat.taxHtml(totalTax));
				}
				else
				{
					rows.set(CardRow.BUY_SELL, "Live Price: N/A");
					rows.set(CardRow.LIVE_MARGIN, "Live Margin: N/A");
					rows.set(CardRow.TAX, "Tax: N/A");
				}

				// Max Potential Profit for the pending buy: (sell - buy - tax) x ordered qty,
				// where sell is the flip's recommended sell price (else the current market high).
				Long sellPrice = pending.recommendedSellPrice != null && pending.recommendedSellPrice > 0
					? pending.recommendedSellPrice : high;
				long maxPotentialProfit = 0L;
				if (sellPrice != null && sellPrice > 0)
				{
					int sellTax = GeTax.taxFor(pending.itemId, sellPrice);
					maxPotentialProfit = (sellPrice - pending.pricePerItem - sellTax) * pending.quantity;
				}
				rows.set(CardRow.MAX_POTENTIAL, PanelFormat.maxPotentialProfitHtml(maxPotentialProfit));

				updateLiquidityLabel(rows.get(CardRow.LIQUIDITY), liquidity);
				updateRiskLabel(rows.get(CardRow.RISK), risk);
			}));
	}

	/**
	 * Build a small, non-alarming confidence badge for a completed flip, or
	 * {@code null} when the flip is fully confident (nothing to show).
	 */
	private JLabel buildConfidenceLabel(CompletedFlip flip)
	{
		if (!flip.isPriceIsEstimated() && !flip.isQuantityAnomaly())
		{
			return null;
		}

		StringBuilder text = new StringBuilder(240).append("<html>");
		StringBuilder tip = new StringBuilder(260);
		if (flip.isQuantityAnomaly())
		{
			text.append("<span style='color:").append(COLOR_ANOMALY_HEX).append(";'>&#9888; Anomaly: Quantity Flagged (Edit)</span>");
			tip.append("Recorded quantity looks higher than the item's 4h GE buy limit allows, so it may be over-counted. ");
		}
		if (flip.isPriceIsEstimated())
		{
			if (flip.isQuantityAnomaly())
			{
				text.append("<br>");
			}
			text.append("<span style='color:").append(COLOR_ANOMALY_HEX).append(";'>&#9888; Anomaly: Profit Flagged (Edit)</span>");
			tip.append("Price was recovered from offline trade history as a blended average, so the profit is an estimate. ");
		}
		text.append("</html>");

		JLabel label = new JLabel(text.toString());
		label.setFont(FONT_PLAIN_12);
		label.setToolTipText(tip.append("Click to edit this trade on the website.").toString());
		label.setCursor(new Cursor(Cursor.HAND_CURSOR));
		final int flipId = flip.getId();
		label.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				LinkBrowser.browse(FLIP_EDIT_URL + flipId);
			}
		});
		return label;
	}

	/**
	 * Create a panel for a completed flip
	 */
	private JPanel createCompletedFlipPanel(CompletedFlip flip)
	{
		// Color based on profit/loss
		Color backgroundColor = flip.isSuccessful() ? 
			new Color(40, 60, 40) : // Dark green for profit
			new Color(60, 40, 40);  // Dark red for loss
		JPanel panel = CardWidgets.createBaseItemPanel(backgroundColor, 110, false);

		// Top section: Item icon and name
		HeaderPanels header = createItemHeaderPanels(flip.getItemId(), flip.getItemName(), backgroundColor);
		allowForWrappedName(panel, header.extraNameHeight);
		JPanel topPanel = header.topPanel;
		final JLabel completedStarLabel = header.starLabel;

		// Details section with profit/loss info - use GridBagLayout for tighter column spacing
		JPanel detailsPanel = CardWidgets.panel(new GridBagLayout(), backgroundColor);
		detailsPanel.setBorder(new EmptyBorder(3, 0, 0, 0));

		GridBagConstraints gbc = new GridBagConstraints();
		gbc.anchor = GridBagConstraints.WEST;
		gbc.insets = new Insets(1, 0, 1, 15); // 15px gap between columns

		// Row 1: Quantity and Buy Price
		JLabel qtyLabel = CardWidgets.label(String.format(FORMAT_QTY, flip.getQuantity()), COLOR_TEXT_GRAY, FONT_PLAIN_12);

		JLabel buyPriceLabel = CardWidgets.label(String.format("Buy: %s", PanelFormat.formatGPExact(flip.getBuyPricePerItem())), COLOR_BUY_RED, FONT_PLAIN_12);

		// Row 2: Invested and Sell Price
		JLabel investedLabel = CardWidgets.label(String.format("Cost: %s", PanelFormat.formatGP(flip.getBuyTotal())), COLOR_TEXT_GRAY, FONT_PLAIN_12);

		JLabel sellPriceLabel = CardWidgets.label(String.format(FORMAT_SELL, PanelFormat.formatGPExact(flip.getSellPricePerItem())), COLOR_SELL_GREEN, FONT_PLAIN_12);

		// Row 3: Net Profit and ROI
		JLabel profitLabel = new JLabel(String.format("Profit: %s", PanelFormat.formatGP(flip.getNetProfit())));
		Color profitColor = flip.isSuccessful() ? 
			COLOR_PROFIT_GREEN : // Bright green
			COLOR_LOSS_RED;  // Bright red
		profitLabel.setForeground(profitColor);
		profitLabel.setFont(FONT_BOLD_12);

		JLabel roiLabel = CardWidgets.label(String.format(FORMAT_ROI, flip.getRoiPercent()), profitColor, FONT_BOLD_12);

		// Add labels with GridBagLayout - columns stay compact
		gbc.gridx = 0; gbc.gridy = 0; detailsPanel.add(qtyLabel, gbc);
		gbc.gridx = 1; gbc.gridy = 0; gbc.insets = new Insets(1, 0, 1, 0); detailsPanel.add(buyPriceLabel, gbc);
		gbc.gridx = 0; gbc.gridy = 1; gbc.insets = new Insets(1, 0, 1, 15); detailsPanel.add(investedLabel, gbc);
		gbc.gridx = 1; gbc.gridy = 1; gbc.insets = new Insets(1, 0, 1, 0); detailsPanel.add(sellPriceLabel, gbc);
		gbc.gridx = 0; gbc.gridy = 2; gbc.insets = new Insets(1, 0, 1, 15); detailsPanel.add(profitLabel, gbc);
		gbc.gridx = 1; gbc.gridy = 2; gbc.insets = new Insets(1, 0, 1, 0); detailsPanel.add(roiLabel, gbc);

		// Add horizontal glue to prevent stretching
		gbc.gridx = 2; gbc.gridy = 0; gbc.weightx = 1.0; gbc.fill = GridBagConstraints.HORIZONTAL;
		detailsPanel.add(Box.createHorizontalGlue(), gbc);

		// Confidence signal: badge flips whose price is an offline-history
		// estimate or whose quantity looks over the GE buy limit, mirroring the
		// web dashboard so a blended offline price isn't shown as exact.
		JLabel confidenceLabel = buildConfidenceLabel(flip);
		if (confidenceLabel != null)
		{
			gbc.gridx = 0; gbc.gridy = 3; gbc.gridwidth = 2; gbc.weightx = 0;
			gbc.fill = GridBagConstraints.NONE; gbc.insets = new Insets(3, 0, 0, 0);
			detailsPanel.add(confidenceLabel, gbc);
			gbc.gridwidth = 1;
			if (flip.isPriceIsEstimated() && flip.isQuantityAnomaly())
			{
				allowForWrappedName(panel, BADGE_SECOND_LINE_HEIGHT);
			}
		}

		panel.add(topPanel, BorderLayout.NORTH);
		panel.add(detailsPanel, BorderLayout.CENTER);

		// Add click to show more details
		panel.setCursor(new Cursor(Cursor.HAND_CURSOR));
		panel.addMouseListener(new MouseAdapter()
		{
			private boolean expanded = false;

			@Override
			public void mouseClicked(MouseEvent e)
			{
				// Right-click opens the context menu (handled in mousePressed/mouseReleased); left-click expands.
				if (e.getButton() != MouseEvent.BUTTON1 || e.isPopupTrigger())
				{
					return;
				}
				if (!expanded)
				{
					// Add extra details
					JPanel extraDetails = new JPanel();
					extraDetails.setLayout(new BoxLayout(extraDetails, BoxLayout.Y_AXIS));
					extraDetails.setBackground(backgroundColor);
					extraDetails.setBorder(new EmptyBorder(5, 38, 0, 0));

					// Duration
					int hours = flip.getFlipDurationSeconds() / 3600;
					int minutes = (flip.getFlipDurationSeconds() % 3600) / 60;
					String duration = hours > 0 ? 
						String.format("%dh %dm", hours, minutes) :
						String.format("%dm", minutes);

					JLabel durationLabel = CardWidgets.label(String.format("Duration: %s", duration), COLOR_TEXT_DIM_GRAY, FONT_PLAIN_12);

					// GE Tax
					JLabel taxLabel = CardWidgets.label(String.format("GE Tax: %s", PanelFormat.formatGP(flip.getGeTax())), COLOR_TEXT_DIM_GRAY, FONT_PLAIN_12);

					extraDetails.add(durationLabel);
					extraDetails.add(Box.createRigidArea(new Dimension(0, 2)));
					extraDetails.add(taxLabel);

					panel.add(extraDetails, BorderLayout.SOUTH);
					expanded = true;
				}
				else
				{
					// Remove extra details
					if (panel.getComponentCount() > 2)
					{
						panel.remove(2);
						expanded = false;
					}
				}

				panel.revalidate();
				panel.repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				maybeShowCompletedMenu(e);
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				maybeShowCompletedMenu(e);
			}

			private void maybeShowCompletedMenu(MouseEvent e)
			{
				if (e.isPopupTrigger())
				{
					showItemContextMenu(flip.getItemId(), flip.getItemName(), completedStarLabel,
						e.getComponent(), e.getX(), e.getY());
				}
			}
		});

		return panel;
	}

	/**
	 * Dismiss an active flip (remove from tracking)
	 */
	private void dismissActiveFlip(ActiveFlip flip)
	{
		int result = JOptionPane.showConfirmDialog(
			this,
			String.format("Remove %s from active flips?%n%nThis will hide it from tracking.%nUse this if you sold/used the items outside of the GE.", flip.getItemName()),
			"Dismiss Active Flip",
			JOptionPane.YES_NO_OPTION,
			JOptionPane.QUESTION_MESSAGE
		);

		if (result == JOptionPane.YES_OPTION)
		{
			// Dismiss asynchronously with RSN filter for multi-account support
			String rsn = plugin.getCurrentRsnSafe().orElse(null);
			apiClient.dismissActiveFlipAsync(flip.getItemId(), rsn).thenAccept(success ->
			{
				SwingUtilities.invokeLater(() ->
				{
					if (Boolean.TRUE.equals(success))
					{
						// Refresh the active flips list
						refreshActiveFlips();
						JOptionPane.showMessageDialog(
							this,
							String.format("%s has been removed from active flips.", flip.getItemName()),
							"Dismissed",
							JOptionPane.INFORMATION_MESSAGE
						);
					}
					else
					{
						JOptionPane.showMessageDialog(
							this,
							"Failed to dismiss active flip. Please try again.",
							ERROR_DIALOG_TITLE,
							JOptionPane.ERROR_MESSAGE
						);
					}
				});
			});
		}
	}

	/**
	 * Get the current scroll position of a scroll pane.
	 */
	private int getScrollPosition(JScrollPane scrollPane)
	{
		if (scrollPane == null || scrollPane.getVerticalScrollBar() == null)
		{
			return 0;
		}
		return scrollPane.getVerticalScrollBar().getValue();
	}

	/**
	 * Restore the scroll position of a scroll pane after content refresh.
	 * Uses invokeLater to ensure layout is complete before restoring.
	 */
	private void restoreScrollPosition(JScrollPane scrollPane, int position)
	{
		if (scrollPane == null || scrollPane.getVerticalScrollBar() == null || position <= 0)
		{
			return;
		}
		// Use invokeLater to restore after layout is complete
		SwingUtilities.invokeLater(() -> scrollPane.getVerticalScrollBar().setValue(position));
	}

	/**
	 * Toggle auto-recommend on/off.
	 * When turned on, starts cycling through current recommendations into Flip Assist.
	 */
	private void toggleAutoRecommend()
	{
		AutoRecommendService service = plugin.getAutoRecommendService();
		if (service == null)
		{
			autoRecommendButton.setSelected(false);
			return;
		}

		if (autoRecommendButton.isSelected())
		{
			// Starting auto-recommend
			if (currentRecommendations.isEmpty())
			{
				autoRecommendButton.setSelected(false);
				autoRecommendStatusLabel.setText("No recommendations - refresh first");
				autoRecommendStatusLabel.setVisible(true);
				return;
			}

			// Wire status callback
			service.setOnStatusChanged(status -> SwingUtilities.invokeLater(() -> {
				autoRecommendStatusLabel.setText(status);
				autoRecommendStatusLabel.setVisible(true);
			}));

			// Wire queue advanced callback to repaint panel highlight
			service.setOnQueueAdvanced(this::repopulateRecommendationsGated);

			// Wire skip-exhausted callback to fetch fresh recommendations
			service.setOnQueueExhausted(() -> refreshRecommendations(true));

			service.start(new ArrayList<>(currentRecommendations));

			// Check if start() actually activated the service (it may bail if all items are filtered)
			if (!service.isActive())
			{
				autoRecommendButton.setSelected(false);
				return;
			}

			// Switch to Recommended tab
			tabbedPane.setSelectedIndex(TAB_RECOMMENDED);

			// Start the 2-minute refresh timer
			plugin.startAutoRecommendRefreshTimer();

			autoRecommendButton.setBackground(COLOR_AUTO_RECOMMEND_ACTIVE);
			autoRecommendButton.setForeground(Color.WHITE);
			autoRecommendButton.setText("Auto");
			skipButton.setVisible(true);
			log.debug("Auto-recommend enabled with {} recommendations", currentRecommendations.size());
		}
		else
		{
			// Stopping auto-recommend
			service.stop();
			plugin.stopAutoRecommendRefreshTimer();

			autoRecommendButton.setBackground(null);
			autoRecommendButton.setForeground(Color.WHITE);
			autoRecommendButton.setText("Auto");
			skipButton.setVisible(false);
			autoRecommendStatusLabel.setVisible(false);

			// Repaint recommendations to remove highlight
			repopulateRecommendationsGated();

			log.debug("Auto-recommend disabled");
		}
	}

	/**
	 * Show or hide the auto-recommend button based on config setting.
	 */
	public void setAutoRecommendVisible(boolean visible)
	{
		SwingUtilities.invokeLater(() -> {
			autoRecommendButton.setVisible(visible);
			if (!visible && autoRecommendButton.isSelected())
			{
				autoRecommendButton.setSelected(false);
				AutoRecommendService service = plugin.getAutoRecommendService();
				if (service != null && service.isActive())
				{
					service.stop();
					plugin.stopAutoRecommendRefreshTimer();
				}
				skipButton.setVisible(false);
				autoRecommendStatusLabel.setVisible(false);
			}
		});
	}

	/**
	 * Update the auto-recommend button state (e.g., when service is stopped externally).
	 */
	public void updateAutoRecommendButton(boolean active)
	{
		SwingUtilities.invokeLater(() -> {
			autoRecommendButton.setSelected(active);
			skipButton.setVisible(active);
			if (active)
			{
				autoRecommendButton.setBackground(COLOR_AUTO_RECOMMEND_ACTIVE);
				autoRecommendButton.setForeground(Color.WHITE);
				autoRecommendButton.setText("Auto");
			}
			else
			{
				autoRecommendButton.setBackground(null);
				autoRecommendButton.setForeground(Color.WHITE);
				autoRecommendButton.setText("Auto");
				autoRecommendStatusLabel.setVisible(false);
			}
		});
	}
}

package com.flipsmart;

import lombok.Value;

import javax.inject.Singleton;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.List;
import java.util.concurrent.ConcurrentLinkedDeque;

/**
 * Bounded, in-memory log of recent fulfilled GE trade events used by the Flip
 * Assist "waiting for flips" hint. Newest entries are at the front; older
 * entries beyond {@link #MAX_ENTRIES} are dropped.
 *
 * <p>Each entry represents a single fill event ("Bought 28x Bow string"); a
 * partially filled offer that fills again later produces two separate entries
 * because the user perceives them as distinct activity beats.
 */
@Singleton
public class TradeActivityLog
{
	public static final int MAX_ENTRIES = 4;

	@Value
	public static class Entry
	{
		int itemId;
		String itemName;
		boolean buy;
		int quantity;
		long timestampMs;
	}

	private final Deque<Entry> entries = new ConcurrentLinkedDeque<>();

	public void addEntry(int itemId, String itemName, boolean isBuy, int quantity)
	{
		if (quantity <= 0 || itemName == null)
		{
			return;
		}
		entries.addFirst(new Entry(itemId, itemName, isBuy, quantity, System.currentTimeMillis()));
		while (entries.size() > MAX_ENTRIES)
		{
			entries.pollLast();
		}
	}

	public List<Entry> snapshot()
	{
		return Collections.unmodifiableList(new ArrayList<>(entries));
	}

	public boolean isEmpty()
	{
		return entries.isEmpty();
	}

	public void clear()
	{
		entries.clear();
	}
}

package com.flipsmart.v9;

import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Per-flip state for a V9 short-timeframe sell, carried from first listing through the
 * re-adjustment ladder. The timeframe is snapshotted at listing time so a later change to
 * the global timeframe config never re-points an in-flight flip's rungs.
 */
@Data
@NoArgsConstructor
public class V9FlipState
{
	private int itemId;
	private String timeframe;
	private long listingTimestampMs;
	private String scenario;
	private Long scenarioBMid;
	private long buyPrice;
	private int totalQty;
	private int remainingQty;
	private long originalTarget;
	private int ladderRung;
	private long ladder1ResolvedAtMs;
	private long seed;
	private long realizedProfit;
	private long savedAtMillis;
}

package com.flipsmart.v9;

/**
 * Decides when a V9 short-timeframe flip owns an item's sell, and how to resolve the sell
 * target for its first listing. Pure logic, split out from the plugin so the hand-off between
 * V9 and the legacy adjustment paths is unit-testable.
 */
public final class V9SellArbitration
{
	private V9SellArbitration()
	{
	}

	/**
	 * True once V9 is tracking a flip for this item, from buy-basis capture onward — not only
	 * after the re-adjustment ladder has armed. The legacy sell-adjustment paths key off this to
	 * stand down, so a flip whose first listing has not yet fired can never be grabbed by the
	 * legacy path and re-priced below its V9 target.
	 */
	public static boolean v9OwnsSell(boolean v9Enabled, V9FlipState state)
	{
		return v9Enabled && state != null;
	}

	/**
	 * Sell target for the first listing: the live session recommendation when present, otherwise
	 * the target snapshotted on the flip state at buy time. Returns 0 when neither is available.
	 */
	public static long resolveFirstListingTarget(Long sessionRecommendation, V9FlipState state)
	{
		if (sessionRecommendation != null && sessionRecommendation > 0)
		{
			return sessionRecommendation;
		}
		return state != null ? state.getOriginalTarget() : 0L;
	}
}

package com.flipsmart.v9;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Holds and persists {@link V9FlipState} per active sell, keyed by item id, scoped per RSN.
 * Follows the existing offer/ledger persistence idiom (JSON blob under the flipsmart config
 * group). Absolute timers are never stored — rungs are recomputed from the listing timestamp
 * on restore, so offline elapsed time counts. Entries older than {@link #MAX_AGE_MS} are
 * dropped on load so a long-abandoned flip can't resurrect a stale prompt.
 */
@Slf4j
public class V9FlipStateStore
{
	private static final String CONFIG_GROUP = "flipsmart";
	private static final String KEY_PREFIX = "v9FlipState_";

	// Covers the longest ladder (4h: 2h40m + 2h40m) with generous margin.
	static final long MAX_AGE_MS = 6L * 60L * 60L * 1000L;

	private final Gson gson;
	private final Map<Integer, V9FlipState> byItem = new ConcurrentHashMap<>();

	public V9FlipStateStore(Gson gson)
	{
		this.gson = gson;
	}

	public V9FlipState get(int itemId)
	{
		return byItem.get(itemId);
	}

	public void put(V9FlipState state)
	{
		if (state != null)
		{
			byItem.put(state.getItemId(), state);
		}
	}

	public void remove(int itemId)
	{
		byItem.remove(itemId);
	}

	public Map<Integer, V9FlipState> snapshot()
	{
		return new HashMap<>(byItem);
	}

	public void clear()
	{
		byItem.clear();
	}

	/** Serialize the current map to JSON (pure; the persistence entry points wrap this). */
	String serialize(long now)
	{
		Map<Integer, V9FlipState> out = new HashMap<>();
		for (V9FlipState s : byItem.values())
		{
			s.setSavedAtMillis(now);
			out.put(s.getItemId(), s);
		}
		return gson.toJson(out);
	}

	/** Replace the in-memory map from JSON, dropping entries older than {@link #MAX_AGE_MS}. */
	void load(String json, long now)
	{
		byItem.clear();
		if (json == null || json.isEmpty())
		{
			return;
		}
		try
		{
			Type type = new TypeToken<Map<Integer, V9FlipState>>() {}.getType();
			Map<Integer, V9FlipState> parsed = gson.fromJson(json, type);
			if (parsed == null)
			{
				return;
			}
			for (V9FlipState s : parsed.values())
			{
				if (s == null)
				{
					continue;
				}
				if (now - s.getSavedAtMillis() <= MAX_AGE_MS)
				{
					byItem.put(s.getItemId(), s);
				}
			}
		}
		catch (Exception e)
		{
			logLoadFailure(e);
		}
	}

	private void logLoadFailure(Exception e)
	{
		if (log.isDebugEnabled())
		{
			log.debug("Ignoring unreadable persisted v9 flip state ({})", e.getMessage());
		}
	}

	public void persist(ConfigManager configManager, String rsn)
	{
		if (rsn == null || rsn.isEmpty())
		{
			return;
		}
		try
		{
			if (byItem.isEmpty())
			{
				configManager.unsetConfiguration(CONFIG_GROUP, KEY_PREFIX + rsn);
				return;
			}
			configManager.setConfiguration(CONFIG_GROUP, KEY_PREFIX + rsn, serialize(System.currentTimeMillis()));
		}
		catch (Exception e)
		{
			if (log.isDebugEnabled())
			{
				log.debug("Failed to persist v9 flip state for {}: {}", rsn, e.getMessage());
			}
		}
	}

	public void restore(ConfigManager configManager, String rsn)
	{
		if (rsn == null || rsn.isEmpty())
		{
			return;
		}
		String json = configManager.getConfiguration(CONFIG_GROUP, KEY_PREFIX + rsn);
		load(json, System.currentTimeMillis());
	}
}

package com.flipsmart;

import com.flipsmart.domain.offer.OfferSignal;
import com.flipsmart.util.ItemUtils;
import java.text.DecimalFormat;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayMenuEntry;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.util.AsyncBufferedImage;

import java.awt.*;

import static net.runelite.api.MenuAction.RUNELITE_OVERLAY_CONFIG;
import static net.runelite.client.ui.overlay.OverlayManager.OPTION_CONFIGURE;

/**
 * In-game overlay that displays all 8 Grand Exchange offer slots with real-time status.
 * Shown regardless of world location; hidden only while a trade or inventory window
 * (Grand Exchange, GE collection box, bank, or bank deposit box) is open.
 */
public class GrandExchangeOverlay extends Overlay
{
	private static final DecimalFormat PERCENTAGE_FORMAT = new DecimalFormat("0");

	// String constants
	private static final String OVERLAY_TITLE = "Exchange Viewer";
	private static final String NO_OFFERS_MESSAGE = "No offers";

	private static final Color COLOR_BUY = new Color(0, 128, 0);  // Dark green
	private static final Color COLOR_SELL = new Color(180, 0, 0); // Dark red
	private static final Color COLOR_COMPLETE = new Color(200, 180, 50); // Gold
	private static final Color COLOR_EMPTY = new Color(128, 128, 128); // Gray
	private static final Color COLOR_CANCELLED = new Color(200, 100, 0); // Orange
	private static final Color COLOR_BACKGROUND = new Color(62, 53, 41); // Dark brown (GE style)
	private static final Color COLOR_BORDER = new Color(0, 0, 0); // Black
	private static final Color COLOR_TITLE = new Color(255, 215, 0); // Gold


	private static final int PADDING = 8;
	private static final int MAX_ITEM_NAME_LENGTH = 12;

	// Compact mode constants
	private static final int COMPACT_LINE_HEIGHT = 14;
	private static final int COMPACT_ICON_SIZE = 18;

	// Layout spacing constants

	// Compact mode spacing constants
	/** Extra Y spacing after title in compact mode */
	private static final int COMPACT_TITLE_SPACING = 2;
	/** X adjustment for compact icon positioning */
	private static final int COMPACT_ICON_X_OFFSET = -2;
	/** Y adjustment for compact icon positioning */
	private static final int COMPACT_ICON_Y_OFFSET = 4;

	private final Client client;
	private final FlipSmartConfig config;
	private final ItemManager itemManager;


	@Inject
	private GrandExchangeOverlay(Client client, FlipSmartConfig config, ItemManager itemManager)
	{
		this.client = client;
		this.config = config;
		this.itemManager = itemManager;

		setPosition(OverlayPosition.DYNAMIC);
		setPriority(OverlayPriority.MED);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setMovable(true);
		setResizable(false);

		getMenuEntries().add(new OverlayMenuEntry(RUNELITE_OVERLAY_CONFIG, OPTION_CONFIGURE, OVERLAY_TITLE));
	}

	/**
	 * Whether the overlay should be suppressed because a trade or inventory window
	 * is open on screen — its contents would be redundant with, or visually conflict
	 * with, the native window. Covers the Grand Exchange, its collection box, the
	 * bank, and the bank deposit box.
	 */
	static boolean shouldSuppressOverlay(Client client)
	{
		return isInterfaceOpen(client, InterfaceID.GE_OFFERS)
			|| isInterfaceOpen(client, InterfaceID.GE_COLLECT)
			|| isInterfaceOpen(client, InterfaceID.BANKMAIN)
			|| isInterfaceOpen(client, InterfaceID.BANK_DEPOSITBOX);
	}

	private static boolean isInterfaceOpen(Client client, int groupId)
	{
		Widget root = client.getWidget(groupId, 0);
		return root != null && !root.isHidden();
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showGEOverlay())
		{
			return null;
		}

		// Hide while a GE/bank window is open — the native window already shows this info
		if (shouldSuppressOverlay(client))
		{
			return null;
		}

		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();

		// GE offers may be null if player hasn't opened GE this session
		// In that case, don't show overlay
		if (offers == null)
		{
			return null;
		}

		// Use RuneLite's font for crisp rendering
		graphics.setFont(FontManager.getRunescapeFont());

		// Enable proper anti-aliasing
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		graphics.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		return renderCompact(graphics, offers);
	}

	/**
	 * Panel background, border and centred drop-shadowed title, shared by the collapsed
	 * header and both overlay layouts. Compact draws a single border and the small font;
	 * the other two double the border and use bold. Sets the font, so callers needing
	 * metrics afterwards read them from the graphics context.
	 */
	private void drawPanelChrome(Graphics2D graphics, int x, int y, int width, int height, int titleBaselineY,
		boolean compact)
	{
		graphics.setColor(COLOR_BACKGROUND);
		graphics.fillRect(x, y, width, height);
		graphics.setColor(COLOR_BORDER);
		graphics.drawRect(x, y, width, height);
		if (!compact)
		{
			graphics.drawRect(x + 1, y + 1, width - 2, height - 2);
		}
		graphics.setFont(compact ? FontManager.getRunescapeSmallFont() : FontManager.getRunescapeBoldFont());
		FontMetrics metrics = graphics.getFontMetrics();
		int titleX = x + (width - metrics.stringWidth(OVERLAY_TITLE)) / 2;
		graphics.setColor(Color.BLACK);
		graphics.drawString(OVERLAY_TITLE, titleX + 1, titleBaselineY + 1);
		graphics.setColor(COLOR_TITLE);
		graphics.drawString(OVERLAY_TITLE, titleX, titleBaselineY);
	}

	/**
	 * Render the compact (mini) overlay - shows item name and percentage only.
	 */
	private Dimension renderCompact(Graphics2D graphics, GrandExchangeOffer[] offers)
	{
		int totalWidth = 150;

		int x = 0;
		int y = 0;
		int currentY = y + PADDING + COMPACT_LINE_HEIGHT;

		// Count active offers
		int activeCount = 0;
		for (GrandExchangeOffer offer : offers)
		{
			if (offer.getState() != GrandExchangeOfferState.EMPTY)
			{
				activeCount++;
			}
		}

		// Calculate height: title + active offers + padding
		int totalHeight = COMPACT_LINE_HEIGHT + (PADDING * 2);
		if (activeCount == 0)
		{
			totalHeight += COMPACT_LINE_HEIGHT; // "No offers" line
		}
		else
		{
			totalHeight += activeCount * COMPACT_LINE_HEIGHT;
		}

		// Draw background
		drawPanelChrome(graphics, x, y, totalWidth, totalHeight, currentY, true);
		FontMetrics metrics = graphics.getFontMetrics();

		currentY += COMPACT_LINE_HEIGHT + COMPACT_TITLE_SPACING;

		// Render each slot
		for (int slot = 0; slot < offers.length; slot++)
		{
			GrandExchangeOffer offer = offers[slot];

			if (offer.getState() == GrandExchangeOfferState.EMPTY)
			{
				continue;
			}

			GrandExchangeOfferState state = offer.getState();
			int itemId = offer.getItemId();
			int quantitySold = offer.getQuantitySold();
			int totalQuantity = offer.getTotalQuantity();

			boolean isBuy = OfferSignal.isBuyState(state);

			double percentage = totalQuantity > 0 ? (quantitySold * 100.0) / totalQuantity : 0;
			String itemName = ItemUtils.getItemName(itemManager, itemId);

			// Truncate item name if too long
			if (itemName.length() > MAX_ITEM_NAME_LENGTH)
			{
				itemName = itemName.substring(0, MAX_ITEM_NAME_LENGTH - 1) + "..";
			}

			Color statusColor = getStatusColor(state, isBuy);

			AsyncBufferedImage itemImage = itemManager.getImage(itemId);
			if (itemImage != null && itemImage.getWidth() > 0)
			{
				int iconX = x + PADDING + COMPACT_ICON_X_OFFSET;
				int iconY = currentY - COMPACT_ICON_SIZE + COMPACT_ICON_Y_OFFSET;
				graphics.drawImage(itemImage, iconX, iconY, COMPACT_ICON_SIZE, COMPACT_ICON_SIZE, null);
			}

			// Draw item name with B/S indicator
			int textX = x + PADDING + COMPACT_ICON_SIZE;
			String displayText = (isBuy ? "B: " : "S: ") + itemName;
			graphics.setColor(Color.BLACK);
			graphics.drawString(displayText, textX + 1, currentY + 1);
			graphics.setColor(isBuy ? COLOR_BUY : COLOR_SELL);
			graphics.drawString(displayText, textX, currentY);

			// Draw percentage on the right
			String pctText = PERCENTAGE_FORMAT.format(percentage) + "%";
			int pctWidth = metrics.stringWidth(pctText);
			int pctX = x + totalWidth - PADDING - pctWidth;
			graphics.setColor(Color.BLACK);
			graphics.drawString(pctText, pctX + 1, currentY + 1);
			graphics.setColor(statusColor);
			graphics.drawString(pctText, pctX, currentY);

			currentY += COMPACT_LINE_HEIGHT;
		}

		// No offers message
		if (activeCount == 0)
		{
			graphics.setColor(COLOR_EMPTY);
			drawCenteredString(graphics, NO_OFFERS_MESSAGE, x, currentY, totalWidth);
		}

		return new Dimension(totalWidth, totalHeight);
	}


	/**
	 * Get the status color for an offer state.
	 */
	private Color getStatusColor(GrandExchangeOfferState state, boolean isBuy)
	{
		switch (state)
		{
			case BOUGHT:
			case SOLD:
				return COLOR_COMPLETE;
			case CANCELLED_BUY:
			case CANCELLED_SELL:
				return COLOR_CANCELLED;
			case BUYING:
			case SELLING:
				return isBuy ? COLOR_BUY : COLOR_SELL;
			default:
				return COLOR_EMPTY;
		}
	}

	private void drawCenteredString(Graphics2D g, String text, int x, int y, int width)
	{
		FontMetrics metrics = g.getFontMetrics();
		int textX = x + (width - metrics.stringWidth(text)) / 2;
		g.drawString(text, textX, y);
	}



}

package com.flipsmart.plugin;

import java.util.List;
import java.util.Timer;
import java.util.TimerTask;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.BooleanSupplier;
import java.util.function.LongSupplier;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

/**
 * Owns the FlipSmart plugin's background timers and one-shot Swing timers.
 *
 * The plugin delegates all timer lifecycle to this collaborator: startUp wires
 * and starts the timers, shutDown stops them. Cadence, daemon flags, logged-in
 * guards and the one-shot tracking semantics are preserved exactly as they were
 * when this logic lived on the plugin.
 */
@Slf4j
public class PluginScheduler
{
	/** Auto-recommend queue refresh interval (2 minutes) */
	public static final long AUTO_RECOMMEND_REFRESH_INTERVAL_MS = 2 * 60 * 1000L;

	/** Active-offer advisor poll interval (30 seconds) */
	public static final long ACTIVE_OFFER_ADVISOR_INTERVAL_MS = 30_000L;
	public static final long ACTIVE_OFFER_ADVISOR_EVENT_DEBOUNCE_MS = 3_000L;

	/** Active Flips snapshot heartbeat interval (5 minutes), deliberately not user-configurable */
	public static final long ACTIVE_FLIPS_SNAPSHOT_INTERVAL_MS = 5 * 60 * 1000L;

	/** Delay before syncing offline fills after login */
	public static final int OFFLINE_SYNC_DELAY_MS = 2000;
	/** Delay before refreshing panel after sync */
	public static final int PANEL_REFRESH_DELAY_MS = 1000;
	/** Delay before cleaning up stale flips (allows GE state to stabilize) */
	public static final int STALE_FLIP_CLEANUP_DELAY_MS = 15000;
	/** Delay before validating inventory quantities */
	public static final int INVENTORY_VALIDATION_DELAY_MS = 2000;
	/** Delay before re-evaluating auto-recommend after login sync */
	public static final int AUTO_RECOMMEND_REEVALUATE_DELAY_MS = 3000;

	private Timer flipFinderRefreshTimer;
	private Timer autoRecommendRefreshTimer;
	private Timer activeOfferAdvisorTimer;
	private Timer activeFlipsSnapshotTimer;

	/**
	 * Wall-clock instant at which the flip-finder auto-refresh timer will next fire.
	 * This is the single source of truth for the "Item refresh in Ns" countdown the
	 * panel renders — the visual label reads this value rather than tracking its own
	 * independent deadline, so a manual refresh (which restarts the timer) always
	 * moves the countdown and the actual refresh together. 0 when the timer is stopped.
	 */
	@Getter
	private volatile long nextFlipFinderRefreshAtMillis;

	private final LongSupplier clock;

	private final List<javax.swing.Timer> activeOneShotTimers = new CopyOnWriteArrayList<>();

	public PluginScheduler()
	{
		this(System::currentTimeMillis);
	}

	/** Test seam: inject a deterministic clock for the refresh-cadence bookkeeping. */
	PluginScheduler(LongSupplier clock)
	{
		this.clock = clock;
	}

	/**
	 * Start the auto-refresh timer for flip finder.
	 *
	 * @param refreshMinutesRaw the configured refresh interval in minutes (clamped 1..60)
	 * @param loggedInCheck     supplies whether the player is logged into RuneScape
	 * @param refreshBody       the per-tick body to run when logged in (matches the
	 *                          original timer task body byte-for-byte)
	 */
	public void startFlipFinderRefreshTimer(int refreshMinutesRaw, BooleanSupplier loggedInCheck, Runnable refreshBody)
	{
		if (flipFinderRefreshTimer != null)
		{
			flipFinderRefreshTimer.cancel();
		}

		flipFinderRefreshTimer = new Timer("FlipFinderRefreshTimer", true);

		int refreshMinutes = Math.max(1, Math.min(60, refreshMinutesRaw));
		long refreshIntervalMs = refreshMinutes * 60 * 1000L;

		// Start (or restart, e.g. on a manual refresh) resets the countdown deadline
		// to a full interval from now, keeping the visual countdown and the actual
		// refresh trigger synchronized.
		nextFlipFinderRefreshAtMillis = clock.getAsLong() + refreshIntervalMs;

		flipFinderRefreshTimer.scheduleAtFixedRate(new TimerTask()
		{
			@Override
			public void run()
			{
				// The fixed-rate timer fires regardless of login state; advance the
				// countdown deadline on every tick so the label tracks the real next fire.
				nextFlipFinderRefreshAtMillis = clock.getAsLong() + refreshIntervalMs;
				if (!loggedInCheck.getAsBoolean())
				{
					log.debug("Skipping auto-refresh - player not logged into RuneScape");
					return;
				}
				refreshBody.run();
			}
		}, refreshIntervalMs, refreshIntervalMs);

		log.debug("Flip Finder auto-refresh started (every {} minutes)", refreshMinutes);
	}

	public void stopFlipFinderRefreshTimer()
	{
		if (flipFinderRefreshTimer != null)
		{
			flipFinderRefreshTimer.cancel();
			flipFinderRefreshTimer = null;
			nextFlipFinderRefreshAtMillis = 0;
			log.debug("Flip Finder auto-refresh stopped");
		}
	}

	/**
	 * Start the auto-recommend refresh timer (2-minute interval).
	 *
	 * @param loggedInCheck supplies whether the player is logged into RuneScape
	 * @param refreshCycle  the cycle body to run when logged in
	 */
	/**
	 * A daemon timer running {@code body} every {@code intervalMs}, but only while the
	 * player is logged in. All three plugin timers share this shape; they differ only in
	 * how they dispose of the previous timer, which stays with each caller.
	 */
	private static Timer startGatedTimer(String name, long intervalMs,
		BooleanSupplier loggedInCheck, Runnable body)
	{
		Timer timer = new Timer(name, true);
		timer.scheduleAtFixedRate(new TimerTask()
		{
			@Override
			public void run()
			{
				if (loggedInCheck.getAsBoolean())
				{
					body.run();
				}
			}
		}, intervalMs, intervalMs);
		return timer;
	}

	public void startAutoRecommendRefreshTimer(BooleanSupplier loggedInCheck, Runnable refreshCycle)
	{
		stopAutoRecommendRefreshTimer();

		autoRecommendRefreshTimer = startGatedTimer("AutoRecommendRefreshTimer",
			AUTO_RECOMMEND_REFRESH_INTERVAL_MS, loggedInCheck, refreshCycle);

		log.debug("Auto-recommend refresh timer started (every 2 minutes)");
	}

	public void stopAutoRecommendRefreshTimer()
	{
		if (autoRecommendRefreshTimer != null)
		{
			autoRecommendRefreshTimer.cancel();
			autoRecommendRefreshTimer = null;
		}
	}

	/** True when the auto-recommend refresh timer is running. */
	public boolean isAutoRecommendRefreshTimerRunning()
	{
		return autoRecommendRefreshTimer != null;
	}

	/**
	 * Start the active-offer advisor poll timer (30-second interval).
	 *
	 * @param loggedInCheck supplies whether the player is logged into RuneScape
	 * @param pollBody      the poll body to run on each interval when logged in
	 */
	public void startActiveOfferAdvisorTimer(BooleanSupplier loggedInCheck, Runnable pollBody)
	{
		activeOfferAdvisorTimer = startGatedTimer("ActiveOfferAdvisorTimer",
			ACTIVE_OFFER_ADVISOR_INTERVAL_MS, loggedInCheck, pollBody);
	}

	public void stopActiveOfferAdvisorTimer()
	{
		if (activeOfferAdvisorTimer != null)
		{
			activeOfferAdvisorTimer.cancel();
			activeOfferAdvisorTimer = null;
		}
	}

	/**
	 * Start the Active Flips snapshot heartbeat (5-minute interval). Deliberately its
	 * own timer rather than riding the user-configurable flip-finder refresh, which can
	 * be set up to 60 minutes and would let a player leave the web dashboard that stale.
	 *
	 * @param loggedInCheck supplies whether the player is logged into RuneScape
	 * @param body          the heartbeat body to run on each interval when logged in
	 */
	public void startActiveFlipsSnapshotTimer(BooleanSupplier loggedInCheck, Runnable body)
	{
		if (activeFlipsSnapshotTimer != null)
		{
			activeFlipsSnapshotTimer.cancel();
		}

		activeFlipsSnapshotTimer = startGatedTimer("ActiveFlipsSnapshotTimer",
			ACTIVE_FLIPS_SNAPSHOT_INTERVAL_MS, loggedInCheck, body);
	}

	public void stopActiveFlipsSnapshotTimer()
	{
		if (activeFlipsSnapshotTimer != null)
		{
			activeFlipsSnapshotTimer.cancel();
			activeFlipsSnapshotTimer = null;
		}
	}

	/**
	 * Create and start a tracked one-shot Swing timer. The timer is automatically
	 * removed from tracking after it fires. All tracked timers are stopped on shutdown.
	 */
	public void scheduleOneShot(int delayMs, Runnable action)
	{
		javax.swing.Timer timer = new javax.swing.Timer(delayMs, null);
		timer.addActionListener(e ->
		{
			try
			{
				action.run();
			}
			finally
			{
				activeOneShotTimers.remove(timer);
			}
		});
		timer.setRepeats(false);
		activeOneShotTimers.add(timer);
		timer.start();
	}

	/** Stop all active one-shot Swing timers. */
	public void stopAllOneShotTimers()
	{
		for (javax.swing.Timer timer : activeOneShotTimers)
		{
			timer.stop();
		}
		activeOneShotTimers.clear();
	}
}

package com.flipsmart.plugin;

import java.util.function.BiConsumer;
import java.util.function.LongSupplier;

/**
 * Coalesces event-driven panel refresh requests so a burst of GE offer events
 * produces one API-backed refresh per quiet window instead of one per event.
 * A window closes {@link #QUIET_WINDOW_MS} after the last request, or
 * {@link #MAX_WAIT_MS} after the first request during a continuous stream.
 * Requests carry a level: a full refresh covers recommendations, active flips,
 * and completed flips; an active-flips request refreshes only that list. A full
 * request upgrades the pending window and is never downgraded.
 *
 * Manual and timer-driven refreshes call the panel directly and bypass this.
 */
public class PanelRefreshCoalescer
{
	public static final int QUIET_WINDOW_MS = 5_000;
	// A completed flip changes session P&L, which the user watches update live; that refresh
	// wants a much shorter quiet window than a burst of routine offer events does.
	public static final int FAST_QUIET_WINDOW_MS = 750;
	public static final int MAX_WAIT_MS = 10_000;

	private final BiConsumer<Integer, Runnable> oneShotScheduler;
	private final LongSupplier clock;
	private final Runnable fullRefresh;
	private final Runnable activeFlipsRefresh;

	private boolean windowOpen;
	private boolean fullRequested;
	private long firstRequestAt;
	private long lastRequestAt;
	// The quiet window for the pending cycle. The fastest request in a cycle wins, so a
	// completed-flip refresh riding an open offer-event window still fires promptly.
	private int quietWindowMs = QUIET_WINDOW_MS;

	public PanelRefreshCoalescer(BiConsumer<Integer, Runnable> oneShotScheduler, LongSupplier clock,
		Runnable fullRefresh, Runnable activeFlipsRefresh)
	{
		this.oneShotScheduler = oneShotScheduler;
		this.clock = clock;
		this.fullRefresh = fullRefresh;
		this.activeFlipsRefresh = activeFlipsRefresh;
	}

	/** Request a refresh when the current window closes, opening one if needed. */
	public void request(boolean full)
	{
		request(full, QUIET_WINDOW_MS);
	}

	/** As {@link #request} but with the short quiet window, for a refresh the user watches live. */
	public void requestSoon(boolean full)
	{
		request(full, FAST_QUIET_WINDOW_MS);
	}

	private void request(boolean full, int quietMs)
	{
		int scheduleMs;
		synchronized (this)
		{
			long now = clock.getAsLong();
			lastRequestAt = now;
			fullRequested |= full;
			if (windowOpen)
			{
				quietWindowMs = Math.min(quietWindowMs, quietMs);
				return;
			}
			windowOpen = true;
			firstRequestAt = now;
			quietWindowMs = quietMs;
			scheduleMs = quietMs;
		}
		oneShotScheduler.accept(scheduleMs, this::onTimerFire);
	}

	private void onTimerFire()
	{
		Runnable action = null;
		int nextDelayMs = 0;
		synchronized (this)
		{
			long now = clock.getAsLong();
			long sinceLast = now - lastRequestAt;
			long sinceFirst = now - firstRequestAt;
			if (sinceLast >= quietWindowMs || sinceFirst >= MAX_WAIT_MS)
			{
				action = fullRequested ? fullRefresh : activeFlipsRefresh;
				windowOpen = false;
				fullRequested = false;
				quietWindowMs = QUIET_WINDOW_MS;
			}
			else
			{
				nextDelayMs = (int) Math.max(1, Math.min(quietWindowMs - sinceLast, MAX_WAIT_MS - sinceFirst));
			}
		}
		if (action != null)
		{
			action.run();
		}
		else
		{
			oneShotScheduler.accept(nextDelayMs, this::onTimerFire);
		}
	}
}

package com.flipsmart.plugin;

/**
 * Deduplicates RSN pushes to the backend. The RSN sync path fires on every
 * LOGGED_IN transition — including every world hop — but the backend only
 * needs to hear about an RSN it has not been told about this client session.
 * Callers mark a push only after the backend confirms it, so a failed push
 * is retried on the next login transition.
 */
public class RsnSyncGate
{
	private volatile String lastPushedRsn = "";

	public boolean shouldPush(String rsn)
	{
		return rsn != null && !rsn.isEmpty() && !rsn.equals(lastPushedRsn);
	}

	public void markPushed(String rsn)
	{
		lastPushedRsn = rsn;
	}

	/** Forget the pushed state so the next sync pushes again (e.g. after re-auth). */
	public void reset()
	{
		lastPushedRsn = "";
	}
}

package com.flipsmart.plugin;

import com.flipsmart.BankSnapshotService;
import com.flipsmart.FlipSmartConfig;
import com.flipsmart.FlipSmartPlugin;
import com.flipsmart.GEHistoryService;
import com.flipsmart.GeOfferDescriptionService;
import com.flipsmart.GrandExchangeTracker;
import com.flipsmart.OfflineSyncService;
import com.flipsmart.PlayerSession;
import com.flipsmart.WebhookSyncService;
import com.flipsmart.trading.OfferStore;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.ScriptID;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.VarClientIntChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.events.WorldChanged;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.events.ConfigChanged;

/**
 * Routes RuneLite EventBus events to the appropriate collaborators.
 *
 * The {@code @Subscribe} methods stay physically on {@link FlipSmartPlugin}
 * (RuneLite scans the registered plugin object for them) but are reduced to thin
 * stubs that delegate here. The handler bodies that depend only on injected
 * collaborators and already-exposed plugin hooks were moved verbatim into this
 * class. A couple of handlers ({@code onGameTick}, {@code onVarClientIntChanged})
 * remain coupled to plugin-private mutable state set during startUp; for those,
 * the router delegates straight back to the plugin so the behavior and ordering
 * are preserved exactly.
 */
public class EventRouter
{
	private static final String CONFIG_GROUP = "flipsmart";
	private static final int INVENTORY_CONTAINER_ID = 93;

	private final FlipSmartPlugin plugin;
	private final Client client;
	private final FlipSmartConfig config;
	private final PlayerSession session;
	private final WebhookSyncService webhookSyncService;
	private final OfflineSyncService offlineSyncService;
	private final BankSnapshotService bankSnapshotService;
	private final GEHistoryService geHistoryService;
	private final GeOfferDescriptionService geOfferDescriptionService;
	private final GrandExchangeTracker grandExchangeTracker;
	private final OfferStore offerStore;

	public EventRouter(FlipSmartPlugin plugin, Client client, FlipSmartConfig config,
		PlayerSession session, WebhookSyncService webhookSyncService, OfflineSyncService offlineSyncService,
		BankSnapshotService bankSnapshotService, GEHistoryService geHistoryService,
		GeOfferDescriptionService geOfferDescriptionService, GrandExchangeTracker grandExchangeTracker,
		OfferStore offerStore)
	{
		this.plugin = plugin;
		this.client = client;
		this.config = config;
		this.session = session;
		this.webhookSyncService = webhookSyncService;
		this.offlineSyncService = offlineSyncService;
		this.bankSnapshotService = bankSnapshotService;
		this.geHistoryService = geHistoryService;
		this.geOfferDescriptionService = geOfferDescriptionService;
		this.grandExchangeTracker = grandExchangeTracker;
		this.offerStore = offerStore;
	}

	public void onConfigChanged(ConfigChanged configChanged)
	{
		if (!CONFIG_GROUP.equals(configChanged.getGroup()))
		{
			return;
		}

		if ("showFlipFinder".equals(configChanged.getKey()))
		{
			// Add/remove the sidebar panel live so the toggle takes effect without a
			// plugin or client restart.
			if (config.showFlipFinder())
			{
				plugin.showFlipFinderPanel();
			}
			else
			{
				plugin.hideFlipFinderPanel();
			}
		}

		if ("enableAutoRecommend".equals(configChanged.getKey()) && plugin.getFlipFinderPanel() != null)
		{
			plugin.getFlipFinderPanel().setAutoRecommendVisible(config.enableAutoRecommend());
		}

		if ("f2pMode".equals(configChanged.getKey()) && plugin.getFlipFinderPanel() != null)
		{
			plugin.getFlipFinderPanel().refresh();
		}

		if (("cashstackOverrideEnabled".equals(configChanged.getKey())
			|| "cashstackOverrideAmount".equals(configChanged.getKey())) && plugin.getFlipFinderPanel() != null)
		{
			plugin.getFlipFinderPanel().updateCashstackOverrideIndicator();
			plugin.getFlipFinderPanel().refresh();
		}

		String key = configChanged.getKey();
		if ("discordWebhookUrl".equals(key) || "notifySaleCompleted".equals(key))
		{
			webhookSyncService.syncIfChanged();
		}
	}

	public void onGameStateChanged(GameStateChanged gameStateChanged)
	{
		GameState gameState = gameStateChanged.getGameState();

		if (gameState == GameState.LOGGING_IN || gameState == GameState.HOPPING || gameState == GameState.CONNECTION_LOST)
		{
			session.onLoginStateChange(client.getTickCount());

			// These transitions clear offlineSyncCompleted, so the sync will run again on the
			// LOGGED_IN that follows. GEHistoryService has to be cleared with it: its
			// historyReadThisSession latch used to survive here (only LOGIN_SCREEN reset it),
			// so any session in which the player had opened the History tab once silently
			// dropped every offline fill across every later hop and reconnect.
			geHistoryService.reset();

			if (!offerStore.export().isEmpty())
			{
				offlineSyncService.persistOfferState();
			}
		}

		if (gameState == GameState.LOGIN_SCREEN)
		{
			plugin.handleLogoutState();
		}

		if (gameState == GameState.LOGGED_IN)
		{
			plugin.handleLoggedInState();
		}
	}

	public void onWorldChanged(WorldChanged event)
	{
		plugin.updateMembersWorldCache();
		if (plugin.getFlipFinderPanel() != null)
		{
			plugin.getFlipFinderPanel().refresh();
		}
	}

	public void onGameTick(GameTick event)
	{
		plugin.onGameTickHandler(event);
	}

	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int containerId = event.getContainerId();

		if (containerId == INVENTORY_CONTAINER_ID)
		{
			plugin.updateCashStack();
			return;
		}

		if (containerId == InventoryID.BANK.getId())
		{
			bankSnapshotService.onBankContainerChanged(plugin.getCurrentRsnSafe().orElse(null));
		}
	}

	public void onScriptPostFired(ScriptPostFired event)
	{
		if (event.getScriptId() != ScriptID.GE_OFFERS_SETUP_BUILD)
		{
			return;
		}

		if (geOfferDescriptionService != null)
		{
			geOfferDescriptionService.onSetupBuildScriptPostFired();
		}

		int openItemId = client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH);

		// Lock the recommendation as soon as the setup panel builds — the selected
		// item if one is already chosen, otherwise the focused recommendation, so a
		// refresh can't swap it during the empty-open to search window.
		if (plugin.getAutoRecommendService() != null)
		{
			plugin.getAutoRecommendService().acquireOfferLockForOpenSetup(openItemId, plugin.getFocusedFlipItemId());
		}

		int offerType = client.getVarbitValue(VarbitID.GE_NEWOFFER_TYPE);
		if (offerType != 1)
		{
			if (openItemId > 0 && plugin.getAutoRecommendService() != null)
			{
				plugin.getAutoRecommendService().overrideFocusForBuy(openItemId);
			}
			return;
		}

		if (openItemId <= 0)
		{
			return;
		}

		// During queue-driven Exit Trades (breakeven/instant), the flow owns the focus. Scope the
		// prompt to the item actually on the sell screen so working slots out of order never shows a
		// stale queue-pointer item. REGULAR sell-only mode falls through to the normal sell flow.
		if (plugin.getExitTradesController() != null && plugin.getExitTradesController().ownsOverlay())
		{
			plugin.getExitTradesController().onSellScreenOpened(openItemId);
			plugin.maybeRecalc12hSellPrice(openItemId);
			plugin.maybeSuggestV9FirstListing(openItemId);
			plugin.maybeAdvanceV9Ladder(openItemId);
			return;
		}

		grandExchangeTracker.autoFocusOnActiveFlip(openItemId);
		plugin.maybeRecalc12hSellPrice(openItemId);
		plugin.maybeSuggestV9FirstListing(openItemId);
		plugin.maybeAdvanceV9Ladder(openItemId);
	}

	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged offerEvent)
	{
		if (geOfferDescriptionService != null)
		{
			geOfferDescriptionService.recordBuyLimitWindow(offerEvent.getOffer());
		}
		// Delegated back to the plugin: the body builds GrandExchangeTracker.OfferContext,
		// a package-private nested type, so it stays in the com.flipsmart package.
		plugin.onGrandExchangeOfferChangedHandler(offerEvent);
	}

	public void onVarClientIntChanged(VarClientIntChanged event)
	{
		plugin.onVarClientIntChangedHandler(event);
	}

	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.GE_HISTORY)
		{
			geHistoryService.onHistoryWidgetLoaded();
		}
		if (event.getGroupId() == InterfaceID.GE_OFFERS && geOfferDescriptionService != null)
		{
			geOfferDescriptionService.onGeOffersWidgetLoaded();
		}
	}

	public void onScriptCallbackEvent(ScriptCallbackEvent event)
	{
		if (geOfferDescriptionService != null)
		{
			geOfferDescriptionService.onScriptCallbackEvent(event);
		}
	}

	public void onBeforeRender(BeforeRender event)
	{
		if (geOfferDescriptionService != null)
		{
			geOfferDescriptionService.onBeforeRender(event);
		}
	}

	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (geOfferDescriptionService != null)
		{
			geOfferDescriptionService.onMenuOptionClicked(event);
		}
	}
}

package com.flipsmart.plugin;

import com.flipsmart.ActionAlertNotifier;
import com.flipsmart.ActiveFlipTracker;
import com.flipsmart.ActiveOfferAdvisorService;
import com.flipsmart.AutoRecommendService;
import com.flipsmart.FlipAssistOverlay;
import com.flipsmart.FlipSmartConfig;
import com.flipsmart.FlipSmartPlugin;
import com.flipsmart.GEHistoryService;
import com.flipsmart.GrandExchangeSlotOverlay;
import com.flipsmart.InventoryHighlightOverlay;
import com.flipsmart.ManualAdjustmentTracker;
import com.flipsmart.OfflineSyncService;
import com.flipsmart.PlayerSession;
import com.flipsmart.GrandExchangeTracker;
import com.flipsmart.exit.ExitTradesController;
import com.flipsmart.trading.OfferStore;
import com.flipsmart.trading.RoundTripLedger;
import com.flipsmart.trading.TransactionLogger;
import net.runelite.client.Notifier;
import net.runelite.client.ui.ClientUI;

import javax.swing.SwingUtilities;

/**
 * Performs the post-construction setter-callback wiring for the FlipSmart
 * collaborators during startUp().
 *
 * The exact set and order of setter calls and lambda wiring is preserved from
 * when this logic lived directly on {@link FlipSmartPlugin}. The lambdas route
 * plugin-private behavior back through the plugin instance, which exposes the
 * required hooks as package-visible/public methods.
 */
public class ServiceWiring
{
	/**
	 * Wire callbacks for offline sync and active flip tracker services.
	 * (formerly FlipSmartPlugin.wireServiceCallbacks)
	 */
	public void wireServiceCallbacks(FlipSmartPlugin plugin, OfflineSyncService offlineSyncService,
		ActiveFlipTracker activeFlipTracker, PanelRefreshCoalescer refreshCoalescer)
	{
		offlineSyncService.setOnSyncComplete(plugin::schedulePostSyncTasks);
		activeFlipTracker.setOnPanelRefreshNeeded(() -> refreshCoalescer.request(true));
		activeFlipTracker.setOnActiveFlipsRefreshNeeded(() -> refreshCoalescer.request(false));
	}

	/**
	 * Initialize auto-recommend service and wire its callbacks.
	 * (formerly FlipSmartPlugin.initializeAutoRecommendService)
	 *
	 * @return the constructed AutoRecommendService
	 */
	public AutoRecommendService initializeAutoRecommendService(FlipSmartPlugin plugin, FlipSmartConfig config,
		FlipAssistOverlay flipAssistOverlay, GrandExchangeSlotOverlay geSlotOverlay, OfferStore offerStore,
		Notifier notifier, ClientUI clientUI)
	{
		AutoRecommendService autoRecommendService = new AutoRecommendService(config, plugin, offerStore);
		ActionAlertNotifier actionAlerts = new ActionAlertNotifier(notifier, config, plugin::getItemName,
			clientUI::isFocused);
		autoRecommendService.setOnActionAlert(actionAlerts::onDecision);
		autoRecommendService.setOnFocusChanged(plugin::handleAutoRecommendFocusChanged);
		autoRecommendService.setOnOverlayMessageChanged(flipAssistOverlay::setAutoStatusMessage);
		autoRecommendService.setDisplayedSellPriceProvider(itemId -> plugin.getFlipFinderPanel() != null ? plugin.getFlipFinderPanel().getDisplayedSellPrice(itemId) : null);
		autoRecommendService.setOnHighlightItemSlot(plugin::highlightSlotForItem);
		autoRecommendService.setOnClearAllHighlights(geSlotOverlay::clearAllAdjustmentHighlights);
		autoRecommendService.setOnStickyHighlight(geSlotOverlay::setStickyAdjustmentHighlight);
		autoRecommendService.setOnClearStickyHighlight(geSlotOverlay::clearStickyAdjustmentHighlight);
		autoRecommendService.setOnResetAllHighlights(geSlotOverlay::resetAllHighlights);
		flipAssistOverlay.setOnStepChanged(autoRecommendService::onOverlayStepChanged);
		return autoRecommendService;
	}

	/**
	 * Construct the active-offer advisor service and wire its callbacks. The
	 * 30-second poll timer is started separately via the scheduler.
	 * (formerly FlipSmartPlugin.initializeActiveOfferAdvisor, minus the timer)
	 *
	 * @return the constructed ActiveOfferAdvisorService
	 */
	public ActiveOfferAdvisorService initializeActiveOfferAdvisor(FlipSmartPlugin plugin)
	{
		ActiveOfferAdvisorService activeOfferAdvisorService = new ActiveOfferAdvisorService();
		activeOfferAdvisorService.setCallbacks(
			resp -> SwingUtilities.invokeLater(() -> plugin.applyActiveOfferSurface(resp)),
			resp -> SwingUtilities.invokeLater(() -> plugin.handleActiveOfferHandoff(resp)),
			itemId -> SwingUtilities.invokeLater(() -> plugin.clearActiveOfferSurface(itemId)));
		return activeOfferAdvisorService;
	}

	/**
	 * Construct the Exit Trades controller and wire it to the overlay and offer stream.
	 * Prompts route through the same amber focus glow the sell flow already uses; the
	 * offer listener advances the queue and re-surfaces the next slot's prompt on change.
	 *
	 * @return the constructed ExitTradesController
	 */
	public ExitTradesController initializeExitTradesController(FlipSmartPlugin plugin,
		FlipAssistOverlay flipAssistOverlay, GrandExchangeSlotOverlay geSlotOverlay, OfferStore offerStore)
	{
		ExitTradesController controller = new ExitTradesController(offerStore);
		controller.setBuyBasisSupplier(plugin::getExitBuyBasis);
		controller.setBackendSellPriceSupplier(plugin::getExitBackendSellPrice);
		controller.setWikiPriceSupplier(plugin::getWikiPrice);
		controller.setInventoryQtySupplier(plugin::getExitInventoryQty);
		controller.setItemNameSupplier(plugin::getItemName);
		controller.setHeldSellItemIdsSupplier(plugin::getExitHeldSellItemIds);
		controller.setOnFocusTarget(flipAssistOverlay::setFocusedFlip);
		controller.setOnStatusMessage(flipAssistOverlay::setAutoStatusMessage);
		controller.setOnHighlightSlotForItem(plugin::highlightSlotForItem);
		controller.setOnClearHighlights(geSlotOverlay::clearAllAdjustmentHighlights);
		controller.setOnComplete(() -> flipAssistOverlay.setAutoStatusMessage("Exit Trades complete", 0));
		offerStore.addListener(event -> {
			if (controller.onOfferChanged(event.record))
			{
				controller.surfaceCurrent();
			}
		});
		return controller;
	}

	/**
	 * Initialize manual adjustment tracker for staleness detection on manual flips.
	 * (formerly FlipSmartPlugin.initializeManualAdjustmentTracker)
	 *
	 * @return the constructed ManualAdjustmentTracker
	 */
	public ManualAdjustmentTracker initializeManualAdjustmentTracker(FlipSmartPlugin plugin, FlipSmartConfig config,
		FlipAssistOverlay flipAssistOverlay, GrandExchangeSlotOverlay geSlotOverlay,
		InventoryHighlightOverlay inventoryHighlightOverlay, PlayerSession session,
		GrandExchangeTracker grandExchangeTracker, ActiveOfferAdvisorService activeOfferAdvisorService,
		OfferStore offerStore)
	{
		ManualAdjustmentTracker manualAdjustmentTracker = new ManualAdjustmentTracker(plugin.getApiClient(), config, offerStore);

		manualAdjustmentTracker.setOnAdjustmentPrompt(flipAssistOverlay::setAutoStatusMessage);

		manualAdjustmentTracker.setOnFocusFlip((focus, statusMsg) ->
		{
			flipAssistOverlay.setFocusedFlip(focus);
			flipAssistOverlay.setAutoStatusMessage(statusMsg, focus.getItemId());
			plugin.updateInventoryHighlightForFocus(focus);
		});

		manualAdjustmentTracker.setOnHighlightSlot((slot, recommendedPrice) ->
			geSlotOverlay.setAdjustmentHighlight(slot, recommendedPrice));
		manualAdjustmentTracker.setOnClearHighlight(geSlotOverlay::clearAdjustmentHighlight);

		manualAdjustmentTracker.setOnHighlightInventoryItem(inventoryHighlightOverlay::addHighlight);
		manualAdjustmentTracker.setOnClearInventoryItem(inventoryHighlightOverlay::removeHighlight);
		manualAdjustmentTracker.setOnSellPriceAdjusted((itemId, price) ->
		{
			if (session != null)
			{
				session.setRecommendedPrice(itemId, price);
			}
		});

		manualAdjustmentTracker.setCashStackSupplier(() ->
			session.getCurrentCashStack() > 0 ? session.getCurrentCashStack() : null);
		manualAdjustmentTracker.setRsnSupplier(() -> plugin.getCurrentRsnSafe().orElse(null));
		manualAdjustmentTracker.setFilledSlotsSupplier(plugin::getFilledGESlotCount);
		manualAdjustmentTracker.setMembersWorldSupplier(plugin::isMembersWorld);
		manualAdjustmentTracker.setV9OwnsSell(plugin::v9OwnsSell);

		grandExchangeTracker.setManualAdjustmentTracker(manualAdjustmentTracker);
		grandExchangeTracker.setActiveOfferAdvisorService(activeOfferAdvisorService);
		grandExchangeTracker.setAdjustmentPromptsEnabled(config::showAdjustmentPrompts);
		grandExchangeTracker.setConfig(config);

		return manualAdjustmentTracker;
	}

	/**
	 * Register the single transaction-recording listener on the shared OfferStore.
	 *
	 * The logger uses the SAME rsn supplier the tracker was wired with
	 * ({@code plugin::getCurrentRsnSafe}) so recorded RSN is identical to the old inline
	 * recording path. It must subscribe to the same OfferStore instance the tracker writes
	 * to, so every state change the tracker applies is recorded exactly once.
	 */
	public void wireTransactionLogger(FlipSmartPlugin plugin, FlipSmartConfig config, PlayerSession session,
		OfferStore offerStore, RoundTripLedger roundTripLedger, PanelRefreshCoalescer refreshCoalescer)
	{
		TransactionLogger logger = new TransactionLogger(
			plugin.getApiClient(), session, plugin::getCurrentRsnSafe, roundTripLedger);
		logger.setOnSellRecorded(() -> refreshCoalescer.requestSoon(true));
		logger.setTimeframeSupplier(() -> {
			FlipSmartConfig.FlipTimeframe tf = config.flipTimeframe();
			return tf != null && tf.isTimeframeBased() ? tf.getApiValue() : null;
		});
		offerStore.addListener(logger::onOfferEvent);
	}

	/**
	 * Wire all GrandExchangeTracker callbacks.
	 * (formerly FlipSmartPlugin.wireGrandExchangeTrackerCallbacks)
	 *
	 * API-backed refreshes triggered by GE offer events route through the
	 * {@link PanelRefreshCoalescer} so a burst produces one refresh per window.
	 * Immediate responsiveness comes from the OfferStore listener registered
	 * here, which redisplays the Active Flips tab from local state on the EDT.
	 */
	public void wireGrandExchangeTrackerCallbacks(FlipSmartPlugin plugin, GrandExchangeTracker grandExchangeTracker,
		AutoRecommendService autoRecommendService, GEHistoryService geHistoryService,
		OfferStore offerStore, PanelRefreshCoalescer refreshCoalescer)
	{
		grandExchangeTracker.setAutoRecommendService(autoRecommendService);
		grandExchangeTracker.setOnV9SellFill(plugin::onV9SellFill);
		grandExchangeTracker.setOnV9SellCancelled(plugin::onV9SellCancelled);
		grandExchangeTracker.setRsnSupplier(plugin::getCurrentRsnSafe);
		grandExchangeTracker.setOnPanelRefresh(() -> refreshCoalescer.request(true));
		grandExchangeTracker.setOnActiveFlipsRefresh(() -> { if (plugin.getFlipFinderPanel() != null) plugin.getFlipFinderPanel().reevaluateSlotLimitDisplay(); plugin.maybeEventPollAdvisor(); refreshCoalescer.request(false); });
		offerStore.addListener(event -> SwingUtilities.invokeLater(() -> {
			if (plugin.getFlipFinderPanel() != null)
			{
				plugin.getFlipFinderPanel().applyLocalOfferEvent(event);
			}
		}));
		grandExchangeTracker.setOnPendingOrdersUpdate(orders -> { if (plugin.getFlipFinderPanel() != null) plugin.getFlipFinderPanel().updatePendingOrders(plugin.getPendingBuyOrders()); });
		grandExchangeTracker.setOnFocusChanged(plugin::handleGETrackerFocusChanged);
		grandExchangeTracker.setOnFocusClear(plugin::handleGETrackerFocusClear);
		grandExchangeTracker.setOnOrderSubmitted(plugin::handleOrderSubmittedForSourcing);
		grandExchangeTracker.setDisplayedSellPriceProvider(itemId -> plugin.getFlipFinderPanel() != null ? plugin.getFlipFinderPanel().getDisplayedSellPrice(itemId) : null);
		grandExchangeTracker.setOneShotScheduler(plugin::scheduleOneShot);
		grandExchangeTracker.setBuyBasisProvider(plugin::buyBasisForItem);

		geHistoryService.setOnBackfillComplete(() -> {
			if (plugin.getFlipFinderPanel() != null)
			{
				SwingUtilities.invokeLater(plugin.getFlipFinderPanel()::refresh);
			}
		});
	}
}

package com.flipsmart.api;

import com.flipsmart.FlipSmartConfig;
import com.flipsmart.api.dto.Dtos.AuthResult;
import com.flipsmart.api.dto.Dtos.DeviceAuthResponse;
import com.flipsmart.api.dto.Dtos.DeviceStatusResponse;
import com.flipsmart.api.dto.Dtos.EntitlementsResponse;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Consumer;
import java.util.function.Function;
import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Transport + auth/session core for the FlipSmart API.
 *
 * Owns the OkHttp client, Gson, config, the shared {@link ApiBackoffGate} and ALL
 * mutable authentication/session state (JWT, refresh token, premium/blocked flags,
 * callbacks, auth coalescing and the 401 re-auth retry). Endpoint groups in
 * {@code com.flipsmart.api.endpoints} are stateless and route every HTTP call
 * through this class.
 */
@Slf4j
public class ApiHttpTransport
{
	public static final MediaType JSON = MediaType.get("application/json; charset=utf-8");
	private static final String PRODUCTION_API_URL = "https://api.flipsm.art";
	private static final String ACCESS_TOKEN_KEY = "access_token";
	private static final String REFRESH_TOKEN_KEY = "refresh_token";
	private static final String JSON_KEY_STATUS = "status";
	private static final String DEVICE_INFO = "RuneLite Plugin";
	private static final String HEADER_AUTHORIZATION = "Authorization";
	private static final String BEARER_PREFIX = "Bearer ";
	private static final int HTTP_SERVER_ERROR_THRESHOLD = 500;
	private static final int HTTP_TOO_MANY_REQUESTS = 429;

	@Getter
	private final OkHttpClient httpClient;
	@Getter
	private final Gson gson;
	private final FlipSmartConfig config;
	private final ApiBackoffGate backoffGate;

	// JWT token management — all access guarded by authLock
	private String jwtToken = null;
	private long tokenExpiry = 0;

	// Refresh token for persistent login (stored via config, but kept in memory for use)
	private String refreshToken = null;

	// Premium status (updated on login)
	private boolean isPremium = false;

	// RSN-level blocked status (updated on entitlements fetch)
	private boolean isRsnBlocked = false;

	// V9 short-timeframe behavior gate, sourced from entitlements. Fail-closed:
	// stays false unless a backend explicitly reports v9_enabled=true, so the
	// published plugin is inert against a backend that doesn't serve V9.
	private boolean v9Enabled = false;

	// Lock for authentication to prevent concurrent auth attempts
	private final Object authLock = new Object();

	// Callback when authentication permanently fails (both refresh token and password fail)
	@Setter
	private volatile Runnable onAuthFailure = null;

	// Callback when refresh token changes (for persistence to config)
	@Setter
	private volatile Consumer<String> onRefreshTokenChanged = null;

	// Coalesce concurrent authenticateAsync() calls into a single attempt
	private volatile CompletableFuture<Boolean> pendingAuthFuture = null;

	// Guards the re-login prompt so a burst of failed requests raises it once, not once per call
	private final AtomicBoolean authFailureNotified = new AtomicBoolean(false);

	public ApiHttpTransport(OkHttpClient httpClient, Gson gson, FlipSmartConfig config)
	{
		this(httpClient, gson, config, new ApiBackoffGate());
	}

	ApiHttpTransport(OkHttpClient httpClient, Gson gson, FlipSmartConfig config, ApiBackoffGate backoffGate)
	{
		this.httpClient = httpClient;
		this.gson = gson;
		this.config = config;
		this.backoffGate = backoffGate;
	}

	/**
	 * Deserialize a response body into a DTO using the transport's Gson. Centralizes
	 * the {@code gson.fromJson(body, T.class)} boilerplate that each endpoint group
	 * previously hand-rolled; behavior is identical to a direct Gson call (returns
	 * {@code null} for an empty/null body).
	 */
	public <T> T parse(String body, Class<T> type)
	{
		return gson.fromJson(body, type);
	}

	/**
	 * Get the API URL to use. Returns the configured override URL if set,
	 * otherwise returns the production URL.
	 */
	public String getApiUrl()
	{
		String configuredUrl = config.apiUrl();
		if (configuredUrl == null || configuredUrl.isEmpty())
		{
			return PRODUCTION_API_URL;
		}
		return configuredUrl;
	}

	/**
	 * URL-encode a value for use in query parameters.
	 * Handles RSNs with spaces and special characters.
	 */
	public static String urlEncode(String value)
	{
		return URLEncoder.encode(value, StandardCharsets.UTF_8);
	}

	/**
	 * Thread-safe read of the JWT token.
	 */
	private String getJwtToken()
	{
		synchronized (authLock)
		{
			return jwtToken;
		}
	}

	/**
	 * Thread-safe compound check: token exists and is not expired.
	 */
	private boolean isTokenValid()
	{
		synchronized (authLock)
		{
			return jwtToken != null && System.currentTimeMillis() < tokenExpiry;
		}
	}

	/**
	 * Add Authorization header with Bearer token to a request builder.
	 */
	private Request.Builder withAuthHeader(Request.Builder builder)
	{
		return builder.header(HEADER_AUTHORIZATION, BEARER_PREFIX + getJwtToken());
	}

	/**
	 * Build an authenticated GET request for a fully-formed URL. Used by endpoint
	 * groups that pre-build their URL via {@link okhttp3.HttpUrl} and need the
	 * Bearer header applied without the executeAuthenticatedAsync wrapper (e.g.
	 * fire-and-forget callback-style endpoints).
	 */
	public Request withAuthGet(okhttp3.HttpUrl url)
	{
		return withAuthHeader(new Request.Builder().url(url))
			.get()
			.build();
	}

	/**
	 * Execute an HTTP request asynchronously with automatic retry on 401
	 * This is the core method that handles all HTTP requests off the main threads
	 *
	 * @param request The request to execute
	 * @param responseHandler Function to process successful response body and return result
	 * @param errorHandler Consumer to handle errors
	 * @param retryOnAuth Whether to retry with re-authentication on 401
	 * @param <T> The return type
	 * @return CompletableFuture with the result
	 */
	public <T> CompletableFuture<T> executeAsync(Request request, Function<String, T> responseHandler,
												 Consumer<String> errorHandler, boolean retryOnAuth)
	{
		if (!backoffGate.allowRequest())
		{
			if (errorHandler != null)
			{
				errorHandler.accept("API backing off after repeated failures");
			}
			return CompletableFuture.completedFuture(null);
		}

		CompletableFuture<T> future = new CompletableFuture<>();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				backoffGate.recordFailure();
				log.debug("Request failed: {}", e.getMessage());
				if (errorHandler != null)
				{
					errorHandler.accept("Connection error: " + e.getMessage());
				}
				future.complete(null);
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (response)
				{
					if (response.code() == 401 && retryOnAuth)
					{
						// Token might have expired, try to re-authenticate
						log.debug("Received 401, attempting to re-authenticate");
						synchronized (authLock)
						{
							jwtToken = null;
						}

						authenticateAsync().thenAccept(authSuccess ->
						{
							if (Boolean.TRUE.equals(authSuccess))
							{
								// Rebuild request with new token
								Request retryRequest = withAuthHeader(request.newBuilder())
									.build();

								// Retry without auth retry to prevent infinite loop
								executeAsync(retryRequest, responseHandler, errorHandler, false)
									.thenAccept(future::complete);
							}
							else
							{
								// Auth permanently failed - notify so UI can show login screen
								notifyAuthFailure();
								future.complete(null);
							}
						});
						return;
					}

					if (!response.isSuccessful())
					{
						if (response.code() >= HTTP_SERVER_ERROR_THRESHOLD || response.code() == HTTP_TOO_MANY_REQUESTS)
						{
							backoffGate.recordFailure();
						}
						log.debug("Request returned error: {}", response.code());
						if (errorHandler != null)
						{
							errorHandler.accept("Error " + response.code());
						}
						future.complete(null);
						return;
					}

					backoffGate.recordSuccess();
					okhttp3.ResponseBody responseBody = response.body();
					String jsonData = responseBody != null ? responseBody.string() : "";
					T result = responseHandler.apply(jsonData);
					future.complete(result);
				}
				catch (Exception e)
				{
					log.debug("Error processing response: {}", e.getMessage());
					future.complete(null);
				}
			}
		});

		return future;
	}

	/**
	 * Execute an authenticated request asynchronously
	 */
	public <T> CompletableFuture<T> executeAuthenticatedAsync(Request.Builder requestBuilder,
															  Function<String, T> responseHandler)
	{
		return executeAuthenticatedAsync(requestBuilder, responseHandler, null);
	}

	/**
	 * Execute an authenticated request asynchronously, forwarding non-2xx and
	 * connection errors to the given handler before the future completes with null.
	 */
	public <T> CompletableFuture<T> executeAuthenticatedAsync(Request.Builder requestBuilder,
															  Function<String, T> responseHandler,
															  Consumer<String> errorHandler)
	{
		return ensureAuthenticatedAsync().thenCompose(authenticated ->
		{
			if (!authenticated)
			{
				log.debug("Failed to authenticate");
				return CompletableFuture.completedFuture(null);
			}

			Request request = withAuthHeader(requestBuilder)
				.build();

			return executeAsync(request, responseHandler, errorHandler, true);
		});
	}

	/**
	 * Check if we have a valid JWT token, and refresh if needed (async)
	 */
	public CompletableFuture<Boolean> ensureAuthenticatedAsync()
	{
		// Check if we have a token and it's not expired
		if (isTokenValid())
		{
			return CompletableFuture.completedFuture(true);
		}

		// Token is missing or expired, authenticate. If that fails terminally,
		// surface it so the UI can prompt a re-login instead of failing silently.
		return authenticateAsync().thenApply(success ->
		{
			if (!success)
			{
				notifyAuthFailure();
			}
			return success;
		});
	}

	/**
	 * Authenticate with the API and obtain a JWT token.
	 * Tries refresh token first (if available), falls back to email/password.
	 * Coalesces concurrent calls — if auth is already in progress, returns the pending future.
	 */
	private CompletableFuture<Boolean> authenticateAsync()
	{
		synchronized (authLock)
		{
			// Coalesce concurrent auth attempts — return pending future if auth is in progress
			if (pendingAuthFuture != null && !pendingAuthFuture.isDone())
			{
				return pendingAuthFuture;
			}

			CompletableFuture<Boolean> future = doAuthenticateAsync();
			pendingAuthFuture = future;
			// Clear reference when done to allow future auth attempts
			future.whenComplete((result, ex) -> {
				synchronized (authLock)
				{
					if (pendingAuthFuture == future)
					{
						pendingAuthFuture = null;
					}
				}
			});
			return future;
		}
	}

	/**
	 * Internal authentication logic. Called by authenticateAsync() which handles coalescing.
	 */
	private CompletableFuture<Boolean> doAuthenticateAsync()
	{
		// Try refresh token first if we have one
		String currentRefreshToken = refreshToken;

		if (currentRefreshToken != null && !currentRefreshToken.isEmpty())
		{
			return refreshAccessTokenAsync()
				.thenCompose(success -> {
					if (success)
					{
						return CompletableFuture.completedFuture(true);
					}
					// refreshAccessTokenAsync already clears refreshToken on 401.
					// Fall back to password auth.
					return loginWithPasswordAsync();
				});
		}

		return loginWithPasswordAsync();
	}

	/**
	 * Authenticate using stored email/password (legacy fallback)
	 */
	private CompletableFuture<Boolean> loginWithPasswordAsync()
	{
		return loginAsync(config.email(), config.password())
			.thenApply(result -> result.success);
	}

	/**
	 * Login with email and password (async)
	 * @return CompletableFuture with AuthResult containing success status and message
	 */
	public CompletableFuture<AuthResult> loginAsync(String email, String password)
	{
		CompletableFuture<AuthResult> future = new CompletableFuture<>();

		AuthResult validationError = validateLoginCredentials(email, password);
		if (validationError != null)
		{
			future.complete(validationError);
			return future;
		}

		Request request = buildLoginRequest(email, password);

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.error("Failed to authenticate with API: {}", e.getMessage());
				future.complete(new AuthResult(false, "Connection error: " + e.getMessage()));
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				future.complete(handleLoginResponse(response));
			}
		});

		return future;
	}

	/**
	 * Validate login credentials and return error if invalid
	 */
	private AuthResult validateLoginCredentials(String email, String password)
	{
		if (email == null || email.isEmpty())
		{
			return new AuthResult(false, "Please enter your email address");
		}
		if (password == null || password.isEmpty())
		{
			return new AuthResult(false, "Please enter your password");
		}
		return null;
	}

	/**
	 * Build the login HTTP request (includes refresh token request for persistent login)
	 */
	private Request buildLoginRequest(String email, String password)
	{
		// Request refresh token for persistent plugin login
		String url = String.format("%s/auth/login?include_refresh=true&device_info=%s",
			getApiUrl(), DEVICE_INFO);

		JsonObject jsonBody = new JsonObject();
		jsonBody.addProperty("email", email);
		jsonBody.addProperty("password", password);
		RequestBody body = RequestBody.create(JSON, jsonBody.toString());

		return new Request.Builder()
			.url(url)
			.post(body)
			.build();
	}

	/**
	 * Handle login response and return appropriate AuthResult
	 */
	private AuthResult handleLoginResponse(Response response)
	{
		try (response)
		{
			if (!response.isSuccessful())
			{
				return handleLoginError(response.code());
			}

			processSuccessfulLogin(response);
			log.debug("Successfully authenticated with API (premium: {})", isPremium());
			return new AuthResult(true, "Login successful!");
		}
		catch (Exception e)
		{
			log.error("Error processing login response: {}", e.getMessage());
			return new AuthResult(false, "Error processing response");
		}
	}

	/**
	 * Map login error codes to user-friendly messages
	 */
	private AuthResult handleLoginError(int code)
	{
		switch (code)
		{
			case 401:
				return new AuthResult(false, "Incorrect email or password");
			case 404:
				return new AuthResult(false, "Account not found. Please sign up first.");
			default:
				return new AuthResult(false, "Login failed (error " + code + ")");
		}
	}

	/**
	 * Process successful login response and store tokens
	 */
	private void processSuccessfulLogin(Response response) throws IOException
	{
		okhttp3.ResponseBody responseBody = response.body();
		String jsonData = responseBody != null ? responseBody.string() : "";
		JsonObject tokenResponse = gson.fromJson(jsonData, JsonObject.class);
		processTokenResponse(tokenResponse);
	}

	/**
	 * Process token response and store access token, refresh token, and premium status.
	 * Used by both login and refresh token flows to avoid code duplication.
	 *
	 * @param tokenResponse The JSON response containing access_token, optional refresh_token, and is_premium
	 */
	private void processTokenResponse(JsonObject tokenResponse)
	{
		String newRefreshToken = null;
		synchronized (authLock)
		{
			jwtToken = tokenResponse.get(ACCESS_TOKEN_KEY).getAsString();
			tokenExpiry = System.currentTimeMillis() + (6 * 24 * 60 * 60 * 1000L);

			// Store refresh token if provided (for persistent login / token rotation)
			if (tokenResponse.has(REFRESH_TOKEN_KEY) && !tokenResponse.get(REFRESH_TOKEN_KEY).isJsonNull())
			{
				newRefreshToken = tokenResponse.get(REFRESH_TOKEN_KEY).getAsString();
				refreshToken = newRefreshToken;
			}

			// Premium is intentionally NOT sourced from the token here. The token's is_premium
			// is USER-level (true if the user holds premium on ANY rsn or web), but plugin
			// gating — slots, focus, Auto, the free cap — is PER-RSN. Sourcing it from the token
			// wrongly treats a user with web/other-rsn premium as premium on a free rsn. Premium
			// is sourced solely from the flip-finder payload (subscription.tier), which is per-rsn.
		}

		// A fresh token means any prior terminal failure is resolved; re-arm the prompt.
		authFailureNotified.set(false);

		// Notify outside of lock to avoid potential deadlocks
		if (newRefreshToken != null && onRefreshTokenChanged != null)
		{
			onRefreshTokenChanged.accept(newRefreshToken);
		}
	}

	/**
	 * Synchronous login wrapper for backward compatibility
	 * Note: This should only be called from background threads
	 */
	public AuthResult login(String email, String password)
	{
		return awaitAuth("Login", loginAsync(email, password));
	}

	/**
	 * Block on an async auth call, turning any failure into a failed {@link AuthResult}.
	 * {@code label} names the operation in both the log line and the returned message.
	 */
	private static AuthResult awaitAuth(String label, CompletableFuture<AuthResult> call)
	{
		try
		{
			return call.get();
		}
		catch (Exception e)
		{
			log.error("{} failed: {}", label, e.getMessage());
			return new AuthResult(false, label + " failed: " + e.getMessage());
		}
	}

	/**
	 * Exchange a refresh token for new access and refresh tokens.
	 * This is used for persistent login without storing passwords.
	 *
	 * @return CompletableFuture with true if refresh succeeded, false otherwise
	 */
	public CompletableFuture<Boolean> refreshAccessTokenAsync()
	{
		CompletableFuture<Boolean> future = new CompletableFuture<>();

		String currentRefreshToken;
		synchronized (authLock)
		{
			currentRefreshToken = refreshToken;
		}

		if (currentRefreshToken == null || currentRefreshToken.isEmpty())
		{
			future.complete(false);
			return future;
		}

		String url = String.format("%s/auth/refresh?device_info=%s", getApiUrl(), DEVICE_INFO);

		JsonObject jsonBody = new JsonObject();
		jsonBody.addProperty(REFRESH_TOKEN_KEY, currentRefreshToken);
		RequestBody body = RequestBody.create(JSON, jsonBody.toString());

		Request request = new Request.Builder()
			.url(url)
			.post(body)
			.build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Refresh token exchange failed: {}", e.getMessage());
				future.complete(false);
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (response)
				{
					if (!response.isSuccessful())
					{
						log.debug("Refresh token rejected (status {})", response.code());
						// Only clear the refresh token on 401 (explicitly rejected).
						// Server errors (5xx) are transient — the token may still be valid.
						if (response.code() == 401)
						{
							synchronized (authLock)
							{
								refreshToken = null;
							}
						}
						future.complete(false);
						return;
					}

					okhttp3.ResponseBody responseBody = response.body();
					String jsonData = responseBody != null ? responseBody.string() : "";
					JsonObject tokenResponse = gson.fromJson(jsonData, JsonObject.class);

					processTokenResponse(tokenResponse);

					log.debug("Successfully refreshed access token (premium: {})", isPremium());
					future.complete(true);
				}
				catch (Exception e)
				{
					log.error("Error processing refresh response: {}", e.getMessage());
					future.complete(false);
				}
			}
		});

		return future;
	}

	/**
	 * Set the refresh token directly (used when loading from config).
	 * @param token The refresh token
	 */
	public void setRefreshToken(String token)
	{
		synchronized (authLock)
		{
			this.refreshToken = token;
		}
	}

	/**
	 * Get the current refresh token (for saving to config).
	 * @return The refresh token, or null if not set
	 */
	public String getRefreshToken()
	{
		synchronized (authLock)
		{
			return refreshToken;
		}
	}

	/**
	 * Sign up a new account with email and password (async)
	 * @return CompletableFuture with AuthResult containing success status and message
	 */
	public CompletableFuture<AuthResult> signupAsync(String email, String password)
	{
		CompletableFuture<AuthResult> future = new CompletableFuture<>();

		String apiUrl = getApiUrl();

		if (email == null || email.isEmpty())
		{
			future.complete(new AuthResult(false, "Please enter your email address"));
			return future;
		}

		if (password == null || password.isEmpty())
		{
			future.complete(new AuthResult(false, "Please enter your password"));
			return future;
		}

		if (password.length() < 6)
		{
			future.complete(new AuthResult(false, "Password must be at least 6 characters"));
			return future;
		}

		String url = String.format("%s/auth/signup", apiUrl);

		// Create JSON body with email and password
		JsonObject jsonBody = new JsonObject();
		jsonBody.addProperty("email", email);
		jsonBody.addProperty("password", password);
		RequestBody body = RequestBody.create(JSON, jsonBody.toString());

		Request request = new Request.Builder()
			.url(url)
			.post(body)
			.build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.error("Failed to sign up with API: {}", e.getMessage());
				future.complete(new AuthResult(false, "Connection error: " + e.getMessage()));
			}

			@Override
			public void onResponse(Call call, Response response) throws IOException
			{
				try (response)
				{
					if (!response.isSuccessful())
					{
						if (response.code() == 400)
						{
							future.complete(new AuthResult(false, "Email already registered. Please login instead."));
						}
						else
						{
							future.complete(new AuthResult(false, "Sign up failed (error " + response.code() + ")"));
						}
						return;
					}

					okhttp3.ResponseBody responseBody = response.body();
					String jsonData = responseBody != null ? responseBody.string() : "";
					JsonObject tokenResponse = gson.fromJson(jsonData, JsonObject.class);

					synchronized (authLock)
					{
						jwtToken = tokenResponse.get(ACCESS_TOKEN_KEY).getAsString();
						tokenExpiry = System.currentTimeMillis() + (6 * 24 * 60 * 60 * 1000L);
					}

					log.debug("Successfully signed up and authenticated with API");
					future.complete(new AuthResult(true, "Account created successfully!"));
				}
				catch (Exception e)
				{
					log.error("Error processing signup response: {}", e.getMessage());
					future.complete(new AuthResult(false, "Error processing response"));
				}
			}
		});

		return future;
	}

	/**
	 * Synchronous signup wrapper for backward compatibility
	 * Note: This should only be called from background threads
	 */
	public AuthResult signup(String email, String password)
	{
		return awaitAuth("Signup", signupAsync(email, password));
	}

