	/**
	 * Clear the current authentication tokens (access and refresh)
	 */
	public void clearAuth()
	{
		synchronized (authLock)
		{
			jwtToken = null;
			tokenExpiry = 0;
			refreshToken = null;
			// Default to true during logout to avoid briefly blocking
			// recommendations before the next entitlement check resolves
			isPremium = true;
			isRsnBlocked = false;
			// V9 stays fail-closed on logout — never assume it until re-confirmed.
			v9Enabled = false;
		}
		// Re-arm the prompt so a fresh failure on the next login isn't suppressed
		// by a stale flag from before this logout.
		authFailureNotified.set(false);
	}


	/**
	 * Notify that authentication has permanently failed
	 */
	private void notifyAuthFailure()
	{
		boolean recoverable;
		synchronized (authLock)
		{
			recoverable = refreshToken != null && !refreshToken.isEmpty();
		}
		// A retained refresh token means the failure is transient (e.g. a 5xx) and the
		// next attempt can recover on its own — don't prompt. Only when no credential
		// remains is the session truly dead. compareAndSet keeps it to one prompt until
		// the next successful auth resets the flag.
		if (recoverable || !authFailureNotified.compareAndSet(false, true))
		{
			return;
		}
		log.warn("FlipSmart session expired and could not be renewed; prompting re-login");
		Runnable callback = onAuthFailure;
		if (callback != null)
		{
			callback.run();
		}
	}

	/**
	 * Fetch user entitlements from the API to check premium status and RSN-level access.
	 * Call this when the player logs into the game.
	 *
	 * @param rsn The player's RuneScape Name (optional, for RSN-level entitlement checks)
	 */
	public CompletableFuture<Boolean> fetchEntitlementsAsync(String rsn)
	{
		if (!isTokenValid())
		{
			return CompletableFuture.completedFuture(false);
		}

		String url = String.format("%s/auth/entitlements", getApiUrl());
		if (rsn != null && !rsn.isEmpty())
		{
			url += "?rsn=" + urlEncode(rsn);
		}

		Request request = withAuthHeader(new Request.Builder()
			.url(url))
			.get()
			.build();

		return executeAsync(request, responseBody -> {
			try
			{
				applyEntitlements(EntitlementsResponse.fromJson(gson, responseBody));
				return isPremium();
			}
			catch (Exception e)
			{
				setV9Enabled(false);
				log.error("Error parsing entitlements response", e);
				return isPremium();
			}
		}, error -> {
			setV9Enabled(false);
			log.warn("Failed to fetch entitlements: {}", error);
		}, true);
	}

	/**
	 * Apply an entitlements snapshot to local state. Only RSN-blocked status is
	 * taken from here — premium is sourced exclusively from the flip-finder
	 * payload ({@code subscription.tier}). The snapshot carries premium nested
	 * under {@code rsn_entitlement}, and re-sourcing it here historically
	 * downgraded premium players to the free slot tier (see
	 * {@code EntitlementsResponseTest}).
	 */
	void applyEntitlements(EntitlementsResponse entitlements)
	{
		if (entitlements == null)
		{
			return;
		}

		boolean rsnBlocked = entitlements.isRsnBlocked();
		boolean v9 = entitlements.isV9Enabled();
		synchronized (authLock)
		{
			isRsnBlocked = rsnBlocked;
			v9Enabled = v9;
		}
		log.debug("Fetched entitlements - rsnBlocked: {}, v9Enabled: {}", rsnBlocked, v9);
	}

