package com.flipsmart.domain.offer;

/** Outcome of OfferStateMachine.decide(): the resulting record plus what observably happened. */
public final class OfferTransition
{
    public enum Kind { NONE, PLACED, FILLED_DELTA, COMPLETED, COLLECTED, CANCELLED, REJECTED }

    public final Kind kind;
    public final OfferRecord record;      // updated record (null only when REJECTED with no prior)
    public final int newlyFilledQuantity; // fill delta for this signal (also nonzero on PLACED with an immediate fill, and on CANCELLED carrying a residual fill)
    public final long newlySpent;         // GP delta for this signal (nonzero on the same transitions as newlyFilledQuantity)

    private OfferTransition(Kind kind, OfferRecord record, int newlyFilledQuantity, long newlySpent)
    {
        this.kind = kind;
        this.record = record;
        this.newlyFilledQuantity = newlyFilledQuantity;
        this.newlySpent = newlySpent;
    }

    public static OfferTransition of(Kind kind, OfferRecord record, int newlyFilledQuantity, long newlySpent)
    {
        return new OfferTransition(kind, record, newlyFilledQuantity, newlySpent);
    }

    /** Convenience overload for transitions where no GP was spent (NONE, PLACED, CANCELLED, COLLECTED). */
    public static OfferTransition of(Kind kind, OfferRecord record, int newlyFilledQuantity)
    {
        return new OfferTransition(kind, record, newlyFilledQuantity, 0L);
    }

    public static OfferTransition rejected(OfferRecord unchanged)
    {
        return new OfferTransition(Kind.REJECTED, unchanged, 0, 0L);
    }
}

package com.flipsmart.domain.offer;

import lombok.Getter;
import lombok.NoArgsConstructor;

/** One Grand Exchange order's full lifecycle. Immutable: transitions return a new instance. */
@Getter
@NoArgsConstructor // Gson
public final class OfferRecord
{
    private long offerId;          // canonical key, minted at NEW
    private Integer slot;          // 0..7 while live; null once collected/cancelled-empty
    private int itemId;
    private String itemName;
    private boolean buy;
    private int totalQuantity;
    private long price;
    private int filledQuantity;    // cumulative
    private long spent;            // cumulative GP
    private OfferState state;
    private long createdAtMillis;
    private long completedAtMillis;
    private long lastActivityAtMillis;
    private String offerStage;     // "initial" | "breakeven_relist"

    public static final String STAGE_INITIAL = "initial";
    public static final String STAGE_BREAKEVEN_RELIST = "breakeven_relist";

    // 2 % keeps noise from price rounding from triggering false negatives
    private static final double BREAKEVEN_RELIST_TOLERANCE = 0.02;

    public static boolean shouldAdvanceToBreakevenRelist(boolean breakevenExitAccepted, long observedRelistPrice, long advisedPrice)
    {
        if (!breakevenExitAccepted || advisedPrice <= 0 || observedRelistPrice <= 0)
        {
            return false;
        }
        double delta = Math.abs(observedRelistPrice - advisedPrice);
        return delta <= advisedPrice * BREAKEVEN_RELIST_TOLERANCE;
    }

    private OfferRecord(long offerId, Integer slot, int itemId, String itemName, boolean buy,
                        int totalQuantity, long price, int filledQuantity, long spent,
                        OfferState state, long createdAtMillis, long completedAtMillis,
                        long lastActivityAtMillis, String offerStage)
    {
        this.offerId = offerId;
        this.slot = slot;
        this.itemId = itemId;
        this.itemName = itemName;
        this.buy = buy;
        this.totalQuantity = totalQuantity;
        this.price = price;
        this.filledQuantity = filledQuantity;
        this.spent = spent;
        this.state = state;
        this.createdAtMillis = createdAtMillis;
        this.completedAtMillis = completedAtMillis;
        this.lastActivityAtMillis = lastActivityAtMillis;
        this.offerStage = offerStage;
    }

    /** A freshly-placed offer (state NEW, zero filled). */
    public static OfferRecord newOffer(long offerId, int slot, int itemId, String itemName,
                                       boolean buy, int totalQuantity, long price, long now)
    {
        return new OfferRecord(offerId, slot, itemId, itemName, buy, totalQuantity, price,
            0, 0L, OfferState.NEW, now, 0L, now, STAGE_INITIAL);
    }

    public OfferRecord withFill(int newFilledQuantity, long newSpent, OfferState newState, long now)
    {
        long completed = (newState == OfferState.FILLED && completedAtMillis == 0) ? now : completedAtMillis;
        return new OfferRecord(offerId, slot, itemId, itemName, buy, totalQuantity, price,
            newFilledQuantity, newSpent, newState, createdAtMillis, completed, now, offerStage);
    }

    public OfferRecord withState(OfferState newState, long now)
    {
        Integer newSlot = newState.isTerminal() ? null : slot;
        return new OfferRecord(offerId, newSlot, itemId, itemName, buy, totalQuantity, price,
            filledQuantity, spent, newState, createdAtMillis, completedAtMillis, now, offerStage);
    }

    public OfferRecord withSlot(Integer newSlot)
    {
        return new OfferRecord(offerId, newSlot, itemId, itemName, buy, totalQuantity, price,
            filledQuantity, spent, state, createdAtMillis, completedAtMillis, lastActivityAtMillis, offerStage);
    }

    public OfferRecord withCreatedAtMillis(long newCreatedAtMillis)
    {
        return new OfferRecord(offerId, slot, itemId, itemName, buy, totalQuantity, price,
            filledQuantity, spent, state, newCreatedAtMillis, completedAtMillis, lastActivityAtMillis, offerStage);
    }

    public OfferRecord withActivityAtMillis(long newLastActivityAtMillis)
    {
        return new OfferRecord(offerId, slot, itemId, itemName, buy, totalQuantity, price,
            filledQuantity, spent, state, createdAtMillis, completedAtMillis, newLastActivityAtMillis, offerStage);
    }

    public OfferRecord withOfferStage(String newStage)
    {
        return new OfferRecord(offerId, slot, itemId, itemName, buy, totalQuantity, price,
            filledQuantity, spent, state, createdAtMillis, completedAtMillis, lastActivityAtMillis, newStage);
    }

    public String getOfferStage()
    {
        return offerStage != null ? offerStage : STAGE_INITIAL;
    }

    /** Last activity time, falling back to creation time for records persisted before the field existed. */
    public long getEffectiveLastActivityAtMillis()
    {
        return lastActivityAtMillis > 0 ? lastActivityAtMillis : createdAtMillis;
    }
}

package com.flipsmart.domain.offer;

public enum OfferState
{
    NEW,
    PARTIAL_FILL,
    FILLED,
    COLLECTED,            // terminal
    CANCELLED_EMPTY,      // terminal
    CANCELLED_PARTIAL;    // → COLLECTED

    public boolean isTerminal()
    {
        return this == COLLECTED || this == CANCELLED_EMPTY;
    }
}

package com.flipsmart.domain.offer;

public enum OfferDisposition
{
	SURFACE_PRICE,
	HANDOFF,
	NONE;

	public static OfferDisposition route(OfferAction action)
	{
		if (action == null)
		{
			return NONE;
		}
		switch (action)
		{
			case MOVE_PRICE_DOWN:
			case MOVE_PRICE_UP:
			case EXIT_AT_BREAKEVEN:
			case EXIT_AT_LOSS:
				return SURFACE_PRICE;
			case CANCEL_AND_RELIST_OTHER:
			case CANCEL_AND_SELL_PARTIAL:
				return HANDOFF;
			case WAIT:
			default:
				return NONE;
		}
	}
}

