@Slf4j
public class GeSlotWidgetDecorator
{
    static final int GE_INTERFACE_GROUP = 465;
    static final int SLOT_CONTAINER_START = 7;
    static final int GE_MAX_SLOTS = 8;

    // Frame pieces (drawn as a thin outer-edge outline) + the item background box (light fill).
    // The full-width divider (13) is left vanilla so we don't touch the slot interior.
    static final int[] BORDER_CHILDREN = { 5, 6, 7, 8, 9, 10, 11, 12, 14, 15, 17 };

    // Which outer edge(s) each frame piece contributes to the slot's perimeter outline.
    // Item box (17) is absent -> edges 0 -> rendered as a light fill instead of an outline.
    private static final Map<Integer, Integer> BORDER_EDGES = new HashMap<>();
    static
    {
        BORDER_EDGES.put(5, SpriteOutline.TOP);
        BORDER_EDGES.put(6, SpriteOutline.BOTTOM);
        BORDER_EDGES.put(7, SpriteOutline.LEFT);
        BORDER_EDGES.put(8, SpriteOutline.RIGHT);
        BORDER_EDGES.put(9, SpriteOutline.TOP | SpriteOutline.LEFT);
        BORDER_EDGES.put(10, SpriteOutline.TOP | SpriteOutline.RIGHT);
        BORDER_EDGES.put(11, SpriteOutline.BOTTOM | SpriteOutline.LEFT);
        BORDER_EDGES.put(12, SpriteOutline.BOTTOM | SpriteOutline.RIGHT);
        BORDER_EDGES.put(14, SpriteOutline.LEFT);
        BORDER_EDGES.put(15, SpriteOutline.RIGHT);
    }

    private static final int OUTLINE_THICKNESS = 2;
    // Blend strength for the item-box fill: 0.5 keeps it light so the native texture shows through.
    private static final double TINT_STRENGTH = 0.5;

    // "Buy"/"Sell"/"Empty" state-text child. We left-align it and pull it tight to the slot's
    // left border; the timer lives in its own child so the two never push each other around.
    static final int STATE_TEXT_CHILD = 16;
    private static final int STATE_TEXT_INSET_X = 4;

    // The timer child is right-aligned inside the label's box less this padding, so a longer
    // duration extends leftward and its right edge never crosses into the neighbouring slot.
    private static final int TIMER_INSET_X = 4;

    private static final int TIMER_COLOR_RUNNING = 0xFFFFFF;
    private static final int TIMER_COLOR_COMPLETE = 0x4CBB17;
    private static final int TIMER_COLOR_COMPLETE_COLORBLIND = 0x0066CC;

    // Custom sprite-id namespace: high base to avoid colliding with game sprite ids.
    private static final int CUSTOM_SPRITE_BASE = 0x7F00_0000;

    private final Client client;
    private final FlipSmartConfig config;
    private final FlipSmartPlugin plugin;
    private final SpriteManager spriteManager;

    // (vanillaSpriteId, tint) -> custom sprite id already registered in the override map
    private final Map<Long, Integer> registered = new HashMap<>();
    private int nextCustomId = CUSTOM_SPRITE_BASE;

    // slot index -> (recolored child index -> vanilla sprite id) captured before first override
    private final Map<Integer, Map<Integer, Integer>> vanillaBorderIds = new HashMap<>();

    // slot index -> the state-text widget's original x-alignment, captured before left-aligning it
    private final Map<Integer, Integer> vanillaTextAlignment = new HashMap<>();

    // slot index -> the state-text widget's original x position, captured before nudging it
    private final Map<Integer, Integer> vanillaTextX = new HashMap<>();

    // slot index -> the last tint we could actually decide, with the offer facts behind it.
    // Held across an undecidable tick so the border stays put instead of dropping to vanilla;
    // the facts stop a new offer in a recycled slot inheriting its predecessor's colour.
    private final Map<Integer, DecidedTint> lastDecidedTint = new HashMap<>();

    // slot index -> the timer child we appended, reused until the client rebuilds the slot
    private final Map<Integer, Widget> timerWidgets = new HashMap<>();

    @Inject
    GeSlotWidgetDecorator(Client client, FlipSmartConfig config, FlipSmartPlugin plugin,
        SpriteManager spriteManager)
    {
        this.client = client;
        this.config = config;
        this.plugin = plugin;
        this.spriteManager = spriteManager;
    }

    // Different border children can share a vanilla sprite id while needing different outline
    // shapes (e.g. a straight-edge piece vs. a corner piece), so edges must be part of the key.
    private static long key(int vanillaSpriteId, SlotBorderTint tint, int edges)
    {
        return ((long) vanillaSpriteId << 12) | ((long) (edges & 0xF) << 8) | tint.ordinal();
    }

    int customSpriteId(int vanillaSpriteId, SlotBorderTint tint, int edges, int width, int height,
                       int relX, int relY, int slotWidth, int slotHeight)
    {
        Long k = key(vanillaSpriteId, tint, edges);
        Integer existing = registered.get(k);
        if (existing != null)
        {
            return existing;
        }

        BufferedImage image;
        if (edges == 0)
        {
            // Item box: a light fill of the vanilla sprite.
            BufferedImage vanilla = spriteManager.getSprite(vanillaSpriteId, 0);
            if (vanilla == null)
            {
                // Not loaded yet; keep vanilla this tick, retry next reconcile.
                return vanillaSpriteId;
            }
            image = SpriteRecolor.tint(vanilla, tint.getColor(), TINT_STRENGTH);
        }
        else
        {
            // Frame piece: a thin edge outline sized to the piece's rendered bounds (so the client
            // tiles it exactly once), positioned at the slot border via the piece's overhang offset.
            if (width <= 0 || height <= 0 || slotWidth <= 0 || slotHeight <= 0)
            {
                return vanillaSpriteId;
            }
            image = SpriteOutline.build(width, height, edges, tint.getColor(), OUTLINE_THICKNESS,
                relX, relY, slotWidth, slotHeight);
        }

        int id = nextCustomId++;
        client.getSpriteOverrides().put(id, ImageUtil.getImageSpritePixels(image, client));
        registered.put(k, id);
        return id;
    }

    void applyBorder(int slot, Widget slotWidget, SlotBorderTint tint)
    {
        Map<Integer, Integer> captured = vanillaBorderIds
            .computeIfAbsent(slot, k -> new HashMap<>());

        int slotWidth = slotWidget.getWidth();
        int slotHeight = slotWidget.getHeight();

        for (int childIndex : BORDER_CHILDREN)
        {
            Widget piece = slotWidget.getChild(childIndex);
            if (piece == null)
            {
                continue;
            }
            captured.putIfAbsent(childIndex, piece.getSpriteId());
            int vanillaId = captured.get(childIndex);
            int edges = BORDER_EDGES.getOrDefault(childIndex, 0);
            piece.setSpriteId(customSpriteId(vanillaId, tint, edges, piece.getWidth(), piece.getHeight(),
                piece.getRelativeX(), piece.getRelativeY(), slotWidth, slotHeight));
        }
    }

    void revertBorder(int slot, Widget slotWidget)
    {
        Map<Integer, Integer> captured = vanillaBorderIds.get(slot);
        if (captured == null)
        {
            return;
        }
        for (Map.Entry<Integer, Integer> e : captured.entrySet())
        {
            Widget piece = slotWidget.getChild(e.getKey());
            if (piece != null)
            {
                piece.setSpriteId(e.getValue());
            }
        }
    }

    public void reconcile()
    {
        boolean bordersOn = config.highlightSlotBorders();
        boolean timersOn = config.showOfferTimers();

        GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
        if (offers == null)
        {
            return;
        }
        for (int slot = 0; slot < Math.min(offers.length, GE_MAX_SLOTS); slot++)
        {
            Widget slotWidget = client.getWidget(GE_INTERFACE_GROUP, SLOT_CONTAINER_START + slot);
            if (slotWidget == null || slotWidget.isHidden())
            {
                continue;
            }

            GrandExchangeOffer offer = offers[slot];
            if (offer.getState() == GrandExchangeOfferState.EMPTY)
            {
                lastDecidedTint.remove(slot);
                revertBorder(slot, slotWidget);
                revertStateText(slot, slotWidget);
                continue;
            }

            reconcileBorder(slotWidget, slot, offer, bordersOn);
            if (timersOn)
            {
                // The record is needed for the timer only — the client cannot say when an offer
                // was placed — so a missing one degrades to a bare label, not a bare slot.
                applyStateText(slot, slotWidget, offer, plugin.getOfferStore().bySlot(slot));
            }
            else
            {
                revertStateText(slot, slotWidget);
            }
        }
    }

    void applyStateText(int slot, Widget slotWidget, GrandExchangeOffer offer, OfferRecord tracked)
    {
        Widget text = slotWidget.getChild(STATE_TEXT_CHILD);
        if (text == null)
        {
            return;
        }
        vanillaTextAlignment.putIfAbsent(slot, text.getXTextAlignment());
        vanillaTextX.putIfAbsent(slot, text.getOriginalX());

        boolean changed = false;
        if (text.getXTextAlignment() != WidgetTextAlignment.LEFT)
        {
            text.setXTextAlignment(WidgetTextAlignment.LEFT);
            changed = true;
        }
        int targetX = vanillaTextX.get(slot) + STATE_TEXT_INSET_X;
        if (text.getOriginalX() != targetX)
        {
            text.setOriginalX(targetX);
            changed = true;
        }

        String label = OfferSignal.isBuyState(offer.getState()) ? "Buy" : "Sell";
        if (!label.equals(text.getText()))
        {
            text.setText(label);
            changed = true;
        }
        if (changed)
        {
            text.revalidate();
        }

        applyTimer(slot, slotWidget, text, offer, tracked);
    }

    private void applyTimer(int slot, Widget slotWidget, Widget stateText, GrandExchangeOffer offer,
                            OfferRecord tracked)
    {
        long lastActivity = tracked == null ? 0L : tracked.getEffectiveLastActivityAtMillis();
        if (lastActivity <= 0)
        {
            hideTimer(slot, slotWidget);
            return;
        }

        boolean complete = offer.getState() == GrandExchangeOfferState.BOUGHT
            || offer.getState() == GrandExchangeOfferState.SOLD;
        String elapsed = elapsedLabel(complete, lastActivity, tracked);
        int color = timerColor(complete);

        Widget timer = timerWidget(slot, slotWidget, stateText);
        // Re-checked every pass, not just at creation: the slot can report width 0 while the
        // interface is still building, and a timer left at that width would never draw.
        int width = Math.max(0, slotWidget.getWidth() - TIMER_INSET_X);
        if (timer.isHidden() || timer.getOriginalWidth() != width
            || timer.getTextColor() != color || !elapsed.equals(timer.getText()))
        {
            timer.setHidden(false);
            timer.setOriginalWidth(width);
            timer.setTextColor(color);
            timer.setText(elapsed);
            timer.revalidate();
        }
    }

    // A finished offer freezes at how long it was open. Measuring from last activity would
    // always read 0:00, since completing an offer is itself the last activity. Records
    // persisted before creation time was tracked fall back to that degenerate reading.
    private static String elapsedLabel(boolean complete, long lastActivity, OfferRecord tracked)
    {
        if (!complete || tracked.getCompletedAtMillis() <= 0)
        {
            return TimeUtils.formatElapsedTime(lastActivity);
        }
        long openedAt = tracked.getCreatedAtMillis() > 0 ? tracked.getCreatedAtMillis() : lastActivity;
        return TimeUtils.formatFrozenElapsedTime(openedAt, tracked.getCompletedAtMillis());
    }

    private int timerColor(boolean complete)
    {
        if (!complete)
        {
            return TIMER_COLOR_RUNNING;
        }
        return config.colorblindMode() ? TIMER_COLOR_COMPLETE_COLORBLIND : TIMER_COLOR_COMPLETE;
    }

    /**
     * The timer's own child, created on demand. The client discards appended children whenever it
     * rebuilds the slot, so an orphaned reference means "build a fresh one", not "give up".
     */
    private Widget timerWidget(int slot, Widget slotWidget, Widget stateText)
    {
        Widget cached = attachedTimer(slot, slotWidget);
        if (cached != null)
        {
            return cached;
        }

        Widget created = slotWidget.createChild(WidgetType.TEXT);
        created.setFontId(stateText.getFontId());
        created.setTextShadowed(stateText.getTextShadowed());
        created.setYTextAlignment(stateText.getYTextAlignment());
        created.setXTextAlignment(WidgetTextAlignment.RIGHT);
        // The vanilla label auto-sizes and reports originalWidth 0, so the timer's box has to span
        // the slot itself: right-aligned inside it, a longer duration grows leftward from a fixed
        // right edge instead of pushing into the neighbouring slot.
        created.setOriginalX(0);
        created.setOriginalY(stateText.getOriginalY());
        created.setOriginalWidth(Math.max(0, slotWidget.getWidth() - TIMER_INSET_X));
        created.setOriginalHeight(stateText.getOriginalHeight());
        created.revalidate();
        timerWidgets.put(slot, created);
        return created;
    }

    private void hideTimer(int slot, Widget slotWidget)
    {
        Widget timer = attachedTimer(slot, slotWidget);
        if (timer == null || timer.isHidden())
        {
            return;
        }
        timer.setText("");
        timer.setHidden(true);
        timer.revalidate();
    }

    // Our child survived the last slot rebuild only if it is still among the parent's children.
    // An orphaned reference means "build a fresh one", not "give up".
    private Widget attachedTimer(int slot, Widget slotWidget)
    {
        Widget cached = timerWidgets.get(slot);
        Widget[] children = cached == null ? null : slotWidget.getChildren();
        if (children != null)
        {
            for (Widget candidate : children)
            {
                if (candidate == cached)
                {
                    return cached;
                }
            }
        }
        return null;
    }

    void revertStateText(int slot, Widget slotWidget)
    {
        hideTimer(slot, slotWidget);

        Integer alignment = vanillaTextAlignment.get(slot);
        if (alignment == null)
        {
            return;
        }
        Widget text = slotWidget.getChild(STATE_TEXT_CHILD);
        if (text == null)
        {
            return;
        }
        boolean changed = false;
        if (text.getXTextAlignment() != alignment)
        {
            text.setXTextAlignment(alignment);
            changed = true;
        }
        Integer originalX = vanillaTextX.get(slot);
        if (originalX != null && text.getOriginalX() != originalX)
        {
            text.setOriginalX(originalX);
            changed = true;
        }
        if (changed)
        {
            text.revalidate();
        }
    }

    void reconcileBorder(Widget slotWidget, int slot, GrandExchangeOffer offer, boolean bordersOn)
    {
        if (!bordersOn)
        {
            revertBorder(slot, slotWidget);
            return;
        }
        int itemId = offer.getItemId();
        long price = offer.getPrice();
        boolean buy = OfferSignal.isBuyState(offer.getState());

        // Tint from the live slot rather than the tracked record: the check needs only item,
        // price and direction, so a gap in the store costs the timer but never the border.
        java.util.Optional<SlotBorderTint> tint = SlotBorderTint.forOffer(
            plugin.calculateCompetitiveness(itemId, price, buy), config.colorblindMode());
        if (tint.isPresent())
        {
            lastDecidedTint.put(slot, new DecidedTint(tint.get(), itemId, price, buy));
            applyBorder(slot, slotWidget, tint.get());
            return;
        }

        DecidedTint held = lastDecidedTint.get(slot);
        if (held != null && held.describes(itemId, price, buy))
        {
            applyBorder(slot, slotWidget, held.tint);
        }
        else
        {
            revertBorder(slot, slotWidget);
        }
    }

    private static final class DecidedTint
    {
        private final SlotBorderTint tint;
        private final int itemId;
        private final long price;
        private final boolean buy;

        DecidedTint(SlotBorderTint tint, int itemId, long price, boolean buy)
        {
            this.tint = tint;
            this.itemId = itemId;
            this.price = price;
            this.buy = buy;
        }

        boolean describes(int otherItemId, long otherPrice, boolean otherBuy)
        {
            return itemId == otherItemId && price == otherPrice && buy == otherBuy;
        }
    }

    public void revertAll()
    {
        for (int slot = 0; slot < GE_MAX_SLOTS; slot++)
        {
            Widget slotWidget = client.getWidget(GE_INTERFACE_GROUP, SLOT_CONTAINER_START + slot);
            if (slotWidget != null)
            {
                revertBorder(slot, slotWidget);
                revertStateText(slot, slotWidget);
            }
        }
    }

    public void shutDownRevert()
    {
        revertAll();
        for (Integer id : registered.values())
        {
            client.getSpriteOverrides().remove(id);
        }
        registered.clear();
        vanillaBorderIds.clear();
        vanillaTextAlignment.clear();
        vanillaTextX.clear();
        lastDecidedTint.clear();
        timerWidgets.clear();
    }
}

package com.flipsmart;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.api.widgets.WidgetType;

/**
 * Injects a clickable "FlipSmart item" shortcut row at the top of the Grand
 * Exchange item-search results, pointing at the focused buy recommendation.
 *
 * <p>The plugin attaches the game's own search-select listener to the row and
 * gives it a "Select" action, but never invokes it — <strong>the player clicks
 * the row</strong> to select the item. This mirrors the vanilla "previous
 * search" shortcut and the mechanism used by the approved Flipping Copilot
 * plugin ({@code GePreviousSearch}). The RuneLite Plugin Hub forbids selecting
 * or clicking an item on the player's behalf, so we only set up the shortcut
 * and let the player trigger it.
 */
@Slf4j
class GeSearchSuggestion
{
	// GE search-results container == InterfaceID.Chatbox.MES_LAYER_SCROLLCONTENTS
	// == ComponentID.CHATBOX_GE_SEARCH_RESULTS.
	private static final int CHATBOX_GE_SEARCH_RESULTS = 10616884;

	// The vanilla GE "select search result" client script and the op/key trigger
	// args the game attaches to each real result row. We attach the same listener
	// to our row so a player click runs the game's own selection logic — we never
	// run it ourselves.
	private static final int GE_SELECT_SCRIPT = 754;
	private static final int GE_SELECT_OP = 84;
	private static final int GE_SELECT_KEY = -2147483640;

	// Orange used by the vanilla "previous search" item name.
	private static final String NAME_COLOR = "ff9040";

	// Result-row child indices in the search-results container.
	private static final int ROW_CHILD = 0;
	private static final int LABEL_CHILD = 1;
	private static final int NAME_CHILD = 2;
	private static final int ICON_CHILD = 3;

	private static final int FONT_ID = 495;

	private final Client client;
	private final FlipSmartConfig config;
	private final FlipAssistOverlay flipAssistOverlay;

	GeSearchSuggestion(Client client, FlipSmartConfig config, FlipAssistOverlay flipAssistOverlay)
	{
		this.client = client;
		this.config = config;
		this.flipAssistOverlay = flipAssistOverlay;
	}

	/**
	 * Inject or refresh the suggested-item shortcut row for the focused buy.
	 * No-op unless Flip Assist is enabled, a buy is focused, and the GE search
	 * results widget is present. MUST be called on the client thread.
	 */
	void showSuggestedItemInSearch()
	{
		if (!config.enableFlipAssistant())
		{
			return;
		}

		FocusedFlip focusedFlip = flipAssistOverlay.getFocusedFlip();
		if (focusedFlip == null || !focusedFlip.isBuying())
		{
			log.debug("GE search opened but no focused buy — skipping row injection (focus={})", focusedFlip);
			return;
		}

		String itemName = focusedFlip.getItemName();
		if (itemName == null || itemName.isEmpty())
		{
			return;
		}

		Widget searchResults = client.getWidget(CHATBOX_GE_SEARCH_RESULTS);
		if (searchResults == null)
		{
			log.debug("GE search opened but results widget not present yet — skipping row injection");
			return;
		}

		int itemId = focusedFlip.getItemId();

		// When the game already shows a "previous search" shortcut row, repurpose
		// its existing children; otherwise build our own. Mirrors Flipping Copilot.
		if (previousSearchRowVisible())
		{
			log.debug("Injecting FlipSmart search row (repurpose previous-search) for {} (id {})", itemName, itemId);
			repurposePreviousSearchRow(searchResults, itemId, itemName);
		}
		else
		{
			log.debug("Injecting FlipSmart search row (create new) for {} (id {})", itemName, itemId);
			createSuggestionRow(searchResults, itemId, itemName);
		}
	}

	private boolean previousSearchRowVisible()
	{
		return client.getVarpValue(VarPlayerID.GE_LAST_SEARCHED) != -1
			&& client.getVarbitValue(VarbitID.DISABLE_LAST_SEARCHED) == 0;
	}

	private void repurposePreviousSearchRow(Widget searchResults, int itemId, String itemName)
	{
		Widget row = searchResults.getChild(ROW_CHILD);
		Widget label = searchResults.getChild(LABEL_CHILD);
		Widget nameWidget = searchResults.getChild(NAME_CHILD);
		Widget icon = searchResults.getChild(ICON_CHILD);
		if (row == null || label == null || nameWidget == null || icon == null)
		{
			return;
		}

		applySelectListener(row, itemId, itemName);

		label.setText("FlipSmart item:");
		label.setOriginalWidth(95);
		label.setXTextAlignment(WidgetTextAlignment.LEFT);
		label.revalidate();

		nameWidget.setText(itemName);
		nameWidget.revalidate();

		icon.setItemId(itemId);
		icon.revalidate();
	}

	private void createSuggestionRow(Widget searchResults, int itemId, String itemName)
	{
		Widget row = searchResults.createChild(ROW_CHILD, WidgetType.RECTANGLE);
		row.setTextColor(0xFFFFFF);
		row.setOpacity(255);
		row.setFilled(true);
		row.setOriginalX(114);
		row.setOriginalY(0);
		row.setOriginalWidth(256);
		row.setOriginalHeight(32);
		applySelectListener(row, itemId, itemName);
		// Subtle hover feedback so it reads as clickable.
		row.setOnMouseOverListener((JavaScriptCallback) ev -> row.setOpacity(200));
		row.setOnMouseLeaveListener((JavaScriptCallback) ev -> row.setOpacity(255));
		row.revalidate();

		Widget label = searchResults.createChild(LABEL_CHILD, WidgetType.TEXT);
		label.setText("FlipSmart item:");
		label.setFontId(FONT_ID);
		label.setOriginalX(114);
		label.setOriginalY(0);
		label.setOriginalWidth(95);
		label.setOriginalHeight(32);
		label.setYTextAlignment(WidgetTextAlignment.CENTER);
		label.revalidate();

		Widget nameWidget = searchResults.createChild(NAME_CHILD, WidgetType.TEXT);
		nameWidget.setText(itemName);
		nameWidget.setFontId(FONT_ID);
		nameWidget.setOriginalX(254);
		nameWidget.setOriginalY(0);
		nameWidget.setOriginalWidth(116);
		nameWidget.setOriginalHeight(32);
		nameWidget.setYTextAlignment(WidgetTextAlignment.CENTER);
		nameWidget.revalidate();

		Widget icon = searchResults.createChild(ICON_CHILD, WidgetType.GRAPHIC);
		icon.setItemId(itemId);
		icon.setItemQuantity(1);
		icon.setItemQuantityMode(0);
		icon.setRotationX(550);
		icon.setModelZoom(1031);
		icon.setBorderType(1);
		icon.setOriginalX(214);
		icon.setOriginalY(0);
		icon.setOriginalWidth(36);
		icon.setOriginalHeight(32);
		icon.revalidate();
	}

	/**
	 * Attach the game's native select listener and a "Select" right-click action.
	 * The plugin never invokes this — only the player's click does.
	 */
	private void applySelectListener(Widget row, int itemId, String itemName)
	{
		row.setHasListener(true);
		row.setName("<col=" + NAME_COLOR + ">" + itemName + "</col>");
		row.setOnOpListener(GE_SELECT_SCRIPT, itemId, GE_SELECT_OP);
		row.setOnKeyListener(GE_SELECT_SCRIPT, itemId, GE_SELECT_KEY);
		row.setAction(0, "Select");
	}
}

