	public static boolean isTradeable(ItemManager itemManager, int itemId)
	{
		ItemComposition composition = itemManager.getItemComposition(itemId);
		return composition != null && composition.isTradeable();
	}
}

package com.flipsmart.util;
import com.flipsmart.domain.flip.ActiveFlip;
import com.flipsmart.domain.offer.OfferRecord;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/**
 * Single source of truth for resolving the player's recorded average buy price
 * for an item from their current active flips. Used by the GE slot-hover tooltip
 * (showing live P&amp;L) and the offer-setup window description (issue #665).
 */
public final class BuyPriceLookup
{
	private BuyPriceLookup()
	{
		// Utility class - prevent instantiation
	}

	/**
	 * Find the player's recorded average buy price for {@code itemId} from a
	 * snapshot of their current active flips.
	 *
	 * @return The recorded average buy price, or {@code null} if no active flip
	 *         exists for the item (or all matching flips have a non-positive price).
	 */
	public static Long findAverageBuyPrice(List<ActiveFlip> activeFlips, int itemId)
	{
		if (activeFlips == null)
		{
			return null;
		}
		for (ActiveFlip flip : activeFlips)
		{
			if (flip.getItemId() == itemId && flip.getAverageBuyPrice() > 0)
			{
				return flip.getAverageBuyPrice();
			}
		}
		return null;
	}

	/** Convenience overload with no held-quantity hint; the records fallback averages every buy. */
	public static Long findAverageBuyPriceWithFallback(
		List<ActiveFlip> activeFlips, Long cycleBasis, List<OfferRecord> offerRecords, int itemId)
	{
		return findAverageBuyPriceWithFallback(activeFlips, cycleBasis, offerRecords, itemId, 0);
	}

	/**
	 * Resolve the recorded average buy price, in descending order of authority: the backend
	 * active-flips snapshot, then the ledger's open-cycle basis, then the offer-record fallback.
	 * The record store never evicts, so it can describe stock already sold; {@code heldQuantity}
	 * (from the ledger) bounds the fallback to the most-recent buys covering what's still held.
	 * Non-positive means the holding is unknown (cold start / pre-ledger), so every record counts.
	 *
	 * @return the average buy price, or {@code null} if no source knows the item.
	 */
	public static Long findAverageBuyPriceWithFallback(
		List<ActiveFlip> activeFlips, Long cycleBasis, List<OfferRecord> offerRecords, int itemId,
		int heldQuantity)
	{
		Long fromFlips = findAverageBuyPrice(activeFlips, itemId);
		if (fromFlips != null)
		{
			return fromFlips;
		}
		if (cycleBasis != null && cycleBasis > 0)
		{
			return cycleBasis;
		}
		return averageBuyPriceFromOffers(offerRecords, itemId, heldQuantity);
	}

	/**
	 * Quantity-weighted average buy price for the item's filled buy offers, walking the most-recent
	 * buys first (by monotonic offerId). A positive {@code heldQuantity} stops once that many units
	 * are covered, pro-rating the lot that straddles the boundary, so the basis describes the stock
	 * still held rather than positions already sold; a non-positive value counts every recorded buy.
	 * {@code null} when none carry a fill. Sells and other items are ignored.
	 */
	static Long averageBuyPriceFromOffers(List<OfferRecord> offerRecords, int itemId, int heldQuantity)
	{
		List<OfferRecord> buys = filledBuys(offerRecords, itemId);
		buys.sort(Comparator.comparingLong(OfferRecord::getOfferId).reversed());
		long remaining = heldQuantity > 0 ? heldQuantity : Long.MAX_VALUE;
		double spent = 0;
		long filled = 0;
		for (OfferRecord r : buys)
		{
			if (remaining <= 0)
			{
				break;
			}
			long take = Math.min(r.getFilledQuantity(), remaining);
			spent += r.getSpent() * (take / (double) r.getFilledQuantity());
			filled += take;
			remaining -= take;
		}
		return filled > 0 ? Math.round(spent / filled) : null;
	}

	private static List<OfferRecord> filledBuys(List<OfferRecord> offerRecords, int itemId)
	{
		List<OfferRecord> buys = new ArrayList<>();
		if (offerRecords != null)
		{
			for (OfferRecord r : offerRecords)
			{
				if (r != null && r.isBuy() && r.getItemId() == itemId && r.getFilledQuantity() > 0)
				{
					buys.add(r);
				}
			}
		}
		return buys;
	}
}

package com.flipsmart;
import com.flipsmart.domain.flip.FlipRecommendation;
import com.flipsmart.util.GeTax;

import lombok.Data;

/**
 * Represents a flip that the user has selected as their current focus.
 * This can be either a recommended flip (buying step) or an active flip (selling step).
 */
@Data
public class FocusedFlip
{
	/**
	 * The step of the flip process
	 */
	public enum FlipStep
	{
		BUY,  // Need to buy the item
		SELL  // Already bought, need to sell
	}

	private final int itemId;
	private final String itemName;
	private final FlipStep step;

	// Buy step fields
	private final long buyPrice;
	private final int buyQuantity;

	// Sell step fields
	private final long sellPrice;
	private final int sellQuantity;

	/**
	 * Create a FocusedFlip for the BUY step (from a recommendation)
	 */
	public static FocusedFlip forBuy(int itemId, String itemName, long buyPrice, int buyQuantity, long sellPrice)
	{
		return forBuy(itemId, itemName, buyPrice, buyQuantity, sellPrice, 0);
	}

	/**
	 * Create a FocusedFlip for the BUY step with price offset applied
	 * @param priceOffset Positive offset = buy higher to fill faster
	 */
	public static FocusedFlip forBuy(int itemId, String itemName, long buyPrice, int buyQuantity, long sellPrice, int priceOffset)
	{
		// Apply offset: add to buy price (pay more to fill faster)
		long adjustedBuyPrice = Math.max(1, buyPrice + priceOffset);
		// Also adjust sell price by subtracting offset (sell lower to fill faster)
		long adjustedSellPrice = Math.max(1, sellPrice - priceOffset);

		return new FocusedFlip(
			itemId,
			itemName,
			FlipStep.BUY,
			adjustedBuyPrice,
			buyQuantity,
			adjustedSellPrice,
			0  // No sell quantity yet
		);
	}

	/**
	 * Create a FocusedFlip for the SELL step (from an active flip)
	 */
	public static FocusedFlip forSell(int itemId, String itemName, long sellPrice, int sellQuantity)
	{
		return forSell(itemId, itemName, sellPrice, sellQuantity, 0);
	}

	/**
	 * Create a FocusedFlip for the SELL step with price offset applied
	 * @param priceOffset Positive offset = sell lower to fill faster
	 */
	public static FocusedFlip forSell(int itemId, String itemName, long sellPrice, int sellQuantity, int priceOffset)
	{
		// Apply offset: subtract from sell price (sell lower to fill faster)
		long adjustedSellPrice = Math.max(1, sellPrice - priceOffset);

		return new FocusedFlip(
			itemId,
			itemName,
			FlipStep.SELL,
			0,  // Not relevant for selling
			0,
			adjustedSellPrice,
			sellQuantity
		);
	}

	/**
	 * Get the price relevant to the current step
	 */
	public long getCurrentStepPrice()
	{
		return step == FlipStep.BUY ? buyPrice : sellPrice;
	}

	/**
	 * Get the quantity relevant to the current step
	 */
	public int getCurrentStepQuantity()
	{
		return step == FlipStep.BUY ? buyQuantity : sellQuantity;
	}

	/**
	 * Check if we're in the buying step
	 */
	public boolean isBuying()
	{
		return step == FlipStep.BUY;
	}

	/**
	 * Check if we're in the selling step
	 */
	public boolean isSelling()
	{
		return step == FlipStep.SELL;
	}

	/**
	 * Calculate the expected profit for a recommendation after applying the price offset.
	 * This matches the profit shown in the Flip Assist overlay.
	 */
	public static long calculateAdjustedProfit(FlipRecommendation rec, int priceOffset)
	{
		long adjBuy = Math.max(1, rec.getRecommendedBuyPrice() + priceOffset);
		long adjSell = Math.max(1, rec.getRecommendedSellPrice() - priceOffset);
		long margin = adjSell - adjBuy;
		int geTax = GeTax.taxFor(rec.getItemId(), adjSell);
		return (margin - geTax) * rec.getRecommendedQuantity();
	}

	/**
	 * Whether a recommendation clears the user's minimum-profit and minimum-volume
	 * filters. Flip Finder's list ({@code FlipFinderPanel.shouldDisplay}) and the
	 * Flip Assist queue ({@code AutoRecommendService}) share this predicate so both
	 * surface the same items.
	 */
	public static boolean passesRecommendationFilters(FlipRecommendation rec, int priceOffset, int minProfit, int minVolume)
	{
		return calculateAdjustedProfit(rec, priceOffset) >= minProfit
			&& rec.getDailyVolume() >= minVolume;
	}
}

package com.flipsmart;

import com.flipsmart.domain.flip.ActiveFlip;
import java.util.List;
import java.util.Optional;
import java.util.concurrent.Executors;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Supplier;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Pushes the plugin's canonical Active Flips projection to the backend so the
 * website mirrors the same list (Flip-Smart/flip-smart#1113).
 *
 * The projection itself is never recomputed here — this only serialises what the
 * Active Flips tab already renders, which is what makes the two surfaces agree
 * by construction.
 */
@Slf4j
@Singleton
public class ActiveFlipsSnapshotPushService
{
	private static final long DEBOUNCE_MS = 2_000L;

	private final FlipSmartApiClient apiClient;
	private final PlayerSession session;
	private ScheduledExecutorService scheduler; // NOPMD DoNotUseThreads - desktop plugin, not J2EE
	private final AtomicReference<ScheduledFuture<?>> pending = new AtomicReference<>();
	private final AtomicReference<String> lastDelivered = new AtomicReference<>();

	@Inject
	public ActiveFlipsSnapshotPushService(FlipSmartApiClient apiClient, PlayerSession session)
	{
		this.apiClient = apiClient;
		this.session = session;
	}

	/** The live scheduler, created on first use and replaced if a shutdown terminated it. */
	private ScheduledExecutorService scheduler() // NOPMD DoNotUseThreads
	{
		synchronized (this)
		{
			if (scheduler == null || scheduler.isShutdown())
			{
				scheduler = Executors.newSingleThreadScheduledExecutor(r -> // NOPMD DoNotUseThreads
				{
					Thread t = new Thread(r, "flipsmart-active-flips-push"); // NOPMD DoNotUseThreads
					t.setDaemon(true);
					return t;
				});
			}
			return scheduler;
		}
	}

	/**
	 * Identity of a projection for dedup purposes: which flips exist and on which
	 * side, deliberately EXCLUDING fill progress. Fill ticks fire constantly; if
	 * they counted as changes, one slowly-filling order would push dozens of times.
	 * This is also exactly what the server consumes, so the payload's other fields
	 * are only ever as fresh as the last identity change.
	 */
	private static String identity(List<ActiveFlip> flips)
	{
		return flips.stream()
			.map(f -> f.getItemId() + ":" + f.getPhase())
			.sorted()
			.collect(Collectors.joining(","));
	}

	/**
	 * Schedule a debounced push. {@code flipsSupplier} is invoked at SEND time (after
	 * the debounce), not now — so the payload and the {@code captured_at} timestamp
	 * the endpoint stamps around it describe the same instant, instead of the payload
	 * being up to {@link #DEBOUNCE_MS} stale relative to its own timestamp.
	 */
	public void scheduleSnapshotPush(Supplier<List<ActiveFlip>> flipsSupplier)
	{
		try
		{
			ScheduledFuture<?> previous = pending.getAndSet(
				scheduler().schedule(() -> doPush(flipsSupplier), DEBOUNCE_MS, TimeUnit.MILLISECONDS));
			if (previous != null)
			{
				previous.cancel(false);
			}
		}
		catch (RejectedExecutionException e)
		{
			if (log.isDebugEnabled())
			{
				log.debug("active flips snapshot schedule rejected (shutting down): {}", e.getMessage());
			}
		}
	}

	/** Force the next push through even if the projection is unchanged (TTL refresh). */
	public void invalidateDedup()
	{
		lastDelivered.set(null);
	}

	public void shutdown()
	{
		ScheduledFuture<?> previous = pending.getAndSet(null);
		if (previous != null)
		{
			previous.cancel(false);
		}
		synchronized (this)
		{
			if (scheduler != null)
			{
				scheduler.shutdownNow(); // NOPMD DoNotUseThreads
			}
		}
	}

	/**
	 * @param flipsSupplier evaluated here, at send time. May return {@code null} to
	 *                      mean "skip this push" (e.g. an unobserved empty snapshot) —
	 *                      distinct from an empty list, which is a real "no flips" and
	 *                      is always delivered.
	 */
	private void doPush(Supplier<List<ActiveFlip>> flipsSupplier)
	{
		Optional<String> rsn = session.getRsnSafe();
		if (!rsn.isPresent())
		{
			return;
		}

		List<ActiveFlip> flips = flipsSupplier.get();
		if (flips == null)
		{
			return;
		}

		String identity = identity(flips);
		if (identity.equals(lastDelivered.get()))
		{
			return;
		}

		try
		{
			apiClient.pushActiveFlipsSnapshotAsync(rsn.get(), flips)
				.thenAccept(ok ->
				{
					// Advance the baseline only on DELIVERY. Recording an attempt
					// would let a dropped push suppress its own retry, silently
					// breaking AC2 (a cancelled offer never leaving the dashboard).
					if (Boolean.TRUE.equals(ok))
					{
						lastDelivered.set(identity);
					}
				})
				.exceptionally(e ->
				{
					if (log.isDebugEnabled())
					{
						log.debug("active flips snapshot push failed: {}", e.getMessage());
					}
					return null;
				});
		}
		catch (RuntimeException e)
		{
			if (log.isDebugEnabled())
			{
				log.debug("active flips snapshot push threw: {}", e.getMessage());
			}
		}
	}
}

package com.flipsmart;

import java.awt.geom.Area;
import java.awt.image.BufferedImage;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

import java.awt.*;

@Slf4j
public class InventoryHighlightOverlay extends WidgetItemOverlay
{
	private static final Color COLOR_GLOW = new Color(255, 185, 50);

	private static final int GE_INTERFACE_GROUP = 465;
	private static final int GE_OFFER_PANEL_CHILD = 26;
	private static final int SINGLE_ITEM_QUANTITY = 1;

	private final Set<Integer> highlightedItemIds = ConcurrentHashMap.newKeySet();

	private final Map<Long, BufferedImage> outlineCache = new ConcurrentHashMap<>();

	@Inject
	private ItemManager itemManager;

	@Inject
	private Client client;

	public InventoryHighlightOverlay()
	{
		showOnInventory();
	}

	public void addHighlight(int itemId)
	{
		highlightedItemIds.add(itemManager.canonicalize(itemId));
	}

	public void removeHighlight(int itemId)
	{
		highlightedItemIds.remove(itemManager.canonicalize(itemId));
		outlineCache.keySet().removeIf(key -> (int) (key >> 32) == itemId);
	}

	public void clearAll()
	{
		highlightedItemIds.clear();
		outlineCache.clear();
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (!highlightedItemIds.contains(itemManager.canonicalize(itemId)))
		{
			return;
		}

		if (!isGrandExchangeOpen())
		{
			return;
		}

		Rectangle bounds = widgetItem.getCanvasBounds();
		if (bounds == null || bounds.width <= 0)
		{
			return;
		}

		int quantity = widgetItem.getQuantity();
		long cacheKey = ((long) itemId << 32) | (quantity & 0xFFFFFFFFL);
		BufferedImage outline = outlineCache.computeIfAbsent(cacheKey, k -> generateOutline(itemId, quantity));
		if (outline == null)
		{
			return;
		}

		long elapsed = System.currentTimeMillis() % 1500;
		float pulseAlpha = (float) (0.5 + 0.5 * Math.sin(elapsed / 1500.0 * 2 * Math.PI));

		Shape originalClip = graphics.getClip();
		Area clipArea = new Area(new Rectangle(
			bounds.x - 10, bounds.y - 10,
			bounds.width + 20, bounds.height + 20));
		// Stacks render a quantity number in the top-left corner; crop it out so the
		// glow doesn't obscure it. A single item shows no number, so highlight fully.
		if (quantity > SINGLE_ITEM_QUANTITY)
		{
			clipArea.subtract(new Area(new Rectangle(
				bounds.x, bounds.y, bounds.width / 2, bounds.height / 3)));
		}
		graphics.setClip(clipArea);

		Composite originalComposite = graphics.getComposite();
		for (int i = 2; i >= 1; i--)
		{
			float alpha = (0.3f + 0.2f * pulseAlpha) / i;
			graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, Math.min(alpha, 1.0f)));
			graphics.drawImage(outline,
				bounds.x - i,
				bounds.y - i,
				bounds.width + i * 2,
				bounds.height + i * 2,
				null);
		}

		float innerAlpha = 0.7f + 0.3f * pulseAlpha;
		graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, innerAlpha));
		graphics.drawImage(outline, bounds.x, bounds.y, bounds.width, bounds.height, null);

		graphics.setComposite(originalComposite);
		graphics.setClip(originalClip);
	}

	private BufferedImage generateOutline(int itemId, int quantity)
	{
		BufferedImage itemImage = itemManager.getImage(itemId, quantity, false);
		if (itemImage == null)
		{
			return null;
		}

		int w = itemImage.getWidth();
		int h = itemImage.getHeight();
		BufferedImage outline = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);

		int glowRgb = COLOR_GLOW.getRGB() & 0x00FFFFFF; // strip alpha

		for (int y = 0; y < h; y++)
		{
			for (int x = 0; x < w; x++)
			{
				// Only draw outline on transparent pixels adjacent to opaque ones
				if ((itemImage.getRGB(x, y) >>> 24) != 0)
				{
					continue;
				}

				if (hasOpaqueNeighbor(itemImage, x, y, w, h))
				{
					outline.setRGB(x, y, 0xFF000000 | glowRgb);
				}
			}
		}

		return outline;
	}

	private boolean isGrandExchangeOpen()
	{
		Widget geWidget = client.getWidget(GE_INTERFACE_GROUP, 0);
		if (geWidget != null && !geWidget.isHidden())
		{
			return true;
		}

		Widget offerPanel = client.getWidget(GE_INTERFACE_GROUP, GE_OFFER_PANEL_CHILD);
		return offerPanel != null && !offerPanel.isHidden();
	}

	private boolean hasOpaqueNeighbor(BufferedImage image, int x, int y, int w, int h)
	{
		for (int dy = -1; dy <= 1; dy++)
		{
			for (int dx = -1; dx <= 1; dx++)
			{
				if (dx == 0 && dy == 0)
				{
					continue;
				}
				int nx = x + dx;
				int ny = y + dy;
				if (nx >= 0 && nx < w && ny >= 0 && ny < h
					&& (image.getRGB(nx, ny) >>> 24) != 0)
				{
					return true;
				}
			}
		}
		return false;
	}
}

package com.flipsmart.session;

import com.flipsmart.domain.flip.CompletedFlip;
import com.flipsmart.util.GeTax;
import com.flipsmart.util.GpUtils;
import com.flipsmart.util.TimeUtils;

import java.util.List;
import java.util.Locale;

/**
 * Pure session-performance math: realised profit from completed flips sold within
 * the session, projected profit including unrealised gains on open positions, and
 * the derived GP/hour rates. No Swing, no I/O.
 */
public final class SessionStats
{
	/** Below this much logged-in time, GP/hour is too volatile to be meaningful. */
	static final long MIN_ACTIVE_MS = 60_000L;
	private static final long MS_PER_HOUR = 3_600_000L;
	private static final String NOT_AVAILABLE = "—";

	private SessionStats()
	{
	}

	public static ProfitBase computeBase(List<CompletedFlip> completed, List<OpenPosition> open,
										 long sessionStartMs)
	{
		return new ProfitBase(realisedProfit(completed, sessionStartMs), unrealisedProfit(open));
	}

	public static Snapshot snapshot(ProfitBase base, long activeMs)
	{
		long projected = base.realisedProfit + base.unrealisedProfit;
		return new Snapshot(base.realisedProfit, projected, activeMs,
			gpPerHour(base.realisedProfit, activeMs), gpPerHour(projected, activeMs));
	}

	public static Snapshot compute(List<CompletedFlip> completed, List<OpenPosition> open,
								   long sessionStartMs, long activeMs)
	{
		return snapshot(computeBase(completed, open, sessionStartMs), activeMs);
	}

	static long realisedProfit(List<CompletedFlip> completed, long sessionStartMs)
	{
		long sum = 0L;
		for (CompletedFlip flip : completed)
		{
			if (TimeUtils.parseIsoToMillis(flip.getSellTime()) >= sessionStartMs)
			{
				sum += flip.getNetProfit();
			}
		}
		return sum;
	}

	/**
	 * Value of the positions still held, at their recommended sell price net of tax. Only the
	 * unsold quantity counts — units already sold belong to realised profit, so valuing them
	 * here too would double-count them (see {@link OpenPositions}).
	 */
	static long unrealisedProfit(List<OpenPosition> open)
	{
		long sum = 0L;
		for (OpenPosition position : open)
		{
			Long recommendedSell = position.recommendedSellPrice;
			if (recommendedSell == null || position.unsoldQuantity <= 0)
			{
				continue;
			}
			long tax = GeTax.taxFor(position.itemId, recommendedSell);
			long perItem = recommendedSell - position.averageBuyPrice - tax;
			sum += perItem * position.unsoldQuantity;
		}
		return sum;
	}

	static Long gpPerHour(long profit, long activeMs)
	{
		if (activeMs < MIN_ACTIVE_MS)
		{
			return null;
		}
		return (long) (profit * (double) MS_PER_HOUR / activeMs);
	}

	public static String formatSignedGp(long amount)
	{
		String magnitude = GpUtils.formatGPSigned(amount);
		return amount > 0 ? "+" + magnitude : magnitude;
	}

	public static String formatGpPerHour(Long perHour)
	{
		return perHour == null ? NOT_AVAILABLE : formatSignedGp(perHour);
	}

	public static String formatDuration(long ms)
	{
		long totalSeconds = Math.max(0L, ms) / 1000L;
		long hours = totalSeconds / 3600L;
		long minutes = (totalSeconds % 3600L) / 60L;
		long seconds = totalSeconds % 60L;
		return String.format(Locale.ROOT, "%02d:%02d:%02d", hours, minutes, seconds);
	}

	public static final class ProfitBase
	{
		public static final ProfitBase EMPTY = new ProfitBase(0L, 0L);
		public final long realisedProfit;
		public final long unrealisedProfit;

		public ProfitBase(long realisedProfit, long unrealisedProfit)
		{
			this.realisedProfit = realisedProfit;
			this.unrealisedProfit = unrealisedProfit;
		}
	}

	public static final class Snapshot
	{
		public final long realisedProfit;
		public final long projectedProfit;
		public final long activeMs;
		public final Long realisedGpPerHour;
		public final Long projectedGpPerHour;

		public Snapshot(long realisedProfit, long projectedProfit, long activeMs,
						Long realisedGpPerHour, Long projectedGpPerHour)
		{
			this.realisedProfit = realisedProfit;
			this.projectedProfit = projectedProfit;
			this.activeMs = activeMs;
			this.realisedGpPerHour = realisedGpPerHour;
			this.projectedGpPerHour = projectedGpPerHour;
		}
	}
}

package com.flipsmart.session;

/**
 * An unsold position held during the session: the quantity still to be sold, plus the
 * basis and target used to value it. Deliberately not an {@code ActiveFlip} — a flip's
 * quantity is the offer's original size, which over-values a partially-filled sell.
 */
public final class OpenPosition
{
	public final int itemId;
	public final int unsoldQuantity;
	public final long averageBuyPrice;
	public final Long recommendedSellPrice;

	public OpenPosition(int itemId, int unsoldQuantity, long averageBuyPrice, Long recommendedSellPrice)
	{
		this.itemId = itemId;
		this.unsoldQuantity = unsoldQuantity;
		this.averageBuyPrice = averageBuyPrice;
		this.recommendedSellPrice = recommendedSellPrice;
	}
}

package com.flipsmart.session;

import com.flipsmart.ui.panel.CardWidgets;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import lombok.Getter;
import lombok.Setter;
import net.runelite.client.ui.ColorScheme;

/**
 * The session-performance block above the panel tabs: session profit, session
 * duration, realised GP/hour and projected GP/hour. Presentation only — every
 * figure comes from a {@link SessionStats.Snapshot}.
 *
 * A header row carries a collapse arrow: clicking it hides the four data rows so
 * users on smaller viewports can reclaim vertical space for the recommendation
 * list. The collapsed state is applied via {@link #setCollapsed} and reported
 * through {@link #setToggleListener} so the panel can persist it.
 */
public final class SessionStatsView
{
	private static final Color COLOR_PROFIT_GREEN = new Color(100, 255, 100);
	private static final Color COLOR_LOSS_RED = new Color(255, 100, 100);
	private static final int ROW_HEIGHT = 18;
	private static final String ARROW_EXPANDED = "▼";
	private static final String ARROW_COLLAPSED = "▶";
	// The panel inherits RuneLite's RuneScape pixel font, which lacks the
	// triangle glyphs; Arial (as the rest of the panel uses) renders them.
	private static final Font ARROW_FONT = new Font("Arial", Font.PLAIN, 11);

	@Getter
	private final JPanel component = new JPanel();
	private final JPanel body = new JPanel();
	private final JLabel toggleArrow = new JLabel(ARROW_EXPANDED, SwingConstants.RIGHT);
	private final JLabel sessionProfitValue = new JLabel();
	private final JLabel sessionDurationValue = new JLabel();
	private final JLabel realisedRateValue = new JLabel();
	private final JLabel projectedRateValue = new JLabel();

	@Getter
	private boolean collapsed;
	@Setter
	private Consumer<Boolean> toggleListener;

	public SessionStatsView()
	{
		component.setLayout(new BoxLayout(component, BoxLayout.Y_AXIS));
		component.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		component.setBorder(BorderFactory.createEmptyBorder(4, 10, 6, 10));

		component.add(buildHeader());

		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		body.add(buildRow("Profit this session", sessionProfitValue));
		body.add(buildRow("Session duration", sessionDurationValue));
		body.add(buildRow("Realised GP/hour", realisedRateValue));
		body.add(buildRow("Projected GP/hour", projectedRateValue));
		component.add(body);
	}

	private JPanel buildHeader()
	{
		JPanel header = CardWidgets.panel(new BorderLayout(), ColorScheme.DARKER_GRAY_COLOR);
		header.setMaximumSize(new Dimension(Integer.MAX_VALUE, ROW_HEIGHT));
		header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

		JLabel title = new JLabel("Session Stats");
		title.setForeground(Color.LIGHT_GRAY);

		toggleArrow.setForeground(Color.LIGHT_GRAY);
		toggleArrow.setFont(ARROW_FONT);

		header.add(title, BorderLayout.WEST);
		header.add(toggleArrow, BorderLayout.EAST);
		header.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mousePressed(MouseEvent e)
			{
				toggle();
			}
		});
		return header;
	}

	private JPanel buildRow(String label, JLabel valueLabel)
	{
		JPanel row = CardWidgets.panel(new BorderLayout(), ColorScheme.DARKER_GRAY_COLOR);
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, ROW_HEIGHT));
		JLabel name = new JLabel(label);
		name.setForeground(Color.LIGHT_GRAY);
		valueLabel.setHorizontalAlignment(SwingConstants.RIGHT);
		row.add(name, BorderLayout.WEST);
		row.add(valueLabel, BorderLayout.EAST);
		return row;
	}



	/** Apply a collapsed state (e.g. restoring a persisted preference) without notifying the listener. */
	public void setCollapsed(boolean value)
	{
		collapsed = value;
		applyCollapsed();
	}

	private void toggle()
	{
		collapsed = !collapsed;
		applyCollapsed();
		if (toggleListener != null)
		{
			toggleListener.accept(collapsed);
		}
	}

	private void applyCollapsed()
	{
		body.setVisible(!collapsed);
		toggleArrow.setText(collapsed ? ARROW_COLLAPSED : ARROW_EXPANDED);
		component.revalidate();
		component.repaint();
	}

	public void render(SessionStats.Snapshot snapshot)
	{
		sessionProfitValue.setText(SessionStats.formatSignedGp(snapshot.realisedProfit));
		sessionProfitValue.setForeground(profitColor(snapshot.realisedProfit));

		sessionDurationValue.setText(SessionStats.formatDuration(snapshot.activeMs));
		sessionDurationValue.setForeground(Color.WHITE);

		applyRate(realisedRateValue, snapshot.realisedGpPerHour);
		applyRate(projectedRateValue, snapshot.projectedGpPerHour);
	}

	private void applyRate(JLabel label, Long perHour)
	{
		label.setText(SessionStats.formatGpPerHour(perHour));
		label.setForeground(perHour == null ? Color.LIGHT_GRAY : profitColor(perHour));
	}

	private Color profitColor(long amount)
	{
		return amount < 0 ? COLOR_LOSS_RED : COLOR_PROFIT_GREEN;
	}
}

package com.flipsmart.session;

/**
 * Tracks the wall-clock session start and accumulated logged-in time, excluding
 * spans the player was logged out. Poll {@link #update(boolean, long)} with the
 * current login state; read elapsed logged-in time with {@link #activeMs(long)}.
 * Pure and deterministic — every "now" is injected so it unit-tests without a
 * real clock.
 */
public final class SessionClock
{
	private final long sessionStartMs;
	private long accumulatedActiveMs;
	private boolean loggedIn;
	private long loginStartMs;

	public SessionClock(long sessionStartMs)
	{
		this.sessionStartMs = sessionStartMs;
	}

	public long startMs()
	{
		return sessionStartMs;
	}

	public void update(boolean loggedIn, long nowMs)
	{
		if (loggedIn && !this.loggedIn)
		{
			loginStartMs = nowMs;
		}
		else if (!loggedIn && this.loggedIn)
		{
			accumulatedActiveMs += Math.max(0L, nowMs - loginStartMs);
		}
		this.loggedIn = loggedIn;
	}

	public long activeMs(long nowMs)
	{
		long openSpan = loggedIn ? Math.max(0L, nowMs - loginStartMs) : 0L;
		return accumulatedActiveMs + openSpan;
	}
}

package com.flipsmart.session;

import com.flipsmart.domain.flip.ActiveFlip;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.IntUnaryOperator;

/**
 * Derives unsold positions from the Active Flips projection.
 *
 * A projected flip carries the sell offer's original quantity, so valuing it directly also
 * values the units that have already sold — and those are simultaneously counted in realised
 * profit, double-counting every partial fill in projected profit until the offer terminalizes.
 * Subtracting the filled quantity values only what is genuinely still unsold. Awaiting-sale
 * lots have no live sell offer, so their filled lookup is zero and their full quantity stands.
 *
 * {@code filledSellQuantityForItem} sums fills across every live sell offer of an item, not per
 * offer, so two simultaneous sell offers of the same item share one filled pool here — consumed
 * flip-by-flip — instead of each flip subtracting the item's whole filled total independently.
 *
 * Returns new instances; the projected flips are shared with the panel's cards and the
 * backend snapshot and are never mutated here.
 */
public final class OpenPositions
{
	private OpenPositions()
	{
	}

	public static List<OpenPosition> derive(List<ActiveFlip> projected,
											IntUnaryOperator filledSellQuantityForItem)
	{
		if (projected == null || projected.isEmpty())
		{
			return Collections.emptyList();
		}
		Map<Integer, Integer> unclaimedFilledByItem = new HashMap<>();
		List<OpenPosition> out = new ArrayList<>(projected.size());
		for (ActiveFlip flip : projected)
		{
			int itemId = flip.getItemId();
			int unclaimed = unclaimedFilledByItem.computeIfAbsent(itemId,
				id -> Math.max(0, filledSellQuantityForItem.applyAsInt(id)));
			int claimed = Math.min(unclaimed, flip.getTotalQuantity());
			unclaimedFilledByItem.put(itemId, unclaimed - claimed);
			int unsold = flip.getTotalQuantity() - claimed;
			out.add(new OpenPosition(itemId, unsold,
				flip.getAverageBuyPrice(), flip.getRecommendedSellPrice()));
		}
		return out;
	}
}
